INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('84a36a7f-f445-5360-9d10-325a2ed533bf', '9780006496434', 'The Little House', 'rbvUPps9vKsC', 'It was easy for Elizabeth. She married the man she loved. It was harder for Ruth. She married Elizabeth''s son and then found that, somehow, she could never quite measure up. This thriller examines what women want and what they fear, as Ruth confronts the shifting borders of her own sanity.', 'en', 1998, 368, 'http://books.google.com/books/content?id=rbvUPps9vKsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
