INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('91af6f17-6a45-562e-9476-dcf82cec9d95', '9780006514855', 'Girls'' Night in', 'xLwHHQAACAAJ', '''Girls'' Night In'' features stories about growing up, growing out of, moving out, moving on, falling apart and getting it all together. So turn off your cell phone and curl up on the couch: this is one ''Girls'' Night In'' you won''t want to miss.', 'en', 2000, 586, 'http://books.google.com/books/content?id=xLwHHQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
