INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f5139920-f0fe-5450-b2f1-03beef0eec3f', '9780006551393', 'The Lexus and the Olive Tree', 'u8zxpq6o7HYC', 'Half of this new, post-Cold War world is intent on building a better Lexus, on streamlining their societies and economies for the global marketplace, while the other half is locked in elemental struggles over who owns which olive tree, which strip of land.', 'en', 2000, 352, 'http://books.google.com/books/content?id=u8zxpq6o7HYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '33', 'accepted', 'Thomas L. Friedman', 'Capitalism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 0 FROM public.book WHERE isbn13 = '9780006551393' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ce1ae4f4-6c23-5eeb-bf27-3467a9375a18', '9780006551812', '''Tis', 'Q3BhQgAACAAJ', 'FROM THE PULIZER PRIZE-WINNING AUTHOR OF THE #1 "NEW YORK TIMES" BESTSELLER "ANGELA''S ASHES" Frank McCourt''s glorious childhood memoir, "Angela''s Ashes, " has been loved and celebrated by readers everywhere. It won the National Book Critics Circle Award, the "Los Angeles Times" Book Award and the Pulitzer Prize. Rarely has a book so swiftly found its place on the literary landscape. And now we have "''Tis, " the story of Frank''s American journey from impoverished immigrant to brilliant teacher and raconteur. Frank lands in New York at age nineteen and gets a job at the Biltmore Hotel, where he immediately encounters the vivid hierarchies of this "classless country," and then is drafted into the army and is sent to Germany to train dogs and type reports. It is Frank''s incomparable voice that renders these experiences spellbinding. When Frank returns to America in 1953, he works on the docks, always resisting what everyone tells him. He knows that he should be getting an education, and though he left school at fourteen, he talks his way into New York University. There, he falls in love with the quintessential Yankee and tries to live his dream. But it is not until he starts to teach that Frank finds his place in the world.', 'en', 2000, 495, 'http://books.google.com/books/content?id=Q3BhQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '34', 'accepted', 'Frank McCourt', 'Ireland', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 6 FROM public.book WHERE isbn13 = '9780006551812' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1c798584-ef9c-5c00-ae9f-c864a300edaa', '9780006646006', 'Ocean Star Express', 'I2QZAAAACAAJ', 'Joe and his parents are enjoying a summer holiday by the sea at the Ocean Star Hotel. The sky is bright blue, the sun shines and Joe loves all that the seaside has to offer. But when the fog rolls in and rain falls Joe begins to wish that he was back at home again. Things change, however, when the owner of the hotel invites Joe to share in a magical world, only a few steps away. The loft is black as night but then above Joe''s head a thousand tiny stars begin to sparkle and in the distance he hears the chug-chug-chug of a model train. A whole world is soon to open up before Joe''s eyes, a world of snow-capped mountains, great deserts, and rocking fishing boats.', 'en', 2002, 32, 'http://books.google.com/books/content?id=I2QZAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
