INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b01e3be1-ebbd-5bc0-9e64-4851793fc599', '9780007116263', 'The Lord of the Rings, the Return of the King', 'kNBnQgAACAAJ', 'A visual guide to the third in the Lord of the Rings movie trilogy. A large-format, full-colour guide to the characters, places, landscapes, artefacts, battles, and costumes as seen in the film, it features images, informative text and specially commissioned extras.', 'en', 2003, 72, 'http://books.google.com/books/content?id=kNBnQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '42', 'accepted', 'Jude Fisher', 'Imaginary wars and battles', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 12 FROM public.book WHERE isbn13 = '9780007116263' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5c8416f5-f961-5d9b-b2e6-23ed955f0d29', '9780007117536', 'All Families are Psychotic', 'jYBsNp6NPVoC', 'On the eve of the next Space Shuttle mission, a divided family comes together... Warm, witty and wise, All Families Are Psychotic is Coupland at the very top of his form: ''Irresistibly hilarious, unique and wonderful'' Independent on Sunday In a cheap motel an hour from Cape Canaveral, Janet Drummond takes her medication, and does a rapid tally of the whereabouts of her children. Wade has spent the night in jail; suicidal Bryan is due to arrive at any moment with his vowel-free girlfriend, Shw; and then there is Sarah, ''a bolt of lightning frozen in midflash'' -- here in Orlando to be the star of Friday''s shuttle mission. With Janet''s ex-husband and his trophy wife also in town, Janet spends a moment contemplating her family, and where it all went wrong. Or did it?', 'en', 2002, 279, 'http://books.google.com/books/content?id=jYBsNp6NPVoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
