INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0005375a-a078-5a53-8c8b-7dfc4869086b', '9780007120819', 'The Big Four', 'wcOQUSWQEdUC', 'A ruthless international cartel seeks world domination... Framed in the doorway of Poirot''s bedroom stood an uninvited guest, coated from head to foot in dust. The man''s gaunt face stared for a moment, then he swayed and fell. Who was he? Was he suffering from shock or just exhaustion? Above all, what was the significance of the figure 4, scribbled over and over again on a sheet of paper? Poirot finds himself plunged into a world of international intrigue, risking his life to uncover the truth about ''Number Four''.', 'en', 2002, 272, 'http://books.google.com/books/content?id=wcOQUSWQEdUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
