INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9c83fb93-d197-53c5-9cc7-652c4189169a', '9780007120864', 'The Thirteen Problems', 'MK9JNwoZAncC', 'The Tuesday Night Club is a venue where locals challenge Miss Marple to solve recent crimes... One Tuesday evening a group gathers at Miss Marple''s house and the conversation turns to unsolved crimes... The case of the disappearing bloodstains; the thief who committed his crime twice over; the message on the death-bed of a poisoned man which read ''heap of fish''; the strange case of the invisible will; a spiritualist who warned that ''Blue Geranium'' meant death... Now pit your wits against the powers of deduction of the ''Tuesday Night Club''.', 'en', 2002, 315, 'http://books.google.com/books/content?id=MK9JNwoZAncC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
