INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b2526b2f-7f07-5fe5-b393-f7915e39c5ee', '9780007121007', 'Mrs McGinty''s Dead', 'gcS0d5HhGEEC', 'An old widow is brutally killed in the parlour of her cottage... Mrs McGinty died from a brutal blow to the back of her head. Suspicion fell immediately on her shifty lodger, James Bentley, whose clothes revealed traces of the victim''s blood and hair. Yet something was amiss: Bentley just didn''t look like a murderer. Poirot believed he could save the man from the gallows - what he didn''t realise was that his own life was now in great danger...', 'en', 2002, 328, 'http://books.google.com/books/content?id=gcS0d5HhGEEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
