INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d6c6d5c5-711a-5a52-b97c-2d0874903298', '9780007130313', 'Cut', 'Q140Mlie138C', 'Fifteen-year old Callie is so withdrawn that she''s not speaking to anyone - including her therapist at Sea Pines, known to its guests as ''Sick Minds'' - the residential treatment facility where her parents and doctor send her after discovering that she cuts herself. Her story unfolds primarily through dramatic monologues, gradually revealing the family turmoil that led to her self-destructive behaviour.', 'en', 2002, 173, 'http://books.google.com/books/content?id=Q140Mlie138C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
