INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5ed57d63-0381-5813-80e9-c80672d01466', '9780007154883', 'The Listerdale Mystery', 'J1tLGz5G84EC', 'A selection of mysteries, some light-hearted, some romantic, some very deadly... Twelve tantalizing cases... the curious disappearance of Lord Listerdale; a newlywed''s fear of her ex-fiance; a strange encounter on a train; a domestic murder investigation; a wild man''s sudden personality change; a retired inspector''s hunt for a murderess; a young woman''s impersonation of a duchess; a necklace hidden in a basket of cherries; a mystery writer''s arrest for murder; an astonishing marriage proposal; a soprano''s hatred for a baritone; the case of the rajah''s emerald. All have one thing in common: the skilful hand of Agatha Christie.', 'en', 2003, 317, 'http://books.google.com/books/content?id=J1tLGz5G84EC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
