INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1ff6c789-5fa8-5449-a4e3-28c1cc2e6d99', '9780007158058', 'The Real Trial of Oscar Wilde', 'QfNgQfTKcg0C', 'Oscar Wilde had one of literary history''s most explosive love affairs with Lord Alfred "Bosie" Douglas. In 1895, Bosie''s father, the Marquess of Queensberry, delivered a note to the Albemarle Club addressed to "Oscar Wilde posing as sodomite." With Bosie''s encouragement, Wilde sued the Marquess for libel. He not only lost but he was tried twice for "gross indecency" and sent to prison with two years'' hard labor. With this publication of the uncensored trial transcripts, readers can for the first time in more than a century hear Wilde at his most articulate and brilliant. The Real Trial of Oscar Wilde documents an alarmingly swift fall from grace; it is also a supremely moving testament to the right to live, work, and love as one''s heart dictates.', 'en', 2004, 384, 'http://books.google.com/books/content?id=QfNgQfTKcg0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
