INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6624a9d1-54a5-53e8-bd0a-138b3b42cf4a', '9780007179817', 'Microserfs', 'N3AmmJIsK6wC', 'At computer giant Microsoft, Dan, Susan, Abe, Todd and Bug are struggling to get a life. The job may be super cool, the pay may be astronomical, but they''re heading nowhere, and however hard they work, however many shares they earn, they''re never going to be as rich as Bill. And besides, with all the hours they''re putting in, their best relationships are on e-mail. Something''s got to give.', 'en', 2004, 371, 'http://books.google.com/books/content?id=N3AmmJIsK6wC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
