INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d697e7e1-3f2a-5f9b-85e0-bff98c3432f6', '9780007204441', 'Naked Lunch', '1B36S7t4k5AC', 'The anarchic, phenomenally strong-selling classic from the godfather of the Beats: revitalised with a cool new jacket. WELCOME TO INTERZONE...Say hello to Bradley the Buyer, the best narcotics agent in the business. Attend international playboy A.J.''s annual party, where the punch is to be treated with extreme caution. Meet Dr ''Fingers'' Schafer, the Lobotomy Kid and his giant centipede, ''The Complete American De-anxietized Man.'' And enter the dark and infernal mind of Bill Lee as he pursues his daily quest for the ultimate merchandise...Provocative, influential, morbidly fascinating, Naked Lunch is an apocalyptic ride through the darker recesses of the human psyche.', 'en', 2005, 289, 'http://books.google.com/books/content?id=1B36S7t4k5AC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '92', 'accepted', 'William S. Burroughs', 'Alienation (Social psychology)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 4 FROM public.book WHERE isbn13 = '9780007204441' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9cc8aa65-b1eb-58a4-8e4a-a372bf4ab3be', '9780007204465', 'Tropic of Cancer', 'ProgRjTL8FIC', 'Miller''s groundbreaking first novel, banned in Britain for almost thirty years, now reinvigorated in a new Harper Perennial Modern Classics edition. A penniless and as yet unpublished writer, Henry Miller arrived in Paris in 1930. Leaving behind a disintegrating marriage and an unhappy career in America, he threw himself into the low-life of bohemian Paris with unwavering gusto. A fictional account of Miller''s adventures amongst the prostitutes and pimps, the penniless painters and writers of Montparnasse, Tropic of Cancer is an extravagant and rhapsodic hymn to a world of unrivalled eroticism and freedom. Tropic of Cancer''s 1934 publication in France was hailed by Samuel Beckett as ''a momentous event in the history of modern writing''. The novel was subsequently banned in the UK and the USA and not released for publication for a further thirty years.', 'en', 2005, 336, 'http://books.google.com/books/content?id=ProgRjTL8FIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
