INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b762d2aa-1068-5467-8141-db6ca912f50c', '9780060001537', 'Diary of a Spider', 'UWvZo2pIhzMC', 'This is the diary ... of a spider. But don''t be worried – he''s more scared of you and your gigantic shoe! Actually, he''s a lot like you. He goes to gym class and has Grandparents'' Day at school. But he also spins sticky webs, scales walls, and takes wind–catching lessons. Lucky for him, his best friend is a fly! Doreen Cronin and Harry Bliss, the team behind the #1 bestselling Diary Of A Worm, spin a hilarious tale about the upside–down web world of an eight–legged charmer and his unlikely friend, Fly.', 'en', 2005, 40, 'http://books.google.com/books/content?id=UWvZo2pIhzMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
