INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('586cca80-c7e2-54cf-9dd6-92d8e49deb9a', '9780060090371', 'Lucy Sullivan Is Getting Married', 'qLl-3FGhPl0C', 'What happens when a psychic tells Lucy that she''ll be getting married within the year? Her roommates panic! What is going to happen to their blissful existence of eating take-out, drinking too much wine, bringing men home, and never vacuuming? Lucy reassures her friends that she''s far too busy arguing with her mother and taking care of her irresponsible father to get married. And then there''s the small matter of not even having a boyfriend. But then Lucy meets gorgeous, unreliable Gus. Could he be the future Mr. Lucy Sullivan? Or could it be handsome Chuck? Or Daniel, the world''s biggest flirt? Or even cute Jed, the new guy at work? Maybe her friends have something to worry about after all....', 'en', 2002, 640, 'http://books.google.com/books/content?id=qLl-3FGhPl0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
