INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('250e236b-a110-5051-9392-95b340703a73', '9780060218058', 'The Last of the Really Great Whangdoodles', 'D-iftWFTCcgC', 'The Whangdoodle was once the wisest, the kindest, and the most extraordinary creature in the world. Then he disappeared and created a wonderful land for himself and all the other remarkable animals -- the ten-legged Sidewinders, the little furry Flukes, the friendly Whiffle Bird, and the treacherous, "oily" Prock. It was an almost perfect place where the last of the really great Whangdoodles could rule his kingdom with "peace, love and a sense of fun"-- apart from and forgotten by people. But not completely forgotten. Professor Savant believed in the Whangdoodle. And when he told the three Potter children of his search for the spectacular creature, Lindy, Tom, and Ben were eager to reach Whangdoodleland. With the Professor''s help, they discovered the secret way. But waiting for them was the scheming Prock, who would use almost any means to keep them away from his beloved king. Only by skill and determination were the four travelers able to discover the last of the really great Whangdoodles and grant him his heart''s desire. Julie Andrews Edwards, star of stage and screen, has written a unique and beloved story that has become a modern classic. The Last of the Really Great Whangdoodles is sure to continue to delight readers everywhere. This edition includes a new foreword by the author.', 'en', 1996, 209, 'http://books.google.com/books/content?id=D-iftWFTCcgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '134', 'accepted', 'Julie Andrews Edwards', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 5 FROM public.book WHERE isbn13 = '9780060218058' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fa78a81f-4e10-50b2-9d4f-3c8f92b7edfe', '9780060245603', 'Today I Feel Silly & Other Moods That Make My Day', 's_2GIF_c0T8C', 'Today I feel silly. Mom says it''s the heat. I put rouge on the cat and gloves on my feet. I ate noodles for breakfast and pancakes at night. I dressed like a star and was quite a sight. Today I am sad, my mood''s heavy and gray. There''s a frown on my face and it''s been there all day. My best friend and I had a really big fight. She said that I tattled and I know that she''s right. Silly, cranky, excited, or sad--everyone has moods that can change each day. Jamie Lee Curtis''s zany and touching verse, paired with Laura Cornell''s whimsical and original illustrations, helps kids explore, identify, and, even have fun with their ever-changing moods. Here''s another inspired picture book from the bestselling author-illustrator team of Tell Me Again About the Night I Was Born and When I Was Little: A Four-Year-Old''s Memoir of Her Youth.', 'en', 1998, 40, 'http://books.google.com/books/content?id=s_2GIF_c0T8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '135', 'accepted', 'Jamie Lee Curtis', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 2 FROM public.book WHERE isbn13 = '9780060245603' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4b7c62b7-b348-5571-b09e-b51e8f695f03', '9780060256579', 'The Missing Piece Meets the Big O', '-m4gwgEACAAJ', 'The missing piece sat alone waiting for someone to come along and take it somewhere.... The different ones it encounters - and what it discovers in its helplessness - are portrayed with simplicity and compassion in the words and drawings of Shel Silverstein.', 'en', 1981, 104, 'http://books.google.com/books/content?id=-m4gwgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '136', 'accepted', 'Shel Silverstein', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 15 FROM public.book WHERE isbn13 = '9780060256579' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6368c097-723f-53db-b300-80c62fd55dc0', '9780060256753', 'Lafcadio, the Lion Who Shot Back', 'lmeJRAAACAAJ', '"You don''t have to shoot me," says the young lion. "I will be your rug and I will lie in front of your fireplace and I won''t move a muscle and you can sit on me and toast all the marshmallows you want. I love marshmallows." But the hunter will not listen to reason, so what is there for a young lion to do? After eating up the hunter, Lafcadio takes the gun home and practices and practices until he becomes the world''s greatest sharp-shooter. Now dressed in starched collars and fancy suits, and enjoying all the marshmallows he wants, Lafcadio is pampered and admired wherever he goes. But is a famous, successful, and admired lion a happy lion? Or is he a lion at all? Told and drawn with wit and gusto, Shel Silverstein''s modern fable speaks not only to children but to us all!', 'en', 1963, 112, 'http://books.google.com/books/content?id=lmeJRAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '137', 'accepted', 'Shel Silverstein', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 6 FROM public.book WHERE isbn13 = '9780060256753' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('09bd14f0-c067-5a75-9dc2-d22682b92988', '9780060277406', 'The Secret Garden Cookbook', 'c7E_HQAACAAJ', 'Frances Hodgson Burnett''s The Secret Garden delights in the wondrous discoveries of lonely Mary Lennox as she slowly helps bring an abandoned garden back to life. It also delights in good food and a robust appetite, and the health and strength they can bring. Written at a time when many children were going hungry and even starving, Burnett''s beloved story celebrates the magic of fresh air, new milk, homemade currant buns, and hearty, simple fare. Inside the pages of this cookbook are recipes for Mary''s favorite foods, in and out of the garden, from porridge to roasted potatoes and eggs, all inspired by The Secret Garden and all adapted by chef and culinary historian Amy Coder from traditional Victorian recipes. Ms. Coder has supplemented these simple, wholesome recipes with fascinating tidbits on Victorian foods and Victorian eating customs. The result is a scrumptious tribute to Burnett''s classic novel, a fascinating glimpse into the cooking customs of a historical period that is now long past, and a step-by-step guide to making delicious, tasty treats to enjoy in your own secret garden.', 'en', 1999, 128, 'http://books.google.com/books/content?id=c7E_HQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
