INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('471dedb4-38d3-5e1b-987c-7d0d1a8a23bf', '9780060511067', 'Amelia Bedelia Goes Camping', 'WEEz7PKLpQkC', 'Camp Out Amelia Bedelia has never been camping in the great outdoors before. She''s trying her best to do exactly as she''s told, but pitching a tent is not the same as throwing it into the bushes, and catching a fish with your bare hands isn''t easy. As usual, the mixed-up housekeeper makes this camping trip one hugely entertaining adventure.', 'en', 2003, 64, 'http://books.google.com/books/content?id=WEEz7PKLpQkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
