INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('13bb4a13-2b70-5bc4-be08-512e908bb691', '9780060511111', 'Amelia Bedelia Helps Out', 'rELWOiQkJTYC', 'Starring everyone''s favourite literal–minded housekeeper, Amelia Bedelia Helps Out appears for the first time in full colour and as an I Can Read Book! A neighbor needs Amelia Bedelia''s helping hands, so everyone''s favorite housekeeper is off to Miss Emma''s house for a day of work. It''s a good thing Miss Emma likes to laugh, because Amelia Bedelia makes her usual merry mess! " Available for the first time in full color! " The zany antics of Amelia Bedelia, one of children''s books most lovable characters, have been enjoyed by kids for more than 40 years! " Herman Parish, nephew to Peggy Parish, who was the original creator of Amelia Bedelia, carries on the tradition of his aunt with new books starring the entertaining housekeeper. Ages 4–8', 'en', 2005, 64, 'http://books.google.com/books/content?id=rELWOiQkJTYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
