INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6e1f1005-011b-5154-b55a-bef9f91eeeee', '9780060519131', 'Savannah Blues', 'q6lDgw6lr-MC', 'Landing a catch like Talmadge Evans III got Eloise "Weezie" Foley a jewel of a town house in Savannah''s historic district. Divorcing Tal got her exiled to the backyard carriage house, where she has launched a spite-fest with Tal''s new fiancÉe, the elegant Caroline DeSantos. An antiques picker, Weezie combs Savannah''s steamy back alleys and garage sales for treasures when she''s not dealing with her loopy relatives or her hunky ex-boyfriend. But an unauthorized sneak preview at a sale lands Weezie smack in the middle of magnolia-scented murder, mayhem...and more. Dirty deals simmer all around her—just as her relationship with the cutest chef in town heats up and she finds out how delicious love can be the second time around.', 'en', 2003, 404, 'http://books.google.com/books/content?id=q6lDgw6lr-MC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
