INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bfd0f42e-a342-5c51-9f28-5c1498a6a4d2', '9780060556525', 'Gold', 'td_ulwEACAAJ', 'Gold is the final and crowning achievement of the fifty-year career of science fiction''s transcendent genius, the world-famous author who defined the field of science fiction for its practitioners, its millions of readers, and the world at large. The first section contains stories that range from the humorous to the profound, at the heart of which is the title story, "Gold," a moving and revealing drama about a writer who gambles everything on a chance at immortality: a gamble Asimov himself made -- and won. The second section contains the grand master''s ruminations on the SF genre itself. And the final section is comprised of Asimov''s thoughts on the craft and writing of science fiction.', 'en', 2003, 416, 'http://books.google.com/books/content?id=td_ulwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
