INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4cf52799-14a1-533c-9d01-ab2de0689902', '9780060570583', 'The Perennial Philosophy', 'YdaFEb_LE9YC', 'The Perennial Philosophy is defined by its author as "The metaphysic that recognizes a divine Reality substantial to the world of things and lives and minds." With great wit and stunning intellect, Aldous Huxley examines the spiritual beliefs of various religious traditions and explains them in terms that are personally meaningful.', 'en', 2004, 336, 'http://books.google.com/books/content?id=YdaFEb_LE9YC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
