INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a4809ba9-ffed-5990-9ed0-724675bf8411', '9780060572969', 'Dead Witch Walking', 'KW1YBk2wPlIC', 'All the creatures of the night gather in "the Hollows" of Cincinnati, to hide, to prowl, to party ... and to feed. Vampires rule the darkness in a predator-eat-predator world rife with dangers beyond imagining -- and it’s Rachel Morgan''s job to keep that world civilized. A bounty hunter and witch with serious sex appeal and an attitude, she''ll bring ''em back alive, dead ... or undead.', 'en', 2004, 416, 'http://books.google.com/books/content?id=KW1YBk2wPlIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
