INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e9621d9f-878d-5531-8ebb-d44c10431de3', '9780060577865', 'Bad Childhood---Good Life', '2sepdlitBW8C', 'Exploring how the past influences the present, the author discusses how to understand each individual''s unique coping style and how to tap into the extraordinary quality of human spirit that will create the transition from victim to victor.', 'en', 2006, 272, 'http://books.google.com/books/content?id=2sepdlitBW8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
