INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fbdfaf76-66a0-5bb0-8edc-f8345f1c1aac', '9780060587031', 'The Day I Swapped My Dad for Two Goldfish', '6EqMPwAACAAJ', '"I''ll swap you my dad," I said. "Oh-oh," said my little sister. What if you wanted your best friend''s two goldfish so much that you''d swap anything for them, even your father? What if your mother came home and found out what you''d done?', 'en', 2006, 64, 'http://books.google.com/books/content?id=6EqMPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
