INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('07452eea-f74f-53b6-a158-c78d41b3ff7e', '9780060732707', 'My Little Pony: Hide-and-Seek', 'oP3lPQAACAAJ', 'Ponies know how to have fun! A game of hide-and-seek is the perfectpastime on a beautiful afternoon. But when Sparkleworks is nowhere to be found, the ponies decide to turn the tables and make her find them.', 'en', 2004, 24, 'http://books.google.com/books/content?id=oP3lPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
