INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a16116e1-f34d-5819-b316-9cb865eae6db', '9780060734015', 'Bridge to Terabithia (rack)', 'LgLT04F1KscC', 'Jess Aarons'' greatest ambition is to be the fastest runner in his grade. He''s been practicing all summer and can''t wait to see his classmates'' faces when he beats them all. But on the first day of school, a new girl boldly crosses over to the boys'' side and outruns everyone. That''s not a very promising beginning for a friendship, but Jess and Leslie Burke become inseparable. Together they create Terabithia, a magical kingdom in the woods where the two of them reign as king and queen, and their imaginations set the only limits. Then one morning a terrible tragedy occurs. Only when Jess is able to come to grips with this tragedy does he finally understand the strength and courage Leslie has given him.', 'en', 2004, 191, 'http://books.google.com/books/content?id=LgLT04F1KscC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
