INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3d63c04e-43e7-5933-907c-739ef32d33bc', '9780060735449', 'Island of the Sequined Love Nun', 'YLqclgEACAAJ', 'Take a wonderfully crazed excursion into the demented heart of a tropical paradise—a world of cargo cults, cannibals, mad scientists, ninjas, and talking fruit bats. Our bumbling hero is Tucker Case, a hopeless geek trapped in a cool guy''s body, who makes a living as a pilot for the Mary Jean Cosmetics Corporation. But when he demolishes his boss''s pink plane during a drunken airborne liaison, Tuck must run for his life from Mary Jean''s goons. Now there''s only one employment opportunity left for him: piloting shady secret missions for an unscrupulous medical missionary and a sexy blond high priestess on the remotest of Micronesian hells. Here is a brazen, ingenious, irreverent, and wickedly funny novel from a modern master of the outrageous.', 'en', 2004, 336, 'http://books.google.com/books/content?id=YLqclgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
