INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d491288c-a8c5-5ee4-9c8b-4090b41f1cc2', '9780060753634', 'Mating in Captivity', '-HIhMOQanIEC', 'A guide for loving couples who are looking to renew sexual passion in their lives explains how societal taboos and ideals about domestic equality have compromised the healthy expression of eroticism in today''s relationships, in a resource that explains how to overcome personal constraints for greater intimacy. 40,000 first printing.', 'en', 2006, 272, 'http://books.google.com/books/content?id=-HIhMOQanIEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
