INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cf92fcf1-3f49-56d5-9200-8c60676af3b2', '9780060763725', 'Psyche in a Dress', 'NYE3GwAACAAJ', 'But this is what I could not give up: I could not give up myself Psyche has known Love—scented with jasmine and tasting of fresh oranges. Yet he is fleeting and fragile, lost to her too quickly. Punished by self-doubt, Psyche yearns to be transformed, like the beautiful and brutal figures in the myths her lover once spoke of. Attempting to uncover beauty in the darkness, she is challenged, tested, and changed by the gods and demons who tempt her. Her faith must be found again, for if she is to love, she must never look back.', 'en', 2006, 116, 'http://books.google.com/books/content?id=NYE3GwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
