INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d73f7bcd-d431-5cd0-aa66-8501d16e1352', '9780060782139', 'Time For Kids: Butterflies!', 'OdZxnI53jj4C', 'Butterflies There are 20,000 different kinds of butterflies in the world. Many have brightly colored wings. But butterflies don''t start life as beauties. Every butterfly begins as a tiny egg that hatches into a caterpillar. Then an amazing change takes place. The caterpillar turns into a fluttering butterfly!', 'en', 2006, 32, 'http://books.google.com/books/content?id=OdZxnI53jj4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
