INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('05f7e66c-74e3-5e90-b54b-60624d8438be', '9780060786731', 'A False Mirror', 'MMG3b9fo-hYC', 'Summoned to a small harbor town by a former trenchmate falsely accused of assaulting an ex-lover''s husband, Scotland Yard inspector Ian Rutledge is reminded of an affair from his own past and investigates a bizarre coincidence.', 'en', 2007, 384, 'http://books.google.com/books/content?id=MMG3b9fo-hYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
