INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0ba9870e-3200-547a-b1f2-ad4a9d127575', '9780060793197', 'The 3-Hour Diet (TM) On the Go (Collins Gem)', 'xaefjgEACAAJ', 'More Than 600 New Options! Imagine eating your favorite foods every 3 hours to finally get the results you''ve been searching for. NO calorie-counting, NO carb deprivation, and NO skipping sweets. Based on the revolutionary principles of Time-Based Nutrition™, this pocket guidebook will give you the slimming secrets you need to enjoy fast food, restaurant meals, gas station gourmet, and much more! Visit www.3hourdiet.net for your free personalized weight-loss profile.', 'en', 2005, 192, 'http://books.google.com/books/content?id=xaefjgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
