INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5104f19b-7f8d-5538-a9aa-5b3fa7a522a8', '9780060815523', 'The Best American Crime Writing 2006', 'Ec5HlwEACAAJ', 'A sterling collection of the year''s most shocking, compelling, and gripping writing about real-life crime, the 2006 edition of The Best American Crime Writing offers fascinating vicarious journeys into a world of felons and their felonious acts. This thrilling compendium includes: Jeffrey Toobin''s eye-opening exposé in The New Yorker about a famous prosecutor who may have put the wrong man on death row Skip Hollandsworth''s amazing but true tale of an old cowboy bank robber who turned out to be a "classic good-hearted Texas woman" Jimmy Breslin''s stellar piece about the end of the Mob as we know it', 'en', 2006, 352, 'http://books.google.com/books/content?id=Ec5HlwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
