INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('97f54dfa-58a3-59de-a2dd-23a5012af56e', '9780060841867', 'The Curtain', 'JCDXPxiayrwC', 'Traces the author''s personal view of the history and significance of the novel in western civilization, arguing that a novel''s development crosses international and language boundaries while serving to reveal previously unknown aspects of a reader''s existence. By the author of The Art of the Novel. 35,000 first printing.', 'en', 2006, 176, 'http://books.google.com/books/content?id=JCDXPxiayrwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
