INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3dc5eb7d-3d98-5b35-9414-b72c3b5f3ce9', '9780060845308', 'Mambo Kings Play Songs of Love, The Tie-in', 'rL2fOXmLquMC', 'In late 1940s New York City, Cesar and Nestor Castillo, two young Cuban musicians, are dubbed the "Mambo Kings" for their talent and rise to superstardom. Reissue. (Tie in to the Broadway musical production, produced by Daryl Roth, opening August 2005) (Historical Fiction)', 'en', 2005, 448, 'http://books.google.com/books/content?id=rL2fOXmLquMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
