INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e2f3d66b-ebb8-524b-b7bc-1936e0d0358f', '9780060882600', 'The Annotated Charlotte''s Web', 'vaYYHAAACAAJ', 'Charlotte''s Web, one of America''s best-loved children''s books, is seamless in plot, poignant in its delineation of characters who will live in children''s literature forever, and written with a seeming ease and fluency that make the reading as engrossing as it is effortless. The Annotated Charlotte''s Web opens the door to the creator''s workshop and allows the reader to glance over the shoulder of one of the most exacting and fastidious American writers, watching as he forms his masterpiece.', 'en', 2006, 320, 'http://books.google.com/books/content?id=vaYYHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
