INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9c5b585e-e02d-5d6f-bd18-ace933b1ba92', '9780060885373', 'Little House in the Big Woods', '7JctNysS3xkC', 'A year in the life of two young girls growing up on the Wisconsin frontier, as they help their mother with the daily chores, enjoy their father''s stories and singing, and share special occasions when they get together with relatives or neighbors.', 'en', 2007, 198, 'http://books.google.com/books/content?id=7JctNysS3xkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
