INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4f2b535e-3b87-5bdb-9f13-d77715e6a264', '9780060916817', 'The Chaneysville Incident', 'zYOcrhUIRX4C', 'The legends say something happened in Chaneysville. The Chaneysville Incident is the powerful story of one man''s obsession with discovering what that something was--a quest that takes the brilliant and bitter young black historian John Washington back through the secrets and buried evil of his heritage. Returning home to care for and then bury his father''s closest friend and his own guardian, Old Jack Crawley, he comes upon the scant records of his family''s proud and tragic history, which he drives himself to reconstruct and accept. This is the story of John''s relationship with his family, the town, and the woman he loves; and also between the past and the present, between oppression and guilt, hate and violence, love and acceptance.', 'en', 1990, 448, 'http://books.google.com/books/content?id=zYOcrhUIRX4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
