INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ba5c75bd-7c2e-566c-a86e-dc776041c967', '9780060921712', 'The Complete Stories', 't2NozDINo3UC', 'A collection of short stories, most of which appeared in literary magazines during the author''s lifetime, along with previously unpublished works, spans the career of one of the century''s foremost African-American writers. Reprint.', 'en', 1996, 336, 'http://books.google.com/books/content?id=t2NozDINo3UC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
