INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b210a959-7cc4-5335-8258-8349ec78ab32', '9780060927196', 'Success Stories', 'bGIs7R90isEC', 'In Sucess Stories, an exceptionally varied yet coherent collection, Russell Banks proves himself one of the most astute and forceful writers in America today. Queen for a Day, Success Story, and Adultery trace fortunes of the Painter family in there pursuit of and retreat from the American dream. Banks also explores the ethos of rampant materialism in a group of contemporary moral fables. The Fish is an evocating parable of faith and greed set in a Southeast Asian village, The Gully tells of the profitability of violence and the ironies of upward mobility in a Latin American shantytown, and Chrildren''s Story explores the repressed rage that boils beneath the surface of relationships between parents and children and between citizens of the first and third worlds.', 'en', 1996, 192, 'http://books.google.com/books/content?id=bGIs7R90isEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '341', 'accepted', 'Russell Banks', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 17 FROM public.book WHERE isbn13 = '9780060927196' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('981acd3d-a480-5710-9b43-eacba15c2ff4', '9780060927516', 'Testaments Betrayed', 'gWzdD3wGV8MC', 'Milan Kundera has established himself as one of the great novelists of our time with such books as The Unbearable Lightness of Being, Immortality and The Book of Laughter and Forgetting. In Testaments Betrayed, he proves himself a brilliant defender of the moral rights of the artist and the respect due to a work of art and its creator''s wishes. The betrayal of both—often by their most passionate proponents—is the principal theme of this extraordinary work. Readers will be particularly intrigued by Kundera''s impassioned attack on society''s shifting moral judgments and persecutions of art and artists, from Mayakovsky to Rushdie.', 'en', 1996, 288, 'http://books.google.com/books/content?id=gWzdD3wGV8MC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '342', 'accepted', 'Milan Kundera', 'Literary Collections', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 9 FROM public.book WHERE isbn13 = '9780060927516' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ecda38c2-5215-5ecb-aaba-4ad4c9047d7d', '9780060927547', 'Mr. Ives'' Christmas', 'Z7XK28QOcWAC', 'Hijuelos'' novel tells the story of Mr. Ives, who was adopted from a foundling''s home as a child. When we first meet him in the 1950s, Mr. Ives is very much a product of his time. He has a successful career in advertising, a wife and two children, and believes he is on his way to pursuing the typical American dream. But the dream is shattered when his son Robert, who is studying for the priesthood, is killed violently at Christmas. Overwhelmed by grief and threatened by a loss of faith in humankind, Mr. Ives begins to question the very foundations of his life. Part love story--of a man for his wife, for his children, for God--and part meditation on how a person can find spiritual peace in the midst of crisis, Mr. Ives'' Christmas is a beautifully written, tender and passionate story of a man trying to put his life in perspective. In the expert hands of Oscar Hijuelos, the novel speaks eloquently to the most basic and fulfilling aspects of life for all of us.', 'en', 1996, 256, 'http://books.google.com/books/content?id=Z7XK28QOcWAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '343', 'accepted', 'Oscar Hijuelos', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 18 FROM public.book WHERE isbn13 = '9780060927547' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('15e9a352-ef21-5cc8-b617-c7feee51e0dc', '9780060928414', 'Slowness', 'czPAd_xrPyMC', 'Milan Kundera''s lightest novel, a divertimento, an opera buffa, Slowness is also the first of this author''s fictional works to have been written in French. Disconcerted and enchanted, the reader follows the narrator of Slowness through a midsummer''s night in which two tales of seduction, separated by more than two hundred years, interweave and oscillate between the sublime and the comic. Underlying this libertine fantasy is a profound meditation on contemporary life: about the secret bond between slowness and memory, about the connection between our era''s desire to forget and the way we have given ourselves over to the demon of speed. And about "dancers" possessed by the passion to be seen, for whom life is merely a perpetual show emptied of every intimacy and every joy.', 'en', 1997, 156, 'http://books.google.com/books/content?id=czPAd_xrPyMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
