INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7988f231-2691-5e07-975d-11d4ea102065', '9780060930134', 'The Fifth Mountain', 'HKq_H_z2XsYC', 'Elijah, a biblical prophet in the Middle East during the ninth century B.C., confronts the pagan princess Jezebel and finds love in the strange land of Zarephath with a young widow, only to have his new-found happiness shattered by tragedy', 'en', 1999, 256, 'http://books.google.com/books/content?id=HKq_H_z2XsYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
