INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4469d7e3-95ba-5b7b-8451-aa7d2f075bf1', '9780060930868', 'Cloudsplitter', 'gri4AX2RVSEC', 'A triumph of the imagination and a masterpiece of modern storytelling, Cloudsplitter is narrated by the enigmatic Owen Brown, last surviving son of America''s most famous and still controversial political terrorist and martyr, John Brown. Deeply researched, brilliantly plotted, and peopled with a cast of unforgettable characters both historical and wholly invented, Cloudsplitter is dazzling in its re-creation of the political and social landscape of our history during the years before the Civil War, when slavery was tearing the country apart. But within this broader scope, Russell Banks has given us a riveting, suspenseful, heartbreaking narrative filled with intimate scenes of domestic life, of violence and action in battle, of romance and familial life and death that make the reader feel in astonishing ways what it is like to be alive in that time.', 'en', 1999, 758, 'http://books.google.com/books/content?id=gri4AX2RVSEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '353', 'accepted', 'Russell Banks', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 10 FROM public.book WHERE isbn13 = '9780060930868' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1de94268-6e1c-59fa-9306-f85e4caba5ec', '9780060931360', 'Plato, Not Prozac!', 'CZgACbdCRB8C', 'If you''re facing a dilemma -- whether it''s handling a relationship, living ethically, dealing with a career change, or finding meaning in life -- the world''s most important thinkers from centuries past will help guide you toward a solution compatible with your individual beliefs. From Kirkegaard''s thoughts on coping with death to the I Ching''s guidelines on adapting to change, Plato, Not Prozac! makes philosophy accessible and shows you how to use it to solve your everyday problems. Gone is the need for expensive therapists, medication, and lengthy analysis. Clearly organized by common problems to help you tailor Dr. Lou Marinoff''s advice to your own needs, this is an intelligent, effective, and persuasive prescription for self-healing therapy that is giving psychotherapy a run for its money.', 'en', 2000, 320, 'http://books.google.com/books/content?id=CZgACbdCRB8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
