INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2854ccc2-7052-5f72-a2cf-ce19a3a3e4d8', '9780060931803', 'The Map That Changed the World', 'W523pFmahJQC', 'An enthralling glimpse into the life of William Smith, a nineteenth-century engineer who became the founding father of modern geology, explores his creation of a lavish map detailing his discovery that rocks are comprised of many different layers amidst the backdrop of his wife''s madness and debtors prison. By the author of The Professor and the Madman. Reprint.', 'en', 2002, 352, 'http://books.google.com/books/content?id=W523pFmahJQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
