INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('87716db0-26b7-54f6-b31c-0090a3f05787', '9780060932688', 'Collected Stories', 'DksnCgBzb3oC', 'Collected here are twenty-six of Gabriel Garcia Marquez''s most brilliant and enchanting short stories, presented in the chronological order of their publication in Spanish from three volumes: Eyes of a Blue Dog,Big Mama''s Funeral, and The Incredible and Sad Tale of lnnocent Eréndira and Her Heartless Grandmother. Combining mysticism, history, and humor, the stories in this collection span more than two decades, illuminating the development of Marquez''s prose and exhibiting the themes of family, poverty, and death that resound throughout his fiction.', 'en', 1999, 352, 'http://books.google.com/books/content?id=DksnCgBzb3oC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '359', 'accepted', 'Gabriel Garcia Marquez', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 3 FROM public.book WHERE isbn13 = '9780060932688' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5f15cb30-9b9b-57f1-8d17-eaf6c43503e6', '9780060933524', 'A Mulligan for Bobby Jobe', '6XAkcx5J6w4C', 'Bobby Jobe is a pro golfer whose swing is better than his attitude. When he bogies the last four holes and blows his lead in a major tournament -- again -- he berates his caddy, Henry "Greyhound" Mote. Jobe loses both Greyhound, who walks off the course, and the game. And before the day is out, he''ll lose his eyesight to a lightning strike and his future in golf -- unless he can do what no one has ever done blind: make a comeback. Bob Cullen''s funny and wise story, full of PGA lore, perfectly captures the mysterious and irresistible nature of the game of golf, not to mention, love, friendship, and life.', 'en', 2002, 400, 'http://books.google.com/books/content?id=6XAkcx5J6w4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
