INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('187dcee5-4dd2-5f9c-8b4a-e29dbd771006', '9780060935559', 'One Matchless Time', 'oXpAlwEACAAJ', 'William Faulkner was a literary genius, and one of America''s most important and influential writers. Drawing on previously unavailable sources -- including letters, memoirs, and interviews with Faulkner''s daughter and lovers -- Jay Parini has crafted a biography that delves into the mystery of this gifted and troubled writer. His Faulkner is an extremely talented, obsessive artist plagued by alcoholism and a bad marriage who somehow transcends his limitations. Parini weaves the tragedies and triumphs of Faulkner''s life in with his novels, serving up a biography that''s as engaging as it is insightful.', 'en', 2005, 528, 'http://books.google.com/books/content?id=oXpAlwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '364', 'accepted', 'Jay Parini', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 3 FROM public.book WHERE isbn13 = '9780060935559' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('47ffd476-acfa-53a7-bd34-163199d88df9', '9780060936198', 'The Girl in the Glass', 'mgYTlwEACAAJ', 'The Great Depression has bound a nation in despair -- and only a privileged few have risen above it: the exorbitantly wealthy ... and the hucksters who feed upon them. Diego, a seventeen-year-old illegal Mexican immigrant, owes his salvation to master grifter Thomas Schell. Together with Schell''s gruff and powerful partner, they sail comfortably through hard times, scamming New York''s grieving rich with elaborate, ingeniously staged séances -- until an impossible occurrence changes everything. While "communing with spirits," Schell sees an image of a young girl in a pane of glass, silently entreating the con man for help. Though well aware that his otherworldly "powers" are a sham, Schell inexplicably offers his services to help find the lost child -- drawing Diego along with him into a tangled maze of deadly secrets and terrible experimentation. At once a hypnotically compelling mystery and a stunningly evocative portrait of Depression-era New York, The Girl in the Glass is a masterly literary adventure from a writer of exemplary vision and skill.', 'en', 2005, 304, 'http://books.google.com/books/content?id=mgYTlwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
