INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('60c5b27e-f2d2-562a-8461-8eef82a5bda5', '9780060936501', 'The Best American Science Writing 2002', 'p8yA_CtoUx0C', 'If, as Matt Ridley suggests, science is simply the search for new forms of ignorance, then perhaps it follows that with science''s advances come new questions. Will human genetic engineering become commonplace? Will human cloning ever be safe? Are there many universes? How much will the climate change during the coming century? The Best American Science Writing 2002 gathers top writers and scientists covering the latest developments in the fastest-changing, farthest-reaching scientific fields, such as medicine, genetics, computer technology, evolutionary psychology, cutting-edge physics, and the environment. Among this year''s selections: In "The Made-to-Order Savior," Lisa Belkin spotlights two desperate families seeking an unprecedented cure by a medically and ethically unprecedented means -- creating a genetically matched child. Margaret Talbot''s "A Desire to Duplicate" reveals that the first human clone may very likely come from an entirely unexpected source, and sooner than we think. Michael Specter reports on the shock waves rippling through the field of neuroscience following the revolutionary discovery that adult brain cells might in fact regenerate ("Rethinking the Brain"). Christopher Dickey''s "I Love My Glow Bunny" recounts with sly humor a peculiar episode in which genetic engineering and artistic culture collide. Natalie Angier draws an insightful contrast between suicide terrorists and rescue workers who risk their lives, and finds that sympathy and altruism have a definite place in the evolution of human nature, David Berlinski''s "What Brings a World into Being?" ponders the idea of biology and physics as essentially digital technologies, exploring the mysteries encoded in the universe''s smallest units, be they cells or quanta. Nicholas Wade shows how one of the most controversial books of the year, The Skeptical Environmentalist, by former Greenpeace member and self-described leftist Bjorn Lomborg, debunks some of the most cherished tenets of the environmental movement, suggesting that things are perhaps not as bad as we''ve been led to believe. And as a counterpoint, Darcy Frey''s profile of George Divoky reveals a dedicated researcher whose love of birds and mystery leads to some sobering discoveries about global warming and forcefully reminds us of the unsung heroes of science: those who put in long hours, fill in small details, and take great trouble. In the end, the unanswered questions are what sustain scientific inquiry, open new frontiers of knowledge, and lead to new technologies and medical treatments. The Best American Science Writing 2002 is a series of exciting reports from science''s front lines, where what we don''t know is every bit as important as what we know.', 'en', 2002, 352, 'http://books.google.com/books/content?id=p8yA_CtoUx0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '366', 'accepted', 'Matt Ridley; Alan Lightman', 'Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 13 FROM public.book WHERE isbn13 = '9780060936501' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('780572d6-675f-51b0-bcde-1e37baa44143', '9780060936648', 'Wittgenstein''s Poker', '9Ahdyu6ygXEC', 'On October 25, 1946, in a crowded room in Cambridge, England, the great twentieth-century philosophers Ludwig Wittgenstein and Karl Popper came face to face for the first and only time. The meeting -- which lasted ten minutes -- did not go well. Their loud and aggressive confrontation became the stuff of instant legend, but precisely what happened during that brief confrontation remained for decades the subject of intense disagreement. An engaging mix of philosophy, history, biography, and literary detection, Wittgenstein''s Poker explores, through the Popper/Wittgenstein confrontation, the history of philosophy in the twentieth century. It evokes the tumult of fin-de-siécle Vienna, Wittgentein''s and Popper''s birthplace; the tragedy of the Nazi takeover of Austria; and postwar Cambridge University, with its eccentric set of philosophy dons, including Bertrand Russell. At the center of the story stand the two giants of philosophy themselves -- proud, irascible, larger than life -- and spoiling for a fight.', 'en', 2002, 368, 'http://books.google.com/books/content?id=9Ahdyu6ygXEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '367', 'accepted', 'David Edmonds; John Eidinow', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 13 FROM public.book WHERE isbn13 = '9780060936648' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0f47baa6-6349-5ad3-b5f3-059f4238044c', '9780060936662', 'Smart Discipline(R)', 'Bpo2r2iKcKsC', 'Larry J. Koenig, Ph.D., creator of the hugely popular Smart Discipline® seminars, explains his simple, dramatically effective system to help children follow the rules at home and at school. It is easily tailoredto differences in age, temperament, and the needs of children with ADD/ADHD. Positive results usually are seen within a few days. Best of all: instead of nagging, parents can use Dr. Koenig''s powerful esteem-building strategies to affirm their children''s strengths. The Smart Discipline system: Gets kids to do what you ask, the first time you ask Stops fighting, bickering, and disrespectful language Ends hassles over homework, chores, messy rooms, and bedtime Instills positive self-image and builds confidence. . . and much more!', 'en', 2004, 208, 'http://books.google.com/books/content?id=Bpo2r2iKcKsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '368', 'accepted', 'Larry Koenig', 'Family & Relationships', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 15 FROM public.book WHERE isbn13 = '9780060936662' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0f04f719-5b29-5f6f-883c-56eef814a1e0', '9780060938109', 'The Schopenhauer Cure', 'aDG4lgEACAAJ', 'Suddenly confronted with his own mortality after a routine checkup, eminent psychotherapist Julius Hertzfeld is forced to reexamine his life and work -- and seeks out Philip Slate, a sex addict whom he failed to help some twenty years earlier. Yet Philip claims to be cured -- miraculously transformed by the pessimistic teachings of German philosopher Arthur Schopenhauer -- and is, himself, a philosophical counselor in training. Philips dour, misanthropic stance compels Julius to invite Philip to join his intensive therapy group in exchange for tutoring on Schopenhauer. But with mere months left, life may be far too short to help Philip or to compete with him for the hearts and minds of the group members. And then again, it might be just long enough.', 'en', 2006, 358, 'http://books.google.com/books/content?id=aDG4lgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '369', 'accepted', 'Irvin Yalom', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 8 FROM public.book WHERE isbn13 = '9780060938109' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7e708821-b24d-54b3-867b-be53aa884c89', '9780060954833', 'African Nights', 'MRgktwEACAAJ', 'Lyrical, beautifully written tales of life in Africa Africa evokes a deep sense of mystery. It is a place that retains what most of the world has lost: space, roots, traditions, awesome beauty, true wilderness, rare animals, and extraordinary people. In this wonderful and haunting collection of stories, Kuki Gallmann writes of her life in Africa, where every day brings challenge and adventure. African Nights is a treasury of memories, in which fascinating people and places are brought to life. The healing powers Africa can have on those who embrace the land as a place of mystery, superstition, danger, and beauty.', 'en', 2000, 336, 'http://books.google.com/books/content?id=MRgktwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '370', 'accepted', 'Kuki Gallmann', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 16 FROM public.book WHERE isbn13 = '9780060954833' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c5e7344c-4871-52c0-b59f-f549a8afd6db', '9780060955427', 'The Autobiography of Mark Twain', '5GboyAEACAAJ', '"Mark Twain''s autobiography is a classic of American letters, to be ranked with the autobiographies of Benjamin Franklin and Henry Adams.... It has the marks of greatness in it--style, scope, imagination, laughter, tragedy."--From the Introduction by Charles Neider Mark Twain was a figure larger than fife: massive in talent, eruptive in temperament, unpredictable in his actions. He crafted stories of heroism, adventure, tragedy, and comedy that reflected the changing America of the time, and he tells his own story--which includes sixteen pages of photos--with the same flair he brought to his fiction. Writing this autobiography on his deathbed, Twain vowed to he "free and frank and unembarrassed" in the recounting of his life and his experiences. Twain was more than a match for the expanding America of riverboats, gold rushes, and the vast westward movement, which provided the material for his novels and which served to inspire this beloved and uniquely American autobiography.', 'en', 2000, 508, 'http://books.google.com/books/content?id=5GboyAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
