INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d0c67303-a853-5736-9040-422345a5fbad', '9780060957353', 'The Darling', 'NlC2QKgJY4kC', 'Set in Liberia and the United States from 1975 through 1991, The Darling is the story of Hannah Musgrave, a political radical and member of the Weather Underground. Hannah flees America for West Africa, where she and her Liberian husband become friends of the notorious warlord and ex-president, Charles Taylor. Hannah''s encounter with Taylor ultimately triggers a series of events whose momentum catches Hannah''s family in its grip and forces her to make a heartrending choice.', 'en', 2005, 400, 'http://books.google.com/books/content?id=NlC2QKgJY4kC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '374', 'accepted', 'Russell Banks', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 2 FROM public.book WHERE isbn13 = '9780060957353' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1498459d-3e1c-5316-9ab6-9ea79f4c986f', '9780060957605', 'The Making of a Philosopher', 'oJ5dL5OmXHMC', 'Part memoir, part study, The Making of a Philosopher is the self–portrait of a deeply intelligent mind as it develops over a life on both sides of the Atlantic. The Making of a Philosopher follows Colin McGinn from his early years in England reading Descartes and Anselm, to his years in the states, first in Los Angeles, then New York. McGinn presents a contemporary academic take on the great philosophical figures of the twentieth century, including Bertrand Russell, Jean–Paul Sartre, and Noam Chomsky, alongside stories of the teachers who informed his ideas and often became friends and mentors, especially the colorful A.J. Ayer at Oxford. McGinn''s prose is always elegant and probing; students of contemporary philosophy and the general reader alike will absorb every page.', 'en', 2003, 256, 'http://books.google.com/books/content?id=oJ5dL5OmXHMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
