INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a2df8d13-8f83-5012-82de-7589c0879b63', '9780060973339', 'Fear of Falling', 'votxQgAACAAJ', 'A brilliant and insightful work that examines the insecurities of the middle class in an attempt to explain its turn to the right during the past two decades, "Fear of Falling" traces the myths about the middle class to their roots in the ambitions and anxieties that torment the group and that have led to its retreat from a responsible leadership role.', 'en', 1989, 292, 'http://books.google.com/books/content?id=votxQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
