INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f9097cfe-860b-5b6e-9b3b-485ab0456cec', '9780060975098', 'Three Farmers on Their Way to a Dance', 'U6zjwAEACAAJ', 'In the spring of 1914, renowned photographer August Sander took a photograph of three young men on their way to a country dance. This haunting image, capturing the last moments of innocence on the brink of World War I, provides the central focus of Powers''s brilliant and compelling novel. As the fate of the three farmers is chronicled, two contemporary stories unfold. The young narrator becomes obsessed with the photo, while Peter Mays, a computer writer in Boston, discovers he has a personal link with it. The three stories connect in a surprising way and provide the reader with a mystery that spans a century of brutality and progress.', 'en', 1992, 352, 'http://books.google.com/books/content?id=U6zjwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
