INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8527eee7-bc6b-50f5-a253-7c39f94279ac', '9780060976095', 'Fiskadoro', 'YSTe7qSIA0wC', 'Hailed by the New York Times as "wildly ambitious" and "the sort of book that a young Herman Melville might have written had he lived today and studied such disparate works as the Bible, ''The Wasteland,'' Fahrenheit 451, and Dog Soldiers, screened Star Wars and Apocalypse Now several times, dropped a lot of acid and listened to hours of Jimi Hendrix and the Rolling Stones," Fiskadoro is a stunning novel of an all-too-possible tomorrow. Deeply moving and provacative, Fiskadoro brilliantly presents the sweeping and heartbreaking tale of the survivors of a devastating nuclear war and their attempts to breaking tale of the survivors of a devastating nuclear war and their attempts to salvage remnants of the old world and rebuild their culture.', 'en', 1995, 221, 'http://books.google.com/books/content?id=YSTe7qSIA0wC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
