INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4414c581-3c53-5e09-b517-3e325b059da6', '9780060976101', 'The Stars at Noon', 'mAXpwAEACAAJ', 'Set in Nicaragua in 1984, The Stars at Noon is a story of passion, fear, and betrayal told in the voice of an American woman whose mission in Central America is as shadowy as her surroundings. Is she a reporter for an American magazine as she sometimes claims, or a contact person for Eyes of Peace? And who is the rough English businessman with whom she becomes involved? As the two foreigners become entangled in increasingly sinister plots, Denis Johnson masterfully dramatizes a powerful vision of spiritual bereavement and corruption.', 'en', 1995, 192, 'http://books.google.com/books/content?id=mAXpwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
