INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('875de28a-261b-533a-8755-9a44611fce0d', '9780060977085', 'Prisoner''s Dilemma', '1YScHAvC1gMC', 'Something is wrong with Eddie Hobson Sr., father of four, sometime history teacher, quiz master, black humorist and virtuoso invalid. His recurring fainting spells have worsened, and with his ingrained aversion to doctors, his worried family tries to discover the nature of his sickness. Meanwhile, in private, Eddie puts the finishing touches on a secret project he calls Hobbstown, a place that he promises will save him, the world and everything that''s in it. A dazzling novel of compassion and imagination, Prisoner''s Dilemma is a story of the power of invalid experience.', 'en', 1996, 352, 'http://books.google.com/books/content?id=1YScHAvC1gMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
