INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d5f38a98-e339-5c9a-94ee-d5788e3a0dd0', '9780060987466', 'The Long Hard Road Out of Hell', 'Z05eRmEpdjIC', 'The best-selling autobiography of America’s most controversial celebrity icon, Marilyn Manson (with a bonus chapter not in the hardcover). In his twenty-nine years, rock idol Manson has experienced more than most people have (or would want to) in a lifetime. Now, in his shocking and candid memoir, he takes readers from backstage to gaol cells, from recording studios to emergency rooms, from the pit of despair to the top of the charts, and recounts his metamorphosis from a frightened Christian schoolboy into the most feared and revered music superstar in the country. Illustrated with dozens of exclusive photographs and featuring a behind-the-scenes account of his headline-grabbing Dead to the World tour.', 'en', 1999, 275, 'http://books.google.com/books/content?id=Z05eRmEpdjIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '394', 'accepted', 'Marilyn Manson; Neil Strauss', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 6 FROM public.book WHERE isbn13 = '9780060987466' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a1459d24-17d2-55d7-bfee-e563c0d2d05c', '9780060987527', 'Confessions of an Ugly Stepsister', 'R7lwacBA53QC', 'Is this new land a place where magics really happen? From Gregory Maguire, the acclaimed author of Wicked, comes his much-anticipated second novel, a brilliant and provocative retelling of the timeless Cinderella tale. In the lives of children, pumpkins can turn into coaches, mice and rats into human beings.... When we grow up, we learn that it''s far more common for human beings to turn into rats.... We all have heard the story of Cinderella, the beautiful child cast out to slave among the ashes. But what of her stepsisters, the homely pair exiled into ignominy by the fame of their lovely sibling? What fate befell those untouched by beauty . . . and what curses accompanied Cinderella''s exquisite looks? Extreme beauty is an affliction Set against the rich backdrop of seventeenth-century Holland, Confessions of an Ugly Stepsister tells the story of Iris, an unlikely heroine who finds herself swept from the lowly streets of Haarlem to a strange world of wealth, artifice, and ambition. Iris''s path quickly becomes intertwined with that of Clara, the mysterious and unnaturally beautiful girl destined to become her sister. Clara was the prettiest child, but was her life the prettiest tale? While Clara retreats to the cinders of the family hearth, burning all memories of her past, Iris seeks out the shadowy secrets of her new household--and the treacherous truth of her former life. God and Satan snarling at each other like dogs.... Imps and fairy godmotbers trying to undo each other''s work. How we try to pin the world between opposite extremes! Far more than a mere fairy-tale, Confessions of an Ugly Stepsister is a novel of beauty and betrayal, illusion and understanding, reminding us that deception can be unearthed--and love unveiled--in the most unexpected of places.', 'en', 2000, 372, 'http://books.google.com/books/content?id=R7lwacBA53QC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '395', 'accepted', 'Gregory Maguire', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 13 FROM public.book WHERE isbn13 = '9780060987527' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('893d63a7-9e6e-5eb4-abe8-001e9e79987f', '9780060989156', 'The Dirt', '6vcYiMsZaR0C', 'The most influential, enduring, and iconic metal band of the 1980''s reveals everything a tell-all of epic proportions. This unbelievable autobiography explores the rebellious lives of four of the most influential icons in American rock history. Motley Crue was the voice of a barely pubescent Generation X, the anointed high priests of backward-masking pentagram rock, pioneers of Hollywood glam, and the creators of MTV''s first "power ballad." Their sex lives claimed celebrities from Heather Locklear to Pamela Anderson to Donna D''Errico. Their scuffles involved everyone from Axl Rose to 2LiveCrew. Their hobbies have included collecting automatic weapons, cultivating long arrest records, pushing the envelope of conceivable drug abuse, and dreaming up backstage antics that would make Ozzy Osbourne blanch with modesty. Provocatively written and brilliantly designed, this book includes over 100 photos, many never before published, for the most exciting and insightful look ever into the Crue.', 'en', 2002, 431, 'http://books.google.com/books/content?id=6vcYiMsZaR0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '396', 'accepted', 'Tommy Lee; Vince Neil; Nikki Sixx; Mick Mars', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 9 FROM public.book WHERE isbn13 = '9780060989156' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0d810fe0-57bb-5ce0-bb92-e67225366645', '9780060997021', 'Life Is Elsewhere', 'Q4-KVB3OnskC', 'The author initially intended to call this novel The Lyrical Age. The lyrical age, according to Kundera, is youth, and this novel, above all, is an epic of adolescence; an ironic epic that tenderly erodes sacrosanct values: childhood, motherhood, revolution, and even poetry. Jaromil is in fact a poet. His mother made him a poet and accompanies him (figuratively) to his love bed and (literally) to his deathbed. A ridiculous and touching character, horrifying and totally innocent ("innocence with its bloody smile"!), Jaromil is at the same time a true poet. He''s no creep, he''s Rimbaud. Rimbaud entrapped by the communist revolution, entrapped in a somber farce.', 'en', 2000, 432, 'http://books.google.com/books/content?id=Q4-KVB3OnskC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '397', 'accepted', 'Milan Kundera; Aaron Asher', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 8 FROM public.book WHERE isbn13 = '9780060997021' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('11bd4ef8-03a6-594e-b4a8-522b55a7e713', '9780061015625', 'Cat Laughing Last', 'KwDSlgEACAAJ', 'Fans of Lillian Jackson Braun and Rita Mae Brown and cat lovers everywhere will delight in this newest mystery featuring two furry felines on the scent of a killer. Famous novelist Elliot Traynor is temporarily living in Molena Point. He and his wife don''t have much to do with the villagers, which is fine with them since no one particularly likes Vivi. But their arrival has coincided with some peculiar happenings in the town, culminating with a botched burglary in the home of 60–something Susan Brittian. Susan is a friend to feline detectives Joe Grey and Dulcie and they aren''t going to let this crime go unpunished. With whiskers twitching they investigate the crime and soon find themselves on the scent of a killer.', 'en', 2002, 368, 'http://books.google.com/books/content?id=KwDSlgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
