INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2c90511b-f38c-579f-9cf7-e2802f59e835', '9780061020094', 'The Crow: The Lazarus Heart', '_ccsPwAACAAJ', 'As S&M photographer Jared Poe waits on Louisiana''s Death Row to be executed for the murder of his lover, he can not imagine that his search for the true killer will continue after his death in the shadowy realm of The Crow', 'en', 1999, 336, 'http://books.google.com/books/content?id=_ccsPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
