INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1a395f3c-d1f0-5b70-b36f-c5eb17899ce1', '9780061020575', 'Well of Darkness', '32gVlwEACAAJ', 'Second in line for succession to the throne, Prince Dagnarus will have his crown...and his queen -- though his heart''s prize is a married elfin beauty. Let his hated half-brother Prince Helmos and the Dominion Lords dare to oppose him. For Dagnarus''s most loyal servant has ventured into the terrible darkness, where lies the most potent talisman in the realm. And once it is in the dark prince''s hand, no power will deter his Destiny.', 'en', 2001, 562, 'http://books.google.com/books/content?id=32gVlwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '400', 'needs_review', 'Margaret Weis; Tracy Hickman', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 0 FROM public.book WHERE isbn13 = '9780061020575' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bf65ee80-5df8-5e7d-9a2e-3a29d7cba660', '9780061020704', 'The Light Fantastic', 'fAU6uoSrTJEC', 'Terry Pratchett''s profoundly irreverent novels are consistent number one bestsellers in England, where they have garnered him a revered position in the halls of parody next to Mark Twain, Kurt Vonnegut, Douglas Adams, and Carl Hiaasen. In The Light Fantastic only one individual can save the world from a disastrous collision. Unfortunately, the hero happens to be the singularly inept wizard Rincewind, who was last seen falling off the edge of the world...', 'en', 2000, 241, 'http://books.google.com/books/content?id=fAU6uoSrTJEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
