INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('66c1224d-af47-5b42-b3ee-8cea31019a6f', '9780061030659', 'U.S.S. Seawolf', 'd63jTKM6iGcC', 'Armed with stolen U.S. military technology, the Chinese are producing a frightening new breed of weaponry,led by the ICBM submarine Xia III -- a vessel that just might be able to launch a nuclear warhead across the Pacific Ocean and take out an American West Coast city. National Security Adviser Admiral Arnold Morgan can''t let that happen, and he dispatches the most stealthy hunter-killer submarine in the U.S. fleet, the 9,000-ton ultrasecret Seawolf, deep into the dark, forbidden waters of the South China Sea. But then the unthinkable happens: Seawolf, collides with a Chinese destroyer and falls into enemy hands. A team of cunning Navy SEALs -- the biggest Special Forces assault group assembled since Vietnam -- is sent in to free the captive Seawolf, crew and bring them home. The American Eagle confronts the Chinese Dragon with the balance of world power on the line. Failure is not an option...', 'en', 2001, 496, 'http://books.google.com/books/content?id=d63jTKM6iGcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
