INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('734fffee-8da7-52b2-b905-6eefc6a96b27', '9780061054679', 'Peril''s Gate', 'OSOvzcbhuucC', 'On the world of Athera, the fate of all realms hangs on the resolution of the brutal conflict born of prince against prince. Branded a minion of evil -- escaping the death sentence imposed by his half-brother Lysaer and his Alliance of Light -- Arithon, Master of Shadow, now faces the last choice remaining to him in the merciless winter wilds: to cast his lot with a renegade enchanter whom Arithon dares not trust ... or die by the swords of fanatical enemies.', 'en', 2002, 940, 'http://books.google.com/books/content?id=OSOvzcbhuucC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
