INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('01530598-8c39-5076-ad5b-bb3153c429d7', '9780061054907', 'Love in Vein', 'AO_bZJcLnHEC', 'A sexy new repackaging of the extremely popular anthology of vampire erotica, edited by acclaimed author Poppy Z. Brite. The classic horror tale is about fear. But in the last few years a new literature of the macabre has arisen, one that goes deeper than horror, beyond fear, to explore our darkest, most intimate hungers. The ones even lovers are forbidden to share. Acclaimed dark fantasy author Poppy Z. Brite has brought together this genre''s most powerful and seductive authors in an original collection of vampiric erotica, a shameless celebration of unspeakable intimacies. It is not for everyone. But neither is the night.', 'en', 1995, 397, 'http://books.google.com/books/content?id=AO_bZJcLnHEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
