INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4a32fe6a-039b-50c4-adf9-e4141ce95dc5', '9780061056000', 'Cat on the Edge', 'G0yvy42PB1AC', 'It''s been quite a week for Joe Grey. First the large, powerful feline discovers that, through some strange, inexplicable phenomenon, he now has the ability to understand human language. Then he discovers he can speak it as well! It''s a nightmare for a cat who''d prefer to sleep the day away carefree, but Joe can handle it. That is, until he has the misfortune to witness a murder in the alley behind Jolly''s Deli -- and worse, to be seen witnessing it. With all of his nine lives suddenly at risk, Joe''s got no choice but to get to the bottom of the heinous crime -- because his mouse-hunting days are over for good unless he can help bring a killer to justice.', 'en', 1996, 274, 'http://books.google.com/books/content?id=G0yvy42PB1AC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '409', 'accepted', 'Shirley Rousseau Murphy', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 1 FROM public.book WHERE isbn13 = '9780061056000' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a651e5fe-adb3-5ea7-820f-9f199a2c2c97', '9780061059476', 'Cat in the Dark', 'wz1vlwEACAAJ', '"Of course I worry. What if the cops witness a cat opening a skylight and masterminding a robbery? The tabloids will love it." There''s a new pair of thieves in Molena Point, California, a renegade yellow-eyed tomcat with a cold disdain for the law, and a scruffy human partner who is no better. The two, clever and silent at their work, are bad news indeed to crime-solving cats Joe Grey and Dulcie. But when Joe learns the pair''s connection to a good friend, and then an innocent couple turns up dead in the library garden, Joe and Dulcie must engage in some fancy paw work to unmask the deceptions and route the real killer -- before his brazen criminal crime spree careens madly toward them.', 'en', 1999, 320, 'http://books.google.com/books/content?id=wz1vlwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '410', 'accepted', 'Shirley Rousseau Murphy', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 18 FROM public.book WHERE isbn13 = '9780061059476' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ef729fa9-d4da-5041-b259-f880a4344cd9', '9780061093982', 'Treasure Box', 'KRbrxIVhjnMC', 'A shattering childhood tragedy left Quentin Fears devastated and unable to cope with the world and its citizens. It didn''t, however, prevent him from making millions through brilliant investments. And now the enigmatic recluse has experienced the extraordinarily unexpected: love at first sight. But a whirlwind courtship and marriage to Madeleine -- beautiful, witty, and equally ill-at-ease with reality -- is bringing Quentin something other than the bliss he anticipated, for now he must meet his new wife''s family. A bizarre, dysfunctional collection of extreme characters, they are guarding a secret both shocking and terrifying -- as is Madeleine herself. And suddenly Quentin Fears must prevent his dream woman from unleashing an ageless malevolence intent on ruling the world.', 'en', 1997, 384, 'http://books.google.com/books/content?id=KRbrxIVhjnMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '411', 'accepted', 'Orson Scott Card', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 5 FROM public.book WHERE isbn13 = '9780061093982' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dbf9a9fa-1894-5a00-a5d9-6cd0b3a3566c', '9780061093999', 'Homebody', 'X4Hyy8XRBf0C', 'Damaged Houses A master craftsman, Don Lark could fix everything except what mattered, his own soul. After tragedy claimed the one thing he loved, he began looking for dilapidated houses to buy, renovate, and resell at a profit--giving these empty shells the second chance at life he denied himself. Damaged Souls Then in a quiet Southern town, Lark finds his biggest challenge: a squalid yet sturdy mansion that has suffered decades of abuse at the hands of greedy landlords and transient tenants. While two charming old neighbor ladies ply him with delicious cooking, they offer dire warnings about the house''s evil past. But there is something about this building that pushes Lark on, even as its enchantments grow increasingly ominous. Will finishing the house offer Lark redemption, or unleash the darkest forces of damnation upon him?', 'en', 1999, 430, 'http://books.google.com/books/content?id=X4Hyy8XRBf0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '412', 'accepted', 'Orson Scott Card', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 11 FROM public.book WHERE isbn13 = '9780061093999' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('842664e2-11e6-5752-9de0-2567f1d1c0dc', '9780061094156', 'Imajica II', 'DZVKScH9E5oC', 'The magical tale of ill-fated lovers lost among worlds teetering on the edge of destruction, where their passion holds the key to escape. There has never been a book like Imajica. Transforming every expectation offantasy fiction with its heady mingling of radical sexuality and spiritual anarchy, it has carried its millions of readers into regions of passion and philosophy that few books have even attempted to map. It''s an epic in every way; vast in conception, obsessively detailed in execution, and apocalyptic in its resolution. A book of erotic mysteries and perverse violence. A book of ancient, mythological landscapes and even more ancient magic.', 'en', 1995, 544, 'http://books.google.com/books/content?id=DZVKScH9E5oC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
