INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('55c340b6-6746-52df-8d12-b4dedb4efb3e', '9780061094224', 'Choke', '_H-mz4TopZ4C', 'Chuck Chandler, a Key West tennis pro, tends to choke in his big matches, a tendency he must overcome when he meets Harry Carras and his beautiful wife Clare, and becomes a suspect in Harry''s death', 'en', 1996, 352, 'http://books.google.com/books/content?id=_H-mz4TopZ4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '414', 'accepted', 'Stuart Woods', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 16 FROM public.book WHERE isbn13 = '9780061094224' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('02f5b954-c63e-5e7f-954c-79c33953dcee', '9780061094231', 'Dirt', '6RxDPgAACAAJ', 'On the heels of his New York Times bestseller Choke, Stuart Woods brings back one of his best-loved characters, Stone Barrington, in a glittering roller-coaster ride through the murderous world of high-profile celebrity gossip. Feared and disliked for both her poison pen and ice-queen persona, gossip columnist Amanda Dart finds the tables have turned. When an anonymous gossipmonger begins faxing the scathing details of Amanda''s sexual indiscretions to national opinion makers, she turns to Stone Barrington for help. But as the faxes also expose other members of the gossip "community," it becomes apparent that the most respected of the social scene will stop at nothing--even murder--to clear their names. Set against a backdrop of glitzy Manhattan society, Dirt is a sexy, fast-paced and witty thriller--Stuart Woods at his best.', 'en', 1997, 448, 'http://books.google.com/books/content?id=6RxDPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
