INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('55419b6a-6ca3-5f74-aac3-73745e61fd59', '9780061125935', 'Goodnight Moon 123', '3Q2focAO09AC', 'A little bunny counts and bids goodnight to all the objects in his room before falling asleep.', 'en', 2007, 32, 'http://books.google.com/books/content?id=3Q2focAO09AC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '424', 'accepted', 'Margaret Wise Brown; Clement Hurd', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 16 FROM public.book WHERE isbn13 = '9780061125935' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c6e9542d-5bee-5fc0-8b9c-9dc2045fb1f3', '9780061127762', 'Charlotte''s Web Signature Edition', 'oi9BPAAACAAJ', 'This is the story of a little girl named Fern who loved a little pig named Wilbur—and of Wilbur''s dear friend Charlotte, a beautiful large grey spider who lived with Wilbur in the barn. With the help of Templeton, the rat who never did anything for anybody unless there was something in it for him, and with a wonderfully clever plan of her own, Charlotte saved the life of Wilbur, who by this time had grown up to be quite some pig. How all of this comes about is Mr. White''s story. It is a story of the magic of childhood on the farm. It is also a story of friendship, loyalty, and truth and shows readers that friends come in all shapes and sizes. The beloved story of Charlotte the spider, Wilbur the pig, and Fern, the little girl who understood their language, will continue to delight readers both young and old everywhere for generations to come.', 'en', 2006, 224, 'http://books.google.com/books/content?id=oi9BPAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '425', 'accepted', 'E. B. White', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 12 FROM public.book WHERE isbn13 = '9780061127762' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('177c7138-8679-5346-9651-7ed64664211c', '9780061127915', 'By Myself and Then Some', 'nHXXmAEACAAJ', 'The epitome of grace, independence, and wit, Lauren Bacall continues to project an audacious spirit and pursue on-screen excellence. The product of an extraordinary mother and a loving extended family, she produced, with Humphrey Bogart, some of the most electric and memorable scenes in movie history. After tragically losing Bogart, she returned to New York and a brilliant career in the theatre. A two-time Tony winner, she married and later divorced her second love, Jason Robards, and never lost sight of the strength that made her a star. Now, thirty years after the publication of her original National Book Award–winning memoir, Bacall has added new material to her inspiring history. In her own frank and beautiful words, one of our most enduring actresses reveals the remarkable true story of a lifetime so rich with incident and achievement that Hollywood itself would be unable to adequately reproduce it.', 'en', 2006, 512, 'http://books.google.com/books/content?id=nHXXmAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
