INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('989e0a1a-b46f-523b-a13a-0106a88f9aef', '9780061131523', 'The White Masai', 'uatyAAAAMAAJ', 'A former European entrepreneur recounts how she fell in love with Lketinga, a Masai warrior, while vacationing in Kenya and subsequently uprooted her life to move to the isolated bush country of Africa, where they worked to build a relationship in spite of difficult language and cultural barriers. 30,000 first printing.', 'en', 2006, 320, 'http://books.google.com/books/content?id=uatyAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
