INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b2ce0db2-591b-5384-8bdf-5d00ec45ca11', '9780061136900', 'The Crusader', 'iWR3AAAAMAAJ', 'Based on extraordinary research: a major reassessment of Ronald Reagan''s lifelong crusade to dismantle the Soviet Empire–including shocking revelations about the liberal American politician who tried to collude with USSR to counter Reagan''s efforts Paul Kengor''s God and Ronald Reagan made presidential historian Paul Kengor''s name as one of the premier chroniclers of the life and career of the 40th president. Now, with The Crusader, Kengor returns with the one book about Reagan that has not been written: The story of his lifelong crusade against communism, and of his dogged–and ultimately triumphant–effort to overthrow the Soviet Union. Drawing upon reams of newly declassified presidential papers, as well as untapped Soviet media archives and new interviews with key players, Kengor traces Reagan''s efforts to target the Soviet Union from his days as governor of California to the fall of the Berlin Wall and the collapse of what he famously dubbed the "Evil Empire." The result is a major revision and enhancement of what historians are only beginning to realize: That Reagan not only wished for the collapse of communism, but had a deep and specific understanding of what it would take––and effected dozens of policy shifts that brought the USSR to its heels within a decade of his presidency. The Crusader makes use of key sources from behind the Iron Curtain, including one key memo that implicates a major American liberal politician–still in office today–in a scheme to enlist Soviet premier Yuri Andropov to help defeat Reagan''s 1984 reelection bid. Such new finds make The Crusader not just a work of extraordinary history, but a work of explosive revelation that will be debated as hotly in 2006 as Reagan''s policies were in the 1980s.', 'en', 2006, 432, 'http://books.google.com/books/content?id=iWR3AAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '431', 'accepted', 'Paul Kengor', 'Political Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 6 FROM public.book WHERE isbn13 = '9780061136900' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('aa1d87a0-6fa5-57eb-8e74-2a772f7e148c', '9780061137037', 'Spider''s House', '3_jMWuT2OGEC', 'Set in Fez, Morocco, during that country''s 1954 nationalist uprising, The Spider''s House is perhaps Paul Bowles''s most beautifully subtle novel, richly descriptive of its setting and uncompromising in its characterizations. Exploring once again the dilemma of the outsider in an alien society, and the gap in understanding between cultures—recurrent themes of Paul Bowles''s writings—The Spider''s House is dramatic, brutally honest, and shockingly relevant to today''s political situation in the Middle East and elsewhere.', 'en', 2006, 432, 'http://books.google.com/books/content?id=3_jMWuT2OGEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
