INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2dd4493d-5367-5c7f-af1f-3083673c4fea', '9780061137365', 'Days', '38Pt8xMOTqsC', 'Between 1987 and 1989, Paul Bowles, at the suggestion of a friend, kept a journal to record the daily events of his life. What emerges is not only just a record of the meals, conversations, and health concerns of the author of The Sheltering Sky but also a fascinating look at an artist at work in a new medium. Characterized by a refreshing informality, clear-sightedness, and passages of exquisite prose, these pages record with equal fascination the behavior of an itinerant spider, a brutal episode of violence in a Tangier marketplace, and the pageantry and excess of Malcolm Forbes''s seventieth birthday party. In Days, a master observer of the foreign and obscure turns his attentions toward his own daily existence, giving us a startlingly candid portrait of his life in late twentieth-century Tangier.', 'en', 2006, 128, 'http://books.google.com/books/content?id=38Pt8xMOTqsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
