INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7fc2af6a-bdd8-56e5-a90e-0cdb391d2241', '9780061137457', 'Howl', 't-wfAQAAIAAJ', 'A special anniversary edition of the first publication of the seminal poetic work describes the background of Ginsberg''s famous poem, and discusses literary allusions, and techniques of composition used in creating the controversial work. Reprint.', 'en', 2006, 208, 'http://books.google.com/books/content?id=t-wfAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
