INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b10421a1-f299-5025-9d16-c93abeb3a916', '9780061139635', 'Points in Time', 't4EukRRN6z8C', 'In this intense and brilliant book Bowles focuses on Morocco, condensing expreience, emotion, and the whole history of a people into a series of short, insightful vignettes. He distills for us the very essence of Moroccan culture. With extraordinary immediacy, he takes the reader on a journey through the Moroccan centuries, pausing at points along the way to create resonant images of the country, it''s landscapes, and the beliefs and characteristics of its inhabitants.', 'en', 2006, 96, 'http://books.google.com/books/content?id=t4EukRRN6z8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '436', 'accepted', 'Paul Bowles', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 20 FROM public.book WHERE isbn13 = '9780061139635' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cd7661ce-43b3-573d-bbf2-0dc4711b58ef', '9780061140501', 'At the Edge', 'TOsOjwEACAAJ', 'Claire, Tempest, and Leona: triplets blessed—or cursed—each with a special extra sense that they would deny, given the chance . . . Claire, the youngest, finds solitude and escape in rural Montana. The descendant of an ancient Celtic seer, she struggles to conceal her unsettling power to sense what others feel—the good and the evil, the pain and the joy. When her peace is shattered by her new neighbor, Neil Olafson, Claire''s shielded emotions start simmering. He''s the opposite of everything she''s ever wanted, a man who ignites her latent sensuality. And while her eerie powers have frightened others away, Neil isn''t running. And when Claire comes face-to-face with danger, he becomes her protector—as well as her lover. Now, Claire and Neil must confront the past and save the life of a young innocent. But there is a killer lurking in the background who wants them both dead before they can unravel his dirty secrets. And he''s been very busy . . .', 'en', 2007, 384, 'http://books.google.com/books/content?id=TOsOjwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
