INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5d237532-5ddc-568d-a3d3-c0633c64b4f0', '9780061140532', 'Remind Me Again Why I Need A Man', 'EvzyzYHTliIC', 'Despairing of finding an ideal husband in spite of her attractive looks and intelligence, television producer Amelia Lockwood endures a humiliating year of night classes while reconnecting with a handsome former flame who broke her heart. 35,000 first printing.', 'en', 2007, 384, 'http://books.google.com/books/content?id=EvzyzYHTliIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
