INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('27633dd8-2e2c-507f-b226-10e4de33eaed', '9780061144899', 'When the Heart Waits', 'JlP91ei7BGQC', 'From the Bestselling Author of The Secret Life of Bees, an Inspiring Autobiographical Account of Personal Pain, Spiritual Awakening, and Divine Grace Blending her own experiences with an intimate grasp of spirituality, Sue Monk Kidd relates the passionate and moving tale of her spiritual crisis, when life seemed to have lost meaning and her longing for a hasty escape from the pain yielded to a discipline of "active waiting." This PLUS edition includes a reader''s guide.', 'en', 2006, 240, 'http://books.google.com/books/content?id=JlP91ei7BGQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
