INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('99844c1f-9fb2-520c-a28e-db2707e9b0eb', '9780061145391', 'The Gabriel Hounds', 'JIn5AZLEPGsC', 'It''s all a grand adventure when Christy Mansel unexpectedly runs into her cousin Charles in Damascus. And being young, rich, impetuous, and used to doing whatever they please, they decide to barge in uninvited on their eccentric Great-Aunt Harriet—despite a long-standing family rule strictly forbidding unannounced visits. A strange new world awaits Charles and Christy beyond the gates of Dar Ibrahim—"Lady Harriet''s" ancient, crumbling palace in High Lebanon—where a physician is always in residence and a handful of Arab servants attends to the odd old woman''s every need. But there is a very good—very sinister—reason why guests are not welcome at Dar Ibrahim. And the young cousins are about to discover that, as difficult as it is to break into the dark, imposing edifice, it may prove even harder still to escape . . .', 'en', 2006, 322, 'http://books.google.com/books/content?id=JIn5AZLEPGsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
