INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b070e0f0-62fe-52d3-aefb-5a2ce6f6a98d', '9780061196676', 'Smithsonian Intimate Guide to Human Origins', 'xufuSNGg_vMC', 'From the savannas of Africa to modern-day labs for biomechanical analysis and molecular genetics, Smithsonian Intimate Guide to Human Origins reveals how anthropologists are furiously redrawing the human family tree. Their discoveries have spawned a host of new questions: Should chimpanzees be included as a human species? Was it the physical difficulty of human childbirth that encouraged the development of social groups in early human species? Did humans and Neanderthals interbreed? Why did humans supplant Neanderthals in the end? In answering such questions, Smithsonian Intimate Guide to Human Origins sheds new light on one of the most important questions of all: What makes us human?', 'en', 2007, 176, 'http://books.google.com/books/content?id=xufuSNGg_vMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
