INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2fcba609-4978-5541-b279-21c45aff3e6c', '9780061196683', 'My secret', 'JZIYAAAAYAAJ', 'A collection of artfully decorated postcards with secrets anonymously written on them by people from all over the world and sent to the founder of PostSecret, a community art project that evolved into a website.', 'en', 2006, 144, 'http://books.google.com/books/content?id=JZIYAAAAYAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
