INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('03aba463-12e8-5847-97c9-31d1012012ee', '9780061198755', 'The Secret Lives of Men and Women', 'Q9q774PMUrwC', 'Postsecret.com founder Frank Warren is back with an irresistible addition to his bestselling PostSecret series. For The Secret Lives of Men and Women, Warren has selected a never-before-seen collection of postcards bearing the explosive confessions and captivating revelations of men and women everywhere. Created using photographs, collages, illustrations, and more, the handmade cards offer a compelling dialogue on some of today’s most provocative topics—from marriage and infidelity, to parenting, office politics, repressed fantasies, and even abortion—daring us to consider how well we really know our friends, family, even ourselves.', 'en', 2007, 144, 'http://books.google.com/books/content?id=Q9q774PMUrwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
