INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1861da1d-0c03-545d-805b-cefb0f8b5c77', '9780061312113', 'The Blue and Brown Books', 'ffiZugEACAAJ', 'These works, as the sub-title makes clear, are unfinished sketches for Philosophical Investigations, possibly the most important and influential philosophical work of modern times. The ''Blue Book'' is a set of notes dictated to Witgenstein''s Cambridge students in 1933-1934: the ''Brown Book'' was a draft for what eventually became the growth of the first part of Philosophical Investigations. This book reveals the germination and growth of the ideas which found their final expression in Witgenstein''s later work. It is indispensable therefore to students of Witgenstein''s thought and to all those who wish to study at first-hand the mental processes of a thinker who fundamentally changed the course of modern philosophy.', 'en', 1965, 208, 'http://books.google.com/books/content?id=ffiZugEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
