INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fd9f9ae2-82e6-5ab9-8b8f-a89e9546cb31', '9780062511119', 'A Manual for Living', 'cofP7FbBfAgC', 'The essence of perennial Stoic wisdom in aphorisms of stunning insight and simplicity. The West''s first and best little instruction book offers thoroughly contemporary and pragmatic reflections on how best to live with serenity and joy.', 'en', 1994, 96, 'http://books.google.com/books/content?id=cofP7FbBfAgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
