INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fa1c3495-357c-5dee-aaa2-5141552e5ff1', '9780064402453', 'Racso and the Rats of NIMH', 'MgoNv0g8pskC', '‘Racso, a brash and boastful little rodent, is making his way to Thorn Valley, determined to learn how to read and write and become a hero. His bragging and lies get him off to a bad start, but a crisis gives him the opportunity to prove his mettle. A worthy successor [to Mrs. Frisby and the Rats of NIMH, a Newbery Medal winner by the author''s father].'' ''BL. 1986 Children''s Editors'' Choices (BL) Children''s Choices for 1987 (IRA/CBC) Notable 1986 Childrens'' Trade Books in Social Studies (NCSS/CBC) 1986 Children''s Books (NY Public Library) Best Science Fiction/Fantasy 1986 (VOYA)', 'en', 1988, 288, 'http://books.google.com/books/content?id=MgoNv0g8pskC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
