INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9e5fa42c-95f3-57fc-979a-aa6a7154a7f6', '9780064403368', 'Child of the Owl', 'IvP2bGRcViQC', 'Twelve-year-old Casey is waiting for the day that Barney, her father, hits it big -- ''cause when that horse comes in, he tells her, it''s the penthouse suite. But then hr ends up in the hospital, and Casey is sent to Chinatown to live with her grandmother, Paw-Paw. Now the waiting seems longer than ever. Casey feels lost in Chinatown. She''s not prepared for the Chinese school, the noisy crowds, missing her father. But Paw-Paw tells her about the mother Casey never knew, and about her family''s owl charm and her true Chinese name. And Casey at last begins to understand that this -- Paw-Paw''s Chinatown home, her parents'' home -- is her home,too.', 'en', 1990, 288, 'http://books.google.com/books/content?id=IvP2bGRcViQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '479', 'accepted', 'Laurence Yep', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 7 FROM public.book WHERE isbn13 = '9780064403368' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7ebb9dcf-35b3-5954-916d-4c0a7aa996b9', '9780064403870', 'R-T, Margaret, and the Rats of NIMH', 'WTHHHA80Q_oC', 'When Margaret and her younger brother, Artie, get lost in the woods on a family camping trip, they are rescued by rats -- the superintelligent rats of NIMH. Taken into the rat''s community, the children are safe for the time being. But winter is coming. Margaret and Artie have to get back home. And when they do, they must protect the rats who have helped them. Everything depends on their silence... but it''s hard to evade questions forever. Children''s Choices for 1991 (IRA/CBC)VOYA''s Best Science Fiction, Fantasy, and Horror 1990Parenting Honorable Mention, Reading Magic Award', 'en', 1991, 272, 'http://books.google.com/books/content?id=WTHHHA80Q_oC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
