INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b22439ab-5b88-57ef-9ae1-feeb20fa0536', '9780064404419', 'The Rainbow People', '5AHwqNDuiCwC', '"Culled from 69 stories collected in a [1930s] WPA project, [these 20] tales are organized into sections with themes like ''Tricksters'' or ''Virtues and Vices,'' each with a thoughtful introduction placing the individual stories in the context of feelings and background of the original tellers. Yep''s telling is vigorous, often poetic, imbued with earthy humor and realism touched with fatalism. A handsomely designed collection." —K. Notable Children''s Books of 1989 (ALA) The USA Through Children''s Books 1990 (ALA) 1989 Boston Globe–Horn Book Award for Nonfiction 1990 Fanfare Honor List (The Horn Book) 1989 Children''s Editors'' Choices (BL) Notable 1989 Children''s Trade Books in Social Studies (NCSS/CBC) Children''s Books of 1989 (Library of Congress) 1989 Children''s Books (NY Public Library) "The Best Books" 1989 (Parents Magazine)', 'en', 1992, 208, 'http://books.google.com/books/content?id=5AHwqNDuiCwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
