INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('051c1e0b-9f98-5599-8aa9-540b3df88495', '9780064405447', 'Betsy''s Wedding', 'aT6r0nSbMG8C', 'Betsy marries Joe, her high school sweetheart, and they have all the problems of young newlyweds, in a sixtieth anniversary edition of a beloved story which includes a new biographical section and a new forward. Original.', 'en', 1996, 260, 'http://books.google.com/books/content?id=aT6r0nSbMG8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
