INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f3bbb0d3-07a2-55b2-911a-046a66328480', '9780064405713', 'Crazy Lady!', 'aJwh7yxnoMoC', 'Increasingly alienated from his widowed father, Vernon joins his friends in ridiculing the neighborhood outcasts''Maxine, an alcoholic prone to outrageous behavior, and Ronald, her retarded son. But when a social service agency tries to put Ronald into a special home, Vernon fights against the move. 1994 Newbery Honor Book Notable Children''s Books of 1994 (ALA) 1994 Best Books for Young Adults (ALA) 1994 Young Adult Editors'' Choices (BL) 1994 Books for the Teen Age (NY Public Library) Young Adult Choices for 1995 (IRA)', 'en', 1995, 192, 'http://books.google.com/books/content?id=aJwh7yxnoMoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
