INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e4464162-3ceb-51b8-8c6e-8f69017fa406', '9780064406307', 'The Midwife''s Apprentice (rpkg)', 'Bhm76u8ZcHMC', '''Like Cushman''s 1995 Newbery Honor Book, Catherine, Called Birdy, this novel is about a strong young woman in medieval England who finds her own way home. This is a world, like Chaucer''s, that''s . . . dangerous, primitive and raucous. From the first page you''re caught by the spirit of the homeless, nameless waif, somewhere around 12 years old. She gets the village midwife to take her in, befriends a cat, names herself Alyce, and learns something about delivering babies. When she fails, she runs away, but she picks herself up again and returns to work and independence.'' --ALA Booklist (starred review). ''. . .A fascinating view of a far distant time.'' -- The Horn Book (starred review)', 'en', 1996, 128, 'http://books.google.com/books/content?id=Bhm76u8ZcHMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
