INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('60883933-2e17-59cf-8ef1-7269c3883578', '9780064407144', 'Down to the Bonny Glen', 'nO5OGr8anJ8C', 'With the arrival of her new governess, Miss Crow, Martha begins to see that her work is quite important and soon realizes she could learn a great deal from her if she only took the time to get to know her. Simultaneous.', 'en', 2001, 321, 'http://books.google.com/books/content?id=nO5OGr8anJ8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
