INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e7f4f944-c9be-5a1f-8987-ab3a046d35b6', '9780064408585', 'Emily of Deep Valley', '8uT9_Io3bYwC', 'After graduating high school, Emily Webster longs to go off to university with everyone else, but she must stay at home and take care of her grandfather, a Civil War veteran, and it is at home that she discovers many new adventures. Reprint.', 'en', 2000, 304, 'http://books.google.com/books/content?id=8uT9_Io3bYwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
