INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('12d5cd73-8c2b-56f9-addd-d8c80975111e', '9780064420815', 'Christmas Stories', 'qJxFQDe9AP4C', 'Gentle adaptations of Laura Ingalls Wilder''s celebrated Little House stories have been gathered together here in two new titles in our Little House Chapter Book series. In Christmas Stories, join Laura and her family for some pioneer Christmas celebrations. Christmas on the frontier means visits from friends, good things to eat, and presents! For Laura, every Christmas in the little house is better than the one before. Laura and her friends share wonderful adventures in Little House Friends. From racing ponies with cousin Lena to bobsled rides with Cap Garland and the gang, Laura loves spending time with her friends. Even mean old Nellie Oleson can''t spoil Laura''s fun!With simple text, entertaining stories, and Renee Graef''s beautiful black-and-white artwork, Little House Chapter Books are the perfect way to introduce beginning chapter-book readers to the world of Little House.', 'en', 1998, 80, 'http://books.google.com/books/content?id=qJxFQDe9AP4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
