INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2cf89d28-2590-52a8-8041-041eae845b05', '9780064433730', 'Winter Days in the Big Woods', 'H-igY69LTxcC', 'Laura helps Ma and Pa make the little log cabin snug and cozy for the snowy days ahead. 1994 "Pick of the Lists" (ABA)', 'en', 1995, 32, 'http://books.google.com/books/content?id=H-igY69LTxcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '504', 'accepted', 'Laura Ingalls Wilder', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 1 FROM public.book WHERE isbn13 = '9780064433730' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b05ab62b-75c9-562c-a4c2-edbbb85773db', '9780064434874', 'Christmas in the Big Woods', 'FT1YpUwRYykC', 'Long ago, a little girl named Laura Ingalls lived in a little house in the Big Woods of Wisconsin with her Pa, her Ma, her sisters, Mary and Carrie, and their good old bulldog, Jack. Winter was just around the corner, and Laura worked hard to help make the little house ready for the cold days ahead. Soon there was frost on the windows and snow on the ground, but Laura and her folks were warm and cozy in their snug little house in the Big Woods. Laura Ingalls Wilder''s Little House books have been cherished by generations of readers. Now for the first time, the youngest readers can share her adventures in these very special picture books adapted from Laura Ingalls Wilder''s beloved storybooks. Renée Graef''s warm paintings, inspired by Garth Williams'' classic Little House illustrations, bring Laura and her family lovingly to life.', 'en', 1997, 32, 'http://books.google.com/books/content?id=FT1YpUwRYykC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '505', 'accepted', 'Laura Ingalls Wilder', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 13 FROM public.book WHERE isbn13 = '9780064434874' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b4556d4e-e9ce-5cce-ba68-fde7b9df5bb3', '9780064434942', 'A Little House Birthday', 'fyfDRpzVoM0C', 'Join the Ingalls family as they celebrate little Laura’s fifth birthday in the Big Woods of Wisconsin. There are special presents from everyone, and that night Laura falls asleep to the merry music of Pa’s fiddle. Renée Graef’s enchanting full-color illustrations, inspired by Garth Williams’s classic artwork, bring Laura and her family lovingly to life in our tenth My First Little House Book, adapted from Laura Ingalls Wilder’s beloved storybooks. It’s a Little House birthday to remember!', 'en', 1998, 40, 'http://books.google.com/books/content?id=fyfDRpzVoM0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
