INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('56cc158a-31d6-5075-af3c-7fdac4d456c0', '9780064440578', 'Grizzwold', 'Sy_X4g1pvzcC', 'Grizzwold the lovable bear is having a tough time finding somewhere to live. He''s too big for most places, and too clumsy for others. He''s not even any good as a live bearskin rug! Will Grizzwold ever find a home that''s just right?', 'en', 1984, 64, 'http://books.google.com/books/content?id=Sy_X4g1pvzcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
