INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b5f8a7ce-dc7c-5cff-b614-30597e920676', '9780064472777', 'All-American Girl', 'Fktx5yUMHpMC', 'Top Ten Reasons Samantha Madison is in Deep Trouble 10. Her big sister is the most popular girl in school 9. Her little sister is a certified genius 8. She''s in love with her big sister''s boyfriend 7. She got caught selling celebrity portraits in school 6. And now she''s being forced to take art classes 5. She''s just saved the president of the United Statesfrom an assassination attempt 4. So the whole world thinks she is a hero 3. Even though Sam knows she is far, far from being a hero 2. And now she''s been appointed teen ambassador to the UNAnd the number-one reason Sam''s life is over?1. The president''s son just might be in love with her', 'en', 2003, 398, 'http://books.google.com/books/content?id=Fktx5yUMHpMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
