INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('466fec5b-73d6-55d1-9dd8-5bdd5aad3463', '9780064473552', 'Hexwood', 'vDTJwAEACAAJ', 'Strange things happen at Hexwood Farm. From her window, Ann Stavely watches person after person disappear through the farm''s gate -- and never come out again. Later, in the woods nearby, she meets a tormented sorcerer, who seems to have arisen from a centuries-long sleep. But Ann knows she saw him enter the farm just that morning. Meanwhile, time keeps shifting in the woods, where a small boy -- or perhaps a teenager -- has encountered a robot and a dragon. Long before the end of their adventure, the strangeness of Hexwood has spread from Earth right out to the center of the galaxy.', 'en', 2002, 464, 'http://books.google.com/books/content?id=vDTJwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '516', 'accepted', 'Diana Wynne Jones', 'Young Adult Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 2 FROM public.book WHERE isbn13 = '9780064473552' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('261763f8-e721-5940-9f6f-574ccf0de947', '9780066236179', 'A Light in the Attic Book and CD', 'FJfQsgEACAAJ', 'Last night while I lay thinking here Some Whatifs crawled inside my ear And pranced and partied all night long And sang their same old Whatif song: Whatif I flunk that test? Whatif green hair grows on my chest? Whatif nobody likes me? Whatif a bolt of lightning strikes me?... To celebrate its 20th anniversary, Shel Silverstein''s A Light in the Attic is now available in a special edition containing the classic hardcover book and a CD of highlights from his Grammy Award-winning album. Here in the attic of Shel Silverstein you will find Backward Bill, Sour Face Ann, the Meehoo with an Exactlywatt, and the Polar Bear in the Frigidaire. You will talk with Broiled Face, and find out what happens when Somebody steals your knees, you get caught by the Quick-Digesting Gink, a Mountain snores, and They Put a Brassiere on the Camel. From the creator of the beloved poetry collections Where the Sidewalk Ends and Falling Up, here is another wondrous book of poems and drawings.', 'en', 2001, 176, 'http://books.google.com/books/content?id=FJfQsgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '517', 'accepted', 'Shel Silverstein', 'Juvenile Nonfiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 19 FROM public.book WHERE isbn13 = '9780066236179' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9980bbd7-9282-5f2b-8b04-ebfd578c594f', '9780066238500', 'The Chronicles of Narnia (adult)', '3VGkK_F9thYC', 'Journeys to the end of the world, fantastic creatures, and epic battles between good and evil -- what more could any reader ask for in one book? The book that has it all is The Lion, the Witch and the Wardrobe, written in 1949 by Clive Staples Lewis. But Lewis did not stop there. Six more books followed, and together they became known as The Chronicles of Narnia. For the past fifty years, The Chronicles of Narnia have transcended the fantasy genre to become part of the canon of classic literature. Each of the seven books is a masterpiece, drawing the reader into a land where magic meets reality, and the result is a fictional world whose scope has fascinated generations. This edition presents all seven books -- unabridged -- in one impressive volume. The books are presented here according to Lewis'' preferred order, each chapter graced with an illustration by the original artist, Pauline Baynes. Deceptively simple and direct, The Chronicles of Narnia continue to captivate fans with adventures, characters, and truths that speak to readers of all ages, even fifty years after they were first published.', 'en', 2001, 767, 'http://books.google.com/books/content?id=3VGkK_F9thYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '518', 'accepted', 'C. S. Lewis', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 17 FROM public.book WHERE isbn13 = '9780066238500' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('91a89269-b23e-5cbd-adf5-9c759aae41c8', '9780066620107', 'What Would Machiavelli Do?', 'W9jVlwEACAAJ', 'What Would Machiavelli Do? He would feast on other people''s discord He wouldn''t exactly seek the company of ass-kissers and bimbos, but he wouldn''t reject them out of hand either He would realize that loving yourself means never having to say you''re sorry He would kill people, but only if he could feel good about himself afterward He would establish and maintain a psychotic level of control He would use other people''s opinions to sell his book!', 'en', 2002, 176, 'http://books.google.com/books/content?id=W9jVlwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '519', 'accepted', 'Stanley Bing', 'Humor', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 2 FROM public.book WHERE isbn13 = '9780066620107' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('34b3da95-282f-5905-9c09-e30c2cbbce25', '9780067575208', 'The Sense of Wonder', 'Zee5SAOqO2UC', 'First published more than three decades ago, this reissue of Rachel Carson''s award-winning classic brings her unique vision to a new generation of readers. Stunning new photographs by Nick Kelsh beautifully complement Carson''s intimate account of adventures with her young nephew, Roger, as they enjoy walks along the rocky coast of Maine and through dense forests and open fields, observing wildlife, strange plants, moonlight and storm clouds, and listening to the "living music" of insects in the underbrush. "If a child is to keep alive his inborn sense of wonder." Writes Carson, "he needs the companionship of at least one adult who can share it, rediscovering with him the joy, excitement and mystery of the world we live in." The Sense of Wonder is a refreshing antidote to indifference and a guide to capturing the simple power of discovery that Carson views as essential to life. In her insightful new introduction, Linda Lear remembers Rachel Carson''s groundbreaking achievements in the context of the legendary environmentalist''s personal commitment to introducing young and old to the miracles of nature. Kelsh''s lush photographs inspire sensual, tactile reactions: masses of leaves floating in a puddle are just waiting to be scooped up and examined more closely. An image of a narrow path through the trees evokes the earthy scent of the woods after a summer rain. Close-ups of mosses and miniature lichen fantasy-lands will spark innocent''as well as more jaded''imaginations. Like a curious child studying things underfoot and within reach, Kelsh''s camera is drawn to patterns in nature that too often elude hurried adults''a stand of beech trees in the springtime, patches of melting snow and the ripples from a pebble tossed into a slow-moving stream. The Sense of Wonder is a timeless volume that will be passed on from children to grandchildren, as treasured as the memory of an early-morning walk when the song of a whippoorwill was heard as if for the first time.', 'en', 1998, 112, 'http://books.google.com/books/content?id=Zee5SAOqO2UC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '520', 'accepted', 'Rachel Carson', 'Nature', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 20 FROM public.book WHERE isbn13 = '9780067575208' ON CONFLICT DO NOTHING;
