INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('29f88e8b-4e66-58cc-bf0c-6cacebc8e6ed', '9780071401944', 'Crucial Conversations', 'PibJN5XVQRkC', 'The New York Times Bestseller! Learn how to keep your cool and get the results you want when emotions flare. When stakes are high, opinions vary, and emotions run strong, you have three choices: Avoid a crucial conversation and suffer the consequences; handle the conversation badly and suffer the consequences; or read Crucial Conversations and discover how to communicate best when it matters most. Crucial Conversations gives you the tools you need to step up to life''s most difficult and important conversations, say what''s on your mind, and achieve the positive resolutions you want. You''ll learn how to: Prepare for high-impact situations with a six-minute mastery technique Make it safe to talk about almost anything Be persuasive, not abrasive Keep listening when others blow up or clam up Turn crucial conversations into the action and results you want Whether they take place at work or at home, with your neighbors or your spouse, crucial conversations can have a profound impact on your career, your happiness, and your future. With the skills you learn in this book, you''ll never have to worry about the outcome of a crucial conversation again.', 'en', 2002, 240, 'http://books.google.com/books/content?id=PibJN5XVQRkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '523', 'accepted', 'Kerry Patterson; Joseph Grenny; Ron McMillan; Al Switzler', 'Business & Economics', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 12 FROM public.book WHERE isbn13 = '9780071401944' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('487e2ca3-7d60-5108-a7cd-bc691766be5b', '9780071418584', 'How to Talk to Anyone : 92 Little Tricks for Big Success in Relationships', 'LQt6mAEACAAJ', '"You''ll not only break the ice, you''ll melt it away with your new skills." -- Larry King "The lost art of verbal communication may be revitalized by Leil Lowndes." -- Harvey McKay, author of “How to Swim with the Sharks Without Being Eaten Alive” What is that magic quality makes some people instantly loved and respected? Everyone wants to be their friend (or, if single, their lover!) In business, they rise swiftly to the top of the corporate ladder. What is their "Midas touch?" What it boils down to is a more skillful way of dealing with people. The author has spent her career teaching people how to communicate for success. In her book How to Talk to Anyone (Contemporary Books, October 2003) Lowndes offers 92 easy and effective sure-fire success techniques-- she takes the reader from first meeting all the way up to sophisticated techniques used by the big winners in life. In this information-packed book you’ll find: 9 ways to make a dynamite first impression 14 ways to master small talk, "big talk," and body language 14 ways to walk and talk like a VIP or celebrity 6 ways to sound like an insider in any crowd 7 ways to establish deep subliminal rapport with anyone 9 ways to feed someone''s ego (and know when NOT to!) 11 ways to make your phone a powerful communications tool 15 ways to work a party like a politician works a room 7 ways to talk with tigers and not get eaten alive In her trademark entertaining and straight-shooting style, Leil gives the techniques catchy names so you''ll remember them when you really need them, including: "Rubberneck the Room," "Be a Copyclass," "Come Hither Hands," “Bare Their Hot Button,” “The Great Scorecard in the Sky," and "Play the Tombstone Game,” for big success in your social life, romance, and business. How to Talk to Anyone, which is an update of her popular book, Talking the Winner''s Way (see the 5-star reviews of the latter) is based on solid research about techniques that work! By the way, don''t confuse How to Talk to Anyone with one of Leil''s previous books, How to Talk to Anybody About Anything. This one is completely different!', 'en', 2003, 345, 'http://books.google.com/books/content?id=LQt6mAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '524', 'accepted', 'Leil Lowndes', 'Family & Relationships', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 14 FROM public.book WHERE isbn13 = '9780071418584' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c9708f53-01af-54e4-a77f-39fdfe264cf7', '9780071428484', 'Easy French Reader, Second Edition', 'TY4AAAAACAAJ', 'The fun and easy way to quickly enhance your French reading skills Easy French Reader is based on the premise that the best way to learn a language is to start reading it, immediately. Suitable for raw beginners to intermediate-level language learners, this popular title features engaging readings of progressive difficulty that allow you to rapidly build your comprehension. Find out what unfamiliar words and phrases mean with the book''s helpful glossary Discover the nuances of French language and culture as well as the country''s history through engaging texts Get a feel for authentic French society with readings from contemporary literature', 'en', 2003, 228, 'http://books.google.com/books/content?id=TY4AAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
