INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('54cb74d2-772c-5e97-aa1d-3d201a988a7d', '9780071451383', 'Practice Makes Perfect: Italian Verb Tenses', 'Mbix2qU7bwcC', 'Practice makes perfect Italian verb tenses goes beyond other verb books to coach you in when and why verb tenses are used. In addition to an array of fully conjugated verbs, you will find clear and concise explanations that pinpoint why specific tenses work in given situations as well as plenty of engaging examples and numerous skill-building exercises. This is the ideal reference/workbook for beginning to intermediate Italian language learners whose goal is to learn to speak and write Italian with fluency.', 'en', 2005, 252, 'http://books.google.com/books/content?id=Mbix2qU7bwcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
