INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d21e4b8e-912a-5675-8adc-405dec27c482', '9780099284482', 'A Star Called Henry', 'nLiacLHmhOsC', '"Born in the Dublin slums of 1901, his father a one-legged whorehouse bouncer and settler of scores, Henry Smart has to grow up fast. By the time he can walk he''s out robbing and begging, often cold and always hungry, but a prince of the streets. By Easter Monday, 1916, he''s fourteen years old and already six-foot-two, a soldier in the Irish Citizen Army. A year later he''s ready to die for Ireland again, a rebel, a Fenian and a killer. With his father''s wooden leg as his weapon, Henry becomes a Republican legend - one of Michael Collins'' boys, a cop killer, an assassin on a stolen bike."', 'en', 2000, 342, 'http://books.google.com/books/content?id=nLiacLHmhOsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '548', 'accepted', 'Roddy Doyle', 'Dublin (Ireland)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 3 FROM public.book WHERE isbn13 = '9780099284482' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a376753c-1cde-5e7f-85a2-61e16c8c96f0', '9780099285557', 'Set this House on Fire', 'TDaEPwAACAAJ', 'The day after Peter Leverett met his old friend Mason Flagg in Italy, Mason was found dead. The hours leading up to his death were a nightmare for Peter - both in their violence and in their maddening unreality.The blaze of events which followed was, Peter soon realised, ignited by a conflict between two men- Mason Flagg himself and Cass Kinsolving, a tortured, self-destructive painter, a natural enemy and prey to the monstrous evil of Mason Flagg.Three events - murder, rape and suicide - explode in this relentless and passionate novel, almost overwhelming in its conception of the varieties of good and evil.', 'en', 2001, 567, 'http://books.google.com/books/content?id=TDaEPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '549', 'accepted', 'William Styron', 'Americans', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 10 FROM public.book WHERE isbn13 = '9780099285557' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('37e6cb2d-cdd8-59ca-9420-703f1954e7c8', '9780099285564', 'The Confessions of Nat Turner', 'zXaiQSlk7qoC', 'In 1831 Nat Turner awaits death in a Virginia jail cell. He is a slave, a preacher, and the leader of the only effective slave revolt in the history of ''that peculiar institution''. William Styron''s ambitious and stunningly accomplished novel is Turner''s confession, made to his jailers under the duress of his God. Encompasses the betrayals, cruelties and humiliations that made up slavery - and that still sear the collective psyches of both races.', 'en', 2004, 480, 'http://books.google.com/books/content?id=zXaiQSlk7qoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
