INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cf429cf0-faac-5d18-a001-e170ee50492a', '9780099285823', 'Experience', 'gGnR11zgMVgC', 'Perhaps the most gifted and innovative novelist of his generation. Martin Amis has been the object of obsessive media scrutiny for much of his career. In this much anticipated memoir, he writes with striking candour about his life and, in the process, giv', 'en', 2001, 401, 'http://books.google.com/books/content?id=gGnR11zgMVgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '551', 'accepted', 'Martin Amis', 'Amis, Kingsley', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 15 FROM public.book WHERE isbn13 = '9780099285823' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5f0a6106-9662-5b2c-a497-b54bc448d23f', '9780099297703', 'Hannibal', 'av8SBXdrG7YC', 'WORTH THE WAIT. . . Harris''s writing bears the hallmarks of honed perfection. . . this piece of literature is popular fiction only in the sense that it will sell. And sell. . . LOOK NO FURTHER FOR THE CHILLER OF THE YEAR'' Peter Millar, The times ''Insanely readable. . . No thriller writer is better attuned than Thomas Harris to the rhythms of suspense. No horror writer is more adept at making the stomach churn. . . COMPELLING. . . TRULY SHOCKING. . . A BRILLIANT BOOK'' Mail on Sunday ''It is a gut-churning, nail-biting, skin-crawling, often lyrical triumph - addictive on every level. . . The plot is a helluva plot. . . The denouement is as exciting as the rest. . . IF THERE''S A BETTER BOOK THIS YEAR, with truth, fantasy and a touch of erudition combined in prose which really does leap off the page, I''LL EAT MY HAT'' Francis Fyfield, Express. ''No panting fan. . . could have hope for more. . . HANNIBAL IS A GREAT POPULAR NOVEL AND A PLAUSIBLE CANDIDATE FOR THE PULITZER PRIZE'' Guardian', 'en', 2000, 564, 'http://books.google.com/books/content?id=av8SBXdrG7YC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
