INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('00fbd169-1e18-5522-befb-cada1d1b1837', '9780099339212', 'The First Forty-nine Stories', '61BQ5JD_NCEC', '"From Ernest Hemingway''s Preface- ''There are many kinds of stories in this book. I hope you will find some that you like- In going where you have to go, and doing what you have to do, and seeing what you have to see, you dull and blunt the instrument you write with. But I would rather have it bent and dulled and know I had to put it on the grindstone and hammer it into shape and put a whetstone to it, and know that I had something to write about, than to have it bright and shining, and nothing to say, or smooth and well-oiled in the closet, but unused.'' A collection of Hemingway''s first forty-nine short stories, featuring a brief introduction by the author and lesser known as well as familiar tales, including ''Up in Michigan'', ''Fifty Grand'', and ''The Light of the World'', and the Snows of Kilimanjaro, Winner Take Nothing''and Men Without Womencollections."', 'en', 1993, 467, 'http://books.google.com/books/content?id=61BQ5JD_NCEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '554', 'accepted', 'Ernest Hemingway', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 2 FROM public.book WHERE isbn13 = '9780099339212' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b0552ba5-ec83-5106-af46-173677348331', '9780099409960', 'The Phantom Menace', 'vd1pffZFhZ8C', 'A long time ago in a galaxy far, far away, an evil legacy long believed dead is stirring. Now the dark side of the Force threatens to overwhelm the light, and only an ancient Jedi prophecy stands between hope and doom for the entire galaxy. On the green, unspoiled world of Naboo, Jedi Master Qui-Gon Jinn and his apprentice, Obi-Wan Kenobi, arrive to protect the realm''s young queen as she seeks a diplomatic solution to end the siege of her planet by Trade Federation warships. At the same time, on desert-swept Tatooine, a slave boy named Anakin Skywalker, who possesses a strange ability for understanding the "rightness" of things, toils by day and dreams by night--of becoming a Jedi Knight and finding a way to win freedom for himself and his beloved mother. It will be the unexpected meeting of Jedi, Queen, and a gifted boy that will mark the start of a drama that will become legend.', 'en', 2000, 255, 'http://books.google.com/books/content?id=vd1pffZFhZ8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '556', 'accepted', 'Terry Brooks; George Lucas', 'Life on other planets', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 8 FROM public.book WHERE isbn13 = '9780099409960' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6f16cf25-8a04-50aa-b335-5e22f8c3e504', '9780099410355', 'Traitor', 'VbICOKLM6TIC', 'From the depths of catastrophe, a glimmer of hope. After the capture of Coruscant, the mighty heart of the New Republic, a stunned galaxy fears that nothing can stop the Yuuzhan Vong. Still, that crushing defeat produces one small miracle: Jacen Solo is alive. Yet he can scarcely imagine himself in stranger circumstances. The young Jedi Knight is in the care of Vergere, a fascinating creature of mystery and power, her intentions hard to fathom, her cruelties rarely concealed. But this master of inscrutable arts has much to teach the young Jedi...for she holds the key to a new way to experience the Force, to take it to another level - dangerous, dazzling, perhaps deadly. In the wrong hands, the tremendous energies of the Froce can be devastating. And there are others watching Jacen''s progress closely, waiting patiently for the moment when he will be ready for their own dire purposes. Now, all is in shadows. Yet whatever happens, whether Jacen''s newfound mastery unleashes light or darkness, he will never be the same Jedi again...', 'en', 2002, 320, 'http://books.google.com/books/content?id=VbICOKLM6TIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '557', 'accepted', 'Matthew Woodring Stover', 'Science fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 6 FROM public.book WHERE isbn13 = '9780099410355' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7327aeb6-45a4-51e7-bd57-e132a1e6724a', '9780099410386', 'Star by Star', 'lPtDoGRj6MIC', 'A must-read for every fan of Star Wars fiction and the New Jedi Order series in particular! It is a dark time for the New Republic. The Yuuzhan Vong, despite some recent losses, continue to advance into the Core, and continue their relentless hunt for the Jedi. Now, in a desperate act of courage, Anakin Solo leads a Jedi strike force into the heart of Yuuzhan Vong territory, where he hopes to destroy a major Vong anti-Jedi weapon. There, with his brother and sister at his side, he will come face to face with his destiny--as the New Republic, still fighting the good fight, will come face to face with theirs...', 'en', 2002, 605, 'http://books.google.com/books/content?id=lPtDoGRj6MIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '558', 'accepted', 'Troy Denning', 'Life on other planets', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 5 FROM public.book WHERE isbn13 = '9780099410386' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('57fd7c34-fed3-5b5a-b8f5-0703b398d2a4', '9780099421863', 'Fury', 'PlLF4HAejtgC', 'From one of the world''s truly great writers, Fury is a wickedly brilliant and pitch-black comedy about a middle-aged professor who finds himself in New York City in the summer of 2000. Not since the Bombay of Midnight''s Children have a time and place been so intensely and accurately captured in a novel. Fury opens on a New York living at breakneck speed in an age of unprecedented decadence. Malik Solanka, historian of ideas and dollmaker extraordinaire, steps out of his life one day, abandons his family without a word of explanation, and flees to New York. There is a fury within him, and he fears that he has become dangerous to those he loves. He arrives in New York at a time of unprecedented plenty, in the highest hour of America''s wealth and power, seeking to "erase" himself. But fury is all around him. Cab drivers spout invective. A serial killer is murdering women with a lump of concrete. The petty spats and bone-deep resentments of the metropolis engulf him. Meanwhile, his own thoughts, emotions and desires are also running wild. A young woman in a D''Angelo baseball cap is in store. Also another woman, with whom he will fall in love and drawn towards a different fury, whose roots lie of the far side of the world.', 'en', 2002, 272, 'http://books.google.com/books/content?id=PlLF4HAejtgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '559', 'accepted', 'Salman Rushdie', 'Anger', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 10 FROM public.book WHERE isbn13 = '9780099421863' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('67d32571-89ee-5658-adbb-6b3e1d3b33cd', '9780099422341', 'Yeats is Dead!', 'DrE3If94axcC', 'In aid of Amnesty International, this is a brilliant ''serial'' novel by fifteen of the very brightest talents in Irish writing. It begins with Roddy Doyle and ends with Frank McCourt. In between thirteen other Irish writers spin an increasingly elaborate tale ofmurder, mayhem and literary shenanigans in present-day Dublin.', 'en', 2002, 298, 'http://books.google.com/books/content?id=DrE3If94axcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
