INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7095b4b7-49b7-53ae-84a7-0af41c3ffb5c', '9780099422686', 'Choke', 'xkbpbiEC_oAC', '"Victor Mancini has devised a complicated scam to pay for his mother''s hospital care- pretend to be choking on a piece of food in a restaurant and the person who ''saves you'' will feel responsible for you for the rest of their lives. Multiply that a couple of hundred times and you generate a healthy flow of cheques, week in, week out. Victor also works at a theme park with a motley group of losers, cruises sex addiction groups for action, and visits his mother, whose Alzheimer''s disease now hides what may be the startling truth about his parentage."', 'en', 2002, 293, 'http://books.google.com/books/content?id=xkbpbiEC_oAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '561', 'accepted', 'Chuck Palahniuk', 'Alzheimer''s disease', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 9 FROM public.book WHERE isbn13 = '9780099422686' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('81423803-3dd9-5cfe-bc8b-7cd19d9c2c89', '9780099422693', 'The Dying Animal', 'prPo8epCoIkC', '''No matter how much you know, no matter how much you think, no matter how much you plot and you connive and you plan, you''re not superior to sex'' With these words America''s most unflaggingly energetic and morally serious novelist launches perhaps his fiercest book. The speaker is David Kepesh, white-haired and over sixty, an eminent TV culture critic and star lecturer at a New York college - as well as an articulate propagandist of the sexual revolution. For years he has made a practice of sleeping with adventurous female students while maintaining an aesthete''s critical distance. But now that distance has been annihilated. The agency of Kepesh''s undoing is Consuela Castillo, the decorous, humblingly beautiful twenty-four-year-old daughter of Cuban exiles. When he becomes involved with her, Kepesh finds himself dragged helplessly into the quagmire of sexual jealousy and loss. In chronicling the themes of eros and mortality, licence and repression, freedom and sacrifice. The Dying Animalis a burning coal of a book, filled with intellectual heat and not a little danger.', 'en', 2002, 156, 'http://books.google.com/books/content?id=prPo8epCoIkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '562', 'accepted', 'Philip Roth', 'College teachers', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 1 FROM public.book WHERE isbn13 = '9780099422693' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8e31871a-ac74-5665-adff-c8c78607c930', '9780099427865', 'Illusions', 'Z93wmaJAtyoC', 'In the cloud-washed airspace between the cornfields of Illinois and blue infinity, a man puts his faith in the propeller of his biplane. For disillusioned writer and itinerant barnstormer Richard Bach, belief is as real as a full tank of gas and sparks firing in the cylinders ... until he meets Donald Shimoda - former mechanic and self-described messiah who can make wrenches fly and Richard''s imagination soar... In Illusions,the unforgettable follow-up to his phenomenal New York Times bestseller Jonathan Livingston Seagull,Richard Bach takes to the air to discover the ageless truths that give our souls wings- that people don''t need airplanes to soar ... that even the darkest clouds have meaning once we lift ourselves above them ... and that messiahs can be found in the unlikeliest places - like hay fields, one-traffic-light midwestern towns, and most of all, deep within ourselves.', 'en', 2001, 144, 'http://books.google.com/books/content?id=Z93wmaJAtyoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
