INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('76447956-70ca-5362-8f5c-d920c63476ae', '9780099428169', 'In the Pond', 'bkmry89MaYYC', 'Ha Jin has been compared to the late Issac Babel for his spare evocation of ordinary lives caught up in the flux of vast social movements. Winner of the Hemingway/PEN Award for first fiction for his story collection Under the Red Flag, Ha Jin is a writer of stark power, simple beauty and poignant irony. His themes of personal honour in the face of political rectitude are carried forward here in his first novel, In the Pond, a close, unsentimental depiction of life in a small factory town; the manoeuvring, posturing, petty jealousies and injustices of an ordinary man who tangles with the party bosses.', 'en', 2002, 160, 'http://books.google.com/books/content?id=bkmry89MaYYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
