INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b32b0bdc-8f5e-5e86-99ca-cb52e47fe634', '9780099428633', 'How to Travel with a Salmon and Other Essays', '-SLftgAACAAJ', 'This witty and irreverent collection of essays presents Eco''s playful but unfailingly accurate takes on everything from militarism, computer jargon, Westerns, librarians and bureaucrats to meals on airplanes, Amtrak trains, bad coffee, express mail, fax machines and pornography. "An uncanny combination of the profound and the profane".--San Francisco Chronicle.', 'en', 2001, 229, 'http://books.google.com/books/content?id=-SLftgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
