INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f6e18ef8-abbb-5f03-a556-cd16958a2825', '9780099432449', 'A Birthday for Frances', 'wJ1xPwAACAAJ', 'Frances isn''t happy, because it isn''t her big birthday day, it is Gloria''s. Frances isn''t sure she will give Gloria her whole present and might keep half for herself. After all, little sisters aren''t that good, they can''t throw, they always break your crayons, pull your toys apart and put water in your mud pies. It isn''t till Gloria makes her birthday cake wish, that Frances changes her mind!', 'en', 1968, 32, 'http://books.google.com/books/content?id=wJ1xPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '569', 'accepted', 'Russell Hoban', 'Badgers', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 2 FROM public.book WHERE isbn13 = '9780099432449' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f508d2d8-0e1b-56fe-a49c-6b6d192608dc', '9780099436744', 'The Gangs of New York', '5dtj8Od-IcwC', 'The Gangs of New York is a tour through a now unrecognisable city of abysmal poverty and habitual violence cobbled from legend, memory, police records, the self-aggrandizements of aging crooks, popular journalism, and solid historical research. Asbury presents the definitive work on this subject, an illumination of the gangs of old New York that ultimately gave rise to the modem Mafia and its depiction in films like The Godfather.', 'en', 2002, 384, 'http://books.google.com/books/content?id=5dtj8Od-IcwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '570', 'accepted', 'Herbert Asbury', 'Gangs', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 13 FROM public.book WHERE isbn13 = '9780099436744' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('52c2f9f0-5575-5ce1-ad64-a53971b86eae', '9780099437529', 'The Whore''s Child and Other Stories', 'iXmFAAAACAAJ', '"In this entrancing first collection of stories, a master storyteller focuses on a fresh and fascinating range of human behaviour, revealing himself as an even more versatile and accomplished writer than his acclaimed novels have shown. As with all Russo''s characters, we warm to these newcomers almost in spite of themselves. In the title story, a septuagenarian nun resolutely invades the narrator''s college writing workshop with an incredible saga; a seasoned Hollywood moviemaker uncovers a 25-year-old flame he never knew he''d harboured; a precious fifth-grader puzzles over life, love and baseball as he watches his parents'' marriage dissolve; another child is forced into a harrowing cross-country escape; and an elderly couple rediscover the power - and misery - of their relationship during a long-awaited retreat to a hurricane-swept resort island."', 'en', 2003, 240, 'http://books.google.com/books/content?id=iXmFAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
