INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d0ca2162-4f59-5d16-b52f-94c346eb4cf7', '9780099446729', 'Blackwood Farm', 'cIn8Twm4MIkC', 'Lestat Is Back, Saviour And Demon, Presiding Over A Gothic Story Of Family Greed And Hatred Through Generations, A Terrifying Drama Of Blood Lust And Betrayal, Possession And Matricide. Blackwood Farm With Its Grand Southern Mansion, Set Among Dark Cypress Swamps In Louisiana, Harbours Terrible Blood-Stained Secrets And Family Ghosts. Heir To Them All Is Quinn Blackwood, Young, Rash And Beautiful, Himself A ''Bloodhunter'' Whom Lestat Takes Under His Wing. But Quinn Is In Thrall Not Only To The Past And His Own Appetites But, Even More Dangerously, To A Companion Spirit, A ''Goblin'' Succubus Who Could Destroy Him And Others. Only The Unearthly Power Of Lestat Combined With The Earthly Powers Of The Mayfair Clan Could Hope To Save Quinn From Himself And His Ghosts, Or To Rescue The Doomed Girl Quinn Loves From Her Own Mortality- Shocking, Savage And Richly Erotic, This Novel With The Deceptively Gentle Title Bring Us Anne Rice At Her Most Powerfully Disturbing. Here Are Vampires And Witches, Men And Women, Demons And A Doppelg-Nger, Caught Up In A Maelstrom Of Death And Destruction, Blood And Fire, Cruelty And Fate.', 'en', 2003, 774, 'http://books.google.com/books/content?id=cIn8Twm4MIkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '573', 'accepted', 'Anne Rice', 'Horror', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 12 FROM public.book WHERE isbn13 = '9780099446729' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cbc98d75-78ea-5054-954a-566b0557a090', '9780099448464', 'The Carpenter''s Pencil', 'M6aM8vvrfjAC', '"It is the summer of 1936, the early months of the agonsing civil war that engulfs Spain and shakes the rest of the world. In a prison in the pilgrim city of Santiago de Compostela, an artist sketches the famouse porch of the cathedral, the Portico da Gloria. He uses a carpenter''s pencil. But instead of reproducing the sculptured faces of the prophets and elders, he draws the faces of his fellow Republican prisoners. any years later in post Franco Spain, a survivor of that period, Doctor Daniel da Barca, returns from exile to his native Galicia, and the threads of past memories begin to be woven together. This poetic and moving novel conveys the horror and savagery of the tragedy that divided Spain, and the experiences of the men and women who lived through it. Yet in the process, it also relates one of the most beautiful love stories imaginable."', 'en', 2003, 165, 'http://books.google.com/books/content?id=M6aM8vvrfjAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '574', 'accepted', 'Manuel Rivas', 'Galicia (Spain : Region)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 17 FROM public.book WHERE isbn13 = '9780099448464' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d7b2d36d-e578-5e54-9d09-63f7112dc7f7', '9780099448471', 'Sputnik Sweetheart', '--_eXhJE0noC', 'Twenty two year old, Sumire is in love for the first time with a woman seventeen years her senior, Miu. Surprised that she might, after all, be a lesbian, Sumire spends hours on the phone talking to her best friend, K, a primary school teacher, who is used to answering questions, but what he most wants to say to Sumire is I love you.', 'en', 2002, 229, 'http://books.google.com/books/content?id=--_eXhJE0noC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '575', 'accepted', 'Haruki Murakami', 'Businesswomen', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 0 FROM public.book WHERE isbn13 = '9780099448471' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8f82c759-6301-5246-b07c-8a50a8342538', '9780099448570', 'South of the Border, West of the Sun', 'D3pTwEWLjj8C', 'Growing up in the suburbs in post-war Japan, it seemed to Hajime that everyone but him had brothers and sisters. His sole companion was Shimamoto, also an only child. Together they spent long afternoons listening to her father''s record collection. But when his family moved away, the two lost touch. Now Hajime is in his thirties. After a decade of drifting he has found happiness with his loving wife and two daughters, and success running a jazz bar. Then Shimamoto reappears. She is beautiful, intense, enveloped in mystery. Hajime is catapulted into the past, putting at risk all he has in the present.', 'en', 2003, 190, 'http://books.google.com/books/content?id=D3pTwEWLjj8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '576', 'accepted', 'Haruki Murakami', 'Domestic fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 20 FROM public.book WHERE isbn13 = '9780099448570' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fd597674-c6ac-559f-85ee-800f32cc2745', '9780099448754', 'The Elephant Vanishes', 'GzP6Dzk-f8sC', 'When a man''s favourite elephant vanishes, the balance of his whole life is subtly upset; a couple''s midnight hunger pangs drive them to hold up a McDonald''s; a woman finds she is irresistible to a small green monster that burrows through her front garden; an insomniac wife wakes up to a twilight world of semi-consciousness in which anything seems possible - even death. In every one of the stories that make up The Elephant Vanishes, Murakami makes a determined assault on the normal. He has a deadpan genius for dislocating realities to uncover the surreal in the everyday, the extraordinary in the ordinary.', 'en', 2003, 327, 'http://books.google.com/books/content?id=GzP6Dzk-f8sC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '577', 'accepted', 'Haruki Murakami', 'Japan', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 6 FROM public.book WHERE isbn13 = '9780099448754' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0836c614-4ea2-5552-ac22-917373097446', '9780099448761', 'Dance Dance Dance', '23aiRAguYcEC', 'Combining an offbeat cast of characters with Murakami''s idiosyncratic prose, this novel is an assault on all the senses, a murder mystery that is also philosophical speculation, and a dark fable of advanced capitalism.', 'en', 2003, 393, 'http://books.google.com/books/content?id=23aiRAguYcEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '578', 'accepted', 'Haruki Murakami', 'Crime investigation', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 7 FROM public.book WHERE isbn13 = '9780099448761' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5251cf7b-1123-563e-843d-62a9e0776da9', '9780099448921', 'The Rings of Saturn', 't671cbf3pz0C', 'The Rings of Saturn begins as the record of a journey on foot through coastal East Anglia. From Lowestoft to Bungay, Sebald''s own story becomes the conductor of evocations of people and cultures past and present: of Chateaubriand, Thomas Browne, Swinburne and Conrad, of fishing fleets, skulls and silkworms. The result is a rich meditation on the past via a melancholy trip along the Suffolk coast, and an intricately patterned and haunting book on the transience of all things human. ''Sebald is the Joyce of the 21st Century'' The Times', 'en', 2002, 304, 'http://books.google.com/books/content?id=t671cbf3pz0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '579', 'accepted', 'Winfried Georg Sebald', 'Authors, German', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 16 FROM public.book WHERE isbn13 = '9780099448921' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('15f5434e-9ee7-5359-8412-fbf0c35d1ddc', '9780099449867', 'Elephant', 'c0EEfxDAqDAC', 'These seven stories were the last that Carver wrote. Among them is one of his longest, ''Errand'', in which he imagines the death of Chekhov, a writer Carver hugely admired and to whose work his own was often compared. This fine story suggests that the greatest of modern short-story writers may, in the year before his untimely death, have been flexing his muscles for a longer work.', 'en', 2003, 124, 'http://books.google.com/books/content?id=c0EEfxDAqDAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '580', 'accepted', 'Raymond Carver', 'Short stories, American', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 17 FROM public.book WHERE isbn13 = '9780099449867' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('32cd9a7c-ee3b-5747-92fd-b87797a58a43', '9780099449898', 'Will You Please be Quiet, Please', 'ybfel1V2jd8C', 'With this, his first collection, Carver breathed new life into the short story. In the pared-down style that has since become his hallmark, Carver showed how humour and tragedy dwell in the hearts of ordinary people, and won a readership that grew with every subsequent brilliant collection of stories, poems and essays that appeared in the last eleven years of his life.', 'en', 2003, 181, 'http://books.google.com/books/content?id=ybfel1V2jd8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '581', 'accepted', 'Raymond Carver', 'Short stories', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 17 FROM public.book WHERE isbn13 = '9780099449898' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('18e7f646-4f55-5c08-93b8-6b5781ae448f', '9780099453833', 'The Time of Our Singing', 'atHpDdRLCK4C', 'Jonah, Joseph and Ruth are the children of mixed-race parents determined to protect them from the grinding effects of race. Hothouse children, they are all musically talented, but they cannot be protected from the world for long. Jonah becomes a successful young tenor, but the world of opera can only accept him as a ''brilliant Negro singer''; Joseph, our narrator, becomes a pianist and devotes his talents to the service of his brother''s; Ruth turns her back on classical music (''white music'') and disappears, on the run with her black husband under suspicion of being a Black Panther. Powers brilliantly and devastatingly delineates the tragedy of race in America, as it unfolds from the Civil Rights movement to Rodney King and Louis Farrakhan, through the lives and choices of one family, caught on the cusp of identities.', 'en', 2004, 631, 'http://books.google.com/books/content?id=atHpDdRLCK4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '582', 'accepted', 'Richard Powers', 'African Americans', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 14 FROM public.book WHERE isbn13 = '9780099453833' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f4b81fd6-13a1-570e-932b-ce8d947f05d9', '9780099456452', 'The Spook''s Apprentice', 'ZA0yS2C37r4C', 'A wonderful and terrifying series by a new writer about a young boy training to be an exorcist. Thomas Ward is the seventh son of a seventh son and has been apprenticed to the local Spook. The job is hard, the Spook is distant and many apprentices have failed before Thomas. Somehow Thomas must learn how to exorcise ghosts, contain witches and bind boggarts. But when he is tricked into freeing Mother Malkin, the most evil witch in the County, the horror begins . .', 'en', 2005, 325, 'http://books.google.com/books/content?id=ZA0yS2C37r4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '583', 'accepted', 'Joseph Delaney', 'Exorcism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 2 FROM public.book WHERE isbn13 = '9780099456452' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dc56ca92-ce04-53fb-9863-b01fb3d2e4f9', '9780099458265', 'Human Traces', 'KTKZiwoIHMUC', 'As young boys both Jacques RebiSre and Thomas Midwinter become fascinated with trying to understand the human mind.As psychiatris- ts, their quest takes them from the squalor of the Victorian lunatic asylum to the crowded lecture halls of the renowned Professor Charcot in Paris; from the heights of the Sierra Madre in California to the plains of unexplored Africa. As the concerns of the old century fade and the First World War divides Europe, the two men''s volatile relationship develops and changes, but is always tempered by one exceptional woman; Thomas''s sister Sonia.Moving and challenging in equal measure, HUMAN TRACES explores the question of what kind of beings men and women really are.', 'en', 2006, 793, 'http://books.google.com/books/content?id=KTKZiwoIHMUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '584', 'accepted', 'Sebastian Faulks', 'Europe', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 3 FROM public.book WHERE isbn13 = '9780099458265' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a95e9717-0063-5c2d-866a-7eb447c79a41', '9780099460176', 'Blood Canticle', 'iQjGwPtIEVAC', 'Lestat is back with a vengeance and in thrall to Rowan Mayfair. Both demon and angel, he is drawn to kill but tempted by goodness as he moves among the pantheon of Anne Rice''s unforgettable characters. Julien Mayfair, his tormentor; Rowan, witch and neurosurgeon, who attracts spirits to herself, casts spells on others and finds herself dangerously drawn to Lestat; Patsy, country and western singer, who was killed by Quinn Blackwood and dumped in a swamp; Ash Templeton, a 5,000 year old Taltos whose genes live on in the Mayfairs. Now, Lestat fights to save Patsy''s ghost from the dark realms of the Earthbound, to uncover the mystery of the Taltos and to decide the fate of Rowan Mayfair. Both of Anne Rice''s irresistible realms - the worlds of Blackwood Farm and the Mayfair Witches - collide as Lestat struggles between his lust for blood and the quest for life, between gratification and redemption.', 'en', 2004, 400, 'http://books.google.com/books/content?id=iQjGwPtIEVAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
