INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c71269b6-4671-53c1-b683-4de68277b818', '9780099461098', 'Underground', 'i2104FzgbvIC', 'This account of the 1995 gas attack on the Tokyo subway system by a Japanese religious cult is told, based on hundreds of interviews with survivors, relatives of those who died, and the perpetrators.', 'en', 2003, 309, 'http://books.google.com/books/content?id=i2104FzgbvIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '586', 'accepted', 'Haruki Murakami', 'Cults', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 16 FROM public.book WHERE isbn13 = '9780099461098' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('91c8b053-3343-5638-8e5a-c2da5f6900fd', '9780099461265', 'Open House', 'shlDD04amKoC', 'When Samantha Morrow''s husband leaves her and her eleven-year-old son she is faced with the terrifying prospect of having to recreate her whole life. She opens her house to a series of lodgers who each in the eccentric way help her to see herself. And she shakes a friend, who shows her that she has the ability to make her own future.', 'en', 2003, 314, 'http://books.google.com/books/content?id=shlDD04amKoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '587', 'accepted', 'Elizabeth Berg', 'Divorced women', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 14 FROM public.book WHERE isbn13 = '9780099461265' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f3825fd9-b13f-57e9-b0eb-654b1f30e375', '9780099462255', 'Like a Charm', 'HVWEDUYM-YUC', 'The cream of British and American crime writers combine for a must- have collection of linked short stories- With each writer picking up the story in their usual locale (Val McDermid in Manchester, Denise Mina in Glasgow, Karin Slaughter in Atlanta), each of these prestigious crime writers tells a gripping story (original to this collection) of murder, betrayal and intrigue. And running through each story is a charm bracelet- which brings bad luck wherever it''s found... The must- have collection for all fans of British and American crime writing at it''s best...', 'en', 2004, 384, 'http://books.google.com/books/content?id=HVWEDUYM-YUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '588', 'accepted', 'Karin Slaughter', 'Bracelets', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 12 FROM public.book WHERE isbn13 = '9780099462255' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('38dcc0a9-e92e-57a8-bde3-8b2586feabaf', '9780099468196', 'Bleachers', 'B9D3QT00fqEC', 'High school All-American Neely Crenshaw was probably the best quarterback ever to play for the legendary Messina Spartans. Fifteen years have gone by since those glory days, and Neely has come home to Messina to bury Coach Eddie Rake, the man who molded the Spartans into an unbeatable football dynasty. As Coach Rake''s ''boys'' sit in the bleachers waiting for the dimming field lights to signal his passing, they replay the old glories, and try to decide once and for all whether they love Eddie Rake - or hate him. For Neely Crenshaw, still struggling to come to terms with his explosive relationship with the Coach, his dreams of a great career in the NFL, and the choices he made as a young man, the stakes could not be higher.', 'en', 2004, 229, 'http://books.google.com/books/content?id=B9D3QT00fqEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
