INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('332f0659-43d1-5101-bc87-cfc458cc3655', '9780099471431', 'Lasher', 'UeyMABieKGMC', 'At the centre of Anne Rice''s brilliant novel, the beautiful Rowan Mayfair, queen of the coven, must flee from the darkly brutal, yet irresistible demon known as Lasher. With a dreamlike power, this wickedly seductive entity draws us through twilight paths, telling a chillingly hypnotic story of spiritual aspirations and passion...', 'en', 2004, 883, 'http://books.google.com/books/content?id=UeyMABieKGMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
