INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2d8a110e-5f69-5cd6-ac0f-e6f53e98bd17', '9780099474128', 'Women Who Love Too Much', '_v6tu8Tpyq8C', 'Is having ''somebody to love'' the most important thing in your life? Do you constantly believe that with ''the right man'' you would no longer feel depressed or lonely? Are you bored with ''nice guys'' who are open, honest and dependable? If being in', 'en', 2004, 314, 'http://books.google.com/books/content?id=_v6tu8Tpyq8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
