INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('43b0681c-4c2d-5fe3-98b5-7923ec3cdd57', '9780099474548', 'A Very Long Engagement', '4XejAAAACAAJ', 'One bitter night in January 1917, five French soldiers are court-martialled and sent into No-Man''s Land. Days later, five corpses are given a hasty burial. After the war, the fiancée of one of the men sets out to discover what happened.', 'en', 2004, 320, 'http://books.google.com/books/content?id=4XejAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
