INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('88a3427c-35e7-5156-9e04-e1b615e579b9', '9780099481249', 'Enduring Love', 'S702H90xDekC', '"The story of how an ordinary man can be driven to the brink of murder and madness by the delusions of another. It begins on a windy summer''s day in the Chilterns when the calm, organized life of Joe Rose is shattered by a ballooning accident."--Publisher''s description.', 'en', 2004, 245, 'http://books.google.com/books/content?id=S702H90xDekC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
