INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('803a1392-d6b5-5aad-afa4-71210e1f29e9', '9780099481683', 'Skipping Christmas', 'r58lD61nLEAC', 'A classic tale for modern times, Skipping Christmas offers a hilarious look at the chaos and frenzy that has become part of our holiday tradition. Imagine a year without Christmas. No crowded shops, no corny office parties, no fruitcakes, no unwanted presents. That''s just what Luther and Nora Krank have in mind when they decide that, just this once, they''ll skip the holiday altogether. Theirs will be the only house on the street without a rooftop Frosty the snowman; they won''t be hosting their annual Christmas Eve bash; they aren''t even going to have a tree. They won''t need one, because come December 25 they''re setting sail on a Caribbean cruise. But, as this weary couple is about to discover, skipping Christmas brings enormous consequences - and isn''t half as easy as they''d imagined.', 'en', 2004, 198, 'http://books.google.com/books/content?id=r58lD61nLEAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
