INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b3d55a94-3cd9-5f44-ae6c-a7432e9b2e7f', '9780099489986', 'Watermelon', '-55iSi-yKusC', 'Claire''s husband James leaves her for Denise from the flat downstairs, the day their first child is born. Broken-hearted, Claire returns home to her family to get better. So much better in fact, that when James slithers back into her life he''s in for a surprise.', 'en', 2005, 520, 'http://books.google.com/books/content?id=-55iSi-yKusC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
