INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f9ea8b82-4c69-5655-90ca-bf56f550b0be', '9780099490685', 'The Invisible Writing', 'GGIziAcbly8C', 'Taken together, Arthur Koestler''s volumes of autobiography constitute an unrivalled study of twentieth-century man and his dilemma. ARROW IN THE BLUE ended with his joining the Communist Party and THE INVISIBLE WRITING covers some of the most important experiences in his life. We see him in Germany, Russia, England, France and Spain, working sometimes openly and sometimes underground for the cause in which he believed. This was the time of the ''seven years'' night'' over Europe - of Hitler''s spectacular successes against the Western Democracies. They were also the years of the great Russian purges, which led to Koestler#s eventual break with Communism in 1938, after Hitler and Stalin between them had claimed the lives of most of his friends and relatives. This book tells of Koestler''s travels through Russia and remote parts of Soviet Central Asia and of his life as an exile. It puts in perspective his experiences in Franco''s prisons under sentence of death and in concentration camps in Occupied France (told at greater length in DIALOGUE WITH DEATH AND SCUM OF THE EARTH), and ends with his escape from Occupied France in 1940 to England, where he found stability and a new home. An epilogue brings the story up to 1953, when it was written. Koestler calls the book ''a typical case history of a member of the educated middle classes of Central Europe in our time''. It has two main themes: the historical background against which the author developed, and an unsparing analysis of his intellectual and spiritual development.', 'en', 2005, 528, 'http://books.google.com/books/content?id=GGIziAcbly8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '610', 'accepted', 'Arthur Koestler', 'Authors, English', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 6 FROM public.book WHERE isbn13 = '9780099490685' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dde7d732-066b-55b2-afaa-27315bc6942f', '9780099498582', 'Dublin 4', 'yPgE79B9h0gC', 'A vintage collection of short stories set in the heart of Dublin, from the bestselling author of Light a Penny Candle and Circle of Friends. A society hostess entertains her husband''s mistress to dinner; a country girl savours the delights of city life; a student faces the dilemma of unmarried pregnancy; and a drink-ridden photographer tries to relaunch a shattered career... This vintage collection of stories from the bestselling author of Light a Penny Candle and Circle of Friends is Maeve Binchy at her best - her trademark warmth, wit and compassion are unmistakeable.', 'en', 2006, 256, 'http://books.google.com/books/content?id=yPgE79B9h0gC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '611', 'accepted', 'Maeve Binchy', 'Domestic fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 18 FROM public.book WHERE isbn13 = '9780099498582' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ab2e312d-0da7-5ccc-a39e-b3fe220a75c6', '9780099498599', 'Circle of Friends', 'P4-i_eBBhL8C', 'It began with Benny Hogan and Eve Malone, growing up, inseparable, in the village of Knockglen. Benny--the only child, yearning to break free from her adoring parents...Eve--the orphaned offspring of a convent handyman and a rebellious blueblood, abandoned by her mother''s wealthy family to be raised by nuns. Eve and Benny--they knew the sins and secrets behind every villager''s lace curtains...except their own. It widened at Dublin, at the university where Benny and Eve met beautiful Nan Mahlon and Jack Foley, a doctor''s handsome son. But heartbreak and betrayal would bring the worlds of Knockglen and Dublin into explosive collision. Long-hidden lies would emerge to test the meaning of love and the strength of ties held within the fragile gold bands of a... Circle Of Friends. From the Paperback edition.', 'en', 2006, 722, 'http://books.google.com/books/content?id=P4-i_eBBhL8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '612', 'accepted', 'Maeve Binchy', 'College attendance', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 7 FROM public.book WHERE isbn13 = '9780099498599' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('58e5173f-c7fc-52cd-98ae-77be82e1bdeb', '9780099498636', 'Victoria Line, Central Line', 'V7kjF8MAhbsC', 'A vintage collection of short stories from the bestselling author of Light a Penny Candle and Circle of Friends. Millions of people travel on London''s tube every day, yet we usually give our fellow passengers only a cursory glance. But each one of these nameless passengers has their own story to tell. At Notting Hill, the mysterious secretary, harbouring her secrets, travels to work; at Highburyand Islington, Adam has a sudden change of heart; and at Holborn, a disastrous reunion is about to take place... With her characteristic mix of compassionate humour and biting realism, this vintage collection of stories is Maeve Binchy at her very best', 'en', 2006, 432, 'http://books.google.com/books/content?id=V7kjF8MAhbsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '613', 'accepted', 'Maeve Binchy', 'London (England)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 15 FROM public.book WHERE isbn13 = '9780099498636' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('df38827f-620a-5fbc-b405-a2df2a99988c', '9780099498667', 'Firefly Summer', 'VEXwXNUsyHcC', 'Firefly Summer is warm, humorous, sad and happy. Reading it is a joy'' Irish Independent. Kate and John Ryan have four children, of whom the eldest are Michael and Dara. Their small town is peaceful and friendly, an unchanging background for a golden childhood. In long, hot summers Michael and Dara and their friends fish and swim or play in the ivy-clad ruins of Fernscourt, the great house burned down during the Troubles... No one in Mountfern has the slightest inkling of what it will mean when the ruins are bought by Patrick O''Neill, an Irish American with a dream in his heart and a great deal of money in his pocket. It is not until the very end of this drama, with its interlocking stories of love lost and won, ambitions nurtured and secrets betrayed, that Patrick O''Neill will understand the irony and the significance of his great dream for Mountfern.', 'en', 2006, 928, 'http://books.google.com/books/content?id=VEXwXNUsyHcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
