INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f1bf1271-7c5f-5fc1-b218-15211ea375e2', '9780099556312', 'Airframe', 'drRsu1CjsYIC', 'The twin jet plane en route to Denver from Hong Kong is merely a green radar blip half an hour off the California coast when the call comes through to air traffic control: ''Socal Approach, this is TransPacific 545. We have an emergency. '' The pilot requ', 'en', 1997, 431, 'http://books.google.com/books/content?id=drRsu1CjsYIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
