INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8b75b700-a30c-5770-a940-25bf4ef9392e', '9780099582014', 'Sabbath''s Theater', 'lm070nfcbeAC', 'Once a scandalously inventive puppeteer, Mickey Sabbath at sixty-four is still defiantly antagonistic and exceedingly libidinous. But after the death of his long-time mistress, Sabbath embarks on a turbulent journey into his past. Bereft and grieving, besieged by the ghosts of those who loved and hated him most, he contrives a succession of farcical disasters that take him to the brink of madness and extinction.', 'en', 1996, 451, 'http://books.google.com/books/content?id=lm070nfcbeAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '617', 'accepted', 'Philip Roth', 'American fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 3 FROM public.book WHERE isbn13 = '9780099582014' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('24f4391a-c125-5fae-b2aa-27bc1e459fa8', '9780099595816', 'Civilwarland in Bad Decline', 'ZY7h1t8IZjUC', 'A brilliant collection of stories from the winner of the Folio Prize A collection of six stories and a novella, CIVILWARLAND IN BAD DECLINE introduces an astonishing new voice in American fiction. George Saunders'' vision of America''s near future is as black and funny as you can get. He takes us on a trip to the shopping malls and theme parks and enviromental hazards that lie just around the chronological corner, introducing us to gang of misfits and losers struggling to survive in an increasingly haywire world. Saunders'' dialogue is superb, his plots marvellously bizarre: he is an original and uniquely American voice destined to become one of the most important literary discoveries of his generation.', 'en', 1997, 179, 'http://books.google.com/books/content?id=ZY7h1t8IZjUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '618', 'accepted', 'George Saunders', 'Short stories', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 14 FROM public.book WHERE isbn13 = '9780099595816' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('34169d38-136f-590b-a2e1-c24c367d3627', '9780099730514', 'Six Memos for the Next Millennium', 'grihPwAACAAJ', 'SIX MEMOS FOR THE NEXT MILLENNIUM is the text to a series of lectures which became an obsession for Italo Calvino in the last year of his life. Drawing on the works of Lucretius, Ovid, Boccaccio, Falubert, Kundera, Perec and many more, he pinpoints the universal laws and indispensable literary values future generations might cherish -lightness, quickness, exactitude, visibility and multiplicity. It is an eloquent and lively ''defence'' of literature - a fitting gift for the next millennium.', 'en', 1996, 128, 'http://books.google.com/books/content?id=grihPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '619', 'accepted', 'Italo Calvino', 'Literature', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 8 FROM public.book WHERE isbn13 = '9780099730514' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('adfd78e9-66ff-533a-b2f3-f4cf3467144a', '9780099748618', 'London Fields', 'uhvuxNSWO6gC', 'The narrator, Samson Young, enters the Black Cross, a thoroughly undesirable public house, and finds the main players of his drama assembled, just waiting to begin. It''s a gift of a story from real life. . . all Samson has to do is to write it as it happens. Taking a small pocket of time and a richly diverse part of London, Martin Amis dissects the nature of a society as it hurtles towards the millennium.', 'en', 1999, 526, 'http://books.google.com/books/content?id=uhvuxNSWO6gC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '621', 'accepted', 'Martin Amis', 'City and town life', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 17 FROM public.book WHERE isbn13 = '9780099748618' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f0bbf820-2838-5031-bde4-2bf4e30af7c6', '9780099771814', 'American Pastoral', 'O9E8gGrjhj4C', 'In American Pastoral, Philip Roth gives us a novel of unqualified greatness that is an elegy for all the twentieth century''s promises of prosperity, civic order, and domestic bliss. Roth''s protagonist is Seymour ''Swede'' Levov - a legendary high school athlete, a devoted family man, a hard worker, the prosperous inheritor of his father''s Newark glove factory - comes of age in thriving, triumphant post-war America. And then one day in 1968, Swede''s beautiful American luck deserts him. For Swede''s adored daughter, Merry, has grown from a loving, quick-witted girl into a sullen, fanatical teenager - a teenager capable of an outlandishly savage act of political terrorism. And overnight Swede is wrenched out of the longed-for American pastoral and into the indigenous American berserk. Compulsively readable, propelled by sorrow, rage, and a deep compassion for its characters, this is Roth''s masterpiece.', 'en', 1998, 432, 'http://books.google.com/books/content?id=O9E8gGrjhj4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '623', 'accepted', 'Philip Roth', 'American literature', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 1 FROM public.book WHERE isbn13 = '9780099771814' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8fad3fb7-3295-52da-9c57-a146b4f1db9b', '9780099801900', 'Deception', '0P2Yf1WvZ6oC', 'A famous writer and his mistress meet in a room without a bed. They talk, they play games with each other, they have sex, they tell lies. This work since "Complaint", explores adultery and the unmasking of illicit lovers in a novel that exposes the tenderness and uncertainty underlying all affairs of the heart.', 'en', 1991, 208, 'http://books.google.com/books/content?id=0P2Yf1WvZ6oC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '624', 'accepted', 'Philip Roth', 'Adultery', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 18 FROM public.book WHERE isbn13 = '9780099801900' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ed43a1d8-23e6-5e19-a3be-eeaaa1a9dabc', '9780099910107', 'A Farewell to Arms', 'm68LhBiNv8YC', 'In 1918 Ernest Hemingway went to war, to the ''war to end all wars''. He volunteered for ambulance service in Italy, was wounded and twice decorated. Out of his experiences came A Farewell to Arms. Hemingway''s description of war is unforgettable. He recreates the fear, the comradeship, the courage of his young American volunteer and the men and women he meets in Italy with total conviction. But A Farewell to Arms is not only a novel of war. In it Hemingway has also created a love story of immense drama and uncompromising passion.', 'en', 1994, 293, 'http://books.google.com/books/content?id=m68LhBiNv8YC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '625', 'accepted', 'Ernest Hemingway', 'War', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 3 FROM public.book WHERE isbn13 = '9780099910107' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7bcaac45-5e76-51cf-9ec5-844b007662a5', '9780099911708', 'Cross Stitch', '0Pm4ihLyutIC', 'In 1945, Claire Randall is back from the war and reunited with her husband on a second honeymoon in Scotland. Innocently she walks through a stone circle in the highlands, and finds herself in a violent skirmish taking place in 1743. Suddenly she is a Sassenach, an outlander, in a country torn by war and by clan feuds. -- back cover.', 'en', 1992, 864, 'http://books.google.com/books/content?id=0Pm4ihLyutIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
