INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('707854cc-0de4-58bd-9f03-9b1037164fac', '9780132197380', 'Three Genres', 'WPjQPAAACAAJ', 'Three Genres gives students a basic introduction to fiction/ literary nonfiction, poetry, and drama and helps them to develop their creative skills in each area. Each genre section is self-contained and includes complete works as examples along with helpful advice about how to draw on the variety of techniques they use. The style is informal, practical, and positive. Minot encourages student to draw on their own experiences and develop skills on their own.', 'en', 2006, 476, 'http://books.google.com/books/content?id=WPjQPAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
