INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c49fb014-1a7d-5876-b23b-a6404d2cbcee', '9780140018325', 'Kiss Kiss', 'l2lJH0BD77AC', 'Eleven Devious, Shocking Stories from the Master of the Unpredictable. What could go wrong when a wife pawns the mink coat that her lover gave her as a parting gift? What happens when a pricelass piece of furniture is the subject of a deceitful bargain? Can a wronged woman take revenge on her dead husband? In these dark, dangerous stories Roald Dahl explores the sinister side of human nature: the cunning, sly, selfish part of each of us that leads into the territory of the unexpected and unsettling. Stylish, macabre and haunting, these tales will leave you with a delicious feeling of unease.', 'en', 1962, 231, 'http://books.google.com/books/content?id=l2lJH0BD77AC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
