INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8c343bf9-a958-5ea3-be63-a59adc478592', '9780140071788', 'Roald Dahl''s Book of Ghost Stories', 'zGt6RQAACAAJ', 'Who better to investigate the literary spirit world that the supreme connoisseur of the unexpected, Roald Dahl? His own short stories have teased and twisted imaginations in their millions, but amongst the many permutations of the macabre, Dahl has always felt a special fascination for the classic ghost story. In this book of ghost stories he has selected fourteen of his favourites for this superbly disquieting volume.', 'en', 1985, 249, 'http://books.google.com/books/content?id=zGt6RQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
