INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0cd5ccc7-b8c1-5c85-80a5-c35733113b44', '9780140105834', 'The Pigeon', '92txPwAACAAJ', 'Set in Paris and attracting comparisons with Franz Kafka and Edgar Allan Poe, The Pigeon is Patrick Süskind''s tense, disturbing follow-up to the bestselling Perfume. The novella tells the story of a day in the meticulously ordered life of bank security guard Jonathan Noel, who has been hiding from life since his wife left him for her Tunisian lover. When Jonathan opens his front door on a day he believes will be just like any other, he encounters not the desired empty hallway but an unwelcome, diabolical intruder . . .', 'en', 1989, 77, 'http://books.google.com/books/content?id=92txPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
