INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f0e23417-5c53-5762-bbb4-e2da629cfd68', '9780140125054', 'Q E D', '2X-3QgAACAAJ', 'Quantum electrodynamics - or QED, for short - is the revolutionary theory that explains how light and electrons interact. Thanks to Richard Feynman and his colleagues, who won the Nobel Prize for their ground-breaking work in this area, it is also one of the rare parts of physics that is known for sure, a theory that has stood the test of time. In these entertaining and witty lectures Feynman uses everyday examples to explain the deepest and most complex mysteries of the world around us, in the definitive introduction to QED.', 'en', 1990, 158, 'http://books.google.com/books/content?id=2X-3QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
