INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('008dd303-07d2-512c-8a77-ecdba09a358d', '9780140128468', 'Love''s Executioner', 'ZBptQgAACAAJ', 'Contains eight case-studies of people the author has treated, including a woman of 67, obsessively pining with love for her 32-year-old previous therapist and a woman of 19 stone who has emotional difficulties because of her weight problem. This title includes stories that reveal the diversity of human motivation.', 'en', 1991, 270, 'http://books.google.com/books/content?id=ZBptQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
