INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('eb9e9293-2bc9-59d0-ba9e-82eab71e7579', '9780140131673', 'East is East', '5DHuAAAAMAAJ', 'A young Japanese seaman jumps ship off the coast of Georgia and washes ashore on a barrier island inhabited by a strange mix of rednecks, descendents of slaves, genteel retired people, and a colony of artists. The result is a sexy, savagely hilarious tragicomedy of thwarted expectations, mistaken identity, love, jealousy and betrayal. "An absolutely stunning work, full of brilliant cross-cultural insights".--The New York Times Book Review.', 'en', 1991, 384, 'http://books.google.com/books/content?id=5DHuAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
