INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1d9c55e8-b91f-5bff-98ad-130cc47f1b08', '9780140139396', 'The Big Rock Candy Mountain', 'Je5dOcy2HF4C', 'Bo Mason and his wife and two boys live a transient life of poverty and despair; drifting from town to town, the violent, ruthless Bo seeks his fortune. Stegner has created a masterful, harrowing saga of a family trying to survive during the lean years of the early 20th century.', 'en', 1943, 563, 'http://books.google.com/books/content?id=Je5dOcy2HF4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
