INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('27548e4c-c887-566d-b94f-3010818cd115', '9780140144185', 'Journal of a Novel', 'EYVy6y3GHj0C', 'Each working day from January 29 to November 1, 1951, John Steinbeck warmed up to the work of writing East of Eden with a letter to the late Pascal Covici, his friend and editor at The Viking Press. It was his way, he said, of "getting my mental arm in shape to pitch a good game." Steinbeck''s letters were written on the left-hand pages of a notebook in which the facing pages would be filled with the test of East of Eden. They touched on many subjects—story arguments, trial flights of worknamship, concern for his sons. Part autobiography, part writer''s workshop, these letters offer an illuminating perspective on Steinbeck''s creative process, and a fascinating glimpse of Steinbeck, the private man.', 'en', 1969, 182, 'http://books.google.com/books/content?id=EYVy6y3GHj0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
