INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9be4092f-1472-549b-b56b-4e0c41148a16', '9780140150742', 'The Portable Dorothy Parker', 'WHN3-tctBZ8C', 'One of the most quotable of twentieth-century authors, Dorothy Parker has attained a wide-ranging and enthusiastic following. This revised and enlarged edition, with an introduction by Brendan Gill, comprises the original 1944 Portable, as selected and arranged by Dorothy Parker herself and including all her most celebrated poems and stories, along with a selection of her later stories, play reviews, articles, book reviews from Esquire, and the complete Constant Reader, her collected New Yorker book reviews."To say that Mrs. Parker writes well is as fatuous, I am afraid, as proclaiming that Cellini was clever with his hands. ... Mrs. Parker has an eye for people, an ear for language, and a feeling for the lithe things of life that are so immense a part of the process of living." - Ogden Nash"She has put into what she has written a voice, a state of mind, an era, a few moments of human experience that nobody else has conveyed." - Edmund Wilson', 'en', 1976, 610, 'http://books.google.com/books/content?id=WHN3-tctBZ8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
