INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('36398c66-8c66-54ce-81bb-c906a063df85', '9780140186123', 'Collected Short Stories', 'N3uC9Z0BHjEC', 'Affairs, obsessions, ardours, fantasy, myth, legend and dream, fear, pity and violence - this magnificant collection of stories illuminates all corners of the human experience. Previously published in three volumes - "May We Borrow Your Husband?," "A Sense of Reality" and "Twenty-One Stories" - these thirty-seven stories reveal Graham Greene in a range of contrasting moods, sometimes cynical and witty, sometimes searching and philosophical. Each one confirms V.S. Pritchett''s statement that Greene is ''a master of storytelling''.', 'en', 1986, 368, 'http://books.google.com/books/content?id=N3uC9Z0BHjEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
