INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d8e96701-6ceb-5e9d-b33d-3010d1906c8a', '9780140187076', 'J R', 'DLSmngEACAAJ', 'At the center of this hugely comic tale of "free enterprise" America stands JR--an eleven-year-old capitalist, eagerly following the example of the grasping world around him. Operating through pay phones and post-office money orders, JR inadvertently parlays a shipment of Navy surplus picnic forks, a defaulted bond issue, and a single share of common stock into a vast paper empire embracing timber, mineral and natural gas rights, publishing, and a brewery. At once a novel of epic comedy and a biting satire of the American dream, JR displays the style and extraordinary inventiveness that has made Gaddis one of the most acclaimed writers of our time.', 'en', 1993, 752, 'http://books.google.com/books/content?id=DLSmngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
