INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8e01778c-0dec-5396-a75f-39e9b90baa32', '9780140192070', 'I Ching, Or, Book of Changes', 'RFC1QgAACAAJ', 'Jessica Hart has never forgotten Matthew Landley. After all, he was her first love when she was fifteen years old. But he was also her school maths teacher, and their forbidden affair ended in scandal with his arrest and imprisonment. Now, seventeen years later, Matthew returns with a new identity, a long-term girlfriend and a young daughter, who know nothing of what happened before. Yet when he runs into Jessica, neither of them can ignore the emotional ties that bind them together. With so many secrets to keep hidden, how long can Jessica and Matthew avoid the dark mistakes of their past imploding in the present?', 'en', 1989, 739, 'http://books.google.com/books/content?id=RFC1QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
