INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2bd8ae5e-c9ba-5c01-9616-3009d45ea886', '9780140234442', 'Selected letters, 1940-1956', 'iPYOAQAAMAAJ', 'The life and craft of Jack Kerouac are traced through some of his most personal and mesmerizing letters. Written between 1940, when he was a freshman in college, and 1956, immediately before his leap into celebrity with the publication of On the Road, these letters offer valuable insights into Kerouac''s family life, friendships with Neal Cassady, Allen Ginsberg, and William S. Burroughs, and others.', 'en', 1996, 656, 'http://books.google.com/books/content?id=iPYOAQAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
