INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('94f42f91-53b0-565f-b19e-6358ad185330', '9780140244915', 'How the Mind Works', 'O521DV3v47wC', '"Presented with extraordinary lucidity, cogency and panache...Powerful and gripping...To have read [the book] is to have consulted a first draft of the structural plan of the human psyche...a glittering tour de force" - Spectator "Why do memories fade? Why do we lose our tempers? Why do fools fall in love? Pinker''s objective in this erudite account is to explore the nature and history of the human mind...He explores computations and evolutions, and then considers how the mind lets us "see, think, feel, interact, and pursue higher callings like art, religion and philosophy" - Sunday Times', 'en', 1999, 660, 'http://books.google.com/books/content?id=O521DV3v47wC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
