INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ed785182-c230-5305-a198-627682ceb89b', '9780140251579', 'The Making of Pride and Prejudice', 'ssBRUQiDk74C', 'This book reveals in detail how Jane Austen''s classic novel is transformed into a stunning television drama. Filmed on location at Wiltshire and Derbyshire, ''Pride and Prejudice'', with its lavish sets and distinguished cast, was scripted by award-winning dramatist Andrew Davies. Chronicling 18 months of work - from the original concept to the first broadcast - ''The Making of Pride and Prejudice'' brings vividly to life the challenges and triumphs involved in every stage of production of this sumptuous television series. Follow a typical day''s filming, including the wholesale transformation of Lacock village into Jane Austen''s Meryton. Discover how Colin Firth approaches the part of Darcy, how actors'' costumes and wigs are designed and how Carl Davis recreates the period music and composes an original score. Piece together the roles of many behind-the-scenes contributors to the series, from researchers and fencing masters to experts in period cookery and gardening.', 'en', 1995, 128, 'http://books.google.com/books/content?id=ssBRUQiDk74C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
