INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cf95134e-ba98-5334-a386-dc26f4ec8af3', '9780140259100', 'The Nuclear Age', 'p0EMAAAACAAJ', 'From Library Journal : Brilliant nuclear detonations and rising silver Titans have plagued William''s dreams since his childhood during the Cuban missile crisis, when he fashioned a fallout shelter from the family ping-pong table. Thirty years later his fear has mushroomed into blinding paranoia, and when his wife announces she is leaving, he laces a hole in the backyard with dynamite, places her in it, and prepares to blow her up.', 'en', 1996, 320, 'http://books.google.com/books/content?id=p0EMAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
