INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a4b35a2a-ade7-5f8d-9d5a-68f38a5b76db', '9780140271799', 'Rachel''s Holiday', 'jSYcXXXVQd4C', 'RACHEL''S HOLIDAY, Marian''s classic novel about addiction, is being given a new lease of life with a fantastic new jacket treatment. Here''s Rachel Walsh, twenty-seven and the miserable owner of size 8 feet. She has regular congress with Luke Costello, a man who wears his leather trousers tight. And she''s fond - some might say too fond - of recreational drugs. Until she finds herself being frogmarched to the Cloisters - Dublin''s answer to the Betty Ford Clinic. She''s outraged. Surely she''s not thin enough to be an addict? Heartsick and Luke-sick, she seeks redemption in the shape of Chris, a Man with a Past. A man who might be more trouble than he''s worth.', 'en', 1997, 626, 'http://books.google.com/books/content?id=jSYcXXXVQd4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
