INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('728cae88-0979-5f30-ad9e-2fa549680bed', '9780140275650', 'Age of Iron', 'cUkGRf7ahXoC', 'South African professor Mrs. Curren has always been opposed to apartheid''s brutality though she has lived isolated from its horrors, but as she nears death from cancer, she confronts a generation of blood and revenge.', 'en', 1998, 198, 'http://books.google.com/books/content?id=cUkGRf7ahXoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
