INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e399b11d-4fbe-5c76-ae83-8e984f2a3017', '9780140276909', 'Jemima J.', 'qPw2c2og4HIC', 'Jemima Jones is overweight. About seven stone overweight. Treated like a slave by her thin and bitchy flatmates, lorded over at the Kilburn Herald by the beautiful Geraldine (less talented, better paid), her only consolation is food. That and a passion for her charming, sexy colleague Ben. Her life needs to change and soon. But can Jemima reinvent herself? Should she? A novel about attraction, obsession and the meaning of true love.', 'en', 1998, 450, 'http://books.google.com/books/content?id=qPw2c2og4HIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
