INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2c266c99-ce5f-51b5-b20e-675b2f5d9b42', '9780140277821', 'Difficult Conversations', '5nHFQgAACAAJ', 'What is a difficult conversation? Asking for a pay rise, saying ''no'' to your boss or spouse, confronting a friend or neighbour, asking a difficult favour, apologizing. We all have conversations that we dread and find unpleasant. But can we develop the skills to make such situations less stressful and more productive? Based on fifteen years of research and consultations with thousands of people, DIFFICULT CONVERSATIONS pinpoints what works. Use this ground-breaking, step-by-step book to turnyour difficult conversations into positive, problem-solving experiences.', 'en', 2000, 250, 'http://books.google.com/books/content?id=5nHFQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
