INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1f0aaa7a-914d-5612-9f1f-19c9cacb9d2e', '9780140281705', 'The World of Mr. Mulliner', 'mjmeAAAACAAJ', 'Mr Mulliner, raconteur par excellence of the Anglers'' Rest, has some amazing stories to relate. Take, for example, young Lancelot. He is a bohemian - or was, until he had to look after his saintly uncle''s cat Webster, and was startlingly transformed. Then there is Mulliner''s brother Wilfred, a whizzo at chemistry, whose ''Magic Marvels'' medicine gets him in and out of a dreadful scrape. Mervyn, not one of the brighter members of the family, has a scrap over some strawberries. Not to mention Augustine the resourceful curate, Ignatius the portrait-painter, Adrian the detective and many more besides, whose wonderful and intriguing exploits are revealed in this witty omnibus. ''Witty and effortlessly fluid. His books are laugh-out-loud funny.'' Arabella Weir', 'en', 1999, 624, 'http://books.google.com/books/content?id=mjmeAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
