INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cb255e5c-a92a-54ff-908d-1ebf3bc73af1', '9780140284126', 'The Inimitable Jeeves', 'pk6XQgAACAAJ', 'Michael Hordern stars as Jeeves with Richard Briers as Bertie in a BBC Radio full-cast dramatization. Just when Bertie thinks that all''s right with the world, there''s young Bingo Little, who''s in love for the umpteenth time and needs Bertie to put in a good word for him with his uncle; Aunt Agatha, who forces Bertie to get engaged to the formidable Honoria Glossop; and friction in the Wooster home over a red cummerbund, purple socks and some snazzy old Etonian spats. Only the inimitable Jeeves can save the day.', 'en', 1999, 240, 'http://books.google.com/books/content?id=pk6XQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
