INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f23023ea-db99-56fe-ba86-daea7bde5be5', '9780140295948', 'Spellbound', 'gaHTANVEA3gC', 'Alice knows she should be happy. After all she has a handsome husband, a beautiful house and membership to all the most exclusive clubs in London. So what if the rumours about her husband''s skirt-chasing are becoming harder to ignore? When Joe''s indiscretions force a transfer to New York, Alice hopes it might be a fresh start. And when they find a beautiful old house in Connecticut Alice is overjoyed. For a while she and Joe seem as happy as newlyweds. But then the late nights and unexplained absences start again. What should Alice do? Stay and fight for him? Or leave with her head held high?', 'en', 2003, 439, 'http://books.google.com/books/content?id=gaHTANVEA3gC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
