INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('42914b72-8a36-506a-8a31-52e5035841ea', '9780140296037', 'A Year in Provence', 'ZCSQ0DH_vgcC', 'Enjoy an irresistible feast of humour and discover the joys of French rural living with Peter Mayle''s bestselling, much-loved account of ''A Year In Provence''. Peter Mayle and his wife did what most of us only imagine doing when they made their long-cherished dream of a life abroad a reality: throwing caution to the wind, they bought a glorious two hundred year-old farmhouse in the Lub�ron Valley and began a new life. In a year that begins with a marathon lunch and continues with a host of gastronomic delights, they also survive the unexpected and often hilarious curiosities of rural life. From mastering the local accent and enduring invasion by bumbling builders, to discovering the finer points of boules and goat-racing, all the earthy pleasures of Proven�al life are conjured up in this enchanting portrait.', 'en', 2000, 210, 'http://books.google.com/books/content?id=ZCSQ0DH_vgcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
