INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bb6489a6-e57f-566d-bc32-eb87e32a0187', '9780140296150', 'Selected Letters, 1957-1969', '8BoBPQAACAAJ', 'The second and final volume of letters from the Kerouac collection documents his romances, travels, writing, and emotional struggles, as well as his relationships with Allen Ginsberg, William Burroughs, Lawrence Ferlinghetti, Malcolm Cowley, and others. Reprint.', 'en', 2000, 656, 'http://books.google.com/books/content?id=8BoBPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
