INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('03a72f88-3c20-530b-90ab-3cfd8f4c1776', '9780140296617', 'The Periodic Table', 'TOo-PgAACAAJ', 'An extraordinary work in which each of the 21 chapters takes its title and starting point from one of the elements in the periodic table. Mingling fact and fiction, history and anecdote, Levi uses his training as a chemist and his experiences as a prisoner in Auschwitz to illuminate the human condition.', 'en', 2001, 194, 'http://books.google.com/books/content?id=TOo-PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
