INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2903ff65-88e8-5925-8b3b-53c9097afe31', '9780140297973', 'Pleasing Myself', '4rKpPwAACAAJ', 'Frank Kermode has often said that much of his best work has been done at shorter length, in the essays he has written on a very wide range of subjects for literary journals of one kind or another. This volume brings together a selection of these pieces that have been written since the 1990s, on topics as diverse as Donne, Yeats, Howard Hodgkin, gnosticism, the sea and money, as well as futher thoughts on Shakespeare.', 'en', 2002, 278, 'http://books.google.com/books/content?id=4rKpPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
