INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('831b3eab-2740-594a-8151-a49c4bcf7e79', '9780140299144', 'Vinyl Cafe Unplugged', 'FQjXMqlpfPEC', 'Bestselling author and radio storytelling sensation Stuart McLean revisits the heartwarming and hilarious friends from his iconic Vinyl Cafe. Dave and his wife Morley would no doubt tell you that life is what you make it. Unfortunately for them, that means a compilation tape of mistakes, miscues, misunderstandings, and muddle. That''s not to say that there is anything particularly unusual about the family and friends at the Vinyl Cafe. After all, who wouldn''t try to toilet-train a cat? Who hasn''t started a small home fix-it job only to set fire to the walls? Created mass hysteria at a school concert? Lost an aging relative while visiting our nation''s capital? "Vinyl Cafe Unplugged" is a warm and delightful collection of stories following the common foibles and everyday absurdities of family life.', 'en', 2001, 272, 'http://books.google.com/books/content?id=FQjXMqlpfPEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
