INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('73c96eac-00c8-51b2-9a07-3e6e1473280f', '9780140435191', 'The Pursuit of the Well-beloved and the Well-beloved', 'tLjGScN9eNAC', 'Hardy''s two versions of a strange story set in the weird landscape of Portland. The central figure is a man obsessed both with the search for his ideal woman and with sculpting the perfect figure of Aphrodite.', 'en', 2007, 416, 'http://books.google.com/books/content?id=tLjGScN9eNAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
