INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9dbdbc1a-0b9d-5e59-98bf-553af543930d', '9780140439052', 'A Christmas Carol and Other Christmas Writings', '1vITxwEACAAJ', 'After reading Christmas Carol, the notoriously reculsive Thomas Carlyle was "seized with a perfect convulsion of hospitality" and threw not one but two Christmas dinner parties. The impact of the story may not always have been so dramatic but, along with Dickens other Christmas writings, it has had a lasting and significant influence upon our ideas about the Christmas spirit, and about the season as a time for celebration, charity, and memory.', 'en', 2003, 288, 'http://books.google.com/books/content?id=1vITxwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
