INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5108faca-c90a-5c8b-8fcf-0def29dfd1c7', '9780140440935', 'Faust', 'IYSxmzIyouoC', 'A brief analysis of the development, style, and protagonists of the play is included with Goethe''s masterpiece about a troubled man who sells his soul to the devil.', 'en', 1959, 288, 'http://books.google.com/books/content?id=IYSxmzIyouoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
