INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1fbae884-8a29-5c87-843f-cfd591aea298', '9780140441123', 'Prometheus Bound and Other Plays', '0gbclW98ougC', 'Aeschylus (525;456 BC) brought a new grandeur and epic sweep to the drama of classical Athens, raising it to the status of high art. In Prometheus Bound the defiant Titan Prometheus is brutally punished by Zeus for daring to improve the state of wretchedness and servitude in which mankind is kept. The Suppliants tells the story of the fifty daughters of Danaus who must flee to escape enforced marriages, while Seven Against Thebes shows the inexorable downfall of the last members of the cursed family of Oedipus. And The Persians, the only Greek tragedy to deal with events from recent Athenian history, depicts the aftermath of the defeat of Persia in the battle of Salamis, with a sympathetic portrayal of its disgraced King Xerxes. Philip Vellacott''s evocative translation is accompanied by an introduction, with individual discussions of the plays, and their sources in history and mythology.', 'en', 1961, 160, 'http://books.google.com/books/content?id=0gbclW98ougC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '792', 'accepted', 'Aeschylus; Philip Vellacott', 'Drama', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 17 FROM public.book WHERE isbn13 = '9780140441123' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('001c2893-2b75-5afc-8396-68a7e1295a04', '9780140441222', 'Iphigenia, Phaedra, Athaliah', 'pNT4xgEACAAJ', 'Strongly influenced by Classical drama, Jean Racine (1639–99) broke away from the grandiose theatricality of baroque drama to create works of intense psychological realism, with characters manipulated by cruel and vengeful gods. Iphigenia depicts a princess’s absolute submission to her father’s will, despite his determination to sacrifice her to gain divine favour before going to war. Described by Voltaire as ‘the masterpiece of the human mind’, Phaedra shows a woman’s struggle to overcome her overwhelming passion for her stepson – an obsession that brings destruction to a noble family. And Athaliah portrays a ruthless pagan queen, who defies Jehovah in her desperate attempt to keep the throne of Jerusalem from its legitimate heir.', 'en', 1970, 320, 'http://books.google.com/books/content?id=pNT4xgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '793', 'accepted', 'Jean Racine', 'Drama', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 0 FROM public.book WHERE isbn13 = '9780140441222' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('203fd304-277c-59d8-972e-f1b638b476be', '9780140441376', 'The Nibelungenlied', 'nCV_E8HJkNUC', 'Written by an unknown author in the twelfth century, this powerful tale of murder and revenge reaches back to the earliest epochs of German antiquity, transforming centuries-old legend into a masterpiece of chivalric drama. Siegfried, a great prince of the Netherlands, wins the hand of the beautiful princess Kriemhild of Burgundy, by aiding her brother Gunther in his struggle to seduce a powerful Icelandic Queen. But the two women quarrel, and Siegfried is ultimately destroyed by those he trusts the most. Comparable in scope to the Iliad, this skilfully crafted work combines the fragments of half-forgotten myths to create one of the greatest epic poems - the principal version of the heroic legends used by Richard Wagner, in The Ring.', 'en', 1965, 404, 'http://books.google.com/books/content?id=nCV_E8HJkNUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '794', 'accepted', 'A. Hatto', 'Literary Collections', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 0 FROM public.book WHERE isbn13 = '9780140441376' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('87a712fd-9cda-5c00-867e-62afcdad8a2b', '9780140441529', 'The Wasps', 'jInV9Bd_Z88C', 'In ''The Wasps'' an old-fashioned father and his loose-living son come to blows--and end up in court; elsewhere Aristophanes milks the clash of generations for all it is worth by sending up the purveyors of new ideas like Socrates and Euripides (the most controversial of the great tragedians). In ''The Poet and the Women'' Euripides, accused of misogyny, gets a relative in drag to infiltrate an all-woman festival and find out what revenge is being plotted, with predictable bawdy results. In ''The Frogs, '' written in the darkest days of the Peloponnesian War, the god Dionysus descends to the Underworld to find a poet to bring back: does Athens in her hour of danger need the traditional wisdom of Aeschylus or the brilliant modern cleverness of Euripides? As the great debate proceeds, Aristophanes combines parody with slapstick and political discussion with pantomime high spirit, to produce a hilarious and unique masterpiece.', 'en', 1964, 224, 'http://books.google.com/books/content?id=jInV9Bd_Z88C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '795', 'accepted', 'Aristophanes', 'Drama', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 5 FROM public.book WHERE isbn13 = '9780140441529' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3e562e3d-fe07-5573-8ba1-87e0e61d6341', '9780140441734', 'Rameau''s Nephew / D''alembert''s Dream', 'uMbVzAEACAAJ', 'One of the key figures of the French Enlightenment, Denis Diderot was a passionate critic of conventional morality, society and religion. Among his greatest and most well-known works, these two dialogues are dazzling examples of his radical scientific and philosophical beliefs. In Rameau''s Nephew, the eccentric and foolish nephew of the great composer Jean-Philippe Rameau meets Diderot by chance, and the two embark on a hilarious consideration of society, music, literature, politics, morality and philosophy. Its companion-piece, D''Alembert''s Dream, outlines a material, atheistic view of the universe, expressed through the fevered dreams of Diderot''s friend D''Alembert. Unpublished during his lifetime, both of these powerfully controversial works show Diderot to be one of the most advanced thinkers of his age, and serve as fascinating testament to the philosopher''s wayward genius.', 'en', 1976, 237, 'http://books.google.com/books/content?id=uMbVzAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '796', 'accepted', 'Denis Diderot', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 6 FROM public.book WHERE isbn13 = '9780140441734' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9ff77874-5ece-560a-94bd-8efa71836072', '9780140441796', 'The Gambler, Bobok, A Nasty Story', '8Af3uAEACAAJ', 'The stories in this volume demonstrate Dostoyevsky’s genius for fusing caricature, irony and the grotesque to create a powerful dark humour. The Gambler is a breathtaking portrayal of an intense and futile obsession. Based on Dostoyevsky’s own experience of financial desperation and the compulsive desire to win money, it focuses on the characters that take their places at the gaming tables of ‘Roulettenburg’: the outspoken, aristocratic ‘Grandmamma’, the mercenary Mademoiselle Blanche, the cool, mysterious Polina and Alex, the author’s self-portrait; a man gripped by exhilaration and hopelessness. Bobok is a blackly comic satire in which a desolate writer becomes drawn into the conversations of the dead, and A Nasty Story is a humorous look at the disparity between a man’s exaggerated ideal of himself and the sad reality.', 'en', 1966, 240, 'http://books.google.com/books/content?id=8Af3uAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '797', 'accepted', 'Fiodor Mijaïlovich Dostoevskiï; Fyodor Dostoyevsky', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 14 FROM public.book WHERE isbn13 = '9780140441796' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b488b96d-418a-52f2-b576-621d49fe2a8d', '9780140442052', 'Cousin Pons', 'qVrTzAEACAAJ', 'Mild, harmless and ugly to behold, the impoverished Pons is an ageing musician whose brief fame has fallen to nothing. Living a placid Parisian life as a bachelor in a shared apartment with his friend Schmucke, he maintains only two passions: a devotion to fine dining in the company of wealthy but disdainful relatives, and a dedication to the collection of antiques. When these relatives become aware of the true value of his art collection, however, their sneering contempt for the parasitic Pons rapidly falls away as they struggle to obtain a piece of the weakening man''s inheritance. Taking its place in the Human Comedy as a companion to Cousin Bette, the darkly humorous Cousin Pons is among of the last and greatest of Balzac''s novels concerning French urban society: a cynical, pessimistic but never despairing consideration of human nature.', 'en', 2006, 336, 'http://books.google.com/books/content?id=qVrTzAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '798', 'accepted', 'Honore Balzac', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 4 FROM public.book WHERE isbn13 = '9780140442052' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3690baa6-c59d-5c4e-8159-a4a9608e5823', '9780140442243', 'Home of the Gentry', 'j7snw8iJobgC', 'The nobleman Lavretsky, broken and disillusioned by a failed marriage, returns from Paris to his Russian estate, where he begins to fall in love with a young woman named Liza.', 'en', 1970, 298, 'http://books.google.com/books/content?id=j7snw8iJobgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '799', 'accepted', 'Ivan Turgenev', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 12 FROM public.book WHERE isbn13 = '9780140442243' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bf004365-6fb2-52e9-981c-16c5c183cec0', '9780140442328', 'A Harlot High and Low', 'tcVnaPgSagAC', 'Handsome would-be poet Lucien Chardon is poor and naive, but highly ambitious. Failing to make his name in his dull provincial hometown, he is taken up by a patroness, the captivating married woman Madame de Bargeton, and prepares to forge his way in the glamorous beau monde of Paris. But Lucien has entered a world far more dangerous than he realized, as Madame de Bargeton''s reputation becomes compromised and the fickle, venomous denizens of the courts and salons conspire to keep him out of their ranks. Lucien eventually learns that, wherever he goes, talent counts for nothing in comparison to money, intrigue and unscrupulousness. Lost Illusions is one of the greatest novels in the rich procession of the Comedie humaine, Balzac''s panoramic social and moral history of his times.', 'en', 1970, 554, 'http://books.google.com/books/content?id=tcVnaPgSagAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '800', 'accepted', 'Honore Balzac', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 5 FROM public.book WHERE isbn13 = '9780140442328' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('438797c3-4a2e-5211-892e-d975160699ad', '9780140442373', 'Rabouilleuse', 'E7WaaxaiSVkC', 'Philippe and Joseph Bridau are two extremely different brothers. The elder, Philippe, is a superficially heroic soldier and adored by their mother Agathe. He is nonetheless a bitter figure, secretly gambling away her savings after a brief but glorious career in Napoleon’s army. His younger brother Joseph, meanwhile, is fundamentally virtuous - but their mother is blinded to his kindness by her disapproval of his life as an artist. Foolish and prejudiced, Agathe lives on unaware that she is being cynically manipulated by her own favourite child, but will she ever discover which of her sons is truly the black sheep of the family? A dazzling depiction of the power of money and the cruelty of life in nineteenth-century France, The Black Sheep compellingly explores is a compelling exploration of the nature of deceit.', 'en', 1970, 339, 'http://books.google.com/books/content?id=E7WaaxaiSVkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '801', 'accepted', 'Honoré de Balzac', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 1 FROM public.book WHERE isbn13 = '9780140442373' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('baf66e01-fffd-5364-b45f-6dd2bcf497a6', '9780140442410', 'Germania', '-TCOs_SFAy0C', 'The Agricola is both a portrait of Julius Agricola – the most famous governor of Roman Britain and Tacitus'' well-loved and respected father-in-law – and the first detailed account of Britain that has come down to us. It offers fascinating descriptions of the geography, climate and peoples of the country, and a succinct account of the early stages of the Roman occupation, nearly fatally undermined by Boudicca''s revolt in AD 61 but consolidated by campaigns that took Agricola as far as Anglesey and northern Scotland. The warlike German tribes are the focus of Tacitus'' attention in the Germania, which, like the Agricola, often compares the behaviour of ''barbarian'' peoples favourably with the decadence and corruption of Imperial Rome.', 'en', 1970, 174, 'http://books.google.com/books/content?id=-TCOs_SFAy0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
