INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('652663e7-1f1f-544e-9761-2290bfc14de1', '9780140442526', 'Notes from Underground', '-s47DK9xBS4C', 'A single, tormented, character dominates both of these short novels written at different stages of Dostoyevsky''s career', 'en', 1972, 287, 'http://books.google.com/books/content?id=-s47DK9xBS4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
