INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('65fe3088-1f41-5eb6-95ed-6b77846c17eb', '9780140442571', 'Philosophical Dictionary', 'a8BK7o9SFnIC', 'Voltaire''s Philosophical Dictionary, first published in 1764, is a series of short, radical essays - alphabetically arranged - that form a brilliant and bitter analysis of the social and religious conventions that then dominated eighteenth-century French thought. One of the masterpieces of the Enlightenment, this enormously influential work of sardonic wit - more a collection of essays arranged alphabetically, than a conventional dictionary - considers such diverse subjects as Abraham and Atheism, Faith and Freedom of Thought, Miracles and Moses. Repeatedly condemned by civil and religious authorities, Voltaire''s work argues passionately for the cause of reason and justice, and criticizes Christian theology and contemporary attitudes towards war and society - and claims, as he regards the world around him: ''common sense is not so common''.', 'en', 1972, 400, 'http://books.google.com/books/content?id=a8BK7o9SFnIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
