INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9e80e711-f43d-5973-836d-eb638f8d4206', '9780140442755', 'Phaedrus', 'fNHF-hAPJdgC', 'Set in the idyllic countryside outside Athens, the Phraedrusis a dialogue between the philosopher Socrates and his friend Phaedrus, inspired by their reading of a clumsy speech by the writer Lysias on the nature of love. Their conversation develops into a wide-ranging discussion on such subjects as the pursuit of beauty, the immortality of the soul and the attainment of truth, and ends with an in-depth consideration of the principles of rhetoric. Probably a work of Plato''s maturity, the Phaedrusrepresents a high point in his achievement as a writer. This volume also contains two of his letters, which discuss his involvement in politics, in particular his role as adviser to Dionysius II of Syracuse, which are crucial documents for our understanding of Plato''s life and career.', 'en', 1973, 160, 'http://books.google.com/books/content?id=fNHF-hAPJdgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '806', 'accepted', 'Plato', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 4 FROM public.book WHERE isbn13 = '9780140442755' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('97ac02f2-ebb7-59a2-a058-328ee333a922', '9780140443073', 'Love', 'ungt2wstvLQC', 'In 1818, when he was in his mid-thirties, Stendhal met and fell passionately in love with the beautiful Mathilde Dembowski. She, however, was quick to make it clear that she did not return his affections, and in his despair he turned to the written word to exorcise his love and explain his feelings. The result is an intensely personal dissection of the process of falling - and being - in love: a unique blend of poetry, anecdote, philosophy, psychology and social observation. Bringing together the conflicting sides of his nature, the deeply emotional and the coolly analytical, Stendhal created a work that is both acutely personal and universally applicable.', 'en', 1975, 336, 'http://books.google.com/books/content?id=ungt2wstvLQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
