INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('39661452-a01e-543a-87de-e9ce603199f3', '9780140443530', 'Notre-Dame de Paris', 'fYmEyx-TMlMC', 'Tells the story of the hunchback Quasimodeo, bell-ringer of Nortre-Dame, the archdeacon Claude Frollo, and the gypsy dancer Esmeralda who wins Quasimodo''s selfless devotion.', 'en', 1978, 493, 'http://books.google.com/books/content?id=fYmEyx-TMlMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
