INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b9e94c08-d03f-5df2-a687-4c8b66d2fe74', '9780140443943', 'Eugene Onegin', 'c3eIQgAACAAJ', 'Distinguished by James E. Falen''s masterful use of contemporary American English and handling of rhyme and meter, this new translation of Alexander Pushkin''s verse novel ably provides English readers with the chance to experience the work of the poet Russians regard as the fountainhead of their literature. The introduction includes Falen''s discussion of how his translation compares with those of his predecessors and a general analysis of the poem. Nearly one hundred notes annotate the text."', 'en', 1979, 240, 'http://books.google.com/books/content?id=c3eIQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
