INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('95805bad-97d6-51e1-861a-cb9a96643e87', '9780140444308', 'Les Miserables', 'X3KZKnFd7H8C', 'After nineteen years in prison, Jean Valjean has difficulty adjusting to the outside world, which scorns and shuns him', 'en', 1982, 1232, 'http://books.google.com/books/content?id=X3KZKnFd7H8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
