INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('87616189-bc8c-5275-889d-a491d44d77a6', '9780140444438', 'Divina Commedia. English', 'wMZdyAEACAAJ', 'Dante relates his mystical interpretation of the heavens, and his moment of transcendent glory, as he journeys, first with Beatrice, then alone, toward the Trinity. Including an interpretive commentary, a glossary and bibliography, this translation seeks to clarify the theological themes and make Dante accessible to the English-speaking public.', 'en', 1986, 433, 'http://books.google.com/books/content?id=wMZdyAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '817', 'accepted', 'Dante Alighieri', 'Poetry', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 18 FROM public.book WHERE isbn13 = '9780140444438' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4bc12a50-3aae-56c6-88b8-4106d1a88c8a', '9780140445145', 'Twilight of Idols and Anti-Christ', '-ur_M2YcDYIC', '''Twilight of the Idols'', an attack on all the prevalent ideas of his time, offers a lightning tour of his whole philosophy. It also prepares the way for ''The Anti-Christ'', a final assault on institutional Christianity. Both works show Nietzsche lashing out at self-deception, astounded at how often morality is based on vengefulness and resentment. Both reveal a profound understanding of human mean-spiritedness which still cannot destroy the underlying optimism of Nietzsche, the supreme affirmer among the great philosophers.', 'en', 1990, 208, 'http://books.google.com/books/content?id=-ur_M2YcDYIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '818', 'accepted', 'Friedrich Nietzsche', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 13 FROM public.book WHERE isbn13 = '9780140445145' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('848f8014-490c-5cc6-a37d-9ff239f5ed05', '9780140445220', 'Sketches from a Hunter''s Album', '3V1ufDxyAkgC', 'Turgenev’s first major prose work is a series of twenty-five Sketches: the observations and anecdotes of the author during his travels through Russia satisfying his passion for hunting. His album is filled with moving insights into the lives of those he encounters – peasants and landowners, doctors and bailiffs, neglected wives and bereft mothers – each providing a glimpse of love, tragedy, courage and loss, and anticipating Turgenev’s great later works such as First Love and Fathers and Sons. His depiction of the cruelty and arrogance of the ruling classes was considered subversive and led to his arrest and confinement to his estate, but these sketches opened the minds of contemporary readers to the plight of the peasantry and were even said to have led Tsar Alexander II to abolish serfdom.', 'en', 1990, 403, 'http://books.google.com/books/content?id=3V1ufDxyAkgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '819', 'accepted', 'Ivan Turgenev', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 17 FROM public.book WHERE isbn13 = '9780140445220' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8b972a85-daff-574c-b3db-10339507c5b5', '9780140445503', 'Gargantua and Pantagruel', 'fWwtsxg7zG0C', 'The dazzling and exuberant moral stories of Rabelais (c. 1471-1553) expose human follies with their mischievous and often obscene humour, while intertwining the realistic with carnivalesque fantasy to make us look afresh at the world. Gargantua depicts a young giant, reduced to laughable insanity by an education at the hands of paternal ignorance, old crones and syphilitic professors, who is rescued and turned into a cultured Christian knight. And in Pantagruel and its three sequels, Rabelais parodied tall tales of chivalry and satirized the law, theology and academia to portray the bookish son of Gargantua who becomes a Renaissance Socrates, divinely guided in his wisdom, and his idiotic, self-loving companion Panurge.', 'en', 2006, 1041, 'http://books.google.com/books/content?id=fWwtsxg7zG0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '820', 'accepted', 'Francois Rabelais; Michael Andrew Screech', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 14 FROM public.book WHERE isbn13 = '9780140445503' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c7f1e947-f20f-5b67-8d4c-ed543f85fbcc', '9780140445770', 'Either/Or', 'qUA-_xdRPgAC', 'In Either/Or, using the voices of two characters - the aesthetic young man of part one, called simply ''A'', and the ethical Judge Vilhelm of the second section - Kierkegaard reflects upon the search for a meaningful existence, contemplating subjects as diverse as Mozart, drama, boredom, and, in the famous Seducer''s Diary, the cynical seduction and ultimate rejection of a young, beautiful woman. A masterpiece of duality, Either/Or is a brilliant exploration of the conflict between the aesthetic and the ethical - both meditating ironically and seductively upon Epicurean pleasures, and eloquently expounding the noble virtues of a morally upstanding life.', 'en', 2004, 640, 'http://books.google.com/books/content?id=qUA-_xdRPgAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '821', 'accepted', 'Soren Kierkegaard', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 3 FROM public.book WHERE isbn13 = '9780140445770' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('49f9f5cc-54f3-5a41-9067-6be5d8caff2c', '9780140446043', 'The Complete Essays', 'K_BuQw1SV_8C', 'In 1572 Montaigne retired to his estates in order to devote himself to leisure, reading and reflection. There he wrote his constantly expanding ''essays'', inspired by the ideas he found in books from his library and his own experience. He discusses subjects as diverse as war-horses and cannibals, poetry and politics, sex and religion, love and friendship, ecstasy and experience. Above all, Montaigne studied himself to find his own inner nature and that of humanity. The Essays are among the most idiosyncratic and personal works in all literature. An insight into a wise Renaissance mind, they continue to engage, enlighten and entertain modern readers.', 'en', 2004, 1344, 'http://books.google.com/books/content?id=K_BuQw1SV_8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '822', 'accepted', 'Michel Montaigne', 'Literary Collections', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 1 FROM public.book WHERE isbn13 = '9780140446043' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b551a19c-98bb-5bb0-997c-3dca4fad11c9', '9780140446166', 'The Symposium', 'pdNgQgAACAAJ', 'In this text Plato uses a dinner party as a scene for a series of speeches by the guests. From these there emerges a complete and complex philosophy of love. The pivot of the argument is Socrates'' speech in which sensuality is transcended and we move from the sensible world to the ideal world. Just as the preceding speeches are vital to the theme and scheme of progression, so to is the character sketch of Socrates by Alcibiades which rounds off the dialogue.', 'en', 1999, 90, 'http://books.google.com/books/content?id=pdNgQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '823', 'accepted', 'Plato; Christopher Gill', 'Amour - Ouvrages avant 1800', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 15 FROM public.book WHERE isbn13 = '9780140446166' ON CONFLICT DO NOTHING;
