INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('017a57d1-7fb8-5ca3-b9e5-3ccba8c18d7b', '9780140447200', 'Maxims and Reflections', '-2RWY230tW0C', 'Throughout his long, hectic and astonishingly varied life, Johann Wolfgang von Goethe (1749�1832) would jot down his passing thoughts on theatre programmes, visiting cards, draft manuscripts and even bills � Goethe was probably the last true �Renaissance Man�. Although employed as a Privy Councillor at the Duke of Weimar�s court, where he helped oversee major mining, road-building and irrigation projects, he also painted, directed plays, carried out research in anatomy, botany and optics � and still found time to produce masterpieces in every literary genre. His fourteen hundred Maxims and Reflections reveal some of his deepest thought on art, ethics, literature and natural science, but also his immediate reactions to books, chance encounters or his administrative work. Although variable in quality, the vast majority have a freshness and immediacy which vividly conjure up Goethe the man. They make an ideal introduction to one of the greatest of European writers.', 'en', 2005, 208, 'http://books.google.com/books/content?id=-2RWY230tW0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '826', 'accepted', 'Johann Goethe', 'Literary Collections', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 3 FROM public.book WHERE isbn13 = '9780140447200' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('775ffb0d-772c-5b07-9fb4-80c69c9d502b', '9780140447262', 'The Bacchae and Other Plays', 'mWhUeP5STaEC', 'Through their sheer range, daring innovation, flawed but eloquent characters and intriguing plots, the plays of Euripides have shocked and stimulated audiences since the fifth century BC. Phoenician Women portrays the rival sons of King Oedipus and their mother�s doomed attempts at reconciliation, while Orestes shows a son ravaged with guilt after the vengeful murder of his mother. In the Bacchae, a king mistreats a newcomer to his land, little knowing that he is the god Dionysus disguised as a mortal, while in Iphigenia at Aulis, the Greek leaders take the horrific decision to sacrifice a princess to gain favour from the gods in their mission to Troy. Finally, the Rhesus depicts a world of espionage between the warring Greek and Trojan camps.', 'en', 2005, 360, 'http://books.google.com/books/content?id=mWhUeP5STaEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
