INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4d655b05-d824-5c16-9a16-ccabd9e26bfd', '9780140447606', 'Democracy in America', 'PotlkxV-wF0C', 'A study of America''s national government, egalitarian ideals, and character offers reflections on the effect of majority rule on the rights of individuals and provides insight into the rewards and responsibilities of a democratic government, in a new translation that also includes Two Weeks in the Wilderness, the author''s description of the Iroquois, and Excursion to Lake Oneida. Original.', 'en', 2003, 992, 'http://books.google.com/books/content?id=PotlkxV-wF0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '828', 'accepted', 'Alexis Tocqueville; Gerald Bevan; Isaac Kramnick', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 16 FROM public.book WHERE isbn13 = '9780140447606' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fa3b176c-406c-5f8f-9956-6c217ed3a8e4', '9780140447804', 'The Consolation of Philosophy', 'ut44nSC0Ue0C', 'The Consolation of Philosophy is perhaps unique in the nature and extent of its influence on Western thinking. An eminent public figure under the Gothic emperor Theodoric, Boethius (c. A D 475-525) was also an exceptional Greek scholar and it was to the Greek philosophers that he turned when he fell from favour and was imprisoned in Pavia. Written in the period leading up to his brutal execution, it is a dialogue of alternating prose and verse between the ailing prisoner and his ''nurse'' Philosophy, whose instruction on the nature of fortune and happiness, good and evil, fate and free will, restore his health and bring him to enlightenment. The clarity of Boethius''s thought and his breadth of vision made The Consolation of Philosophy hugely popular throughout medieval Europe and his ideas suffused the thought of Chaucer and Dante. This translation makes it accessible to the modern reader while losing nothing of Boethius''s poetic artistry and philosophical brilliance.', 'en', 1999, 192, 'http://books.google.com/books/content?id=ut44nSC0Ue0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '829', 'accepted', 'Boethius; Victor Watts', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 18 FROM public.book WHERE isbn13 = '9780140447804' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3217e0e4-4cc3-5503-a4a8-c80dcfe35781', '9780140447897', 'Metamorphosis', 'D3McXPPkPK8C', 'A new translation in hexameter verse of Ovid''s narrative poem embraces more than two hundred mythical tales linked by the theme of transformation, incorporating many famed myths and legends of ancient Greece and Rome.', 'en', 2004, 723, 'http://books.google.com/books/content?id=D3McXPPkPK8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '830', 'accepted', 'Ovid; David Raeburn', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 4 FROM public.book WHERE isbn13 = '9780140447897' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e65fe6ad-0939-5e1a-80b6-236abaaea3ea', '9780140447972', 'Sentimental Education', 'b6cBs1HnSyMC', 'Sentimental Education begins with the hero - Frederic Moreau - leaving Paris and returning to the provinces and his mother. Part love story, part historical novel and satire it tells of how Moreau is driven by passion for an unattainable older woman. His ''sentimental education'' turns out to be more of an anxious quest than a happy one, echoing Flaubert''s own life experience of unrequited love. Packed with vivid detail and characterised by its historical authenticity, the book was described by Flaubert as ''the moral history of the men of my generation''.', 'en', 1964, 460, 'http://books.google.com/books/content?id=b6cBs1HnSyMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
