INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('18955466-0bd7-5bd0-ac6f-b5170a8c1c54', '9780140448009', 'Three Tales', 'XFzgaUR-Vy0C', 'Features short fiction by the French naturalist author that is introduced by an essay describing his life, works, and artistic abilities, as well as explanatory notes, a chronology, and suggestions for further reading.', 'en', 2005, 110, 'http://books.google.com/books/content?id=XFzgaUR-Vy0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
