INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b53f457d-75b2-5632-aed3-be1f3fe37d0b', '9780140448078', 'Dead Souls', 'FP2wmNJclpwC', 'In a new translation of the comic classic of Russian literature, Chichikov, an enigmatic stranger and schemer, buys deceased serfs'' names from their landlords'' poll tax lists hoping to mortgage them for profit and to reinvent himself as a gentleman. Reprint.', 'en', 2004, 512, 'http://books.google.com/books/content?id=FP2wmNJclpwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
