INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a6adcfc5-40a7-5d5d-a1ec-84b021149427', '9780140448924', 'The Black Tulip', 'GNHcP8V-YQ0C', 'Set at the height of the "tulipomania" that gripped Holland in 17th century, this is the story of Cornelius van Baerle, a humble grower whose sole desire is to grow the perfect specimen of the tulip negra. When his godfather is murdered, Cornelius finds himself caught up in the deadly politics of the time, imprisoned and facing a death sentence. His jailor''s daughter Rosa, holds both the key to his survival and his chance to produce the ultimate tulip.', 'en', 2003, 246, 'http://books.google.com/books/content?id=GNHcP8V-YQ0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
