INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('83bea7c9-113c-5e71-b050-27b098498491', '9780140449518', 'The Birds and Other Plays', 'i15nevzKzvoC', 'Collects five comedies from Aristophanes, including "The Birds," in which two Athenians join the birds to build a utopian city.', 'en', 1978, 336, 'http://books.google.com/books/content?id=i15nevzKzvoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
