INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9172d1d9-6be0-5b29-a39a-890edc2534a0', '9780140449778', 'The Women''s War', 'hEP4AGLZ00EC', 'The Baron des Canolles is a man torn apart by the civil war that dominates mid-seventeenth century France. For while the na�ve Gascon soldier cares little for the politics behind the battles, he is torn apart by a deep passion for two powerful women on opposing sides of the war: Nanon de Lartigues, a keen supporter of the Queen Regent Anne of Austria, and the Victomtesse de Cambes, who supports the rebellious forces of the Princess de Cond�. Set around Bordeaux during the first turbulent years of the reign of Louis XIV, The Women�s War sees two women taking central stage in a battle for all France. Humorous, dramatic and romantic, it offers a compelling exploration of political intrigue, the power of redemption, the force of love and the futility of war.', 'en', 2006, 546, 'http://books.google.com/books/content?id=hEP4AGLZ00EC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
