INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b20ec831-164e-52da-9f39-dcb24367c4b9', '9780140620634', 'Dracula', '0fbAkQEACAAJ', 'Irish author Bram Stoker introduced the character of Count Dracula and provided the basis of modern vampire fiction in his 1897 novel entitled "Dracula." Written as a series of letters, newspaper clippings, diary entries, and ships'' logs, the story begins with lawyer Jonathan Harker journeying to meet Dracula at his remote castle to complete a real estate transaction. Harker soon discovers that he is being held prisoner, and that Dracula has a rather disquieting nocturnal life. Touching on themes such as Victorian culture, immigration, and colonialism, among others, this timeless classic is sure to keep readers on the edge of their seats! Now available as part of the Canterbury Classics singles series, "Dracula" is a must-have addition to the libraries of all classic literature lovers.', 'en', 1994, 449, 'http://books.google.com/books/content?id=0fbAkQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
