INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c64a53da-af42-55bc-b47f-580ee193a7fb', '9780141000183', 'Chocolat', 'Shqhw6PEXY0C', 'When the beautiful and mysterious Vianne moves to Lansquenet and opens a chocolate shop across from the church, the inhabitants of the tiny village find themselves torn between the solemn law of religion and the joyful rewards of Vianne''s confections. Reprint. (A Miramax film, releasing December 2000, directed by Lasse Hallstrm, starring Juliette Binoche, Johnny Depp, Alfred Molina, Lena Olin, & Judi Dench) (General Fiction)', 'en', 2000, 306, 'http://books.google.com/books/content?id=Shqhw6PEXY0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
