INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5ad1d8bd-c395-5922-841b-8ce2ae9b675d', '9780141000589', 'Sammlung', 'qOVvDwAAQBAJ', 'This major new complete edition of Shakespeare''s works combines accessibility with the latest scholarship. Each play and collection of poems is preceded by a substantial introduction that looks at textual and literary-historical issues. The texts themselves have been scrupulously edited and are accompanied by same-page notes and glossaries. Particular attention has been paid to the design of the book to ensure that this first new edition of the twenty-first century is both attractive and approachable.', 'en', 2002, 1808, 'http://books.google.com/books/content?id=qOVvDwAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
