INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8a52c40b-15c5-58c1-b399-5cd2fba0e4be', '9780141001821', 'In the Heart of the Sea', 'EaqOURNUL88C', 'Recounts the story of the 1820 wreck of the whaleship Essex, which inspired Melville''s classic "Moby-Dick," and describes its doomed crew''s ninety-day attempt to survive whale attacks and the elements on three tiny lifeboats.', 'en', 2001, 302, 'http://books.google.com/books/content?id=EaqOURNUL88C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
