INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('af823b1a-cfaa-5d99-a4ef-a1c5f5e427a2', '9780141005348', 'How to Build a Time Machine', 'C1Wx4bkPyM0C', 'Is time travel really possible? Can we break the last cosmic taboo? Yes, says internationally acclaimed writer and physicist Paul Davies. In this highly entertaining and mind-blowing book he reveals how it can be done. Taking us on an astonishing ride into the far reaches of Einstein''s universe, this is the ultimate time-traveller''s companion.', 'en', 2002, 148, 'http://books.google.com/books/content?id=C1Wx4bkPyM0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
