INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('166256ae-4493-5611-bec3-a379c7028d5a', '9780141007458', 'Stiff', 'X157PwAACAAJ', 'What happens to your body after you have died? Fertilizer? Crash Test Dummy? Human Dumpling? Ballistics Practise?Life after death is not as simple as it looks. Mary Roach''s Stiff lifts the lid off what happens to our bodies once we have died. Bold, original and with a delightful eye for detail, Roach tells us everything we wanted to know about this new frontier in medical science. Interweaving present-day explorations with a history of past attempts to study what it means to be human Stiff is a deliciously dark investigations for readers of popular science as well as fans of the macabre', 'en', 2004, 304, 'http://books.google.com/books/content?id=X157PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
