INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d8e207c1-18cb-5a63-ace7-f80ea885c801', '9780141007472', 'Under The Duvet', 'W9p21K45kkwC', 'Setting the record straight about her life as a novelist (less glitz and glamour than sitting alone in a darkened bedroom with a laptop in front of her) Marian Keyes here presents a selection of her articles. These regular bulletins from a woman under the duvet include unpublished pieces.', 'en', 2002, 304, 'http://books.google.com/books/content?id=W9p21K45kkwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
