INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('72395845-130e-5418-bcde-bc7ed08dd2bd', '9780141010311', 'Golden Buddha', 'NXNoVOa9IBoC', 'The author of the bestselling Dirk Pitt novels introduces us to a thrilling new high seas action hero: Juan Cabrillo. Skipper of a non-descript lumber hauler disguising a state of the art spy ship behind the hull, Cabrillo takes the helm on dangerous covert missions carried out for whatever U.S. agency pays the price. And the stakes have never been higher - Cabrillo and his crew must put Tibet back in the hands of the Delai Lama by striking a deal with the Russians and the Chinese. His gambling chip is a golden Buddha containing records of vast oil reserves in the disputed land. But first, he has to locate and seize the artefact. Visit clivecussler.com.au for more Sign up to the Cussler Down Under e-newsletter', 'en', 2005, 527, 'http://books.google.com/books/content?id=NXNoVOa9IBoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '875', 'accepted', 'Clive Cussler; Craig Dirgo', 'Cabrillo, Juan (Fictitious character)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 9 FROM public.book WHERE isbn13 = '9780141010311' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e2265e73-8045-59fd-a719-70fab834827b', '9780141010373', 'Jamie''s Kitchen', 'WG3SNQAACAAJ', 'The No 1 bestseller I love this book. It''s the very first thing I ever wrote, and I never thought the person worst at English in my school would end up writing a book. It''s largely made up of recipes scribbled on the back of order forms and beer mats, collected together in a black bin liner that my wife almost threw away twice - it''s a miracle this book ever came to be! Because of this book, a lot of blokes were henpecked into doing a bit of cooking. Good job too! The salad and pasta recipes are real winners, but the one people still talk about all the time is my perfect roast chicken, with its herb butter stuffed right under the skin of the bird. I think one of the best things about the recipes in The Naked Chef is that the ingredients are totally accessible. It''s the key element to my cooking: simple, quick recipes that can be made by everyone. Happy cooking. Love, Jamie O xxx ''Simply brilliant cooking, and Jamie''s recipes are a joy'' Nigel Slater ''When teenagers start asking for Jamie Oliver''s cook books as a present, you know the tide has turned'' Daily Telegraph', 'en', 2004, 336, 'http://books.google.com/books/content?id=WG3SNQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
