INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('db9c279d-f21e-5c5b-abdb-d0a50652e62d', '9780141013954', 'The Merchant of Venice', '2Tk9PgAACAAJ', 'William Shakespeare''s The Merchant of Venice is both a witty comedy and a moving exploration of bigotry and stigmatisation, and this Penguin Shakespeare edition is edited by W. Moelwyn Merchant with an introduction by Peter Holland. ''The quality of mercy is not strain''d, It droppeth as the gentle rain from heaven'' Bassanio, a noble but impoverished Venetian, asks his friend the merchant Antonio for a loan to impress an heiress. Antonio agrees, but is forced to borrow the sum from a cynical Jewish moneylender, Shylock, who forces him into a chilling contract, which stipulates he must honour the debt with a pound of his own flesh. But Bassanio''s beloved is not as demure as she seems, and disguising herself as a lawyer, Portia proves herself one of Shakespeare''s most cunning heroines, in a witty attack on Shylock''s claim. A complex and controversial comedy, The Merchant of Venice explores prejudice and the true nature of justice. This book contains a general introduction to Shakespeare''s life and Elizabethan theatre, a separate introduction to The Merchant of Venice, a chronology, suggestions for further reading, an essay discussing performance options on both stage and screen, and a commentary. William Shakespeare (1564-1616) was born to John Shakespeare and Mary Arden some time in late April 1564 in Stratford-upon-Avon. He wrote about 38 plays (the precise number is uncertain), many of which are regarded as the most exceptional works of drama ever produced, including Romeo and Juliet (1595), Henry V (1599), Hamlet (1601), Othello (1604), King Lear (1606) and Macbeth (1606), as well as a collection of 154 sonnets, which number among the most profound and influential love-poetry in English. If you enjoyed The Merchant of Venice, you might like The Taming of the Shrew, also available in Penguin Shakespeare. ''The man who of all modern, and perhaps ancient poets, had the largest and most comprehensive soul'' John Dryden', 'en', 2005, 240, 'http://books.google.com/books/content?id=2Tk9PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '879', 'accepted', 'William Shakespeare; Peter Holland', 'Jews', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 16 FROM public.book WHERE isbn13 = '9780141013954' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('08d994fc-4a82-57f4-8e4e-29841ed3c3c9', '9780141014081', 'Complete Maus', 'rBj-nQEACAAJ', 'Combined here are Maus I: A Survivor''s Tale and Maus II - the complete story of Vladek Spiegelman and his wife, living and surviving in Hitler''s Europe. By addressing the Holocaust through cartoons the author captures the everyday reality of fear and the sensation of survival.', 'en', 2003, 296, 'http://books.google.com/books/content?id=rBj-nQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
