INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bbfb329d-9a6a-59fe-8249-185516c47db4', '9780141015088', 'How to Breathe Underwater', 't1v9VmPRz5QC', 'In her dazzling first book Julie Orringer dives into the private world of childhood and immerses us in its fears and longings: the jealous friendships and the bitter sibling battles; the parents that row and the boys that won''t dance with you. Then, in a voice that is equally tender and compassionate, she reminds us of those rare, exhilarating moments of victory.''Unbelievably good: the humiliations and cruelties and passions of childhood, sparkling fresh prose, a writer with a big heart and an acute sense of the small things that loom large in our lives'' Monica Ali, Guardian', 'en', 2005, 222, 'http://books.google.com/books/content?id=t1v9VmPRz5QC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
