INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d5b98653-8eec-5661-9d37-0753a6c5020a', '9780141180366', 'Finding time again', 'heRcAAAAMAAJ', 'Since the original, prewar translation there has been no completely new rendering of the French original into English. This translation brings to the fore a more sharply engaged, comic and lucid Proust. IN SEARCH OF LOST TIME is one of the greatest, most entertaining reading experiences in any language. As the great story unfolds from its magical opening scenes to its devastating end, it is the Penguin Proust that makes Proust accessible to a new generation. Each book is translated by a different, superb translator working under the general editorship of Professor Christopher Prendergast, University of Cambridge.', 'en', 2003, 374, 'http://books.google.com/books/content?id=heRcAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
