INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5b35c50b-25fe-56d5-8cae-ef75f0c20aef', '9780141180946', 'Forty Stories', 'K99DPgAACAAJ', 'This collection of pithy, brilliantly acerbic pieces is a companion to Sixty Stories, Barthelme''s earlier retrospective volume. Barthelme spotlights the idiosyncratic, haughty, sometimes downright ludicrous behavior of human beings, but it is style rather than content which takes precedence.', 'en', 2005, 246, 'http://books.google.com/books/content?id=K99DPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
