INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4cbf19de-e8aa-599c-9f4e-8bee16c03bde', '9780141182803', 'Ulysses', 'HD3cW0XWvz0C', 'Written over a seven-year period, from 1914 to 1921, this book has survived bowdlerization, legal action and controversy. The novel deals with the events of one day in Dublin, 16th June 1904, now known as "Bloomsday". The principal characters are Stephen Dedalus, Leopold Bloom and his wife Molly. Ulysses has been labelled dirty, blasphemous and unreadable. In a famous 1933 court decision, Judge John M. Woolsey declared it an emetic book--although he found it not quite obscene enough to disallow its importation into the United States--and Virginia Woolf was moved to decry James Joyce''s "cloacal obsession". None of these descriptions, however, do the slightest justice to the novel. To this day it remains the modernist masterpiece, in which the author takes both Celtic lyricism and vulgarity to splendid extremes. It is funny, sorrowful, and even (in its own way) suspenseful. And despite the exegetical industry that has sprung up in the last 75 years, Ulysses is also a compulsively readable book.', 'en', 2000, 933, 'http://books.google.com/books/content?id=HD3cW0XWvz0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '894', 'accepted', 'James Joyce', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 10 FROM public.book WHERE isbn13 = '9780141182803' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5c1e08a9-d1b2-5520-84c8-8ccca92c8096', '9780141182865', 'A Confederacy of Dunces', 'tv77QQAACAAJ', 'Ignatius Reilly, the hero, is a grotesque Gargantua, in violent revolt against the entire 20th century and what he takes to be the manifold excesses and perversions of the past 400 years. He lumbers through New Orleans leaving chaos in his wake.', 'en', 2000, 338, 'http://books.google.com/books/content?id=tv77QQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
