INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8ba17234-9b9f-521b-95f1-0893c9b8d188', '9780141183022', 'Sammlung', 'BBipQgAACAAJ', 'Though best known in the English speaking world for his short fictions and poems, Borges is revered in Latin America equally as an immensely prolific and beguiling writer of non-fiction prose. In THE TOTAL LIBRARY, more than 150 of Borges'' most brilliant pieces are brought together for the first time in one volume - all in superb new translations. More than a hundred of the pieces have never previously been published in English. THE TOTAL LIBRARY presents Borges at once as a deceptively self-effacing guide to the universe and as the inventor of a universe that is an indispensible guide to Borges', 'en', 1999, 560, 'http://books.google.com/books/content?id=BBipQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
