INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('69931a15-cb25-557a-90b0-288d706a1e57', '9780141183220', 'Speak, Memory', 'hjBIWkO2wgsC', 'An autobiographical volume covering Nabokov''s first 40 years up to his departure from Europe for America at the outset of World War II, telling of his emergence as a writer, his early loves and his marriage, his passion for butterflies and his lost homeland.', 'en', 2000, 255, 'http://books.google.com/books/content?id=hjBIWkO2wgsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
