INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6e12285e-d59f-52ac-b7c7-ac3ec05dc62c', '9780141183718', 'A Spy In The House Of Love', 'm5h3-edKIpcC', 'Beautiful, bored and bourgeoise, Sabina leads a double life inspired by her relentless desire for brief encounters with near-strangers. Fired into faithlessness by a desperate longing for sexual fulfilment, she weaves a sensual web of deceit across New York. But when the secrecy of her affairs becomes too much to bear, Sabina makes a late night phone-call to a stranger from a bar, and begins a confession that captivates the unknown man and soon inspires him to seek her out...', 'en', 2001, 124, 'http://books.google.com/books/content?id=m5h3-edKIpcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
