INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('19be2c82-d68d-5e73-a118-0b175758c0ec', '9780141183725', 'Keep the Aspidistra Flying', '0oNp8FTIhlcC', 'London 1934. Gordon Comstock, copywriter for the The Queen of Sheba Toilet Requisites embarks on a new life as a poetry-writing bookseller with diastrous consequences.', 'en', 2000, 277, 'http://books.google.com/books/content?id=0oNp8FTIhlcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
