INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0709c4ed-719c-56e0-926b-032518d49c80', '9780141184272', 'Orlando', 'fGVgQgAACAAJ', 'Classic fiction. Orlando, deciding not to grow old, pursues his quest for passion, adventure, fulfilment and protracted youth. Chasing a dream through the centuries, he bounds from Elizabethan England and imperial Turkey to the modern world. Will he find happiness with the exotic Russian Princess Sasha? Or is the dashing explorer Shelmerdine the ideal man? And what form will Orlando take on the journey - a nobleman; gypsy; writer? Man or ... woman?', 'en', 2000, 228, 'http://books.google.com/books/content?id=fGVgQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
