INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8a14a162-3718-5765-abcb-b396c77d0007', '9780141184289', 'The Good Soldier Svejk', 'lRXvOwAACAAJ', 'This text is the classic novel of the little man fighting officialdom and bureaucracy with the only weapons available to him - passive resistance, subterfuge, native wit and dumb insolence.', 'en', 2000, 752, 'http://books.google.com/books/content?id=lRXvOwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
