INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7a361000-32ef-58ae-ba3d-be3991a1fae4', '9780141184296', 'Rhinoceros', '_-54PwAACAAJ', 'This volume contains English translations of three plays by Ionesco, one of the founding fathers of the theatre of the absurd. Tragic, farcical, alive and kicking, they can be read as a way to liberation.', 'en', 2000, 224, 'http://books.google.com/books/content?id=_-54PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
