INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0ea372c1-f3ad-5d56-986c-45753851ea80', '9780141184883', 'The Dharma Bums', 'hrJdIzWZWS4C', 'Published just one year after "On The Road", this is the story of two men enganged in a passionate search for Dharma or truth. Their major adventure is the pursuit of the Zen Way, which takes them climbing into the High Sierras to seek the lesson of solitude.', 'en', 2000, 204, 'http://books.google.com/books/content?id=hrJdIzWZWS4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
