INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('688f13b8-0b30-5fb2-b35b-1f9a08f0b87f', '9780141185118', 'Tortilla Flat', 'M5XwSwVsJagC', 'Adopting the structure and themes of the Arthurian legend, Steinbeck created a "Camelot" on a shabby hillside above Monterey on the California coast and peopled it with a colorful band of knights. As Steinbeck chronicles their thoughts and emotions, temptations and lusts, he spins a tale as compelling, and ultimately as touched by sorrow, as the famous legends of the Round Table.', 'en', 2000, 154, 'http://books.google.com/books/content?id=M5XwSwVsJagC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
