INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a362b99e-b36e-5eb1-a066-07ffca51f291', '9780141185163', 'Orwell in Spain', 'uVNpAAAAMAAJ', 'Including Homage to Catalonia, Orwell''s profound experience of fighting in the Spanish Civil War, this title also contains Orwell''s essays, letters and pamphlets, which show his resolution to tell the truth about the war amid a crop of lies from both the Communist Party and the British Press.', 'en', 2001, 416, 'http://books.google.com/books/content?id=uVNpAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
