INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9f5fd74b-0c72-5db8-98dd-ad2d7f6d0997', '9780141185323', 'The Years', '0Djjz5VusG0C', 'The story of the Pargiter family - their intimacies and estrangements, anxieties and triumphs - mapped out amongst the bustling rhythms of London''s streets during the first decade of the 20th century. The Pargiter children must learn to find their footing in a world of rapidly changing rules.', 'en', 2002, 444, 'http://books.google.com/books/content?id=0Djjz5VusG0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
