INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8d8cae44-d024-56f1-80d0-b90972021cc8', '9780141185750', 'The House of Bernarda Alba and Other Plays', 'JOrGHAAACAAJ', 'The revolutionary genius of Spanish theatre, Lorca brought vivid and tragic-poetry to the stage with these powerful dramas. All appeal for freedom and sexual and social equality, and are also passionate defences of the imagination.', 'en', 2001, 169, 'http://books.google.com/books/content?id=JOrGHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
