INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a4dde4b7-1f5a-591f-abc2-769df23edf71', '9780141185934', 'Answered Prayers', 'YaymPwAACAAJ', 'A brilliantly malicious expose of the literary jet-set, when Answered Prayers first appeared in excerpts in Esquire magazine it outraged Capote''s society friends, who recognized thinly veiled portraits of themselves in these scandalous fictional ''memoirs''. P.B. Jones is the amoral, bisexual protagonist of this great, unfinished novel, who discovers that bed-hoping rather than literary ability is the way to get published. Living by his wits and his charm, Jones makes his way through the exotic boudoirs of the glitterati - only to discover that the prayers that are answered cause more pain than those that remained ignored.', 'en', 2001, 192, 'http://books.google.com/books/content?id=YaymPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
