INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f7f4fd53-4911-50eb-810a-07f348a3583c', '9780141186351', 'Giovanni''s Room', 'j_2lPBQUrMEC', 'First published in 1957, this book attempts to tackle the conflict between homosexual and heterosexual love. It tells of David, a young man awakening to his true homosexual nature, through a relationship with a barman named Giovanni, as he awaits his fiancee''s arrival from Spain.', 'en', 2001, 159, 'http://books.google.com/books/content?id=j_2lPBQUrMEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
