INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('27c93249-3c87-516d-83ee-00b4aa2aea8b', '9780141186696', 'The Bell', '6h_qw0DsgOsC', 'The story of a lay community of mixed-up people encamped outside Imber Abbey, home of an enclosed order of nuns, follows the lives of Dora Greenfield, an erring wife who returns to her husband, and Michael Meade, who is confronted by his homosexual former lover. Repriint.', 'en', 2001, 296, 'http://books.google.com/books/content?id=6h_qw0DsgOsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
