INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d050d09a-9bd7-5cf9-8f9e-b604d24566ad', '9780141187068', 'The Call of Cthulhu and Other Weird Stories', '-O9fQgAACAAJ', 'H P Lovecraft is credited with reinventing the horror genre in the twentieth century. In this volume, Lovecraft''s preeminent interpreter, S T Joshi, presents a selection of the master''s fiction. These stories reveal the development of Lovecraft''s mesmerizing narrative style and establish him as a canonical - and visionary - American writer.', 'en', 2002, 420, 'http://books.google.com/books/content?id=-O9fQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
