INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bca62aba-d4e8-58ce-8b48-8e1f2c56c4d5', '9780141187198', 'Seven Gothic Tales', '4uKAnVKabtsC', 'A selection of stories about romantics, adventurers and dreamers, ranging from Tuscany to Elisnore and Zanzibar: a jealous countess cannot bear her husband to admire her jewels; an Englishman embarks on an odyssey; a maiden lady believes herself to be a famous courtesan; and more.', 'en', 2002, 368, 'http://books.google.com/books/content?id=4uKAnVKabtsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '927', 'accepted', 'Isak Dinesen', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 15 FROM public.book WHERE isbn13 = '9780141187198' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2c6eaf1d-3bd2-578b-bbb7-a065c126cc4a', '9780141187426', 'Orientalism', 'TFq8QgAACAAJ', 'For generations now, Edward W. Said''s Orientalism has defined our understanding of colonialism and empire, and this Penguin Modern Classics edition contains a preface written by Said shortly before his death in 2003. In this highly-acclaimed work, Edward Said surveys the history and nature of Western attitudes towards the East, considering orientalism as a powerful European ideological creation - a way for writers, philosophers and colonial administrators to deal with the ''otherness'' of eastern culture, customs and beliefs. He traces this view through the writings of Homer, Nerval and Flaubert, Disraeli and Kipling, whose imaginative depictions have greatly contributed to the West''s romantic and exotic picture of the Orient. Drawing on his own experiences as an Arab Palestinian living in the West, Said examines how these ideas can be a reflection of European imperialism and racism. Edward W. Said (1935-2003) was a Palestinian-American cultural critic and author, born in Jerusalem and educated in Egypt and the United States. His other books include The Question of Palestine, Culture and Imperialism and Out of Place: A Memoir. If you enjoyed Orientalism, you might like Frantz Fanon''s The Wretched of the Earth, also available in Penguin Modern Classics. ''Stimulating, elegant and pugnacious''Observer ''Beautifully patterned and passionately argued''New Statesman ''Very exciting ... his case is not merely persuasive, but conclusive'' John Leonard, New York Times ''Magisterial''Terry Eagleton', 'en', 2003, 396, 'http://books.google.com/books/content?id=TFq8QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '928', 'accepted', 'Edward W. Said', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 19 FROM public.book WHERE isbn13 = '9780141187426' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1bff5569-9026-5f2a-9450-14024de14053', '9780141187884', 'One Flew Over the Cuckoo''s Nest', 'ho6RQgAACAAJ', 'Tyrannical Nurse Ratched rules her ward in an Oregon State mental hospital with a strict and unbending routine, unopposed by her patients, who remain cowed by mind-numbing medication and the threat of electric shock therapy. But her regime is disrupted by the arrival of McMurphy - the swaggering, fun-loving trickster with a devilish grin who resolves to oppose her rules on behalf of his fellow inmates. His struggle is seen through the eyes of Chief Bromden, a seemingly mute half-Indian patient who understands McMurphy''s heroic attempt to do battle with the powers that keep them imprisoned. Ken Kesey''s extraordinary first novel is an exuberant, ribald and devastatingly honest portrayal of the boundaries between sanity and madness.', 'en', 2005, 281, 'http://books.google.com/books/content?id=ho6RQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
