INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9dd980e7-cab1-5351-b10e-e28b013b9cff', '9780141303352', 'Mr Majeika and the School Trip', 'YJ8eqb-iyJ8C', 'More amazing adventures with Mr Majeika, the ex-wizard, turned teacher, and his class at St Barty''s School. This time there''s a trip down a magic river, a battle to save St Barty''s from the wrecking ball, and work experience for Class Three.', 'en', 1999, 89, 'http://books.google.com/books/content?id=YJ8eqb-iyJ8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
