INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4f4dee33-c768-5e06-8a69-deb59011938c', '9780141307411', 'Crazy', 'VnpzPgAACAAJ', 'Benjamin Lebert introduces himself on the first day at his new school: Hi, I''m Benjamin Lebert, I''m 16 and a cripple. Just so you know... He is paralysed down his left side, but nevertheless lives his life to the full as a rebellious schoolboy, smoking, drinking, running away, meeting girls and having sex - and all the while pondering the meaning of life.', 'en', 2000, 175, 'http://books.google.com/books/content?id=VnpzPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
