INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4f78a810-8935-5429-8edb-20ee1690a676', '9780141310688', 'Westmark', 'v5U-PQAACAAJ', 'Theo, a boy fleeing from criminal charges, falls in with a charlatan, his dwarf attendant, and an urchin girl; travels with them about the kingdom of Westmark; and ultimately arrives at the palace where the king is grieving over the loss of his daughter. An ALA Notable Book. Reissue.', 'en', 2002, 184, 'http://books.google.com/books/content?id=v5U-PQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
