INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ea10392a-3b69-5a53-92d4-5e9c7a6ae8e0', '9780141311401', 'Boy', 'GmE-PgAACAAJ', '''Throughout my young days at school and just afterwards, a number of things happened to me that I have never forgotten.'' Many remarkable things did happen to Roald Dahl when he was a boy, no doubt providing some of the marvellous ideas for his later books. And, like his stories, Dahl''s childhood tales are unmissable.', 'en', 2001, 176, 'http://books.google.com/books/content?id=GmE-PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
