INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9ab6a755-e4d4-5da8-ba68-2d0e46de7bd5', '9780142003800', 'Drop City', 'MyrgIOFAV70C', 'The members of the Drop City commune clash with Alaskan homesteaders who live near to where the commune has recently moved, as both groups struggle for love, nourishment, and shelter. By the author of A Friend of the Earth. Reprint. 150,000 first printing.', 'en', 2004, 497, 'http://books.google.com/books/content?id=MyrgIOFAV70C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
