INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e1a3627b-16e2-5d40-9942-f3bfb437a5e5', '9780142004203', 'The Life of Graham Greene: 1904-1939', 'sJYgxgEACAAJ', 'Graham Greene was one of the most guarded and complex literary figures of our time. In the first volume of Norman Sherry''s celebrated biography, Greene''s early life is explored through letters, diaries, and hundreds of interviews, including a breakdown in his early teens, his years at Oxford, and, most particularly, his long and tortuous courtship of his future wife. Sherry uncovers the origins of Greene''s literary preoccupations, as well as reasons for his conversion to Roman Catholicism. Greene''s development as a novelist, from the early success of The Man Within to his masterpiece, The Power and the Glory, is also explored in full, as Sherry literally follows Greene''s footsteps to West Africa and Mexico, penetrating the strange and emotional territory that Greene made into his own.', 'en', 2004, 816, 'http://books.google.com/books/content?id=sJYgxgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
