INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('843a10cd-3848-571d-918a-41517384f0f2', '9780142180044', 'Zazie in the Metro', 'yeQH9-jeaucC', 'Impish, foul-mouthed Zazie arrives in Paris from the country to stay with Gabriel, her female-impersonator uncle. All she really wants to do is ride the metro, but finding it shut because of a strike, Zazie looks for other means of amusement and is soon caught up in a comic adventure that becomes wilder and more manic by the minute. In 1960 Queneau''s cult classic was made into a hugely successful film by Louis Malle. Packed full of word play and phonetic games, Zazie in the Metro remains as stylish and witty as ever.', 'en', 2001, 157, 'http://books.google.com/books/content?id=yeQH9-jeaucC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
