INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bb3d4196-dcec-52ab-9c45-1b2b2cffa399', '9780142437766', 'In the Land of Time, and Other Fantasy Tales', 'QxyQcySJF1gC', 'A pioneer in the realm of imaginative literature, Lord Dunsany has gained a cult following for his influence on modern fantasy literature, including such authors as J.R.R. Tolkien and H. P. Lovecraft. This unique collection of short stories ranges over five decades of work. Liberal selections of earlier tales—including the entire Gods of Pegana as well as such notable works as "Idle Days of the Yann" and "The Fortress Unvanquishable, Save for Sacnoth"—are followed by memorable later tales, including several about the garrulous traveler Joseph Jorkens and the outrageous murder tale "The Two Bottles of Relish." Throughout, the stories are united by Dunsany''s cosmic vision, his impeccable and mellifluous prose, and his distinctively Irish sense of whimsy. First time in Penguin Classics The only annotated edition of Dunsany''s short stories', 'en', 2004, 432, 'http://books.google.com/books/content?id=QxyQcySJF1gC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
