INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ca7e441b-06b8-58fb-a4b4-699a573471f9', '9780142437889', 'Aleph and other stories', 'XYZlAAAAMAAJ', 'Twenty fictional pieces survey the depth and range of the distinguished Argentine writer''s forty-year career as he journeys inside the minds of an unrepentant Nazi, an imprisoned Maya priest, fanatical Christian theologians, a man awaiting his assassin, and a woman plotting vengeance on her father''s "killer." Reprint.', 'en', 2000, 210, 'http://books.google.com/books/content?id=XYZlAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
