INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2f9a50f9-06ba-5259-8925-a66972fe11c6', '9780142437896', 'A Universal History of Iniquity', 'DLRIPgAACAAJ', 'In his writing, Borges always combined high seriousness with a wicked sense of fun. Here he reveals his delight in re-creating (or making up) colorful stories from the Orient, the Islamic world, and the Wild West, as well as his horrified fascination with knife fights, political and personal betrayal, and bloodthirsty revenge. Sparkling with the sheer exuberant pleasure of story-telling, this collection marked the emergence of an utterly distinctive literary voice.', 'en', 2004, 128, 'http://books.google.com/books/content?id=DLRIPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
