INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4e20799c-8ace-59d2-b97a-fe9420ddd958', '9780143036067', 'Windblown World', '6IhnPwAACAAJ', 'Excerpts and passages from the personal diaries of the great Beat writer chronicle a pivotal era in Kerouac''s life, describing the creation of his first novel, The Town and City; his special friendships with Allen Ginsberg, William S. Burroughs, and Neal Cassady; and his own take on the events described in On the Road. Reprint.', 'en', 2006, 480, 'http://books.google.com/books/content?id=6IhnPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
