INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('72e46cc6-4815-59a6-9397-a66847e1def0', '9780143036081', 'The United States of Europe', 'Yra-GwAACAAJ', 'Now comprising 25 nations and 450 million citizens, the European Union has more people, wealth and votes than the United States. The author explores the challenge it poses to American political and economic supremacy.', 'en', 2005, 320, 'http://books.google.com/books/content?id=Yra-GwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
