INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2f71d938-ef1e-59e1-98cb-d90422948976', '9780143036241', 'The Christians and the Fall of Rome', 'DAeWAAAACAAJ', 'Penguin brings you the works of the great thinkers, pioneers, radicals and visionaries whose ideas shook civilization, and helped make us who we are. Penguin''s Great Ideas series features twelve groundbreaking works by some of history''s most prodigious thinkers, and each volume is beautifully packaged with a unique type-drive design that highlights the bookmaker''s art. Offering great literature in great packages at great prices, this series is ideal for those readers who want to explore and savor the Great Ideas that have shaped the world.', 'en', 2005, 96, 'http://books.google.com/books/content?id=DAeWAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1030', 'accepted', 'Edward Gibbon', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 11 FROM public.book WHERE isbn13 = '9780143036241' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('79dcc3bb-b590-5639-a087-ef9586ca90a7', '9780143036357', 'Why I Write', '6I_qPwAACAAJ', 'Throughout history, some books have changed the world. They have transformed the way we see ourselves—and each other. They have inspired debate, dissent, war and revolution. They have enlightened, outraged, provoked and comforted. They have enriched lives—and destroyed them. Now, Penguin brings you the works of the great thinkers, pioneers, radicals and visionaries whose ideas shook civilization, and helped make us who we are. Penguin''s Great Ideas series features twelve groundbreaking works by some of history''s most prodigious thinkers, and each volume is beautifully packaged with a unique type-drive design that highlights the bookmaker''s art. Offering great literature in great packages at great prices, this series is ideal for those readers who want to explore and savor the Great Ideas that have shaped the world. Whether puncturing the lies of politicians, wittily dissecting the English character or telling unpalatable truths about war, Orwell''s timeless, uncompromising essays are more relevant, entertaining and essential than ever in today''s era of spin.', 'en', 2005, 120, 'http://books.google.com/books/content?id=6I_qPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
