INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0b13f43c-7cb3-5112-a728-acd3f6b7f211', '9780143036395', 'The Stone Diaries', 'yRaLBJc475AC', 'Carol Shields'' The Stone Diaries irrevocably transformed our understanding of the art of storytelling-and won Shields the Pulitzer Prize in Literature. Artfully disguised as a novel masquerading as the autobiography of an ordinary woman, this seductively written tale gradually reveals itself to be a profound meditation on fact, fiction, and the vast, blurred territory that lies between. Book jacket.', 'en', 2005, 384, 'http://books.google.com/books/content?id=yRaLBJc475AC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
