INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8ca8896e-204f-5425-bf87-8b00b2ff8214', '9780143036661', 'March', '-pOd81IGgmUC', 'In a story inspired by the father character in Little Women and drawn from the journals and letters of Louisa May Alcott''s father Bronson, a man leaves behind his family to serve in the Civil War and finds his marriage and beliefs profoundly challenged by his experiences. Reader''s Guide included. Reprint.', 'en', 2006, 280, 'http://books.google.com/books/content?id=-pOd81IGgmUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
