INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('80fcbfdb-23a0-5d3a-9468-47602a3db6c6', '9780143037484', 'Rounding the Mark', '1LXaCwAAQBAJ', 'Two seemingly unrelated murders draw Sicilian sleuth Inspector Montalbano into a dangerous world of illicit trafficking in human lives and test both his personal endurance and his loyalty to the institution he serves. Original. 35,000 first printing.', 'en', 2006, 272, 'http://books.google.com/books/content?id=1LXaCwAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
