INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3edb3f2b-a0c3-5fae-bacf-bdfd04a73f28', '9780143037491', 'The Social Contract', '8U7BuQAACAAJ', 'This volume brings together three of Rousseau''s most important political writings--The Social Contract and The First Discourse (Discourse on the Sciences and Arts) and The Second Discourse (Discourse on the Origin and Foundations of Inequality)--and presents essays by major scholars that shed light on these texts.', 'en', 2004, 168, 'http://books.google.com/books/content?id=8U7BuQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
