INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0642732f-572d-5d5a-91d0-144ed0e8f911', '9780143037576', 'Fear and Trembling', 'acFp6PqEVwsC', 'The perfect books for the true book lover, Penguin''s Great Ideas series features twelve more groundbreaking works by some of history''s most prodigious thinkers. Each volume is beautifully packaged with a unique type-driven design that highlights the bookmaker''s art. Offering great literature in great packages at great prices, this series is ideal for those readers who want to explore and savor the Great Ideas that have shaped our world. Inspired by the trial of a bureaucrat who helped cause the Holocaust, this radical work on the banality of evil stunned the world with its exploration of a regime''s moral blindness and one man''s insistence that he be absolved all guilt because he was ''only following orders''.', 'en', 2005, 160, 'http://books.google.com/books/content?id=acFp6PqEVwsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
