INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('285fadcd-f1c9-53b6-8ea8-de7a05aac42b', '9780143039655', 'Malgudi Days', 'dqRETZRkGCcC', 'Introducing this collection of stories, R. K. Narayan describes how in India ''the writer has only to look out of the window to pick up a character and thereby a story''. Malgudi Days is the marvellous result. Here Narayan portrays an astrologer, a snake-charmer, a postman, a vendor of pies and chappatis - all kinds of people, drawn in full colour and endearing domestic detail. And under his magician''s touch the whole imaginary city of Malgudi springs to life, revealing the essence of India and of human experience.', 'en', 1982, 264, 'http://books.google.com/books/content?id=dqRETZRkGCcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
