INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('89657289-3b31-5d7a-aa9e-3663257b745d', '9780143039860', 'Sometimes a Great Notion', 'WToh-xW3cfoC', 'The magnificent second novel from the legendary author of One Flew Over the Cuckoo''s Nest Following the astonishing success of his first novel, One Flew Over the Cuckoo''s Nest, Ken Kesey wrote what Charles Bowden calls "one of the few essential books written by an American in the last half century." This wild-spirited tale tells of a bitter strike that rages through a small lumber town along the Oregon coast. Bucking that strike out of sheer cussedness are the Stampers. Out of the Stamper family''s rivalries and betrayals Ken Kesey has crafted a novel with the mythic impact of Greek tragedy.', 'en', 1964, 715, 'http://books.google.com/books/content?id=WToh-xW3cfoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
