INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('add266df-b6bf-5132-8f36-e32f8e1692a0', '9780143039938', 'The Book of Imaginary Beings', 'FuNQPwAACAAJ', 'A whimsical compendium of mythological creature profiles considers the inventions of such literary masters as Shakespeare, Lewis Carroll, and Kafka, in a humorously commentated volume that explores the qualities of a range of dragons, unicorns, and othercurious beasts.', 'en', 2006, 236, 'http://books.google.com/books/content?id=FuNQPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
