INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9a7bade5-83dc-58f5-b3e0-e58b70d3103b', '9780156028066', 'Women and Writing', 'TfAZjjQKGsoC', 'Known for her novels, and for the dubious fame of being a doyenne of the ''Bloomsbury Set'', in her time Virginia Woolf was highly respected as a major essayist and critic with a special interest and commitment to contemporary literature, and women''s writing in particular. This spectacular collection of essays and other writings does justice to those efforts, offering unique appraisals of Aphra Behn, Mary Wollstonecraft, the Duchess of Newcastle, Dorothy Richardson, Charlotte Bronte, and Katherine Mansfield, amongst many others. Gathered too, and using previously unpublished (sometimes even unsigned) journal extracts, are what will now become timeless commentaries on ''Women and Fiction'', ''Professions for Women'' and ''The Intellectual Status of Women''. More than half a century after the publication of A Room Of One''s Own, distinguished scholar Michele Barrett cohesively brings together work which, throughout the years, has been scattered throughout many texts and many volumes. . . affording these very valuable writings the collective distinction they deserve at last.', 'en', 2003, 216, 'http://books.google.com/books/content?id=TfAZjjQKGsoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
