INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6c9189e1-a0ea-54ff-b70d-d428113fc8ea', '9780156949606', 'The Waves', '7HEM1SgPmC8C', 'Against the background of the sea, the author presents a group of characters from childhood to old age who speak in soliloquy, and we see them as they appear to themselves and to each other. In the end one of the characters sums up the effect of their lives as a whole.', 'en', 1959, 297, 'http://books.google.com/books/content?id=7HEM1SgPmC8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
