INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('10dc50d5-f201-5d8b-a612-bb6bbef4a69b', '9780192752536', 'Party Shoes', 'aYCk-RPF92sC', 'Near the end of the Second World War, Selina receives a parcel from America that contains a beautiful party dress and shoes. But her excitement turns to sorrow when she realizes she''ll never have a chance to wear the beautiful dress, until she and her cousins decide to organize a pageant.', 'en', 2002, 243, 'http://books.google.com/books/content?id=aYCk-RPF92sC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
