INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('73684129-9d21-540e-b257-b5199828cc73', '9780192801975', 'Hegel: A Very Short Introduction', '-kTyUz5mLnsC', 'Many people regard Hegel''s work as obscure and extremely difficult, yet his importance and influence are universally acknowledged. Peter Singer eliminates any excuse for remaining ignorant of the outlines of Hegel''s philosophy by providing a broad discussion of his ideas and an account of his major works.', 'en', 2001, 131, 'http://books.google.com/books/content?id=-kTyUz5mLnsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
