INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('22b1c952-c4d3-5452-bdd7-89d5172c5ef9', '9780192802637', 'Persuasion', 'lpD5anvUaRUC', 'The romance between Captain Wentworth and Anne, the daughter of Sir Walter Elliot, seems doomed because of the young man''s family connections and lack of wealth.', 'en', 2004, 249, 'http://books.google.com/books/content?id=lpD5anvUaRUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1174', 'accepted', 'Jane Austen', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 8 FROM public.book WHERE isbn13 = '9780192802637' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1a0539e4-7547-5ab4-b6da-1c851cd78e34', '9780192802644', 'Mansfield Park', 'jl6iDrN4ARwC', '''"Me!" cried Fanny..."Indeed you must excuse me. I could not act any thing if you were to give me the world. No, indeed, I cannot act."'' At the age of ten, Fanny Price leaves the poverty of her Portsmouth home to be brought up among the family of her wealthy uncle, Sir Thomas Bertram, in the chilly grandeur of Mansfield Park. There she accepts her lowly status, and gradually falls in love with her cousin Edmund. When the dazzling and sophisticated Henry and Mary Crawford arrive, Fanny watches as her cousins become embroiled in rivalry and sexual jealousy. As the company starts to rehearse a play by way of entertainment, Fanny struggles to retain her independence in the face of the Crawfords'' dangerous attractions; and when Henry turns his attentions to her, the drama really begins... This new edition does full justice to Austen''s complex and subtle story, placing it in its Regency context and elucidating the theatrical background that pervades the novel.', 'en', 2003, 418, 'http://books.google.com/books/content?id=jl6iDrN4ARwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1175', 'needs_review', 'Jane Austen', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 0 FROM public.book WHERE isbn13 = '9780192802644' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c5f18f14-9f5b-5a1e-ba23-da4e99f9446a', '9780192803467', 'Egyptian Myth: A Very Short Introduction', 'pXkRDAAAQBAJ', 'Egyptian myths articulated the core values of one of the longest lasting civilizations in history, and myths of deities such as Isis and Osiris influenced contemporary cultures and became part of the Western cultural heritage. Egyptian Mythology: A Very Short Introduction explains the cultural and historical background to the fascinating and complex world of Egyptian myth, with each chapter dealing with a particular theme. To show the variety of source material for Egyptian myth, each chapter features a particular object--such as the obelisk known as Cleopatra''s Needle, a golden statue of Tutankhamun, and a papyrus containing a story in which the Egyptian gods behave outrageously--which is illustrated by a photograph or line-drawing. The myth "The Contendings of Horus and Seth" is looked at in detail, and the many interpretations it has provoked are examined. In addition to a list of major deities and myths, there are explanations of related topics such as how hieroglyphs work, royal names and titles, and the Egyptian cosmos. There is also a timeline of Egyptian history, a glossary of technical terms and an up-to-date bibliography.', 'en', 2004, 143, 'http://books.google.com/books/content?id=pXkRDAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1177', 'accepted', 'Geraldine Pinch', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 16 FROM public.book WHERE isbn13 = '9780192803467' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dfbca00d-f0f2-5019-9310-5a78369ea0a5', '9780192804099', 'The Major Works', 'Q0xkC5CEhHQC', 'This authoritative edition was originally published in the acclaimed Oxford Authors series under the general editorship of Frank Kermode. It brings together a unique combination of Milton''s poetry and prose - all the English verse together with a generous selection from the major prosewritings - to give the essence of his work and thinking.Milton''s influence on English poetry and criticism has been incalculable, and this edition covers the full range of his poetic and political output. It includes Paradise Lost, Paradise Regained, and Samson Agonistes as well as major prose works such as Areopagitica and The Tenure of Kings andMagistrates. As well as all the English and Italian verse, the volume includes most of the Latin and Greek verse in parallel translation. Spelling has been modernized, and the poems are arranged in order of publication, essential to an understanding of the progress of Milton''s career in relationto the political and religious upheavals of his time. The extensive notes cover syntax, vocabulary, historical context, and biblical and classical allusions. The introduction traces both Milton''s changing conception of his own vocation, and the critical reception his work has received over the pastfour centuries.', 'en', 2003, 1008, 'http://books.google.com/books/content?id=Q0xkC5CEhHQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1178', 'accepted', 'John Milton', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 7 FROM public.book WHERE isbn13 = '9780192804099' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e6341127-7de9-57e5-85bb-fa29145823f3', '9780192805348', 'Gulliver''s Travels', 'f_0bQHhTqUoC', '"Gulliver''s travels purports to be a travel book. It is a blend of fantasy and realism and describes the shipwrecked Gulliver''s encounters with the inhabitants of four places: Lilliput, Brobdingnag, Laputa, and the country of the Houyhnhnms"--Provided byp', 'en', 2005, 422, 'http://books.google.com/books/content?id=f_0bQHhTqUoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
