INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1c64d396-e1c7-584f-9d65-1366059caa33', '9780192806949', 'A Christmas Carol and Other Christmas Books', 'e4YJ2oiSjzYC', 'Collects some of the author''s Christmas stories, including "A Christmas Carol," in which a miser learns the true meaning of Christmas when three ghostly visitors review his past and foretell his future.', 'en', 2006, 438, 'http://books.google.com/books/content?id=e4YJ2oiSjzYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1180', 'accepted', 'Charles Dickens', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 1 FROM public.book WHERE isbn13 = '9780192806949' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b423ed6e-9093-5e41-9a64-e5e3a6d8a033', '9780192807267', 'Candide and Other Stories', 'zxJGB-_Y3Y4C', 'Candide is the most famous of Voltaire''s ''philosophical tales'', in which he combined witty improbabilities with the sanest of good sense. This edition includes four other prose tales - Micromegas, Zadig, The Ing--ecirc--;nu, and The White Bull - and a verse tale based on Chaucer''s The Wife of Bath''s Tale,: What Pleases the Ladies. - ;''If this is the best of all possible worlds, then what must the others be like?'' Young Candide is tossed on a hilarious tide of misfortune, experiencing the full horror and injustice of this ''best of all possible worlds'' - the Old and the New - before finally accepting that his old philosophy tutor Dr Pangloss has got it all wrong. There are no grounds for his daft theory of Optimism. Yet life goes on. We must cultivate our garden, for there is certainly room for improvement. Candide is the most famous of Voltaire''s ''philosophical tales'', in which he combined witty improbabilities with the sanest of good sense. First published in 1759, it was an instant bestseller and has come to be regarded as one of the key texts of the Enlightenment. What Candide does for chivalric romance, the other tales in this selection - Micromegas, Zadig, The Ingenu, and The White Bull - do for science fiction, the Oriental tale, the sentimental novel, and the Old Testament. This new edition also includes a verse tale based on Chaucer''s The Wife of Bath''s Tale, in which we discover that most elusive of secrets: What Pleases the Ladies. -', 'en', 2006, 301, 'http://books.google.com/books/content?id=zxJGB-_Y3Y4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1181', 'accepted', 'Voltaire', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 6 FROM public.book WHERE isbn13 = '9780192807267' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('479c675b-eb60-5d34-9ac1-b9aa55324946', '9780192822758', 'Confessions', 'ZinPjKdL9mEC', 'When it was first published in 1781, The Confessions scandalised Europe with its emotional honesty and frank treatment of the author''s sexual and intellectual development. Since then, it has had a more profound impact on European thought. Rousseau left posterity a model of the reflective life - the solitary, uncompromising individual, the enemy of servitude and habit and the selfish egoist who dedicates his life to a particular ideal. The Confessions recreates the world in which he progressed from incompetent engraver to grand success; his enthusiasm for experience, his love of nature, and his uncompromising character make him an ideal guide to eighteenth-century Europe, and he was the author of some of the most profound work ever written on the relation between the individual and the state.', 'en', 2000, 676, 'http://books.google.com/books/content?id=ZinPjKdL9mEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1183', 'accepted', 'Jean-Jacques Rousseau', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 19 FROM public.book WHERE isbn13 = '9780192822758' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('905bd256-32e4-531a-8f16-c766565b732e', '9780192822895', 'La Débâcle', 'GxNnSTI4YJsC', 'Zola wrote that ''my title speaks not merely of a war, but also of the crumbling of a regime and the end of a world''. The penultimate novel of the Rougon-Macquart cycle, La Debacle (1892) takes as its subject the dramatic events of the Franco-Prussian War and the Commune of 1870-71. During Zola''s lifetime it was the bestselling of all his novels, praised by contemporaries for its epic sweep as well as its attention to historical detail. The novel seeks to explain why the Second Empire ended in a crushing military defeat and revolutionary violence. It focuses on ordinary soldiers, showing their bravery and suffering in the midst of circumstances they cannot control. Zola''s descriptions are some of the most powerful he ever wrote. He skilfully integrates his narrative of events and the fictional lives of his characters to provide the finest account of this tragic chapter in the history of France. Often compared to War and Peace, La Debacle has been described as a ''seminal'' work for all modern depictions of war.', 'en', 2000, 592, 'http://books.google.com/books/content?id=GxNnSTI4YJsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
