INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('779299c1-96b3-5a34-a064-07fed52cbb21', '9780192824547', 'The First Philosophers', 'fiDWoqLUW9AC', 'A complete collection of philosophical writing of the Presocratics and Sophists, this book shows how "the first philosophers" paved the way for Plato and Aristotle, hence influencing the whole of Western thought.', 'en', 2000, 400, 'http://books.google.com/books/content?id=fiDWoqLUW9AC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
