INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b138c449-721b-58ca-ac8a-a09df54f1185', '9780192834409', 'The Castle of Otranto', 'juUIspq7CGwC', 'First published pseudonymously in 1764, The Castle of Otranto purported to be a translation of an Italian story of the time of the crusades. In it Walpole attempted, as he declared in the Preface to the second edition, `to blend the two kinds of romance: the ancient and the modern''. He gives us a series of catastrophes, ghostly interventions, revelations of identity, and exciting contests. Crammed with invention, entertainment, terror, and pathos, the novel was an immediate success and Walpole''s own favourite among his numerous works. His friend, the poet Thomas Gray, wrote that he and his family, having read Otranto, were now `afraid to go to bed o''nights''. The novel is here reprinted from a text of 1798, the last that Walpole himself prepared for the press.', 'en', 1998, 125, 'http://books.google.com/books/content?id=juUIspq7CGwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
