INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8d7e1f1e-09fb-5f19-a6dd-7f9e05128271', '9780192834423', 'The Bostonians', 'hGX8aqWTX_8C', 'Olive Chancellor and Basil Ransom, cousins, clash, when Olive wants Verena Tarrant to use her eloquence for the woman''s movement, and Basil wants Verena to give up politics and marry him.', 'en', 1998, 504, 'http://books.google.com/books/content?id=hGX8aqWTX_8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
