INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('be120d26-f7fe-53a5-a2c8-b5e3fae1e45b', '9780192835093', 'The Karamazov Brothers', 'uErHu34S6bQC', 'Dostoevsky''s last and greatest novel, The Karamazov Brothers (1880) is both a brilliantly told crime story and a passionate philosophical debate. The dissolute landowner Fyodor Pavlovich Karamazov is murdered; his sons--the atheist intellectual Ivan, the hot-blooded Dmitry, and the saintly novice Alyosha--are all involved at some level. Brilliantly bound up with this psychological drama is Dostoevsky''s intense and disturbing exploration of many deeply felt ideas about the existence of God, freedom of will, the collective nature of guilt, and the disastrous consequences of rationalism. Filled with eloquent voices, this new translation fully realizes the power and dramatic virtuosity of Dostoevsky''s most brilliant work. About the Series: For over 100 years Oxford World''s Classics has made available the broadest spectrum of literature from around the globe. Each affordable volume reflects Oxford''s commitment to scholarship, providing the most accurate text plus a wealth of other valuable features, including expert introductions by leading authorities, voluminous notes to clarify the text, up-to-date bibliographies for further study, and much more.', 'en', 1998, 1054, 'http://books.google.com/books/content?id=uErHu34S6bQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1202', 'accepted', 'Fyodor Dostoevsky; Ignat Avsey', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 1 FROM public.book WHERE isbn13 = '9780192835093' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f54f192d-2871-512d-ac94-775632b63a1d', '9780192835437', 'Daisy Miller and Other Stories', 'siHgsquTgRIC', 'The tale of Daisy''s irruption into staid European society enjoyed, as did Daisy herself, asuccès de scandale; and it has remained one of Jamess most popular short stories. Like the others collected here--''Pandora,'' ''The Patagonia,'' and ''Four Meetings''-- it describes a confrontation between different values in a changing world. Is the new independent American girl enchanting in her spontaneity, alarming in her unpredictability, or merely vulnerable in her ignorance of social codes? Hung about with make admirers who seek, uncertainly, to grasp the new phenomenon, Daisy marches on undiscourageable, to her triumphant--or tragic--destiny. This volume contains prefaces by Henry James, a chronology of his life, and editor''s notes. About the Series:For over 100 yearsOxford World''s Classicshas made available the broadest spectrum of literature from around the globe. Each affordable volume reflects Oxford''s commitment to scholarship, providing the most accurate text plus a wealth of other valuable features, including expert introductions by leading authorities, voluminous notes to clarify the text, up-to-date bibliographies for further study, and much more.', 'en', 1998, 352, 'http://books.google.com/books/content?id=siHgsquTgRIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1203', 'accepted', 'Henry James', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 9 FROM public.book WHERE isbn13 = '9780192835437' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('32079858-bea8-5d56-a8fa-c36226838c2e', '9780192835857', 'Selected Philosophical Writings', '7Yn8Id1BEqwC', 'St Thomas Aquinas (1225-1274) saw religion as part of the natural human propensity to worship. His ability to recognize the naturalness of this phenomenon and simultaneously to go beyond it, to explore spiritual revelation, makes his work fresh and highly readable today. While drawing on a strong distinction between theology and philosophy, Aquinas interleaved them intricately in his writings, which range from an examination of the structures of thought to the concept of God as the end of all things. This accessible new translation chooses substantial passages not only from the indispensable Summa Theologicae, but from many other works, fully illustrating the breadth and progression of Aquinas''s philosophy.', 'en', 1998, 496, 'http://books.google.com/books/content?id=7Yn8Id1BEqwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1204', 'accepted', 'Saint Thomas (Aquinas)', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 4 FROM public.book WHERE isbn13 = '9780192835857' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('60357cff-9354-54a6-be6b-aaa987b1c512', '9780192836021', 'The Ladies'' Paradise', 'iiyXsyHqh8MC', 'The Ladies'' Paradise (Au Bonheur des Dames) recounts the spectacular development of the modern department store in late nineteenth century Paris. The store is a symbol of capitalism, of the modern city, and of the bourgeois family; it is emblematic of consumer culture and the changes in sexualattitudes and class relations taking place at the end of the century.Octave Mouret, the store''s owner-manager, masterfully exploits the desires of his female customers. In his private life as much as in business he is the great seducer. But when he falls in love with the innocent Denise Baudu, he discovers she is the only one of the salesgirls who refuses to becommodified.This new translation of the eleventh book in the Rougon-Macquart cycle captures the spirit of one of Zola''s greatest novels of the modern city.', 'en', 1998, 438, 'http://books.google.com/books/content?id=iiyXsyHqh8MC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1205', 'accepted', 'Émile Zola', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 8 FROM public.book WHERE isbn13 = '9780192836021' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6a864866-e2fb-54fe-be31-842092ab4045', '9780192836229', 'A Sentimental Education', 'Dn7ixiuEWeMC', 'Frederic Moreau, a moderately gifted young provincial, is ambitious in many ways: he dreams of fame, of vast wealth, of literary and artistic achievement, of a grand passion. On the Paris paddle-steamer which transports him to his home town of Nogent-sur-Seine at the outset of the novel, he becomes transfixed by the demure Madame Arnoux and, back in Paris, cultivates her ebullient and enterprising husband in order to be near her. Frederic''s devotion fluctuates like his other enthusiasms, and he is caught up in the intense pleasures and the inevitable ennuis of Parisian life.', 'en', 2000, 464, 'http://books.google.com/books/content?id=Dn7ixiuEWeMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1206', 'accepted', 'Gustave Flaubert', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 20 FROM public.book WHERE isbn13 = '9780192836229' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a1d5b3b9-2ed9-53fd-bd04-ad75435d79be', '9780192836366', 'Faust', 'c3CZ8UQp_CoC', 'Loosely connected with Part One and the German legend of Faust, Part Two is a dramatic epic rather than a strictly constructed drama. It is conceived as an act of homage to classical Greek culture and inspired above all by the world of story-telling and myth at the heart of the Greektradition, as well as owing some of its material to the Arabian Nights tales.The restless and ruthless hero, advised by his cynical demon-companion Mephistopheles, visits classical Greece i search of the beautiful Helen of Troy. Returning to modern times, he seeks to crown his career by gaining control of the elements, and at his death is carried up into the unkown regions,still in pursuit of the `Eternal Feminine''.David Luke''s translation of Part One won the European Poetry Translation Prize. Here he again imitates the varied verse-forms of the original, and provides a highly readable - and actable - translation, supported by an introduction, full notes, and an index of classical mythology.', 'en', 1998, 304, 'http://books.google.com/books/content?id=c3CZ8UQp_CoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1207', 'accepted', 'Johann Wolfgang von Goethe', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 3 FROM public.book WHERE isbn13 = '9780192836366' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f711dd42-db0f-55df-bb1c-6000b9edcfee', '9780192836380', 'La Dame Aux Camélias', 'Aqft1VzHuHkC', 'This new translation successfully combines a feeling for the formal proprieties of Dumas''s style with a supple and colloquial liveliness that once again proves this story irresistible. -', 'en', 1986, 256, 'http://books.google.com/books/content?id=Aqft1VzHuHkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1208', 'accepted', 'Alexandre Dumas; David Coward', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 5 FROM public.book WHERE isbn13 = '9780192836380' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('36f81c05-f931-53a4-b59a-ec637690ccac', '9780192836892', 'First Love and Other Stories', 'J3lKucR0wcoC', 'This collection brings together six of Turgenev''s best-known `long'' short stories, in which he turns his skills of psychological observation and black comedy to subjects as diverse as the tyranny of serfdom, love, and revenge on the Russian steppes. These stories all display the elegance andclarity of Turgenev''s finest writing.Richard Freeborn was until recently Professor of Russian at the School of Slavonic and East European Studies, London.', 'en', 1999, 304, 'http://books.google.com/books/content?id=J3lKucR0wcoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1209', 'accepted', 'Ivan Sergeevich Turgenev', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 2 FROM public.book WHERE isbn13 = '9780192836892' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('081592c3-0ccc-5f5d-b5c5-5b1c4234e330', '9780192837622', 'The Confidence-man', 'Hiy9OyE-TAQC', 'Male, female, deft, fraudulent, constantly shifting: which of the `masquerade'' of passengers on the Mississippi steamboat Fidele is `the confidence man''? The central motif of Melville''s last and most `modern'' novel can be seen as a symbol of American cultural history.', 'en', 1999, 361, 'http://books.google.com/books/content?id=Hiy9OyE-TAQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
