INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2ccaba66-4458-51ba-aff4-92981d6ccf50', '9780192837684', 'The Eclogues ; The Georgics', 'cbVpH9EbtcoC', 'The Eclogues, ten short pastoral poems, were composed between approximately 42 and 39 BC, during the time of the ''Second'' Triumvirate of Lepidus, Anthony, and Octavian. In them Virgil subtly blended an idealized Arcadia with contemporary history. To his Greek model - the Idylls of Theocritus - he added a strong element of Italian realism: places and people, real or disguised, and contemporary events are introduced. The Eclogues display all Virgil''s art and charm and are among his mostdelightful achievements. Between approximately 39 and 29 BC, years of civil strife between Antony, and Octavian, Virgil was engaged upon the Georgics. Part agricultural manual, full of observations of animals and nature, they deal with the farmer''s life and give it powerful allegorical meaning. These four books contain some of Virgil''s finest descriptive writing and are generally held to be his greatest and most entertaining work, and C. Day Lewis''s lyrical translations are classics in theirown right.', 'en', 1999, 180, 'http://books.google.com/books/content?id=cbVpH9EbtcoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1211', 'accepted', 'Virgil', 'Agriculture', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 14 FROM public.book WHERE isbn13 = '9780192837684' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('32f2015b-7b9f-52f0-ab95-2603ba9d6c53', '9780192837806', 'Scenes of Clerical Life', 'tCfq__XvAiUC', 'When Scenes of Clerical Life, George Eliot''s first novel, was published anonymously in 1857, it was immediately recognized, in the words of Saturday Review, as `the production of a peculiar and remarkable writer''. The three stories that make up the Scenes, `The Sad Fortunes of the ReverendAmos Barton'', `Mr Gilfil''s Love Story'', and `Janet''s Repentance'', intriguingly foreshadow George Eliot''s later work. The first readers, including Dickens and Thackeray, were struck by the humorous irony, the truthfulness of the presentation of the lives of ordinary people, and the compassionateacceptance of human weakness which characterize Eliot''s writing.', 'en', 2000, 310, 'http://books.google.com/books/content?id=tCfq__XvAiUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1212', 'accepted', 'George Eliot', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 17 FROM public.book WHERE isbn13 = '9780192837806' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a80c12c8-9c55-5137-959e-54b961a45de1', '9780192838742', 'Jacques the Fatalist and His Master', 'oJ7qCzCI1NIC', '''Your Jacques is a tasteless mishmash of things that happen, some of them true, others made up, written without style and served up like a dog''s breakfast.''Jacques the Fatalist is Diderot''s answer to the problem of existence. If human beings are determined by their genes and their environment, how can they claim to be free to want or do anything? Where are Jacques and his Master going? Are they simply occupying space, living mechanically until theydie, believing erroneously that they are in charge of their Destiny? Diderot intervenes to cheat our expectations of what fiction should be and do, and behaves like a provocative, ironic and unfailingly entertaining master of revels who finally show why Fate is not to be equated with doom.In the introduction to this brilliant new translation, David Coward explains the philosophical basis of Diderot''s fascination with Fate and shows why Jacques the Fatalist pioneers techniques of fiction which, two centuries on, novelists still regard as experimental.', 'en', 1999, 304, 'http://books.google.com/books/content?id=oJ7qCzCI1NIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1213', 'accepted', 'Denis Diderot', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 1 FROM public.book WHERE isbn13 = '9780192838742' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a9663a3a-198c-5909-bc95-d1935761da1e', '9780192838971', 'The Notebooks of Leonardo Da Vinci', 'ZMp0pOmY3GEC', 'Throughout his life Leonardo da Vinci carried notebooks in which he scribbled down ideas and opinions as they occurred - personal, domestic, scientific, philosophical, artistic - frequently accompanied by explanatory sketches and diagrams. Surviving manuscripts contain drafts of letters, fanciful fables, rough treatises on the art of painting or the power of water, descriptions of the Medici courts, even jokes. The present selection gives coherence to this rich kaleidoscope of ideas. From it emerges the portrait of a true Renaissance man, whose habit of rigorous enquiry, observation, and experiment, grounded on a philosophic system, led him to conceive of the universe as an organized cosmos corresponding to a work of art.', 'en', 1952, 432, 'http://books.google.com/books/content?id=ZMp0pOmY3GEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1214', 'accepted', 'Leonardo Da Vinci; Leonardo (da Vinci)', 'Art', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 5 FROM public.book WHERE isbn13 = '9780192838971' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('33c80e95-da21-5804-905b-09d51e01d8db', '9780192838995', 'Eugene Onegin', '-l1D5bJ4K3UC', 'Eugene Onegin is the master work of the poet whom Russians regard as the fountainhead of their literature. Set in 1820s Russia, Pushkin''s novel in verse follows the fates of three men and three women. It was Pushkin''s own favourite work, and this new translation conveys the literal sense and the poetic music of the original. - ;Eugene Onegin is the master work of the poet whom Russians regard as the fountainhead of their literature. Set in 1820s imperial Russia, Pushkin''s novel in verse follows the emotions and destiny of three men - Onegin the bored fop, Lensky the minor elegiast, and a stylized Pushkin himself - and the fates and affections of three women - Tatyana the provincial beauty, her sister Olga, and Pushkin''s mercurial Muse. Engaging, full of suspense, and varied in tone, it also portrays a large cast of other characters and offers the reader many literary, philosophical, and autobiographical digressions, often in a highly satirical vein. Eugene Onegin was Pushkin''s own favourite work, and it shows him attempting to transform himself from a romantic poet into a realistic novelist. This new translation seeks to retain both the literal sense and the poetic music of the original, and capture the poem''s spontaneity and wit. The introduction examines several ways of reading the novel, and text is richly annotated. -', 'en', 1998, 240, 'http://books.google.com/books/content?id=-l1D5bJ4K3UC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1215', 'accepted', 'Alexander Pushkin; James E. Falen', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 17 FROM public.book WHERE isbn13 = '9780192838995' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f985d8f2-b3f8-53ee-a66e-8dbfb91ab421', '9780192839190', 'The Admirable Crichton ; Peter Pan ; When Wendy Grew Up ; What Every Woman Knows ; Mary Rose', 'nG97v_jo08IC', 'For some 20 years at the beginning of the century J M Barrie enjoyed enormous commercial success with a wide variety of plays, but he is best known for Peter Pan. It retains its popularity today, both in the original and in adaptations. As well as being the author of the greatest of allchildren''s plays Barrie also wrote sophisticated social comedy and political satire, much of it now newly topical. The Admirable Crichton and What Every Woman Knows are shrewd and entertaining contributions to the politics of class and gender, while Mary Rose is one of the best ghost stories writtenfor the stage. Under the General Editorship of Michael Cordner, of the University of York, the texts of the plays have been newly edited and are supplemented with a scholarly introduction and detailed annotation.', 'en', 1999, 384, 'http://books.google.com/books/content?id=nG97v_jo08IC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
