INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c8de338f-2a68-52b1-9d0c-1af4f22941db', '9780195061666', 'Alcestis', 'SgQiG25-5MgC', 'At once a vigorous translation of one of Euripides'' most subtle and witty plays, and a wholly fresh interpretation, this version reveals for the first time the extraordinary formal beauty and thematic concentration of the Alcestis. William Arrowsmith rejects the standard view of the Alcestis as a psychological study of the egotist Admetos and his naive but devoted wife. His translation, instead, presents the play as a drama of human existence--in keeping with the tradition of Greek tragedy--with recognizably human characters who also represent masked embodiments of human conditions.', 'en', 1989, 142, 'http://books.google.com/books/content?id=SgQiG25-5MgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
