INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ab98d786-0812-57af-8f8e-5d6d39c55521', '9780195125986', 'Bakkhai', '9n_IHbgieKYC', '"Regarded by many as Euripides'' masterpiece, Bakkhai examines both the horror and the beauty of the religious ecstasy that Dionysos brings to Thebes. His offer of closeness to nature and freedom from the constraints of civilization, especially for women, excites bitter resistance as well as fanatical acceptance." "Disguised as a young holy man and accompanied by his band of Asian worshipers, the god Dionysos arrives in Greece at Thebes, proclaims his godhood and his new religion, and drives the Theban women mad. When the Theban king, Pentheus, tries to imprison him, Dionysos afflicts Pentheus himself with madness and leads him, dressed as a bacchant, to the mountains, where his own mother, Agaue, and her companions tear him to pieces in an insane Bacchic frenzy."', 'en', 2001, 160, 'http://books.google.com/books/content?id=9n_IHbgieKYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
