INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a3669bae-1524-5f62-af4a-61d7ecc8df71', '9780195135794', 'Manic-Depressive Illness', 'hOHWEtEKEO4C', 'This long-awaited second edition of Manic-Depressive Illness will exhaustively review the biological and genetic literature that has dominated the field in recent years, and incorporate cutting-edge research conducted since publication of the first edition. Drs. Frederick Goodwin and Kay Redfield Jamison have updated their surveys of psychological and epidemiological evidence, as well as that pertaining to diagnostic issues, course, and outcome, and they offer practical guidelines for differential diagnosis and clinical management. This book will be a valuable addition to the libraries of psychiatrists and other physicians, psychologists, clinical social workers, neuroscientists, pharmacologists, and the patients and families who live with manic-depressive illness.', 'en', 2007, 1262, 'http://books.google.com/books/content?id=hOHWEtEKEO4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
