INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('67dca072-3190-501a-a7a2-4b43dcfd41a3', '9780195135923', 'The Oresteia', 'SY9HlKSNwZUC', 'The story of the house of Atreus is a tale of incest, adultery, human sacrifice, cannibalism, and political intrigue. It is also a story in which human action is simultaneously willed and determined.".', 'en', 2003, 304, 'http://books.google.com/books/content?id=SY9HlKSNwZUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
