INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1ab8c3d0-4cd3-5626-bd6f-2f95f54d33e6', '9780195145816', 'Philosophy of Mind', 'rtEo8PRjpVoC', 'This is a comprehensive collection of readings in the philosophy of mind, ranging from Descartes to the leading edge of the discipline. Extensive selections cover foundations, the nature of consciousness, and the nature of mental content.', 'en', 2002, 675, 'http://books.google.com/books/content?id=rtEo8PRjpVoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
