INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('293da7ab-3678-512f-ba00-cde948f28330', '9780195168952', 'Battle Cry of Freedom', '09FkZqu_YcMC', 'Filled with fresh interpretations and information, puncturing old myths and challenging new ones, Battle Cry of Freedom will unquestionably become the standard one-volume history of the Civil War. James McPherson''s fast-paced narrative fully integrates the political, social, and military events that crowded the two decades from the outbreak of one war in Mexico to the ending of another at Appomattox. Packed with drama and analytical insight, the book vividly recounts the momentous episodes that preceded the Civil War—the Dred Scott decision, the Lincoln-Douglas debates, John Brown''s raid on Harper''s Ferry—and then moves into a masterful chronicle of the war itself—the battles, the strategic maneuvering on both sides, the politics, and the personalities.', 'en', 2005, 867, 'http://books.google.com/books/content?id=09FkZqu_YcMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1245', 'accepted', 'James M. McPherson', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 4 FROM public.book WHERE isbn13 = '9780195168952' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('33b5c85c-9118-531d-b4a3-cf8645f89da2', '9780195169249', 'Introduction to Philosophy', 'h0zuAAAAMAAJ', 'Introduction to Philosophy, Fourth Edition, is the most comprehensive topically organized collection of classical and contemporary philosophy available. Building on the exceptionally successful tradition of previous editions, this edition for the first time incorporates the insights of a new coeditor, John Martin Fischer, and has been updated and revised to make it more accessible. Ideal for introductory philosophy courses, the text includes sections on the meaning of life, God and evil, knowledge and reality, the philosophy of science, the mind/body problem, freedom of will, consciousness, ethics, and philosophical puzzles and paradoxes. It presents seventy substantial--and in some cases complete--selections from the best and most influential works in philosophy, offering a unique balance between classical and contemporary material. An extensive glossary of philosophical terms is also included. The fourth edition features fifteen new readings, including work by Albert Camus, Roderick M. Chisholm, Daniel Dennett, Harry G. Frankfurt, William Paley, Derek Parfit, John Perry, Richard Taylor, Peter Van Inwagen, Bernard Williams, and Susan Wolf. Part III, Knowledge and Reality, has been restructured and now includes Plato''s Thaetetus, selections by Edmund L. Gettier and Robert Nozick, and an essay by Christopher Grau that explores the philosophical concepts presented in the popular film The Matrix. Two new ethics puzzles--"The Trolley Problem" and "Ducking Harm and Sacrificing Others"--are also included. This edition incorporates Study Questions after each reading and is accompanied by an Instructor''s CD and a Student Companion Website, both containing helpful resources.', 'en', 2007, 819, 'http://books.google.com/books/content?id=h0zuAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
