INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dfb1f1d0-bc0c-5050-a9ef-24f97489bc22', '9780195300925', 'The Faiths of the Founding Fathers', 'Ux9nDAAAQBAJ', 'An in-depth examination of the spiritual beliefs of America''s founding fathers provides an account of the religious culture of the late colonial era and looks at individual beliefs of men and women who played a significant role in American history.', 'en', 2006, 225, 'http://books.google.com/books/content?id=Ux9nDAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
