INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cc7aa818-e82c-54ff-bccb-7f3bb97b8536', '9780195309683', 'Acts of God', 'Rmfli9l7ezUC', 'This revised edition features a new chapter analyzing the failed response to Hurricane Katrina. Steinberg argues that it is wrong to see natural disasters as random outbursts of nature or expressions of divine judgment. He reveals how business and government decisions have paved the way for the greater losses of life and property.', 'en', 2006, 309, 'http://books.google.com/books/content?id=Rmfli9l7ezUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
