INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bf25f3f6-a2d6-5193-afa3-275d0a0c86cd', '9780195325928', 'The Oxford Handbook of Philosophy of Mathematics and Logic', '2zA7PgAACAAJ', 'Mathematics and logic have been central topics of concern since the dawn of philosophy. Since logic is the study of correct reasoning, it is a fundamental branch of epistemology and a priority in any philosophical system. Philosophers have focused on mathematics as a case study for general philosophical issues and for its role in overall knowledge- gathering. Today, philosophy of mathematics and logic remain central disciplines in contemporary philosophy, as evidenced by the regular appearance of articles on these topics in the best mainstream philosophical journals; in fact, the last decade has seen an explosion of scholarly work in these areas. This volume covers these disciplines in a comprehensive and accessible manner, giving the reader an overview of the major problems, positions, and battle lines. The 26 contributed chapters are by established experts in the field, and their articles contain both exposition and criticism as well as substantial development of their own positions. The essays, which are substantially self-contained, serve both to introduce the reader to the subject and to engage in it at its frontiers. Certain major positions are represented by two chapters--one supportive and one critical. The Oxford Handbook of Philosophy of Math and Logic is a ground-breaking reference like no other in its field. It is a central resource to those wishing to learn about the philosophy of mathematics and the philosophy of logic, or some aspect thereof, and to those who actively engage in the discipline, from advanced undergraduates to professional philosophers, mathematicians, and historians.', 'en', 2007, 832, 'http://books.google.com/books/content?id=2zA7PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1250', 'accepted', 'Stewart Shapiro', 'Mathematics', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 19 FROM public.book WHERE isbn13 = '9780195325928' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7ed6bac2-db36-5ada-9951-5a276558db41', '9780198140818', 'Aristophanes'' Peace', 'cLxfAAAAMAAJ', 'Aristophanes'' Peace was performed at the City Dionysia in Athens in 421 BC as a decade-long war with Sparta seemed finally to be drawing to an end, and is one of only eleven extant plays by the greatest Old Comic poet. Olson''s edition of the play, which replaces Platnauer''s of 1969, is based on a complete new collation of the manuscripts, many of which have never been adequately reported before. The extensive commentary explores matters of all sorts, but it focuses in particular on therealities of day-to-day life in classical Athens and also examines the practical problems of staging. The substantial introduction includes essays on Aristophanes'' early career, the politics of the Greek world in the late 420s, and the poet''s theology.', 'en', 1998, 408, 'http://books.google.com/books/content?id=cLxfAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1251', 'accepted', 'Aristophanes; S. Douglas Olson', 'Drama', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 4 FROM public.book WHERE isbn13 = '9780198140818' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b7ffa1cf-72c0-5d58-8152-112628a62783', '9780198144960', 'Lysistrata', 'a6uQuCQuSUoC', 'Aristophanes'' Lysistrata was last edited in 1928, and the last commentary was in 1927; the only previous edition in English appeared in 1911. The present edition brings the play up to date in terms of the advances made in Aristophanic scholarship in the past sixty years. In particular, it is the first to report all the manuscripts, papyri, and testimonial sources of the text, offering a new account of its history and a detailed review of the transmission of the Aristophanic corpus as a whole.', 'en', 1990, 320, 'http://books.google.com/books/content?id=a6uQuCQuSUoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
