INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('662accdd-83b6-5dc7-9257-29abb15c4fe1', '9780198711551', 'The Canterbury Tales', '2KNzQgAACAAJ', 'Since its first publication in 1989, Helen Cooper''s guide to The Canterbury Tales has established itself as the standard work on the poem. This second edition continues to offer the most comprehensive scrutiny of the Tales both as a whole and individually. In addition, Cooper incorporates the most significant recent scholarship and criticism, reflecting current research in the areas of Chaucer''s historical and social context and developments in the interpretation of Chaucer''s presentation of women.', 'en', 1996, 456, 'http://books.google.com/books/content?id=2KNzQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
