INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9f52228f-ee94-52de-9d1a-f7bee01223e0', '9780198752752', 'Medieval Philosophy : A New History of Western Philosophy, Volume 2', 'd1wa8MZqFaMC', 'Sir Anthony Kenny continues his magisterial new history of Western philosophy with a fascinating guide through more than a millennium of thought from 400 AD onwards, charting the story of philosophy from the founders of Christian and Islamic thought through to the Renaissance. The middle ages saw a great flourishing of philosophy, and the intellectual endeavour of the era reaches its climax in the thirteenth and fourteenth centuries, with the systems of such great thinkers as Thomas Aquinas and John Duns Scotus. Specially written for a broad popular readership, but serious and deep enough to offer a genuine understanding of the great philosophers, Kenny''s lucid and stimulating history will become the definitive work for anyone interested in the people and ideas that shaped the course of Western thought. - ;Sir Anthony Kenny continues his magisterial new history of Western philosophy with a fascinating guide through more than a millennium of thought from 400 AD onwards, charting the story of philosophy from the founders of Christian and Islamic thought through to the Renaissance.The middle ages saw a great flourishing of philosophy, and the intellectual endeavour of the era reaches its climax in the thirteenth and fourteenth centuries, with the systems of the great schoolmen such as Thomas Aquinas and John Duns Scotus. Specially written for a broad popular readership, but serious and deep enough to offer a genuine understanding of the great philosophers, Kenny''s lucid and stimulating history will become the definitive work for anyone interested in the people and ideas that shaped the course of Western thought. - ;from the reviews of the preceding volume..... This wonderful book . . . is not only an authoritative guide to the history of philosophy but also a compelling introduction to every major area of philosophical inquiry. . . . Kennys prose is exceptionally clear . . . He conveys his rich subject matter with a light touch of which only the greatest of writers are capable. . . . This, combined with his breadth and depth of learning and philosophical sophistication, make reading this book hugely rewarding. It is also worth mentioning that the book is beautifully illustrated . . . One is left eager for subsequent volumes and convinced that the intellectual cosmos is, indeed, boundlessly rich. - James Ladyman, Times Higher Education Supplement', 'en', 2005, 352, 'http://books.google.com/books/content?id=d1wa8MZqFaMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1260', 'accepted', 'Anthony Kenny', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 10 FROM public.book WHERE isbn13 = '9780198752752' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ce78934f-024a-5f18-84d4-8497e73d142f', '9780198782742', 'Contemporary Political Philosophy', 'yYCcAQAAQBAJ', '"This new edition of Will Kymlicka''s best selling critical introduction to contemporary political theory has been fully revised to include many of the most significant developments in Anglo-American political philosophy in the last 11 years, particularly the new debates on political liberalism, deliberative democracy, civic republicanism, nationalism, and cultural pluralism." "The book now includes two new chapters on citizenship theory and multiculturalism, in addition to updated chapters on utilitarianism, liberal egalitarianism, libertarianism, Marxism, communitarianism, and feminism. Extended guides to further reading have been added at the end of each chapter, listing the most important books and articles on each school of thought, as well as relevant journals and web sites."--BOOK JACKET.', 'en', 2002, 512, 'http://books.google.com/books/content?id=yYCcAQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
