INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('afd9615f-d74d-52cb-9c67-71459a7fbe08', '9780199203611', 'The Major Works', 'N-P6v44wHxkC', 'Features selections of the author''s prose and poems, including the full texts of "The Dunciad," "The Rape of the Lock," and "Peri Bathous."', 'en', 2006, 768, 'http://books.google.com/books/content?id=N-P6v44wHxkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
