INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('72756983-5194-57dc-aa57-dbf900cf3dbf', '9780205479801', 'The Actor in You', 'lZZQAAAAMAAJ', 'The Actor in Youenhances the reader’s appreciation of the art of acting by helping them realize that they already possess, in principle, the following skills: the ability to play a role, the ability to fulfill the sense of drama and to structure dramatic scenes, and the capacity to express emotion. Without losing its simplicity, directness, and enjoyable writing style, this revised and enlarged edition has benefited from helpful suggestions by teachers who have used it successfully in the classroom. Drawing exercises and examples from readers’ everyday lives and from well-known films and television programs, Benedetti succeeds in deducing dramatic principles from those experiences and then applying them to everyday life for artistic purpose.', 'en', 2005, 160, 'http://books.google.com/books/content?id=lZZQAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
