INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c903f066-2e75-5dbd-b414-1144cdc93dcc', '9780224060875', 'It''s Not about the Bike', '5ATbkSDvfd0C', 'If you read just one sports book this year, this is the one'' Express on SundayLance Armstrong was one of the most precocious talents the world of cycling had ever seen. Within a year of turning professional in 1992 he was World Champion. In 1994 he won tw', 'en', 2001, 294, 'http://books.google.com/books/content?id=5ATbkSDvfd0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
