INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('60b75ec1-9339-58ae-bb21-02396f6d3e43', '9780226014906', 'The Crescent Obscured', 'FKiKeqOhSpwC', 'From the beginning of the colonial period to the recent conflicts in the Middle East, encounters with the Muslim world have helped Americans define national identity and purpose. Focusing on America''s encounter with the Barbary states of North Africa from 1776 to 1815, Robert Allison traces the perceptions and mis-perceptions of Islam in the American mind as the new nation constructed its ideology and system of government. "A powerful ending that explains how the experience with the Barbary states compelled many Americans to look inward . . . with increasing doubts about the institution of slavery." —David W. Lesch, Middle East Journal "Allison''s incisive and informative account of the fledgling republic''s encounter with the Muslim world is a revelation with a special pertinence to today''s international scene." —Richard W. Bulliet, Journal of Interdisciplinary History "This book should be widely read. . . . Allison''s study provides a context for understanding more recent developments, such as America''s tendency to demonize figures like Iran''s Khumaini, Libya''s Qaddafi, and Iraq''s Saddam." —Richard M. Eaton, Eighteenth Century Studies', 'en', 2000, 284, 'http://books.google.com/books/content?id=FKiKeqOhSpwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1278', 'accepted', 'Robert Allison', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 16 FROM public.book WHERE isbn13 = '9780226014906' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b17710dd-b9a5-5ef0-895d-aae32a4c8769', '9780226020457', 'The Bridge on the Drina', 'Y7WcIKgk5NQC', 'The Bridge on the Drina is a vivid depiction of the suffering history has imposed upon the people of Bosnia from the late 16th century to the beginning of World War I. As we seek to make sense of the current nightmare in this region, this remarkable, timely book serves as a reliable guide to its people and history. "No better introduction to the study of Balkan and Ottoman history exists, nor do I know of any work of fiction that more persuasively introduces the reader to a civilization other than our own. It is an intellectual and emotional adventure to encounter the Ottoman world through Andric''s pages in its grandiose beginning and at its tottering finale. It is, in short, a marvelous work, a masterpiece, and very much sui generis. . . . Andric''s sensitive portrait of social change in distant Bosnia has revelatory force."—William H. McNeill, from the introduction "The dreadful events occurring in Sarajevo over the past several months turn my mind to a remarkable historical novel from the land we used to call Yugoslavia, Ivo Andric''s The Bridge on the Drina."—John M. Mohan, Des Moines Sunday Register Born in Bosnia, Ivo Andric (1892-1975) was a distinguished diplomat and novelist. He was awarded the Nobel Prize for Literature in 1961. His books include The Damned Yard: And Other Stories, and The Days of the Consuls.', 'en', 1977, 314, 'http://books.google.com/books/content?id=Y7WcIKgk5NQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1279', 'accepted', 'Ivo Andríc', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 0 FROM public.book WHERE isbn13 = '9780226020457' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ca16c057-d26d-5d12-bc5c-2017a500d24d', '9780226025971', 'Love and Saint Augustine', 'YqI3H-TKBGkC', 'Editors Joanna Vecchiarelli Scott and Judith Chelius Stark make Hannah Arendt''s important early work accessible for the first time. Here is a completely corrected and revised English translation that incorporates Arendt''s own substantial revisions and provides additional notes based on letters, contracts, and other documents. "A revelation that may force us to reconsider the traditional interpretation of Arendt''s work".--KIRKUS REVIEWS.', 'en', 1996, 254, 'http://books.google.com/books/content?id=YqI3H-TKBGkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1280', 'accepted', 'Hannah Arendt; Joanna Vecchiarelli Scott; Judith Chelius Stark', 'Family & Relationships', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 12 FROM public.book WHERE isbn13 = '9780226025971' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('28a72da4-5b17-5756-8402-b1930afb03e8', '9780226042756', 'Plato''s Symposium', '0zoQDYBYTs4C', 'Plato, Allan Bloom wrote, is "the most erotic of philosophers," and his Symposium is one of the greatest works on the nature of love ever written. This new edition brings together the English translation of the renowned Plato scholar and translator, Seth Benardete, with two illuminating commentaries on it: Benardete''s "On Plato''s Symposium" and Allan Bloom''s provocative essay, "The Ladder of Love." In the Symposium, Plato recounts a drinking party following an evening meal, where the guests include the poet Aristophanes, the drunken Alcibiades, and, of course, the wise Socrates. The revelers give their views on the timeless topics of love and desire, all the while addressing many of the major themes of Platonic philosophy: the relationship of philosophy and poetry, the good, and the beautiful.', 'en', 2001, 199, 'http://books.google.com/books/content?id=0zoQDYBYTs4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1281', 'accepted', 'Plato; Seth Benardete', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 2 FROM public.book WHERE isbn13 = '9780226042756' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5b278578-2225-5a37-b5e0-5f60fb628f93', '9780226066660', 'Philosophy in a Time of Terror', 'Ze0Pn60iZvEC', '"In her introduction, Borradori contends that philosophy has an invaluable contribution to make to the understanding of terrorism. Just as the traumas produced by colonialism, totalitarianism, and the Holocaust wrote the history of the twentieth century, the history of the twenty-first century is already signed by global terrorism. Each dialogue here, accompanied by a critical essay, recognizes the magnitude of this upcoming challenge. Characteristically, Habermas''s dialogue is dense, compact, and elegantly traditional. Derrida''s, on the other hand, takes the reader on a long, winding, and unpredictable road. Yet unexpected agreements emerge between them: both have a deep suspicion of the concept of "terrorism" and both see the need for a transition from classical international law, premised on the model of nation-states, to a new cosmopolitan order based on continental alliances.".', 'en', 2004, 208, 'http://books.google.com/books/content?id=Ze0Pn60iZvEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1282', 'accepted', 'Jürgen Habermas; Giovanna Borradori; Jacques Derrida', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 8 FROM public.book WHERE isbn13 = '9780226066660' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a3c1cab7-b58d-53a0-852a-07f7fbfb1778', '9780226134345', 'A Preface to Democratic Theory, Expanded Edition', '95Zpl8C0-wYC', 'For this fiftieth-anniversary edition, Dahl has written an extensive new afterword that reevaluates Madisonian theory in light of recent research. And in a new foreword, he reflects back on his influential volume and the ways his views have evolved since he wrote it. For any student or scholar of political science, this new material is an essential update on a gold standard in the evolving field of democratic theory.', 'en', 2006, 200, 'http://books.google.com/books/content?id=95Zpl8C0-wYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1283', 'accepted', 'Robert A. Dahl', 'Political Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 5 FROM public.book WHERE isbn13 = '9780226134345' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8311f79d-d20b-54bd-bfde-02e6783abfde', '9780226142692', 'Lost Prophet', 'qnxMPwAACAAJ', 'A biographical tour de force on one of the 20th century''s bravest civil rights champions. Critically heralded American historian D''Emilio brings Bayard Rustin out of the shadows of the past to tell the story of a man who was a victim of homophobic prejudice.', 'en', 2004, 592, 'http://books.google.com/books/content?id=qnxMPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
