INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dd04d7e5-dcc5-5709-8aba-9a8d7d7615b7', '9780226301198', 'Love, Sex & Tragedy', '31udHwAACAAJ', 'A noted classicist offers a survey of the Greek and Roman roots of everything from hard bodies to political systems, tracing follies and philosophical questions through the centuries to the birthplace of Western civilization.', 'en', 2005, 345, 'http://books.google.com/books/content?id=31udHwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
