INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('37e326cf-3e36-5f76-b808-97eef8814bf3', '9780226321325', 'Billy Budd, Sailor', 'LMC-GqItKwkC', 'Definitive text of Billy Budd, Sailor, is presented with extensive notes and commentary enabling the reader to trace the genesis and growth of Melville''s masterpiece', 'en', 1962, 230, 'http://books.google.com/books/content?id=LMC-GqItKwkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
