INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('634ad6de-30c0-5b86-a810-25969d64352c', '9780226675763', 'Antitrust Law, Second Edition', 'wvkymAEACAAJ', 'When it was first published a quarter of a century ago, Richard Posner''s exposition and defense of an economic approach to antitrust law was a jeremiad against the intellectual disarray that then characterized the field. As other perspectives on antitrust law have fallen away, Posner''s book has played a major role in transforming the field of antitrust law into a body of economically rational principles largely in accord with the ideas set forth in the first edition. Today''s antitrust professionals may disagree on specific practices and rules, but most litigators, prosecutors, judges, and scholars agree that the primary goal of antitrust laws should be to promote economic welfare, and that economic theory should be used to determine how well business practices conform to that goal. In this thoroughly revised edition, Posner explains the economic approach to new generations of lawyers and students. He updates and amplifies his approach as it applies to the developments, both legal and economic, in the antitrust field since 1976. The "new economy," for example, has presented a host of difficult antitrust questions, and in an entirely new chapter, Posner explains how the economic approach can be applied to new industries such as software manufacturers, Internet service providers, and those that provide communications equipment and services. "The antitrust laws are here to stay," Posner writes, "and the practical question is how to administer them better-more rationally, more accurately, more expeditiously, more efficiently." This fully revised classic will continue to be the standard work in the field.', 'en', 2001, 304, 'http://books.google.com/books/content?id=wvkymAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1307', 'accepted', 'Richard A. Posner', 'Law', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 3 FROM public.book WHERE isbn13 = '9780226675763' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6ae43670-1b04-50d0-9e41-7646041cc50e', '9780226677149', 'A Dance to the Music of Time', 'PhGCnG7pbtkC', '"Movement 2. The rumble of distant events in Germany and Spain presages the storm of WWII. In England, even as the whirl of marriages and adulteries, fashions and frivolities, personal triumphs and failures gathers speed, men and women find themselves on the brink of fateful choices.', 'en', 1995, 718, 'http://books.google.com/books/content?id=PhGCnG7pbtkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
