INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a23ea0b1-2241-586f-a2fb-abc52106a853', '9780226777108', 'History of Political Philosophy', '5xK3wAEACAAJ', 'This volume provides an unequaled introduction to the thought of chief contributors to the Western tradition of political philosophy from classical Greek antiquity to the twentieth century. Written by specialists on the various philosophers, this third edition has been expanded significantly to include both new and revised essays.', 'en', 1987, 980, 'http://books.google.com/books/content?id=5xK3wAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1311', 'accepted', 'Leo Strauss; Joseph Cropsey', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 16 FROM public.book WHERE isbn13 = '9780226777108' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('afeef8f9-5dde-5075-96f2-3e928338485b', '9780226817415', 'From Counterculture to Cyberculture', 'wz5EmQEACAAJ', 'In the early 1960s, computers haunted the American popular imagination. Bleak tools of the cold war, they embodied the rigid organization and mechanical conformity that made the military-industrial complex possible. But by the 1990s—and the dawn of the Internet—computers started to represent a very different kind of world: a collaborative and digital utopia modeled on the communal ideals of the hippies who so vehemently rebelled against the cold war establishment in the first place. From Counterculture to Cyberculture is the first book to explore this extraordinary and ironic transformation. Fred Turner here traces the previously untold story of a highly influential group of San Francisco Bay–area entrepreneurs: Stewart Brand and the Whole Earth network. Between 1968 and 1998, via such familiar venues as the National Book Award–winning Whole Earth Catalog, the computer conferencing system known as WELL, and, ultimately, the launch of the wildly successful Wired magazine, Brand and his colleagues brokered a long-running collaboration between San Francisco flower power and the emerging technological hub of Silicon Valley. Thanks to their vision, counterculturalists and technologists alike joined together to reimagine computers as tools for personal liberation, the building of virtual and decidedly alternative communities, and the exploration of bold new social frontiers. Shedding new light on how our networked culture came to be, this fascinating book reminds us that the distance between the Grateful Dead and Google, between Ken Kesey and the computer itself, is not as great as we might think.', 'en', 2006, 327, 'http://books.google.com/books/content?id=wz5EmQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1312', 'accepted', 'Fred Turner', 'Social Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 13 FROM public.book WHERE isbn13 = '9780226817415' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('048e6956-4fec-5b61-bb7d-b4c00311bae9', '9780231054751', 'Genetics and the Origin of Species', 's7igybOj-dEC', 'Featuring an introduction by Stephen Jay Gould, "Genetics and the Origin of Species" presents the first edition of Dobzhansky''s groundbreaking and now classic inquiry into what has emerged as the most important single area of scientific inquiry in the twentieth century: biological theory of evolution. Genetics and the Origin of Species went through three editions (1937, 1941, and 1951) in which the importance accorded natural selection changed radically.', 'en', 1982, 364, 'http://books.google.com/books/content?id=s7igybOj-dEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1313', 'accepted', 'Theodosius Dobzhansky', 'Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 0 FROM public.book WHERE isbn13 = '9780231054751' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('47240091-20f7-56f8-b75a-244dc05410cf', '9780231073370', 'The Pillow Book of Sei Sh?nagon', 'H-F5iZeCMfQC', 'The Pillow Book of Sei Shonagon is an immensely detailed account of court life in eleventh-century Japan. Written at the height of Heian culture, it is a classic text of great literary beauty, full of lively anecdotes, humorous observations, and subtle impressions. Sei Shonagon was a contemporary and erstwhile rival of Lady Murasaki, whose novel, The Tale of Genji, fictionalized the court life that Lady Shonagon captures so vividly in her diary. The Pillow Book contains her reflections on royal and religious ceremonies, nature, pilgrimage, conversation, and poetry. Lady Shonagon shares character sketches and the things she both loves and loathes. Her style is so eloquent, her wit so sharp, even the briefest fragments enchant us. There is no better introduction to the daily preoccupations of the Heian upper class, and Ivan Morris''s notes and contextualization enrich the material for scholars and general readers.', 'en', 1991, 419, 'http://books.google.com/books/content?id=H-F5iZeCMfQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
