INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7e537877-91d1-5acf-8ba7-05222412970e', '9780231082815', 'Three Plays by Kobo Abe', 'D9GgngEACAAJ', 'Three plays by one of contemporary Japan''s most prominent writers -- Involuntary Homicide, The Green Stockings, The Ghost is Here -- translated for this volume reveal Kobo Abe''s deep love of absurdity in the face of universal concerns.', 'en', 1993, 233, 'http://books.google.com/books/content?id=D9GgngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
