INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('051d406d-d3b9-5560-b1ee-f62d9115d0e4', '9780231104470', 'The Columbia Reader on Lesbians and Gay Men in Media, Society, and Politics', 'bjeJCGF5OiUC', 'More than one hundred articles, essays, and primary documents cover the formation of gay identity, religious, scientific, medical, and legal perspectives, the mainstream media, lesbian and gay media, and community prospects and tactics--from Eve Kosofsky Sedgwick''s essay, "How to Bring Your Kids Up Gay," to Joseph Cardinal Ratzinger''s "Letter to the Bishops of the Catholic Church on the Pastoral Care of Homosexual Persons," to a 1947 Newsweek article, "Homosexuals in Uniform".', 'en', 1999, 672, 'http://books.google.com/books/content?id=bjeJCGF5OiUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1317', 'accepted', 'Larry P. Gross; James D. Woods', 'Social Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 9 FROM public.book WHERE isbn13 = '9780231104470' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('66dfc593-28fc-52fa-b75f-4ab13e9edb31', '9780231109253', 'Poems Between Women', 'd_1dqrZtllwC', 'The collection Poems Between Women explores many facets of female-female relationships in poems not only about love or affection between or inspired by women but also about the moments that complicate and call into question the nature of sexuality and intimacy between women. Including women married and single, young and old, lesbian, bisexual, and heterosexual, the anthology covers historical development and changing mores through the seventeenth century, after the Restoration of Charles II, a time of relative freedom for women; the eighteenth century, when the cult of romantic friendship reached its peak; the nineteenth century, when women writers wrote about issues of same-sex desire indirectly and explored complex issues such as death in tones of weariness and resignation; and the twentieth century, when poets began to engage in more overt explorations of women''s bodies, sensuality, and lovemaking. Emma Donoghue''s introduction deftly guides readers into the rich tradition of women''s poetry in English, exploring the relationships between poets and their muses and poets and their cultures. Poems Between Women is testimony not only to the recurring theme of the unique bonds among women but also to the universality of love, friendship, and creativity.', 'en', 1999, 256, 'http://books.google.com/books/content?id=d_1dqrZtllwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1318', 'accepted', 'Emma Donoghue', 'Poetry', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 8 FROM public.book WHERE isbn13 = '9780231109253' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('77fa7ebd-5862-5031-be66-0e7e94eecc9a', '9780231118958', 'Antigone''s Claim', 'pKerAgAAQBAJ', 'Why do smokers claim that the first cigarette of the day is the best? What is the biological basis behind some heavy drinkers'' belief that the "hair-of-the-dog" method alleviates the effects of a hangover? Why does marijuana seem to affect ones problem-solving capacity? Intoxicating Minds is, in the author''s words, "a grand excavation of drug myth." Neither extolling nor condemning drug use, it is a story of scientific and artistic achievement, war and greed, empires and religions, and lessons for the future. Ciaran Regan looks at each class of drugs, describing the historical evolution of their use, explaining how they work within the brain''s neurophysiology, and outlining the basic pharmacology of those substances. From a consideration of the effect of stimulants, such as caffeine and nicotine, and the reasons and consequences of their sudden popularity in the seventeenth century, the book moves to a discussion of more modern stimulants, such as cocaine and ecstasy. In addition, Regan explains how we process memory, the nature of thought disorders, and therapies for treating depression and schizophrenia. Regan then considers psychedelic drugs and their perceived mystical properties and traces the history of placebos to ancient civilizations. Finally, Intoxicating Minds considers the physical consequences of our co-evolution with drugs -- how they have altered our very being -- and offers a glimpse of the brave new world of drug therapies.', 'en', 2002, 118, 'http://books.google.com/books/content?id=pKerAgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1319', 'accepted', 'Judith Butler', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 16 FROM public.book WHERE isbn13 = '9780231118958' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d77029f0-f0f3-57bc-9918-81088a99006c', '9780231121002', 'The Vital Illusion', 'jk9MRcgG97EC', 'What does the advent of cloning mean for human beings? What does the turn of the millennium say about our relationship to time? The prophet of postmodernity untangles the "vital illusion" between the virtual and the actual, taking the pulse of humanity surrounded by a technological landscape.', 'en', 2000, 96, 'http://books.google.com/books/content?id=jk9MRcgG97EC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1320', 'accepted', 'Jean Baudrillard; Julia Witwer', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 14 FROM public.book WHERE isbn13 = '9780231121002' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f2abe4b1-fe28-51c3-bec6-ff30de9c1ddb', '9780231121255', 'An Arab-Syrian Gentleman and Warrior in the Period of the Crusades', 'xqy8ngEACAAJ', 'The life of Us?mah ibn-Munqidh epitomizes the height of Arab civilization during the early Crusading period. These memoirs--which represent a rare first-hand account of medieval European manners, morals, politics, and medicine written by a non-European--offers new perspective and insight into an important point of military and cultural contact between the East and West. In his introduction, translator Philip Hitti writes, "Ancient Arabic literature has preserved for us other biographies, memoirs, and reminiscences by great men, but there is hardly anything superior to this one in its simplicity of narrative, dignity, and wealth of contents and general human interest.', 'en', 2000, 265, 'http://books.google.com/books/content?id=xqy8ngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1321', 'accepted', 'Usāmah ibn Munqidh; Philip Khuri Hitti', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 10 FROM public.book WHERE isbn13 = '9780231121255' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('68b7470f-451c-5f76-8a2c-abce439fbc2c', '9780231121897', 'William Faulkner', 'G3_DKH4sX-4C', 'This book explores the puzzling phenomenon of new veiling practices among lower middle class women in Cairo, Egypt. Although these women are part of a modernizing middle class, they also voluntarily adopt a traditional symbol of female subordination. How can this paradox be explained? An explanation emerges which reconceptualizes what appears to be reactionary behavior as a new style of political struggle--as accommodating protest. These women, most of them clerical workers in the large government bureaucracy, are ambivalent about working outside the home, considering it a change which brings new burdens as well as some important benefits. At the same time they realize that leaving home and family is creating an intolerable situation of the erosion of their social status and the loss of their traditional identity. The new veiling expresses women''s protest against this. MacLeod argues that the symbolism of the new veiling emerges from this tense subcultural dilemma, involving elements of both resistance and acquiescence.', 'en', 1999, 192, 'http://books.google.com/books/content?id=G3_DKH4sX-4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
