INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7594b526-57aa-55ed-8aab-e589da49be93', '9780231121910', 'Nathaniel Hawthorne, The Scarlet Letter', 'OHFFpZosoC8C', 'Gives an account and a sampling of varied interpretations of Hawthorne''s "The Scarlet Letter," encompassing moral and historical criticism, New Criticism, archetypal and myth criticism, psychoanalytical and feminist criticism, and linguistic and semioticcriticism.', 'en', 2000, 192, 'http://books.google.com/books/content?id=OHFFpZosoC8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
