INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('96156a8b-9580-5c6a-b5fa-2af575221c36', '9780231124270', 'The Poetry of Sylvia Plath', 'TSrx1mELRBUC', 'Liquid Metal brings together ''seminal'' essays that have opened up the study of science fiction to serious critical interrogation. Eight distinct sections cover such topics as the cyborg in science fiction; the science fiction city; time travel and the primal scene; science fiction fandom; and the 1950s invasion narratives. Important writings by Susan Sontag, Vivian Sobchack, Steve Neale, J.P. Telotte, Peter Biskind and Constance Penley are included.', 'en', 1999, 202, 'http://books.google.com/books/content?id=TSrx1mELRBUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1324', 'accepted', 'Claire Brennan', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 20 FROM public.book WHERE isbn13 = '9780231124270' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('559758da-9df6-5088-aa4a-a810f2ce56ee', '9780231124928', 'The Intellectuals and the Flag', '4EVNgJIinV4C', 'Calls upon intellectuals on the left to once again engage American public life and resist the trappings of knee-jerk negativism, intellectual fads, and political orthodoxy. Gitlin argues for a renewed sense of patriotism based on the ideals of sacrifice, tough-minded criticism, and a willingness to look anew at the global role of the United States in the aftermath of 9/11. [Publisher web site].', 'en', 2006, 167, 'http://books.google.com/books/content?id=4EVNgJIinV4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
