INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('780a5dea-3f55-5dff-8ab3-0826028e7f93', '9780237525378', 'Oliver Twist', 'X6RvTDRdb1wC', 'This wonderful series is a quick way into a range of exciting stories, from the chilling tale of Frankenstein, to the gripping adventure of Treasure Island and the powerful animal story of Call of the Wild. Fast-moving and accessible, each story is a shortened, dramatically illustrated version of the classic novel, which loses none of the strength and flavour of the original.', 'en', 2003, 48, 'http://books.google.com/books/content?id=X6RvTDRdb1wC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
