INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b9f1313d-0668-50d9-beee-a040f1e85ad7', '9780241142462', 'The Best of McSweeney''s', 'TG0sAQAAIAAJ', 'The Best of McSweeney''s Volume 2 the second instalment of Dave Eggers''s crash course in what McSweeney''s is all about brings together more stories from the first ten issues of the magazine. Jonathan Ames, Judy Budnitz, Glen David Gold, Jonathan Lethem and A.M. Homes are amongst the writers spreading their wings in this fine collection and showing once more why McSweeney''s is now a byword for brilliance, innovation and the unexpected.', 'en', 2005, 384, 'http://books.google.com/books/content?id=TG0sAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
