INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6a0c14f3-564c-53d4-8701-7e84296de796', '9780253201621', 'Dante''s Vita Nuova', 'SWf4r6lObPMC', '"A fresh, new version of a 1962 translation that has had enormous popularity in comparative literature classes. The Vita Nuova (the New Life) is a small book which relates in prose and often very beautiful verse the story of the youthful Dante''s love for Beatrice. The esay which follows the translation provides new insights into this puzzling thirteenth-century work. Musa regards Dante''s intention in this so-called "Book of Memory" as a cruel and comic commentary on the youthful lover. He argues that Dante, using the tradition of love poetry current in his time, points up the foolishness and shallowness of his protagonist, a self-centered and self-pitying youth who only occasionally in the progress of his suffering catches even a glimpse of the true nature of Love or his beloved. "The sensitive man who would realize a man''s destiny must ruthlessly cut out of his heart the canker at its center [i.e. self-pity], the canker that the heart instinctively tends to cultivate." According to Musa, this is one of Dante''s central ideas. Dante scholars, libraries, and students of the Italian classics will welcome this distinguished translation and its provocative commentary"--Back cover.', 'en', 1973, 210, 'http://books.google.com/books/content?id=SWf4r6lObPMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
