INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('815be2b4-71ee-5ad6-9b16-7aac86879091', '9780253209108', 'Hegel''s Phenomenology of Spirit', 'fRMDS8-XLWYC', 'The text of Martin Heidegger''s 1930-1931 lecture course on Hegel''s Phenomenology of Spirit contains some of Heidegger''s most crucial statements about temporality, ontological difference and dialectic, and being and time in Hegel. Within the context of Heidegger''s project of reinterpreting Western thought through its central figures, Heidegger takes up a fundamental concern of Being and Time, "a dismantling of the history of ontology with the problematic of temporality as a clue." He shows that temporality is centrally involved in the movement of thinking called phenomenology of spirit.', 'en', 1994, 176, 'http://books.google.com/books/content?id=fRMDS8-XLWYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
