INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cd44e088-9d68-5194-abdf-e7c0f1bc12cf', '9780262240512', 'The Parallax View', 'PwJXmwEACAAJ', 'Seeks to rehabilitate dialectical materialism by discussing the "parallax gap," which separates two points because of the displacement of an object resulting from a change in observational position.', 'en', 2006, 433, 'http://books.google.com/books/content?id=PwJXmwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
