INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e1cf9813-6a7d-53b7-b7d5-dfa20ecc7645', '9780262532556', 'The Man Who Tasted Shapes', 'EvA5xS-qKR8C', 'Uncovers the strange medical mystery of synesthesia, a condition in which people can taste shapes or hear and smell colors, and suggests that everyone has synesthetic powers.', 'en', 2003, 296, 'http://books.google.com/books/content?id=EvA5xS-qKR8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
