INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d54bf435-6f5e-5570-9ea9-c2b17a06edff', '9780262540421', 'Elbow Room', 'P4NtNzOKxycC', 'Essays discuss reason, self-control, self-definition, time, cause and effect, accidents, and responsibility, and explain why people want free will', 'en', 1984, 200, 'http://books.google.com/books/content?id=P4NtNzOKxycC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
