INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a5cb6b2b-3ecf-59ae-8b26-31f69837d576', '9780262740159', 'Looking Awry', 'COT8nZsi6zYC', 'Slavoj Zizek, a leading intellectual in the new social movements that are sweepingEastern Europe, provides a virtuoso reading of Jacques Lacan. Zizek inverts current pedagogicalstrategies to explain the difficult philosophical underpinnings of the French theoretician andpractician who revolutionized our view of psychoanalysis. He approaches Lacan through the motifs andworks of contemporary popular culture, from Hitchcock''s Vertigo to Stephen King''s Pet Sematary, fromMcCullough''s An Indecent Obsession to Romero''s Return of the Living Dead - a strategy of "lookingawry" that recalls the exhilarating and vital experience of Lacan.Zizek discovers fundamentalLacanian categories the triad Imaginary/Symbolic/Real, the object small a, the opposition of driveand desire, the split subject - at work in horror fiction, in detective thrillers, in romances, inthe mass media''s perception of ecological crisis, and, above all, in Alfred Hitchcock''s films. Theplayfulness of Zizek''s text, however, is entirely different from that associated with thedeconstructive approach made famous by Derrida. By clarifying what Lacan is saying as well as whathe is not saying, Zizek is uniquely able to distinguish Lacan from the poststructuralists who sooften claim him.Slavoj Zizek is a Researcher in the Institute of Sociology at the University ofLjubljana, Yugoslavia. His work has been published in France and in Yugoslavia where, running as aproreform candidate, he narrowly missed being elected to the presidency of the republic ofSlovenia.', 'en', 1992, 188, 'http://books.google.com/books/content?id=COT8nZsi6zYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1365', 'accepted', 'Slavoj Žižek', 'Performing Arts', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 7 FROM public.book WHERE isbn13 = '9780262740159' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('129c8d61-4215-5107-a552-cd1e6725d468', '9780262740258', 'The Puppet and the Dwarf', 'jf4IPcBVKdMC', 'One of our most daring intellectuals offers a Lacanian interpretation of religion, finding that early Christianity was the first revolutionary collective. Slavoj Zizek has been called "an academic rock star" and "the wild man of theory"; his writing mixes astonishing erudition and references to pop culture in order to dissect current intellectual pieties. In The Puppet and the Dwarf he offers a close reading of today''s religious constellation from the viewpoint of Lacanian psychoanalysis. He critically confronts both predominant versions of today''s spirituality--New Age gnosticism and deconstructionist-Levinasian Judaism--and then tries to redeem the "materialist" kernel of Christianity. His reading of Christianity is explicitly political, discerning in the Pauline community of believers the first version of a revolutionary collective. Since today even advocates of Enlightenment like Jurgen Habermas acknowledge that a religious vision is needed to ground our ethical and political stance in a "postsecular" age, this book--with a stance that is clearly materialist and at the same time indebted to the core of the Christian legacy--is certain to stir controversy.', 'en', 2003, 196, 'http://books.google.com/books/content?id=jf4IPcBVKdMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1366', 'accepted', 'Slavoj Žižek; Žižek; Stockholm Inst Of Transition Staff; Mladen Dolar; Alenka Zupancic', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 9 FROM public.book WHERE isbn13 = '9780262740258' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a50bb48c-8de1-5498-bdcc-5fb5edc6fb8b', '9780268018498', 'Treatise on Happiness', 'MQh9QgAACAAJ', 'The Treatise on Happiness and the accompanying Treatise on Human Acts comprise the first twenty-one questions of I-II of the Summa Theologiae. From his careful consideration of what true happiness is, to his comprehensive discussion of how it can be attained, St. Thomas Aquinas offers a challenging and classic statement of the goals of human life, both ultimate and proximate. This translation presents in accurate, consistent, contemporary English the great Christian thinker''s enduring contributions on the subject of man''s happiness.', 'en', 1983, 224, 'http://books.google.com/books/content?id=MQh9QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1367', 'accepted', 'Saint Thomas (Aquinas); Thomas Aquinas', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 3 FROM public.book WHERE isbn13 = '9780268018498' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1590eaa3-9606-51ae-b91b-f4ede7851177', '9780273661948', 'Marketing and the Bottom Line', 'qeVE8r4ugzsC', 'Marketing and the bottom line sets out to change this. Based an extensive and original research involving world-beating companies such as 3M, Accenture, British Airways, Diageo and McDonald''s, this book analyzes the impact that marketing has on the financial well-being of a company. Viewing marketing as a strategic board-level function, Ambler sets out a new generation of marketing metrics designed to make marketing more accountable for what it does, what it spends and what it earns.', 'en', 2003, 336, 'http://books.google.com/books/content?id=qeVE8r4ugzsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1368', 'accepted', 'Tim Ambler', 'Business & Economics', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 9 FROM public.book WHERE isbn13 = '9780273661948' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('70c64f75-d0cf-51ab-8440-634989710d96', '9780273704744', 'Traders, Guns & Money', 'QLw2sjBuF9oC', 'Derivatives. Warren Buffett once called them ''financial weapons of mass destruction.'' Unlike some WMDs, however, derivatives are easy to find: nowadays, thousands of companies use them to make money and protect against risk. But most derivatives buyers simply don''t understand what they''re dealing with and sellers are in no rush to enlighten them. This book will! Traders, Guns and Money is a sensational first-person expose of the derivatives business, straight from one of the industry''s most widely-known experts. Satyajit Das has operated for decades on both the "buy" and "sell" side, and authored some of the field''s leading references. Now, he''s written the first no-holds-barred insider''s guide To The real derivatives business.', 'en', 2006, 334, 'http://books.google.com/books/content?id=QLw2sjBuF9oC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1369', 'accepted', 'Satyajit Das', 'Business & Economics', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 3 FROM public.book WHERE isbn13 = '9780273704744' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4f008d9d-5e8a-5948-9112-7759f013470e', '9780275942694', 'The Heights of Courage', '7aIXJkFzqe8C', 'In October 1973, the State of Israel was invaded by Egyptian and Syrian forces. Despite early losses, Israel managed to outfight its opponents. The brief and bloody Yom Kippur War stands as a unique chapter in modern military history. Fought primarily by tank units, the war became a story not only of battle strategy and tactics, but also one of human discipline, endurance and sacrifice. Avigdor Kahalani was commander of a tank battalion on the Golan Heights during the Yom Kippur War, in The Heights of Courage he describes this experience. Beginning with a description of the initial Syrian offensive, the author recounts the personal endeavours of the men in his battalion, their fears and ambitions, as well as their emotional and physical hardships. His account traces the efforts of the Israel Armoured Corps as they struggled to overcome extreme difficulties and setbacks in the field, and he describes their ultimate penetration into enemy territory.', 'en', 1992, 234, 'http://books.google.com/books/content?id=7aIXJkFzqe8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
