INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('da8d4f9e-7d9f-5bf2-ac1b-e9cd320109cb', '9780275991166', 'C. S. Lewis', 'mAL6V-aM7KkC', 'Examines the life and works of the British author and scholar, best known for his creation of "The Chronicles of Narnia" series.', 'en', 2007, 1416, 'http://books.google.com/books/content?id=mAL6V-aM7KkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
