INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4d85c99c-10cf-508e-b7f1-690cb0994b61', '9780285633148', 'The Lost World of Agharti', 'zcfiLwAACAAJ', 'For centuries, into our time, people have sought to discover the truth of the ancient legend of a hidden subterranean kingdom linked to every continent by a vast network of tunnels and passageways. The people who inhabit this utopia are said to have lived in seclusion for untold aeons, guarding the secret Vril Power by which man and nature can be controlled. This remarkable book records the findings of the many explorers who have sought to learn the truth and attempts to trace the course of the tunnels leading to Agharti.', 'en', 1996, 232, 'http://books.google.com/books/content?id=zcfiLwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1372', 'accepted', 'Alec Maclellan', 'Body, Mind & Spirit', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 17 FROM public.book WHERE isbn13 = '9780285633148' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0be43c96-abb8-565f-afd1-eeccebdb7223', '9780285635944', 'Zero', 'Yj1EPgAACAAJ', 'A NEW YORK TIMES NOTABLE BOOKThe Babylonians invented it, the Greeks banned it, the Hindus worshipped it, and the Christian Church used it to fend off heretics. Today it''s a timebomb ticking in the heart of astrophysics. For zero, infinity''s twin, is not like other numbers. It is both nothing and everything.Zero has pitted East against West and faith against reason, and its intransigence persists in the dark core of a black hole and the brilliant flash of the Big Bang. Today, zero lies at the heart of one of the biggest scientific controversies of all time: the quest for a theory of everything. Within the concept of zero lies a philosophical and scientific history of humanity.Charles Seife''s elegant and witty account takes us from Aristotle to superstring theory by way of Egyptian geometry, Kabbalism, Einstein, the Chandrasekhar limit and Stephen Hawking. Covering centuries of thought, it is a concise tour of a world of ideas, bound up in the simple notion of nothing.', 'en', 2003, 248, 'http://books.google.com/books/content?id=Yj1EPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1373', 'accepted', 'Charles Seife', 'Zero (The number)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 15 FROM public.book WHERE isbn13 = '9780285635944' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('333a20c1-f117-57ef-ae42-ca8e94e89728', '9780285647473', 'Zen Buddhism & Psychoanalysis', 'wMEAJwAACAAJ', 'The key book in our quest for understanding of ourselves and our lives.What differences are there in Eastern and Western thought regarding the nature of the human mind and our role in the cosmos? How can Zen and psychoanalysis help us in our struggle to realise our full potential as human beings and members of society?Erich Fromm''s seminal work among contemporary efforts to resolve our spiritual crisis results here in the great achievement of a language to reveal the contributions of Zen and psychoanalysis to our ''struggle to be fully born''. He shows how both can teach us in their different ways to live our lives rather than be ''lived by them''.D.T. Suzuki explains with profound and gentle wisdom how Western materialism and intellectualism contrast with the Eastern concept of acceptance as the basis of well-being for the ''whole man''. His illuminating discussion of the unconscious and the self shed fresh light on our understanding of our own nature.Combined with Richard De Martino''s clear account of the psychology of Zen, these writings make up a work of brilliance and value that has much to help us in our quest for understanding.', 'en', 1974, 188, 'http://books.google.com/books/content?id=wMEAJwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1374', 'accepted', 'Daisetz Teitaro Suzuki; Erich Fromm; Richard De Martino', 'Psychoanalysis and religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 13 FROM public.book WHERE isbn13 = '9780285647473' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3048f040-aeb5-50b6-b295-7d4009e17c96', '9780285647879', 'The Wanderer', 'RU1_QgAACAAJ', 'It has always been a pleasure to me to watch the flowers and insects in their struggle to keep alive. When the sun was hot they would come to life again, and give themselves up for an hour or so to the old delight; the big, strong flies were just as much alive as in midsummer. There was a peculiar sort of earth-bug here that I had not seen before--little yellow things, no bigger than a small-type comma, yet they could jump several thousand times their own length. Think of the strength of such a body in proportion to its size! There is a tiny spider here with its hinder part like a pale yellow pearl.', 'en', 2001, 164, 'http://books.google.com/books/content?id=RU1_QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
