INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d255313f-e195-5c10-ae97-c8b3ad37da32', '9780285648111', 'Memoirs', 'hUViQgAACAAJ', 'Pablo Neruda has been hailed as the greatest poet of the 20th century & was a Nobel laureat. In these memoirs he also recounts his distinguished career as a diplomat & politician, during which he came to know iconic figures including Gandhi, Che Guevara & Mao Tse Tung.', 'en', 2004, 378, 'http://books.google.com/books/content?id=hUViQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
