INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8dc9ae30-d5e4-588b-b1f1-09f1900085e3', '9780292701328', 'Paso Del Norte', 'nf_eDyxtbD0C', 'A major figure in the history of post-Revolutionary literature in Mexico, Juan Rulfo received international acclaim for his brilliant short novel Pedro Páramo (1955) and his collection of short stories El llano en llamas (1953), translated as a collection here in English for the first time. In the transition of Mexican fiction from direct statements of nationalism and social protest to a concentration on cosmopolitanism, the works of Rulfo hold a unique position. These stories of a rural people caught in the play of natural forces are not simply an interior examination of the phenomena of their world; they are written for the larger purpose of showing the actions of humans in broad terms of reality.', 'en', 1967, 191, 'http://books.google.com/books/content?id=nf_eDyxtbD0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
