INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e1074034-d377-526b-9e5c-5c2e982d74bf', '9780295979847', 'Philip Vera Cruz', '52PrdUKTUxgC', 'A lost chapter of both California labor history and the Asian American experience are eloquently brought to light in Philip Vera Cruz’s oral memoir. This account of an exceptional leader explores the unacknowledged role of Filipino laborers in the creation of the United Farm Workers union.', 'en', 2000, 208, 'http://books.google.com/books/content?id=52PrdUKTUxgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
