INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0bb1f33b-5676-587c-8910-3b1a0f0ba268', '9780299125400', 'Mark Twain''s Own Autobiography', 'ZehUN4w4ZxwC', 'Fifteen studies are grouped into three closely related themes identified as 1) textual construction of the professions--the ways in which texts help shape professional perspectives of human experience; 2) the dynamics of discourse communities--the discursive process as a means of enrolling outsiders into an insider''s views and commitments; and 3) the dynamics of how texts, originating within specialized discourse communities, can profoundly influence a wide range of social activities. Paper edition (unseen), $15.75. Annotation copyrighted by Book News, Inc., Portland, OR', 'en', 1990, 301, 'http://books.google.com/books/content?id=ZehUN4w4ZxwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
