INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('551fd383-6259-5d40-a2c1-66e4ac5912eb', '9780299178000', 'Letters to J. D. Salinger', 'zL13dNDYjccC', 'Presents nearly eighty personal letters addressed to the reclusive author of The Catcher in the Rye by such noted authors, editors, journalists, and critics as Frederick Busch, Nicholas Delbanco, Stewart O''Nan, George Plimpton, Melanie Rae Thon, W. P. Kinsella, and others.', 'en', 2002, 270, 'http://books.google.com/books/content?id=zL13dNDYjccC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
