INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b164911f-dc5a-5cd1-b78e-847efcab8be2', '9780300000894', 'Psychoanalysis and Religion', 'gtAgGreKUcEC', 'A noted psychoanalyst assesses the modern issue between traditional religion and a philosophy that takes as the sole aim in life the satisfaction of instinctive and material values. "A daring book to have cast into the midst of the world''s excitements, for it will itself breed new excitements...it is not a book to be missed by those interested in man''s spiritual growth."--New York Times', 'en', 1950, 126, 'http://books.google.com/books/content?id=gtAgGreKUcEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1384', 'accepted', 'Erich Fromm', 'Psychology', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 5 FROM public.book WHERE isbn13 = '9780300000894' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d320335c-cdc9-5d42-a82c-10044880bcf1', '9780300044881', 'Euthyphro, Apology, Crito, Meno, Gorgias, Menexenus', 'fkTYyAEACAAJ', 'Annotation. Among Plato''s later dialogues, the Parmenides is one of the most significant. Not only a document of profound philosophical importance in its own right, it also contributes to the understanding of Platonic dialogues that followed it, and it exhibits the foundations of the physics and ontology that Aristotle offered in his Physics and Metaphysics VII. In this book, R.E. Allen provides a superb translation of the Parmenides along with a structural analysis that procedes on the assumption that formal elements, logical and dramatic, are important to its interpretation and that the argument of the Parmenides is aporetic, a statement of metaphysical perplexities. Allen''s original translation of and commentary on the Parmenides were published in 1983 to great acclaim and have now been revised by the author.', 'en', 1984, 352, 'http://books.google.com/books/content?id=fkTYyAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
