INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('552d1253-3efb-5c24-86df-e297a3601846', '9780300090956', 'Leonardo on Painting', 'roHf588GZJYC', 'This is a selection of Leonardo da Vinci''s writings on painting. Martin Kemp and Margaret Walker have edited material not only from his so-called Treatise on Painting but also from his surviving manuscripts and from other primary sources.', 'en', 2001, 336, 'http://books.google.com/books/content?id=roHf588GZJYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
