INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0f50e0e9-873c-559d-ae0f-5dd3918a5d11', '9780300093049', 'Art and Beauty in the Middle Ages', 'uT61fJtcHroC', 'In this authoritative, lively book, the celebrated Italian novelist and philosopher Umberto Eco presents a learned summary of medieval aesthetic ideas. Juxtaposing theology and science, poetry and mysticism, Eco explores the relationship that existed between the aesthetic theories and the artistic experience and practice of medieval culture. "[A] delightful study. . . . [Eco''s] remarkably lucid and readable essay is full of contemporary relevance and informed by the energies of a man in love with his subject."--Robert Taylor, Boston Globe "The book lays out so many exciting ideas and interesting facts that readers will find it gripping."--Washington Post Book World "A lively introduction to the subject."--Michael Camille, The Burlington Magazine "If you want to become acquainted with medieval aesthetics, you will not find a more scrupulously researched, better written (or better translated), intelligent and illuminating introduction than Eco''s short volume."--D. C. Barrett, Art Monthly', 'en', 2002, 144, 'http://books.google.com/books/content?id=uT61fJtcHroC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
