INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3aac06ef-aba4-59f5-946d-723018afa672', '9780300094008', 'Marcel Proust', 'NxTaYm26Q1cC', 'This book is a magisterial account of the life and times of Marcel Proust. Based on a host of recently available letters, memoirs, and manuscripts, it sheds new light on Proust''s character, his development as an artist, and his masterpiece "In Search of Lost Time" (long known in English as "Remembrance of Things Past"). 47 illustrations.', 'en', 2002, 992, 'http://books.google.com/books/content?id=NxTaYm26Q1cC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
