INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bbd2583f-1a31-55f4-93f1-ff422e345dfe', '9780306804984', 'Hannibal', 'TZLStAEACAAJ', 'In the year 216 B.C., Hannibal of Carthage, faced with an opposing Roman army twice the size of his own, outwitted the enemy at Cannae by means of a strategy which has become a classic of its kind. As a result of his famous ”double pincer” maneuver, 70,000 Roman soldiers died within the space of a few hours on a field the size of New York''s Central Park. Yet, as devastating and startling as Cannae was, it was only one of a long list of incredible achievements. Hannibal''s fantastic 1,000-mile march across the Alps from Spain to Italy was one of the wonders of ancient times. He began his hazardous journey with 90,000 infantry, 12,000 cavalry, and 37 elephants. By the time he reached the Valley of the Po, more than 30,000 troops and many of his elephants had perished, but he still managed to stay in Italy for sixteen years.Blending biography and military adventure, Hannibal is a portrait of a military genius who was also a highly civilized man. The son of Hamilcar Barca, a famous general in his own right, Hannibal was a student of the Greek classics. But his father''s lifelong grudge against Rome fostered in the son a deep hatred for that Republic and a fierce determination to subdue it forever. This resulted in the bloody battles of Lake Trasimene, Campania, Nole, Capua, and Zama, all of which Leonard Cottrell describes with vigor and authority. In gathering material for Hannibal, Cottrell traveled the entire route that Hannibal took across the Alps, thus bringing to his account a valuable firsthand knowledge of his subject. With the drama and authenticity for which he is famous, Leonard Cottrell describes Hannibal''s amazing campaign—a saga of victory after victory which fell just short of its ultimate goal: the annihilation of Rome.', 'en', 1992, 248, 'http://books.google.com/books/content?id=TZLStAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1400', 'accepted', 'Leonard Cottrell', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 11 FROM public.book WHERE isbn13 = '9780306804984' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a8e9f29c-6647-5fae-990e-d0cb348d31fa', '9780306805622', 'The Collapse of the Third Republic', 'IdyBPwAACAAJ', 'On June 17, 1940 William L. Shirer stood in the streets of Paris and watched the unending flow of gray German uniforms along its boulevards. In just six lovely weeks in the spring and summer of 1940 a single battle brought down in total military defeat one of the world''s oldest, greatest, and most civilized powers—the second mightiest empire on earth and the possessor of one of the finest military machines ever assembled. How did it happen? After nearly a decade of research in the massive archives left from World War II and after hundreds of conversations with the Third Republic’s leaders, generals, diplomats, and ordinary citizens, Shirer presents the definitive answer in his stunning re-creation of why and how France fell before Hitler''s armies in 1940. His book is also a devastating examination of the confusion, corruption, and cynicism that drained the strength and toughness of a democracy which Thomas Jefferson once called "every man''s second country." This book complements and completes the dramatic story of The Rise and Fall of the Third Reich and continues to rank as one of the most important works of history of our time.', 'en', 1994, 1082, 'http://books.google.com/books/content?id=IdyBPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1401', 'accepted', 'William Lawrence Shirer', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 16 FROM public.book WHERE isbn13 = '9780306805622' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('44c7c061-12bf-5771-834b-43b146037920', '9780306808821', 'The Complete Short Stories Of Robert Louis Stevenson', 'qDS8tQEACAAJ', 'Scottish novelist, poet, and essayist Robert Louis Stevenson (1850–1894) was a writer of power and originality, who penned such classics as Treasure Island, Kidnapped, and The Weir of Hermiston. The editor has collected in convenient form Stevenson''s short fiction, including the complete New Arabian Nights and The Strange Case of Dr. Jekyll and Mr. Hyde, as well as ghost stories, medieval romances, farces, horror stories, and the South Sea Tales. This volume amply illustrates Stephenson''s wide range and enduring appeal.', 'en', 1998, 720, 'http://books.google.com/books/content?id=qDS8tQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1402', 'accepted', 'Charles Neider; Robert Louis Stevenson', 'Literary Collections', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 8 FROM public.book WHERE isbn13 = '9780306808821' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f79d0954-a7a1-5034-a640-cdc55cbeb475', '9780306808906', 'Hemingway', 'uWPGtAEACAAJ', 'Distinguished by its precision, its graceful use of language, and its resonant depth, the innovative style of Nobel Prize-winning author Ernest Hemingway (1899-1961) radically altered literary conventions and influenced generations of writers. In The Sun Also Rises, A Farewell to Arms, For Whom the Bell Tolls, The Old Man and the Sea, and numerous short stories, he explored such universal themes as stoicism in adversity, as well as our futile struggles against nature and mortality.This evocative, sympathetic biography illuminates the events that informed Hemingway''s vigorous life: an accident-prone youth and early rivalry with his father; his experiences in World War I, the Spanish Civil War, and World War II; his stormy relationships with writers and women; his sudden fame, slow decline, and suicide. Based on previously unavailable information and exclusive interviews, Hemingway enriches anyone''s understanding and appreciation of America''s most important twentieth-century writer.', 'en', 1999, 644, 'http://books.google.com/books/content?id=uWPGtAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
