INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8a24ef0d-0334-5c56-990d-fc6491a4df70', '9780306809323', 'The Dark Side Of Genius', '2FpPtAEACAAJ', 'This is the definitive life story of Alfred Hitchcock, the enigmatic and intensely private director of Psycho, Vertigo, Rear Window, The Birds, and more than forty other films. While setting forth every stage of Hitchcock''s long life and brilliant career, Donald Spoto also explores the roots of the director''s obsessions with blondes, food, murder, and idealized love—and he traces the incomparable, bizarre genius from Hitchcock''s English childhood through the golden years of his career in America as one of the greatest directors in the history of filmmaking.', 'en', 1999, 608, 'http://books.google.com/books/content?id=2FpPtAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
