INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('79fcdc75-c6a2-5715-8f51-59b9d4677017', '9780307264657', 'Terrorist', 'KlFnmmF0IJcC', 'Eighteen-year-old Ahmad, the son of an Irish-American mother and long-gone Egyptian father, is contemptuous of the self-indulgent society surrounding him, and devoted to the teachings of Islam, becomes drawn into an insidious terrorist plot.', 'en', 2006, 320, 'http://books.google.com/books/content?id=KlFnmmF0IJcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
