INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d3bf5ef7-e9f7-5245-9bd0-67cf16c9403f', '9780310257868', 'Becoming a Contagious Christian', 'm4GxAYrSmyMC', 'Over one million people have experienced the groundbreaking evangelism training course Becoming a Contagious Christian -- a proven resource designed to equip believers for relational evangelism. Now revised and updated, it avoids stereotyped approaches that feel intimidating to many Christians -- and to their friends! Instead, it shows ordinary believers how to share the gospel in natural and effective ways being the person God made them to be. This participant''s guide is designed to help you get the most out of the Becoming a Contagious Christian course. By applying training principles to real-life situations and relationships, you''ll identify and develop an evangelism style that''s effective for you. DVD segments, as well as individual and group activities, will help you gain confidence and equip you to: Discover your own style of communicating about Christ Build spiritually significant relationships Direct conversations toward matters of faith Tell your own story of coming to faith Use easy-to-remember gospel illustrations Pray with someone to receive Christ, and more! Designed for use with the revised and updated Becoming a Contagious Christian kit and small group DVD editions.', 'en', 2007, 299, 'http://books.google.com/books/content?id=m4GxAYrSmyMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1444', 'accepted', 'Mark Mittelberg; Lee Strobel; Bill Hybels', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 4 FROM public.book WHERE isbn13 = '9780310257868' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f6b20331-1e98-5207-82d0-5305d5f72182', '9780310259664', 'Journey into God''s Word', 'Yg9xDiYmaR8C', 'Life is a journey, and like any journey, it requires an accurate, reliable roadmap to get us where we need to go. God has provided such a guide in his Word. But just as a navigator needs to learn how to interpret all the contours and symbols of a map, so also we need to be able to understand how the Bible communicates its directions to us. Journey Into God''s Word helps Bible readers acquire these skills and become better at reading, interpreting, and applying the Bible to life. This abridgment of the bestselling college/seminary textbook Grasping God''s Word takes the proven principles from that book and makes them accessible to people in the church. It starts with general principles of interpretation, then moves on to apply those principles to specific genres and contexts. Hands-on exercises guide readers through the interpretation process, with an emphasis on real-life application.', 'en', 2005, 462, 'http://books.google.com/books/content?id=Yg9xDiYmaR8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
