INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f76c7cd5-e11d-55de-99ba-1bbecddea756', '9780312132149', 'White Man''s Grave', 'OIk_WGE4UhkC', 'When a Peace Corps volunteer disappears in the African wilds, his father and his friend go after him, believing that American power and influence encompass the globe--but soon encounter greater powers and a mystery beyond their control. Reprint.', 'en', 1995, 400, 'http://books.google.com/books/content?id=OIk_WGE4UhkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
