INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c10d4f6c-16b4-5432-815b-b4cf4c49bb63', '9780312135256', 'Isak Dinesen', 'atV8pWcV_CIC', 'Winner of the National Book Award A brilliant literary portrait, Isak Dinesen remains the only comprehensive biography of one of the greatest storytellers of our time. Her magnificent memoir, Out of Africa, established Isak Dinesen as a major twentieth-century author, who was twice nominated for the Nobel Prize. With exceptional grace, Judith Thurman''s classic work explores Dinesen''s life. Until the appearance of this book, the life and art of Isak Dinesen have been--as Dinesen herself wrote of two lovers in a tale-- "a pair of locked caskets, each containing the key to the other." Judith Thurman has provided the master key to them both.', 'en', 1995, 512, 'http://books.google.com/books/content?id=atV8pWcV_CIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
