INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dc97f434-ec5d-56e6-87c5-6e43bcb24c24', '9780312143404', 'Four Weddings and a Funeral', 'iFY9e377DRIC', 'The hilarious, Academy Award-nominated screenplay that features six old friends, three disastrous receptions, a tongue-tied priest, and the role that made Hugh Grant the world''s favorite bumbling bachelor. Toasted by romantics and cynics, critics and fans, Four Weddings and a Funeral grossed more than $250 million worldwide, garnered Academy Award nominations for Best Picture and Best Original Screenplay, and was unanimously pronounced the romantic comedy of the 90s. Richard Curtis''s smart, irreverent, and brilliantly crafted screenplay will delight fans of the movie, as well as screenwriters and film students. From the first spoken line to the last ("I do"), it''s a jubilant celebration of friendship, romance, and good humor.', 'en', 1996, 128, 'http://books.google.com/books/content?id=iFY9e377DRIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
