INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ed45df6a-3cbc-5720-a8ac-6d5fb1084754', '9780312157111', 'The Communist Manifesto: Marx', 'dhK7wAEACAAJ', 'This is an edition of The Communist Manifesto with related documents. A 30-page introduction traces the trajectory of Marx''s thought from the 1840s onward and provides background on the political, social and intellectual contexts of which the Manifesto was an historical product. Accompanying the Manifesto are 8 additional documents that show the evolution of and influences on Marx''s thought over time. A Marx-Engels chronology, questions for consideration, a bibliography, illustrations, a glossary of terms and an index are also included.', 'en', 1999, 184, 'http://books.google.com/books/content?id=dhK7wAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
