INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3b13b809-1871-565e-bb45-eae61d7b0097', '9780312199432', 'One Thousand White Women', 'AS-xz-xoHmYC', 'One Thousand White Women is the story of May Dodd and a colorful assembly of pioneer women who, under the auspices of the U.S. government, travel to the western prairies in 1875 to intermarry among the Cheyenne Indians. The covert and controversial "Brides for Indians" program, launched by the administration of Ulysses S. Grant, is intended to help assimilate the Indians into the white man''s world. Toward that end May and her friends embark upon the adventure of their lifetime. Jim Fergus has so vividly depicted the American West that it is as if these diaries are a capsule in time.', 'en', 1999, 434, 'http://books.google.com/books/content?id=AS-xz-xoHmYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
