INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b4351982-ccca-58b6-8d11-e9433e8d3941', '9780312202057', 'Requiem for Harlem', 'JDTsV63ow-UC', 'The fourth and final volume of the epic series Mercy of a Rude Stream, by one of the century''s most respected authors, follows a tormented love affair while recreating the world of Jewish Harlem and bohemian Greenwich Village. Reprint. 15,000 first printing.', 'en', 1998, 304, 'http://books.google.com/books/content?id=JDTsV63ow-UC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
