INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c32efd10-7e9a-578b-94c1-7e51c0049de6', '9780312263232', 'Four Mothers', 'md0QD7R6f2kC', 'This beautifully imagined debut novel tells the story of five generations of women in one family against the backdrop of 100 years in Jerusalem. Starting with the birth of the family''s first boy to the last generation, this epic is rich in the magical realism of fable and folklore.', 'en', 2000, 276, 'http://books.google.com/books/content?id=md0QD7R6f2kC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
