INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('768c28e2-2e8e-5942-8f6a-0ca19a627a2b', '9780312277109', 'An Unfortunate Woman', 'Fx4k5hJwYrEC', 'Completed prior to the author''s 1984 suicide, a last unpublished novel explores what he terms the fragile and mysterious shadowland surrounding death and considers the protagonist''s ruminations on another person''s suicide. By the author of Trout Fishing in America. Reprint. 35,000 first printing.', 'en', 2001, 132, 'http://books.google.com/books/content?id=Fx4k5hJwYrEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
