INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f63765a5-7c12-5e27-bf56-51131c126b44', '9780312288013', 'Serious Girls', 'mF4yPQAACAAJ', 'Sixteen year olds Maya and Roe form an intense friendship when they find themselves cast as outsiders at an all girls boarding school. Sharing their life stories, and curiosity about the adult world, they wonder how they might become "people" with style and character as opposed to school girls. When they move beyond the enclosed world of the school to experience the city, and relationships with men, both girls test the line between an emerging sense of self and its total disintegration.', 'en', 2004, 240, 'http://books.google.com/books/content?id=mF4yPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
