INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f5a4867c-a115-525a-a47d-3bfd82249f50', '9780312339012', 'Where the Mountain Casts Its Shadow', 'ZOomkQfnWsAC', 'Shares the personal behind-the-scenes stories of famous mountaineers to reveal the events that compelled them to risk their lives and personal relationships, in a collection of portraits that includes coverage of such adventurers as Jim Wickwire, Conrad Anker, and Lynn Hill. Reprint. 15,000 first printing.', 'en', 2005, 256, 'http://books.google.com/books/content?id=ZOomkQfnWsAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
