INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('212a6b36-554b-5e25-8dba-7055e0f3dbe1', '9780312354077', 'Dirty Little Secrets', 'bJqBvgEACAAJ', 'A young, hip, sexy novel that takes readers behind the velvet rope of the glamorous and shady entertainment industry Nothing prepares Tyler Blake for the fast-paced living of New York City. A small-town girl from Georgia, she quickly gets caught up in the glamorous entertainment industry. While pursuing her dream of becoming an actress, Tyler continually gets sidetracked by men who promise to help her and finds herself going from one dysfunctional relationship to another. Just when Tyler finally believes she has found her ideal man, in hip-hop producer Brian McCall, everything begins to go horribly wrong. Trapped in a nightmarish relationship, Tyler is determined not to go down without a fight. "Passion, deception, heartbreak, love and a delicious read...what more do you need!" -- B. Lawson Thornton, Essence bestselling author of Misery Loves Company', 'en', 2006, 256, 'http://books.google.com/books/content?id=bJqBvgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
