INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7267ad19-ce0b-5ab4-b2e1-481c60e0d779', '9780312354954', 'The Devil in the Junior League', 'qHDjN1BLI6kC', 'A member of the exclusive Junior League of Willow Creek, Texas, Fredericka Mercedes Hildebrand Ware''s perfect life begins to unravel when her husband betrays her, steals her money, and vanishes, and the only way she can keep from becoming fodder in the JLWC gossip mill is to get the tacky wife of wealthy but tasteless lawyer Howard Grout into the elite society. 100,000 first printing.', 'en', 2006, 336, 'http://books.google.com/books/content?id=qHDjN1BLI6kC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
