INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c8228a56-6db5-531f-bed7-4b9f2cc02ec4', '9780312357771', 'The Silver Pigs', 'a0wmuQEACAAJ', 'When Marcus Didius Falco, a Roman "informer" who has a nose for trouble that''s sharper than most, encounters Sosia Camillina in the Forum, he senses immediately all is not right with the pretty girl. She confesses to him that she is fleeing for her life, and Falco makes the rash decision to rescue her--a decision he will come to regret. For Sosia bears a heavy burden: as heavy as a pile of stolen Imperial ingots, in fact. Matters just get more complicated when Falco meets Helena Justina, a Senator''s daughter who is connected to the very same traitors he has sworn to expose. Soon Falco finds himself swept from the perilous back alleys of Ancient Rome to the silver mines of distant Britain--and up against a cabal of traitors with blood on their hands and no compunction whatsoever to do away with a snooping plebe like Falco....', 'en', 2006, 329, 'http://books.google.com/books/content?id=a0wmuQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
