INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4ff52b02-8be0-55a0-8727-09cf0cba45a9', '9780312423674', 'Primo Levi', 'mGzmdvFtIXkC', 'A profile of the author of Survival in Auschwitz and The Periodic Table examines his daily experiences as a paint factory manager who tended an invalid mother and lived in the same house his entire life, discussing the impact of such factors as Mussolini''s regime, his difficult reintegration into postwar Italy, and his struggles with depression and insomnia. Reprint. 10,000 first printing.', 'en', 2004, 640, 'http://books.google.com/books/content?id=mGzmdvFtIXkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
