INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0f722088-e60f-5df2-982e-d92bcef0336a', '9780312424084', 'A Home at the End of the World', 'MwMEpfe72u4C', 'From the Pulitzer Prize-winning author of "The Hours" comes the masterful story of a unique family that is formed when Jonathan moves to New York to live with boyhood friend Bobby and Clare, a veteran of the city''s erotic wars. Soon to be a motion picture starring Colin Farrell, Sissy Spacek, and Robin Wright Penn.', 'en', 2004, 342, 'http://books.google.com/books/content?id=MwMEpfe72u4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
