INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3a80739a-f6fc-5466-8bc3-dd99b9fc87c6', '9780312424121', 'Call It Sleep', 'HdZwPwAACAAJ', 'When Henry Roth published his debut novel Call It Sleep in 1934, it was greeted with considerable critical acclaim though, in those troubled times, lackluster sales. Only with its paperback publication thirty years later did this novel receive the recognition it deserves—--and still enjoys. Having sold-to-date millions of copies worldwide, Call It Sleep is the magnificent story of David Schearl, the "dangerously imaginative" child coming of age in the slums of New York.', 'en', 2005, 462, 'http://books.google.com/books/content?id=HdZwPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
