INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('22002ca5-15e3-53fa-981c-16976e746265', '9780312424916', 'Saints at the River', 'YlTVmAEACAAJ', 'When a twelve-year-old girl drowns in the Tamassee River and her body is trapped in a deep eddy, the people of the small South Carolina town that bears the river''s name are thrown into the national spotlight. The girl''s parents want to attempt a rescue of the body; environmentalists are convinced the rescue operation will cause permanent damage to the river and set a dangerous precedent. Torn between the two sides is Maggie Glenn, a twenty-eight-year-old newspaper photographer who grew up in the town and has been sent to document the incident. Since leaving home almost ten years ago, Maggie has done her best to avoid her father, but now, as the town''s conflict opens old wounds, she finds herself revisiting the past she''s fought so hard to leave behind.', 'en', 2005, 239, 'http://books.google.com/books/content?id=YlTVmAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
