INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9336f0bb-abb0-546d-bd86-6560d0faa50c', '9780312425081', 'Chemistry and Other Stories', 'lyFJyJXwL30C', 'Spanning the entire twentieth century, a collection of short stories, set against the backdrop of Appalachia, chronicles the struggle of rural communities with the changes of the modern world, capturing the collision between the Old and New South in the lives of the region''s inhabitants. Original. 20,000 first printing.', 'en', 2007, 230, 'http://books.google.com/books/content?id=lyFJyJXwL30C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
