INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('29353087-bc17-5855-96e8-033537986d61', '9780312862176', 'The Dark Descent', 'pNgZxdPETK0C', 'Traces the evolution of the horror story by presenting an anthology of works from the past and from current writers, with contributions from Stephen King, H.P. Lovecraft, Harlan Ellison, Charles L. Grant, and Clive Barker', 'en', 1997, 1011, 'http://books.google.com/books/content?id=pNgZxdPETK0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
