INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3edc086d-bfce-58d5-af2a-4124c0deaf9a', '9780312869595', 'Jack of Kinrowan', 'FcODdbHfSbgC', 'The two stories of Jacky Rowan are combined into one volume, which tells the complete story of how she is dumped into the perilous land of the Faerie and how her enslavement is broken by a young fiddler. Reprint. 20,000 first printing.', 'en', 1999, 412, 'http://books.google.com/books/content?id=FcODdbHfSbgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
