INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('63bf40bc-a4e1-5e08-bfa6-6a2f19249aa5', '9780312872793', 'Lurulu', 'Jm3auoBpHUsC', 'Continues the adventures of Myron Tany, a rebellious member of a wealthy family, who tours the Galaxy on an interstellar freighter alongside a crew of actors, musicians, thieves, and other questionable characters. By the author of Ports of Call. Reprint. 15,000 first printing.', 'en', 2007, 204, 'http://books.google.com/books/content?id=Jm3auoBpHUsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
