INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1d99ebb2-4240-5418-8cac-b73b3b4213ba', '9780312873110', 'The Land of Laughs', 'OUIAmQEACAAJ', 'Have you ever loved a magical book above all others? Have you ever wished the magic were real? Welcome to The Land of Laughs. A novel about how terrifying that would be. Schoolteacher Thomas Abbey, unsure son of a film star, doesn''t know who he is or what he wants--in life, in love, or in his relationship with the strange and intense Saxony Gardner. What he knows is that in his whole life nothing has touched him so deeply as the novels of Marshall France, a reclusive author of fabulous children''s tales who died at forty-four. Now Thomas and Saxony have come to France''s hometown, the dreamy Midwestern town of Galen, Missouri, to write France''s biography. Warned in advance that France''s family may oppose them, they''re surprised to find France''s daughter warmly welcoming instead. But slowly they begin to see that something fantastic and horrible is happening. The magic of Marshall France has extended far beyond the printed page...leaving them with a terrifying task to undertake.', 'en', 2001, 256, 'http://books.google.com/books/content?id=OUIAmQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
