INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('74c7a769-110a-5626-a7fd-e2edab612469', '9780312874568', 'Tales of the Dying Earth', 'Y_HRpJHlylUC', 'A first-time compilation of a classic science fiction series gathers all four books of The Dying Earth series--The Dying Earth, The Eyes of the Overworld, Cugel''s Saga, and Rialto the Magnificent--in which Earth, in the distant future, tries to survive the approaching death of its red sun. Reprint. 12,500 first printing.', 'en', 2000, 741, 'http://books.google.com/books/content?id=Y_HRpJHlylUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
