INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b59e763d-e4bf-562c-ad7d-337b6469c727', '9780312877514', 'Lovelock', '0xpWmAEACAAJ', 'Lovelock is a capuchin monkey engineered to be the perfect servant--intelligent, agile, pliant, and devoted to his owner. He is a Witness--privileged to spend his days and nights observing the life of one of Earth''s most brilliant scientists through digital recording devices behind his eyes. In his heart is the desire to please, not just to avoid the pain his owner can inflict with a word, but because he loves her. Lovelock is on a voyage he did not choose. What human would consider the feelings of a capuchin monkey, no matter how enhanced? But Lovelock is something special among Witnesses--he''s a little smarter than most humans; smart enough to break through some of his conditioning. Smart enough to feel the bonds of slavery, and want freedom.', 'en', 2001, 288, 'http://books.google.com/books/content?id=0xpWmAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
