INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5e18ee34-70f8-54df-b8f6-c95f9805bb8f', '9780312890384', 'Pacific Edge', 'H_ubx3mtdPwC', 'Set at the end of the 21st century in California, this story revolves around a seemingly perfect society. At first, bio-architect Kevin Claiborne thinks he has indeed found Utopia, but gradually events lead him to discover the corruption beneath the surface.', 'en', 1995, 336, 'http://books.google.com/books/content?id=H_ubx3mtdPwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
