INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8fdc9cb7-2802-53ac-bbf9-3742c6389a8c', '9780312929640', 'The Circle', 'N-H70tCN0S8C', 'Fresh from Annapolis, Dan Lenson boards an antiquated destroyer headed for the Arctic Circle, where he and the crew encounter a rogue sub, violent weather, and possible court martial', 'en', 1993, 543, 'http://books.google.com/books/content?id=N-H70tCN0S8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
