INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d33e6093-ab36-550f-bb2f-0eb41e576de8', '9780312932787', 'Faking It', 'LkyHoWezX70C', 'Matilda Goodnight and Davy Dempsy are both trying to get the upper hand with the gorgeous gold-digging Clea Lewis, but they will forge a temporary if reluctant alliance to take on an inept art collector, a disgruntled heir, an exasperated hitmat, and a seductive femme fatale as they deal with false identities, forged paintings, swindles, and love. 100,000 first printing.', 'en', 2004, 448, 'http://books.google.com/books/content?id=LkyHoWezX70C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
