INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('532b5e7f-8f39-5f40-86e2-e34821e46281', '9780312982010', 'Abandoned Prayers', 'qWw4mQEACAAJ', 'On Christmas Eve in 1985, a hunter found a young boy''s body along an icy corn field in Nebraska. The residents of Chester, Nebraska buried him as "Little Boy Blue," unclaimed and unidentified-- until a phone call from Ohio two years later led authorities to Eli Stutzman, the boy''s father. Eli Stutzman, the son of an Amish bishop, was by all appearances a dedicated farmer and family man in the country''s strictest religious sect. But behind his quiet façade was a man involved with pornography, sadomasochism, and drugs. After the suspicious death of his pregnant wife, Stutzman took his preschool-age son, Danny, and hit the road on a sexual odyssey ending with his conviction for murder. But the mystery of Eli Stutzman and the fate of his son didn''t end on the barren Nebraska plains. It was just beginning. . . Gregg Olsen''s Abandoned Prayers is an incredible true story of murder and Amish secrets.', 'en', 2003, 399, 'http://books.google.com/books/content?id=qWw4mQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
