INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5ea80e17-600c-5eb7-9087-d7d18970e794', '9780312989385', 'The Janson Directive', '3ZjXmeLJHLgC', 'His quiet life away from U.S. Consular Operations disrupted by the terrorist kidnapping of billionaire Peter Novak, Paul Janson assembles a rescue team of former colleagues only to find himself targeted by his foes. Reprint.', 'en', 2003, 693, 'http://books.google.com/books/content?id=3ZjXmeLJHLgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
