INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d1aef4a6-4093-5234-a94d-0f502ee41eaf', '9780312990695', 'The Ambler Warning', '-dA1x-y9eu0C', 'Imprisoned and drugged in a restricted island psychiatric facility for government intelligence employees, former Consular Operations agent Hal Ambler manages a daring escape and sets out to discover why he was placed there, a situation that is complicated when he realizes that his facial features and all records about him have been altered. Reprint.', 'en', 2006, 632, 'http://books.google.com/books/content?id=-dA1x-y9eu0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
