INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5180a0fe-94ba-5e28-a6e5-570473a07f27', '9780312990718', 'Robert Ludlum''s The Moscow Vector', 'YIvFngEACAAJ', 'At an international conference in Prague, Lt. Col. Jon Smith, an Army research doctor specializing in infectious diseases and secretly an agent attached to Covert-One, is contacted by a Russian colleague, Dr. Valentine Petrenko. Petrenko is concerned about a small cluster of mysterious deaths in Moscow and about the Russian government''s refusal to release publicly any information or data on the outbreak. When the two meet, they are attacked by a group of mysterious men and Petrenko is killed, his notes and medical samples are lost, and Smith barely escapes with his life. At the same time, a series of government officials around the world are coming down with a mysterious, fast-acting virus with a 100% fatality rate. These deaths are somehow related to the increasing militarism from the new Russian government, headed by the autocratic and ambitious President Victor Dudarev. With few clues and precious little time, Smith and Covert-One must unravel this mysterious plot and find the mysterious figure who stands at the center of it all...', 'en', 2006, 464, 'http://books.google.com/books/content?id=YIvFngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1631', 'accepted', 'Robert Ludlum; Patrick Larkin', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 14 FROM public.book WHERE isbn13 = '9780312990718' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a51bfcfd-c09a-5702-bd13-e10cbfe7ef22', '9780312994815', 'The Firefly', 'dTHrmAEACAAJ', 'According to the DC cops, the fiery destruction of an upscale plastic surgery clinic and its staff is just business as usual. With the whole city on high alert because of the upcoming presidential inauguration, the Secret Service can afford to let it go. Retired agent Swamp Morgan pulls what appears to be a "firefly" case-until he digs deeper. Facts don''t add up. A German man, the clinic''s last client, has vanished. The only surviving nurse is almost killed. And a mysterious tape indicating an imminent threat against the government puts Morgan on full alert, but his handlers refuse to listen to his warnings. Morgan''s in a race against time as the deadly pieces fall into place. Fighting the odds, he''s got to shut down the brilliant plan to assassinate the incoming and outgoing presidents before America falls into total chaos-or die trying!', 'en', 2004, 528, 'http://books.google.com/books/content?id=dTHrmAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1632', 'accepted', 'P. T. Deutermann', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 6 FROM public.book WHERE isbn13 = '9780312994815' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d513def9-23de-52f0-9ae0-8f2d8f8409c7', '9780312997113', 'As the Crow Flies', 'IeunykAgyGoC', 'Charlie Trumper inherits his grandfather''s vegetable barrow and his spirited ambition, which drives him to struggle through two World Wars without losing sight of his dream--building London''s largest department store--but a dangerous enemy could destroy everything he has accomplished. Reprint.', 'en', 2004, 800, 'http://books.google.com/books/content?id=IeunykAgyGoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1633', 'accepted', 'Jeffrey Archer', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 8 FROM public.book WHERE isbn13 = '9780312997113' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bdc7adab-b970-5fa1-a940-f5641cd4e694', '9780312997830', 'Dakota', 'N2T1mAEACAAJ', 'HE CAME WEST HAUNTED BY DEATH AND GRIEF... In 1884, a Harvard-educated legislator from New York set off for Dakota Territory. Staggered by the deaths of his mother and wife on the same tragic night, Teddy Roosevelt was returning to a place he had visited the year before, a place that had struck him with its fierce beauty and its bounty of big game and big opportunity. By the Little Missouri River, Teddy Roosevelt established a ranching empire, and soon stood at the center of a storm... AND IN A VIOLENT LAND, HE WAS REBORN... Less than a decade after an Indian rebellion and the Battle of the Little Big Horn, Dakota was being settled by the brave, the ambitious, and the restless. While some men were grabbing power, some were getting away with murder. For Roosevelt, using local cowboys and transplanted Easterners as his ranch hands, this was a place to make his mark, to make a stand and to look a killer in the eye. And this was a time to bring wild Dakota into the heart of America...', 'en', 2005, 306, 'http://books.google.com/books/content?id=N2T1mAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1634', 'accepted', 'Matt Braun', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 8 FROM public.book WHERE isbn13 = '9780312997830' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('057243f8-06e0-5b8e-a774-57118ff7dd45', '9780313309335', 'The Fantastic Vampire', 'mpmrWCQ1e3MC', 'Wherever vampires existed in the imaginations of different peoples, they adapted themselves to the customs of the local culture. In The Vampyre (1819), John Polidori introduced Lord Ruthven and established the vampire craze of the 19th century that resulted in a flood of German vampire poetry, French vampire drama, and British vampire fiction. That tradition culminated in Bram Stoker''s Dracula (1897), which fixed the character of the Transylvanian nobleman firmly in the public imagination. The contributors to this volume examine representations of the vampire in fiction, film, folklore, and popular culture. While some look at Stoker and the early literary vampire, others study the works of contemporary writers, such as Anne Rice and Chelsea Quinn Yarbro, vampirism as a metaphor for AIDS, and racial issues in such films as Blacula and Vampire in Brooklyn.', 'en', 2002, 176, 'http://books.google.com/books/content?id=mpmrWCQ1e3MC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
