INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6290d124-8df4-5e60-9b8f-f68319886a15', '9780313324529', 'From Hinton to Hamlet', 'Wg77SNlqP6MC', 'Text presents thematic groupings of titles built around current young adult literature for use in bridging to the classics.', 'en', 2005, 256, 'http://books.google.com/books/content?id=Wg77SNlqP6MC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
