INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('40403886-d0f0-55c4-a86f-01584e24e005', '9780316000611', 'SantaKid', '2d9FvgAACAAJ', 'When Warrie Ransom, the Big Boss of the Exmas Express Company, decides to buy Christmas and rename it Exmas, Santa Claus, Momma Claus, and their daugher Chrissie can''t believe their eyes. Everything at the North Pole seems to change overnight--the elves stop making kids'' favorite toys, the Christmas doves won''t fly or sing, and no one seems to laugh anymore. It looks like Christmas is going to be ruined. But then Chrissie remembers something she had learned from her dad: you must believe in something bigger than yourself. With a little help from her dad''s helpers, Chrissie--as santaKid--delivers presents to children on Christmas eve, sending Warrie Ransom back to where he came from! After all, when you believe in something, magic can happen.', 'en', 2004, 48, 'http://books.google.com/books/content?id=2d9FvgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
