INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3cd96d47-ac14-5989-bd1f-9de41c76c8f8', '9780316000956', 'Trials of Death', '99CCPgAACAAJ', 'Darren begins the Trials of Initiation to prove himself worthy of being a half-vampire, even as the clan''s blood foes, the vampaneze, gather near Vampire Mountain.', 'en', 2005, 202, 'http://books.google.com/books/content?id=99CCPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1638', 'accepted', 'Darren Shan', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 13 FROM public.book WHERE isbn13 = '9780316000956' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dabaf53f-49d4-5abf-86ca-291d8d332ee8', '9780316010764', 'Oblivion', 'yE6lPwAACAAJ', 'In the stories that make up Oblivion, David Foster Wallace joins the rawest, most naked humanity with the infinite involutions of self-consciousness--a combination that is dazzlingly, uniquely his. These are worlds undreamt-of by any other mind. Only David Foster Wallace could convey a father''s desperate loneliness by way of his son''s daydreaming through a teacher''s homicidal breakdown ("The Soul Is Not a Smithy"). Or could explore the deepest and most hilarious aspects of creativity by delineating the office politics surrounding a magazine profile of an artist who produces miniature sculptures in an anatomically inconceivable way ("The Suffering Channel"). Or capture the ache of love''s breakdown in the painfully polite apologies of a man who believes his wife is hallucinating the sound of his snoring ("Oblivion"). Each of these stories is a complete world, as fully imagined as most entire novels, at once preposterously surreal and painfully immediate.', 'en', 2005, 329, 'http://books.google.com/books/content?id=yE6lPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
