INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3389510e-c842-504d-bff8-d522effe31b8', '9780316013260', 'Julie and Julia', 'KdoZHAAACAAJ', 'Now in paperback-the format in which it''s destined to become a reading group favorite-the most heralded and hilarious memoir of recent years: Nearing 30 and trapped in a dead-end secretarial job, Julie Powell reclaims her life by cooking every single recipe in Julia Child''s legendary Mastering the Art of French Cooking in the span of one year. It''s a hysterical, inconceivable redemptive journey - life rediscovered through aspics, calves'' brains and crème brûlée. The bestselling memoir that''s "irresistible....A kind of Bridget Jones meets The French Chef" (Philadelphia Inquirer) is now a major motion picture directed by Nora Ephron, starring Amy Adams as Julie and Meryl Streep as Julia, the film Julie & Julia will be released by Sony Pictures on August 7, 2009.', 'en', 2006, 307, 'http://books.google.com/books/content?id=KdoZHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1640', 'accepted', 'Julie Powell', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 20 FROM public.book WHERE isbn13 = '9780316013260' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0fb7a8d0-f928-5945-a937-33fefa680f1a', '9780316013307', 'The Truth of the Matter', 'qeb3GwAACAAJ', 'Agnes Scofield, the heroine of Dew''s lovely,low-key period piece, can join Mrs. Ramsay and Mrs. Bridge at the teatable of exquisitely etched literary matrons. A respectable Ohiowidow with three grown children, Agnes is beginning to carve out anindependent middle-aged life for herself (which includes a secretlover) when, in 1947, her children all suddenly return to town. Theyhave full lives of their own, but take for granted that Mother willalways put supper on the table and never step outside her role as self-sacrificing, sexless matriarch. Dew''s achievement is to captureboth Agnes'' ambivalence about these demands and the dignity inher struggle to meet them."-Entertainment Weekly (Editor''s Choice)', 'en', 2006, 352, 'http://books.google.com/books/content?id=qeb3GwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1641', 'accepted', 'Robb Forman Dew', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 4 FROM public.book WHERE isbn13 = '9780316013307' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3420f149-514b-58f6-8c9d-8b0fa94458c8', '9780316013314', 'The Beatles', 'ahrfGwAACAAJ', 'As soon as The Beatles became famous, the spin machine began to construct a myth--one that has continued to this day. But the truth is much more interesting, much more exciting, and much more moving. In this bestselling book, Bob Spitz has written the biography for which Beatles fans have long waited. 32 pages of b/w photos.', 'en', 2006, 983, 'http://books.google.com/books/content?id=ahrfGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1642', 'accepted', 'Bob Spitz', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 14 FROM public.book WHERE isbn13 = '9780316013314' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('11a4e6e7-a074-5210-8403-a2939bbf0a95', '9780316017442', 'The Terror', '2FLxMwEACAAJ', 'The men on board HMS Terror have every expectation of triumph. As part of the 1845 Franklin Expedition, the first steam-powered vessels ever to search for the legendary Northwest Passage, they are as scientifically supported an enterprise as has ever set forth. As they enter a second summer in the Arctic Circle without a thaw, though, they are stranded in a nightmarish landscape of encroaching ice and darkness. Endlessly cold, with diminishing rations, 126 men fight to survive with poisonous food, a dwindling supply of coal, and ships buckling in the grip of crushing ice. But their real enemy is far more terrifying. There is something out there in the frigid darkness: an unseen predator stalking their ship, a monstrous terror constantly clawing to get in.When the expedition''s leader, Sir John Franklin, meets a terrible death, Captain Francis Crozier takes command and leads his surviving crewmen on a last, desperate attempt to flee south across the ice. With them travels an Inuit woman who cannot speak and who may be the key to survival, or the harbinger of their deaths. But as another winter approaches, as scurvy and starvation grow more terrible, and as the terror on the ice stalks them southward, Crozier and his men begin to fear that there is no escape. The Terror swells with the heart-stopping suspense and heroic adventure that have won Dan Simmons praise as "a writer who not only makes big promises but keeps them" (Seattle Post-Intelligencer). With a haunting and constantly surprising story based on actual historical events, The Terror is a novel that will chill you to your core.', 'en', 2007, 769, 'http://books.google.com/books/content?id=2FLxMwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1645', 'accepted', 'Dan Simmons', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 14 FROM public.book WHERE isbn13 = '9780316017442' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ed1a8d94-b517-56cf-a357-fd2177d95310', '9780316066143', 'Hollywood Station', 'W6kjuQEACAAJ', 'Under the leadership of their sergeant, known as "The Oracle," the crew of the LAPD''s Hollywood Station take on their toughest case yet as they deal with the Russian mob, diamonds, counterfeiting, and grenades.', 'en', 2006, 340, 'http://books.google.com/books/content?id=W6kjuQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
