INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d0c357b3-f24a-5085-8869-ec524cfaf317', '9780316154970', 'The Harry Bosch Novels', 'w2cscAAACAAJ', 'For the first time in one volume, the three novels that introduced Michael Connelly''s great LAPD homicide detective, maverick Hieronymous (Harry) Bosch. The Black Echo (Winner of the Edgar Award for Best First Novel) For Harry Bosch-hero, loner, nighthawk-the body stuffed in a drainpipe off Mulholland Drive isn''t just another statistic. This one is personal. Billy Meadows was a fellow Vietnam "tunnel rat," fighting the VC and the fear they used to call the Black Echo. Harry let Meadows down once. He won''t do it again. The Black Ice The corpse in the hotel room seems to be that of a missing LAPD narcotics officer. Rumors abound that the cop had crossed over-selling a new drug called Black Ice. Now Harry''s making some dangerous connections, leading from the cop to a string of bloody murders, and from Hollywood Boulevard''s drug bazaar to Mexico''s dusty back alleys. In this lethal game, Harry is likely to be the next victim. The Concrete Blonde When Harry Bosch shot and killed Norman Church, the police were convinced it marked the end of the hunt for the Dollmaker-L.A.''s most bizarre serial killer. But now Church''s widow is accusing Harry of killing the wrong man-a charge that rings terrifyingly true when a new victim is discovered with the Dollmaker''s macabre signature. For the second time, Harry must hunt the murderer down, before he strikes again. Together, these three novels are the perfect way to discover, or rediscover, the sleuth the New York Times Book Review called a "wonderful, old-fashioned hero who isn''t afraid to walk through the flames."', 'en', 2001, 794, 'http://books.google.com/books/content?id=w2cscAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1647', 'accepted', 'Michael Connelly', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 17 FROM public.book WHERE isbn13 = '9780316154970' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b20426ad-a658-56bc-aac8-e5ca9941a924', '9780316156110', 'Consider the Lobster', 'h1xpAQAACAAJ', 'Do lobsters feel pain? Did Franz Kafka have a funny bone? What is John Updike''s deal, anyway? And what happens when adult video starlets meet their fans in person? David Foster Wallace answers these questions and more in essays that are also enthralling narrative adventures. Whether covering the three-ring circus of a vicious presidential race, plunging into the wars between dictionary writers, or confronting the World''s Largest Lobster Cooker at the annual Maine Lobster Festival, Wallace projects a quality of thought that is uniquely his and a voice as powerful and distinct as any in American letters.', 'en', 2005, 343, 'http://books.google.com/books/content?id=h1xpAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
