INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('42a502a3-e1a5-5345-b665-88ba8b199f6d', '9780316159418', 'The Bookseller of Kabul', 'Cf8UfBNXdQ0C', 'The Norwegian journalist provides a portrait of a committed Muslim man and his family living in post-Taliban Kabul, Afghanistan.', 'en', 2004, 288, 'http://books.google.com/books/content?id=Cf8UfBNXdQ0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
