INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('02483441-ab93-5152-b5f8-f7c5f6b664f0', '9780316159722', 'Yiddish with Dick and Jane', 'FSnjlgEACAAJ', 'Jane is in real estate. Today is Saturday. Jane has an open house. She must schlep the Open House signs to the car. See Jane schlep. Schlep, Jane. Schlep. Schlep, schlep, schlep. In text that captures the unque rhythms of the original Dick and Jane readers, and in 35 all-new illustrations, a story unfolds in which Dick and Jane--hero and heroine of the classic books for children that generations of Americans have used when learning to read--manage to express shades of feeling and nuances of meaning that ordinary English just can''t deliver. How? By speaking Yiddish, employing terms that convey an attitude--part plucky self-assertion, part ironic fatalism. When Dick schmoozes, when Jane kvetches, when their children fress noodles at a Chinese restaurant, the clash of cultures produces genuine hilarity.', 'en', 2004, 112, 'http://books.google.com/books/content?id=FSnjlgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
