INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d0e84b6d-8a16-5fa8-92de-b0c84d766077', '9780316168816', 'The Lovely Bones', 'o-QfngEACAAJ', 'The spirit of fourteen-year-old Susie Salmon describes her murder, her surprise at her new home in heaven, and her witness to her family''s grief, efforts to find the killer, and attempts to come to terms with what has happened. A first novel. Reader''s Guide included. Reprint. 750,000 first printing.', 'en', 2004, 328, 'http://books.google.com/books/content?id=o-QfngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
