INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1226c02e-2ae1-561b-851a-975cd67e3e78', '9780316182744', 'Paint it Black', 'DD8elwEACAAJ', 'From the bestselling author of "White Oleander" comes a powerful story of passion, first love, and a young woman''s search for a true world in the aftermath of loss.', 'en', 2006, 387, 'http://books.google.com/books/content?id=DD8elwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
