INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('afbe1771-612a-55dd-9533-0d686cc35a25', '9780316296199', 'The Magus', 'W6G5bwAACAAJ', 'The Magus is the story of Nicholas Urfe, a young Englishman who accepts a teaching assignment on a remote Greek island. There his friendship with a local millionaire evolves into a deadly game, one in which reality and fantasy are deliberately manipulated, and Nicholas must fight for his sanity and his very survival.', 'en', 2001, 656, 'http://books.google.com/books/content?id=W6G5bwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
