INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3524dbba-40ed-5c3c-a674-4d020e83b28c', '9780316706001', 'The Ice Storm', '8I-oYgEACAAJ', 'The year is 1973. As a freak winter storm bears down on an exclusive, affluent suburb in Connecticut, cark skid out of control, men and women swap partners, and their children experiment with sex, drugs, and even suicide. Here two families, the Hoods and the Williamses, com face-to-face with the seething emotions behind the well-clipped lawns of their lives-in a novel widely hailed as a funny, acerbic, and moving hymn to a dazed and confused era of American life.', 'en', 2002, 288, 'http://books.google.com/books/content?id=8I-oYgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
