INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0e6062e8-7c7a-5ee2-adf2-edce67a00ea3', '9780316735162', 'Gossip Girl #6: You''re the One That I Want', 'zmg8yAEACAAJ', 'Welcome to New York City''s Upper East Side, where my friends and I live in gorgeous apartments, go to exclusive private schools, and make Manhattan our own personal playground. It might look hard to be this fabulous, but for us it''s as easy as sleeping with your best friend''s boyfriend. 6th installment of the Gossip Girls series!', 'en', 2004, 224, 'http://books.google.com/books/content?id=zmg8yAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
