INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3eeb8703-ad49-55d0-b541-7efcafeecf3b', '9780316831307', 'Strangers from a Different Shore', 'HcSSQgAACAAJ', 'In an extraordinary blend of narrative history, personal recollection, & oral testimony, the author presents a sweeping history of Asian Americans. He writes of the Chinese who laid tracks for the transcontinental railroad, of plantation laborers in the canefields of Hawaii, of "picture brides" marrying strangers in the hope of becoming part of the American dream. He tells stories of Japanese Americans behind the barbed wire of U.S. internment camps during World War II, Hmong refugees tragically unable to adjust to Wisconsin''s alien climate & culture, & Asian American students stigmatized by the stereotype of the "model minority." This is a powerful & moving work that will resonate for all Americans, who together make up a nation of immigrants from other shores.', 'en', 1998, 640, 'http://books.google.com/books/content?id=HcSSQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
