INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('38ee03a3-5b77-52d4-ad19-c7f8d316b1be', '9780316907927', 'An Unfinished Life', 'EhUpxwEACAAJ', 'The #1 bestseller that forever changed how we thought about JFK, published with a new epilogue in time for the 50th anniversary of Kennedy''s assassination. When it was originally published in 2003, AN UNFINISHED LIFE brought to light new revelations about JFK''s health, his love affairs, his brothers and father, and the path JFK would have taken in the Vietnam entanglement if he had survived. A blockbuster bestseller, the book was embraced by critics and readers as a landmark assessment of our 35th president. Now, in time for what promises to be remarkable media attention on Kennedy''s death and legacy, AN UNFINISHED LIFE returns with a new, strikingly incisive examination by Robert Dallek in which he further assesses JFK''s impact and hold on American culture.', 'en', 2004, 849, 'http://books.google.com/books/content?id=EhUpxwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
