INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9079cf23-38ac-597b-829e-f2d7c703b465', '9780316910330', 'Gossip Girl #1', 'g7qWxgEACAAJ', 'The wickedly funny first book in the #1 New York Times bestselling series that inspired the original hit CW show and the new series coming to HBO Max''s Spring 2020 launch season (alongside hit series such as Pretty Little Liars and Friends). Welcome to New York City''s Upper East Side, where my friends and I live, go to school, play, and sleep--sometimes with each other. S is back from boarding school, and if we aren''t careful, she''s going to win over our teachers, wear that dress we couldn''t fit into, steal our boyfriends'' hearts, and basically ruin our lives in a major way. I''ll be watching closely... You know you love me. gossip girl', 'en', 2002, 224, 'http://books.google.com/books/content?id=g7qWxgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
