INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0bf592c3-6680-509b-b20e-8a682e32f20a', '9780316926607', 'The Complete Stories of Evelyn Waugh', 'HeLt9TIQx5UC', 'A "lavishly entertaining" (Publishers Weekly) distillation of Waugh''s genius--abundant evidence that one of the twentieth century''s most admired and enjoyed English novelists was also a master of the short form. Evelyn Waugh''s short fiction reveals in miniaturized perfection the elements that made him the greatest satirist of the twentieth century. The stories collected here range from delightfully barbed portraits of the British upper classes to an alternative ending to Waugh''s novel A Handful of Dust; from a "missing chapter" in the life of Charles Ryder, the nostalgic hero of Brideshead Revisited, to a plot-packed morality tale that Waugh composed at a very tender age; from an epistolary lark in the voice of "a young lady of leisure" to a darkly comic tale of scandal in a remote (and imaginary) African outpost.', 'en', 2000, 640, 'http://books.google.com/books/content?id=HeLt9TIQx5UC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1676', 'accepted', 'Evelyn Waugh', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 0 FROM public.book WHERE isbn13 = '9780316926607' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cf5bf7c3-1b9f-59ab-9f98-b08fbfbe1a8e', '9780316955126', 'Don''t Stop the Carnival', 'UKA_PgAACAAJ', 'It''s every parrothead''s dream: to leave behind the rat race of the workaday world and start life all over again amidst the cool breezes, sun-drenched colors, and rum-laced drinks of a tropical paradise. It''s the story of Norman Paperman, a New York City press agent who, facing the onset of middle age, runs away to a Caribbean island to reinvent himself as a hotel keeper. (Hilarity and disaster -- of a sort peculiar to the tropics -- ensue.) It''s the novel in which the Pulitzer Prize-winning author of such acclaimed and bestselling novels as The Caine Mutiny and War and Remembrance draws on his own experience (Wouk and his family lived for seven years on an island in the sun) to tell a story at once brilliantly comic and deeply moving.', 'en', 1992, 416, 'http://books.google.com/books/content?id=UKA_PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
