INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8401d9d7-72e1-5fd8-b5e4-a8e96bb99f78', '9780321209184', 'American Government', '7f_lrQEACAAJ', 'This bestseller in American government has been aggressively revised to provide the most in-depth and current coverage of the 2004 elections, the beginnings of the second George W. Bush administration, and the ongoing wars on terror and in Iraq while also providing expansive new coverage of our system''s Constitutional roots. Written with the belief that students must first understand how American government developed to fully understand the issues facing our nation in the 21st century, O''Connor/Sabato offers the strongest coverage of both history and current events on the market today. The new edition provides deeper coverage of both history and events today by exploring the Constitutional roots of our system and how those roots are relevant and often challenged today. The authors also continue their commitment to currency and student-relevance by providing up-to-the-minute coverage of the new Bush administration, the ongoing war in Iraq, etc.', 'en', 2005, 792, 'http://books.google.com/books/content?id=7f_lrQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1679', 'accepted', 'Karen O''Connor; Larry Sabato', 'Political Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 6 FROM public.book WHERE isbn13 = '9780321209184' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f2ff8e6f-51a1-5315-9e38-d9893448a3de', '9780321276230', 'Essentials of American Government', 'ml8rg8OrRGoC', 'The Essentials edition of the number one book in American government continues to provide the most current and engaging introduction available for the course and contains an entire unit devoted to Texas government and politics. Like the comprehensive edition, this nuts-and-bolts version was written with the belief that knowledge of the development of American government is integral to fully understand our current political system. "Essentials of American Government: Continuity and Change" is a student-friendly text offering a strong historical perspective that highlights the evolution of government and engages students with examples relevant to their lives.', 'en', 2005, 604, 'http://books.google.com/books/content?id=ml8rg8OrRGoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
