INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c420b610-93ae-5e24-a6ef-9123b73238a3', '9780321399533', 'Mary Wollstonecraft Shelley''s Frankenstein, or, The modern Prometheus', '9DcrAQAAIAAJ', 'From the Longman Cultural Editions series, this second edition of Frankenstein presents Mary Shelley''s remarkable novel in several provocative and illuminating contexts: cultural, critical, and literary. Series Editor Susan J. Wolfson presents the 1818 version of Mary Shelley''s famous novel in its cultural and historical contexts. Like all great works of fiction, Frankenstein gains depth and dimension from its "conversation" with contemporary texts, especially those by Shelley''s own parents, husband, and friends. A lively introduction is complemented by a chronology coordinating Shelley''s life with key historical events and a speculative calendar of the novel''s events in the late eighteenth century. In addition to the 1818 text, this cultural edition features the introduction to and a sample revision of the 1831 version. New to this Edition is Frankentalk, a section of selected references to Frankenstein in the popular press, and the complete text of Richard Brinsley Peake’s Frankenstein, A Romantic Drama, the first stage version of Frankenstein.', 'en', 2007, 431, 'http://books.google.com/books/content?id=9DcrAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1683', 'accepted', 'Mary Wollstonecraft Shelley; Susan J. Wolfson', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 10 FROM public.book WHERE isbn13 = '9780321399533' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bc89077e-f815-5596-a0b6-9bca9c0b148b', '9780321427137', 'Oscar Wilde''s The Picture of Dorian Gray', 'dhxDPwAACAAJ', 'From Longman''s new Cultural Editions Series, Oscar Wilde''s The Picture of Dorian Gray, edited by Andrew Elfenbein, includes the novel and contextual materials from the era of Oscar Wilde. This edition of Oscar Wilde''s classic work, The Picture of Dorian Gray, highlights the novel''s modernity in both its form and its revolutionary content, and traces its links to modernist literature and the culture of modernity alike. Previous editions of the novel have only seen it in a late Victorian context, or as an extension of the aesthetic theories of Walter Pater and the "art for art''s sake" movement. As presented in this new edition, however, the freshness and originality of the book emerges, along with its strong social messages. The book is a pastiche of genres that propels nineteenth-century realism into twentieth-century modernism ahead of its own time. Wilde''s novel offers a myth for modernity whose hold on the cultural imagination has only strengthened over time-Dorian Gray''s uncanny bond with his own portrait underscores the loss of selfhood everyone experiences in a world of images and copies, paves the way for the discourses of homosexuality and the understanding of lifestyle as identity so current today, and provides clues to the mysteries of modern ethics and politics. The edition also emphasizes the role of gender and the rise of female emancipation underlying the Sybil Vane subplot, a focus on women that intensifies the book''s relevance to modern transformations of men and women alike.', 'en', 2007, 352, 'http://books.google.com/books/content?id=dhxDPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
