INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('19f1482d-bc55-5293-ba6d-f933a65a2ac8', '9780330304214', 'A Gift of Wings', 'jxNwPwAACAAJ', 'These stories, inspired by Bach''s lifelong passion for flight, filled with memories of friends from the past and friends not yet met, are woven together with warmth, honesty and courage. With signs and signals, coincidences and tangents turning up at every juncture, Bach shows how truly complex and beautiful life can be, and also how its troubles can in fact knock us onto better paths or teach us lessons we benefit from in other situations. Drawing on the allegorical power of flight, each a mini-parable, these stories will inspire you with their simple experiences made technicolour by the prism of Bach''s extraordinary imagination. Celebrating Richard Bach''s unique vision, these transcend their pages to touch the real drama of life with magic that reaches out to us all across its limitless horizons.', 'en', 1989, 299, 'http://books.google.com/books/content?id=jxNwPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
