INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('40d4337a-491b-516c-a837-0e7d0913bb34', '9780330314916', 'The Orchard Keeper', 'UYsaQwAACAAJ', 'Set in a small, remote community in rural Tennessee, this book tells of John Wesley Rattner, a young boy, and Marion Sylder, an outlaw and bootlegger who, unbeknownst of either of them, has killed the boy''s father. Together with Rattner''s Uncle Ather, the three enact a drama.', 'en', 1994, 256, 'http://books.google.com/books/content?id=UYsaQwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
