INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b6228607-d62b-5f18-a16b-592ec0ca860c', '9780330316255', 'The Real Frank Zappa Book', 'nXF4PgAACAAJ', 'The legendary Frank Zappa, one of the most influential, innovative and controversial musical artists for the past 20 years, takes us on a wild, funny trip through his life and times. Along the way, Zappa offers his inimitable views on many things such as art, politics and beer.', 'en', 1990, 352, 'http://books.google.com/books/content?id=nXF4PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
