INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c0c72320-1d1e-5c20-877a-922b0ffad1bc', '9780330334617', 'The Border Trilogy', 'QeGjwgEACAAJ', 'Cormac McCarthy’s award-winning, bestselling trio of novels chronicles the coming-of-age of two young men in the south west of America. John Grady Cole and Billy Parham, two cowboys of the old school, are poised on the edge of a world about to change forever. Their journeys across the border into Mexico, each an adventure fraught with fear and pain, mark a passage into adulthood, and eventual salvation. In All the Pretty Horses, young John Grady Cole, dispossessed by the sale of his family’s Texas ranch, heads across the border in search of the cowboy life, where he finds a job breaking horses, and a dangerously ill-fated romance. In The Crossing, sixteen-year-old Billy Parham captures a wolf that has been marauding his family’s ranch and, instead of killing it, decides to take it on a perilous journey home to the mountains of Mexico.These two drifters come together years later in Cities of the Plain, a magnificent tale of friendship and passion. In the vanishing world of the Old West, blood and violence are conditions of life. Beautiful and brutal, filled with sorrow and humour, The Border Trilogy is both an epic love story and a fierce elegy for the American frontier.', 'en', 2002, 1038, 'http://books.google.com/books/content?id=QeGjwgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1698', 'accepted', 'Cormac McCarthy', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 20 FROM public.book WHERE isbn13 = '9780330334617' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c9b8c9f1-79d1-517c-bce8-a5491620d58a', '9780330334686', 'Misreadings', 'Q91IPgAACAAJ', 'In an upside-down Lolita, Umberto Umberto pursues a granny with ‘whitely lascivious locks’. Professor Anouk Ooma of Prince Joseph’s Land University addresses his colleagues on recent archaeological findings that shed light on the poetry of Italy before the Explosion. Columbus’s landing in the New World is covered by television reporters, commentators and guest experts. We are permitted to see in-house publisher’s readers’ reports, most of them unfavourable, on such submissions as The Odyssey, Don Quixote, Kant’s Critique of Pure Reason, and the Five Books of Moses; and we hear a diatribe, in ancient Greece, against the vulgarity of such upstarts as Herodotus, Thucydides and Plato. ‘For sheer exuberant good humour, nothing could surpass Misreadings, a collection of parodies and squibs that began appearing in the 1950s and 1960s, but whose panache has not faded one bit’ Marina Warner, Books of the Year, Independent on Sunday ‘Made up of vintage, good-humoured games – parodies of think-pieces, spoof essays and carnival pranks’ Lorna Sage, Books of the Year, Observer', 'en', 1994, 180, 'http://books.google.com/books/content?id=Q91IPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
