INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1c7d6bab-bb8e-5421-8078-436003d7a2db', '9780330338813', 'Vurt', 'pUKvPwAACAAJ', 'Winner of the 1994 Arthur C. Clarke award, Vurt is a dark tale of England a few years from now. Scribble and his fellow stash riders are hooked on Vurt Feathers, the most powerful drug available. It lets them escape but it has its dangers.', 'en', 1994, 352, 'http://books.google.com/books/content?id=pUKvPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
