INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('52cb449d-3e61-5e86-bd3d-9841f6e52217', '9780330345040', 'Paper Money', 'nlTE5iVFm2MC', 'Three seemingly unrelated events occur on a single morning in London. An MP wakes up after spending the night with a beautiful young woman. A tycoon meets a leading Bank of England official for breakfast. And an underworld gang boss briefs his crew. Nothing so far to keep the tabloid editors awake. Until ambitious young reporter Kevin Hart uncovers his first promising link... Because what is at stake is conspiracy: conspiracy to defraud, no matter what the human cost. On one unforgettable day in the world''s financial capital, fortunes will be destroyed and ideals will be shattered by the discovery that the whole truth is too dangerous to print...', 'en', 1996, 286, 'http://books.google.com/books/content?id=nlTE5iVFm2MC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
