INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1ee7b1bb-8857-55da-ae8d-99c236f3c793', '9780330347761', 'The Golden Key', 'cSsNAQAACAAJ', 'In Tira Verte births, marriages, treaties and all official documents are painted, not written. The paintings by certain males of the Grijalva family are also magical. This book tells the story of one such painter-magician''s obsession with power, with life, and with a love he can never claim.', 'en', 1997, 1074, 'http://books.google.com/books/content?id=cSsNAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
