INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('eb42b36e-d6d0-573c-9d7b-ebc4c7406054', '9780330363686', 'Just Disgusting!', 'cUeXrwgToScC', 'In the tradition of Just Tricking!, Just Annoying!, Just Stupid! and Just Crazy!, Andy Griffiths has written nine highly original, humorous new stories about Andy G.Includes a terrible agonising death by flesh-eating zombies, a battle with brussel sprouts (the sprouts win) and the disgusting fact that cockroaches can live for nine days without their heads (they only die because they starve to death).Complemented by imaginative, chaotic and downright disgusting illustrations by Terry Denton.', 'en', 2002, 180, 'http://books.google.com/books/content?id=cUeXrwgToScC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
