INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2d2a9c4a-b4b7-5296-9dc2-d3972ed64b25', '9780330367349', 'Bridget Jones', 'ebPEQgAACAAJ', 'The Wilderness Years are over! But not for long. At the end of Bridget Jones"s Diary, Bridget hiccuped off into the sunset with man-of-her-dreams Mark Darcy. Now, in the Edge of Reason, she discovers what it is like when you have the man of your dreams actually in your flat and he hasn''t done the washing up, not just the whole of this week, but ever.', 'en', 1999, 422, 'http://books.google.com/books/content?id=ebPEQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
