INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('835ca965-0063-52ca-9de3-2180b3416ccb', '9780330371230', 'High Five', 'rNKjOLyFuxYC', 'Stephanie Plum''s uncle has disappeared and Grandma thinks he has been abducted by aliens. Things turn serious when Stephanie finds a photo of dismembered body parts in his desk. Meanwhile, she has to bring in bail-jumping, vertically-challenged Randy Briggs.', 'en', 2000, 336, 'http://books.google.com/books/content?id=rNKjOLyFuxYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
