INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b2f47cb6-13b4-50d0-93ef-f8d163ebdb1c', '9780330373579', 'The Sign of the Cross', 'FLVFBAldATIC', 'An insightful and personal examination of Catholicism in Europe.For four years from 1990, Colm Tóibin made a series of trips through Catholic Europe. The result is this beautifully wrought book. He shows the complications and contradictions of the Catholic Church, and tries to unravel how they in turn influence a country''s sense of nationalism. It is not quite a travelogue, nor is it autobiographical. Rather it is a work that tests both faith and the written word, a work that redefines what we have come to expect from non-fiction.', 'en', 2001, 243, 'http://books.google.com/books/content?id=FLVFBAldATIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
