INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('658578bb-9e36-5219-b2a7-18793bc9cfaf', '9780330398046', 'Just as Long as We''re Together', 'nJDx-6iUX3YC', 'Stephanie and Rachel have been best friends for years, in spite of their differences. Alison is new in town, and immediately becomes an integral part of their group. But is it possible to have two best friends? And how can you call anyone a friend if you can''t tell them your most painful secrets?', 'en', 2006, 202, 'http://books.google.com/books/content?id=nJDx-6iUX3YC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
