INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('62f3cf2b-9a7b-5d09-ae00-7b93327584f8', '9780330419154', 'Downsize This!', '3Ai-PwAACAAJ', 'Michael Moore has established himself as someone who just won''t shut up, go away, or otherwise do what political and corporate fat cats would like him to do. He lifts the veil on the people who set themselves up as role models and exposes their vulnerable underbellies.', 'en', 2002, 278, 'http://books.google.com/books/content?id=3Ai-PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
