INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e0300b7a-d354-5048-97e8-5c5c511ffa38', '9780330419581', 'Marching Powder', 'rfFohfHH1RcC', 'Inspired by the description of Bolivia''s San Pedro Prison in the "Lonely Planet" guidebook, Young decided to spend four months listening to inmate McFadden and learning about one of the strangest places on earth.', 'en', 2004, 371, 'http://books.google.com/books/content?id=rfFohfHH1RcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
