INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7e49e681-1717-5b0b-8bac-e9f483d0a6d3', '9780330419642', 'Absolute Power', '7MPcbr9ZgTcC', '''Accomplished and amazing - one of the hottest reads around'' DAILY MAIL Set in Washington D.C., this fascinating thriller of unparalleled suspense dares to explore an unthinkable abuse of power and criminal conspiracy: a vicious murder involving the US President and a cover-up orchestrared by his zealously loyal Chief of Staff and the Secret Service. But, unknown to the President and his lackeys, one unlikely witness saw everything.Trapped behind a two-way mirror in a country house in Maryland, Luther Whitney, a professional burglar, witnesses an event that destroys his faith in justice. By the time he escapes, pursued by two Secret Service agents, a young woman has been sexually assaulted, then shot dead. And a breathtaking cover-up has been set in motion. ''Baldacci''s prose is fluent and amazing . . . this book is sure to make a killing'' THE TIMES ''A high-octane legal thriller. An almost Shakespearian study in the nature of evil - horror in its purest form'' SPECTATOR', 'en', 2003, 550, 'http://books.google.com/books/content?id=7MPcbr9ZgTcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
