INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f4669888-8112-5eb2-b8d7-fcdeb4de68e7', '9780330433136', 'Chasing the Monsoon', '5I7AAme3yfUC', 'In 1987 Frater was able to realize his dream of witnessing firsthand the most dramatic of meteorological events: the Indian monsoon. He followed it from its "burst" on the beaches of Trivandrum, through Delhi, Calcutta and across Bangladesh. The result is an illumination of the towering influence of nature over the lives and culture of India and her people.', 'en', 2005, 273, 'http://books.google.com/books/content?id=5I7AAme3yfUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
