INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('92d741ab-db73-5243-bad3-7c3a5c4c2d43', '9780330444576', 'Indecision', 'waXVYKG0FFEC', 'Dwight is only twenty-eight, but he''s having a midlife crisis. Of course, living a dissolute, dorm like existence in a tiny apartment and working in tech support at Pfizer - are not especially conducive to wisdom. His biggest problem: a chronic inability to make up his mind. Encouraged by one of his roommates, he swallows the first fateful pill.', 'en', 2006, 256, 'http://books.google.com/books/content?id=waXVYKG0FFEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
