INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8c78a338-1aac-5484-8abe-d08df069faf6', '9780330484770', 'American Psycho', 'dneIQgAACAAJ', 'An international bestseller and true modern classic Patrick Bateman is twenty-six and works on Wall Street; he is handsome, sophisticated, charming and intelligent. He is also a psychopath. Taking us to a head-on collision with America''s greatest dream – and its worst nightmare – American Psycho is a bleak, bitter, black comedy about a world we all recognize but do not wish to confront.Celebrating 40 years of outstanding international writing, this is one of the essential Picador novels reissued in a beautiful new series style.', 'en', 2000, 399, 'http://books.google.com/books/content?id=dneIQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1728', 'accepted', 'Bret Easton Ellis', 'American fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 0 FROM public.book WHERE isbn13 = '9780330484770' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2839e6fd-4052-5fd8-b773-29d15a87759d', '9780330487108', 'The Mimic Men', '-mGZ062dBzAC', 'A profound and moving and often humorous novel that evokes a colonial man''s experience in the post-colonial world.A Tolstoyan spirit... The so-called thrid World has produced no more brilliant literary artist'' John Updike, New Yorker Born of Indian heritage, raised in the British-dependent Caribbean island of Isabella, and educated in England, forty-year-old Ralph Singh has spent a lifetime struggling against the torment of cultural displacement. Now in exile from his native country, he has taken up residence at a quaint hotel in a London suburb, where he is writing his memoirs in an attempt to impose order on a chaotic existence. His memories lead him to recognize the cultural paradoxes and tainted fantasies of his colonial childhood and later life: his attempts to fit in at school, his short-lived marriage to an ostenatious white woman. But it is the return of Isabella and his subsequent immersion in the roiling political atmosphere of a newly self-governing nation - every kind of racial fantasy taking wing - that ultimately provide Singh with the necessary insight to discover the crux of his disillusionment. ''Ambitious and successful... Extremely perceptive'' The Times ''The sweep of Naipaul''s imagination, the brilliant fictional frame that expresses it, are in my view eithout equal today'' New York Times Book Review', 'en', 2002, 278, 'http://books.google.com/books/content?id=-mGZ062dBzAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1729', 'accepted', 'V. S. Naipaul', 'British', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 3 FROM public.book WHERE isbn13 = '9780330487108' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ce2887af-816d-5309-9990-d0b74047424c', '9780330487146', 'A Bend in the River', '1zfGyiYEQ8UC', '`Brilliant and terrifying`Observer I had to be the man who was doing well and more than well, the man whose drab shop concealed some bigger operation that made millions. I had to be the man who had planned it all, who had come to the destroyed town at the bend in the river because he had foreseen the rich future. `Salim, the narrator, is a young man from an Indian family of traders long resident on the coast of Centeral Africa. Salim has left the coast to make his way in the interior, there to take on a small trading shop of this and that, sudries, sold to the natives. The place is “a bend in the river”; it is Africa. The time is post-colonial, the time of Independence. The Europeans have withdrawn or been forced to withdraw and the scene is one of chaos, violent change, warring tribes, ignorance, isolation, poverty and a lack of prepartion for the modern world they have entered, or partially assumed as a sort of decoration. It is a story of historical upheaval and social breakdown. Naipaul has fashioned a work of intense imaginative force. It is a haunting creation, rich with incident and human bafflement, played out in an immense detail of landscape rendered with a poignant brilliance.`Elizabeth Hardwick `Always a master of fictional landscape, Naipaul here shows, in his variety of human examples and in his search for underlying social causes, a Tolstoyan spirit`John Updike', 'en', 2002, 326, 'http://books.google.com/books/content?id=1zfGyiYEQ8UC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
