INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8322e1b2-a8ee-5420-8c35-c822082f1345', '9780330487153', 'The Enigma of Arrival', 'p_nohX19FFIC', 'Perhaps Naipaul''s most autobiographical work, this is the story of a writer''s singular journey from the British colony of Trinidad to the ancient countryside of England.', 'en', 2002, 387, 'http://books.google.com/books/content?id=p_nohX19FFIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
