INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f24610e5-4624-5236-a014-b0e77e74c9a1', '9780330491198', 'The Hitchhiker''s Guide to the Galaxy', 'S062QgAACAAJ', 'Adams''s beloved and enduring sci-fi/comedy classic is now available in this beautiful, clothbound, elegantly presented book, filled with never-before-published material, original scripts from the BBC radio series, and much more to please any fan.', 'en', 2002, 180, 'http://books.google.com/books/content?id=S062QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
