INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('47503ba9-96c6-5784-b951-a95453f20258', '9780333666388', 'City on the Seine', 'atCRPwAACAAJ', 'Andrew Trout''s new book on Paris during the period preceding the end Louis XIV''s reign is a fascinating social history of the city anchored by the lives of two of its most famous citizens: Cardinal Richelieu and Louis XIV. Beginning with the emergence of Richelieu as a political force and concluding with the end of Louis XIV''s reign, Trout describes the city as it looked during the seventeenth century and answers a myriad of interesting questions: Did the houses have numbers? Were residential buildings flush with the street? What was anyone likely to see along the River Seine? By answering such questions, Trout constructs a social history of the city that is unequalled. Trout''s book is illustrated with maps and engravings that bring the city to life. City on the Seine is an indispensable work of social history.', 'en', 1996, 288, 'http://books.google.com/books/content?id=atCRPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
