INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('05a6a229-e839-5f36-b78e-c9ac4c493231', '9780334028963', 'The Poet, the Warrior, the Prophet', 'VTZBPgAACAAJ', 'Rainer Maria Rilke, Gabriel Garcia Marquez, Emily Dickinson, Albert Camus, Sigmund Freud and the Tao Te Ching are just some of the influences evident in this book which brings poetry to bear on theology. An atmosphere of wonder and vision is created - as when, for example, through the magic of Isak Dinesen''s Babette''s Feast, Alves evokes a picture of `words which are good to be eaten'' - which in turn leads to a meditation on politics, prophecy and the theme of resurrection.', 'en', 2002, 148, 'http://books.google.com/books/content?id=VTZBPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
