INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b340a68f-8cb4-53c3-b47c-f9a27da7bd46', '9780340425671', 'Casino Royale', 'QdjHPwAACAAJ', 'The legend continues Get ready to enjoy more thrills and spills with the world''s greatest secret agent in the latest addition to this classic action series This is the story that introduced us to James Bond. He''s charming, sophisticated and handsome but also chillingly ruthless and very deadly. In his first mission, James must neutralize a Russian operative by ruining him at the Baccarat table and forcing his ''retirement''. Lady luck appears to be taken with Bond as his target hits a losing streak, but Bond''s attraction to a beautiful female agent leads him to disaster... This new edition also features an new introduction by and background material created exclusively for this series on the literary history of Bond.', 'en', 1988, 188, 'http://books.google.com/books/content?id=QdjHPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
