INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cd68e01f-5133-5f85-b7a7-e49965660c67', '9780340637876', 'How the Irish Saved Civilization', 'xV5CPgAACAAJ', 'Ireland played the central role in maintaining European culture when the dark ages settled on Europe in the fifth century: as Rome was sacked by Visigoths and its empire collapsed, Ireland became ''the isle of saints and scholars'' that enabled the classical and religious heritage to be saved. In his compelling and entertaining narrative, Thomas Cahill tells the story of how Irish monks and scrines copied the mauscripts of both pagan and Christian writers, including Homer and Aristotle, while libraries on the continent were lost forever. Bringing the past and its characters to life, Cahill captures the sensibility of the unsung Irish who relaunched civilisation.', 'en', 1995, 256, 'http://books.google.com/books/content?id=xV5CPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
