INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d79a0573-3928-5e37-8956-268e68c1f00c', '9780340689608', 'Flatmates', 'TR1hHAAACAAJ', 'Flatmates Fiona, Kerry and Linzi have problems enough squabbling over the itemised phone bill and whose turn it is to do the washing up. But nothing can prepare them for the chaos which ensues when Linzi''s latest boyfriend arrives on the scene. Gorgeous but feckless, Gaetano spells trouble with a capital ''T''. And soon events are spiralling out of everyone''s control . . .', 'en', 1997, 320, 'http://books.google.com/books/content?id=TR1hHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
