INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9b1d931a-5e22-51f9-a910-a55fcb0a88fa', '9780340766163', 'Shōgun', 'NGpfQgAACAAJ', 'This is James Clavell''s tour-de-force; an epic saga of one Pilot-Major John Blackthorne, and his integration into the struggles and strife of feudal Japan. Both entertaining and incisive, SHOGUN is a stunningly dramatic re-creation of a very different world. Starting with his shipwreck on this most alien of shores, the novel charts Blackthorne''s rise from the status of reviled foreigner up to the heights of trusted advisor and eventually, Samurai. All as civil war looms over the fragile country.', 'en', 1975, 1152, 'http://books.google.com/books/content?id=NGpfQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
