INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('93ac92c7-99eb-5100-887f-0fbd0d05667b', '9780340766187', 'Whirlwind', 'gOfHHAAACAAJ', 'This is the story of three weeks of fanaticism, passion, self-sacrifice and heartbreak in Tehran in February 1979. Caught between the revolutionaries and the forces of international intrigue is a team of professional pilots. Two of them have Iranian wives they love beyond safety and politics.', 'en', 1999, 1231, 'http://books.google.com/books/content?id=gOfHHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
