INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('895854af-15dd-5749-a988-888d0ca5f9d8', '9780340769201', 'Running Away from Richard', '8p8VNgAACAAJ', 'Just graduated from drama school, Lizzie Jordan is looking forward to a glittering career at the RSC. She''s also looking forward to becoming Mrs Richard Adams (Lizzie just knows that her live-in artist boyfriend is about to propose any day now). So how come, just one month later, Lizzie finds herself sharing a cockroach-infested house in Venice Beach, working as a waitress in a notorious transvestite bar, and pretending to be the fiancee of one of the hottest directors in Hollywood; a man who just happens to be gay? Why does life never seem to work out the way Lizzie Jordan planned?', 'en', 2001, 470, 'http://books.google.com/books/content?id=8p8VNgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
