INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a460cdc6-9262-57d5-b2b3-ac65ba902587', '9780340820469', 'On Writing', 'hk-EPwAACAAJ', 'An autobiographical portrait of Stephen King''s home life, his family and his traumatic recent accident. He offers an insight into his world as well as analysis, advice and instruction on writing. Find out what books and films influenced the young writer, his first idea for a story, the true life tale that inspired Carrie. Citing examples of his work and those of his contemporaries such as John Grisham and Raymond Chandler, King gives tips for writers on how to avoid pitfalls and how to use the tools of the trade from building characters to pace and plotting, the importance of dialogue and description - as well as practical advice on presentation and representation. Discover the symbolism, themes and the three deep interests that power all his work.', 'en', 2001, 384, 'http://books.google.com/books/content?id=hk-EPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
