INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7b564ac2-2072-54a3-9551-c46eaacee603', '9780340829776', 'The Waste Lands', 'Yi9CPgAACAAJ', 'There are new evils, new dangers to threaten Roland''s little band in the devastated city of Lud and the surrounding wastelands, as well as horrific confrontations with Blaine the Mono, the piratical Gasher, and the frightening Tick-Tock Man.', 'en', 2003, 584, 'http://books.google.com/books/content?id=Yi9CPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
