INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cb5417f6-e929-5628-b117-4f385b3faf46', '9780340831205', 'The Art of Happiness at Work', 'gQqONAAACAAJ', 'Following the massive success of THE ART OF HAPPINESS, the Dalai Lama & Howard Cutler now bring their bestselling message to our working lives. Of the many Dalai Lama titles on sale, THE ART OF HAPPINESS - written with western psychiatrist Howard Cutler - is by far the biggest bestseller of them all. A huge international success, it has sold over 2 million copies worldwide, with nearly 300,000 of these in the UK alone. Now, this inspirational new book brings the successful East-meets-West pairing together again to provide a practical application of Tibetan Buddhist spiritual values to the world of work. In this wise and practical book, the Dalai Lama shows us how to place our working lives into the context of our lives as a whole. Rather than striving to find a role which suits us, we should allow our work to arise naturally from who we are - and what is most important to us. From here we reach a pathway that can lead us to true life fulfilment and purpose.', 'en', 2003, 224, 'http://books.google.com/books/content?id=gQqONAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
