INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('733c55db-fbbc-5470-8d41-c5c2b5333ed6', '9780340850626', 'Interstellar Pig', 'RgdGPgAACAAJ', 'Barney''s new next-door neighbours are unlike anyone he''s ever met - utterly charming, slightly odd, and completely obsessed with a board game. When they invite Barney to join them in a game of Interstellar Pig, he''s delighted, until things start to get a little strange.', 'en', 2001, 200, 'http://books.google.com/books/content?id=RgdGPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
