INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('197daf85-f01f-5ec8-ae11-e5ea697b1096', '9780345301116', 'Story of O', '3OwAnoLeneMC', 'Before Fifty Shades of Grey there was Story of O, the notorious novel of dark obsession that introduced the world to erotic fiction. How far will a woman go to express her love? In this exquisite and taboo novel of passion and desire, the answer emerges through a daring exploration of the deepest bonds of sensual domination. "O" is a beautiful Parisian fashion photographer, determined to understand and prove her consuming devotion to her lover, René, through complete submission to his every whim, his every desire. It is a journey of forbidden, dangerous choices that sweeps her through the secret gardens of the sexual underground. From the inner sanctum of a private club where willing women are schooled in the art of subjugation to the excruciating embraces of René''s friend Sir Stephen, O tests the outermost limits of pleasure. For as O discovers, true freedom lies in her pure and complete willingness to do anything for love.', 'en', 1973, 199, 'http://books.google.com/books/content?id=3OwAnoLeneMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
