INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0a5037af-1f42-586e-8628-cac476c30b29', '9780345323903', 'With Friends Like These', 'IKUcAAAACAAJ', 'Willie Whitehorse could have been just another boozed-up guitarist, if it hadn''t been for his songs. Somehow they were different -- they reached out and grabbed people''s souls. Now agent Sam Parker wanted a piece of the action. But when he had it, Sam knew he''d made a terrible mistake...a mistake it was much too late to correct... With Friends Like These... The aliens had returned to Earth after centuries because they needed allies. But after hundreds of years, they had no idea what they would be getting the universe into...and they soon found out! Dream Done Green Pericles was a poet and a genius, who also happened to be a horse! Why Johnny Can''t Speed A father could teach his son a lot of important things, but combat on the freeways wasn''t one of them...not when the kid was eighteen and too full of himself to survive. But revenge did have its compensations!', 'en', 1984, 236, 'http://books.google.com/books/content?id=IKUcAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
