INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ea5594fb-42b1-530d-9610-251d9fe4d474', '9780345437976', 'The Courtesan', 'xus7OLB70OMC', 'Determined to ensure her future by winning the heart of Henry, the Huguenot king of Navarre, sixteenth-century courtesan Gabrielle Cheney finds her plans jeopardized by the malevolent enmity and dark arts of the queen, Catherine de Medici, as well as her growing feelings for Captain Nicolas Remy, a devoted warrior. By the author of The Dark Queen. Original. 45,000 first printing.', 'en', 2005, 560, 'http://books.google.com/books/content?id=xus7OLB70OMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
