INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b253adb9-1e27-5962-ba92-2d7ec5190ed2', '9780345439499', 'The Best of Lester Del Rey', '3LZ6PwAACAAJ', 'A collection of classic stories by the cofounder of Del Rey Books -- now in a stunning new Del Rey Impact edition. A must-have for all science fiction readers -- Introduction by Terry BrooksLester del Rey, science fiction''s most protean personality -- writer, editor, critic, publisher -- sets off an incomparable fireworks display in these tales of robots and humans, animals and aliens, ghosts and gods, science and the supernatural: "Instinct"The robots labored to re-create the extinct human species -- but there was one element they somehow left out."For I Am a Jealous People""In God We Trust" is a great motto -- until you find you can''t."Hereafter, Inc".This is Heaven? The Hell it is!', 'en', 2000, 320, 'http://books.google.com/books/content?id=3LZ6PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
