INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7cf78be6-f65e-5a7d-b306-8c7736756934', '9780345478238', 'Narrative of the Life of Frederick Douglass, an American Slave', 'sk_kwAEACAAJ', 'Includes the autobiography of the famous abolitionist and statesman who escaped to the North after twenty-one years of enslavement, as well as an account that reveals the exploitation of African American female slaves through first-person narrative.', 'en', 2004, 464, 'http://books.google.com/books/content?id=sk_kwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
