INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fe964de1-6b20-569d-aa6a-955801aef31f', '9780345478245', 'Already Dead', 'Z5vfamYeVG0C', 'Those stories you hear? The ones about things that only come out at night? Things that feed on blood, feed on us? Got news for you: they’re true. Only it’s not like the movies or old man Stoker’s storybook. It’s worse. Especially if you happen to be one of them. Just ask Joe Pitt. There’s a shambler on the loose. Some fool who got himself infected with a flesh-eating bacteria is lurching around, trying to munch on folks’ brains. Joe hates shamblers, but he’s still the one who has to deal with them. That’s just the kind of life he has. Except afterlife might be better word. From the Battery to the Bronx, and from river to river, Manhattan is crawling with Vampyres. Joe is one of them, and he’s not happy about it. Yeah, he gets to be stronger and faster than you, and he’s tough as nails and hard to kill. But spending his nights trying to score a pint of blood to feed the Vyrus that’s eating at him isn’t his idea of a good time. And Joe doesn’t make it any easier on himself. Going his own way, refusing to ally with the Clans that run the undead underside of Manhattan–it ain’t easy. It’s worse once he gets mixed up with the Coalition–the city’s most powerful Clan–and finds himself searching for a poor little rich girl who’s gone missing in Alphabet City. Now the Coalition and the girl’s high-society parents are breathing down his neck, anarchist Vampyres are pushing him around, and a crazy Vampyre cult is stalking him. No time to complain, though. Got to find that girl and kill that shambler before the whip comes down . . . and before the sun comes up.', 'en', 2005, 268, 'http://books.google.com/books/content?id=Z5vfamYeVG0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1904', 'accepted', 'Charlie Huston', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 17 FROM public.book WHERE isbn13 = '9780345478245' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ffc5fcb6-bf7d-57b4-8988-d2a088cb77f3', '9780345478252', 'No Dominion', 'UNB7vgEACAAJ', 'Joe Pitt’s life sucks. He hasn’t had a case or a job in God knows how long and his stashes are running on empty. What stashes? The only ones that count to a guy like Joe: blood and money. The money he uses to buy blood; the blood he drinks. Hey, buddy, it’s that or your neck–you want to choose? The only way to lay his hands on both is to take a gig with the local Vampyre Clan. See, something new is on the streets, a new high, a high so strong it can send a Vampyre spazzing through Joe’s local watering hole. Till Joe sends him through a plate-glass window, that is. So it’s time for Joe to gut up and swallow that pride and follow the leads wherever they go. It won’t be long before he’s slapping stoolies, getting sapped, and being taken for a ride above 110th Street. Someone’s pulling Joe’s strings, and now he’s riding the A train, looking to find who it is. He’s gonna cut them when he finds them–the strings and the hands that hold them.', 'en', 2006, 251, 'http://books.google.com/books/content?id=UNB7vgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
