INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8c4b6eb1-297c-5fb3-9187-bad44c8a214f', '9780345494023', 'The Plague Dogs', 'H2SPDQAAQBAJ', 'A large black mongrel named Rowf and a white terrier named Snitter escape from an animal experiment center in England''s Lake District and, aided by a cunning fox, learn to live on their own, until rumors of slaughtered sheep and bubonic plague-carrying dogs transform them into fugitives. Reprint. 15,000 first printing.', 'en', 2006, 390, 'http://books.google.com/books/content?id=H2SPDQAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
