INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e4a002cd-d37f-5ff1-8d64-f50217bcb52e', '9780349100135', 'If this is a Man ; and The Truce', '5EunQgAACAAJ', 'With the moral stamina and intellectual pose of a twentieth-century Titan, this slightly built, duitful, unassuming chemist set out systematically to remember the German hell on earth, steadfastly to think it through, and then to render it comprehensible in lucid, unpretentious prose. He was profoundly in touch with the minutest workings of the most endearing human events and with the most contempible. What has survived in Levi''s writing isn''t just his memory of the unbearable, but also, in THE PERIODIC TABLE and THE WRENCH, his delight in what made the world exquisite to him. He was himself a "magically endearing man, the most delicately forceful enchanter I''ve ever known" - PHILIP ROTH', 'en', 1987, 419, 'http://books.google.com/books/content?id=5EunQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1939', 'accepted', 'Primo Levi', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 0 FROM public.book WHERE isbn13 = '9780349100135' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4810776c-3c75-5142-b9e3-de9a568e9597', '9780349100470', 'The Drowned and the Saved', 'U35BPQAACAAJ', 'Shortly after completing THE DROWNED AND THE SAVED, Primo Levi committed suicide. The matter of his death was sudden, violent and unpremiditated, and there were some who argue that he killed himself because he was tormented by guilt - guilt that he had survived the horrors of Auschwitz while others, better than he, had gone to the wall. THE DROWNED AND THE SAVED is Levi''s impassioned attempt to understand the ''rationale'' behind the concentration camps, was completed shortly before his tragic death in 1987. THE DROWNED AND THE SAVED dispels the myth that Primo Levi forgave the Germans for what they did to his people. He didn''t and couldn''t forgive. He refused, however, to indulge in what he called ''the bestial vice of hatred'' which is an entirely different matter. The voice that sounds in his writing is that of a reasonable man...it warns and reminds us that the unimaginable can happen again. A would-be tyrant is waiting in the wings, with ''beautiful words'' on his lips. The book is constantly impressing on us the need to learn from the past, to make sense of the senseless'' PAUL BAILEY', 'en', 1989, 170, 'http://books.google.com/books/content?id=U35BPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1940', 'accepted', 'Primo Levi', 'Auschwitz (Poland : Concentration camp)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 16 FROM public.book WHERE isbn13 = '9780349100470' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2f3e36a7-885d-50f3-b68e-078b1ff58649', '9780349105307', 'Lincoln', '59WHPwAACAAJ', 'In the hazardous fictional terrain of his historical novels, Gore Vidal is never especially kind to American history in general, or to its icons in particular. Yet in this brilliantly realised study of Abraham Lincoln, he paints a surprising and near-heroic picture of the man who led America through four of the most divisive and dangerous years of the nation''s history. Observed alternately by his loved ones, his rivals and his future assassins, Lincoln at first appears as an inept and naïve backwoods lawyer. People in this novel are not averse to turning up, getting drunk, and regaling the reader with details of Lincoln''s whoring activities and his seemingly inexhaustible supply of folksy stories. Yet gradually Lincoln the towering leader of deep vision emerges in a Washington engulfed by fear, greed and the horrors of the Civil War. Lincoln''s loving but mentally decomposing wife, his view from the White House on slavery and America''s bloodiest war, and his own, fierce personal ambition: all are portrayed with a vibrancy and an urgency that almost belies what they have now become ? history itself.', 'en', 1994, 736, 'http://books.google.com/books/content?id=59WHPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1943', 'accepted', 'Gore Vidal', 'Political fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 14 FROM public.book WHERE isbn13 = '9780349105307' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f83b6b26-013c-5eff-8e8b-56f578d63dfe', '9780349107868', 'Hitler''s Willing Executioners', 'L11gQgAACAAJ', 'Daniel Goldhagen re-visits a question which history has treated as settled, and his research leads him to the inescapble conclusion that none of the answers holds true. That question is: How could the Holocaust happen? His response is an exploration of German society and its ingrained anti-semitism that demands a fundamental revision of our thinking about the years 1933-1945. The author marshals fresh, primary evidence - including extensive testimony from the actual perpetrators - to show that the killers were ordinary Germans who were not compelled to act as they did (they knew they could refuse without retribution) yet they killed willingly and zealously.', 'en', 1997, 634, 'http://books.google.com/books/content?id=L11gQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1945', 'accepted', 'Daniel Jonah Goldhagen', 'Antisemitism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 4 FROM public.book WHERE isbn13 = '9780349107868' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('55b11996-3ded-5531-af12-df1875a445cb', '9780349110011', 'A Supposedly Fun Thing I''ll Never Do Again', '4ipaMAEACAAJ', 'A collection of insightful and uproariously funny non-fiction by the bestselling author of INFINITE JEST - one of the most acclaimed and adventurous writers of our time. A SUPPOSEDLY FUN THING... brings together Wallace''s musings on a wide range of topics, from his early days as a nationally ranked tennis player to his trip on a commercial cruiseliner. In each of these essays, Wallace''s observations are as keen as they are funny. Filled with hilarious details and invigorating analyses, these essays brilliantly expose the fault line in American culture - and once again reveal David Foster Wallace''s extraordinary talent and gargantuan intellect.', 'en', 1998, 353, 'http://books.google.com/books/content?id=4ipaMAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1946', 'accepted', 'David Foster Wallace', 'Popular culture', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 18 FROM public.book WHERE isbn13 = '9780349110011' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('74e02170-8a58-547c-b702-5b0a4771cb06', '9780349111889', 'Brief Interviews with Hideous Men', 'UCWwQgAACAAJ', 'In his startling and singular new short story collection, David Foster Wallace nudges at the boundaries of fiction with inimitable wit and seductive intelligence. Among the stories are ''The Depressed Person'', a dazzling and blackly humorous portrayal of a woman''s mental state; ''Adult World'', which reveals a woman''s agonised consideration of her confusing sexual relationship with her husband; and ''Brief Interviews with Hideous Men'', a dark, hilarious series of portraits of men whose fear of women renders them grotesque. Wallace''s stories present a world where the bizarre and the banal are interwoven and where hideous men appear in many different guises. Thought-provoking and playful, this collection confirms David Foster Wallace as one of the most imaginative young writers around. Wallace delights in leftfield observation, mining the ironic, the surprising and the illuminating from every situation. His new collection will delight his growing number of fans, and provide a perfect introduction for new readers.', 'en', 2001, 273, 'http://books.google.com/books/content?id=UCWwQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1947', 'accepted', 'David Foster Wallace', 'Misogyny', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 9 FROM public.book WHERE isbn13 = '9780349111889' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('41b7ff6f-2e3d-587b-b528-890821340d79', '9780349113005', 'Embrace', 'yRpVHQAACAAJ', 'EMBRACE is the story of the awakening of Karl De Man a thirteen-year-old student at the Berg, an exclusive academy for boys in South Africa in the 1970s. Interwoven with the storyline about Karl at school are memories from Karl''s childhood and first years at the Berg, presented as an ever-growing patchwork of the many influences on his development: growing up on a game reserve in East Africa, intensely aware of landscape and wildlife; a loving and close family, but a traditional one that will never easily accept Karl''s true self: being sent away to school and the formation of new friendships and relationships. But, after threats and punishments handed out after casual sexual games in the dorm, Karl falls in love. He simultaneously has secret affairs with his best friend, Dominic, who is the son of liberal parents, and his choirmaster, Jacques Cilliers. The great strength of the novel is that it places Karl''s passions on a wider canvas, focusing on his raw passions and elemental drives against the landscapes of Africa. It is a staggering follow-up to Mark Behr''s award-winning first novel, THE SMELL OF APPLES.', 'en', 2001, 726, 'http://books.google.com/books/content?id=yRpVHQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1948', 'accepted', 'Mark Behr', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 18 FROM public.book WHERE isbn13 = '9780349113005' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e4d77711-8295-534d-adbf-53b06cf16eab', '9780349113463', 'The Tipping Point', 'EMELnwEACAAJ', 'THE TIPPING POINT is the biography of an idea, and the idea is quite simple. It is that many of the problems we face - from crime to teenage delinquency to traffic jams - behave like epidemics. They aren''t linear phenomena in the sense that they steadily and predictably change according to the level of effort brought to bear against them. They are capable of sudden and dramatic changes in direction. Years of well-intentioned intervention may have no impact at all, yet the right intervention - at just the right time - can start a cascade of change. Many of the social ills that face us today, in other words, are as inherently volatile as the epidemics that periodically sweep through the human population: little things can cause them to ''tip'' at any time and if we want to understand how to confront and solve them we have to understand what those ''Tipping Points'' are. In this revolutionary new study, Malcolm Gladwell explores the ramifications of this. Not simply for politicians and policy-makers, his method provides a new way of viewing everyday experience and enables us to develop strategies for everything from raising a child to running a company.', 'en', 2000, 279, 'http://books.google.com/books/content?id=EMELnwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1949', 'accepted', 'Malcolm Gladwell', 'Social Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 2 FROM public.book WHERE isbn13 = '9780349113463' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('500b81fc-8f6f-5696-9814-ef4fdd12a70a', '9780349113487', 'Aldous Huxley', 'ysCQGwAACAAJ', 'The grandson of biologist T. H. Huxley, Aldous Huxley had a privileged background and was educated at Eton and Oxford despite an eye infection that left him nearly blind. Having learned braille his eyesight then improved enough for him to start writing, and by the 1920s he had become a fashionable figure, producing witty and daring novels like CROME YELLOW (1921), ANTIC HAY (1923) and POINT COUNTER POINT (1928). But it is as the author of his celebrated portrayal of a nightmare future society, BRAVE NEW WORLD (1932), that Huxley is remembered today. A truly visionary book, it was a watershed in Huxley''s world-view as his later work became more and more optimistic - coinciding with his move to California and experimentation with mysticism and psychedelic drugs later in life. Nicholas Murray''s brilliant new book has the greatest virtue of literary biographies: it makes you want to go out and read its subject''s work all over again. A fascinating reassessment of one of the most interesting writers of the twentieth century.', 'en', 2003, 496, 'http://books.google.com/books/content?id=ysCQGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1950', 'accepted', 'Nicholas Murray', 'Great Britain', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 13 FROM public.book WHERE isbn13 = '9780349113487' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d228c12e-0a8e-5359-ba2f-bb7203fb5357', '9780349113913', 'Me Talk Pretty One Day', '5zGGPwAACAAJ', 'David Sedaris moved from New York to Paris where he attempted to learn French. His teacher, a sadist, declared that every day spent with him was like giving birth the Caesarean way! These hilarious essays were inspired by that move.', 'en', 2002, 272, 'http://books.google.com/books/content?id=5zGGPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1951', 'accepted', 'David Sedaris', 'Education', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 2 FROM public.book WHERE isbn13 = '9780349113913' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('941374bc-ec1e-546c-bb3a-13c7b6497b02', '9780349116303', 'Long Walk to Freedom', '7MNfQgAACAAJ', 'The riveting memoirs of the outstanding moral and political leader of our time, LONG WALK TO FREEDOM brilliantly recreates the drama of the experiences that helped shape Nelson Mandela''s destiny. From his imprisonment on Robben Island to his remarkable journey to freedom and inauguration as President this book describes Mandela''s frustrations and strength of heart as well as the overwhelming joy of freedom and power. Emotive and compelling, it completes the story of an epic life. ''Burns with the luminosity of faith in the invincible nature of human hope and dignity . . . Unforgettable'' ANDRE BRINK ''Enthralling . . . Mandela emulates the few great political leaders such as Lincoln and Gandhi, who go beyond mere consensus and move out ahead of their followers to break new ground'' Donald Woods in the SUNDAY TIMES', 'en', 2003, 450, 'http://books.google.com/books/content?id=7MNfQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1952', 'accepted', 'Nelson Mandela', 'Apartheid', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 10 FROM public.book WHERE isbn13 = '9780349116303' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1e4816e1-07da-524d-a599-2ebfffb7b498', '9780349116648', 'Dead Air', '56RxQgAACAAJ', 'Iain Banks'' daring new novel opens in a loft apartment in the East End, in a former factory due to be knocked down in a few days. Ken Nott is a devoutly contrarian vaguely left wing radio shock-jock living in London. After a wedding breakfast people start dropping fruits from a balcony on to a deserted carpark ten storeys below, then they start dropping other things; an old TV that doesn''t work, a blown loudspeaker, beanbags, other unwanted furniture...Then they get carried away and start dropping things that are still working, while wrecking the rest of the apartment. But mobile phones start ringing and they''re told to turn on a TV, because a plane has just crashed into the World Trade Centre... At ease with the volatility of modernity, Iain Banks is also our most accomplished literary writer of narrative-driven adventure stories that never ignore the injustices and moral conundrums of the real world. His new novel, displays his trademark dark wit, buoyancy and momentum.', 'en', 2003, 436, 'http://books.google.com/books/content?id=56RxQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '1953', 'accepted', 'Iain Banks', 'London (England)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 6 FROM public.book WHERE isbn13 = '9780349116648' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('acd4e686-3bd5-54fa-9345-187d5f08246b', '9780349117041', 'The Kalahari Typing School for Men', 'nsI7ngEACAAJ', 'Ex-CID. Ex-New York. Ex-cellent'' reads the sign outside the Satisfaction Guarantee Detective Agency. Cephas Buthelezi certainly talks the talk, Precious discovers, but would he have the wherewithal to deal with her current case - a man who has been attacked by ostrich rustlers, and is eager to reassess his life? Meanwhile, there are difficulties at the Tlokweng Road Speedy Motors, where one of the apprentices has discovered the Lord, problems at home with the mysterious death of a hoopoe, and romantic complications when Mma Makutsi sets up a typing school for men . . .', 'en', 2004, 210, 'http://books.google.com/books/content?id=nsI7ngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
