INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ec84efbb-d050-54c0-8242-187affd91d48', '9780373225736', 'The Stranger Next Door', 'pquQudapo_QC', 'A beautiful woman with dangerous secrets was about to become the Randolphs neighbor. She was a vulnerable stranger who d make any red-blooded male take notice ... and Langley Randolph was no exception. Dependable, solid, and timeless, like the family ranch that had been passed down through the generations, Langley couldn t bear to see a desperate woman fighting tears. Danielle needed the strength of the stalwart rancher next door to unlock the mystery of her memories ... before a killer caught up with her first.', 'en', 2000, 256, 'http://books.google.com/books/content?id=pquQudapo_QC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
