INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fce5d876-ba28-5936-adc1-4db3ee25d496', '9780373246472', 'The Sheik & the Princess Bride', 'PFhUUk6KdLwC', 'Prince Jefri of Bahania had just been bested ... by a woman! And not just any female, but Billie Van Horn, his gorgeous, take-no-prisoners flight instructor who was more than a match for this ultramasculine male. Well, she might be an ace in the air, but when it came to romance Billie was determined to keep both feet on the ground. So why did the sexy sheik make her feel as if she were soaring high above the clouds? She knew that when royal honor called, her high-born lover would fly from her side forever ... unless Jefri defied his destiny and chose love ...', 'en', 2004, 256, 'http://books.google.com/books/content?id=PFhUUk6KdLwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
