INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1e9ad478-1a26-55e5-833e-137950291f87', '9780373771721', 'Call After Midnight & Under the Knife', 'bqw__tuIMdMC', 'A ringing phone in the middle of the night shakes newlywed Sarah Fontaine awake. Expecting her husband''s call from London she hears instead an unfamiliar voice. Nick O''Hara from the U.S. State Department is calling with devastating news: Geoffrey Fontaine, Sarah''s husband of two months, died in a hotel fire ... in Berlin. Convinced her husband is still alive, Sarah forces a confrontation with Nick that finds them crisscrossing Europe on a desperate search for Geoffrey. Trying to stay one heartbeat ahead of a dangerous killer, they become quarry in the clandestine world of international espionage, risking everything for answers that may prove fatal.', 'en', 2006, 555, 'http://books.google.com/books/content?id=bqw__tuIMdMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
