INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('237adece-f3ce-5ad1-9b7c-5c74e7e2f197', '9780373772513', 'Manhunting', 'AsbnYjXNAs8C', 'After three failed engagements, Kate Svenson comes up with a definitive plan for finding the man of her dreams by snaring an eligible bachelor at The Cabins resort, but as her would-be swains begin to drop around her, Jake Templeton decides to save the world of men from this femme fatale.', 'en', 1993, 328, 'http://books.google.com/books/content?id=AsbnYjXNAs8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
