INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6edc0301-2731-5032-9654-2615814217a0', '9780373792733', 'The Perfect Score', 'OAxUYS3BruoC', 'Bad Girl Grading System A -- Totally bad!!! B -- Could be worse... C -- Wannabe territory D -- Way too nice! F -- Give it up, Mattie Brown! Mattie Brown has always prided herself at excelling at everything. And that''s why it''s killing her that she scored only 18% on a sex test! But she isn''t going to take it lying down. (Well, maybe she will, but that''s beside the point.) Her plan -- to proposition Cullen Slater, the neighborhood stud, for some hands-on instruction in how to make her sex life sizzle. Too bad it''s her cute, nice-guy neighbor Mike Peterson who''s lighting her fire... .', 'en', 2006, 240, 'http://books.google.com/books/content?id=OAxUYS3BruoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
