INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1cde5b05-66a2-58e7-af81-e10d3b949a0d', '9780374523930', 'Assembling California', 'peRjDOETl_cC', 'At various times in a span of fifteen years, John McPhee made geological field surveys in the company of Eldridge Moores, a tectonicist at the University of California at Davis. The result of these trips is Assembling California, a cross-section in human and geologic time, from Donner Pass in the Sierra Nevada through the golden foothills of the Mother Lode and across the Great Central Valley to the wine country of the Coast Ranges, the rock of San Francisco, and the San Andreas family of faults. The two disparate time scales occasionally intersect--in the gold disruptions of the nineteenth century no less than in the earthquakes of the twentieth--and always with relevance to a newly understood geologic history in which half a dozen large and separate pieces of country are seen to have drifted in from far and near to coalesce as California. McPhee and Moores also journeyed to remote mountains of Arizona and to Cyprus and northern Greece, where rock of the deep-ocean floor has been transported into continental settings, as it has in California. Global in scope and a delight to read, Assembling California is a sweeping narrative of maps in motion, of evolving and dissolving lands.', 'en', 1994, 294, 'http://books.google.com/books/content?id=peRjDOETl_cC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2033', 'accepted', 'John McPhee', 'Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 3 FROM public.book WHERE isbn13 = '9780374523930' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ec79df0a-7d12-581c-ad7b-624b30958b89', '9780374524791', 'Satan in Goray', 'ic-pPwAACAAJ', 'As messianic zeal sweeps through medieval Poland, the Jews of Goray divide between those who, like the Rabbi, insist that no one can "force the end" and those who follow the messianic pretender Sabbatai Zevi. But as hysteria and depravity increase, it becomes clear that it is not the Messiah who has come to Goray.', 'en', 1996, 288, 'http://books.google.com/books/content?id=ic-pPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
