INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('11b878eb-77b6-5356-8659-4d9a250d9154', '9780374524920', 'The Stories (So Far) of Deborah Eisenberg', 'kKQcuQEACAAJ', 'When Deborah Eisenberg''s first book of stories, Transactions in a Foreign Currency, was published, John Updike noted: "Whenever a new writer arrives, a new window of life is opened, and this has happened here." The scope and depth of Eisenberg''s idiosyncratic vision were even more apparent in her second collection, Under the 82nd Airborne, which The New York Times Book Review called "nothing short of extraordinary." As these two collections gathered here into one volume show, Eisenberg''s stories have an astonishing power and range. Her characters, whether they are walking in the streets of Manhattan or seemingly abandoned in foreign countries, continually make disquieting and sometimes life-threatening discoveries about themselves, discoveries that illuminate not only their own lives but also the wider net of relationships in which they are enmeshed.', 'en', 1997, 496, 'http://books.google.com/books/content?id=kKQcuQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
