INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('69636c09-89eb-55b3-ab4d-116d55dff288', '9780374525118', 'The Spirit Level', '_cOkdT2-to8C', 'The Nobel Prize-winning author presents a volume of poems that explores life''s new beginnings, the significance of ordinary objects, the legacy of a deceased Scottish poet, and the situation in his native Northern Ireland. Reprint.', 'en', 1997, 82, 'http://books.google.com/books/content?id=_cOkdT2-to8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
