INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e3339b17-f25e-5fe7-a1a2-7ee19d61152a', '9780374525866', 'The Magic Barrel', 'WmcxuzutV2wC', 'Winner of the National Book Award for Fiction Introduction by Jhumpa Lahiri Bernard Malamud''s first book of short stories, The Magic Barrel, has been recognized as a classic from the time it was published in 1959. The stories are set in New York and in Italy (where Malamud''s alter ego, the struggleing New York Jewish Painter Arthur Fidelman, roams amid the ruins of old Europe in search of his artistic patrimony); they tell of egg candlers and shoemakers, matchmakers, and rabbis, in a voice that blends vigorous urban realism, Yiddish idiom, and a dash of artistic magic. The Magic Barrel is a book about New York and about the immigrant experience, and it is high point in the modern American short story. Few books of any kind have managed to depict struggle and frustration and heartbreak with such delight, or such artistry.', 'en', 2003, 240, 'http://books.google.com/books/content?id=WmcxuzutV2wC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
