INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cf7debfe-d1f4-5696-b620-ac099545e181', '9780374526962', 'The Eclogues of Virgil', 'ANx9WZHGzEwC', 'Virgil''s great lyrics, rendered by the acclaimed translator of The Odes of Horace and Gilgamesh The Eclogues of Virgil gave definitive form to the pastoral mode, and these magically beautiful poems, which were influential in so much subsequent literature, perhaps best exemplify what pastoral can do. "Song replying to song replying to song," touchingly comic, poignantly sad, sublimely joyful, the various music that these shepherds make echoes in scenes of repose and harmony, and of hardship and trouble in work and love. A bilingual edition, The Eclogues of Virgil includes concise, informative notes and an Introduction that describes the fundamental role of this deeply original book in the pastoral tradition.', 'en', 2000, 112, 'http://books.google.com/books/content?id=ANx9WZHGzEwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
