INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8d5a7c80-7772-551f-91ce-f494155254d5', '9780374530259', 'Gimpel the Fool', 'GLacGqTFTBgC', 'Isaac Bashevis Singer''s first collection of stories, Gimpel the Fool, is a landmark work that has attracted international acclaim since it was first published in 1957. In Saul Bellow''s masterly translation, the title story follows the exploits of Gimpel, an ingenuous baker who is universally deceived but who declines to retaliate against his tormentors. Gimpel and the protagonists of the other stories in this volume all inhabit the distinctive pre-World War II ghettos of Poland and, beyond that, the larger world created by Singer''s unforgettable prose.', 'en', 1957, 224, 'http://books.google.com/books/content?id=GLacGqTFTBgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
