INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0babf99f-71f5-5a94-921c-bdf3ecb7a365', '9780374530303', 'Martin and John', '5bh4680Gf6gC', 'Peck weaves together two sets of stories--the story of John''s life and the stories that John writes in his journals--to create a compelling portrait of a homosexual artist confronted with his own mortality in the wake of AIDS. "A stunning debut".--The New York Times.', 'en', 2006, 248, 'http://books.google.com/books/content?id=5bh4680Gf6gC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
