INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b16be247-4fff-5347-b6cb-de5423e1047f', '9780374530310', 'Georgics (Zongo Classics)', 'JJGJDwAAQBAJ', 'The Georgics is a poem by Latin poet Virgil, likely published in 29 BC. As the name suggests (from the Greek word γεωργικά, geōrgika, i.e. "agricultural (things)") the subject of the poem is agriculture; but far from being an example of peaceful rural poetry, it is a work characterized by tensions in both theme and purpose. The Georgics is considered Virgil''s second major work, following his Eclogues and preceding the Aeneid. The poem draws on a variety of prior sources,[citation needed] and has influenced many later authors from antiquity to the present.', 'en', 2017, 224, 'http://books.google.com/books/content?id=JJGJDwAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2052', 'accepted', 'Virgil', 'Poetry', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 8 FROM public.book WHERE isbn13 = '9780374530310' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('82c50c44-2b10-528f-8e67-87d94a98f565', '9780374530495', 'Palm-of-the-Hand Stories', 'GT10AlhQeksC', 'Nobel Prize winner Yasunari Kawabata felt the essence of his art was to be found not in his longer works but in a series of short-stories which he called Palm-of-the-hand-stories - written over the span of his career. In them we find loneliness, love and the passage of time, demonstrating the range and complexity of a true master.', 'en', 2006, 288, 'http://books.google.com/books/content?id=GT10AlhQeksC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
