INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b802fda9-6b5e-5e1b-b483-f962e704ab37', '9780374626235', 'The complete stories', 'daBNh2-ZJTgC', '"The publication of this extraordinary volume firmly established Flannery O''Connor''s monumental contribution to American fiction. There are thirty-one stories here in all, including twelve that do not appear in the only two short story collections O''Connor put together in her short lifetime -- Everything that Rises Must Converge and A Good Man Is Hard to Find." - back cover.', 'en', 1971, 555, 'http://books.google.com/books/content?id=daBNh2-ZJTgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
