INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('93409157-bc8c-55fd-a348-a26b3160367a', '9780375408274', 'Ralph Ellison', 'aKkQOf8hJMkC', 'A critical biography of the author of Invisible Man draws on access to Ellison''s personal papers to offer a definitive study of the life, work, and influence of Ralph Ellison, detailing his poverty-stricken Oklahoma youth, his education and involvement in New York''s liberal intellectual circles, his personal relationships, and the influence of racism on his life. 40,000 first printing.', 'en', 2007, 657, 'http://books.google.com/books/content?id=aKkQOf8hJMkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
