INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5ebe2006-e624-52ce-8742-771d2b9159c6', '9780375760525', 'Paris 1919', '5NYdwyI5acQC', 'National Bestseller New York Times Editors’ Choice Winner of the PEN Hessell Tiltman Prize Winner of the Duff Cooper Prize Silver Medalist for the Arthur Ross Book Award of the Council on Foreign Relations Finalist for the Robert F. Kennedy Book Award For six months in 1919, after the end of “the war to end all wars,” the Big Three—President Woodrow Wilson, British prime minister David Lloyd George, and French premier Georges Clemenceau—met in Paris to shape a lasting peace. In this landmark work of narrative history, Margaret MacMillan gives a dramatic and intimate view of those fateful days, which saw new political entities—Iraq, Yugoslavia, and Palestine, among them—born out of the ruins of bankrupt empires, and the borders of the modern world redrawn.', 'en', 2002, 570, 'http://books.google.com/books/content?id=5NYdwyI5acQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
