INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d3924535-096f-5d15-bfb9-d7c25a1a420f', '9780380016365', 'Laura', 'jqaFlU8xeVEC', 'centerCourage, Adventure, Steadfast Love From a little house set deep in the Big Woods of Wisconsin, across Indian territory and into the Dakotas, Laura''s family moved westward right along the frontier. Their true-life saga, beloved by countless millions of TV viewers and readers of the bestselling Little House books, is one of spirit and devotion in the face of bitter-cold winters, wilderness trails, and heartbreaking personal tragedy. Here, for the first time, and drawing on her own unpublished memoirs is the endlessly fascinating full account of Laura''s life -- from her earliest years through her enduring marriage to Almanzo Wilder, the "farmer boy" of her stories.', 'en', 1977, 241, 'http://books.google.com/books/content?id=jqaFlU8xeVEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
