INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6c0d27dc-e9ed-5b54-a234-103483f2a1c9', '9780380713813', 'Made in America', 'G8d_4MxVUjoC', 'Bill Bryson, who gave glorious voice to The Mother Tongue, now celebrates her magnificent offspring in the book that reveals once and for all how a dusty western hamlet with neither woods nor holly came to be known as Hollywood...and exactly why Mr. Yankee Doodle call his befeathered cap "Macaroni."', 'en', 1996, 364, 'http://books.google.com/books/content?id=G8d_4MxVUjoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
