INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('631b3c81-3ee6-55fc-9ed2-dcfa4fbda52e', '9780380718122', 'Lucie Babbidge''s House', '5RyCPwAACAAJ', 'Having found a dollhouse full of dolls in the orphanage where she leads an unhappy existence, Lucie creates a secret life for herself.', 'en', 1993, 242, 'http://books.google.com/books/content?id=5RyCPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
