INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('68236978-44bf-5da7-91be-67819deb9ecb', '9780380720866', 'Shadow of a Dark Queen', 'j5YylwEACAAJ', 'A dread darkness is descending upon a great land called Midkemia—a powerful and malevolent race of monsters that has slipped through a hole in the dimensions. And two unlikely young heroes—a bastard heir denied his birthright and an irrepressible scoundrel with a penchant for thievery—must take up arms in the struggle to protect their besieged world...two friends chosen by Destiny to stand at the fore of the battle that is to come against the gargantuan reptile army of the terrible Emerald Queen.', 'en', 1995, 497, 'http://books.google.com/books/content?id=j5YylwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
