INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('02ae69f5-7f98-5048-84e2-b069166479a2', '9780380725786', 'The Death of an Irish Sea Wolf', '_-poqwbBCD4C', 'In a remote community off the west coast of Ireland, residents inclined to gossip speculate why reclusive Clement Ford, the "Sea Wolf," has become such a generous benefactor to his neighbors. then one night, a mysterious figure from Ford''s past arrives on the island, and by morning three people are murdered and Ford has disappeared. In the wake of the tragedy, Chief Superintendent Peter McGarr, and his intuitive wife, Noreen, along with his trusted staff from the Murder Squad, must piece together the deadly evening''s events and answer the questions: Who really is the enigmatic Sea Wolf? And what does he have that is worth killing so many people for?', 'en', 1997, 304, 'http://books.google.com/books/content?id=_-poqwbBCD4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
