INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8c37cec9-6b76-5274-ac1d-53c9c0ca89a3', '9780380731152', 'Devil May Care', 'KzCRA1zOY1EC', 'Ellie is young, rich, engaged and in love. These are the carefree days before marriage and new responsibility, and anything goes -- including house-sitting at eccentric Aunt Kate''s palatial estate in Burton, Virginia. Ellie feels right at home here with the nearly invisible housekeepers and the plethora of pets, but she soon realizes that there are disturbing secrets about the local aristocracy buried in a dusty old book she has carried into the mansion. And her sudden interest in the past is attracting a slew of unwelcome guests -- some of them living and some, perhaps not. And the terrible vegeance that Ellie and her friends seem to have aroused -- now aimed at them -- surely cannot be...satanic.', 'en', 1977, 352, 'http://books.google.com/books/content?id=KzCRA1zOY1EC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
