INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f4300da0-1996-5ee9-9a5e-e1639cc3f91e', '9780380731220', 'Summer of the Dragon', 'vykTQCOW5mEC', 'A good salary and an all-expenses-paid summer spent a sprawling Arizona ranch is too good a deal for fledgling anthropologist D.J. Abbott to turn down. What does it matter that her rich new employer/benefactor, Hank Hunnicutt, is a certified oddball who is presently funding all manner of off-beat projects, from alien conspiracy studies to a hunt for dragon bones? There''s even talk of treasure buried in the nearby mountains, but D.J. isn''t going to allow loose speculation -- or the considerable charms of handsome professional treasure hunter Jesse Franklin -- to sidetrack her. Until Hunnicutt suffers a mysterious accident and then vanishes, leaving the weirdos gathered at his spread to eye each other with frightened suspicion. But on a high desert search for the missing millionaire, D.J. is learning things that may not be healthy for her to know. For the game someone is playing here goes far beyond the rational universe -- and it could leave D.J. legitimately dead.', 'en', 2001, 352, 'http://books.google.com/books/content?id=vykTQCOW5mEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
