INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('04c82293-fdf4-52a8-a339-510d8b811349', '9780380732548', 'Anne Frank', '3ja19MjRbPMC', 'From July 1942 until August 1944, a young girl named Anne Frank kept a diary. Keeping a diary isn''t unusual. Lots of girls do. But Anne''s diary was unique. It chronicled the two years she and her family spent hiding from the Germans who were determined to annihilate all the Jews in Europe. In this sensitive and thoughtful introduction to the Holocaust and to the life of one of its best known victims, acclaimed author Johanna Hurwitz deftly evokes the background of World War II while capturing the unforgettable spirit and tragedy of Anne''s life. From July 1942 until August 1944, a young girl named Anne Frank kept a diary. Keeping a diary isn''t unusual. Lots of girls do. But Anne''s diary was unique. It chronicled the two years she and her family spent hiding from the Germans who were determined to annihilate all the Jews in Europe. In this sensitive and thoughtful introduction to the Holocaust and to the life of one of its best known victims, acclaimed author Johanna Hurwitz deftly evokes the background of World War II while capturing the unforgettable spirit and tragedy of Anne''s life.', 'en', 1999, 64, 'http://books.google.com/books/content?id=3ja19MjRbPMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
