INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d4dd44ed-a000-5bef-8bb3-6b06edd53953', '9780380755691', 'Silver Nights', '4JbTRtjo7C4C', 'An Arranged Marriage Free-spirited Sophia is a tempestuous heiresscapable of turning heads and breaking hearts. Orderedinto a loveless marriage that could bring her even greater riches, Sophia accepts her fate-until she sets her eyes on Adam, the virile nobleman who is to escort her to her future husband''s estate. Adam is immediately captivated by Sophia''sheated sensuality, which sears through his cool reserve and makes him forget his duty. As for Sophia,she is powerless to resist his intense masculinity andair of mystery. Rebelling against her impending marriage, Sophia willfully surrenders herself body and soul to Adam''s intense passion...only to discover that the price of forbidden love could be her life. Free-spirited Sophia is a tempestuous heiress capable of turning heads and breaking hearts. Ordered into a loveless marriage that could bring her even greater riches, Sophia accepts her fate -- until she sets her eyes on Adam, the virile nobleman who is to escort her to her future husband''s estate. Adam is immediately captivated by Sophia''s heated sensuality, which sears through his cool reserve and makes him forget his duty. As for Sophia, she is powerless to resist his intense masculinity and air of mystery. Rebelling against her impending marriage, Sophia willfully surrenders herself body and soul to Adam''s intense passion...only to discover that the price of forbidden love could be her life.', 'en', 2001, 352, 'http://books.google.com/books/content?id=4JbTRtjo7C4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
