INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e456779c-3afa-509a-8fdd-12fb0763bc8b', '9780380759507', 'Firefly', 'eYQVOMmb0hMC', 'The inhabitants of a remote estate in Florida''s savannah country fall under the spell of a horrible predator who inflames and perverts their sexual desires, leading to a series of bizarre and deadly encounters', 'en', 1992, 466, 'http://books.google.com/books/content?id=eYQVOMmb0hMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
