INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c83cb479-2f96-5fdb-b98d-18202cadcf7d', '9780380763399', 'Only Mine', 'jh3rmQlmE08C', 'Whether she′s creating incomparable love stories of passion and redemption or breathtaking tales of romantic suspense, there is simply no finer storyteller at work today than the phenomenal New York Times bestseller Elizabeth Lowell. The bastard son of a viscount and a Cheyenne shaman′s daughter, Wolfe Lonetree agrees to rescue the pampered Lady Jessica from an unwanted impending wedding -- but only if she will be his wife. Naive and shockingly innocent, Lady Jessica Charteris tricked a rugged, handsome stranger into a marriage in name only in order to escape a union with a vile British lord. Totally unprepared for the hardships awaiting her in America, she is terrified by the prospect of life in the harsh and magnificent land at the edge of the Rockies. But even more frightening is Wolfe himself -- a man whose raw sensuality leaves her breathless. Her proud, virile new "husband" is not one to be trifled with, nor will he be denied what his heart fervently desires -- for only in Wolfe Lonetree′s arms can Jessica truly learn the unparalleled joy of becoming the right man′s woman.', 'en', 1992, 400, 'http://books.google.com/books/content?id=jh3rmQlmE08C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
