INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0cc151b0-1d3e-539c-a04b-d45be3a0b5ed', '9780380771080', 'Neon Lit:city of Glass', 'qimLQgAACAAJ', 'A graphic, crime noir novel on a New York detective-cum-novelist who answers a wrong number. A double- barreled investigation, one from the perspective of the detective, the other from that of the novelist. Adapted from Paul Auster''s City of Glass by the creators of Maus.', 'en', 1994, 129, 'http://books.google.com/books/content?id=qimLQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
