INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2ce9694c-c4a2-5c7a-9a9c-8bbdd6251ca6', '9780380777587', 'Runaway Bride', 'M2JQxGf2Ex8C', 'Employing her talents with the martial arts and disguise, Melanie Wyatt smuggles stolen goods to buy freedom for enslaved Chinese children, until Alex McClure, the agent hired to investigate, uncovers her operation and her vulnerable heart. Original.', 'en', 1994, 390, 'http://books.google.com/books/content?id=M2JQxGf2Ex8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
