INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bfb0e0ac-0eb7-51da-895b-87fdc7298212', '9780380784912', 'The Night Remembers', 'xuv2zRcXFiAC', 'Having fled halfway across the country to escape her heartbreaking past, Angela Prescott finds salvation in the embrace of Jesse Brown Wolf, a repairman of Native American descent whose existence is shrouded in mystery, maybe even magic. Reprint.', 'en', 1998, 355, 'http://books.google.com/books/content?id=xuv2zRcXFiAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2216', 'accepted', 'Kathleen Eagle', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 13 FROM public.book WHERE isbn13 = '9780380784912' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a475ccfb-eef7-51de-be4a-662957c96e5c', '9780380789023', 'Smoke and Mirrors', 'VsEtBq0glyQC', 'In the deft hands of Neil Gaiman, magic is no mere illusion ... and anything is possible. In this, Gaiman''s first book of short stories, his imagination and supreme artistry transform a mundane world into a place of terrible wonders -- a place where an old woman can purchase the Holy Grail at a thrift store, where assassins advertise their services in the Yellow Pages under "Pest Control," and where a frightened young boy must barter for his life with a mean-spirited troll living beneath a bridge by the railroad tracks. Explore a new reality -- obscured by smoke and darkness, yet brilliantly tangible -- in this extraordinary collection of short works by a master prestidigitator. It will dazzle your senses, touch your heart, and haunt your dreams.', 'en', 2005, 365, 'http://books.google.com/books/content?id=VsEtBq0glyQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2217', 'accepted', 'Neil Gaiman', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 2 FROM public.book WHERE isbn13 = '9780380789023' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bfdc3d14-7b40-5d6a-a398-26f95872333c', '9780380789832', 'Shards of a Broken Crown', 'jITPlgEACAAJ', 'The demon is no more. The enemy has been routed. But all is not well . . . Winter''s icy grasp is loosening on the world. The Emerald Queen''s vanquished army has its broken back to the Bitter Sea. And treachery is its only recourse. A lackey has declared himself Lord of the defeated, amassing the still fearsome remnants of a ruthless fighting force together for one final assault on a weakened, vulnerable realm. For the warriors who remained steadfast against terrible numbers, for the courageous souls who barely survived a devastating onslaught upon their homeland, the time to rebuild and renew has not yet come. The war is not over in Midkemia. And Jimmy and Dash—two young noble brothers who stand at the center of a gathering storm—are impelled to action that could secure a tenuous peace . . . or turn triumph into catastrophe. The demon is no more. The enemy has been routed. But all is not well . . .', 'en', 1999, 498, 'http://books.google.com/books/content?id=jITPlgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2218', 'accepted', 'Raymond E. Feist', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 6 FROM public.book WHERE isbn13 = '9780380789832' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e8bb56c5-4495-53d8-a2ad-ce00aaf0bc12', '9780380792047', 'Sins of a Shaker Summer', 'ku7bR_YYKFcC', 'Two little girls have suddenly become deathly ill, and eldress Rose Callahan suspects they may have eaten something from the Medicinal Herb Garden. Her suspicions focus on Andrew, who is expanding the tiny industry and experimenting with new herbs. But as Rose investigates, an unexplained death occurs and some chilling secrets come to light--secrets that may make Rose the next victim.', 'en', 1999, 272, 'http://books.google.com/books/content?id=ku7bR_YYKFcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
