INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d7044bbf-fbf3-5b7d-8248-a00c6f1bddfe', '9780380793471', 'Regarding the Fountain', 'ZvPzrkzpzJcC', 'The Dry Creek Middle School drinking fountain has sprung a leak, so principal Walter Russ dashes off a request to Flowing Waters Fountains, Etc. ...We need a new drinking fountain. Please send a catalog. Designer Flo Waters responds: "I''d be delighted...but please understand that all of my fountains are custom-made." Soon the fountain project takes on a life of its own, one chronicled in letters, postcards, memos, transcripts, and official documents. The school board president is up in arms. So is Dee Eel, of the water-supply company. A scandal is brewing, and Mr. Sam N.''s fifth grade class is turning up a host of hilarious secrets buried deep beneath the fountain.', 'en', 1999, 144, 'http://books.google.com/books/content?id=ZvPzrkzpzJcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2220', 'accepted', 'Kate Klise', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 3 FROM public.book WHERE isbn13 = '9780380793471' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f72aea7c-370e-5437-a0d3-905cb19c9297', '9780380794874', 'What Looks Like Crazy On an Ordinary Day', 'FoIQtW6tqhAC', 'In a remarkable debut novel that sizzles with sensuality, crackles with life-affirming energy and moves the reader to laughter and tears, author Pearl Cleage creates a world rich in character, human drama, and deep, compassionate understanding. After a decade of luxe living in Atlanta, Ava Johnson has returned to tiny Idlewild, Michigan -- her fabulous career and power plans smashed to bits on one dark truth: Ava has tested positive for HIV. Bur rather than a sorrowful end, her homecoming is a new beginning. Because, in the ten-plus years since she left, all the problems of the big city have invaded the sleepy community of her childhood. Because dear friends and family sorely need her help in the face of impending trouble and tragedy, and Ava cannot turn her back on them. And because, most importantly, Ava Johnson is inexplicabley and undeniably falling in love.', 'en', 1998, 244, 'http://books.google.com/books/content?id=FoIQtW6tqhAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2221', 'accepted', 'Pearl Cleage', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 17 FROM public.book WHERE isbn13 = '9780380794874' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1c510410-4beb-5754-900e-0d360531d026', '9780380803279', 'Exile''s Return', 'LfkimAEACAAJ', 'Saved by a mage''s intervention from certain death, Kaspar, the evil Duke of Olasko, is lord no more -- reduced to an exile''s existence and forced to wander the harshest realms of the world he once enslaved. Merciless deserts, forbidding mountains, and vast oceans now separate the once powerful despot from his former seat of power -- his dark dreams of vengeance overwhelmed by the daily struggle for survival. But there is a larger drama that will entangle the broken dictator. An evil devastating and deadly seeks entrance to the land -- the mystical tool of a dark empire hungry for conquest and destruction -- and Kaspar has inadvertently discovered the key. Suddenly, Midkemia''s last hope is a disgraced and exiled duke whose history is written in blood, and who now must wield his sword as her champion . . . if he so chooses..', 'en', 2006, 343, 'http://books.google.com/books/content?id=LfkimAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
