INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('19f67257-e9e2-5c02-a192-2a0e0b2c04a0', '9780380809066', 'The Great Book of Amber', '_Z93A1ltySIC', 'Roger Zelazny''s Chronicles of Amber have earned their place as all-time classics of imaginative literature. Now here are all ten novels, together in one magnificent omnibus volume. Witness the titanic battle for supremacy waged on Earth, in the Courts of Chaos, and on a magical world of mystery, adventure, and romance.', 'en', 1999, 1258, 'http://books.google.com/books/content?id=_Z93A1ltySIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
