INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('20381bf6-11c6-5071-a447-c3e0e25fc526', '9780380810956', 'The Wolves in the Walls', 'Ksx1aCPS7CoC', 'Lucy hears sneaking, creeping, crumpling noises coming from inside the walls. She is sure there are wolves living in the walls of her house.', 'en', 2005, 56, 'http://books.google.com/books/content?id=Ksx1aCPS7CoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2224', 'accepted', 'Neil Gaiman', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 4 FROM public.book WHERE isbn13 = '9780380810956' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('552a5858-1760-5b97-8faf-67ea1b3248cd', '9780380813810', 'Lamb', 'cM4dlwEACAAJ', 'The birth of Jesus has been well chronicled, as have his glorious teachings, acts, and divine sacrifice after his thirtieth birthday. But no one knows about the early life of the Son of God, the missing years -- except Biff, the Messiah''s best bud, who has been resurrected to tell the story in the divinely hilarious yet heartfelt work "reminiscent of Vonnegut and Douglas Adams" (Philadelphia Inquirer). Verily, the story Biff has to tell is a miraculous one, filled with remarkable journeys, magic, healings, kung fu, corpse reanimations, demons, and hot babes. Even the considerable wiles and devotion of the Savior''s pal may not be enough to divert Joshua from his tragic destiny. But there''s no one who loves Josh more -- except maybe "Maggie," Mary of Magdala -- and Biff isn''t about to let his extraordinary pal suffer and ascend without a fight.', 'en', 2003, 444, 'http://books.google.com/books/content?id=cM4dlwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2225', 'accepted', 'Christopher Moore', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 19 FROM public.book WHERE isbn13 = '9780380813810' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('85314331-79ba-5898-bc6d-9bfcd714c512', '9780380813865', 'The Body in the Lighthouse', 'jd0ulwEACAAJ', 'Something was very wrong on Sanpere this summer . . . To escape the misery of a sweltering August in Aleford, Massachusetts, caterer and minister''s wife Faith Fairchild and her family head for their cottage on Maine''s peaceful Sanpere Island in Penobscot Bay. But things have changed since their last visit. An aggressive developer is moving forward on plans that will destroy the unique ambience of the island, infuriating residents. Tensions are running dangerously high, and soon murder rears its hideous head. Faith discovers a corpse while exploring the grounds of Sanpere''s historic lighthouse. With fear running rampant and volatile emotions approaching the detonation point, the intrepid sleuth must track down a killer for the sake of a friend and the island she loves.', 'en', 2004, 352, 'http://books.google.com/books/content?id=jd0ulwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2226', 'accepted', 'Katherine Hall Page', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 7 FROM public.book WHERE isbn13 = '9780380813865' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('af431fa7-4af0-5dd7-8a2d-9524c1b914db', '9780380815692', 'The Nightingale''s Song', '7f3GGwAACAAJ', 'Maggie Quinn thinks she has room in her head for only the helpless orphans in her care -- until Gordon Kincaid walks into St. Columba''s. A proud Southern gentleman damaged by the Civil War, he has come to Baltimore to find the daughter he never knew -- a beautiful child who is one of Maggie''s favorites -- and bring her home to Virginia. And when he asks Maggie to accompany them, all she can say is "yes." Widowed and wounded inside, Gordon turns to the emerald-eyed Irish beauty to help him pick up the pieces. Though he senses her distrust he is drawn to Maggie''s angelic voice, her sensuality and passion...and to a tenderness that compels him to share with her his soul. But the scars of war go deep. And it will take uncommon strength for two people who stood on opposite sides to find redemption and a new life in love.', 'en', 2001, 384, 'http://books.google.com/books/content?id=7f3GGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2227', 'accepted', 'Kathleen Eschenburg', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 2 FROM public.book WHERE isbn13 = '9780380815692' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7a83542a-6d4e-5297-b43b-26c24317ba35', '9780380815937', 'In the Beginning...was the Command Line', 'iL9wBRPaTDEC', 'This is "the Word" -- one man''s word, certainly -- about the art (and artifice) of the state of our computer-centric existence. And considering that the "one man" is Neal Stephenson, "the hacker Hemingway" (Newsweek) -- acclaimed novelist, pragmatist, seer, nerd-friendly philosopher, and nationally bestselling author of groundbreaking literary works (Snow Crash, Cryptonomicon, etc., etc.) -- the word is well worth hearing. Mostly well-reasoned examination and partial rant, Stephenson''s In the Beginning... was the Command Line is a thoughtful, irreverent, hilarious treatise on the cyber-culture past and present; on operating system tyrannies and downloaded popular revolutions; on the Internet, Disney World, Big Bangs, not to mention the meaning of life itself.', 'en', 1999, 151, 'http://books.google.com/books/content?id=iL9wBRPaTDEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2228', 'accepted', 'Neal Stephenson', 'Computers', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 0 FROM public.book WHERE isbn13 = '9780380815937' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d85d5c85-de49-58a3-ae42-34a4359d9b88', '9780380817931', 'Olympos', 'rbEOlwEACAAJ', 'Beneath the gaze of the gods, the mighty armies of Greece and Troy met in fierce and glorious combat, scrupulously following the text set forth in Homer''s timeless narrative. But that was before twenty-first-century scholar Thomas Hockenberry stirred the bloody brew, causing an enraged Achilles to join forces with his archenemy Hector and turn his murderous wrath on Zeus and the entire pantheon of divine manipulators; before the swift and terrible mechanical creatures that catered for centuries to the pitiful idle remnants of Earth''s human race began massing in the millions, to exterminate rather than serve. And now all bets are off.', 'en', 2006, 891, 'http://books.google.com/books/content?id=rbEOlwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2229', 'accepted', 'Dan Simmons', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 10 FROM public.book WHERE isbn13 = '9780380817931' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fe5b52d1-5962-5c39-8650-ad93e372c706', '9780380818204', 'The Marriage Lesson', 'CLc-ICBzMskC', 'Lesson #1: Never Tempt a Lady Become a bride? Never! Lady Marianne Shelton has come to London to experience life, and marriage is not part of her plan. To finance her independent future, the pretty country miss pens a series of anonymous stories. Soon they are the talk of the ton-and only she knows that her wicked hero is based on none other than bold, brash Thomas Effington, the future Duke of Roxborough. Lesson #2: Never Deny a Marquess, Thomas has been thrust into le of Marianne''s protector. When she threatens to experience life with the first willing rogue to come along, he decides the best recourse is to tutor her himself. And when he accidentally compromises her honor, he''s willing to accept their only recourse: a wedding. Marianne claims she wants no part of marriage, but her intoxicating allure and disarming willingness make her irresistible. And now Thomas is determined to teach her a lesson: that true love will last forever.', 'en', 2001, 372, 'http://books.google.com/books/content?id=CLc-ICBzMskC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
