INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3cbd013f-c949-5270-bc46-c219f229d3c2', '9780385333900', 'Jailbird', 'QP-4sh0QbtMC', 'A master of contemporary American literature, Vonnegut has authored 18 highly acclaimed books and dozens of short stories and essays. This wry tale follows bumbling bureaucrat Walter F. Starbuck from Harvard to the Nixon White House to the penitentiary as Watergate''s least known co-conspirator.', 'en', 1999, 310, 'http://books.google.com/books/content?id=QP-4sh0QbtMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
