INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c6ec70f4-fd90-5cf6-b02a-96e1a8d98c28', '9780385497398', 'D. B.', 'h_ZvDwAAQBAJ', 'A fictional account of a plane hijacking by American folk hero D. B. Cooper profiles him as a Vietnam veteran who drifts through the early 1970s counterculture before parachuting and disappearing from the 727 he has hijacked, and who is investigated years later by retired FBI agent Frank Marshall. Reprint.', 'en', 2005, 356, 'http://books.google.com/books/content?id=h_ZvDwAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
