INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('68ebdd2c-6f03-5dd1-b73f-6f627d6aff56', '9780385503846', 'Moral Disorder', '1RbbwAEACAAJ', 'A new collection of short fiction presents ten stories that capture important moments in the course of a life and in the lives intertwined with it, in a volume that ranges from the 1930s to the 1980s, is set in a variety of locales, and includes such works as "The Bad News," "The Art of Cooking and Serving," "My Last Duchess," "The Boys at the Lab," and the title tale. 75,000 first printing.', 'en', 2006, 255, 'http://books.google.com/books/content?id=1RbbwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
