INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7e3f4174-2a97-58b3-acc0-893b6197fde5', '9780385604833', 'Walk about', 'BAptri_qXXwC', 'Combined in one volume are Bryson''s Down Under, an account of his memorable walk across Australia, and A Walk in the Woods, that tells of his lengthy stroll along the longest continuous footpath in the world - The Appalachian Trail, with his old friend Stephen Katz. The Trail stretches along the East Coast of the United States, from Georgia to Maine, through some of the most arresting and celebrated landscapes in America - the Smoky Mountains, Shenandoah National Park, the Berkshire Hills of Massachusetts and the Great North Woods of Main.', 'en', 2002, 543, 'http://books.google.com/books/content?id=BAptri_qXXwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
