INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('81b443eb-bf4a-564f-80c7-45e76fb60c37', '9780385721059', 'Good Faith', '5xf0lEBVpn8C', 'Emerging from an ugly divorce in the early 1980s, real estate salesman Joe Stratford is reluctant to join his friend Marcus in a get-rich-quick scheme and wonders about the advances of a free-spirited married woman. By the Pulitzer Prize-winning author of A Thousand Acres. Reader''s Guide available. Reprint. 100,000 first printing.', 'en', 2004, 432, 'http://books.google.com/books/content?id=5xf0lEBVpn8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
