INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4a3bb1c0-b1f4-583b-8281-37743a5d27b0', '9780385721875', 'The Age of Grief', 'uJNpAAAAMAAJ', 'The luminous novella and stories in The Age of Grief explore the vicissitudes of love, friendship, and marriage with all the compassion and insight that have come to be expected from Jane Smiley, the Pulitzer Prize—winning author of A Thousand Acres. In “The Pleasure of Her Company,” a lonely, single woman befriends the married couple next door, hoping to learn the secret of their happiness. In “Long Distance,” a man finds himself relieved of the obligation to continue an affair that is no longer compelling to him, only to be waylaid by the guilt he feels at his easy escape. And in the incandescently wise and moving title novella, a dentist, aware that his wife has fallen in love with someone else, must comfort her when she is spurned, while maintaining the secret of his own complicated sorrow. Beautifully written, with a wry intelligence and a lively comic touch, The Age of Grief captures moments of great intimacy with grace, clarity, and indelible emotional power.', 'en', 2002, 224, 'http://books.google.com/books/content?id=uJNpAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
