INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1a40046e-08d9-5c9c-a7ba-a73f3f3a7415', '9780385721912', 'Man Walks Into a Room', 'NZVBDwAAQBAJ', 'Found wandering in the desert outside of Las Vegas, Samson Greene, a thirty-six-year-old Columbia University English professor, is discovered to have a brain tumor, but when surgery removes the tumor, leaving him with no recollection of his life after the age of twelve, he finds himself struggling to deal with a life, and a wife, he no longer recognizes. A first novel. Reprint. 12,500 first printing.', 'en', 2003, 248, 'http://books.google.com/books/content?id=NZVBDwAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
