INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('88391996-917e-5b08-8edf-2004240584c9', '9780393050578', 'Will in the World', 'S6RkYWZdCn0C', 'A portrait of Elizabethan England and how it contributed to the making of William Shakespeare discusses how he moved to London lacking money, connections, and a formal education; started a family; attempted to forge his career in the competitive theater world; grappled with dangerous religious and political forces; and rose to became his age''s foremost playwright. 100,000 first printing.', 'en', 2004, 430, 'http://books.google.com/books/content?id=S6RkYWZdCn0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
