INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('aff879dd-a473-5dbd-aabc-00b3bba5d6b4', '9780393057249', 'Trainspotting', 'tDsmsXeVZyQC', 'Brace yourself, America, for Irvine Welsh''s Trainspotting—the novel and the film that became the cult sensations of Britain. Trainspotting is the novel that first launched Irvine Welsh''s spectacular career—an authentic, unrelenting, and strangely exhilarating episodic group portrait of blasted lives. It accomplished for its own time and place what Hubert Selby, Jr.''s Last Exit to Brooklyn did for his. Rents, Sick Boy, Mother Superior, Swanney, Spuds, and Seeker are as unforgettable a clutch of junkies, rude boys, and psychos as readers will ever encounter. Trainspotting was made into the 1996 cult film starring Ewan MacGregor and directed by Danny Boyle (A Shallow Grave).', 'en', 2002, 340, 'http://books.google.com/books/content?id=tDsmsXeVZyQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
