INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4ac532d1-d68d-5df9-ab2d-7fa5290c55fe', '9780393057799', 'Redemption', 'z47KmpWe4GsC', 'Draws on FBI files and interviews with family and friends to offer a portrait of the twentieth-century American literary icon, from his incest-marked childhood on the Jewish Lower East Side through his later years in New Mexico.', 'en', 2005, 384, 'http://books.google.com/books/content?id=z47KmpWe4GsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
