INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7977821f-5d5d-58c4-ac90-feee91df2d1f', '9780393703276', 'The Body Remembers: The Psychophysiology of Trauma and Trauma Treatment', 'sq40yAEACAAJ', 'Relates the impact of trauma on the body to the phenomenon of somatic memory. The book illuminates the value of understanding the psychophysiology of trauma for both therapists and their traumatised clients. It progresses from relevant theory to applicable practice.', 'en', 2000, 208, 'http://books.google.com/books/content?id=sq40yAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
