INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5e05f54b-af9d-5286-a4ad-2db17fed1fbc', '9780393924954', 'A History of Modern Europe', 'uvyqHAAACAAJ', 'Available in both one-volume and two-volume paperback editions, A History of Modern Europe presents a panoramic survey of modern Europe from the Renaissance to the present day. A seasoned teacher and talented historian, Professor John Merriman offers a carefully crafted narrative that guides students through a vast amount of complex material, integrating the many aspects of the European experience into a larger, interconnected whole. A full ten percent shorter than its predecessor, the Second Edition has tightened organization throughout to make room for recent research and descriptions of the current issues and events that define Europe''s role in the world today.', 'en', 2004, 1040, 'http://books.google.com/books/content?id=uvyqHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
