INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cbf6c56f-5d8d-5f40-8518-153315fab53e', '9780393925722', 'The Norton Anthology of Western Literature: Beginnings through the Renaissance', 'rzFvPgAACAAJ', 'Read by millions of students over seven editions, The Norton Anthology of Western Literature remains the most trusted undergraduate survey of Western literature available and one of the most successful college texts ever published.', 'en', 2005, 2704, 'http://books.google.com/books/content?id=rzFvPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
