INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('043cbb69-312a-5421-86f3-f438fc43a268', '9780393927207', 'The Norton Anthology of English Literature', '41MumgEACAAJ', 'Firmly grounded by the hallmark strengths of all Norton Anthologies—thorough and helpful introductory matter, judicious annotation, complete texts wherever possible—The Norton Anthology of English Literature has been revitalized in this Eighth Edition through the collaboration between six new editors and six seasoned ones. Under the direction of Stephen Greenblatt, General Editor, the editors have reconsidered all aspects of the anthology to make it an even better teaching tool.', 'en', 2006, 1104, 'http://books.google.com/books/content?id=41MumgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
