INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('72c0070c-73cd-5f99-a72c-673da288e3b9', '9780393959055', 'Walden ; And, Resistance to Civil Government', 'uVxnQgAACAAJ', 'The classic chronicle of a communion with nature at Walden Pond offers a message of living simply and in harmony with nature, and Thoreau champions the belief that people of conscience are at liberty to follow their own opinions.', 'en', 1992, 482, 'http://books.google.com/books/content?id=uVxnQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
