INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fda16a54-6b22-5347-ab45-f9ca8095a0bf', '9780393960570', 'The Awakening', '5ui9QwAACAAJ', 'The text is that of the first edition of the novel, published by Herbert S. Stone in 1899. It has been annotated by the editor and includes translations of French phrases and information about New Orleans locales, customs, and lore, the Bayou region, and Creole culture. "Bibliographical and Historical Contexts", expanded and introduced by a new Editor''s Note, presents biographical, historical, and cultural documents contemporary with the novel''s publication. Included are a biographical essay by the acclaimed Chopin biographer Emily Toth, "An Etiquette/Advice Book Sampler" with selections from the conduct books of the period in which Chopin lived and wrote, and period fashion plates from Harper''s Bazar. A comprehensive "Criticism" section, introduced by a new Editor''s Note, contains expanded selections from hard-to-find contemporary reviews of the novel; two letters of mysterious origin written in response to the novel; and Chopin''s "Retraction," which followed The Awakening''s negative reception. These are followed by twenty-seven interpretive essays, twelve of them new to the Second Edition, that provide a variety of perspectives on The Awakening, including essays by Cynthia Griffin Wolff, Nancy Walker, Elizabeth Fox-Genovese, Paula A. Treichler, Sandra M. Gilbert, Lee R. Edwards, Patricia S. Yaeger, Elizabeth Ammons, and Elaine Showalter. A Chronology of Chopin''s life and an updated Selected Bibliography are also included.', 'en', 1994, 336, 'http://books.google.com/books/content?id=5ui9QwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2442', 'accepted', 'Kate Chopin; Margo Culley', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 9 FROM public.book WHERE isbn13 = '9780393960570' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7d2e3434-bdb5-508d-b60a-6aa0d2bc794f', '9780393963045', 'The Foundations of Early Modern Europe, 1460-1559', 'W_-kQgAACAAJ', 'This synthesis of Europe''s Renaissance and Reformation periods thematically traces the transition from the medieval to the modern. The major themes of the book include technological breakthroughs and their social and economic consequences, the connections between the discovery of new lands and the recovery of ancient learning, Europe''s economic expansion, humanist culture, the formation of the early modern state, and reform and revolution in the Church.', 'en', 1994, 218, 'http://books.google.com/books/content?id=W_-kQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2444', 'accepted', 'Eugene F. Rice; Anthony Grafton', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 8 FROM public.book WHERE isbn13 = '9780393963045' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e8b6b087-ac03-54e0-8fa0-a78ba0c0eb99', '9780393964523', 'Robinson Crusoe', 'mqSfQgAACAAJ', 'Michael Shinagel has collated the reprint with all six authorizededitions published by Taylor in 1719 to achieve a text that is faithfulto Defoe''s original edition. Annotations assist the reader with obscurewords and idioms, biblical references, and nautical terms. "Contexts" helps the reader understand the novel''s historical andreligious significance. Included are four contemporary accounts ofmarooned men, Defoe''s autobiographical passages on the novel''sallegorical foundation, and aspects of the Puritan emblematic traditionessential for understanding the novel''s religious aspects. "Eighteenth-and Nineteenth-Century Opinions" is a comprehensive studyof early estimations by prominent literary and political figures,including Alexander Pope, Jean-Jacques Rousseau, Samuel Johnson, SamuelTaylor Coleridge, William Wordsworth, Edgar Allen Poe, Thomas BabingtonMacaulay, Charles Dickens, Karl Marx, and John Stuart Mill. "Twentieth-Century Criticism" is a collection of fourteen essays (fiveof them new to the Second Edition) that presents a variety ofperspectives on Robinson Crusoe by Virginia Woolf, Ian Watt, EricBerne, Maximillian E. Novak, Frank Budgen, James Joyce, George A.Starr, J. Paul Hunter, James Sutherland, John J. Richetti, LeopoldDamrosch, Jr., John Bender, Michael McKeon, and Carol Houlihan Flynn. A Chronology of Defoe''s life and work and an updated SelectedBibliography are also included.', 'en', 1994, 436, 'http://books.google.com/books/content?id=mqSfQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2445', 'accepted', 'Daniel Defoe; Michael Shinagel', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 13 FROM public.book WHERE isbn13 = '9780393964523' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d86203ca-9023-5836-bf98-cd6789777699', '9780393974294', 'The Norton Anthology of Theory and Criticism', 'qYN4QgAACAAJ', 'This welcome addition to the Norton anthologies binds the writings from 148 authors--among them Gorgias of Leontini, Plato, Aristotle, Horace, Longinus, Quintilian, Dante, Corneille, Dryden, Aphra Behn, Vico, Wollstonecraft, Coleridge, Poe, Baudelaire, Lukacs, Heidegger, Gramsci, Barthes, Raymond Williams, Haraway, Hebdige, hooks, Judith Butler, and the most recent theorist, Stuart Moulthrop.', 'en', 2001, 2662, 'http://books.google.com/books/content?id=qYN4QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
