INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ceb25224-e0c8-520f-ab40-e944a4211b5c', '9780394751221', 'The history of sexuality', 'bvebugEACAAJ', 'In this sequel to The History of Sexuality, Volume I: An Introduction, the brilliantly original French thinker who died in 1984 gives an analysis of how the ancient Greeks perceived sexuality. Throughout The Uses of Pleasure Foucault analyzes an irresistible array of ancient Greek texts on eroticism as he tries to answer basic questions: How in the West did sexual experience become a moral issue? And why were other appetites of the body, such as hunger, and collective concerns, such as civic duty, not subjected to the numberless rules and regulations and judgments that have defined, if not confined, sexual behavior?', 'en', 1988, 304, 'http://books.google.com/books/content?id=bvebugEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
