INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('749b3c79-c33d-5952-b053-8306dbc9ad8a', '9780395706749', 'Revenge of the Lawn', 'D9t9mAEACAAJ', 'Three unforgettable Brautigan masterpieces reissued in a one-volume omnibus edition. REVENGE OF THE LAWN: Originally published in 1971, these bizarre flashes of insight and humor cover everything from "A High Building in Singapore" to the "Perfect California Day." This is Brautigan''s only collection of stories and includes "The Lost Chapters of TROUT FISHING IN AMERICA." THE ABORTION: AN HISTORICAL ROMANCE 1966: A public library in California where none of the books have ever been published is full of romantic possibilities. But when the librarian and his girlfriend must travel to Tijuana, they have a series of strange encounters in Brautigan''s 1971 novel. SO THE WIND WON''T BLOW IT ALL AWAY: It is 1979, and a man is recalling the events of his twelfth summer, when he bought bullets for his gun instead of a hamburger. Written just before his death, and published in 1982, this novel foreshadowed Brautigan''s suicide.', 'en', 1995, 544, 'http://books.google.com/books/content?id=D9t9mAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
