INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('12820376-bf3b-5f51-899e-3ae322614b6a', '9780399154003', 'Under Orders', 'NKCM8GcDwNwC', 'When three corpses turn up on Cheltenham Gold Cup Day, including a jockey who had earlier in the day won the Triumph Hurdle, ex-jockey-turned-sleuth Sid Halley investigates a possible link to Lord Enstone''s mysterious losing streak, a probe that drags him ever deeper into the dark underside of the racing game. 350,000 first printing.', 'en', 2006, 308, 'http://books.google.com/books/content?id=NKCM8GcDwNwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
