INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('188176da-5ed8-527d-b329-9a098000318d', '9780413735904', 'A Clockwork Orange', 'C-PTAwAAQBAJ', 'Anthony Burgess''s stage play of his infamous cult novel and film of the same name. Alex and his vicious teenage gang revel in horrific violence, mugging and gang rape. Alex also revels in the music of Beethoven. The Gang communicates in a language which is as complicated as their actions. When a drug-fuelled night of fun ends in murder, Alex is finally busted and banged up. He is given a choice - be brainwashed into good citizenship and set free, or face a lifetime inside. Anthony Burgess''s play with music, based on his own provocative 1962 novella of the same name, was first published in 1987. A Clockwork Orangewas made into a film classic by Stanley Kubrick in 1971 and was dramatizes by the RSC in 1990.', 'en', 1998, 51, 'http://books.google.com/books/content?id=C-PTAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
