INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e192c8d9-247c-5302-a951-2b39b70c13ff', '9780413771162', 'The Truth', '3fmdQgAACAAJ', 'A new stage adaptation of one of Pratchett''s best-selling novels There''s been a murder. Allegedly. William de Worde is the Discworld''s first investigative journalist. He didn''t mean to be - it was just an accident. But, as William fills his pages with reports of local club meetings and pictures of humorously shaped vegetables, dark forces high up in Ankh-Morpork''s society are plotting to overthrow the city''s ruler, Lord Vetinari.', 'en', 2002, 336, 'http://books.google.com/books/content?id=3fmdQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
