INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('83b8465c-5245-548e-9522-4a9c1958477a', '9780413771605', 'The Name of the World', 'HMOhAAAACAAJ', 'Michael Reed is a man going through the motions, numbed by the death of his wife and child. But when events force him to act as if he cares, he begins to find people who - against all expectation - help him through his private labyrinth.', 'en', 2001, 129, 'http://books.google.com/books/content?id=HMOhAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
