INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('09caba1b-682d-5094-a2e3-ac31876f2cec', '9780413772428', 'Jesus'' Son', 'C-2nPwAACAAJ', 'A collection of linked stories narrated by a recovering alcoholic and heroin addict, Jesus'' Son is a disturbing portrayal of loneliness and hope. He travels through an American underworld of burnt-out sports stars, hospital waiting rooms, doomed relationships and senseless violence.', 'en', 2004, 192, 'http://books.google.com/books/content?id=C-2nPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
