INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('adccd892-600d-54d9-b7d8-f9d7cc22c485', '9780415050791', 'The Presocratic Philosophers', 'wrNzVF5julgC', '"By and large, scholars have asked what the Presocratics said, and what external circumstances may have prompted their sayings; they have not asked whether the Presocratics spoke truly, ow whether their sayings rested on sound arguments. It is those latter questions with which my book is primarily concerned."--Preface, p.xi.', 'en', 1982, 728, 'http://books.google.com/books/content?id=wrNzVF5julgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
