INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('eac37193-353c-565a-b37d-7448938d8a16', '9780415247719', 'A Routledge Literary Sourcebook on Herman Melville''s Moby-Dick', '7SZJSAAACAAJ', '''Moby Dick'' is one of the great American novels. This literary sourcebook contains everything essential to an informed reading of this epic text, including a contextual overview, contemporary documents, early critical reviews and important annotated passages from the novel.', 'en', 2004, 208, 'http://books.google.com/books/content?id=7SZJSAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
