INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('46651a0c-154d-5c16-8e85-b8d7feeea82b', '9780415266710', 'The Franco-Prussian War', 'qNQFngEACAAJ', 'In 1870 Bismarck ordered the Prussian Army to invade France, inciting one of the most dramatic conflicts in European history. It transformed not only the states-system of the Continent but the whole climate of European moral and political thought. The overwhelming triumph of German military might, evoking general admiration and imitation, introduced an era of power politics, which was to reach its disastrous climax in 1914. First published in 1961 and now with a new introduction, The Franco-Prussian War is acknowledged as the definitive history of one of the most dramatic and decisive conflicts in the history of Europe.', 'en', 2001, 532, 'http://books.google.com/books/content?id=qNQFngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
