INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fdf8279d-715e-5727-a241-411c3f7bb616', '9780415278416', 'Phenomenology of Perception', 'q3HwhfjRmswC', 'Challenging and rewarding in equal measure, Phenomenology of Perception is Merleau-Ponty''s most famous work. Impressive in both scope and imagination, it uses the example of perception to return the body to the forefront of philosophy for the first time since Plato. Drawing on case studies such as brain-damaged patients from the First World War, Merleau-Ponty brilliantly shows how the body plays a crucial role not only in perception but in speech, sexuality and our relation to others.', 'en', 2002, 544, 'http://books.google.com/books/content?id=q3HwhfjRmswC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
