INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9f743ad1-ec7c-5bf8-a26d-e0e2c3ef25f9', '9780415283045', 'New Media Language', 't5sJTjdN0aUC', 'Investigating how changes to the world''s media have affected, and been affected by, language this book explores a wide range of topics looking at the important and wide-ranging implications of these changes on the world - and our world-view.', 'en', 2003, 209, 'http://books.google.com/books/content?id=t5sJTjdN0aUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
