INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4f6ecddd-a719-5cc2-a30d-c3eb9ae98675', '9780415285841', 'Marxism and Literary Criticism', 'kUXXeSBNMx8C', 'Is Marx relevant any more? Why should we care what he wrote? What difference could it make to our reading of literature? Terry Eagleton, one of the foremost critics of our generation, has some answers in this wonderfully clear and readable analysis. Sharp and concise, it is, without doubt, the most important work on literary criticism that has emerged out of the tradition of Marxist philosophy and social theory since the nineteenth century.', 'en', 2002, 84, 'http://books.google.com/books/content?id=kUXXeSBNMx8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
