INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0e554ac5-e6e4-5ac6-9475-4e5b94c3c914', '9780425144374', 'Clear and Present Danger', 'RKlOA3XUU5EC', 'The sudden and surprising assassination of three American officials inColombia. Many people in many places, moving off on missions they all mistakenly thought theyunderstood. The future was too fearful for contemplation, and beyond the expected finish lineswere things that, once decided, were better left unseen. Tom Clancy''s new thriller is based on America''s war on drugs . . . and the covert --and shocking -- U. S. response.', 'en', 1989, 688, 'http://books.google.com/books/content?id=RKlOA3XUU5EC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
