INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5e229885-7add-53cd-8bff-68e165ede1aa', '9780425147511', 'The Key to Midnight', 'LUeL6EHN7wgC', 'Millionaire investigator Alex Hunter meets exciting, desirable Joanna Rand while on a mission in Japan but finds that she is a Senator''s daughter who disappeared 10 years ago and now has a new identity. By a #1 best-selling author. Reissue.', 'en', 1995, 419, 'http://books.google.com/books/content?id=LUeL6EHN7wgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
