INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2ea42be2-d36b-5540-a49e-f60f2702374a', '9780435233396', 'His Dark Materials', 'VlBnzbljptgC', 'From the novels by Philip Pullman, this brilliant adaptation by Nicholas Wright of His Dark Materials is sure to be a runaway success with your students - such is the popularity of the original trilogy which has earned wide literary acclaim. Consists of the two critically acclaimed plays performed at the National Theatre both printed in one volume - thus offering exceptional value for money. Invaluable teacher''s notes and student drama activities written by Ruth Moore and Paul Bunyan, recognised experts in the area of Drama in English. Philip Pullman worked closely with playwright Nicolas Wright to create the text, and both writers have contributed introductions to our edition. The exciting, highly imaginative storyline, which captivates boys and girls alike, offers a wide range of textual and dramatic investigations. Parts for all the class, and ideal for smaller groups, with potential for interchangeable male/female roles.', 'en', 2005, 320, 'http://books.google.com/books/content?id=VlBnzbljptgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
