INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('33076d96-08e0-55b0-ad95-f6dedbe489b3', '9780435909611', 'When Rain Clouds Gather', '3AzcBdsfW9QC', 'Two exiles--one white, one black--in a poor village in Botswana struggle with tradition, climate, and the local chief as they try to modernize the villagers'' farming methods.', 'en', 1995, 185, 'http://books.google.com/books/content?id=3AzcBdsfW9QC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
