INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0af8bda1-7ccf-5bb1-a11a-ca69784bed94', '9780439341202', 'Every cloud has a silver lining', '4XVUmgYuvTMC', 'Abby Hayes is starting fifth grade. Her supersibs, the perfect older twins and her genius little brother, have already proved their Hayes worthiness. This is going to be Abby''s year ... and she''s going to record every moment of it.', 'en', 2001, 118, 'http://books.google.com/books/content?id=4XVUmgYuvTMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
