INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c01c6c16-b4a5-5a85-917e-f51ecec37069', '9780439389846', 'The truth about Stacey', 'OK_Esqf06akC', 'The truth about Stacey is that she has diabetes. Nobody knows-- except her friends in the Baby-sitters Club. But even they don''t know the real truth about Stacey. Stacey''s parents are her bigger problem. They won''t recognize what she''s going through, leaving her feeling more alone than ever.', 'en', 2002, 167, 'http://books.google.com/books/content?id=OK_Esqf06akC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
