INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('70ca22d4-2202-5c51-98ff-9b5c921567ed', '9780439485876', 'The Seventh Tower', 'MaYVLILy7xoC', 'Tal has spent his whole life in the darkness. He knows nothing else of the world. Far below the Castle, there lives an Icecarl warrior named Milla. Her fate and Tal''s are irreversibly linked. Together they will discover the secrets behind the veil and the forces desperately trying to tear it apart.', 'en', 2004, 649, 'http://books.google.com/books/content?id=MaYVLILy7xoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
