INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e2c35cf1-0547-53d1-8905-f5822ee2848f', '9780439499064', 'Anacaona, Golden Flower', '3nf5GwAACAAJ', 'Edwidge Danticat, the award-winning, best-selling author of THE FARMING OF BONES and KRIK? KRAK! offers a powerful addition to The Royal Diaries series with the story of Haiti''s heroic queen Anacaona. With her signature narrative grace, Edwidge Danticat brings Haiti''s beautiful queen Anacaona to life. Queen Anacaona was the wife of one of her island''s rulers, and a composer of songs and poems, making her popular among her people. Haiti was relatively quiet until the Spanish conquistadors discovered the island and began to settle there in 1492. The Spaniards treated the natives very cruelly, and when the natives revolted, the Spanish governor of Haiti ordered the arrests of several native nobles, including Anacaona, who was eventually captured and executed, to the horror of her people.', 'en', 2005, 187, 'http://books.google.com/books/content?id=3nf5GwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
