INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('41716bd7-3e49-5990-85d6-ae9bb276d120', '9780439507226', 'The Discovery', 'K7l6Dt6t3vEC', 'Sharks, shipwreck, and sunken treasure in the latest adventure trilogy from Gordon Korman. Four kids are on a marine expedition for the summer, diving to explore an underwater habitat that''s just been altered by a seismic event. What they find, though, is much more than fish - it''s sunken treasure. Can they salvage it without anyone else getting to it first? Will the prospect of wealth set them against one another? And what about those sharks . . . . Dive is another action-packed trilogy from Gordon Korman. The narrative will shift between an account of two kids caught in the shipwreck and the story of the four kids fighting over and desperately trying to get the treasure.', 'en', 2003, 141, 'http://books.google.com/books/content?id=K7l6Dt6t3vEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
