INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f6d54312-b343-50db-a56a-c53078d80fea', '9780439569729', 'SCHOLASTIC SUCCESS WITH 4TH GRADE(WORKBOOK)', 'b-EBHQAACAAJ', '416 bright, colorful pages that give kids practice in the skills every 4th grader needs to be successful. Includes addition and subtraction, multiplication and division, fractions and decimals, problem solving, number concepts, reading comprehension, writing, grammar, maps, and lots more. For use with Grade 4.', 'en', 2003, 416, 'http://books.google.com/books/content?id=b-EBHQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
