INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9d2ec96b-5642-54be-b360-14a75699a3dc', '9780439944397', 'Hello! Is That Grandma?', 'cepoNwAACAAJ', 'Who''s on the phone? Lift the flaps and see! Imagine you dialled a wrong number-and got through to a sheep . . . then a cow . . . then a duck . . . then a very hungry crocodile! And all you wanted to do was wish your grandma ''Happy Birthday!'' A bouncy riot of wrong numbers from best-selling author Ian Whybrow. Quirky illustrations by Deborah Allwright, and lots of fold-out flaps add to the fun.', 'en', 2007, 32, 'http://books.google.com/books/content?id=cepoNwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
