INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ca41c5c2-1551-5728-81b7-9728d33b2eb1', '9780439959049', 'Savage Stone Age Sticker Book', 'avYdPQAACAAJ', 'History with the nasty bits left in!The Savage Stone Age Sticker Book is crammed full of putrid picturepuzzles and wicked word games to bring all those horrible huntersand nasty Neanderthals to life.Want to:make a Stone Age mummy?create your very own cave painting?stampede a mighty mammoth over and over again?Get stuck in to Terry Deary''s foul facts and Martin Brown''s craftycartoons - with over 100 re-usable stickers, you''re sure to findthe Savage Stone Age forever a-peeling!History has never been so horrible!', 'en', 2005, 20, 'http://books.google.com/books/content?id=avYdPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
