INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('558c3c4e-c9be-5973-a588-8fea76981e82', '9780439968089', 'Trickster''s Choice', 'sJ22AAAACAAJ', 'Alianne has an oppressive heritage. She is the daughter of Alanna, Lady Knight and King''s Champion - the foremost warrior of Tortall. Aly is not a fighter - she hates her mother''s obsession, which constantly takes her away from her family and makes her children feel neglected and resentful. After a stormy argument with her mother, Aly runs away to make them sorry. But she gets more than she bargained for when she is kidnapped by pirates, and sold as a slave in the far-off Copper Isles. Aly''s future is bleak, but then she finds out that this has all been planned, by a god, no less. Aly is a favourite of the god Kyprioth - she is the Trickster''s Choice.', 'en', 2004, 453, 'http://books.google.com/books/content?id=sJ22AAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
