INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('50a6fe97-f655-5b09-9e6e-e83e55527590', '9780446354738', 'Nothing Lasts Forever', '_uUTSJW-hSAC', 'Three young doctors-their hopes, their dreams, their unexpected desires... Dr. Paige Taylor: She swore it was euthanasia, but when Paige inherited a million dollars from a patient, the D.A. called it murder. Dr. Kat Hunter: She vowed never to let another man too close again-until she accepted the challenge of a deadly bet. Dr. Honey Taft: To make it in medicine, she knew she''d need something more than the brains God gave her. Racing from the life-and-death decisions of a big major hospital to the tension-packed fireworks of a murder trial, Nothing Lasts Forever lays bare the ambitions and fears of healers and killers, lovers and betrayers. And proves once again that no reader can outguess Sidney Sheldon, the master of the unexpected.', 'en', 1995, 384, 'http://books.google.com/books/content?id=_uUTSJW-hSAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
