INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7323a83e-47ea-5526-a234-b4725b461e6c', '9780446363167', 'Back Bay', 'C_EeTC915JQC', 'Meet the Pratt clas. Driven men. Determined women. Through six turbulent generations, they would pursue a lost Paul Revere treasure. And turn a family secret into an obsession that could destroy them. Here is the novel that launched William Martin''s astonishing literary career and became an instant bestseller. From the grit and romance of old Boston to exclusive -- and dangerous -- Back Bay today, this sweeping saga paints an unforgettable portrait of a powerful dynasty beset by the forces of history...and a heritage of greed, lust, murder and betrayal.', 'en', 1992, 532, 'http://books.google.com/books/content?id=C_EeTC915JQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
