INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f899314f-b091-5e04-8252-4fd951654563', '9780446600347', 'Where There''s Smoke', 'K9QUrq73KPsC', 'When a determined doctor meets the rebellious heir to a Texas oil dynasty, sparks fly . . . but the flames of passion blazing between them could destroy an empire. No one knows why Dr. Lara Mallory opened up her medical practice in the rowdy Texas town controlled by Tackett Oil. But everyone remembers her role in the well-publicized scandal that caused the downfall of White House hopeful Senator Clark Tackett. Now the iron-fisted matriarch of Tackett Oil intends to use her money and power to drive Lara out of town . . . especially when Lara meets Key, the hell-raising -- and handsome -- youngest Tackett son. Following a cataclysmic meeting, this determined doctor and brash, daring pilot find themselves hurtling on a dangerous quest for the one secret that can destroy the Tackett empire -- and anyone who dares to challenge its power. But Lara decides to find the truth behind the corruption in town, even if it costs her everything.', 'en', 1994, 512, 'http://books.google.com/books/content?id=K9QUrq73KPsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
