INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bac30ff2-d49e-5c96-b365-27de1196ad77', '9780446600705', 'Assumed Identity', 'vB0-qjLsg18C', 'Tracking a devastating conspiracy into the heart of Mexico''s Yucata+a7n peninsula, a master of disguise begins to lose his grasp on who he really is and struggles with his love for two women. Reprint.', 'en', 1994, 512, 'http://books.google.com/books/content?id=vB0-qjLsg18C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
