INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2d9bc500-63b3-5863-95d5-93b1285303c3', '9780446601856', 'Charade', 'mt2jEn5Y27IC', 'A TV star with a new lease on life must team up with an ex-cop to investigate a series of murders and dark secrets while danger lurks just outside her door. A medical miracle gives TV personality Cat Delaney more than a new heart. With her second chance at life Cat trades Hollywood for San Antonio, where she hosts a TV show for children with special needs. Here she meets Alex Pierce, an ex-cop turned crime writer -- and the first man to see her as a woman since her surgery. But her new world turns sinister when fatal "accidents" begin killing other heart recipients, and a mysterious stalker starts shadowing her every move. Soon Cat realizes Alex may or may not be her most important ally -- and that her new heart comes at a terrible price: a tangled web of secrets and someone determined to take her life.', 'en', 1995, 496, 'http://books.google.com/books/content?id=mt2jEn5Y27IC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
