INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2a892e81-2bc7-55a1-805b-cabc2125c04c', '9780446602488', 'Night Train to Memphis', 'uxgPtgEACAAJ', 'An assistant curator of Munich''s National Museum, Vicky Bliss is no expert on Egypt, but she does have a Ph.D. in solving crimes. So when an intelligence agency offers her a luxury Nile cruise if she''ll help solve a murder and stop a heist of Egyptian antiquities, all 5''11" of her takes the plunge. Vicky suspects the authorities really want her to lead them to her missing lover, the art thief and master of disguises she knows only as "Sir John Smythe." And right in the shadow of the Sphinx she spots him. . . with his new flame. Vicky is so furious at this romantic stab-in-the-back, not to mention the sudden arrival of her meddling boss, Herr Dr. Schmidt, that she may overlook a danger as old as the pharaohs and as unchanging. . . a criminal who hides behind a mask of charm while moving in for the kill.', 'en', 1995, 368, 'http://books.google.com/books/content?id=uxgPtgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2878', 'accepted', 'Elizabeth Peters', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 0 FROM public.book WHERE isbn13 = '9780446602488' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bf3fd01c-cef8-5d0c-a3f5-20b4f2b4c856', '9780446604239', 'Exclusive', 'ZdtyxreMq58C', 'An ace reporter investigates the suspicious death of her best friend''s baby in this #1 New York Times bestselling political thriller of murder, passion, and intrigue in the White House. Barrie Travis is not famous; she''s just a damn good reporter stuck at a low-budget television station. Then, her old friend -- now America''s First Lady -- asks her to investigate the death of her baby. Stunned by grief after the loss of her infant son, the President''s wife hints that her child didn''t really die of SIDS; in reality, he may have been murdered. Blind to everything but finding the truth, Barrie delves into the private lives of the president and his wife and uncovers dark and terrible secrets that will test her ethics, her patriotism, and her courage. With the help of Gray Bondurant, a mysterious former presidential aide, this story could topple the presidency and change the course of history. In this fast-moving tale from a master of suspense, Barrie must fight powerful forces that want nothing more than to see the scandalous past -- and a certain young reporter -- dead and buried.', 'en', 1997, 496, 'http://books.google.com/books/content?id=ZdtyxreMq58C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
