INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f8dce023-1e7d-5239-9a50-fe51fb0cbdc2', '9780446604406', 'The Laws of Our Fathers', 'qsCa3Ae3Ga8C', 'In Kindle County, a woman is killed in an apparent random drive-by shooting. The woman turns out to be the ex-wife of a prominent state senator and an old acquaintance of Judge Sonia Klonsky, on whose desk the case lands. As the pursuit of justice takes bizarre and unusual turns, Judge Klonsky is brought face-to-face with a host of extraordinary personalities and formidable enemies bent on her destruction.', 'en', 1997, 817, 'http://books.google.com/books/content?id=qsCa3Ae3Ga8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
