INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4c4e410c-2935-578a-81e1-e8b13e938984', '9780446605588', 'Fat Tuesday', 'nfqPbNwaV1EC', 'In this "intriguing" thriller (People), a New Orleans police officer kidnaps an attorney''s wife in an act of revenge -- but he''s not expecting the electric attraction between them. Burke Basile is a cop with nothing left to lose. Haunted by his partner''s death, the end of his marriage, and the destruction of his career, he targets his nemesis, a flamboyant attorney who helps killers evade justice. Burke''s shocking revenge centers around kidnapping Remy, the lawyer''s trophy wife. But Burke hasn''t planned on the scorching desire he''ll feel for this desperate woman, who rose from the slums of New Orleans to marry a man she can never love. Nor can he predict the fierce duel that will explode as the clock ticks toward midnight on Fat Tuesday when all masks will be stripped away -- and Burke will be forced to confront his own terrifying secret.', 'en', 1998, 458, 'http://books.google.com/books/content?id=nfqPbNwaV1EC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2882', 'accepted', 'Sandra Brown', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 17 FROM public.book WHERE isbn13 = '9780446605588' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('013d738e-b35a-5914-aff4-a2c42bc67df0', '9780446606813', 'Message in a Bottle', '0uvZReSiL1gC', 'In this New York Times bestseller, a single mother sets out to find the North Carolina man who sent a message meant for someone else . . . and the journey may change her life forever. Divorced and disillusioned about relationships, Theresa Osborne is jogging when she finds a bottle on the beach. Inside is a letter of love and longing to "Catherine," signed simply "Garrett." Challenged by the mystery and pulled by emotions she doesn''t fully understand, Theresa begins a search for this man that will change her life. What happens to her is unexpected, perhaps miraculous-an encounter that embraces all our hopes for finding someone special, for having a love that is timeless and everlasting.... Nicholas Sparks exquisitely chronicles the human heart. In his first bestselling novel, The Notebook, he created a testament to romantic love that touched readers around the world. Now in this New York Times bestseller, he renews our faith in destiny, in the ability of lovers to find each other no matter where, no matter when...', 'en', 1999, 370, 'http://books.google.com/books/content?id=0uvZReSiL1gC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
