INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('90dbc95e-cb5e-5181-b65a-790fac6fc864', '9780446607131', 'Death of a Gossip', 'CqONGwAACAAJ', 'When society widow and gossip columnist Lady Jane Winter''s body is fished out of the river, Lochdubh Constable Hamish Macbeth and Priscilla Halburton-Smythe navigate the choppy waters of the tattler''s life to find a murderer. Reprint.', 'en', 1999, 179, 'http://books.google.com/books/content?id=CqONGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
