INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('45cfb4f0-03fb-571b-ae9f-6f22fd6b227a', '9780446608473', 'The Wild Swans', 'kOcSuQAACAAJ', 'This novel focuses on two outcasts on two journeys in two eras. In 1689 England, Lady Eliza Grey''s 11 brothers are turned into swans. Rejected by her father, Eliza is flown to America by her brothers where she has a chance to save them--until she is accused of witchcraft. In the second story, set in 1981 New York, Elias Latham has AIDS, is banished from his father''s house, and must learn to live on the streets. Like Eliza, Elias struggles to understand the suffering he must endure.', 'en', 2001, 464, 'http://books.google.com/books/content?id=kOcSuQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
