INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0666df13-688c-551d-b380-dfa6eb5cdac2', '9780446608602', 'Personal Injuries', '0NnWtHEBKYIC', 'To Robbie Feaver the law is all about making a play-to a client, a jury, or a judge. But when the flashy, womanizing, multimillion-dollar personal injury lawyer is caught offering bribes, he''s forced to wear a wire. Even as the besieged attorney looks after his ailing wife, Feaver must also make tapes that will hurl his friends, his enemies, his city, and a particular FBI undercover agent into a crisis of conscience and law. Now Robbie Feaver is making the play of his life.', 'en', 2000, 528, 'http://books.google.com/books/content?id=0NnWtHEBKYIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2888', 'accepted', 'Scott Turow', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 3 FROM public.book WHERE isbn13 = '9780446608602' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f4d86627-0ece-5478-8136-6699a00d1870', '9780446608893', 'Saving Faith', 'twgvDm-fjRMC', 'When lobbyist Faith Lockhart stumbles upon a corruption scheme at the highest levels of government, she becomes a dangerous witness who the most powerful men in the world will go to any lengths to silence in this #1 New York Times bestselling thriller. In a secluded house not far from Washington, D.C., the FBI is interviewing one of the most important witnesses it has ever had: a young woman named Faith Lockhart. For Faith has done too much, knows too much, and will tell too much. Feared by some of the most powerful men in the world, Faith has been targeted to die. But when a private investigator walks into the middle of the assassination attempt, the shooting suddenly goes wrong, and an FBI agent is killed. Now Faith Lockhart must flee for her life--with her story, her deadly secret, and an unknown man she''s forced to trust...', 'en', 2000, 528, 'http://books.google.com/books/content?id=twgvDm-fjRMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2889', 'accepted', 'David Baldacci', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 14 FROM public.book WHERE isbn13 = '9780446608893' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('341cc069-2982-5b2f-bd01-18cb761b0a34', '9780446609197', 'A Highland Christmas', 'vu1jewAACAAJ', 'From the author of the Agatha Raisin television series...A HIGHLAND CHRISTMAS: A Hamish Macbeth Mystery Celebrate the Holidays with M. C. Beaton, The Queen of The Cozy Mystery. In the dark, wintry highlands of Lochdubh, Scotland, where the local Calvinist element resists the secular trimmings of Christmas, the spirit of Old St. Nick is about as welcome as a flat tire on a deserted road. Nor is crime taking a holiday, as Constable Hamish Macbeth soon finds himself protecting an unhappy girl, unlocking the secrets of a frightened old woman, and retrieving some stolen holiday goods. Now the lanky lawman must use all his Highland charm and detective skills to make things right. And he had better do it quickly, for the church bells will soon toll and all of Lochdubh will be forced to face another dreary winter without the comforting embrace of Yuletide cheer.', 'en', 2002, 160, 'http://books.google.com/books/content?id=vu1jewAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
