INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b44e4a59-2bf6-529a-a52e-1a6f52638db8', '9780446612760', 'Still Life with Crows', 'vLPTtgAACAAJ', 'A small Kansas town has turned into a killing ground. Is it a serial killer, a man with the need to destroy? Or is it a darker force, a curse upon the land? Amid golden cornfields, FBI Special Agent Pendergast discovers evil in the blood of America''s heartland. No one is safe.', 'en', 2004, 564, 'http://books.google.com/books/content?id=vLPTtgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
