INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('909368a4-0c86-54c5-95aa-b985dfc2f18a', '9780446614160', 'Words of Silk', '9QiYGwAACAAJ', 'Laney McLeod''s life changes the minute she gets stuck in an elevator in Manhattan-and relies on handsome stranger Deke Sargent to help her fight her claustrophobia. When the power comes back on, Deke and Laney find themselves in a passionate embrace that leads to a night of love. Shocked at her indiscretion, Laney disappears the next morning. Months later, she receives an even greater shock: Deke shows up in her life with an astounding announcement. Unable to forget the chemistry between them, but afraid that she''s just another notch on this wealthy playboy''s bedpost, Laney is about to discover an even deeper fear...one that she must face or forever lose the one man she can''t resist.', 'en', 2005, 224, 'http://books.google.com/books/content?id=9QiYGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2896', 'accepted', 'Sandra Brown', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 19 FROM public.book WHERE isbn13 = '9780446614160' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c13c9fcb-c7df-56be-9f96-199bb094b824', '9780446614832', '3rd Degree', 'U4iBuffnoCkC', 'In James Patterson''s shockingly suspenseful #1 New York Times bestseller, one member of the Women''s Murder Club is hiding a secret so dangerous that it could destroy them all. One of James Patterson''s best loved heroines is about to die. Detective Lindsay Boxer is jogging along a beautiful San Francisco street when a fiery explosion rips through the neighborhood. When Lindsay plunges inside to search for survivors, she finds three people dead. A lost infant and a mysterious message at the scene leaves Lindsay and the San Francisco Police Department completely baffled. Then a prominent businessman is found murdered under bizarre circumstances, with another mysterious message left behind by the killer. Lindsay asks her friends Claire Washburn of the medical examiner''s office, Assistant D.A. Jill Bernhardt, and Chronicle reporter Cindy Thomas to help her figure out who is committing these murders-and why they are intent on killing someone every three days. Even more terrifying, the killer has targeted one of the four friends who call themselves the Women''s Murder Club. Which one will it be?', 'en', 2005, 339, 'http://books.google.com/books/content?id=U4iBuffnoCkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
