INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('88959b09-19da-5a01-a3ed-b03101798613', '9780446616416', 'Kitty and the Midnight Hour', 'UeIpVizqFbIC', 'Kitty Norville is a midnight-shift DJ for a Denver radio station-and a werewolf in the closet. Sick of lame song requests, she accidentally starts ''The Midnight Hour'', a late-night advice show for the supernaturally disadvantaged. After desperate vampires, werewolves, and witches across the country begin calling in to share their woes, her new show is a raging success. But it''s Kitty who can use some help. With one sexy werewolf-hunter and a few homicidal undead on her tail, Kitty may have bitten off more than she can chew...', 'en', 2005, 259, 'http://books.google.com/books/content?id=UeIpVizqFbIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
