INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('862b6fba-bd91-5369-b507-041b196007fa', '9780446616836', 'Love Beyond Reason', 'srU7PgAACAAJ', 'This story reflects the trends and attitudes that were popular at the time, but its theme are eternal and universal. As in all romance fiction, the plot revolves around star-crossed lovers. There are moments of passion, anguish, and tenderness-all integral facets of falling in love.', 'en', 2005, 272, 'http://books.google.com/books/content?id=srU7PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
