INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c89de0d6-0b7b-5e41-86f2-ad91ffeafa88', '9780446617451', 'The White Wolf''s Son', 'rCd8PQAACAAJ', '- Aspect published the previous novel in the series, The Skrayling Tree, in hardcover (0-446-53104-9) in 2003 and in mass market (0-446-61340-1) in 7/04. The prior novel. The Dreamthief''s Daughter (Aspect hardcover, 2001, 0-446-52618-5; mass market, 2002, 0-446-61120-4) received praise from the Washington Post, Denver Post, and Locus, where it was featured on the 2001 Recommended Reading list. - Aspect reissued Moorcock''s classic Gloriana, or the Unfulfill''d Queen in trade paperback in 8/04. Gloriana won Moorcock the World Fantasy Award, the John W. Campbell Award, and the British Fantasy Award. - Moorcock''s Elric the Eternal Champion saga has been optioned by Universal Pictures, with Chris and Paul Weitz (American Pie) producing. - Michael Moorcock is a vanguard author, editor, journalist, critic, and rock musician, who is editor of the controversial magazine New Worlds. A member of the Science Fiction and Fantasy Hall of Fame, Moorcock has won the Guardian Fiction Prize, the Nebula Award, the World Fantasy Award, and the British Fantasy Award, among others.', 'en', 2006, 432, 'http://books.google.com/books/content?id=rCd8PQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2900', 'accepted', 'Michael Moorcock', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 2 FROM public.book WHERE isbn13 = '9780446617451' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('63eb729f-1453-536e-9594-6b833f0e7604', '9780446617796', 'The Angel Experiment', 's2sZyAEACAAJ', 'In James Patterson''s blockbuster series, fourteen-year-old Maximum Ride, better known as Max, knows what it''s like to soar above the world. She and all the members of the "flock"--Fang, Iggy, Nudge, Gasman and Angel--are just like ordinary kids--only they have wings and can fly. It may seem like a dream come true to some, but their lives can morph into a living nightmare at any time...like when Angel, the youngest member of the flock, is kidnapped and taken back to the "School" where she and the others were experimented on by a crew of wack jobs. Her friends brave a journey to blazing hot Death Valley, CA, to save Angel, but soon enough, they find themselves in yet another nightmare--this one involving fighting off the half-human, half-wolf "Erasers" in New York City. Whether in the treetops of Central Park or in the bowels of the Manhattan subway system, Max and her adopted family take the ride of their lives. Along the way Max discovers from her old friend and father-figure Jeb--now her betrayed and greatest enemy--that her purpose is save the world--but can she?', 'en', 2006, 413, 'http://books.google.com/books/content?id=s2sZyAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
