INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('acd26ea7-f62a-50d3-a9da-7e7cbadc531d', '9780446670784', 'Curries Without Worries', 'G4qUHAAACAAJ', 'A thorough but accessible guide to Indian cuisine explains spices and seasonings and offers more than sixty-five simple, easy-to-prepare recipes for vegetarian and non-vegetarian curries, roasts, kebabs, and more. Reprint.', 'en', 1996, 160, 'http://books.google.com/books/content?id=G4qUHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
