INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6857b3d2-99b8-5395-9dbb-5daad49ffb88', '9780446678452', 'Cane River', 'BqCdYgEACAAJ', 'The "New York Times" bestseller and Oprah''s Book Club Pick--the unique and deeply moving epic of four generations of African-American women based on one family''s ancestral past.', 'en', 2002, 522, 'http://books.google.com/books/content?id=BqCdYgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
