INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bff27f31-91b7-5633-b003-7766901dde29', '9780446679084', 'Plum Island', 'BNzdYgEACAAJ', 'The hair-raising suspense of The General''s Daughter... the wry wit of The Gold Coast...this is vintage Nelson DeMille at the peak of his originality and the height of his powers...Wounded in the line of duty, NYPD homicide cop John Corey is convalescing in rural eastern Long Island when an attractive young couple he knows is found shot to death on the family patio. The victims were biologists at Plum Island, a research site rumored to be an incubator for germ warfare.Suddenly, a local double murder takes on shattering global implications -- and thrusts Corey and two extraordinary women into a dangerous search for the secret of PLUM ISLAND....', 'en', 2002, 592, 'http://books.google.com/books/content?id=BNzdYgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '2909', 'accepted', 'Nelson DeMille', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 12 FROM public.book WHERE isbn13 = '9780446679084' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b6bf0a69-e879-5040-988f-f129b26f7035', '9780446691406', 'Gloriana', '6j3QtgAACAAJ', 'A fable satirizing Spenser''s "The Fairie Queen" and reflecting the real life of Elizabeth I, tells of a woman who ascends to the throne upon the death of her debauched and corrupted father, King Hern. Gloriana''s reign brings the Empire of Albion into a Golden Age, but her oppressive responsibilities choke her, prohibiting any form of sexual satisfaction, no matter what fetish she tries. Her problem is in fact symbolic of the hypocrisy of her entire court. While her life is meant to mirror that of her nation - an image of purity, virtue, enlightenment and prosperity - the truth is that her peaceful empire is kept secure by her wicked chancellor Monfallcon and his corrupt network of spies and murderers, the most sinister of whom is Captain Quire, who is commissioned to seduce Gloriana and thus bring down Albion and the entire empire.', 'en', 2004, 496, 'http://books.google.com/books/content?id=6j3QtgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
