INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fe8531fe-df02-5127-8edf-91fd8e24860b', '9780446691437', 'The War of Art', '7y6WvgEACAAJ', 'The Art of War meets "The Artist''s Way" in this no-nonsense, profoundly inspiring guide to overcoming creative blocks of every kind.', 'en', 2003, 168, 'http://books.google.com/books/content?id=7y6WvgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
