INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('62edc7d7-f4b9-5bcb-adcf-6140f520127f', '9780446691864', 'The Daily Show with Jon Stewart Presents America (The Book) Teacher''s Edition', 'x2JoPwAACAAJ', 'For everyone who was too cheap to buy the hardcover, the blockbuster, award-winning #1 New York Times bestseller is now in trade paperback-with a new introduction, fully updated, and with equally unsettling nude photos of the newest Supreme Court justices, and a text corrected by the most reputable college professor we could find/afford.Including:Historical inaccuracies, gross distortions, complete fabrications-corrected by real-life bearded college professor.', 'en', 2006, 227, 'http://books.google.com/books/content?id=x2JoPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
