INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('05dbcda3-d3ae-5b14-a2b6-9c6c7e683f90', '9780446692519', 'Feynman''s Rainbow', 'KiXftgAACAAJ', 'As a young physicist, Leonard Mlodinow looked for guidance from his mentor, the Nobel Prize-winning physicist Richard Feynman. Drawing on transcripts from their meetings during their time together at Cal Tech, Mlodinow shares Feynman''s provocative thoughts and observations. At once a moving portrait of a friendship and an affecting account of Feynman''s final, creative years, this book celebrates the inspiring legacy of one of the greatest thinkers of our time.', 'en', 2004, 192, 'http://books.google.com/books/content?id=KiXftgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
