INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cab5e20f-21cf-57f0-9f0e-aa5e80b5b2bd', '9780446696517', 'True Believer', 'kgfuSgAACAAJ', 'As a science journalist with a regular column in Scientific American, Jeremy Marsh specializes in debunking the supernatural. A born skeptic, he travels to the small town of Boone Creek, North Carolina, determined to find the real cause behind the ghostly apparitions that appear in the towns cemetery. What he doesnt plan on, however, is falling hopelessly in love with Lexie Darnell, granddaughter of the town psychic. Now, if the young lovers are to have any kind of future at all, Jeremy must make a difficult choice: return to the life he knows, or do something hes never done beforetake a giant leap of faith.', 'en', 2006, 465, 'http://books.google.com/books/content?id=kgfuSgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
