INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e32df077-7a7b-59a9-a0a0-be3def5f06c7', '9780446698870', 'The Black Dahlia', 'R2s-PgAACAAJ', 'On January 15, 1947, the torture-ravished body of a beautiful young woman is found in a Los Angeles vacant lot. The victim makes headlines as the Black Dahlia-and so begins the greatest manhunt in California history.Caught up in the investigation are Bucky Bleichert and Lee Blanchard: Warrants Squad cops, friends, and rivals in love with the same woman. But both are obsessed with the Dahlia-driven by dark needs to know everything about her past, to capture her killer, to possess the woman even in death. Their quest will take them on a hellish journey through the underbelly of postwar Hollywood, to the core of the dead girl''s twisted life, past the extremes of their own psyches-into a region of total madness.', 'en', 2006, 348, 'http://books.google.com/books/content?id=R2s-PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
