INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7eab8c7f-5e93-5061-9b5e-c87b89bbfad1', '9780446699075', 'Robert Ludlum''s (TM) The Arctic Event', 'W05LxwEACAAJ', 'On a remote island in the Canadian Arctic, researchers discover the wreckage of a mysterious World War II-era aircraft, a discovery that forces the Russian Federation into a shocking admission. The unmarked plane is a Soviet strategic bomber that disappeared with its crew more than fifty years ago while carrying two metric tons of weaponized anthrax. Desperate to prevent a political and diplomatic firestorm, the U.S. president dispatches a Covert-One team led by Lieutenant Colonel Jon Smith to the crash site. But others have reached the frigid, windswept island first, including an international arms dealer and his crew of vicious mercenaries. As for the Russians, they are lying: a second, even deadlier secret rests within the hulk of the lost bomber, a secret the Russians are willing to kill to protect. Trapped in a polar wilderness, Smith and his team find themselves fighting a savage war on two front--against an enemy they can see and another hiding within their own ranks.', 'en', 2007, 390, 'http://books.google.com/books/content?id=W05LxwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
