INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b1bf0282-f045-5234-80ae-0a1beb1a2728', '9780449911945', 'Rabbit at Rest', 'GXWJDQAAQBAJ', 'Winner of the Pulitzer Prize, the Howells Medal, and the National Book Critics Circle Award In John Updike''s fourth and final novel about Harry “Rabbit” Angstrom, the hero has acquired a Florida condo, a second grandchild, and a troubled, overworked heart. His son, Nelson, is behaving erratically; his daughter-in-law, Pru, is sending him mixed signals; and his wife, Janice, decides in midlife to return to the world of work. As, through the year of 1989, Reagan''s debt-ridden, AIDS-plagued America yields to that of the first George Bush, Rabbit explores the bleak terrain of late middle age, looking for reasons to live and opportunities to make peace with a remorselessly accumulating past.', 'en', 1996, 608, 'http://books.google.com/books/content?id=GXWJDQAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
