INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('aa529976-de17-58c3-aea4-847dab59cad2', '9780465003129', 'The Sword and the Shield', '9TWUAQ7Xof8C', 'A fascinating description of a treasure trove of secret documents found by the FBI offers facts about every country in the world, as well as information that contributes to the history of the last century. Reprint. 60,000 first printing.', 'en', 1999, 736, 'http://books.google.com/books/content?id=9TWUAQ7Xof8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
