INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dcb5682f-2f40-53b9-acb5-3edc417eccd8', '9780465031269', 'Why is sex fun?', 'e7IPAQAAMAAJ', 'Why are humans one of the few species to have sex in private? Why are human females the only mammals to go through menopause? Why is the human penis so unnecessarily large? There is no more knowledgeable authority than the award-winning author of THE THIRD CHIMPANZEE to answer these intriguing questions. Here is a delightfully entertaining and enlightening look at the unique sex lives of humans.', 'en', 1997, 176, 'http://books.google.com/books/content?id=e7IPAQAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
