INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('45acadb0-5d2c-5b32-b913-0895670515d2', '9780470008294', 'Jane Austen For Dummies', 'm8WTNQEACAAJ', 'Explains Austen''s methods, motivations, and morals The fun and easy way(r) to understand and enjoy Jane Austen Want to know more about Jane Austen? This friendly guide gives the scoop on her life, works, and lasting impact on our culture. It chronicles the events of her brief life, examines each of her novels, and looks at why her stories - of women and marriage, class and money, scandal and hypocrisy, emotion and satire - still have meaning for us today. Discover * Why Austen is so popular * The impact on manners, courtships, and dating * Love and life in Austen''s world * Her life and key influences * Her most memorable characters', 'en', 2006, 362, 'http://books.google.com/books/content?id=m8WTNQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
