INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('686ca875-e088-5944-87e6-8580dfd3dc15', '9780470861714', 'The Man Who Changed Everything', 'mGo_jtHwL0sC', 'This is the first biography in twenty years of James Clerk Maxwell, one of the greatest scientists of our time and yet a man relatively unknown to the wider public. Approaching science with a freshness unbound by convention or previous expectations, he produced some of the most original scientific thinking of the nineteenth century — and his discoveries went on to shape the twentieth century.', 'en', 2004, 256, 'http://books.google.com/books/content?id=mGo_jtHwL0sC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
