INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('93b590c9-af92-5c8f-8340-60dfe93db917', '9780471272427', 'The Skeptic''s Dictionary', 'h7m6NAEACAAJ', 'A wealth of evidence for doubters and disbelievers "Whether it''s the latest shark cartilage scam, or some new ''repressed memory'' idiocy that besets you, I suggest you carry a copy of this dictionary at all times, or at least have it within reach as first aid for psychic attacks. We need all the help we can get." -James Randi, President, James Randi Educational Foundation, randi.org "From alternative medicine, aliens, and psychics to the farthest shores of science and beyond, Robert Carroll presents a fascinating look at some of humanity''s most strange and wonderful ideas. Refreshing and witty, both believers and unbelievers will find this compendium complete and captivating. Buy this book and feed your head!" -Clifford Pickover, author of The Stars of Heaven and Dreaming the Future "A refreshing compendium of clear thinking, a welcome and potent antidote to the reams of books on the supernatural and pseudoscientific." -John Allen Paulos, author of Innumeracy and A Mathematician Reads the Newspaper "This book covers an amazing range of topics and can protect many people from being scammed." -Stephen Barrett, M.D., quackwatch.org Featuring close to 400 definitions, arguments, and essays on topics ranging from acupuncture to zombies, The Skeptic''s Dictionary is a lively, commonsense trove of detailed information on all things supernatural, occult, paranormal, and pseudoscientific. It covers such categories as alternative medicine; cryptozoology; extraterrestrials and UFOs; frauds and hoaxes; junk science; logic and perception; New Age energy; and the psychic. For the open-minded seeker, the soft or hardened skeptic, and the believing doubter, this book offers a remarkable range of information that puts to the test the best arguments of true believers.', 'en', 2003, 446, 'http://books.google.com/books/content?id=h7m6NAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3138', 'accepted', 'Robert Carroll', 'Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 17 FROM public.book WHERE isbn13 = '9780471272427' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('676be746-fc28-5579-b660-c3420566887f', '9780471292456', 'Color Drawing', 'f6NCc9SYu0IC', 'Stunningly updated, totally redesigned, practical, and ready to use This new edition of Michael Doyle''s classic Color Drawing is the ultimate up-to-date resource for professionals and students who need to develop and communicate design ideas with clear, attractive, impressive color drawings. In an easy to use, step-by-step approach, this comprehensive guide presents a total system of color design drawing that encompasses approaches to sketch communication as well as more finished presentation drawing. Totally redesigned to provide quick, easy access to key information, this Second Edition covers the basics of color phenomena, media, techniques, and approaches to illustrating materials necessary to communicate design ideas. With nearly 400 new color illustrations, it contains a new section on color and design principles for creating more sophisticated presentation drawings and offers innovative ideas for the reproduction and distribution of finished drawings. Color Drawing features: * A complete body of illustrated instruction that demonstrates the development of design ideas from initial concept through presentation drawing * Finely honed explanations of each technique and process * Faster and easier ways to create design drawings * Methods for combining hand-drawn and computer-generated drawing techniques This remarkably versatile volume is both an illuminating textbook and a completely reliable self-teaching tool, as well as a handy quick reference. It is an excellent guide for students at any level and an unparalleled resource for design professionals.', 'en', 1999, 360, 'http://books.google.com/books/content?id=f6NCc9SYu0IC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
