INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('71194860-9139-57bb-a041-c50ee869221d', '9780471648796', 'The Science of Sherlock Holmes', '6h29NAEACAAJ', 'Praise for The Science of Sherlock Holmes "Holmes is, first, a great detective, but he has also proven to be a great scientist, whether dabbling with poisons, tobacco ash, or tire marks. Wagner explores this fascinating aspect of his career by showing how his investigations were grounded in the cutting-edge science of his day, especially the emerging field of forensics.... Utterly compelling." —Otto Penzler, member of the Baker Street Irregulars and proprietor of The Mysterious Bookshop "E. J. Wagner demonstrates that without the work of Sherlock Holmes and his contemporaries, the CSI teams would be twiddling their collective thumbs. Her accounts of Victorian crimes make Watson''s tales pale! Highly recommended for students of the Master Detective." —Leslie S. Klinger, Editor, The New Annotated Sherlock Holmes "In this thrilling book, E. J. Wagner has combined her considerable strengths in three disciplines to produce a work as compelling and blood-curdling as the best commercial fiction. This is CSI in foggy old London Town. Chilling, grim fun." —John Westermann, author of Exit Wounds and Sweet Deal "I am recommending this delightful work to all of my fellow forensic scientists.... Bravo, Ms. Wagner!" —John Houde, author of Crime Lab: A Guide for Nonscientists "A fabulously interesting read. The book traces the birth of the forensic sciences to the ingenuity of Sherlock Holmes. A wonderful blend of history, mystery, and whodunit." —Andre Moenssens, Douglas Stripp Professor of Law Emeritus, University of Missouri at Kansas City, and coauthor of Scientific Evidence in Civil and Criminal Cases', 'en', 2006, 244, 'http://books.google.com/books/content?id=6h29NAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
