INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a032df98-5db5-5d60-bc62-8e8160818636', '9780471678786', 'All the Shah''s Men', 'LRuRQAAACAAJ', 'This is the first full-length account of the CIA''s coup d''etat in Iran in 1953—a covert operation whose consequences are still with us today. Written by a noted New York Times journalist, this book is based on documents about the coup (including some lengthy internal CIA reports) that have now been declassified. Stephen Kinzer''s compelling narrative is at once a vital piece of history, a cautionary tale, and a real-life espionage thriller.', 'en', 2004, 272, 'http://books.google.com/books/content?id=LRuRQAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
