INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('017fe795-f7d7-5ff7-aa64-9e4e745b720a', '9780471705222', 'Information Technology for Management', '8V9GAAAAYAAJ', 'IT''s Going Global... From Shanghai to San Francisco, IT is playing an increasingly vital role in helping organizations gain the competitive advantage around the globe. That''s why the Fifth Edition of "Information Technology for Management" offers a global perspective on how IT is transforming business. In this comprehensive, up-to-date Fifth Edition, Efraim Turban, Ephraim McLean, James Wetherbe, and new coauthor Dorothy Leidner present late-breaking developments in the field, as well as a new chapter on Global Interorganizational Systems. IT''s About Transformation: The text focuses on how organizations operate and compete in the digital economy, and how IT can assist this transformation. The new edition also features increased strategy coverage. IT''s Current: The Fifth Edition introduces new research, current examples and case studies, and updated reference materials. IT''s Managerial: The text''s strong managerial orientation makes IT relevant and interesting to business students. Technological topics are conveniently covered in six technology guides at the end of the text. IT''s Wireless: A special chapter covers innovations and opportunities in mobile computing and the wireless revolution. IT''s Hands-on: Students solve realistic IT problems when they are "hired" as interns at The Wireless Cafe, a simulated high-tech restaurant in Shanghai.', 'en', 2006, 724, 'http://books.google.com/books/content?id=8V9GAAAAYAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3145', 'accepted', 'Efraim Turban', 'Computers', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 20 FROM public.book WHERE isbn13 = '9780471705222' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6f311fea-d165-5bd5-a983-ffc3b4ee3b1f', '9780471714392', 'Limbo', 'rGvDDwAAQBAJ', 'In Limbo, award-winning journalist Alfred Lubrano identifies and describes an overlooked cultural phenomenon: the internal conflict within individuals raised in blue-collar homes, now living white-collar lives. These people often find that the values of the working class are not sufficient guidance to navigate the white-collar world, where unspoken rules reflect primarily upper-class values. Torn between the world they were raised in and the life they aspire too, they hover between worlds, not quite accepted in either. Himself the son of a Brooklyn bricklayer, Lubrano informs his account with personal experience and interviews with other professionals living in limbo. For millions of Americans, these stories will serve as familiar reminders of the struggles of achieving the American Dream.', 'en', 2005, 248, 'http://books.google.com/books/content?id=rGvDDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3146', 'accepted', 'Alfred Lubrano', 'Social Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 15 FROM public.book WHERE isbn13 = '9780471714392' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9e3432cd-e193-53b4-8a6d-245584334446', '9780471738848', 'Data Structures and Algorithms in Java', 'XXCKQgAACAAJ', 'Fundamental data structures in a consistent object-oriented framework Now revised to reflect the innovations of Java 5.0, Goodrich and Tamassia''s Fourth Edition of Data Structures and Algorithms in Java continues to offer accessible coverage of fundamental data structures, using a consistent object-oriented framework. The authors provide intuition, description, and analysis of fundamental data structures and algorithms. Numerous illustrations, web-based animations, and simplified mathematical analyses justify important analytical concepts. Key Features of the Fourth Edition: * Updates to Java 5.0 include new sections on generics and other Java 5.0 features, and revised code fragments, examples, and case studies to conform to Java 5.0. * Hundreds of exercises, including many that are new to this edition, promote creativity and help readers learn how to think like programmers and reinforce important concepts. * New case studies illustrate topics such as web browsers, board games, and encryption. * A new early chapter covers Arrays, Linked Lists, and Recursion. * A new final chapter on Memory covers memory management and external memory data structures and algorithms. * Java code examples are used extensively, with source code provided on the website. * Online animations and effective in-text art illustrate data structures and algorithms in a clear, visual manner. Access additional resources on the web www.wiley.com/college/goodrich): * Java source code for all examples in the book * Animations * Library (net.datastructures) of Java constructs used in the book * Problems database and search engine * Student hints to all exercises in the book * Instructor resources, including solutions to selected exercises * Lecture slides', 'en', 2005, 720, 'http://books.google.com/books/content?id=XXCKQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
