INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cb053283-553a-5e72-89bf-eddaa5bfe78f', '9780471743675', 'The Warren Buffett Way', '54idNZfWyl0C', 'A decade has passed since the book that introduced Warren Buffett to the world - The Warren Buffett Way by Robert Hagstrom - first appeared. Since then, Buffett has solidified his reputation as the greatest investor of all time - quietly amassing a multibillion-dollar fortune, despite the wild fluctuation of the markets. Although Buffett has claimed time and again that what he does is not beyond anybody else''s competence, some people still do not understand how this value investing legend can consistently perform so well. That''s where Robert Hagstrom and the Second Edition of The Warren Buffett Way come in. This completely revised and updated look at the Oracle of Omaha encompasses Buffett''s numerous investments and accomplishments over the past ten years, as well as the timeless and highly successful investment strategies and techniques he has always used to come out a market winner.', 'en', 2010, 245, 'http://books.google.com/books/content?id=54idNZfWyl0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
