INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('864e3c06-81c2-57fe-b673-336906b7a7fe', '9780471773863', 'Baby Signing For Dummies', '75MH8vwXyBwC', 'Packed with more than 100 clearly illustrated signs, along with baby-specific signing techniques, and stories and games to make learning fun, this easy-to-use guide helps to strengthen the parent-child bond, includes tips on incorporating baby signs into the daycare setting, and even helps babies develop an IQ advantage over infants who do not sign.', 'en', 2006, 257, 'http://books.google.com/books/content?id=75MH8vwXyBwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
