INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6b585de0-2ddf-5962-845d-dfbc8594b78d', '9780471780939', 'Power of An Hour', 'idPQNAEACAAJ', 'Praise for The Power of an Hour "The master at getting what you want from others now tells us how to get what we want from ourselves! This is really a great book, and I recommend it highly-for you, for your team, and for your children." -Bob Burg, author, Endless Referrals "If you want to make predictable, systematic change in your life or your business, buy this book. Each chapter is a stand-alone system that results in powerful change . . . fast." -David Hancock, The Entrepreneurial Publisher, CEO, Morgan James Publishing "Dave''s methods helped me take my business from $0 to $10 million in sales.If you''re a creative business owner who wants total focus and massive success, run, don''t walk, and get this book!" -Stephanie Frank, author, The Accidental Millionaire "The Power of an Hour is a mighty powerful way to sort out your financesby first sorting out yourself!" -Mark Joyner, #1 bestselling author, The Irresistible Offer "The disease of the twenty-first century, no matter who you are or what you do,is Time Deficit Disorder. Dave Lakhani offers a brilliant solution in this book.Get it and take the cure-you''ll be surprised how much better you feel!" -David Garfinkel, author, Customers on Demand', 'en', 2006, 205, 'http://books.google.com/books/content?id=idPQNAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
