INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ace28c10-dcda-5692-aad7-9bb6fde45987', '9780471782476', 'The Science of Stephen King', 'ns5kJxqNcUUC', 'Introduction: Where Science and Fiction Intersect -- From Proms to Cells: The Psychic World of Stephen King -- Carrie -- Firestarter -- The Dead Zone -- Hearts in Atlantis Cell -- The Green Mile -- On the Highway with Stephen King -- "Trucks"--They Came From Outer Space -- Dreamcatcher -- The Tommyknockers -- The Fourth Horseman -- The Stand -- Up the Dimensions with Stephen King -- The Dark Tower I: The Gunslinger -- Insomnia -- Traveling in Time with Stephen King - The Langoliers -- Parallel Worlds -- "The Mists" -- From a Buick 8 -- The Dark Tower -- The Tailisman -- Longevity an Genetic Research - The Golden Years -- Evil, Obsession, and Fear -- The Tommyknockers -- Carrie -- The Talisman -- It -- The Stand -- Danse Macabre -- The Shining -- Misery -- "Night Surf."', 'en', 2007, 272, 'http://books.google.com/books/content?id=ns5kJxqNcUUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
