INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7a59940a-743f-5990-824a-782d50d0a1a9', '9780486218434', 'Technical Manual and Dictionary of Classical Ballet', 'gaMIILrrKgkC', 'Gail Grant''s "Technical Manual" has long been one of the most popular and effective ballet reference guides. Completely revised and updated, this third edition is virtually a new work and should be owned by every student, teacher, choreographer, and ballet enthusiast - even those who purchased the second edition. Extensive revision, explansion and the inclusion of more than 300 new terms have added immeasurably the value of this concise, definitive manual.', 'en', 1982, 176, 'http://books.google.com/books/content?id=gaMIILrrKgkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
