INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('178666e5-640e-53a7-8923-455cad7b6d0a', '9780486249445', 'Mozart''s Don Giovanni', '665b5zp1la0C', 'Don Giovanni has been called the greatest opera ever composed, an almost perfect work. Along with "Aida," "La Boheme," and "Carmen," Mozart''s masterpiece is one of the most often performed operas. The work is so admired that when the Italian composer Gioacchino Rossini was asked which of his own operas he liked best, Rossini unhesitatingly replied, ""Don Giovanni."" This Dover edition contains the standard Italian libretto of "Don Giovanni," side by side with a complete new English translation. Convenient and portable, it also includes an informative Introduction, a complete List of Characters, and an easy-to-follow Plot Summary. All repeats are given in full, so you can follow the text as it is sung, without losing your place. With this inexpensive, handy guide, opera lovers can appreciate every word of Mozart''s brilliant comic drama in the original Italian or in modern English. An ideal companion for reading along with a recording, a broadcast, or at the performance itself, this superb volume is a first-rate aid to enjoyment of one of the world''s most celebrated operas. "', 'en', 1985, 128, 'http://books.google.com/books/content?id=665b5zp1la0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3164', 'accepted', 'Wolfgang Amadeus Mozart; Ellen H. Bleiler; Lorenzo Da Ponte', 'Music', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 6 FROM public.book WHERE isbn13 = '9780486249445' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0b661e71-bbf4-5e16-bd99-8c45edf5640e', '9780486256078', '1001 Illuminated Initial Letters', 'hocfAwAAQBAJ', 'The illuminated letters in this volume by the great Victorian designer Owen Jones, many taken from an illustrated edition of "The Psalms of David, " represent popular alphabet motifs that have been copied by artists and designers for more than a century throughout Europe and North America. Each page of this versatile archive contains approximately 40 magnificently embellished individual letters of the alphabet. (There''s also an additional page of equally attractive Arabic and Roman numerals.) Foliated and filigreed designs--ranging from small to large, simple to spectacular--display the meticulous craftsmanship and attention to detail that have become synonymous with Victorian design. Commercial artists, graphic designers, and craftspeople will find this elegant and versatile treasury of copyright-free decorative letters an excellent and indispensable sourcebook for graphic projects calling for old-fashioned Victorian charm.Republication of the edition published by Day & Son, London, and Ludwig Denicke, Leipzig, 1864.', 'en', 1988, 32, 'http://books.google.com/books/content?id=hocfAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
