INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('764fe935-53aa-579c-bff5-93b4b3a6b8ab', '9780486256429', 'Galapagos', 'wFKrGA5-lRoC', 'More than 100 splendid illustrations enhance this fascinating firsthand account of a 1923 expedition to survey the wildlife of the Galápagos Islands. Beebe, a renowned biologist and explorer, combines literary skill with careful research to produce an exceptionally readable book. "High romance, exact science, fascinating history, wild adventure." — Nation.', 'en', 1988, 528, 'http://books.google.com/books/content?id=wFKrGA5-lRoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
