INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7103de53-323c-5618-9ca1-8891723cf42e', '9780486270609', 'Young Goodman Brown, and Other Short Stories', '-AwmDwAAQBAJ', 'Choice collection of short fiction by one of the masters of the genre. In addition to the title story, this volume includes "The Birthmark," "Rappaccini’s Daughter," "Roger Malvin’s Burial," "The Artist of the Beautiful," "Dr. Heidegger’s Experiment" and "My Kinsman, Major Molineux." Tales deal with scientific experiment, witchcraft, revenge, more.', 'en', 1992, 111, 'http://books.google.com/books/content?id=-AwmDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
