INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c6165e9f-6828-51ae-b0c7-4716bddad94a', '9780486275505', 'The Road Not Taken, and Other Poems', 'CGLcDAAAQBAJ', '"Two roads diverged in a wood, and I I took the one less traveled by, And that has made all the difference. "These deceptively simple lines from the title poem of this collection suggest Robert Frost at his most representative: the language is simple, clear and colloquial, yet dense with meaning and wider significance. Drawing upon everyday incidents, common situations and rural imagery, Frost fashioned poetry of great lyrical beauty and potent symbolism. Now a selection of the best of his early works is available in this volume, originally published in 1916 under the title Mountain Interval. Included are many moving and expressive poems: "An Old Man''s Winter Night," "In the Home Stretch," "Meeting and Passing," "Putting In the Seed," "A Time to Talk," "The Hill Wife," "The Exposed Nest," "The Sound of Trees" and more. All are reprinted here complete and unabridged. Includes a selection from the Common Core State Standards Initiative: "The Road Not Taken."', 'en', 1993, 49, 'http://books.google.com/books/content?id=CGLcDAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
