INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e60e4417-6b38-5d1d-81af-628a42963f0f', '9780486292427', 'The Oresteia Trilogy', 'Bg0mDwAAQBAJ', 'Classic trilogy by great tragedian deals with the bloody history of the House of Atreus. Grand in style, rich in diction and dramatic dialogue, the plays embody Aeschylus'' concerns with the destiny and fate of both individuals and the state, all played out under the watchful eye of the gods.', 'en', 1996, 151, 'http://books.google.com/books/content?id=Bg0mDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
