INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('72894cca-c7e4-5c8e-b3ff-6cce9eecdb3c', '9780486421247', 'Life is a Dream', 'i0fc64syC7IC', 'A king is suspicious of his son''s role in an impending revolution. Considered one of the outstanding Spanish dramas of all-time, this 17th-century allegory explores the mysteries of human destiny, the illusory nature of existence, and the struggle between predestination and free will. Includes an excellent new English translation, with an informative introduction and footnotes.', 'en', 2002, 96, 'http://books.google.com/books/content?id=i0fc64syC7IC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
