INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a4fb194b-a9a9-5a73-a58b-daa3f9775906', '9780486426754', 'The Pilgrim''s Progress', 'uy6ue_mi_AwC', 'One of the most powerful dramas of Christian faith ever written, this captivating allegory of man''s religious journey in search of salvation follows the pilgrim as he travels an obstacle-filled road to the Celestial City. Along the way, he is confronted by monsters and spiritual terrors, among them Worldly Wiseman, Giant Despair, and the demons of the Valley of the Shadow of Death. An enormously influential 17th-century classic, universally known for its simplicity, vigor, and beauty of language.', 'en', 2003, 324, 'http://books.google.com/books/content?id=uy6ue_mi_AwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
