INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d2345f2c-6b65-593d-b5ce-eb59d681c4f4', '9780486432137', 'The Idiot', 'ctkoAwAAQBAJ', 'Splendid novel of mid-19th-century Russian manners, morals, and philosophy focuses on a nobleman whose gentle, child-like nature has earned him the nickname of "the idiot."', 'en', 2003, 540, 'http://books.google.com/books/content?id=ctkoAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
