INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('98b4e095-a7ea-5d25-a6e0-36549f13ef58', '9780486432540', 'Critique of Pure Reason', 'U75JGtgpDt0C', 'In his monumental Critique of Pure Reason, German philosopher Immanuel Kant (1724–1804) argues that human knowledge is limited by the capacity for perception. He attempts a logical designation of two varieties of knowledge: a posteriori, the knowledge acquired through experience; and a priori, knowledge not derived through experience. Kant maintains that the most practical forms of human knowledge employ the a priori judgments that are possible only when the mind determines the conditions of its own experience. This accurate translation by J. M. Meiklejohn offers a simple and direct rendering of Kant''s work that is suitable for readers at all levels.', 'en', 2003, 480, 'http://books.google.com/books/content?id=U75JGtgpDt0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3206', 'accepted', 'Immanuel Kant; J. M. D. Meiklejohn', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 11 FROM public.book WHERE isbn13 = '9780486432540' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('477250be-86f4-5e77-8e60-d0e47aa05825', '9780486434148', 'Discourse on the Origin of Inequality', 'UNooAwAAQBAJ', 'A strikingly original inquiry into politics and human nature, the Discourse presents a theoretical view of people in a pre-social condition and the ensuing effects of civilization. The author develops a theory of evolution that prefigures Darwinism and encompasses aspects of ethics, sociology, and epistemology. One of the most influential works of the Enlightenment.', 'en', 2004, 73, 'http://books.google.com/books/content?id=UNooAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
