INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0fd8ce1e-a38b-5acd-ac29-0f5de104f88d', '9780486437552', 'The Philosophy of History', 'calVsYdns1EC', 'Hegel wrote this classic as an introduction to a series of lectures on the "philosophy of history." With this work, he created the history of philosophy as a scientific study. He reveals philosophical theory as neither an accident nor an artificial construct, but as an exemplar of its age.', 'en', 2004, 480, 'http://books.google.com/books/content?id=calVsYdns1EC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
