INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8489ce04-b060-51fc-b6ff-8391342ef312', '9780486442174', 'The Sword of Welleran', 'K2ZcyQEACAAJ', 'Twelve tales by a master of the English language take readers on flights of fancy and make-believe. Enhanced by the author''s power of expression and 10 ethereal illustrations by S. H. Simes, the collection includes such inventive tales as "The Highwayman," "In the Twilight," "The Ghosts," "The Lord of Cities," and the title piece.', 'en', 2005, 112, 'http://books.google.com/books/content?id=K2ZcyQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
