INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4160704b-3361-56f2-8ab4-fdb31256d5b2', '9780486442891', 'Autobiography of Thomas Jefferson', 'j8PbwAEACAAJ', 'During his remarkable lifetime, Thomas Jefferson (1743–1826) served his country in many capacities — among them, as President of the United States. But ultimately, this great and talented man — an accomplished architect, naturalist, and linguist — wished to be remembered primarily as the author of the Declaration of Independence. In his autobiography, begun in 1821 at the age of 77, Jefferson presents a detailed account of his young life and the period during which he wrote the Declaration. A first draft of the document is included in this edition, as are his comments on the Articles of Confederation, his experiences as a wartime governor of Virginia, minister to France and observations during the French Revolution. Also featured here are rich remembrances and insights as Jefferson recalls his roles as Washington''s secretary of state and vice president under John Adams, and his life in retirement. Fascinating as a trove of firsthand recollections by a pillar of American democracy, this highly recommended volume will be welcomed by students, scholars, and any reader interested in American history.', 'en', 2005, 112, 'http://books.google.com/books/content?id=j8PbwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3212', 'accepted', 'Thomas Jefferson', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 10 FROM public.book WHERE isbn13 = '9780486442891' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c662f5c4-61e9-55c7-901e-8a155f1c6616', '9780486445632', 'Philosophy of Right', 'KMAsAwAAQBAJ', 'In this 1821 classic, Hegel applies his most important concept — the dialectics — to law, rights, morality, the family, economics, and the state. The philosopher defines universal right as the synthesis between the thesis of an individual acting in accordance with the law and the occasional conflict of an antithetical desire to follow private convictions.', 'en', 2005, 272, 'http://books.google.com/books/content?id=KMAsAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
