INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('99788559-1027-54b3-ab70-f046b3690242', '9780486447780', 'Intimate Journals', 'mr2E7yolzp0C', 'Collection of the notorious poet''s essays transcends the squalor of his financial ruin and the torture of physical decline to offer compelling thoughts on his world, society, and philosophy.', 'en', 2006, 128, 'http://books.google.com/books/content?id=mr2E7yolzp0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
