INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('edc27c61-f5c0-52fe-8c23-d2fe59ba7187', '9780486451381', 'The Kingdom of God Is Within You', 'UTw1AwAAQBAJ', 'Banned in Russia, Tolstoy''s The Kingdom of God Is Within You was deemed a threat to church and state. The culmination of a lifetime''s thought, it espouses a commitment to Jesus''s message of turning the other cheek. In a bold and original manner, Tolstoy shows his readers clearly why they must reject violence of any sort—even that sanctioned by the state or the church—and urges them to look within themselves to find the answers to questions of morality. In 1894, one of the first English translations of this book found its way into the hands of a young Gandhi. Inspired by its message of nonresistance to evil, the Mahatma declared it a source of "independent thinking, profound morality, and truthfulness." Much of this work''s emotional and moral appeal lies in its emphasis on fair treatment of the poor and working class. Its view of Christianity, not as a mystic religion but as a workable philosophy originating from the words of a remarkable teacher, extends its appeal to secular and religious readers alike.', 'en', 2006, 352, 'http://books.google.com/books/content?id=UTw1AwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
