INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('906740fd-010f-589e-aba3-749d80dbfa5f', '9780486451404', 'Quicksand', 'LDw1AwAAQBAJ', 'Hypocrisy and prejudice compel a principled racially mixed teacher to desert a steady job and a socially prominent fiancâe.', 'en', 2006, 125, 'http://books.google.com/books/content?id=LDw1AwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
