INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9ef514f2-c06d-53ba-abdb-74c8467d78b5', '9780500050965', 'The Seventy Wonders of the Ancient World', 'BHaQQgAACAAJ', 'A survey of the world''s great ancient wonders from the Great Temple of the Aztecs, to the Nazca lines of Peru, including answers to how the architecture was created and for what purpose.', 'en', 1999, 304, 'http://books.google.com/books/content?id=BHaQQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
