INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e36fe286-eb06-5af3-b30e-c525a5a9f924', '9780517082454', 'Complete Poems', 'C4Y-KgAACAAJ', 'Edgar Allan Poe (1809-1849) is internationally renowned as a pioneering master of the macabre. He is regarded as one of the world''s great short story writers as well as a great lyric poet, and is credited with inventing the detective story and the modern gothic horror tale. He has been an important influence on many major American and European writers including William Faulkner, Fyodor Dostoevsky, Baudelaire, H.P. Lovecraft, and William Butler Yeats, among many others. Poe''s poetry, which is collected in this volume, is more personal than his prose. The themes of love, death, and despair which recur throughout reflect the anguish he suffered in his own troubled life. "Annabel Lee" is a haunting lament to his young wife, Virginia, who died of tuberculosis. "The Bells" is an eerie and melancholy meditation which recreates with brilliant musical language the hypnotic, funereal aura of ringing bells. "The Raven" is a comic tour de force in which the protagonist turns his strange visitor into a symbol of his own sorrow and loss. Poe''s best poems remain some of the most popular and technically accomplished in the English language. This book features a deluxe cover, ribbon marker, top stain, and decorative endpaper with a name plate.', 'en', 1992, 128, 'http://books.google.com/books/content?id=C4Y-KgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
