INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('deb9a1e4-32aa-5026-9950-0c045bdb7592', '9780517884546', 'The Orion Mystery', 'XLSerhdFKVsC', 'Drawing on more than a decade of research, this eye-opening account of one of the great mysteries of the ancient world links the construction of the pyramids and Egyptian religion to precise astronomical study. TV tie-in. 20,000 first printing.', 'en', 1994, 352, 'http://books.google.com/books/content?id=XLSerhdFKVsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
