INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('036cf325-2a3b-5468-b919-61fd69780e9d', '9780520024274', 'The Pound Era', '06EwDwAAQBAJ', '"It is notoriously difficult to recognize degrees of pre-eminence among one''s near-contemporaries. We talk now of the age of Donne, a label that would have seemed bizarre to Ben Johnson. Will The Pound Era seem an appropriate designation, 50 or 100 years hence, for the epoch we think of as ''modern''? Mr. Kenner''s brilliantly written book establishes an excellent case for supposing the answer to be ''Yes.''"—The Economist "Mr. Kenner''s study...is not so much a book as a library, or better, a new kind of book in which biography, history, and the analysis of literature are so harmoniously articulated that every page has a narrative sense....The Pound Era is a book to be read and reread and studied. For the student of modern letters it is a treasure, for the general reader it is one of the most interesting books he will ever pick up in a lifetime of reading."—National Review', 'en', 1973, 624, 'http://books.google.com/books/content?id=06EwDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
