INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4a4f4594-2468-507f-bda1-a5e8074f57b5', '9780520072381', 'The Responsibility of Forms', 'XTLuwAEACAAJ', 'These late essays of Roland Barthes''s are concerned with the visible and the audible, and here the preoccupations are particularly intense and rewarding, in part because Barthes was himself, by predilection, an artist and a musician, and in part because he was of two minds about the very possibility of attaching to art and to music a written text, a criticism.', 'en', 1991, 320, 'http://books.google.com/books/content?id=XTLuwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
