INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bee9bf14-b406-5c8d-95a8-fe7df05dd3b7', '9780520204959', 'Geisha', 'LGTVNSYrKucC', '00 In this classic best-seller, Liza Dalby, the only non-Japanese ever to have trained as a geisha, offers an insider''s look at the exclusive world of female companions to the Japanese male elite. Her new preface considers the geisha today as a vestige of tradition as Japan heads into the 21st century. In this classic best-seller, Liza Dalby, the only non-Japanese ever to have trained as a geisha, offers an insider''s look at the exclusive world of female companions to the Japanese male elite. Her new preface considers the geisha today as a vestige of tradition as Japan heads into the 21st century.', 'en', 1998, 367, 'http://books.google.com/books/content?id=LGTVNSYrKucC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
