INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('eb670f03-c452-57be-86a6-92e044b14175', '9780520206397', 'Balanchine', 'fztBS9mc-Q8C', 'Written with wit, insight, and candor, Balanchine is a book that will delight lovers of biography as well as those with a special interest in dance. For this edition the author has added a thoughtful yet dramatic account of the working out of Balanchine''s legacy, from the making of his controversial will to the present day. The author explores the intriguing legal, financial, and institutional subplots that unfolded after the death of the greatest choreographer of the century, but the central plot of his epilogue is the aesthetic issue: In the absence of their creator, can the ballets retain their wondrous vitality? Taper illuminates the fascinating transmission of Balanchine''s masterworks from one generation to another, an unprecented legacy in the history of ballet, that most evanescent of the arts.', 'en', 1996, 413, 'http://books.google.com/books/content?id=fztBS9mc-Q8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
