INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6c6dd656-0cdd-50a2-b5dd-867b17c3ecb8', '9780520213685', 'Haiti, History, and the Gods', '-aQwDwAAQBAJ', '"By viewing Revolutionary-era Haiti through the lenses of gender and sexuality, Joan Dayan breathes life into an important slice of history."—Karen McCarthy Brown, author of Mama Lola', 'en', 1998, 362, 'http://books.google.com/books/content?id=-aQwDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
