INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c6899234-1ea4-5645-bcad-8d5523110792', '9780520215108', 'Masculinity and Male Codes of Honor in Modern France', 'BbgwDwAAQBAJ', 'In this study of upper-class masculinity from the end of the ancien régime in 1789 to the end of World War I, Robert Nye argues that manhood, masculinity, and male sexuality is, like femininity, a cultural construct, comprising a strict set of heroic ideals and codes of honor which few men have been able to realize in practice. In doing so, Nye destabilizes and historicizes the male body, and incorporates gender into the brand of cultural history inaugurated by Norbert Elias in the 1930s.', 'en', 1998, 316, 'http://books.google.com/books/content?id=BbgwDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
