INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4b353391-4f78-5d18-b34a-420766885703', '9780520231511', 'Undertaker of the Mind', '_zYTngEACAAJ', '"Undertaker of the Mind is the most splendid piece of original research for many a year on the early history of British psychiatry. Brilliantly exploiting hitherto unused documentation, Andrews and Scull bring the once murky world of the eighteenth- century mad-doctor to life, and dispel many deeply embedded myths in the process. Absolutely essential reading!"--Roy Porter, author of The Creation of the Modern World "This is a wonderfully well-written work... The authors reconstruct, in rich and convincing detail, the dilemmas faced by Monro, his patients, their families, and the broader culture when confronted with psychological distress."--Joel Braslow, author of Mental Ills and Bodily Cures "A telling reconstruction of the ideas and practice of probably the most famous psychiatrist in eighteenth-century Britain.... The analyses of Monro''s more famous cases, Cruden, Ferrers, etc., are both stimulating and entertaining."--William Bynum, author of Science and the Practice of Medicine in the Nineteenth Century', 'en', 2001, 386, 'http://books.google.com/books/content?id=_zYTngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
