INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e1142ce6-ae63-5937-8518-cead545d8922', '9780520239326', 'The Whole World Is Watching', 'VbkwDwAAQBAJ', 'This study examines the way news organizations, as the category implies, "organize" the news world, both for practitioners - reporters, editors and managers - and for the consumers - readers, viewers and perhaps even more important, decision-makers.', 'en', 2003, 352, 'http://books.google.com/books/content?id=VbkwDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
