INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('29541754-f23b-5efd-92c7-8811de63865f', '9780520242609', 'The Poems of Exile', 'cyEI5755N2UC', '"This is no small achievement. For the language-lover the translation provides elegant, flowing English verse, for the classicist it conveys close approximation to the Latin meaning coupled with a sense of the movement and rhythmic variety of Ovid''s language"--Geraldine Herbert-Brown, editor of Ovid''s Fasti: Historical Readings at its Bimillennium "This book fills a gap. There is no similar annotated English translation of Ovid''s exile poetry. Thoroughly grounded in Ovidian scholarship, Green''s introduction and notes are helpful and informative. The translation is accurate, idiomatic, and lively, closely imitating the Latin elegiac couplet and capturing Ovid''s changing moods."--Karl Galinsky, author of Ovid''s Metamorphoses: An Introduction to the Basic Aspects', 'en', 1994, 451, 'http://books.google.com/books/content?id=cyEI5755N2UC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
