INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5b0f8e9c-69de-5a95-b76f-56d3c1feebe7', '9780520244955', 'Giovanni and Lusanna', '47EwDwAAQBAJ', '"Set against the grindstone of social class, this story of Lusanna versus Giovanni, gleaned from the archives of Renaissance Florence, throws a floodlight on relations between the sexes. Gene Brucker''s wonderful account has remarkable resonance."—Lauro Martines, author of April Blood “In the years since it first appeared, Gene Brucker''s Giovanni and Lusanna has attracted a large and loyal readership. There is no better introduction to the complex realities of life (and love) in Florence during the Renaissance.”—William J. Connell, Professor of History and La Motta Chair in Italian Studies, Seton Hall University PRAISE FOR THE PREVIOUS EDITION: "At its core, this splendid study is about stubborn love and the forms of law, and the impossibility of each to accommodate the ultimate claims of the other."—New York Times Book Review', 'en', 2005, 160, 'http://books.google.com/books/content?id=47EwDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
