INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7a5658c8-6414-55d9-9bd2-4754b61a5b21', '9780521009379', 'The Ethics and Politics of Asylum', 'fdyhjrmpqx0C', 'Over the last two decades, asylum has become a highly charged political issue across developed countries. This book draws upon political and ethical theory and an examination of the experiences of the United States, Germany, the United Kingdom and Australia to consider how to respond to the challenges of asylum. In addition to explaining why asylum has emerged as such a key political issue, it provides a compelling account of how states could move towards implenting morally defensible responses to refugees.', 'en', 2004, 287, 'http://books.google.com/books/content?id=fdyhjrmpqx0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
