INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4875c89e-8e07-512d-ba00-9c82902de74c', '9780521286916', 'Moral Luck', 'wMGW2Ehldp8C', 'A new volume of philosophical essays by Bernard Williams. The book is a successor to Problems of the Self, but whereas that volume dealt mainly with questions of personal identity, Moral Luck centres on questions of moral philosophy and the theory of rational action. That whole area has of course been strikingly reinvigorated over the last deacde, and philosophers have both broadened and deepened their concerns in a way that now makes much earlier moral and political philosophy look sterile and trivial. Moral Luck contains a number of essays that have contributed influentially to this development. Among the recurring themes are the moral and philosophical limitations of utilitarianism, the notion of integrity, relativism, and problems of moral conflict and rational choice. The work presented here is marked by a high degree of imagination and acuity, and also conveys a strong sense of psychological reality. The volume will be a stimulating source of ideas and arguments for all philosophers and a wide range of other readers.', 'en', 1981, 188, 'http://books.google.com/books/content?id=wMGW2Ehldp8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3310', 'accepted', 'Bernard Williams', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 16 FROM public.book WHERE isbn13 = '9780521286916' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('298060f5-24cd-5fa3-8c4a-f471452e0f14', '9780521288842', 'Evolution and the Theory of Games', 'Nag2IhmPS3gC', 'In this 1982 book, the theory of games, first developed to analyse economic behaviour, is modified so that it can be applied to evolving populations. John Maynard Smith''s concept of an evolutionarily stable strategy is relevant whenever the best thing for an animal or plant to do depends on what others are doing. The theory leads to testable predictions about the evolution of behaviour, of sex and genetic systems, and of growth and life history patterns. This book contains a full account of the theory, and of the data relevant to it. The account is aimed at senior undergraduate and graduate students, teachers and research workers in animal behaviour, population genetics and evolutionary biology. The book will also be of interest to mathematicians and game theorists; the mathematics has been largely confined to appendixes so that the main text may be easily followed by biologists.', 'en', 1982, 234, 'http://books.google.com/books/content?id=Nag2IhmPS3gC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
