INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f66b4a7b-6709-51b3-8f1e-3207c2d529c4', '9780521315791', 'Reading Greek Tragedy', 'zmQKcdh4i-oC', 'This book is an advanced critical introduction to Greek tragedy. It is written specifically for the reader who does not know Greek and who may be unfamiliar with the context of the Athenian drama festival but who nevertheless wants to appreciate the plays in all their complexity. Simon Goldhill aims to combine the best contemporary scholarly criticism in classics with a wide knowledge of modern literary studies in other fields. He discusses the masterpieces of Athenian drama in the light of contemporary critical controversies in such a way as to enable the student or scholar not only to understand and appreciate the texts of the most commonly read plays, but also to evaluate and utilize the range of approaches to the problems of ancient drama.', 'en', 1986, 302, 'http://books.google.com/books/content?id=zmQKcdh4i-oC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
