INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0761b778-9ae2-5f3f-bb31-ce43d7671ec6', '9780521348355', 'Cicero: On Duties', 'PuONLmVUW4QC', 'De Officiis (On Duties) is Cicero''s last theoretical work and contains his analysis, in a Greek theoretical framework, of the political and ethical values of the Roman governing class in the late Republic. It has often been treated merely as a key to the Greek philosophical works that Cicero used, but this volume aims to render De Officiis, which had a profound impact upon subsequent political thinkers, more intelligible by explaining its relation to its own time and place. All the standard series features are present, including a wholly new translation, a concise introduction by a leading scholar, select bibliography, chronology, notes on vocabulary and brief biographies of the most prominent individuals mentioned in the text.', 'en', 1991, 241, 'http://books.google.com/books/content?id=PuONLmVUW4QC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3318', 'accepted', 'Cicero; Marcus Tullius Cicero; Quintus Tullius Cicero', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 6 FROM public.book WHERE isbn13 = '9780521348355' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8bd1bbff-962a-5215-8834-a0822578ba2b', '9780521348881', 'Hegel: Elements of the Philosophy of Right', 'FVJRWWD-3fAC', 'This book is a translation of a classic work of modern social and political thought. Elements of the Philosophy of Right, Hegel''s last major published work, is an attempt to systematize ethical theory, natural right, the philosophy of law, political theory, and the sociology of the modern state into the framework of Hegel''s philosophy of history. Hegel''s work has been interpreted in radically different ways, influencing many political movements from far right to far left, and is widely perceived as central to the communitarian tradition in modern ethical, social, and political thought. This edition includes extensive editorial material informing the reader of the historical background of Hegel''s text, and explaining his allusions to Roman law and other sources, making use of lecture materials which have only recently become available. The new translation is literal, readable, and consistent, and will be informative and scholarly enough to serve the needs of students and specialists alike.', 'en', 1991, 569, 'http://books.google.com/books/content?id=FVJRWWD-3fAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
