INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7b5f8116-c1df-5e05-b24b-e15f7713b251', '9780521398336', 'The Return of Grand Theory in the Human Sciences', 'y5gk3pINr-YC', 'Publisher description: This is a volume of new essays introducing the most influential developments in social and political theory over the last thirty years. In that period empiricism and the positivist ideal of the unification of science have been undermined and transformed by the impact of different, frequently Continental, traditions of thought. The introduction charts these charges and each of the contributors provides a brief and lucid account of the thought of one major figure or school which have helped to bring about these changes. Those discussed include Althusser, Derrida, Foucault, Gadamer, Habermas, Kuhn, Levi-Strauss, Rawls and the Annales historians. Each essay has suggestions for further reading and a useful general bibliography is provided at the end of the volume.', 'en', 1990, 224, 'http://books.google.com/books/content?id=y5gk3pINr-YC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
