INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d98b1445-9d16-5379-a9b6-9bb106e97dbf', '9780521437776', 'The Myth of the Magus', 'nJSXnBd78FYC', 'After identifying its anthropological origins in ancient rituals performed by a shaman or wizard, this text traces the development of the Magus through pre-Christian religious and mystic philosophers, medieval sorcerers and alchemists and the 18th and 19th century occult revival.', 'en', 1993, 320, 'http://books.google.com/books/content?id=nJSXnBd78FYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
