INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1db06468-dcf6-51a4-b811-90642c060354', '9780521476768', 'The Cambridge Companion to Plotinus', '84sQxAEACAAJ', 'Plotinus is the greatest philosopher in the 700 year period between Aristotle and Augustine. He thought of himself as a disciple of Plato, but in his efforts to defend Platonism against Aristotelians, Stoics, and others, he actually produced a reinvigorated version of Platonism that later came to be known as "Neoplatonism". In this volume, sixteen leading scholars introduce and explain the many facets of Plotinus'' complex system. They place Plotinus in the history of ancient philosophy while showing how he was a founder of medieval philosophy.', 'en', 1996, 480, 'http://books.google.com/books/content?id=84sQxAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3328', 'accepted', 'Lloyd Phillip Gerson; Lloyd P. Gerson', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 17 FROM public.book WHERE isbn13 = '9780521476768' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('160b9e7a-163a-5a39-8b0c-8579b0e1fbce', '9780521479349', 'Foucault''s Virginity', '8B4AutVAp4sC', 'The sexy, witty and often bizarre novels, poetry and dialogues of the first centuries of this era (works such as Longus'' Daphnis and Chloe, Achilles Tatius'' Leukippe and Cleitophon and Plutarch''s Amatorius) were being composed at the same time as fundamental ideas about the body, gender and sexuality were being set in place with the rise of Christianity and the Church to dominate the pagan world. Modern writers on the history of sexuality have largely ignored this literature in favour of prose treatises, philosophy and Christian homilies. Simon Goldhill, writing with the same wit and verve as the ancient writers with whom he engages, sets out to put these texts back into the history of sexuality. The result is a dazzling celebration of sex and sexuality in the Greek literature of the first centuries CE.', 'en', 1995, 212, 'http://books.google.com/books/content?id=8B4AutVAp4sC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
