INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a20f9224-6bbd-5454-af6b-5503baf784ba', '9780521484008', 'Aristotle: The Politics and the Constitution of Athens', 'zk7KoZp_S38C', 'This new collection of Aristotle''s political writings provides the student with all the necessary materials for a full understanding of his work as a political scientist. In addition to a revised and extended introduction, this expanded Cambridge Texts edition contains an extensive guide to further reading and an index of names with biographical notes. Presentation of The Politics and The Constitution of Athens in a single volume will make this the most attractive and convenient student edition of these seminal works currently available.', 'en', 1996, 327, 'http://books.google.com/books/content?id=zk7KoZp_S38C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
