INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('19b6f119-ebb7-50e2-b092-512115910576', '9780521750844', 'Jungle Love Level 5', 'vIbr41ZwJVsC', 'The kiss was just amazing. I knew instantly that Ian was the one for me. ''You''re lOvely,'' he said. ''Absolutely lovely. But I can''t do this. Not until I''ve broken things off with Caroline. It just wouldn''t be fair.'' On holiday in the Caribbean, Lisa and Jennifer are both attracted to Ian. And Ian likes both of them. But what about his girlfriend, Caroline? And then there''s Pete.', 'en', 2002, 95, 'http://books.google.com/books/content?id=vIbr41ZwJVsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
