INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e6231a3c-d7ca-5a1b-ba88-dd40210fcd23', '9780521805223', 'Charles Taylor', 'WXm2NF-TXrgC', 'Charles Taylor is a distinctive figures in contemporary philosophy. In a time of increasing specialization Taylor contributes to areas of philosophical conversation across a wide spectrum of ideas including moral theory, theories of subjectivity, political theory, epistemology, hermeneutics, philosophy of mind, philosophy of language and aesthetics. His most recent writings have seen him branching into the study of religion. Written by a team of international authorities, this collection will be read primarily by students and professionals in philosophy, political science, religious studies, but will appeal to a broad swathe of professionals across the humanities and social sciences.', 'en', 2004, 220, 'http://books.google.com/books/content?id=WXm2NF-TXrgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
