INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cc7460e0-c9ab-5148-b750-5f2fd7b88fd4', '9780521834346', 'Myths of the Underworld Journey', 'yEswngEACAAJ', 'Plato, Aristophanes, and the creators of the "Orphic" gold tablets employ the traditional tale of a journey to the realm of the dead to redefine, within the mythic narrative, the boundaries of their societies. Rather than being the relics of a faded ritual tradition or the products of Orphic influence, these myths can only reveal their meanings through this detailed analysis of the specific ways in which each author makes use of the tradition.', 'en', 2004, 276, 'http://books.google.com/books/content?id=yEswngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
