INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('58414ca2-fa33-5a97-bf69-bd992b4cc7ec', '9780525947264', 'The Grits (Girls Raised in the South) Guide to Life', 'AXM-Kg6VFh0C', 'A tribute to southern American women features true stories, recipes, humorous anecdotes, wisdom, and advice on such topics as eating watermelon in a sundress, tending a magnolia tree, and drinking like a lady. 50,000 first printing.', 'en', 2003, 249, 'http://books.google.com/books/content?id=AXM-Kg6VFh0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
