INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0ae6375b-e57c-56fb-85d4-8d5556f91f4f', '9780525948926', 'Atlas Shrugged', 'SZN8PwAACAAJ', 'Government leaders seeking control over all business become increasingly frantic as major industrial companies are being thrown into chaos following the sudden disappearance of their leaders.', 'en', 2005, 1176, 'http://books.google.com/books/content?id=SZN8PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
