INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fc50f3c3-e0fe-5f2f-8cdb-2ef7e5e948e6', '9780525950127', 'The Woods', 'o7fYPzejSowC', 'Grieving over the murder of his sister twenty years earlier and raising his six-year-old daughter alone after losing his wife to cancer, county prosecutor Paul Copeland is inadvertently tied to a murder investigation that he believes may be related to his sister''s case, a discovery that threatens to reveal long-buried family secrets. 400,000 first printing.', 'en', 2007, 404, 'http://books.google.com/books/content?id=o7fYPzejSowC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3359', 'accepted', 'Harlan Coben', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 2 FROM public.book WHERE isbn13 = '9780525950127' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('80dadbf4-a583-5cc3-b28d-f4da2d52355c', '9780529123459', 'The Last Eyewitness', '60AJ6ko1jP0C', 'A beautiful retelling of the last week in the life of Jesus Christ (from John 13-21), including 17 dramatic illustrations by Rob Pepper. This unique work captures the urgency of the last living disciple telling his students about the most significant event in history. It includes first person commentary told in John''s voice with comments from Matthew, Mark, and Luke. The compelling story gives the reader the sense of being around a campfire with first century believers, hearing the story directly from John. So come into the story, smell the mixture of the salty air and billows of smoke floating from the bonfire and hear the Last Eyewitness.', 'en', 2006, 144, 'http://books.google.com/books/content?id=60AJ6ko1jP0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3360', 'accepted', 'Chris Seay; David B. Capes; Brian McLaren', 'Bibles', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 19 FROM public.book WHERE isbn13 = '9780529123459' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('17a9158c-870c-5dcf-b61f-c6b725b65f15', '9780534491826', 'Data Structures and Algorithms in C++', 'W7Lsrs09KDYC', 'Using the C++ programming language, author Adam Drozdek highlights three important aspects of data structures and algorithms. First, the book places special emphasis on the connection between data structures and their algorithms, including an analysis of the algorithms'' complexity. Second, the book presents data structures in the context of object-oriented program design, stressing the principle of information hiding in its treatment of encapsulation and decomposition. Finally, the book closely examines data structure implementation. Overall, this practical and theoretical book prepares students with a solid foundation in data structures for future courses and work in design implementation, testing, or maintenance of virtually any software system. Important Notice: Media content referenced within the product description or the product text may not be available in the ebook version.', 'en', 2004, 758, 'http://books.google.com/books/content?id=W7Lsrs09KDYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3361', 'accepted', 'Adam Drozdek', 'Computers', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 8 FROM public.book WHERE isbn13 = '9780534491826' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fbf69d1f-ae57-582c-bead-058b60678245', '9780534613037', 'Slaughterhouse Blues', 'RQ4pAQAAMAAJ', 'SLAUGHTERHOUSE BLUES: THE MEAT AND POULTRY INDUSTRY IN NORTH AMERICA draws on more than 15 years of research by the authors, a cultural anthropologist and a social geographer, to present a detailed look at the meat and poultry industry in the United States and Canada. Following chapters on today''s beef, poultry, and pork industries, SLAUGHTERHOUSE BLUES examines industry impacts on workers and on the communities that host its plants. The book details the authors'' efforts to help communities plan for and mitigate the negative consequences of meat and poultry plants as well as community opposition to confined animal feeding operations. The book concludes by exploring alternatives to North America''s model of industrialized meat production.', 'en', 2004, 172, 'http://books.google.com/books/content?id=RQ4pAQAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
