INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6933d3d0-e5e6-5d86-97f2-40667e8e1bd0', '9780552135399', 'A Prayer for Owen Meany', 'BrzEQgAACAAJ', '''If you care about something you have to protect it. If you''re lucky enough to find a way of life you love, you have to find the courage to live it.'' Eleven-year-old Owen Meany, playing in a Little League baseball game in Gravesend, New Hampshire, hits a foul ball and kills his best friend''s mother. Owen doesn''t believe in accidents; he believes he is God''s instrument. What happens to Owen after that 1953 foul ball is both extraordinary and terrifying.', 'en', 1990, 637, 'http://books.google.com/books/content?id=BrzEQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
