INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e6933f92-bb33-5daf-84e3-91d9168e884e', '9780552146739', 'Nanny Ogg''s Cookbook', '-PEtxFc3u6YC', 'Recipes from Nanny Ogg, the beloved witch from the Discworld series, also includes her thoughts on life, death, and etiquette, as well as other useful information. Original.', 'en', 2001, 176, 'http://books.google.com/books/content?id=-PEtxFc3u6YC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
