INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5e28e9b3-8a5c-5564-a3ce-b33dd9e79730', '9780552146784', 'The Swords of Night and Day', '_lAbcRWV2N4C', 'A thousand years after they fell in battle, two heroes - Druss and Skilgannon - are revered throughout the war-torn lands of the Dernai, where men and women live in abject fear of the dark sorceress known as the Eternal...But what if the soul of one suc', 'en', 2005, 640, 'http://books.google.com/books/content?id=_lAbcRWV2N4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3368', 'accepted', 'David Gemmell', 'Drenai (Imaginary place)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 15 FROM public.book WHERE isbn13 = '9780552146784' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0505b852-5727-5d5b-93b6-11bd134be9f9', '9780552148085', 'Queen of Sorcery', 'h-KhPwAACAAJ', 'A magnificent epic set against a history of seven thousand years of the struggles of Gods and Kings and men - of strange lands and events - of fate and a prophecy that must be fulfilled! THE BELGARIAD Legends told of how the evil God Torak had coveted the power of the Orb of Aldur, until defeated in a final battle. But prophecy spoke of a time when he would awake and again seek dominance over all the world. Now the Orb had been stolen by a priest of Torak, and that time was at hand. The master Sorcerer Belgarath and his daughter Polgara the arch-sorceress were on the trail of the Orb, seeking to regain it before the final disaster. And with them went Garion, a simple farm boy only months before, but now in the focus of the struggle. He had never believed in sorcery and wanted no part of it. Yet with every league they travelled, the power grew in him, forcing him to acts of wizardry he could not accept. THUS CONTINUES BOOK TWO OF THE BELGARIAD', 'en', 2000, 447, 'http://books.google.com/books/content?id=h-KhPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3369', 'accepted', 'David Eddings', 'Fantasy fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 5 FROM public.book WHERE isbn13 = '9780552148085' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('31d08e4d-850e-5aea-9e62-9e5fc64a464d', '9780552148108', 'Castle of Wizardry', 'BNADx9wti8gC', 'A magnificent epic set against a history of seven thousand years of the struggles of Gods and Kings and men - of strange lands and events - of fate and a prophecy that must be fulfilled! THE BELGARIAD It had all begun with the theft of the Orb that had so long protected the West from the evil God Torak. Before that, Garion had been a simple farm boy. Afterward, he discovered that his aunt was really the Sorceress Polgara and his grandfather was Belgarath, the Eternal Man. Then, on the long quest to recover the Orb, Garion found to his dismay that he, too, was a sorcerer. Now, at last, the Orb was regained and the quest was nearing its end. Of course, the questors still had to escape from this crumbling enemy fortress and flee across a desert filled with Murgo soldiers searching for them, while Grolim Hierarchs strove to destroy them with dark magic. Then, somehow, they must manage to be in Riva with the Orb by Erastide. After that, however, Garion was sure that his part in these great events would be finished. But the Prophecy still held future surprises for Garion - and for the little Princess Ce''Nedra! THUS CONTINUES BOOK FOUR OF THE BELGARIAD', 'en', 2000, 443, 'http://books.google.com/books/content?id=BNADx9wti8gC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3370', 'accepted', 'David Eddings', 'Fantasy fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 8 FROM public.book WHERE isbn13 = '9780552148108' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('76339687-3de4-5c03-8dbc-fa1597b76ab9', '9780552152167', 'Not Without My Daughter', 'a-pQSxS3SBgC', '"An Iranian doctor living in America with his American wife Betty and their child Mahtob wants to see his homeland again. He convinces his wife to take a short holiday there with him and Mahtob. Betty is reluctant, as Iran is not a pleasant place, especially if you are American and female. Upon arrival in Iran, it appears that her worst fears are realized: Moody declares that they will be living there from now on. Betty is determined to escape from Iran, but taking her daughter with her presents a larger problem."', 'en', 2004, 528, 'http://books.google.com/books/content?id=a-pQSxS3SBgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3371', 'accepted', 'Betty Mahmoody; William Hoffer', 'Americans', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 20 FROM public.book WHERE isbn13 = '9780552152167' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('04ef2a95-b55c-550e-9f09-01444ba11aa0', '9780552152945', 'Moving Pictures', '0IJtkM7d6Q0C', 'The tenth Discworld novel. The alchemists of the Discworld have discovered the magic of the silver screen. But what is the dark secret of Holy Wood hill? It''s up to Victor Tugelbend (''Can''t sing. Can''t dance. Can handle a sword a little.'') and Theda Withel (''I come from a little town you''ve probably never heard of'') to find out... Moving Pictures, the tenth Discworld novel is a gloriously funny saga set against the background of a world gone mad!', 'en', 2005, 396, 'http://books.google.com/books/content?id=0IJtkM7d6Q0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3372', 'accepted', 'Terry Pratchett', 'Discworld (Imaginary place)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 11 FROM public.book WHERE isbn13 = '9780552152945' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('63c77ecc-bf95-5239-8c19-1f54846e2cc1', '9780552152952', 'Reaper Man', 'Sosgq1p1ExsC', '''Death has to happen. Tha''ts what bein'' alive is all about. You''re alive, and then you''re dead. It can''t just stop happening.'' But it can. And it has. So what happens after death is now less of a philosophical question than a question of actual reality. On the disc, as here, they need Death. If Death doesn''t come for you, then what are you supposed to do in the meantime? You can''t have the undead wandering about like lost souls. There''s no telling what might happen, particularly when they discover that life really is only for the living...', 'en', 2005, 352, 'http://books.google.com/books/content?id=Sosgq1p1ExsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3373', 'accepted', 'Terry Pratchett', 'Discworld (Imaginary place)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 2 FROM public.book WHERE isbn13 = '9780552152952' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c999ea6d-c8ff-598d-bb3f-b7d3531f4a5d', '9780552153157', 'Lords and Ladies', 'n0e14vDaCEUC', '"The fairies are back - but this time they don''t just want your teeth... Granny Weatherwax and her tiny coven are up against real elves. It''s Midsummer''s Night. No time for dreaming... With full supporting cast of dwarfs, wizards, trolls, Morris dancers and one orang-utan.And lots of hey-nonny-nonny and blood all over the place.', 'en', 2005, 400, 'http://books.google.com/books/content?id=n0e14vDaCEUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3374', 'accepted', 'Terry Pratchett', 'Discworld (Imaginary place)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 6 FROM public.book WHERE isbn13 = '9780552153157' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e795d099-dc26-523b-941b-8b92c507f9b0', '9780552153577', 'Bravo Two Zero', 'qZzcEpGLeC4C', 'In January 1991, eight members of the SAS regiment embarked upon a top secret mission that was to infiltrate them deep behind enemy lines. Under the command of Sergeant Andy McNab, they were to sever the underground communication link between Baghdad and north-west Iraq, and to seek and destroy mobile Scud launchers. Their call sign: BRAVO TWO ZERO. Each man laden with 15 stone of equipment, they patrolled 20km across flat desert to reach their objective. Within days, their location was compromised. After a fierce firefight, they were forced to escape and evade on foot to the Syrian border. In the desperate days that followed, though stricken by hypothermia and other injuries, the patrol ''went ballistic''. Four men were captured. Three died. Only one escaped. For the survivors, however, the worst ordeals were to come. Delivered to Baghdad, they were tortured with a savagery for which not even their intensive SAS training had prepared them. BRAVO TWO ZERO is a breathtaking account of Special Forces soldiering, a chronicle of superhuman courage, endurance and dark humour in the face of overwhelming odds. Believed to be the most highly decorated patrol since the Boer War, BRAVO TWO ZERO is already part of SAS legend.', 'en', 2005, 416, 'http://books.google.com/books/content?id=qZzcEpGLeC4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3375', 'accepted', 'Andy McNab', 'Persian Gulf War, 1991', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 12 FROM public.book WHERE isbn13 = '9780552153577' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('05d84af8-f1fe-55c0-bd56-cfb722bcb8e3', '9780552154284', 'Hogfather', 'uiP3l1w4b1EC', 'Susan had never hung up a stocking . She''d never put a tooth under her pillow in the serious expectation that a dentally inclined fairy would turn up. It wasn''t that her parents didn''t believe in such things. They didn''t need to believe in them. They know they existed. They just wished they didn''t. There are those who believe and those who don''t. Through the ages, superstition has had its uses. Nowhere more so than in the Discworld where it''s helped to maintain the status quo. Anything that undermines superstition has to be viewed with some caution. There may be consequences, particularly on the last night of the year when the time is turning. When those consequences turn out to be the end of the world, you need to be prepared. You might even want more standing between you and oblivion than a mere slip of a girl - even if she has looked Death in the face on numerous occasions...', 'en', 2006, 432, 'http://books.google.com/books/content?id=uiP3l1w4b1EC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3376', 'accepted', 'Terry Pratchett', 'Christmas', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 5 FROM public.book WHERE isbn13 = '9780552154284' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a0cb716a-d003-5a11-bdee-2026b0d250c5', '9780552548229', 'Spindle''s End', 'W6Ev84nWWFoC', '"The princess has been missing since she was a baby. And Rosie, an ordinary girl, is growing up in an unremarkable little village far away from the royal city. nremarkable, that is, in a land where magic is so common that it settles over everything like dust. But a fairy curse is the kind of magic nobody wants, because it always comes true. And Rosie cannot stay ordinary for ever .... obin McKinley, winner of the Newbery Medal, reweaves a classic fantasy tale, sparkling with magic and adventure, some wonderful animals and birds and - of course - fairies, both good and bad."', 'en', 2003, 464, 'http://books.google.com/books/content?id=W6Ev84nWWFoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
