INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a56afe6b-af37-5bc6-9424-edc1da4b1ac2', '9780552554275', 'Vox', 'FcCBWM5jz1UC', '"High in the crumbling Palace of Statues, oily Vox Verlix - nominally the Most High Academe but no more than a prisoner in reality - is brewing a terrible plot to destroy the goblins and the shrykes at a stroke, leaving him free to ake over once again. Rook Barkwater, a young librarian knight, stumbles upon the truth when he is taken captive and forced to work for Rook. But can Rook foil Vox''s plan and save the lives of his librarian collegues? A dramatic and menacing new adventure, illustrated throughout with marvellously imaginative black and white illustrations. "', 'en', 2006, 400, 'http://books.google.com/books/content?id=FcCBWM5jz1UC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3379', 'accepted', 'Paul Stewart; Chris Riddell', 'Children''s stories', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 9 FROM public.book WHERE isbn13 = '9780552554275' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('aafc1f48-bdce-5a9a-a6e4-2a3cf99ed4ed', '9780552771238', 'Past Mortem', 'B1hgo7RElawC', 'With old friends like these, who needs enemies? It''s a question mild mannered detective Edward Newson is forced to ask himself when, in romantic desperation, he logs on to the Friends Reunited website in search of the girlfriends of his youth. Newson is not the only member of the Class of take back ''88 who has been raking over the ashes of the past. As his old class begins to reassemble in cyberspace, the years slip away and old feuds and passions burn hot once more. Meanwhile, back in the present, Newson''s life is no less complicated. He is secretly in love with Natasha, his lovely but very attached sergeant, and failing comprehensively to solve a series of baffling and peculiarly gruesome murders. A school reunion is planned and as history begins to repeat itself, the past crashes headlong into the present. Neither will ever be the same again. In Past Mortem, Ben Elton - previous winner of The Crime Writers'' Association Gold Dagger Award for Popcorn - delivers both a heart-stopping thriller and a killer comic romance.', 'en', 2005, 464, 'http://books.google.com/books/content?id=B1hgo7RElawC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
