INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e7474fc4-b3f5-5c1f-9b92-922fbc96eeff', '9780552771849', 'Popcorn', '1ryYk7Pvs1cC', '"Bruce shoots movies. Wayne and Scout shoot to kill. In a single night they find out the hard way what''s real and what''s not, who''s the hero and who''s the villain. The USA watches slack-jawed as Bruce and Wayne together resolve some serious questions. Does Bruce use erection cream? Does art imitate life or does life simply imitate bad art? And most of all, does sugar-pie really love his honeybun?"', 'en', 2003, 320, 'http://books.google.com/books/content?id=1ryYk7Pvs1cC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
