INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f4ced893-60f7-5212-94a3-d6ae42db9f70', '9780552992091', 'The Hotel New Hampshire', 'oaqajnOR1B8C', 'Quirky, bizarre, tragic, fiendishly funny, The Hotel New Hampshire is anything but a conventional family saga, though a family saga it certainly is. The Berry family are different. Love abounds - both healthy and incestuous. It is the overwhelming', 'en', 1986, 520, 'http://books.google.com/books/content?id=oaqajnOR1B8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
