INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9e36aeb9-720b-5bbb-91de-f29c101ea70f', '9780552998000', 'Blackberry Wine', 'a4VwRkslUcQC', 'Everyday Magic, He Called It. The Transformation Of Base Matter Into The Stuff Of Dreams. Layman S Alchemy.Jay Mackintosh Is Trapped By Memory In The Old Familiar Landscapes Of His Childhood, More Enticing Than The Present, And To Which He Longs To Return.A Bottle Of Home-Brewed Wine Left To Him By A Long-Vanished Friend Seems To Provide Both The Key To An Old Mystery And A Doorway Into Another World. As The Unusual Properties Of The Strange Brew Take Effect, Jay Escapes To A Derelict Farmhouse In The French Village Of Lansquenet, Where A Ghost From The Past Waits To Confront Him, And The Reclusive Marise Haunted, Lovely And Dangerous Hides A Terrible Secret Behind Her Closed Shutters. Between Them, A Mysterious Chemistry. Or Could It Be Magic?', 'en', 2001, 334, 'http://books.google.com/books/content?id=a4VwRkslUcQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3387', 'accepted', 'Joanne Harris', 'Brewing', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 4 FROM public.book WHERE isbn13 = '9780552998000' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('69debc95-3697-5000-9703-ef9fff738af0', '9780552998017', 'The Short History of a Prince', 'tlZoPwAACAAJ', 'Walter McCloud was constantly eclipsed by those around him - his beautiful, talented friends, his flamboyant relatives, his golden-boy brother, Daniel. He was always the outsider, never the star. But the summer of 1972 was a turning point in the life of fifteen-year-old Walter. It was the time when he realized that his great passion for dance would never be matched by his talent; the time when he discovered the funny agony of first love'' and the time when he watched his brother declining into a cruel, untimely death. It is only when, twenty-four years later, Walter returns to fight for the survival of his childhood Eden, his family''s lakeside summer home, that he finally discovers a way to reconcile himself to the past in a way that gives hope for the future.', 'en', 1999, 432, 'http://books.google.com/books/content?id=tlZoPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
