INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('520db6a4-ed31-5667-8c42-6152fd7010fe', '9780552998482', 'Chocolat. Joanne Harris', '1EF4xVC3e5MC', 'Try me...Test me...Taste me.When an exotic stranger, Vianne Rocher, arrives in the French village of Lansquenet and opens a chocolate boutique directly opposite the church, Father Reynaud identifies her as a serious danger to his flock especially as it', 'en', 2000, 320, 'http://books.google.com/books/content?id=1EF4xVC3e5MC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
