INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('931d0759-a3b3-53c4-91de-dab45a4fc57c', '9780552998765', 'Tales of the City', 'JigH-eXXd0YC', 'This internationally beloved modern classic, first published in 1978, will be reissued with a tie-in cover to coincide with the groundbreaking three-part PBS miniseries scheduled to air January 10, 11, and 12, 1994--a joint presentation of the prestigious American Playhouse and KQED San Francisco.', 'en', 2000, 272, 'http://books.google.com/books/content?id=JigH-eXXd0YC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
