INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3c3fdf10-d2d1-50a4-a330-51212f62809c', '9780552998772', 'More Tales of the City', 'BMakUdPrIU8C', 'The divinely human comedy that began with Tales of the Cityrolls recklessly along as Michael Tolliver pursues his favourite gynaecologist, Mona Ramsey uncovers her roots in a desert whorehouse, and Mary Ann Singleton finds love at sea with the amnesiac of her dreams.', 'en', 2000, 288, 'http://books.google.com/books/content?id=BMakUdPrIU8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
