INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('efa3459f-4fb7-54e9-90b6-5ff5267ddb7c', '9780552998789', 'Further Tales of the City', 'wF8Zs-YZ-80C', 'The residents of 28 Barbary Lane are back again in this racy, suspenseful and wildly romantic sequel to Tales of the Cityand More Tales of the City.DeDe Halcyon Day and Mary Ann Singleton track down a charismatic psychopath, Michael Tolliver looks for love, landlady Anna Madrigal imprisons an anchorwoman in her basement storeroom, and Armistead Maupin is in firm control.', 'en', 2000, 271, 'http://books.google.com/books/content?id=wF8Zs-YZ-80C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
