INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7bc36d57-30ea-58c5-81b9-e8e1b7a10767', '9780552998819', 'Sure of You', 'oFsQQuIgN-AC', '____________________ Soon to be a Netflix series starring Ellen Page and Laura Linney . . . ''San Francisco is fortunate in having a chronicler as witty and likeable as Armistead Maupin'' Independent __________________ In this, the sixth and final self-contained volume of Armistead Maupin''s epic chronicle of modern life, a fiercely ambitious TV talk show host finds she must choose between national stardom in New Yorkand a husband and child in San Francisco. Wistful and compassionate yet subversively funny, Sure of You is a triumphant finale to one of the most addictively entertainingseries of novels ever written.', 'en', 1991, 284, 'http://books.google.com/books/content?id=oFsQQuIgN-AC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
