INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ef5a6ac2-050f-5899-ad38-bcbcfdb409da', '9780552998833', 'Five Quarters of the Orange', 'IF63k02hpw4C', 'Beyond The Main Street Of Les Laveuses Runs The Loire, Smooth And Brown As A Sunning Snake - But Hiding A Deadly Undertow Beneath Its Moving Surface. This Is Where Framboise, A Secretive Widow Named After A Raspberry Liqueur, Plies Her Culinary Trade At The Crêperie - And Lets Memory Play Strange Games.Into This World Comes The Threat Of Revelation As Framboise S Nephew A Profiteering Parisian Attempts To Exploit The Growing Success Of The Country Recipes She Has Inherited From Her Mother, A Woman Remembered With Contempt By The Villagers Of Les Laveuses. As The Spilt Blood Of A Tragic Wartime Childhood Flows Again, Exposure Beckons For Framboise, The Widow With An Invented Past.Joanne Harris Has Looked Behind The Drawn Shutters Of Occupied France To Illuminate The Pain, Delight And Loss Of A Life Changed For Ever By The Uncertainties And Betrayals Of War.', 'en', 2002, 432, 'http://books.google.com/books/content?id=IF63k02hpw4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
