INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('98be3fe6-13aa-5287-8222-5decb73194d6', '9780553286397', 'Dragon Wing', 'nY1PnwEACAAJ', 'Wolf Haas'' Detective Brenner series has become wildly popular around the world for a reason: They''re timely, edgy stories told in a wry, quirky voice that''s often hilarious, and with a protagonist it''s hard not to love. In this episode, Brenner-forced out of the police force-tries to get away from detective work by taking a job as the personal chauffeur for two-year-old Helena, the daughter of a Munich construction giant and a Viennese abortion doctor. One day, while Brenner''s attention is turned to picking out a chocolate bar for Helena at a gas station, Helena gets snatched from the car. Abruptly out of a job, Brenner decides to investigate her disappearance on his own. With both parents in the public eye, there''s no scarcity of leads-the father''s latest development project has spurred public protest, and the mother''s clinic has been targeted by the zealous leader of an anti-abortion group. Brenner and God is told with a dark humor that leaves no character, including Brenner, unscathed. Haas tells the story of a fallible hero who can be indecisive and world-weary, baffled and disillusioned by what he finds, but who presses forward nonetheless out of a stubborn sense of decency-a two-year-old is kidnapped, so you find her, because that''s just what you do.', 'en', 1990, 430, 'http://books.google.com/books/content?id=nY1PnwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3449', 'accepted', 'Margaret Weis; Tracy Hickman', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 20 FROM public.book WHERE isbn13 = '9780553286397' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3663af74-36f7-5432-a9fe-fe4025638711', '9780553289510', 'Texas! Lucky', '0YH8bGuQWwIC', 'The first book in #1 New York Times bestselling author Sandra Brown''s beloved Texas! trilogy introduces readers to a close-knit family struggling to go on without its patriarch--and to a man in pursuit of an elusive woman who may hold his future in her hands. Charismatic and easy on the eyes, Lucky Tyler is a born rebel. His romantic conquests have earned him his nickname, while his temper gives him his reputation as the family hothead. One night, he gets in a fight over a woman in distress, followed by a night of passion neither of them will soon forget. But the lady in question has a knack for disappearing. When news breaks of a suspicious fire at Tyler Drilling, Lucky is the prime suspect. Now the mystery woman is more than just the object of his obsession. She''s his alibi. Devon Haines has tried her best to escape Lucky. Yet his bold pursuit and self-assurance are irresistible. In order to clear him of criminal charges, she must reveal her darkest secret; withholding her help could cost him everything he holds dear. Either way, she risks losing him forever.', 'en', 1991, 336, 'http://books.google.com/books/content?id=0YH8bGuQWwIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
