INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('10169807-1fde-55e3-8574-1f56a11e8404', '9780553293425', 'Pebble in the Sky', 'kKVoQuvNjBQC', 'One moment Joseph Schwartz is a happily retired tailor in 1949 Chicago. The next he''s a helpless stranger on Earth during the heyday of the first Galactic Empire. Earth, he soon learns, is a backwater, just a pebble in the sky, despised by all the other 200 million planets of the Empire because its people dare to claim it''s the original home of man. And Earth is poor, with great areas of radioactivity ruining much of its soil--so poor that everyone is sentenced to death at the age of sixty. Joseph Schwartz is sixty-two.', 'en', 1991, 308, 'http://books.google.com/books/content?id=kKVoQuvNjBQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
