INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('90bf2981-a265-51d1-b030-61fe56f1f832', '9780553345841', 'The Mind''s I', 'hz22QgAACAAJ', 'Brilliant, shattering, mind-jolting, "The Mind''s I" is a searching, probing nook--a cosmic journey of the mind--that goes deeply into the problem of self and self-consciousness as anything written in our time. From verbalizing chimpanzees to scientific speculations involving machines with souls, from the mesmerizing, maze-like fiction of Borges to the tantalizing, dreamlike fiction of Lem and Princess Ineffable, her circuits glowing read and gold, "The Mind''s I " opens the mind to the Black Box of fantasy, to the windfalls of reflection, to new dimensions of exciting possibilities.', 'en', 1982, 512, 'http://books.google.com/books/content?id=hz22QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
