INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5a5a0c12-5e35-5563-8f67-45bce132825e', '9780553803525', 'Social Intelligence', 'akQLxTM-5_8C', 'The best-selling author of Emotional Intelligence redefines the nature of human relationships and its impact on every aspect of daily life, bringing together the latest research in biology and brain science to reveal how one''s daily encounters shape the brain and affect the body, from daily mood to the immune response. 250,000 first printing.', 'en', 2006, 403, 'http://books.google.com/books/content?id=akQLxTM-5_8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
