INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('82f728a9-6f13-5fcd-a4c1-7ef7baa2bfd7', '9780553815023', 'The Sinner', 'TGvkcRz-zyEC', 'Within the walls of a cloistered convent, a scene of unspeakable carnage is discovered. On the snow lie two nuns, one dead, one critically injured - victims of a seemingly motiveless, brutally savage attack. Medical examiner Maura Isles'' autopsy of the murder victim yields a shocking surprise, but the case takes a disturbing twist. The body of another woman has been found. And someone has gone to a lot trouble to remove her face, hands and feet. As long buried secrets are revealed so Dr Isles and homicide detective Jane Rizzoli, find themselves part of an investigation that leads to an awful, dawning realisation of the killer''s identity...', 'en', 2004, 419, 'http://books.google.com/books/content?id=TGvkcRz-zyEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3570', 'accepted', 'Tess Gerritsen', 'Boston (Mass.)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 20 FROM public.book WHERE isbn13 = '9780553815023' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('af8219c9-c0a0-5e79-bc41-bee85c0b0a03', '9780553815399', 'The Mapmaker''s Wife', 'zTU_SuhfxpkC', '"In the early 18th Century a group of scientists set off from France to discover the unknown land of South America in a trip that nearly ended in disaster. Scaling the 16,000 foot Peruvian Andes, the scientists faced the depravations and dangers of the rain forest wild cats, insects and vampire bats and barely ended the mission. Some went mad, others succumbed to smallpox, one was stoned to death by locals and another was killed in a bullfight. The youngest, Jean Godin, fell in love and married beautiful local girl Isabel Grameson. earing the end of the expedition, Godin headed out alone to ensure the passage back was safe to take his family home to France. Disaster struck as Spain and Portugal closed their territorial borders to the French and Godin found himself stranded in French Guyana, unable to return to Isabel. hat followed was an extraordinary and heart rending 20 year separation that culminated with Isabel, determined to be reunited with the man she loved, setting out to find him. Thirty others set out with her and 10 horrific weeks later Isabel emerged from the Amazonian wilderness naked, alone and near starvation. The story of her journey and survival held 18th centur', 'en', 2005, 448, 'http://books.google.com/books/content?id=zTU_SuhfxpkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3571', 'accepted', 'Robert Whitaker', 'Amazon River Region', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 13 FROM public.book WHERE isbn13 = '9780553815399' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1e22e3bf-e90f-5529-9d2d-30eb9815d95b', '9780553816952', 'Princess', 'rXsp6RvUVoMC', '"In a land where Kings still rule, I am a Princess. You must know me only as Sultana, for I cannot reveal my true name for fear that harm will come to me and my family for what I am about to tell you. hink of a Saudi Arabian princess and what do you see? A woman glittering with jewels, living a life of unbelievable luxury. She has gold, palaces, swimming-pools, servants, designer dresses galore. But in reality she lives in a gilded cage. She has no freedom, no vote, no control over her own life, no value but as a bearer of sons. Hidden behind the veil, she is a prisoner, her jailers her father, her husband, her sons. Sultana'' is a member of the Saudi royal family, closely related to the King. For the sake of her daughters, she decided that it was time for a woman in her position to speak out about the reality of life for women in her country, whatever their rank. She tells of her own life, from her turbulent childhood to her arranged marriage - a happy one, until her husband decided to take a second wife - and of the lives of her sisters, her friends and her servants. In contrast to the affection and easy camaraderie amongst the women, she relates a history of appalling oppressio', 'en', 2004, 280, 'http://books.google.com/books/content?id=rXsp6RvUVoMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3572', 'accepted', 'Jean Sasson', 'English fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 17 FROM public.book WHERE isbn13 = '9780553816952' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9ec4b765-5353-511f-bffe-6ef00c95e157', '9780553817065', 'The Surgeon', '04p3495xOgYC', 'Today they will find her body. I know how it will happen. I can picture, quite vividly, the sequence of events that will lead to the discoverya In Boston, there''s a killer on the loose. A killer who targets lone women, who breaks into their apartments and performs terrifying ritualistic acts of torture on his victims before finishing them off. His surgical skills lead police to suspect he is a physician - a physician who, instead of saving lives, takes them. But as homicide detective Thomas Moore and his partner Jane Rizzoli begin their investigation, they make a startling discovery. Closely linked to these killings is Catherine Cordell, a beautiful medic with a mysterious past. Two years ago she was subjected to a horrifying rape and attempted murder but shot her attacker dead. Now she is being targeted by this new killer who seems to know all about her past, her work at the Pilgrim Medical Center, and where she lives. The man she believes she killed seems to be stalking her once again, and this time he knows exactly where to find hera', 'en', 2005, 416, 'http://books.google.com/books/content?id=04p3495xOgYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3573', 'accepted', 'Tess Gerritsen', 'Boston (Mass.)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 10 FROM public.book WHERE isbn13 = '9780553817065' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5683192f-4a7c-5232-ab31-fec01e8d7bca', '9780553817072', 'The Apprentice', 'Z5lY0mP_cdkC', 'The Surgeon has been locked up for a year but his chilling legacy still haunts the city, and especially Boston homicide detective Jane Rizzoli. But now a new killer is at work and Rizzoli senses something horrifyingly familiar about this murderer''s modus operandi. It''s when the FBI starts taking an interest in the investigation that Rizzoli begins to wonder just what makes this case so different, so dangerous that the Feds feel the need to get involved. But then the unthinkable happens: the Surgeon escapes. And suddenly there are two brilliant, twisted killers on the loose - master and apprentice, united in their hunt for the most challenging prey of all: the very woman who is hunting them.', 'en', 2005, 411, 'http://books.google.com/books/content?id=Z5lY0mP_cdkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
