INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2480b8f7-eb69-5471-bf34-adf9b503677e', '9780563486497', 'Doctor Who', 'BDsfK1WPuXgC', '"Doctor Who" fans might believe they know everything about the latest incarnation of BBC-TVUs SF series, but this book shows just how much they''ve missed. Pre-production drawings and paintings, countless behind-the-scenes candid shots, and comments and opinions from everyone involved provide the scoop on the how, why, who, and where of all things "Doctor Who."', 'en', 2006, 256, 'http://books.google.com/books/content?id=BDsfK1WPuXgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
