INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5810a9db-f6ee-5d3f-81d6-f06a0b6df15b', '9780563522751', 'Terry Jones'' Medieval Lives', '7Rh7J6xzjpAC', 'Was medieval England full of knights on horseback rescuing fainting damsels in distress? Were the Middle Ages mired in superstition and ignorance? Why does nobody ever mention King Louis the First and Last? And, of course, those key questions: which monks were forbidden the delights of donning underpants... and did outlaws never wear trousers? Terry Jones and Alan Ereira are your guides to this most misrepresented and misunderstood period, and they point you to things that will surprise and provoke. Did you know, for example, that medieval people didn''t think the world was flat? That was a total fabrication by an American journalist in the 19th century. Did you know that they didn''t burn witches in the Middle Ages? That was a refinement of the so-called Renaissance. In fact, medieval kings weren''t necessarily merciless tyrants, and peasants entertained at home using French pottery and fine wine. Terry Jones'' Medieval Lives reveals Medieval Britain as you have never seen it before - a vibrant society teeming with individuality, intrigue and innovation.', 'en', 2005, 240, 'http://books.google.com/books/content?id=7Rh7J6xzjpAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
