INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d8571a0f-d880-51f7-88d1-be2241b54196', '9780567044716', 'Colossians and Philemon', '61CEyAEACAAJ', 'For over one hundred years International Critical Commentaries have had a special place among works on the Bible. They bring together all the relevant aids to exegesis - linguistic, textual, archaeological, historical, literary, and theological - to help the reader understand the meaning of the books of the Old and New Testaments. The new commentaries continue this tradition. All new evidence now available is incorporated and new methods of study are applied. The authors are of the highest international standing. No attempt has been made to secure a uniform theological or critical approach to the biblical text: contributors have been invited for their scholarly distinction, not for their adherence to any one school of thought.', 'en', 2005, 512, 'http://books.google.com/books/content?id=61CEyAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
