INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f12d3a04-ccb7-589c-9342-2140d61a29d4', '9780571090242', 'Death of a Naturalist', 'et6dAgAAQBAJ', 'Death of a Naturalist marks the auspicious outset of an acclaimed master. As a first book of poems, it is remarkable for its accurate perceptions and its rich linguistic gifts.', 'en', 1969, 57, 'http://books.google.com/books/content?id=et6dAgAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
