INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bb831f2e-331a-57b7-a92a-169701e1ac0d', '9780571161157', 'The Complete Herbal Handbook for the Dog and Cat', 'BaPewAEACAAJ', 'Dog and cat owners are becoming increasingly concerned about the saftey of processed pet food and the possible side-effects of over-use of antibiotics and hormone treatments. This new edition, thoroughly revised and updated, covers Natural Rearing, herbal medicine and disease prevention.', 'en', 1991, 368, 'http://books.google.com/books/content?id=BaPewAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
