INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('daa42b36-2cf3-540e-9efc-9422ca23dd70', '9780571191031', 'Tales from Ovid', 'ViuRQgAACAAJ', 'When Michael Hofmann and James Lasdun''s ground-breaking anthology After Ovid (also Faber) was published in 1995, Hughes''s three contributions to the collective effort were nominated by most critics as outstanding. He had shown that rare translator''s gift for providing not just an accurate account of the original, but one so thoroughly imbued with his own qualities that it was as if Latin and English poet were somehow the same person. Tales from Ovid, which went on to win the Whitbread Prize for Poetry, continued the project of recreation with 24 passages, including the stories of Phaeton, Actaeon, Echo and Narcissus, Procne, Midas and Pyramus and Thisbe. In them, Hughes''s supreme narrative and poetic skills combine to produce a book that stands, alongside his Crow and Gaudete, as an inspired addition to the myth-making of our time.', 'en', 1997, 264, 'http://books.google.com/books/content?id=ViuRQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
