INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1ec1eb92-777d-5f94-99ff-37bef07b47bc', '9780571193783', 'The New Life', 'KOAJGwAACAAJ', 'A parable about love, literature and fanaticism. A young university student becomes obsessed with a magical book that delves into the dangerous natures of love and self. Abandoning his studies and his family, he goes with the beautiful Janan on a search for the meaning of the book''s darker secrets.', 'en', 1998, 296, 'http://books.google.com/books/content?id=KOAJGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
