INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('14eec4e8-3f72-5c32-90b5-be52edcb87be', '9780571200610', 'Garden State', 've3aPQAACAAJ', 'This first novel by the acclaimed author of Demonology and The Ice Storm traces a group of friends in Haledon, New Jersey, through one Spring in their rocky passage towards adulthood. The kids are out of school, trying to start a band, trying to find work; looking for something to do within the degraded terrain of their suburban hometown. Garden State starkly captures the lyricism of their lives in an intense and unforgettable story of friendship and betrayal.', 'en', 2002, 212, 'http://books.google.com/books/content?id=ve3aPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
