INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('231a1225-3546-5aa4-8f2d-16d76e574eca', '9780571202119', 'Girl, Interrupted', 'JnzDQgAACAAJ', '"Set in the changing world of the 1960s, the motion picture Girl Interrupted is the searing story of Susanna, a young woman who finds herself at a mental institution for troubled young women. Susanna''s ''short rest'', prescribed by a psychiatrist she had met just once, becomes a strange journey into Alice''s Wonderland, as she spends nearly a year both struggling and flirting with the thin line between ''normal'' and ''crazy''. Susanna soon realizes how hard it is to get out once she''s been committed, and ultimately she has to choose between the world of those who belong on the inside - such as the seductive and dangerous Lisa - and those who can engage with the reality of the outside world." "This volume includes storyboards and a discussion by the film''s director James Mangold about the film-making process by which this screenplay by James Mangold and Lisa Loomer and Anna Hamilton Phelan was transferred to the screen."--BOOK JACKET.Title Summary field provided by Blackwell North America, Inc. All Rights Reserved', 'en', 2000, 167, 'http://books.google.com/books/content?id=JnzDQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
