INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b4d7a603-c2a3-57ca-a4ee-ee3bb177e7ba', '9780571203123', 'My Century', '5MOAPwAACAAJ', 'Here, Gunter Grass writes of great events and seemingly trivial ones, of technical developments and scientific discoveries, of achievements in culture, sport, of megolamania, persecution and murder, war and disasters and of new beginnnings.', 'en', 2000, 248, 'http://books.google.com/books/content?id=5MOAPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
