INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7696b027-4cb4-5131-9d08-8e5a20b9173a', '9780571205219', 'The Journals of Sylvia Plath, 1950-1962', 'TDJgQgAACAAJ', '''Everything that passes before her eyes travels down from brain to pen with shattering clarity - 1950s New England, pre-co-ed Cambridge, pre-mass tourism Benidorm, where she and Hughes honeymooned, the birth of her son Nicholas in Devon in 1962. These and other passages are so graphic that you look up from the page surprised to find yourself back in the here and now . . . The struggle of self with self makes the Journals compelling and unique.'' John Carey, Sunday Times', 'en', 2001, 752, 'http://books.google.com/books/content?id=TDJgQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
