INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('87cbdbec-9991-5827-8020-4acd54a04136', '9780571206926', 'Laughable Loves', 'ZpupPwAACAAJ', 'Laughable loves is a collection of stories that first appeared in print in Prague before 1968, but then was banned. The seven stories are all concerned with love, or rather with the complex erotic games and strategems employed by women and especially men as they try to come to terms with needs ad impulses that can start a terrifying train of events. Sexual attraction is shown as a game that often turns sour, an experience that brings with it painful insisghts and releases uncertainty, panic, vanity and a constant need for reassurance.', 'en', 1999, 287, 'http://books.google.com/books/content?id=ZpupPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3605', 'accepted', 'Milan Kundera', 'Czech Republic', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 1 FROM public.book WHERE isbn13 = '9780571206926' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('54f4de90-3da9-51bc-bc36-9225b4767901', '9780571207084', 'Herzog on Herzog', 'kRzxwAEACAAJ', 'An invaluable set of career-length interviews with the German genius hailed by François Truffaut as "the most important film director alive" Most of what we''ve heard about Werner Herzog is untrue. The sheer number of false rumors and downright lies disseminated about the man and his films is truly astonishing. Yet Herzog''s body of work is one of the most important in postwar European cinema. His international breakthrough came in 1973 with Aguirre, The Wrath of God, in which Klaus Kinski played a crazed Conquistador. For The Enigma of Kaspar Hauser, Herzog cast in the lead a man who had spent most of his life institutionalized, and two years later he hypnotized his entire cast to make Heart of Glass. He rushed to an explosive volcanic Caribbean island to film La Soufrière, paid homage to F. W. Murnau in a terrifying remake of Nosferatu, and in 1982 dragged a boat over a mountain in the Amazon jungle for Fitzcarraldo. More recently, Herzog has made extraordinary "documentary" films such as Little Dieter Needs to Fly. His place in cinema history is assured, and Paul Cronin''s volume of dialogues provides a forum for Herzog''s fascinating views on the things, ideas, and people that have preoccupied him for so many years.', 'en', 2003, 352, 'http://books.google.com/books/content?id=kRzxwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
