INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7a4fd713-0bc3-55c6-a084-9661065628c4', '9780571207992', 'The Wars', 'AqnDQgAACAAJ', 'Robert Ross, a sensitive nineteen-year-old Canadian officer, went to war - the War to End All Wars. He found himself in the nightmare world of trench warfare; of mud and smoke, of chlorine gas and rotting corpses. In this world gone mad, Robert Ross performed a last desperate act to declare his commitment to life in the midst of death.The Wars is quite simply one of the best novels ever written about the First World War.', 'en', 2001, 218, 'http://books.google.com/books/content?id=AqnDQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3608', 'accepted', 'Timothy Findley', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 1 FROM public.book WHERE isbn13 = '9780571207992' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('15814c91-891b-567b-9d47-476d8932e0fb', '9780571209057', 'Famous Last Words', 'XwOkQgAACAAJ', 'In the final days of the Second World War, Hugh Selwyn Mauberley scrawls his desperate account on the walls and ceilings of his ice-cold prison high in the Austrian Alps. Officers of the liberating army discover his frozen, disfigured corpse and his astonishing testament - the sordid truth that he alone possessed. Fascinated but horrified, they learn of a dazzling array of characters caught up in a scandal and political corruption.Famous Last Words is part-thriller, part-horror story; it is also a meditation on history and the human soul and it is Findley''s fine achievement that he has combined these elements into a web that constantly surprises and astounds the reader.', 'en', 2001, 416, 'http://books.google.com/books/content?id=XwOkQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
