INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c03504e9-2011-5706-aea3-9fa2b5dd99f2', '9780571210916', 'Finders Keepers', 'SixqPwAACAAJ', 'In addition to his well-regarded verse, Nobel laureate poet Seamus Heaney has amassed a body of prose works over the last 30-plus years, previously published chiefly in three separate books. Finders Keepers: Selected Prose 1971-2001, offers a "best of" (of sorts) as Heaney sifts through previous writings and offers a variety of strong works, from memoir to lecture transcripts to literary criticism.', 'en', 2003, 432, 'http://books.google.com/books/content?id=SixqPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
