INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a971bb43-2fdd-5722-9aae-338a4aa0a29c', '9780571212927', 'A Beautiful Mind', '5ePBQgAACAAJ', 'A Beautiful Mind is Sylvia Nasar''s award-winning biography about the mystery of the human mind, the triumph over incredible adversity, and the healing power of love.At the age of thirty-one, John Nash, mathematical genius, suffered a devastating breakdown and was diagnosed with schizophrenia. Yet after decades of leading a ghost-like existence, he was to re-emerge to win a Nobel Prize and world acclaim. A Beautiful Mind has inspired the Oscar-winning film directed by Ron Howard and featuring Russell Crowe in the lead role of John Nash.', 'en', 2001, 461, 'http://books.google.com/books/content?id=5ePBQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
