INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fcbae638-e87c-5f8c-b31e-945e02499e58', '9780571214266', 'The Greek Islands', 'Jbh1PwAACAAJ', 'As every reader of Durrell knows, his writing is steeped in the living experience of the Mediterranean, and especially the islands of Greece. This captivating and highly unusual text, originally conceived as a picture book and now reset in paperback format, weaves together evocative descriptions, history and myth with Durrell''s personal reminiscences. No traveller to Greece or admirer of the genius of Durrell should miss it.', 'en', 2002, 332, 'http://books.google.com/books/content?id=Jbh1PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
