INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f8fb72ae-1f88-5c09-b242-b96015f9775b', '9780571217359', 'Finnegans Wake', '7ZSqPwAACAAJ', 'The complete text of James Joyce''s dream masterpiece, one of the great works of twentieth-century literature. This copyright edition incorporates Joyce''s own alterations and corrections to the first printing in 1939. ''Here words are not the polite contortions of twentieth-century printer''s ink. They are alive. They elbow their way on to the page, and glow and blaze and fade and disappear.'' Samuel Beckett', 'en', 1975, 628, 'http://books.google.com/books/content?id=7ZSqPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
