INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b6bb875e-fc0f-5112-b7df-ed4a15560a8e', '9780571219711', 'The Moth Diaries', '94hfPgAACAAJ', 'At an exclusive boarding school, a sixteen-year-old girl records her most intimate thoughts in a diary. The object of her growing obsession is her roommate, Lucy Blake, and Lucy''s friendship with her new and disturbing classmate. Ernessa is a mysterious, moody presence with pale skin and hypnotic eyes. Around her swirl dark rumours, suspicions and secrets as well as a series of ominous disasters. As fear spreads through the school, what is true and what is dreamed bleed together into a waking nightmare of gothic menace, fuelled by the anxieties, lusts and fears of adolescence. At the centre of the diary is the question that haunts all who read it: Is Ernessa really a vampire? Or has the narrator trapped herself in her own fevered imagination?', 'en', 2005, 245, 'http://books.google.com/books/content?id=94hfPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3618', 'accepted', 'Rachel Klein', 'Boarding schools', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 4 FROM public.book WHERE isbn13 = '9780571219711' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2ad6d9a9-4abc-53b1-8493-6de83782ea42', '9780571224388', 'The Unbearable Lightness of Being', 'OU1_PwAACAAJ', 'The Unbearable Lightness of Being is a story of irreconcilable love and infidelities in which Milan Kundera addresses himself to the nature of twentieth-century ''Being'', offering a wide range of brilliant and amusing philosophical speculations. First published in 1984, Kundera''s masterly novel encompasses the extremes of comedy and tragedy and was at once hailed by critics as a contemporary classic. This special hardback edition commemorates the twentieth anniversary of its first publication in English. ''There are novels that are tragic, or entertaining, and this one is both. There are very few that give a fresh perspective on existence, and force the reader to reassess his own life and attitudes.'' Sunday Times ''The Unbearable Lightness of Being is a work of the boldest mastery, originality and richness.'' Vanity Fair', 'en', 2004, 320, 'http://books.google.com/books/content?id=OU1_PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
