INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('23e5859b-e471-5d42-8a05-f7c44edb1ccc', '9780571225378', 'A Pale View of Hills', '_vtQPgAACAAJ', 'Etsuko, a middle-aged Japanese woman now living alone in England, dwells on the recent suicide of her elder daughter, Keiko. Despite the efforts of her surviving daughter to distract her thoughts, Etsuko finds herself recalling a particular summer in Nagasaki after the bomb fell.', 'en', 2005, 183, 'http://books.google.com/books/content?id=_vtQPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
