INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5a7375db-d391-50c4-9c50-fac1431a1e30', '9780571225552', 'The Avignon Quintet', 'SiLSGwAACAAJ', 'An omnibus edition of the five novels published by Durrell in a kaleidoscopic sequence between 1974 and 1985. The books are set mainly in Avignon and the ancient kingdom of Provence, though significant episodes in the quintet are set in the Egyptian desert, Venice, Paris, Vienna and Geneva.', 'en', 2004, 1376, 'http://books.google.com/books/content?id=SiLSGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
