INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5586dc12-b580-5872-80b1-61b900e5419e', '9780571226337', 'City of Glass', 'gRq-QgAACAAJ', '''It was a wrong number that started it . . .'' Chosen as one of the ''100 Most Important Comics of the Century'', Faber is proud to publish the graphic novel City of Glass for the first time in the UK. As Art Spiegelman explains in his new introduction, David Mazzucchelli and Paul Karasik ''created a strange doppelganger of the original book'' and ''a breakthrough work.'' Paul Auster''s Edgar Award-nominated masterwork has been astonishingly transformed into a new visual language.', 'en', 2005, 144, 'http://books.google.com/books/content?id=gRq-QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
