INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dfead5da-a3b4-52b6-955b-d5ef52a6667b', '9780575066892', 'Soul Music', 'Q16dPwAACAAJ', 'Other children got given xylophones. Susan just had to ask her grandfather to take his vest off. Yes. There¿s a Death in the family. It¿s hard to grow up normally when Grandfather rides a white horse and wields a scythe ¿ especially when you have to take over the family business and everyone mistakes you for the Tooth Fairy. And especially when you have to face the new and addictive music that has entered the Discworld. It¿s lawless. It changes people. It¿s called Music with Rocks In. It¿s got a beat and you can dance to it, but¿ It¿s alive. And it won¿t fade away.', 'en', 1999, 424, 'http://books.google.com/books/content?id=Q16dPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3627', 'accepted', 'Terry Pratchett', 'Discworld (Imaginary place)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 19 FROM public.book WHERE isbn13 = '9780575066892' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('59abd6a6-9c10-5e64-a538-842e3001f32c', '9780575068858', 'The Last Hero', '5MK2QgAACAAJ', 'He''s been a legend in his own lifetime. He can remember when a hero didn''t have to worry about fences and lawyers and civilisation, and when people didn''t tell you off for killing dragons. But he can''t always remember, these days, where he put his teeth . . . So now, with his ancient sword and his new walking stick and his old friends -- and they''re very old friends -- Cohen the Barbarian is going on one final quest. He''s going to climb the highest mountain in the Discworld and meet his gods. The last hero in the world is going to return what the first hero stole. With a vengeance. That''ll mean the end of the world, if no one stops him in time.', 'en', 2001, 160, 'http://books.google.com/books/content?id=5MK2QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3628', 'accepted', 'Terry Pratchett', 'Discworld (Imaginary place)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 13 FROM public.book WHERE isbn13 = '9780575068858' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('feb67b67-6e26-52ae-99c3-3c4d046b3caa', '9780575073357', 'The Man in the High Castle', '8HBAPgAACAAJ', 'It is 1962 and the Second World War has been over for seventeen years: people have now had a chance to adjust to the new order. But it¿s not been easy. The Mediterranean has been drained to make farmland, the population of Africa has virtually been wiped out and America has been divided between the Nazis and the Japanese. In the neutral buffer zone that divides the two superpowers lives the man in the high castle, the author of an underground bestseller, a work of fiction that offers an alternative theory of world history in which the Axis powers didn¿t win the war. The novel is a rallying cry for all those who dream of overthrowing the occupiers. But could it be more than that? Subtle, complex and beautifully characterized, The Man in the High Castle remains the finest alternative world novel ever written, and a work of profundity and significance.', 'en', 2001, 256, 'http://books.google.com/books/content?id=8HBAPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3629', 'accepted', 'Philip K. Dick', 'Alternative histories (Fiction)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 5 FROM public.book WHERE isbn13 = '9780575073357' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('570821f8-ccbc-5db8-a220-c6cc455e60de', '9780575073616', 'Worlds', 'FWH3wAEACAAJ', 'Towards the end of the twenty-first century 41 Worlds, small satellites with a total population of half a million, orbit the Earth, which has seen many changes, not least of which is a second revolution in America. Marianne O¿Hara, a brilliant political sciences student, is from New New York, a hollowed out asteroid and the largest of the Worlds, but is to spend a year on Earth as a postgraduate student. Because the political relationship between the Worlds and Earth is complex and voltatile, Marianne unwittingly finds herself caught up with a group of fanatics determined on a third revolution in America - even if such a revolution could lead to the destruction of the Earth...', 'en', 2002, 240, 'http://books.google.com/books/content?id=FWH3wAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
