INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4590ec24-19a4-5cc0-bd1b-27592c09b41f', '9780575075368', 'Dark Lord of Derkholm', 'ILwjHAAACAAJ', 'Can the Wizard Derk and his family of human and griffin children save the world from the depradations of the evil Mr Chesney?', 'en', 2003, 328, 'http://books.google.com/books/content?id=ILwjHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3631', 'accepted', 'Diana Wynne Jones', 'Fantasy fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 8 FROM public.book WHERE isbn13 = '9780575075368' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1c87a954-f5a8-53ae-8d7a-b6669c5cb205', '9780575075597', 'Replay', '9vmNPwAACAAJ', 'At forty-three Jeff Winston is tired of his low-paid, unrewarding job, tired of the long silences at the breakfast table with his wife, saddened by the thought of no children to comfort his old age. But he hopes for better things, for happiness, maybe tomorrow . . . But a sudden, fatal heart attack puts paid to that. Until Jeff wakes up in his eighteen-year-old body, all his memories of the next twenty-five years intact. If he applies those memories, he can be rich in this new chance at life and can become one of the most powerful men in America. Until he dies at forty-three and wakes up in his eighteen-year-old body again . . .', 'en', 2005, 272, 'http://books.google.com/books/content?id=9vmNPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3632', 'accepted', 'Ken Grimwood', 'Fantasy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 4 FROM public.book WHERE isbn13 = '9780575075597' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('346a5871-32a4-52e8-bbbb-db51baa1f3c4', '9780575075825', 'Grendel', 'yHfCHAAACAAJ', 'When Grendel is drawn up from the caves under the mere where he lives with his bloated, inarticulate hag of a mother into the fresh night air, it is to lay waste Hrothgar''s meadhall and heap destruction on the humans he finds there. What else can he do? For he is not like the men who busy themselves with God, love and beauty. He sees the infuriating human rage for order and recognises the meaninglessness of his own existence. GRENDEL is John Gardner''s masterpiece; it vividly reinvents the world of Beowulf. In Grendel himself, a creature of grotesque comedy, pain and disillusioned intelligence, Gardner has created the most unforgettable monster fantasy.', 'en', 2004, 144, 'http://books.google.com/books/content?id=yHfCHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3633', 'accepted', 'John Gardner', 'Beowulf', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 4 FROM public.book WHERE isbn13 = '9780575075825' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('58b80401-e340-5aee-8113-31964a22328e', '9780575076266', 'The Hyperion Omnibus', 'b2ReHAAACAAJ', 'The Hyperion books are credited with single-handedly reinventing and reinvigorating SF in the 1990s. A broad canvased, hugely imaginative and exciting SF epic, the books draw on the works of Keats and provide a uniquely intelligent and literary approach with cutting edge science, compelling characterisation and edge-of-your-seat excitement. The story is continued in ENDYMION and THE RISE OF ENDYMION, which Gollancz will also be publishing in an omnibus volume.', 'en', 2004, 779, 'http://books.google.com/books/content?id=b2ReHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
