INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fe947315-fd12-5bf6-b759-23a6a1d62feb', '9780575402904', 'Dark Visions', 'qpJoGwAACAAJ', 'Take three of the leading names in contemporary horror writing, commission one-third of a book''s worth of stories from each, and the result is DARK VISIONS. Stephen King leads off with three stories, including "Sneakers", about a very unusual haunting, and "Dedication", one of the most powerful and unsettling of all his works. Dan Simmons pays homage to Philip K Dick with "Metastasis", one of three highly accomplished stories. And George Martin rounds off the book with the brilliant werewolf novella, "The Skin Trade". DARK VISIONS is a brilliantly original showcase from three masters of the macabre.', 'en', 2000, 381, 'http://books.google.com/books/content?id=qpJoGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
