INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fc3f45a9-913a-57f1-bc59-b92b4280db6f', '9780586040102', 'Banco', 'rqiAVILt4dIC', 'The sensational sequel to ''Papillon''. ‘Banco'' continues the adventures of Henri Charriere - nicknamed Papillon - in Venezuela, where he has finally won his freedom after thirteen years of escape and imprisonment. Despite his resolve to become an honest man, Charriere is soon involved in hair-raiding exploits with goldminers, gamblers, bank-robbers and revolutionaries - robbing and being robbed, his lust for life as strong as ever. He also runs night clubs in Caracas until an earthquake ruins him in 1967 - when he decides to write the book that brings his international fame.', 'en', 1973, 406, 'http://books.google.com/books/content?id=rqiAVILt4dIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
