INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bacc1b11-66ee-57cc-8819-45e7c10564e3', '9780586210697', 'The Curse of the Mistwraith', 'Ju3E6WIy1ygC', 'The world of Athera lives in eternal fog, its skies obscured by the malevolent Mistwraith. Only the combined powers of two half-brothers can challenge the Mistwraith''s stranglehold: Arithon, Master of Shadow, and Lysaer, Lord of Light. Arithon and Lysaer soon find that they are inescapably bound to a series of events dictated by their own deepest convictions. Yet as the sorcerers of the Fellowship of Seven know well, there is more at stake than one battle with the Mistwraith: between them the half-brothers hold the balance of the world—its harmony and its future—in their hands.', 'en', 2004, 830, 'http://books.google.com/books/content?id=Ju3E6WIy1ygC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
