INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c034583b-8bed-5fbb-b793-efc07b40c9a1', '9780593040591', 'The Illustrated A Brief History of Time', 'pe7TOAAACAAJ', 'This is Stephen Hawking''s updated, expanded and illustrated edition of his celebrated work which includes the most recent developments in the field, many of which were forecast by him. At the same time, he explains his complex theories through a fresh visual dimension. Over one hunded and fifty stunning colour illustrations have been specially commissioned for this purpose to help the reader understand what have become popular mythic images of our century, but which nonetheless remain difficult, abstract ideas to grasp. It includes a new introduction written specially for this edition.', 'en', 1996, 259, 'http://books.google.com/books/content?id=pe7TOAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
