INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('86f40f32-bf5f-579b-b08c-a1967145d30f', '9780600601166', 'The New Hite Report', '7gzFQgAACAAJ', 'This new report includes previously unpublished data and personal accounts from women in the UK and Commonwealth. The original "Hite Report on Female Sexuality" was based on samples of women exclusively in the USA. First published in 1976, it explored women''s feelings about sex and has had a profound influence on generations of readers. In it, women between the ages of 14 and 78 described their most intimate feelings and answered questions about orgasm, masturbation and their sexual desires. This book brings Shere Hite''s thinking to a new generation of women and draws conclusions based on up-to-date and relevant worldwide findings to one of the most probing surveys ever undertaken.', 'en', 2000, 667, 'http://books.google.com/books/content?id=7gzFQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
