INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('eef20b27-60e6-56ee-ac7a-6bb8c13d13d8', '9780618056736', 'Unweaving the Rainbow', 'GWj0q_rdvd8C', 'Offers an assessment of what science is, how it feeds the human appetite for wonder, and how "unweaving" the mysteries of science can be even more beautiful than the mystery itself.', 'en', 2000, 352, 'http://books.google.com/books/content?id=GWj0q_rdvd8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
