INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('301e39a5-9aa4-5ecc-99fa-c3893ee2504b', '9780618056804', 'Baumgartner''s Bombay', 'x3xoZHiciKoC', 'A "beautifully written, richly textured, and haunting story" (Chaim Potok), BAUMGARTNER''S BOMBAY is Anita Desai''s classic novel of the Holocaust era, a story of profound emotional wounds of war and its exiles. The novel follows Hugo Baumgartner as he flees Nazi Germany -- and his Jewish heritage -- for India, only to be imprisoned as a hostile alien and then released to Bombay at war''s end. In this tale of a man who, "like a figure in a Greek tragedy . . . seems to elude his destiny" (NEW LEADER), Desai''s "capacious intelligence, her unsentimental compassion" (NEW REPUBLIC) reach their full height.', 'en', 2000, 240, 'http://books.google.com/books/content?id=x3xoZHiciKoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
