INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('276bfaef-bbc2-50f8-a123-23e5c62e0ece', '9780618056996', 'The Letters of J.R.R. Tolkien', 'vGFR3sZmpmEC', 'Selected letters discuss his books, their meanings, his interests and also reveal his view of the world.', 'en', 2000, 502, 'http://books.google.com/books/content?id=vGFR3sZmpmEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
