INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('31e88e8d-abd5-571b-8cf5-494e7688418b', '9780618057023', 'J.R.R. Tolkien', 'PaP8XzOxTpQC', 'Carefully traces Tolkien''s life, revealing surprising links between his own experience and his written works, especially The Lord of the Rings trilogy and Silmarillion. Reprint.', 'en', 2000, 304, 'http://books.google.com/books/content?id=PaP8XzOxTpQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
