INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('55ca3024-6ef0-56d8-9490-1c019ae6df97', '9780618074518', 'Clear Light of Day', 'HBKAELY0tV4C', 'The classic novel by the author of Diamond Dust evokes the traumatic history of India after the departure of the British in a story of a Hindu family in Old Delhi and the complex relationships that develop among four people. Reprint.', 'en', 2000, 183, 'http://books.google.com/books/content?id=HBKAELY0tV4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3720', 'accepted', 'Anita Desai', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 14 FROM public.book WHERE isbn13 = '9780618074518' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ee36048b-2375-5c5e-b79e-5ae08e43ba4c', '9780618083558', 'The History of the Lord of the Rings', '_NsHAAAACAAJ', 'J.R.R. Tolkien''s The Lord of the Rings, now firmly acknowledged as one of the most popular books of the twentieth century, has captivated generations of readers with its completely convincing fantasy. In The History of The Lord of the Rings, the author''s son & literary heir, Christopher Tolkien, examines the creation of that epic from its inception to its finished form. At the core of these books are many early drafts & unpublished passages by Tolkien, which add greatly to a thorough understanding of his masterpiece. Combining his father''s unique vision with his own privileged insight & editorial commentary, Christopher Tolkien''s The History of The Lord of the Rings is a set of four volumes -- including one unique to this collection -- that no fan of The Lord of the Rings can afford to overlook. "One marvels anew at the depth, breadth, & persistence of J.R.R. Tolkien''s labor. No one sympathetic to his aims, the invention of a secondary universe, will want to miss this chance to be present at the creation." -- Publishers Weekly.', 'en', 2000, 1680, 'http://books.google.com/books/content?id=_NsHAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3721', 'accepted', 'John Ronald Reuel Tolkien; Christopher Tolkien', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 4 FROM public.book WHERE isbn13 = '9780618083558' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7f708164-f7fe-5436-bfb1-f1aa767d2319', '9780618083572', 'The Return of the Shadow', 'CzXSh4NhOy4C', 'In this sixth volume of The History of Middle-earth the story reaches The Lord of the Rings. In The Return of the Shadow (an abandoned title for the first volume) Christopher Tolkien describes, with full citation of the earliest notes, outline plans, and narrative drafts, the intricate evolution of The Fellowship of the Ring and the gradual emergence of the conceptions that transformed what J.R.R. Tolkien for long believed would be a far shorter book, ''a sequel to The Hobbit''. The enlargement of Bilbo''s ''magic ring'' into the supremely potent and dangerous Ruling Ring of the Dark Lord is traced and the precise moment is seen when, in an astonishing and unforeseen leap in the earliest narrative, a Black Rider first rode into the Shire, his significance still unknown. The character of the hobbit called Trotter (afterwards Strider or Aragorn) is developed while his indentity remains an absolute puzzle, and the suspicion only very slowly becomes certainty that he must after all be a Man. The hobbits, Frodo''s companions, undergo intricate permutations of name and personality, and other major figures appear in strange modes: a sinister Treebeard, in league with the Enemy, a ferocious and malevolent Farmer Maggot. The story in this book ends at the point where J.R.R. Tolkien halted in the story for a long time, as the Company of the Ring, still lacking Legolas and Gimli, stood before the tomb of Balin in the Mines of Moria. The Return of the Shadow is illustrated with reproductions of the first maps and notable pages from the earliest manuscripts.', 'en', 2000, 512, 'http://books.google.com/books/content?id=CzXSh4NhOy4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3722', 'accepted', 'John Ronald Reuel Tolkien; Christopher Tolkien', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 16 FROM public.book WHERE isbn13 = '9780618083572' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b219b487-5b56-50d3-bad2-b6cb84a07f9e', '9780618083619', 'J.R.R. Tolkien', 'DiU0zVedmA8C', 'A collection of more than two-hundred reproductions of Tolkien''s drawings, sketches, and paintings explores his career as an artist.', 'en', 2000, 224, 'http://books.google.com/books/content?id=DiU0zVedmA8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
