INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('141d43d2-2364-534c-8058-e25847474646', '9780618111206', 'Once a Wolf', 'UkZWugAVvPYC', 'With powerful and rare photos by a former photographer for the National Geographic Society, "Once a Wolf" explores the long-troubled relationship of humans and wolves. The book traces the persecution of the wolf throughout history and also reveals the role scientists have played in wolf preservation. Full color.', 'en', 2001, 48, 'http://books.google.com/books/content?id=UkZWugAVvPYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
