INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0aec04ba-11b6-58ff-8f50-d109bfdab73d', '9780618127337', 'Stern Men', 'coBvZTs5Yf8C', 'Ruth Thomas, a spunky young woman born into the midst of a feud between two factions of Maine lobstermen, manages to negotiate an end to the conflict. A first novel. Reprint.', 'en', 2001, 304, 'http://books.google.com/books/content?id=coBvZTs5Yf8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
