INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('450865d7-33f2-5d61-97e0-f96aa27ab858', '9780618127368', 'Colter', '3irVaKvVuLIC', 'The author shares his memories of his favorite dog, Colter, and the diverse ways in which he transformed the author''s life, in a look at the dynamic relationship between humans and dogs.', 'en', 2001, 208, 'http://books.google.com/books/content?id=3irVaKvVuLIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
