INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9b3da349-d09e-513b-a30d-4c8fa0c95d83', '9780618131709', 'Chimera', 'm7UiIU8WxCsC', 'In CHIMERAJohn Barth injects his signature wit into the tales of Scheherezade of the Thousand and One Nights, Perseus, the slayer of Medusa, and Bellerophon, who tamed the winged horse Pegasus. In a book that the Washington Post called "stylishly maned, tragically songful, and serpentinely elegant,” Barth retells these tales from varying perspectives, examining the myths’ relationship to reality and their resonance with the contemporary world. A winner of the National Book Award, this feisty, witty, sometimes bawdy book provoked Playboy to comment, "There’s every chance in the world that John Barth is a genius.”', 'en', 2001, 308, 'http://books.google.com/books/content?id=m7UiIU8WxCsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
