INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9f63f323-2875-503b-8560-f0758f3b1657', '9780618134304', 'Henry Adams and the Making of America', 'idzRhAdjnysC', 'A profile of nineteenth-century historian Henry Adams assesses his influence on the study of history, discussing his use of archival sources, firsthand reportage, eyewitness accounts that transformed historical study.', 'en', 2005, 480, 'http://books.google.com/books/content?id=idzRhAdjnysC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3729', 'accepted', 'Garry Wills; Pulitzer Prize-Winning Journalist and Historian Garry Wills', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 12 FROM public.book WHERE isbn13 = '9780618134304' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a8fa1d5a-4115-5a17-a262-3021fa05905f', '9780618134328', 'Nixon Agonistes', '5cVKKLSC788C', 'From one of America''s most distinguished historians comes this classic analysis of Richard Nixon. By considering some of the president''s opinions, Wills comes to the controversial conclusion that Nixon was actually a liberal. Both entertaining and essential, Nixon Agonistes captures a troubled leader and a struggling nation mired in a foolish Asian war, forfeiting the loyalty of its youth, puzzled by its own power, and looking to its cautious president for confidence. In the end, Nixon Agonistes reaches far beyond its assessment of the thirty-seventh president to become an incisive and provocative analysis of the American political machine.', 'en', 2002, 640, 'http://books.google.com/books/content?id=5cVKKLSC788C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
