INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('20e458ea-8429-5d68-ab2d-fce43cd976b2', '9780618153978', 'The Lord of the Rings', 'Ye0OAAAACAAJ', 'Beginning on December 19, New Line Cinema will present a grand trilogy of live-action feature films: The Fellowship of the Ring, The Two Towers, & The Return of the King. The three separately released installments of J.R.R. Tolkien''s The Lord of the Rings will mark the return of "cliffhanger cinema" for the first time since the serial adventures of decades past. Tolkien''s mythic vision will come to life through the cutting-edge cinema technology & artistry of director Peter Jackson. Houghton Mifflin, publisher of the epic masterworks of J.R.R. Tolkien for more than sixty years, is proud to offer new movie tie-in volumes, each available separately & in boxed sets. Paperback & hardcover editions & boxed sets will have different cover art.', 'en', 2001, 1223, 'http://books.google.com/books/content?id=Ye0OAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
