INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('63715bf8-37b7-5deb-b034-734363b53bba', '9780618196258', 'Midnight is a Place', 'HV8MmQEACAAJ', 'In northern England in 1842, fourteen-year-old Lucas leads a lonely, monotonous existence in the house of his unpleasant guardian until the unexpected arrival of an unusual little girl presages a series of events that completely change his life.', 'en', 2002, 304, 'http://books.google.com/books/content?id=HV8MmQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
