INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2b1f1c22-4ede-5ef0-946d-d33a3e17508b', '9780618254118', 'Queen of Scots', 'PmqqAQAACAAJ', 'A new historian of Mary Queen of Scots draws on new sources to shatter various myths surrounding this odd monarch and uncover some of the scandals and political machinations underpinning, and undermining, her throne.', 'en', 2004, 581, 'http://books.google.com/books/content?id=PmqqAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
