INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d6d4f03b-13fb-5cfa-924a-a04d56f4c1f1', '9780618257768', 'Inventing America', 'V-XP_riSQU8C', 'From one of America''s foremost historians, Inventing America compares Thomas Jefferson''s original draft of the Declaration of Independence with the final, accepted version, thereby challenging many long-cherished assumptions about both the man and the document. Although Jefferson has long been idealized as a champion of individual rights, Wills argues that in fact his vision was one in which interdependence, not self-interest, lay at the foundation of society. "No one has offered so drastic a revision or so close or convincing an analysis as Wills has . . . The results are little short of astonishing" (Edmund S. Morgan New York Review of Books ).', 'en', 2002, 432, 'http://books.google.com/books/content?id=V-XP_riSQU8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
