INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e1d78ab6-9638-564a-80af-cb82ecf8b4c6', '9780618479030', 'Natural Health, Natural Medicine', 'qliYOteXA30C', 'The best-selling books of Andrew Weil, "the guru of alternative medicine," (San Francisco Examiner) offer a comprehensive blend of traditional and alternative methods that help to achieve better health in the modern world. Natural Health, Natural Medicine is a comprehensive resource for everything you need to know to maintain optimum health and treat common ailments. This landmark book incorporates Dr. Weil’s theories of preventive health maintenance and alternative healing into one extremely useful and readable reference, featuring general diet and nutrition information as well as simple recipes, answers to readers’ most pressing questions, a catalogue of home remedies, invaluable resources, and hundreds of practical tips. This edition includes up-to-the-minute scientific findings and has been expanded to provide trustworthy advice about low-carb diets, hormone replacement therapy, Alzheimer’s, attention deficit disorder, reflux disease, autism, type 2 diabetes, erectile dysfunction, the flu, and much more.', 'en', 2004, 448, 'http://books.google.com/books/content?id=qliYOteXA30C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
