INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b5364f27-35d7-5813-bd54-3e25b1ae5fb5', '9780631163022', 'The Ideology of the Aesthetic', 'QzYDaoaUyLYC', 'The Ideology of the Aesthetic presents a history and critique of the concept of the aesthetic throughout modern Western thought. As such, this is a critical survey of modern Western philosophy, focusing in particular on the complex relations between aesthetics, ethics and politics. Eagleton provides a brilliant and challenging introduction to these concerns, as characterized in the work of Kant, Schiller, Schopenhauer, Kierkegaard, Marx, Nietzsche, Freud, Heidegger, Lukacs, Adorno, Habermas, and others. Wide in span, as well as morally and politically committed, this is Terry Eagleton''s major work to date. It forms both an original enquiry and an exemplary introduction.', 'en', 1991, 432, 'http://books.google.com/books/content?id=QzYDaoaUyLYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
