INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d3b70fa2-6293-594f-9f2a-1c3e3867bd9d', '9780631169406', 'On Certainty', 'ZGHG6WkVF5EC', 'Written over the last 18 months of his life and inspired by his interest in G. E. Moore''s defence of common sense, this much discussed volume collects Wittgenstein''s reflections on knowledge and certainty, on what it is to know a proposition for sure.', 'en', 1991, 114, 'http://books.google.com/books/content?id=ZGHG6WkVF5EC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
