INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('46d36c23-62d1-5b08-a8fa-36a6bb76e56b', '9780631186274', 'Western Philosophy', 'imkTo_sNrKcC', 'From ancient Greece to the leading philosophers of today, Western Philosophy: An Anthology provides the most comprehensive and authoritative survey of the Western philosophical tradition. In 100 substantial and carefully chosen extracts, the volume covers all the main branches of philosophy - theory of knowledge and metaphysics, philosophy of mind, religion and science, moral philosophy (theoretical and applied), political theory and aesthetics. Chronologically and thematically arranged, the readings are introduced and linked together by a lucid philosophical commentary which guides the reader through the key arguments. This outstanding text will support a wide variety of introductory courses in philosophy, as well as providing more advanced students with a handy collection of classic source materials.', 'en', 1996, 656, 'http://books.google.com/books/content?id=imkTo_sNrKcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
