INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2f4a8270-bdfe-55ec-9829-ac2774a027d2', '9780664226107', 'The Gospel According to Tolkien', 'xcQSngEACAAJ', ': In this accessible and engaging book, Ralph Wood shows us that J.R.R. Tolkien''s masterpiece is a deeply Christian work because it does not blink back the horrors of our terrible times but confronts them with startling honesty. Readers keep turning to this work because here they are immersed in significance and meaning - perceiving the Hope than can be found amidst despair; the Charity that overcomes vengeance; and the Faith that springs from the strange power of weakness. The Gospel According to Tolkien will be loved by both longtime Tolkien fans and those recently drawn to his books through the popular feature films.', 'en', 2003, 169, 'http://books.google.com/books/content?id=xcQSngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3793', 'accepted', 'Ralph C. Wood', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 9 FROM public.book WHERE isbn13 = '9780664226107' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a1065d19-d46d-5292-bed7-ac277acdd43a', '9780664228910', 'That Godless Court?', 'kjLLlS9hWmYC', 'The religion clauses of the First Amendment, which seem simple and clear, have been and continue to be controversial in their application. Church-state issues have never been more complex, controversial, and divisive than they are today. In this helpful and instructive book, Ronald B. Flowers explains clearly and concisely the intricacies and implications of Supreme Court decisions in the volatile area of church-state relations. This is an ideal primer for those Americans who have listened to the debates about what the Supreme Court has and has not said about the relationship between church and state, and where the boundaries between the two have been eroded. It is also ideal for use in the classroom, specifically in undergraduate courses in religion and the court, introductions to U.S. constitutional law, constitutional law and politics, and the Supreme Court. The book is also a helpful tool for pastors, clarifying contemporary church-state issues that impact their churches and parishioners directly and indirectly.', 'en', 2005, 228, 'http://books.google.com/books/content?id=kjLLlS9hWmYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3794', 'accepted', 'Ronald Bruce Flowers', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 18 FROM public.book WHERE isbn13 = '9780664228910' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('76b217b8-c25a-5de7-99ac-de0e4de9771a', '9780664241582', 'Luther and Erasmus', 'IU_8JDjxL34C', 'This volume includes the texts of Erasmus''s 1524 diatribe against Luther, De Libero Arbitrio, and Luther''s violent counterattack, De Servo Arbitrio. E. Gordon Rupp and Philip Watson offer commentary on these texts as well. Long recognized for the quality of its translations, introductions, explanatory notes, and indexes, the Library of Christian Classics provides scholars and students with modern English translations of some of the most significant Christian theological texts in history. Through these works--each written prior to the end of the sixteenth century--contemporary readers are able to engage the ideas that have shaped Christian theology and the church through the centuries.', 'en', 1969, 364, 'http://books.google.com/books/content?id=IU_8JDjxL34C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3795', 'accepted', 'Ernest Gordon Rupp; Philip Saville Watson', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 10 FROM public.book WHERE isbn13 = '9780664241582' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ba0645b2-5c0e-585a-91a8-0e338bfed48f', '9780670034666', 'Self-made Man', 'PGiBQgAACAAJ', 'A Los Angeles Times columnist recounts her eighteen-month undercover stint as a man, a time during which she underwent considerable personal risks as she worked a sales job, joined a bowling league, frequented sex clubs, dated, and encountered firsthand the rigid codes and rituals of masculinity. 80,000 first printing.', 'en', 2006, 290, 'http://books.google.com/books/content?id=PGiBQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
