INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d818c16f-5fb9-5038-a38a-857075838341', '9780670034802', 'Swapping Lives', 'x6Y1CioZ3QQC', 'Longing for a traditional family life in the country in spite of her successful career and many friends, magazine director Vicky Townsley participates in a contest that has her switching places for one month with Amber Winslow, a busy wife and mother. By the author of The Other Woman. 150,000 first printing.', 'en', 2005, 410, 'http://books.google.com/books/content?id=x6Y1CioZ3QQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
