INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8014b4d2-d22e-5ac8-9d7f-5d2a132e033d', '9780670037605', 'Mayflower', 'qk9AXww_XysC', 'A history of the Pilgrim settlement of New England challenges popular misconceptions, discussing such topics as the diseases of European origin suffered by the Wampanoag tribe, the fragile working relationship between the Pilgrims and their Native American neighbors, and the devastating impact of the King Philip''s War. By the author of Sea of Glory. 450,000 first printing.', 'en', 2006, 461, 'http://books.google.com/books/content?id=qk9AXww_XysC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
