INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ce3d6319-e6a5-5071-9d09-2d766eaee375', '9780670820559', 'Spycatcher', 'gkeJAAAAMAAJ', 'The former assistant director of MI5 offers an account of British Intelligence, including his work on the Ring of Five and exposing Soviet espionage and the conspiracy to oust Harold Wilson from the office of Prime Minister in the 1970s', 'en', 1987, 392, 'http://books.google.com/books/content?id=gkeJAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
