INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('68525d22-724e-5848-b7a0-b77b834d7e82', '9780670913527', 'Artemis Fowl', 'TOqePwAACAAJ', 'Twelve-year-old villain, Artemis Fowl, is the most ingenious criminal mastermind in history. His bold and daring plan is to hold a leprechaun to ransom; but he''s taking on more than a bunch of fairies when he kidnaps Captain Holly Short of the Lep-Recon (lower elements police reconnaissance unit).', 'en', 2003, 329, 'http://books.google.com/books/content?id=TOqePwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
