INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4a1641fa-445a-5591-8104-b17853f99eca', '9780670915415', 'In the Shadow of No Towers', '0mLvAQAACAAJ', 'On 11th September 2001, Art Spiegelman raced to the World Trade Center, not knowing if his daughter Nadja was alive or dead. Once she was found safe in her school at the foot of the burning towers he returned home, to meditate on the trauma, and to work on a comic strip. Subversive, iconic, and burningly articulate, In the Shadow of No Towers is New Yorker Art Spiegelman''s extraordinary account of ''the hijacking on 9.11 and the subsequent hijacking of those events'' by America.', 'en', 2004, 48, 'http://books.google.com/books/content?id=0mLvAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
