INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5a49c4b8-4c2c-54e1-8bec-df08652a89b0', '9780671000745', 'Echo Platoon', 'NqJ7l2bMCIYC', 'With Iran and Russia angling to take over oil resources in the Caspian Sea, the Navy SEALs, accompanied by Major Jessica Van Pachen and the Rogue Warrior, are sent in to protect American interests in the region. Reprint.', 'en', 2001, 402, 'http://books.google.com/books/content?id=NqJ7l2bMCIYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
