INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8440773b-89a2-58a5-8ebf-49bc7b7a0b66', '9780671024185', 'Morgan''s Run', 'XtgXaI7yBrMC', 'Colleen McCullough captivated millions with her beloved worldwide bestseller The Thorn Birds. Now she takes readers to the birth of modern Australia with a breath-taking saga brimming with drama, history, and passion. It was one of the greatest human experiments ever undertaken: to populate an unknown continent with the criminals of English society. For Richard Morgan, twelve months as a prisoner on the high seas would be just the beginning in a soul-trying test to survive in a hostile new land where, against all odds, he would find a new love and a new life. From the dank cells of England''s prisons to the unforgiving frontier of the eighteenth-century outback, Morgan''s Run is the epic tale of one man whose strength and character helped settle a country and define its future.', 'en', 2002, 848, 'http://books.google.com/books/content?id=XtgXaI7yBrMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
