INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5917165d-3209-505e-ac58-d17643c2c02c', '9780671025700', 'The Last Dance', 'OGxiKastPxsC', 'In this city, you can get anything done for a price. If you want someone''s eyeglasses smashed, it''ll cost you a subway token. You want his fingernails pulled out? His legs broken? You want him hurt so bad he''s an invalid his whole life? You want him...killed? Let me talk to someone. It can be done. The hanging death of a nondescript old man in a shabby little apartment in a meager section of the 87th Precinct is nothing much in this city, especially to detectives Carella and Meyer. But everyone has a story, and this old man''s story stood to make some people a lot of money. His story takes Carella, Meyer, Brown, and Weeks on a search through Isola''s seedy strip clubs and to the bright lights of the theater district. There they discover an upcoming musical with ties to a mysterious drug -- and a killer who stays until the last dance.', 'en', 2000, 336, 'http://books.google.com/books/content?id=OGxiKastPxsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
