INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dac86303-6351-5e7c-a47a-52a49c173cf5', '9780671026011', 'The Empty Chair', 'xLPy2D0d2F4C', 'Renowned criminalist Lincoln Rhyme faces his ultimate opponent: a kidnapper and murderer dubbed the Insect Boy. But Rhyme is in for a surprise when he learns that catching a criminal is one thing...and keeping him is another. Now Rhyme, in North Carolina to undergo risky spinal cord surgery, finds himself hunting a ruthless killer in the heart of a southern swampland -- and going head-to-head with his protégé, Amelia Sachs, in a rivalry that tests the limits of both their expertise and their love.', 'en', 2001, 512, 'http://books.google.com/books/content?id=xLPy2D0d2F4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
