INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e822fde4-c325-5bcf-a73e-836dabc0c460', '9780671519186', 'The Night Awakens', 'TLK4yMezNiMC', 'The crowned Queen of Suspense, #1 New York Times bestselling author Mary Higgins Clark, has no peer in the realm of stylish, sophisticated thrillers -- brilliant, breathtaking tales that delve into the deepest affairs of the heart, the darkest crimes of passion. Now, in that same haunting tradition, she invites a star-studded cast of authors to share original stories of men and women joined in love...and driven to murder. Sara Shankman puts a chilling new spin on payback...Joseph Hansen slaps a rancher with a cold wake-up call out on the trail...Loren D. Estleman cuts a honeymoon short when a bride learns she''s married to the mob...Brendan DuBois drives a brother to distractionon the road to revenge...Sally Gunning pushes jealousy to a murderous extreme...Nancy Pickard exposes the truth behind the headlines as a young love leads to old-fashioned homicide...and a panoply of other renouned writers spellbind us with the seductive charms of love, lust, and other lethal attractions.', 'en', 2000, 303, 'http://books.google.com/books/content?id=TLK4yMezNiMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3850', 'accepted', 'Mary Higgins Clark', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 10 FROM public.book WHERE isbn13 = '9780671519186' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('24a6d160-0c6d-5f9b-bbe3-3032d6c91a55', '9780671519988', 'The Leader In You', 'kvE_lAEACAAJ', 'For nearly a century, the words and works of Dale Carnegie & Associates, Inc., have translated into proven success—a claim verified by millions of satisfied graduates; a perpetual 3,000-plus enrollment roster per week; and book sales, including the mega-bestseller How to Win Friends and Influence People, totaling over thirty million copies. Now, in The Leader In You, coauthors Stuart R. Levine and Michael A. Crom apply the famed organization’s time-tested human relations principles to demonstrate how anyone, regardless of his or her job, can harness creativity and enthusiasm to work more productively. With insights from leading figures in the corporate, entertainment, sports, academic, and political arenas—and encompassing interviews and advice from such eminent authorities as Lee Iacocca and Margaret Thatcher—this comprehensive, step-by-step guide includes strategies to help you: identify your leadership strengths; achieve your goals and increase your self-confidence; eliminate an “us vs. them” mentality; become a team player and strengthen cooperation among associates; balance work and leisure; control your worries and energize your life; and much more! The most important investment you will ever make is in yourself—once you discover the key that unlocks The Leader In You.', 'en', 1995, 256, 'http://books.google.com/books/content?id=kvE_lAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
