INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9147f997-45e4-5e90-986f-4069d95274c3', '9780671553029', 'Harvest', 'GY5mZyojjv8C', 'Medical resident Dr. Abby Matteo is elated when the elite cardiac transplant team at Boston''s Bayside Hospital taps her as a potential recruit. But faced with a tormenting life-and-death decision, Abby helps direct a crash victim''s harvested heart to a dying teenager -- instead of the wealthy older woman who was supposed to receive it. The repercussions leave Abby shaken and plagued with self-doubt. Suddenly, a new heart appears, and the woman''s transplant is completed. Then Abby makes a terrible discovery. The donor records have been falsified -- the new heart has not come through the proper channels. Defying the hospital''s demands for silence, she begins her own investigation that reveals a murderous, unthinkable conspiracy. Every move Abby makes spawns a vicious backlash...and on a ship anchored in the waters of Boston harbor, the grisly truth lies waiting.', 'en', 1997, 368, 'http://books.google.com/books/content?id=GY5mZyojjv8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3853', 'accepted', 'Tess Gerritsen', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 15 FROM public.book WHERE isbn13 = '9780671553029' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bd4ae82c-54ec-519b-a6de-515e0fcb5240', '9780671553043', 'Life Support', 's-bKpPSlbbUC', 'New York Times bestselling author Tess Gerritsen weaves authenticity into another novel of searing medical suspense, as a dedicated woman doctor probes into the cause of a mystifying and lethal outbreak. The quiet overnight shift at Springer Hospital ER suits Dr. Toby Harper just fine -- until she admits a man in critical condition from a possible viral infection of the brain. The delirious man barely responds to treatment -- and then disappears without a trace. Before Toby can find him, a second case occurs, revealing a terrifying fact: the virus can only be spread through direct tissue exchange. Following a trail of death that winds from a pregnant sixteen-year-old prostitute to her own home, Toby discovers the unthinkable: the epidemic didn''t just happen -- someone let it loose....', 'en', 1998, 400, 'http://books.google.com/books/content?id=s-bKpPSlbbUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
