INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('98f09405-5fa8-562c-813b-703cf8d20162', '9780674215184', 'Doubling the Point', 'dZ7_o8ElbQoC', 'Nadine Gordimer has written of J.M. Coetzee that his vision goes to the nerve-centre of being. What he finds there is more than most people will ever know about themselves, and he conveys it with a brilliant writer''s mastery of tension and elegance. Doubling the Point takes the reader to the center of that vision. These essays and interviews, documenting Coetzee''s longtime engagement with his own culture, and with modern culture in general, constitute a literary autobiography.', 'en', 1992, 438, 'http://books.google.com/books/content?id=dZ7_o8ElbQoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
