INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a13d04fb-43c1-5615-9d08-81435610a080', '9780674268630', 'The Ethics of Authenticity', 'f11Q-RNvmSEC', 'Everywhere we hear of decline, of a world that was better before the influence of modernity. While some lament Western culture''s slide into relativism and nihilism and others celebrate the trend as a liberating sort of progress, Taylor calls on us to face the moral and political crises of our time, and to make the most of modernity''s challenges.', 'en', 1992, 152, 'http://books.google.com/books/content?id=f11Q-RNvmSEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
