INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('410e8a55-7974-5654-b7f9-c6c923b24feb', '9780674295032', 'The Fate of Reason', '3QUVngEACAAJ', 'The Fate of Reason is the first general history devoted to the period between Kant and Fichte, one of the most revolutionary and fertile in modern philosophy. The philosophers of this time broke with the two central tenets of the modem Cartesian tradition: the authority of reason and the primacy of epistemology. They also witnessed the decline of the Aufkldrung, the completion of Kant''s philosophy, and the beginnings of post-Kantian idealism. Thanks to Beiser we can newly appreciate the influence of Kant''s critics on the development of his philosophy. Beiser brings the controversies, and the personalities who engaged in them, to life and tells a story that has uncanny parallels with the debates of the present.', 'en', 1993, 410, 'http://books.google.com/books/content?id=3QUVngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3911', 'accepted', 'Frederick C. Beiser', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 6 FROM public.book WHERE isbn13 = '9780674295032' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bfd04872-b51a-5fd4-bf22-f50e26a1524d', '9780674618763', 'New Worlds, Ancient Texts', 'APVWL5avg7oC', 'On encountering what he called "the Indies", the Jesuit Jose de Acosta wrote, "Having read what poets and philosophers write of the Torrid Zone, I persuaded myself that when I came to the Equator, I would not be able to endure the violent heat, but it turned out otherwise... What could I do then but laugh at Aristotle''s Meteorology and his philosophy?" Acosta''s experience echoes that of his fellow travelers to the New World, and it is this experience, with its profound effect on Western culture, that Anthony Grafton charts. Describing an era of exploration that went far beyond geographic bounds, this book shows how the evidence of the New World shook the foundations of the old, upsetting the authority of the ancient texts that had guided Europeans so far afield. The intellectual shift mapped out here, a movement from book learning to empirical knowledge, did not take place easily or quickly, and Grafton presents it in all its drama and complexity. What he recounts is in effect a war of ideas fought, sometimes unwittingly by mariners, scientists, publishers, scholars, and rulers over one hundred fifty years. He shows us explorers from Cortes and Columbus to Scaliger and Munster, laden with ideas gathered from ancient and medieval texts, in their encounters with the world at large. In colorful vignettes, firsthand accounts, published debates, and copious illustrations, we see these men and their contemporaries trying to make sense of their discoveries as they sometimes confirm, sometimes contest, and finally displace traditional images and notions of the world beyond Europe. The fundamental cultural revolution that Grafton documents still reverberates in our time. By taking us into thisbattle of books versus facts, a conflict that has shaped global views for centuries, Grafton allows us to re-experience and understand the Renaissance as it continues to this day.', 'en', 1992, 296, 'http://books.google.com/books/content?id=APVWL5avg7oC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
