INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2fa0389f-ef69-5819-9bad-2ea191d4efd6', '9780674961876', 'The World, the Text, and the Critic', 'cwF60MVVGAsC', 'Argues that contemporary critics force works of literature to fit their theories and examines the impact of Marxism, linguistics, psychoanalysis, and structuralism on literary criticism', 'en', 1983, 336, 'http://books.google.com/books/content?id=cwF60MVVGAsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3925', 'accepted', 'Edward W. Said', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 20 FROM public.book WHERE isbn13 = '9780674961876' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('91e42042-dee1-5d1b-a95e-3759f020e67e', '9780674990333', 'De officiis', '4lN0AAAAIAAJ', 'Cicero (Marcus Tullius, 106–43 BCE), Roman lawyer, orator, politician and philosopher, of whom we know more than of any other Roman, lived through the stirring era which saw the rise, dictatorship, and death of Julius Caesar in a tottering republic. In his political speeches especially and in his correspondence we see the excitement, tension and intrigue of politics and the part he played in the turmoil of the time. Of about 106 speeches, delivered before the Roman people or the Senate if they were political, before jurors if judicial, 58 survive (a few of them incompletely). In the fourteenth century Petrarch and other Italian humanists discovered manuscripts containing more than 900 letters of which more than 800 were written by Cicero and nearly 100 by others to him. These afford a revelation of the man all the more striking because most were not written for publication. Six rhetorical works survive and another in fragments. Philosophical works include seven extant major compositions and a number of others; and some lost. There is also poetry, some original, some as translations from the Greek. The Loeb Classical Library edition of Cicero is in twenty-nine volumes.', 'en', 1975, 448, 'http://books.google.com/books/content?id=4lN0AAAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3926', 'accepted', 'Marcus Tullius Cicero; Walter Miller', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 13 FROM public.book WHERE isbn13 = '9780674990333' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2732d1cb-b678-5319-95c1-e6a36e5c8c6f', '9780674990463', 'Metamorphoses', 'hZ2EAAAAIAAJ', NULL, 'en', 1984, 496, 'http://books.google.com/books/content?id=hZ2EAAAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3927', 'accepted', 'Publius Ovidius Naso (Dichter)', 'Mythology, Classical', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 1 FROM public.book WHERE isbn13 = '9780674990463' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e9150a03-3296-5e25-9b21-1cd47fcdaa25', '9780674990470', 'Metamorphoses', 'Mfp0AAAAIAAJ', 'Ovid (Publius Ovidius Naso, 43 BCE-17 CE), born at Sulmo, studied rhetoric and law at Rome. Later he did considerable public service there, and otherwise devoted himself to poetry and to society. Famous at first, he offended the emperor Augustus by his Ars Amatoria, and was banished because of this work and some other reason unknown to us, and dwelt in the cold and primitive town of Tomis on the Black Sea. He continued writing poetry, a kindly man, leading a temperate life. He died in exile. Ovid''s main surviving works are the Metamorphoses, a source of inspiration to artists and poets including Chaucer and Shakespeare; the Fasti, a poetic treatment of the Roman year of which Ovid finished only half; the Amores, love poems; the Ars Amatoria, not moral but clever and in parts beautiful; Heroides, fictitious love letters by legendary women to absent husbands; and the dismal works written in exile: the Tristia, appeals to persons including his wife and also the emperor; and similar Epistulae ex Ponto. Poetry came naturally to Ovid, who at his best is lively, graphic and lucid. The Loeb Classical Library edition of Ovid is in six volumes.', 'en', 1976, 499, 'http://books.google.com/books/content?id=Mfp0AAAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3928', 'accepted', 'Ovid', 'Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 11 FROM public.book WHERE isbn13 = '9780674990470' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6cc18071-45b1-55db-bbe4-1b28bbdbe75b', '9780674991842', 'Plato in twelve volumes', 'tRaDAAAAIAAJ', 'Plato, the great philosopher of Athens, was born in 427 BCE. In early manhood an admirer of Socrates, he later founded the famous school of philosophy in the grove Academus. Much else recorded of his life is uncertain; that he left Athens for a time after Socrates'' execution is probable; that later he went to Cyrene, Egypt, and Sicily is possible; that he was wealthy is likely; that he was critical of ''advanced'' democracy is obvious. He lived to be 80 years old. Linguistic tests including those of computer science still try to establish the order of his extant philosophical dialogues, written in splendid prose and revealing Socrates'' mind fused with Plato''s thought. In Laches, Charmides, and Lysis, Socrates and others discuss separate ethical conceptions. Protagoras, Ion, and Meno discuss whether righteousness can be taught. In Gorgias, Socrates is estranged from his city''s thought, and his fate is impending. The Apology (not a dialogue), Crito, Euthyphro, and the unforgettable Phaedo relate the trial and death of Socrates and propound the immortality of the soul. In the famous Symposium and Phaedrus, written when Socrates was still alive, we find the origin and meaning of love. Cratylus discusses the nature of language. The great masterpiece in ten books, the Republic, concerns righteousness (and involves education, equality of the sexes, the structure of society, and abolition of slavery). Of the six so-called dialectical dialogues Euthydemus deals with philosophy; metaphysical Parmenides is about general concepts and absolute being; Theaetetus reasons about the theory of knowledge. Of its sequels, Sophist deals with not-being; Politicus with good and bad statesmanship and governments; Philebus with what is good. The Timaeus seeks the origin of the visible universe out of abstract geometrical elements. The unfinished Critias treats of lost Atlantis. Unfinished also is Plato''s last work of the twelve books of Laws (Socrates is absent from it), a critical discussion of principles of law which Plato thought the Greeks might accept. The Loeb Classical Library edition of Plato is in twelve volumes.', 'en', 1975, 560, 'http://books.google.com/books/content?id=tRaDAAAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3929', 'accepted', 'Plato', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 20 FROM public.book WHERE isbn13 = '9780674991842' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5c4fc435-835a-594f-ba1b-e63fb9fab5e3', '9780674991873', 'History of the Peloponnesian War', '0GaEAAAAIAAJ', 'The Peloponnesian War was really three conflicts (431 421, 415 413, and 413 404 BCE) that Thucydides was still unifying into one account when he died some time before 396 BCE. Although unfinished and as a whole unrevised, in brilliance of description and depth of insight this history has no superior.', 'en', 1976, 480, 'http://books.google.com/books/content?id=0GaEAAAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3930', 'accepted', 'Thucydides', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 15 FROM public.book WHERE isbn13 = '9780674991873' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6b867cf8-e281-587a-9507-14b2c27f16d2', '9780674992023', 'Hiero', '4Q0IAQAAIAAJ', 'Minor works by Xenophon (c. 430-c. 354 BCE) include Hiero, a dialogue on government; Agesilaus, in praise of that king; Constitution of Lacedaemon, on the Spartan system; Ways and Means, on the finances of Athens; a manual of Horsemanship. The Constitution of the Athenians, though not by Xenophon, is an interesting document on Athenian politics. Xenophon (ca. 430 to ca. 354 BCE) was a wealthy Athenian and friend of Socrates. He left Athens in 401 and joined an expedition including ten thousand Greeks led by the Persian governor Cyrus against the Persian king. After the defeat of Cyrus, it fell to Xenophon to lead the Greeks from the gates of Babylon back to the coast through inhospitable lands. Later he wrote the famous vivid account of this "March Up-Country" (Anabasis); but meanwhile he entered service under the Spartans against the Persian king, married happily, and joined the staff of the Spartan king, Agesilaus. But Athens was at war with Sparta in 394 and so exiled Xenophon. The Spartans gave him an estate near Elis where he lived for years writing and hunting and educating his sons. Reconciled to Sparta, Athens restored Xenophon to honour but he preferred to retire to Corinth. Xenophon''s Anabasis is a true story of remarkable adventures. Hellenica, a history of Greek affairs from 411 to 362, begins as a continuation of Thucydides'' account. There are four works on Socrates (collected in Volume IV of the Loeb Xenophon edition). In Memorabilia Xenophon adds to Plato''s picture of Socrates from a different viewpoint. The Apology is an interesting complement to Plato''s account of Socrates'' defense at his trial. Xenophon''s Symposium portrays a dinner party at which Socrates speaks of love; and Oeconomicus has him giving advice on household management and married life. Cyropaedia, a historical romance on the education of Cyrus (the Elder), reflects Xenophon''s ideas about rulers and government; the Loeb edition is in two volumes. We also have his Hiero, a dialogue on government; Agesilaus, in praise of that king; Constitution of Lacedaemon (on the Spartan system); Ways and Means (on the finances of Athens); Manual for a Cavalry Commander; a good manual of Horsemanship; and a lively Hunting with Hounds. The Constitution of the Athenians, though clearly not by Xenophon, is an interesting document on politics at Athens. These eight books are collected in the last of the seven volumes of the Loeb Classical Library edition of Xenophon.', 'en', 1925, 576, 'http://books.google.com/books/content?id=4Q0IAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3931', 'accepted', 'Xenophon', 'Electronic books', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 14 FROM public.book WHERE isbn13 = '9780674992023' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fb9ee0da-bc56-5528-a1f2-a4696bcaf4b5', '9780674992405', 'Epictetus', 'ya9fAAAAMAAJ', 'These volumes contain the teachings ("Discourses") of the slave-philosopher Epictetus (55 A.D-135 AD). Also included in volume 2 are "Fragments", additional pieces from other (now lost) books of the "Discourses"; and "The Encheirdion", a collection of practical precepts for stoicism which can be seen as a handbook for life.', 'en', 1967, 576, 'http://books.google.com/books/content?id=ya9fAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3933', 'accepted', 'Epictetus', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 3 FROM public.book WHERE isbn13 = '9780674992405' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b28da420-8591-5ac3-b745-a516a48f4d10', '9780674992559', 'The Art of Love, and Other Poems', 'ZNwiygEACAAJ', 'In the didactic poetry of Face Cosmetics, Art of Love, and Remedies for Love, Ovid (43 BCE-17 CE) demonstrates abstrusity and wit. His Ibis is an elegiac curse-poem. Nux, Halieutica, and Consolatio ad Liviam are poems now judged not to be by Ovid.', 'en', 1985, 400, 'http://books.google.com/books/content?id=ZNwiygEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '3934', 'accepted', 'Ovid', 'Love poetry', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 11 FROM public.book WHERE isbn13 = '9780674992559' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3eff511a-2d77-5bae-9da6-5c0870e523d3', '9780674994805', 'Babrius and Phaedrus', '7lmEAAAAIAAJ', 'Babrius''s humorous and pointed fables in Greek verse probably date from the first century CE. From the same period come the lively fables in Latin verse written by Phaedrus, which satirize social and political life in Augustan Rome.', 'en', 1965, 736, 'http://books.google.com/books/content?id=7lmEAAAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
