INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3cb9da1a-fcf3-5df6-a5e5-acbcacb7bb31', '9780674995741', 'Fragmenta', 'EqJzlSgSSDcC', 'One of antiquity''s greatest poets, Euripides (ca. 485-406 BCE) has been prized in every age for the pathos, terror, surprising plot twists, and intellectual probing of his dramatic creations. Here, in the third volume of a new edition that is receiving much praise, is the text and translation of three of his plays. Trojan Women, a play about the causes and consequences of war, develops the theme of the tragic unpredictability of life. Iphigenia among the Taurians and Ion exhibit tragic themes and situations (the murder of close relatives). Each ends happily with a joyful reunion. As in the first three volumes of this edition, David Kovacs gives us a freshly edited Greek text and an admired new translation that, in the words of Greece and Rome, is "close to the Greek and reads fluently and well;" his introduction to each play and explanatory notes offer readers judicious guidance.', 'en', 1999, 528, 'http://books.google.com/books/content?id=EqJzlSgSSDcC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
