INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('251d72a3-fb1d-5b92-a4c9-c81d08a9ca17', '9780679732549', 'Shoot the Piano Player', 't_9MDwAAQBAJ', 'Once upon a time Eddie played concert piano to reverent audiences at Carnegie Hall. Now he bangs out honky-tonk for drunks in a dive in Philadelphia. But then two people walk into Eddie''s life--the first promising Eddie a future, the other dragging him back into a treacherous past. Shoot the Piano Player is a bittersweet and nerve-racking exploration of different kinds of loyalty: the kind a man owes his family, no matter how bad that family is; the kind a man owes a woman; and, ultimately, the loyalty he owes himself. The result is a moody thriller that, like the best hard-boiled fiction, carries a moral depth charge.', 'en', 1990, 158, 'http://books.google.com/books/content?id=t_9MDwAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
