INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0fb9cad5-fcc4-5542-99cf-ffb7b3def634', '9780679734482', 'Success', 'L2DpLn2lM5cC', 'Soaring with malicious poetry and almost unbearably accurate in its characterizations, Martin Amis turns Success into a sort of Jacobean revenge comedy. Its antagonists are two mismatched foster brothers who perform a merciless tango of class hatred, sexual rivalry, and disappointed love.', 'en', 1991, 224, 'http://books.google.com/books/content?id=L2DpLn2lM5cC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
