INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e3486015-230a-5252-a426-6ae34bb77b0a', '9780679734499', 'Dead Babies', 'fUrMtSgY5i8C', 'If the Marquis de Sade were to crash one of P. G. Wodehouse''s house parties, the chaos might resemble the nightmarishly funny goings-on in this novel by the author of London Fields. The residents of Appleseed Rectory have primed themselves both for a visit from a triad of Americans and a weekend of copious drug taking and sexual gymnastics. There''s even a heifer to be slugged and a pair of doddering tenants to be ingeniously harassed. But none of these variously bright and dull young things has counted on the intrusion of "dead babies" -- dreary spasms of reality. Or on the uninvited presence of a mysterious prankster named Johnny, whose sinister idea of fun makes theirs look like a game of backgammon.', 'en', 1975, 206, 'http://books.google.com/books/content?id=fUrMtSgY5i8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
