INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('604944c6-bdb6-5a37-bd0f-16f182757fe4', '9780679755487', 'The Death of Virgil', '-qg_DwAAQBAJ', 'It is the reign of the Emperor Augustus, and Publius Vergilius Maro, the poet of the Aeneid and Caesar''s enchanter, has been summoned to the palace, where he will shortly die. Out of the last hours of Virgil''s life and the final stirrings of his consciousness, the Austrian writer Hermann Broch fashioned one of the great works of twentieth-century modernism, a book that embraces an entire world and renders it with an immediacy that is at once sensual and profound. Begun while Broch was imprisoned in a German concentration camp, The Death of Virgil is part historical novel and part prose poem -- and always an intensely musical and immensely evocative meditation on the relation between life and death, the ancient and the modern.', 'en', 1995, 496, 'http://books.google.com/books/content?id=-qg_DwAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
