INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c20323dc-b1ca-52f7-8bdf-e15fab2102e4', '9780679755524', 'The Son Avenger', 'n8YHAQAAMAAJ', 'Powerfully written and filled with magnificent vignettes of the daily life of a medieval estate, ''The Son Avenger'' suggests a Greek tragedy whose vision of fate coexists with a Christian sense of suffering and forgiveness. And in the somber, twilight figure of ''Olav the Bad, '' Undset has created an antihero as moving as Oedipus or Lear.', 'en', 1995, 288, 'http://books.google.com/books/content?id=n8YHAQAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
