INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7aecec68-4e62-5425-9f7e-dc7f4c8576dd', '9780679759256', 'When She was Good', 'Qsw1HwaanPcC', 'In this funny and chilling novel, the setting is a small town in the 1940s Midwest, and the subject is the heart of a wounded and ferociously moralistic young woman, one of those implacable American moralists whose "goodness" is a terrible disease. When she was still a child, Lucy Nelson had her alcoholic failure of a father thrown in jail. Ever since then she has been trying to reform the men around her, even if that ultimately means destroying herself in the process. With his unerring portraits of Lucy and her hapless, childlike husband, Roy, Roth has created an uncompromising work of fictional realism, a vision of provincial American piety, yearning, and discontent that is at once pitiless and compassionate.', 'en', 1995, 320, 'http://books.google.com/books/content?id=Qsw1HwaanPcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
