INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a3ba7d8e-dcbf-5a0c-a88d-485d190b5a9b', '9780679764175', 'Letting Go', '8D-0IVlkpL4C', 'Newly discharged from the Korean War, Gabe Wallach struggles to live seriously and act generously. The reader will find acclaimed author Philip Roth''s fictional study of 1950''s American morals and social mores far different from those of today. TIME calls Roth "The uncontested master of comic irony".', 'en', 1997, 630, 'http://books.google.com/books/content?id=8D-0IVlkpL4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
