INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('57b4a13f-ad21-5fc9-8d9c-d25079d132d8', '9780684800707', 'The Metamorphosis, in the Penal Colony and Other Stories', 'YTDxAQAACAAJ', 'Translated by PEN translation award-winner Joachim Neugroschel, The Metamorphosis, In the Penal Colony, and Other Stories has garnered critical acclaim and is widely recognized as the preeminent English-language anthology of Kafka''s stories. These translations illuminate one of this century''s most controversial writers and have made Kafka''s work accessible to a whole new generation. This classic collection of forty-one great short works -- including such timeless pieces of modern fiction as "The Judgment" and "The Stoker" -- now includes two new stories, "First Sorrow" and "The Hunger Artist."', 'en', 2000, 352, 'http://books.google.com/books/content?id=YTDxAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
