INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('01b6365d-d390-542d-b44f-67dfb57d4e94', '9780684804521', 'The Garden of Eden', 'tsOzjNzcvPcC', 'A sensational bestseller when it appeared in 1986, The Garden of Eden is the last uncompleted novel of Ernest Hemingway, which he worked on intermittently from 1946 until his death in 1961. Set on the Côte d''Azur in the 1920s, it is the story of a young American writer, David Bourne, his glamorous wife, Catherine, and the dangerous, erotic game they play when they fall in love with the same woman. "A lean, sensuous narrative...taut, chic, and strangely contemporary," The Garden of Eden represents vintage Hemingway, the master "doing what nobody did better" (R. Z. Sheppard, Time).', 'en', 1995, 248, 'http://books.google.com/books/content?id=tsOzjNzcvPcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
