INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b0da41f4-ebe8-5b2b-9cda-44296d3620eb', '9780684825106', 'The Promise of Rest', 'Y2I1lAEACAAJ', 'In this stunning and fully independent conclusion to A Great Circle, Reynolds Price tells the complex, moving story of a man''s return home to die of AIDS and of the unexpected effect that his arrival -- and his death -- has on his family. Wade Mayfield''s parents are separated, but for the remaining months of his life they and their friends come together to care for Wade with the love they can muster. They are unprepared, however, for the astonishing mystery Wade has prepared to reveal once he is gone -- a mystery that initiates the possible reunion of his parents and promises to continue the proud traditions of a complex, multiracial family.', 'en', 1996, 368, 'http://books.google.com/books/content?id=Y2I1lAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
