INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4689fbf9-6088-5d78-9cab-c1c5dd490358', '9780684826356', 'The Reawakening', '1SLMomBN0ZwC', 'First published in English in 1965, "The Reawakening" is Primo Levi''s bestselling sequel to his classic memoir of the Holocaust, "Survival in Auschwitz." The inspiring story of Levi''s liberation from the German death camp in January 1945 by the Red Army, it tells of his strange and eventful journey home to Italy by way of the Soviet Union, Hungary, and Romania. Levi''s railway travels take him through bombed-out cities and transit camps, with keen insight he describes the former prisoners and Russian soldiers he encounters along the way. An extraordinary account of faith, hope, and undying courage, "The Reawakening" was praised by Irving Howe as "a remarkable feat of literary craft."', 'en', 1995, 230, 'http://books.google.com/books/content?id=1SLMomBN0ZwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
