INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e762eef2-255f-5990-a7de-8e742c4c3377', '9780684830513', 'The Sun Also Rises', '_-KBsJuQaCgC', 'In the socially dislocated period after World War I, an American expatriate and a British peeress conduct a hopeless love affair.', 'en', 1996, 222, 'http://books.google.com/books/content?id=_-KBsJuQaCgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
