INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('30ca3578-030b-5d52-a74d-7ab8c365a85c', '9780684832401', 'The Denial of Death', 'wP9zAgAAQBAJ', 'Drawing from religion and the human sciences, particularly psychology after Freud, the author attempts to demonstrate that the fear of death is man''s central concern', 'en', 1997, 336, 'http://books.google.com/books/content?id=wP9zAgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
