INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f21cf3e3-71b4-585d-8779-617fe555893e', '9780684837932', 'A Calendar of Wisdom', 'mFb7wAEACAAJ', 'This is the first-ever English-language edition of the book Leo Tolstoy considered to be his most important contribution to humanity, the work of his life''s last years. Widely read in prerevolutionary Russia, banned and forgotten under Communism; and recently rediscovered to great excitement, A Calendar of Wisdom is a day-by-day guide that illuminates the path of a life worth living with a brightness undimmed by time. Unjustly censored for nearly a century, it deserves to be placed with the few books in our history that will never cease teaching us the essence of what is important in this world.', 'en', 1997, 384, 'http://books.google.com/books/content?id=mFb7wAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
