INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6c2ec412-0070-5d35-b2e7-402507ead8ea', '9780684841212', 'Something Happened', 'X-CILqF-RugC', 'Bob Slocum was living the American dream. He had a beautiful wife, three lovely children, a nice house...and all the mistresses he desired. He had it all -- all, that is, but happiness. Slocum was discontent. Inevitably, inexorably, his discontent deteriorated into desolation until...something happened. Something Happened is Joseph Heller''s wonderfully inventive and controversial second novel satirizing business life and American culture. The story is told as if the reader was overhearing the patter of Bob Slocum''s brain -- recording what is going on at the office, as well as his fantasies and memories that complete the story of his life. The result is a novel as original and memorable as his Catch-22.', 'en', 1974, 576, 'http://books.google.com/books/content?id=X-CILqF-RugC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
