INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f71ba812-1009-5334-b257-54ee597fa089', '9780684841250', 'God Knows', 'MGWhOTocVpQC', 'Joseph Heller''s powerful, wonderfully funny, deeply moving novel is the story of David -- yes, King David -- but as you''ve never seen him before. You already know David as the legendary warrior king of Israel, husband of Bathsheba, and father of Solomon; now meet David as he really was: the cocky Jewish kid, the plagiarized poet, and the Jewish father. Listen as David tells his own story, a story both relentlessly ancient and surprisingly modern, about growing up and growing old, about men and women, and about man and God. It is quintessential Heller.', 'en', 1997, 368, 'http://books.google.com/books/content?id=MGWhOTocVpQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
