INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bfdc7d64-b1c8-5c26-aa72-8ec77c0d074e', '9780684843322', 'The Complete Short Stories Of Ernest Hemingway', '27YWOGDIvNEC', 'THE ONLY COMPLETE COLLECTION BY THE NOBEL PRIZE-WINNING AUTHOR In this definitive collection of Ernest Hemingway''s short stories, readers will delight in the author''s most beloved classics such as "The Snows of Kilimanjaro," "Hills Like White Elephants," and "A Clean, Well-Lighted Place," and will discover seven new tales published for the first time in this collection. For Hemingway fans The Complete Short Stories is an invaluable treasury.', 'en', 1998, 650, 'http://books.google.com/books/content?id=27YWOGDIvNEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
