INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a1017cf0-bf63-58f2-bba1-a0d75b621add', '9780684844077', 'Soul of the Sword', 'eoEagVTujdcC', 'A sweeping illustrated history of war and the implements used to perpetrate it takes readers on a fascinating tour of humanity''s most persistant and destructive character trait and the technology that has been developed to promote warfare. 35,000 first printing.', 'en', 2002, 400, 'http://books.google.com/books/content?id=eoEagVTujdcC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
