INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('49f81b2e-a82e-5c53-916c-9d7e546d1550', '9780684846941', 'Kate Vaiden', '13k-lQEACAAJ', '0ne of the most feisty, spellbinding and engaging heroines in modern fiction captures the essence of her own life in this contemporary American odyssey born of red-clay land and small-town people. We meet Kate at a crucial moment in middle age when she begins to yearn to see the son she abandoned when she was seventeen. But if she decides to seek him, will he understand her? Winner of the National Book Critics Circle Award, Kate Vaiden is a penetrating psychological portrait of an ordinary woman in extraordinary circumstances, a story as joyous, tragic, comic and compelling as life itself.', 'en', 1998, 306, 'http://books.google.com/books/content?id=13k-lQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
