INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('60253113-cfbf-574f-a90e-a489f33bd923', '9780684865522', 'No Heroes', 'fE3tUcY6yRgC', 'The author of The Same River Twice recalls his painful but ultimately revealing attempt to return home to the rural hills of Kentucky to give back to his hometown community and to record the personal story of his parents-in-law, Holocaust survivors who had emigrated from Poland in 1946. Reprint.', 'en', 2003, 272, 'http://books.google.com/books/content?id=fE3tUcY6yRgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
