INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('98b33b1a-b8f6-5e42-9bcb-8fae474417f3', '9780688090258', 'Worlds enough and time', '6HMhAQAAIAAJ', 'In the last volume of the parable of Earth''s destruction and humanity''s doomed flight from it, Mariane O''Hara frantically records the lives of her family and contemporaries when most of the earth''s history and literature is wiped out from computer banks.', 'en', 1992, 332, 'http://books.google.com/books/content?id=6HMhAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
