INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('627f3e0c-c715-51c1-9db8-5eeba3b57303', '9780688093686', 'The first man in Rome', 'kMRmPpDKdUgC', 'A story tracing the creation of Republican Rome presents those who founded an empire, including Marius and Sulla, each determined to become the First Man of Rome', 'en', 1990, 896, 'http://books.google.com/books/content?id=kMRmPpDKdUgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
