INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('27896b3d-43b9-56f0-9318-e0369b6ee58b', '9780688143923', 'The Twelve Dancing Princesses', '03BIrNldt1YC', 'For generations, children have loved the enchanting story of the twelve beautiful princesses and the handsome young lad who solves the mystery of their tattered shoes. Now Marianna Mayer brings to life all the splendor and romance of this beloved classic, from the dazzling forests Of silver, gold, and diamonds to a twilight palace where the bewitched princesses dance to hypnotic music. And award-winning artist Kinuko Craft add, her own magic: a visual feast of exquisite, jewel-like paintings that sweep across the pages. Together, Mayer and Craft have created an unforgettable world that readers of all ages will want to return to again and again.', 'en', 1998, 40, 'http://books.google.com/books/content?id=03BIrNldt1YC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4156', 'accepted', 'Marianna Mayer', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 0 FROM public.book WHERE isbn13 = '9780688143923' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ae3d4c6b-027b-5d6c-9508-7ff7740e8eb3', '9780688149895', 'Love Poems', 'rY3IlgEACAAJ', 'In a career that has spanned more than a quarter century, Nikki Giovanni has earned the reputation as one of America''s most celebrated and contoversial writers.Now, she presents a stunning collection of love poems that includes more than twenty new works. From the revolutionary "Seduction" to the tender new poem, "Just a Simple Declaration of Love," from the whimsical "I Wrote a Good Omelet" to the elegiac "All Eyez on U," written for Tupac Shakur, these poems embody the fearless passion and spirited wit for which Nikki Giovanni is beloved and revered. Romantic, bold, and erotic, Love Poems expresses notions of love in ways that are delightfully unexpected. Articulating in sensuous verse what we know only instinctively, Nikki Giovanni once again confirms her place as one of our nations''s most distinguished poets and powerful truth-tellers. In a career that has spanned more than a quarter century, starting with her explosive early years in the Black Rights Movement, Nikki Giovanni has earned a reputation as one of America''s most celebrated and controversial writers. Her mind-speaking work has made her a universal favorite and a number-one best-seller.The love poems-the revolutionary "Seduction," the whimsical "I Wrote a Good Omelet," and the tender "My House" to name just a few-are among the most beloved of all Nikki Giovanni''s works. Now, Love Poems brings together these and other favorites with over twenty new poems. Romantic, bold, and erotic, Love Poems will once again confirm Nikki Giovanni''s place among the country''s most renowned poets and truth tellers.', 'en', 1997, 96, 'http://books.google.com/books/content?id=rY3IlgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4157', 'accepted', 'Nikki Giovanni', 'Poetry', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 4 FROM public.book WHERE isbn13 = '9780688149895' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fd9a4bf3-0a5d-5086-be3d-0d9ab3117e77', '9780688151324', 'Behind a Mask', 'Hi0dRWdAhq0C', 'Six years before she wrote Little Women, Louisa May Alcott, in financial straits, entered "Pauline''s Passion and Punishment," a novelette, in a newspaper contest. Not only did it win the $100 prize, but, published anonymously, it marked the first in the series of "blood & thunder tales" that would be her livelihood for years. In Behind a Mask, editor Madeleine Stern introduces four Alcott thrillers: "Pauline''s Passion and Punishment," "The Mysterious Key," "The Abbot''s Ghost," and the title story, "Behind a Mask." First published in one volume in 1975, they are regarded as Alcott''s finest work in this genre.', 'en', 1997, 281, 'http://books.google.com/books/content?id=Hi0dRWdAhq0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4158', 'accepted', 'Louisa May Alcott', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 17 FROM public.book WHERE isbn13 = '9780688151324' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e087647b-94db-57a7-9e53-7319bec1eeef', '9780688152024', 'NYC Ballet Workout', 'eB47sy06bEcC', 'New York City Ballet Workout is a revolutionary fitness program that will help you begin to develop lean abs, firm buttocks, a contoured waist, sculpted legs, slim thighs, strong arms, perfect posture, flexbility you never thought possible--and grace and poice of a dancer. More than three hundred stunning step-by-step and other photographs throughout make this the most beautiful and easy-to-use exercise book ever created.This elegant book is unlike any exercise book ever published. Graced with more than 300 instructional exercise photographs and extraordinary duotone portraits of New York City Ballet dancers, The New York City Ballet Workout explores the company''s philosophy of balancing art, life, and fitness. By combining elements of New York City Ballet''s balletic regimen with practical strength-building exercises, The New York City Ballet Workout can help people achieve a strong, graceful, and flexible body--one that displays the impeccable poise that is the trademark of New York City Ballet dancers. Many exercises of The New York City Ballet Workout were once confined to the world''s elite rehearsal studios. Now, as refined by Peter Martins and his company, these exercises have been designed as a comprehensive, holistic approach to the body that can be used by anyone from the out-of-shape to the serious athlete, to attain a lean, hard, beautiful body. From flexibility to endurance, this is a complete exercise program for men and women.', 'en', 1997, 208, 'http://books.google.com/books/content?id=eB47sy06bEcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4159', 'accepted', 'Peter Martins', 'Health & Fitness', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 1 FROM public.book WHERE isbn13 = '9780688152024' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bc2869f4-7b69-5060-982f-e6131284b257', '9780688153878', 'Kevin Trudeau''s Mega Memory', 'nI4pXULkI6UC', 'Do you think you have a "bad memory"? Impossible, says Kevin Trudeau, the world''s foremost authority on memory improvement training. There are no bad memories, only untrained memories. In order to release our natural memory, Trudeau says, we just need to learn to retrieve what we already know. As founder of the American Memory Institute, Kevin Trudeau has already helped more than one million people do just that. Each Mega Memory lesson in this book takes no more than thirty minutes per day and uses pictures, rather than the laborious word-association techniques of other memory systems, to activate our inborn memory. With this easy-to-follow system, you''ll be able to instantly remember names, phone numbers, addresses, financial data, speeches, and schoolwork. Even better, Trudeau''s system ensures instant recall and long-term Mega Memory. All you need is the desire to unleash your Mega Memory, and you can reap all these incredible rewards! Labeled with a learning disability at an early age, Kevin Trudeau was convinced his problem was an inability to recall information. He read everything he could on memory improvement. Eventually, he developed his own program for memory retrieval and formed the American Memory Institute. His Mega Memory home study system is the most utilized self-improvement series of all time.', 'en', 1997, 368, 'http://books.google.com/books/content?id=nI4pXULkI6UC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4160', 'accepted', 'Kevin Trudeau', 'Self-Help', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 2 FROM public.book WHERE isbn13 = '9780688153878' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d1737c95-f70e-5872-8249-bb17acf28935', '9780688154721', 'Chester''s Way', 'FFUb6SyP8dEC', 'Chester and Wilson had their own way of doing things, and they did everything together. When they cut their sandwiches, it was always diagonally. When they rode their bikes, they always used hand signals. If Chester was hungry, Wilson was too. They were two of a kind, and that''s the way it was - until indomitable Lilly, who had her own way of doing things, moved into the neighborhood.', 'en', 1997, 32, 'http://books.google.com/books/content?id=FFUb6SyP8dEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4161', 'accepted', 'Kevin Henkes', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 3 FROM public.book WHERE isbn13 = '9780688154721' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5fdc4c5b-dd86-5142-9d48-0c130824f5ac', '9780688166250', 'The Purpose of Your Life', 'J_DExV9GGmAC', 'The co-author of The Celestine Prophecy Experiential Guide helps readers uncover the unsuspected, untapped power of synchronicity and intuition that will bring success, satisfaction, and serenity. Everyone really has a purpose in life, says Carol Adrienne in her new guide to harnessing the power inside yourself. The question is: How do you learn to go with the flow and let your true nature guide you? Chapter by chapter, The Purpose of Your Life explains how to locate the source of your innate energy and focus it, how to align yourself with the natural forces that swirl around us always, and how to develop the intuition that fosters synchronicity. The book is packed with illuminating anecdotes and profiles of fascinating people -- from artists to urban planners to Zen masters -- who describe how they found their own purposes. There are practical exercises throughout, along with charts, self-questionnaires, and other tools that help you understand yourself and your deepest aspirations. As you learn to recognize and trust the voice of intuition, you''ll find new doors opening and new possibilities everywhere. You''ll feel invigorated by the potential you''ve unleashed, a power that will only grow with each new accomplishment. And you''ll discover the serenity and satisfaction that come only to those who are living life to the fullest. The Force is with you -- all you have to do is reach out and start to use it.', 'en', 1999, 320, 'http://books.google.com/books/content?id=J_DExV9GGmAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4162', 'accepted', 'Carol Adrienne', 'Body, Mind & Spirit', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 14 FROM public.book WHERE isbn13 = '9780688166250' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('308523c5-f919-52b2-8ff3-1793c2aa468c', '9780688171629', 'Naked Pictures of Famous People', 'Y3mpejO-RDAC', 'In these nineteen whip-smart essays, Jon Stewart takes on politics, religion, and celebrity with a seethingly irreverent wit, a brilliantsense of timming, and a palate for the obsurd -- and these one-of-a-kind forays into his hilarious world will expose you to all its wickedly naked truths. He''s the MTV generation''s master of modern humor, a star of film, TV, and the comedy stage. This sultan of savvy serves up a whip-smart, utterly original collection of comic essays in Naked Pictures of Famous People. And as of January 11, 1999, you can enjoy the intelligence and self-deprecating charm he brings to contemporary comedy on Comedy Central''s "The Daily Show." In his first book, he translates that unique talent to the page, with humorous forays into a vast array of subjects: fashion, urban life, fast cars, cocktail culture, modern Jewishness, politics, and dating. A seethingly irreverent wit, Stewart has a genius for language and brilliant timing that makes his up-to-the-minute collection a must-have for humor lovers in search of a Woody Allen for the 90s.He''s the MTV generation''s master of modern humor, a star of film, TV, and the comedy stage. This sultan of savvy serves up a whip-smart, utterly original collection of comic essays in Naked Pictures of Famous People. And as of January 11, 1999, you can enjoy the intelligence and self-deprecating charm he brings to contemporary comedy on Comedy Central''s "The Daily Show." In his first book, he translates that unique talent to the page, with humorous forays into a vast array of subjects: fashion, urban life, fast cars, cocktail culture, modern Jewishness, politics, and dating. A seethingly irreverent wit, Stewart has a genius for language and brilliant timing that makes his up-to-the-minute collection a must-have for humor lovers in search of a Woody Allen for the 90s.', 'en', 1999, 164, 'http://books.google.com/books/content?id=Y3mpejO-RDAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4163', 'accepted', 'Jon Stewart', 'Humor', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 1 FROM public.book WHERE isbn13 = '9780688171629' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0ba4d39c-6e59-53b3-ba5b-ca5d81f358e3', '9780688172176', 'Phantoms in the Brain', 'TMnuNquN2RgC', 'Neuroscientist V.S. Ramachandran is internationally renowned for uncovering answers to the deep and quirky questions of human nature that few scientists have dared to address. His bold insights about the brain are matched only by the stunning simplicity of his experiments -- using such low-tech tools as cotton swabs, glasses of water and dime-store mirrors. In Phantoms in the Brain, Dr. Ramachandran recounts how his work with patients who have bizarre neurological disorders has shed new light on the deep architecture of the brain, and what these findings tell us about who we are, how we construct our body image, why we laugh or become depressed, why we may believe in God, how we make decisions, deceive ourselves and dream, perhaps even why we''re so clever at philosophy, music and art. Some of his most notable cases: A woman paralyzed on the left side of her body who believes she is lifting a tray of drinks with both hands offers a unique opportunity to test Freud''s theory of denial. A man who insists he is talking with God challenges us to ask: Could we be "wired" for religious experience? A woman who hallucinates cartoon characters illustrates how, in a sense, we are all hallucinating, all the time. Dr. Ramachandran''s inspired medical detective work pushes the boundaries of medicine''s last great frontier -- the human mind -- yielding new and provocative insights into the "big questions" about consciousness and the self.', 'en', 1999, 352, 'http://books.google.com/books/content?id=TMnuNquN2RgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4164', 'accepted', 'V. S. Ramachandran', 'Medical', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 14 FROM public.book WHERE isbn13 = '9780688172176' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('333a0f42-c837-544e-a0c7-d4b2f3ec3310', '9780688172244', 'The Lost Tomb', 'wbcRHAAACAAJ', 'Kent Weeks made international headlines when, seventy feet below the surface of Egypt''s Valley of the Kings he found the largest and most complicated mausoleum yet discovered, the tomb of Ramesses II''s sons. Now for the first time, Weeks shares up-to-the-minute details on the thrilling discovery and contemplates what the tomb, called KV5, will reveal as the excavation moves forward. Built in the age of Exodus, the tomb could potentially transform ancient and biblical history. Its lower levels, possibly containing mummies of Ramesses II''s sons, may shed new light on many of the mysteries of the Old Testament, including the story of Moses and the flight of the Israelites from Egypt. Weeks draws on his own diaries, as well as those of his wife and his foreman, to describe the excitement and risks that surround such a significant find. From floodwaters that threatened the opened tomb and the precarious craw spaces deep within it, to thieving tourists and scorpions, this adventure is not for the weak of heart. Photographs and sketches illustrate the crew''s progress and the objects and decorations found in the tomb''s chambers and hallways The result a true-life, impossibly thrilling Raiders of the Lost Arkwill entrance readers from beginning to end.', 'en', 1999, 384, 'http://books.google.com/books/content?id=wbcRHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4165', 'accepted', 'Kent R. Weeks', 'Social Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 5 FROM public.book WHERE isbn13 = '9780688172244' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2b748142-68d3-5579-8ddb-4ab9dd7ed940', '9780689707490', 'Cloudy With a Chance of Meatballs', 'fQU6UrNfe4MC', 'The beloved, bestselling tale of edible weather is brought to life! If food dropped like rain from the sky, wouldn''t it be marvelous! Or would it? It could, after all, be messy. And you''d have no choice. What if you didn''t like what fell? Or what if too much came? Have you ever thought of what it might be like to be squashed flat by a pancake?', 'en', 1982, 32, 'http://books.google.com/books/content?id=fQU6UrNfe4MC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
