INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('debb3a90-3114-5303-abcd-c94a639fb184', '9780689716041', 'The Bears on Hemlock Mountain', '2gt4hQwGJOcC', 'An eight-year-old boy who is frightened of traveling over Hemlock Mountain overcomes his fear by taking the trip while chanting, "There are no bears on Hemlock Mountain," in a suspenseful tale. Reissue.', 'en', 1992, 64, 'http://books.google.com/books/content?id=2gt4hQwGJOcC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
