INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a24408d8-cbb2-52ea-98db-c6808265100a', '9780689718762', 'The Fourth of July Story', '_gaVAAAACAAJ', 'Two-time Newbery Honor author Alice Dalgliesh makes history come alive in this accessible story of America''s birthday. Full color.', 'en', 1995, 32, 'http://books.google.com/books/content?id=_gaVAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
