INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('03e642c7-9c9b-5ff0-8f70-2cc4029e2cab', '9780689802171', 'My Name Is Maria Isabel', 'HntuDZ95FnwC', 'Third grader Marâia Isabel, born in Puerto Rico and now living in the United States, wants badly to fit in at school; and the teacher''s writing assignment "My Greatest Wish" gives her that opportunity.', 'en', 1995, 64, 'http://books.google.com/books/content?id=HntuDZ95FnwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
