INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c2fbd4f6-bb93-5112-b985-e94a30cc0199', '9780689822841', 'Hitty Her First Hundred Years', 'tyLHV3_ov0kC', 'Hitty is a doll of great charm and character. It is indeed a privilege to publish her memoirs, which, besides being full of the most thrilling adventures on land and sea, also reveal her delightful personality. One glance at her portrait will show that she is no ordinary doll. Hitty, or Mehitable as she was really named, was made in the early 1800s for Phoebe Preble, a little girl from Maine. Young Phoebe was very proud of her beautiful doll and took her everywhere, even on a long sailing trip in a whaler. This is the story of Hitty''s years with Phoebe, and the many that follow in the life of a well-loved doll.', 'en', 1998, 256, 'http://books.google.com/books/content?id=tyLHV3_ov0kC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
