INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('411f8397-28d1-5917-a22d-6edfa1e4b5d4', '9780689823824', 'A Child''s Garden of Verses', 'luTZAAAAMAAJ', 'Here is a delightful look at childhood, written by master poet and storyteller Robert Louis Stevenson. In this collection of sixty-six poems, Stevenson recalls the joys of his childhood, from sailing boats down a river, to waiting for the lamplighter, to sailing off to foreign lands in his imagination. Tasha Tudor''s watercolor paintings evoke a simpler time in the past, and celebrate two of the things she loves most -- children and nature. Her talents are the perfect match for these inspiring poems, making this a handsome gift edition that will be cherished by families for generations.', 'en', 1999, 67, 'http://books.google.com/books/content?id=luTZAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4171', 'accepted', 'Robert Louis Stevenson', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 7 FROM public.book WHERE isbn13 = '9780689823824' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d726d9d3-b2a6-5755-82a0-a83ca69e5532', '9780689833762', 'Sad Underwear and Other Complications', 'e-sEAAAACAAJ', 'Knock, knock. Who''s there? Someone with sad underwear. Sad underwear? How can that be? When my best friend''s mad at me, Everything is sad. Even my underwear. Only Judith Viorst, with the perfect pitch for the trials of childhood that has made her Alexander books modern classics, could create an ode to melancholy unmentionables. But the title poem is just one of the many pleasures in this collection, which bursts with wit and understanding -- and the occasional poignant note. Sure to delight readers of Shel Silverstein and Jack Prelutsky, as well as Viorst''s own legions of fans, Sad Underwear is a perfect companion volume to her celebrated If I Were In Charge of the World.', 'en', 2000, 80, 'http://books.google.com/books/content?id=e-sEAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
