INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e444681b-38df-5bca-826f-6acccb063a76', '9780689849121', 'Voting Rights Days', 'ZjagAAAACAAJ', 'Set in 1916, Hitty''s owner is the daughter of a suffragist and so is able to witness up-close the political struggles involved in getting women their right to vote. Reader''s Guide available. Simultaneous.', 'en', 2002, 75, 'http://books.google.com/books/content?id=ZjagAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
