INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5b144f6c-b8ba-5bbc-85e9-9359cd59d579', '9780689851131', 'Who Wants a Cheap Rhinoceros?', '70LqAAAACAAJ', 'Shel Silverstein Who wants a cheap Rhinoceros? Looking for a new pet? Bored with cats, dogs, goldfish, gerbils, and hamsters? How about a cheap rhinoceros? Shel Silverstein''s loving look at the joys of rhino ownership may convince you to be the one lucky kid to take home this very, very unusual pet.', 'en', 2002, 64, 'http://books.google.com/books/content?id=70LqAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
