INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b5e1161d-171d-584b-8f06-079cf578624c', '9780689851902', 'What a Scare, Jesse Bear', 'VGgCAAAACAAJ', 'Jesse Bear has a wonderful time getting ready for Halloween. He loves carving pumpkins and trying on costumes. But when it comes time for trick-or-treating, Jesse gets scared. With his parents by his side, Jesse soon builds up the courage to put on his scary mask -- and even plays a trick of his own!', 'en', 2012, 32, 'http://books.google.com/books/content?id=VGgCAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
