INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e74a30f8-54e0-5d4f-a7e5-730b440678d4', '9780689873195', 'The Au Pairs', 'ydhKP0xSPc4C', 'Three girls with three agendas and the ultimate destination: the Hamptons. Summer in the city? Way overrated. Everybody who''s anybody in New York City summers in the Hamptons. Mara, Eliza, and Jacqui all want a piece of the action, all for different reasons. So the girls answer a classified ad to become au pairs. How bad can it be, watching a couple of kids on the beach all day? They''ve got the swank address, the sweet ride, and an all-access pass to the hottest social scene on the East Coast. It''s shaping up to be the summer of their lives.', 'en', 2005, 294, 'http://books.google.com/books/content?id=ydhKP0xSPc4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
