INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('20a35eff-0261-5c80-8086-bd4284b9dc95', '9780689874093', 'I Love Saturdays y domingos', '7NgEbt2Ds5kC', 'Saturdays and Sundays are very special days for the child in this story. On Saturdays, she visits Grandma and Grandpa, who come from a European-American background, and on Sundays -- los domingos -- she visits Abuelito y Abuelita, who are Mexican-American. While the two sets of grandparents are different in many ways, they also have a great deal in common -- in particular, their love for their granddaughter. While we follow our narrator to the circus and the pier, share stories from her grandparents'' pasts, and celebrate her birthday, the depth and joy of both cultures are conveyed in Spanish and English. This affirmation of both heritages will speak to all children who want to know more about their own families and ethnic backgrounds.', 'en', 2004, 32, 'http://books.google.com/books/content?id=7NgEbt2Ds5kC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
