INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0fef0679-f565-5f3c-b51a-4d9e9caf5180', '9780691013800', 'Sounds, Feelings, Thoughts', 'weA9DwAAQBAJ', 'Translated and Introduced by Magnus J. Krynski and Robert A. Maguire Regarded as one of the best representatives since World War II of the rich and ancient art of poetry in Poland, Wislawa Szymborska (1923-2012) is, in the translators'' words, "that rarest of phenomena: a serious poet who commands a large audience in her native land." The seventy poems in this bilingual edition are among the largest and most representative offering of her work in English, with particular emphasis on the period since 1967. They illustrate virtually all her major themes and most of her important techniques. Describing Szymborka''s poetry, Magnus Krynski and Robert Maguire write that her verse is marked by high seriousness, delightful inventiveness, a prodigal imagination, and enormous technical skill. She writes of the diversity, plenitude, and richness of the world, taking delight in observing and naming its phenomena. She looks on with wonder, astonishment, and amusement, but almost never with despair.', 'en', 1981, 232, 'http://books.google.com/books/content?id=weA9DwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
