INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('eae62077-6bd2-518a-9f2a-4c94c790f58d', '9780691020167', 'Philosophy and the Mirror of Nature', 'cxYFw3NkPMoC', 'Philosophy and the Mirror of Nature hit the philosophical world like a bombshell. Richard Rorty, a Princeton professor who had contributed to the analytic tradition in philosophy, was now attempting to shrug off all the central problems with which it had long been preoccupied. After publication, the Press was barely able to keep up with demand, and the book has since gone on to become one of its all-time best-sellers in philosophy. Rorty argued that, beginning in the seventeenth century, philosophers developed an unhealthy obsession with the notion of representation. They compared the mind to a mirror that reflects reality. In their view, knowledge is concerned with the accuracy of these reflections, and the strategy employed to obtain this knowledge--that of inspecting, repairing, and polishing the mirror--belongs to philosophy. Rorty''s book was a powerful critique of this imagery and the tradition of thought that it spawned. He argued that the questions about truth posed by Descartes, Kant, Hegel, and modern epistemologists and philosophers of language simply couldn''t be answered and were, in any case, irrelevant to serious social and cultural inquiry. This stance provoked a barrage of criticism, but whatever the strengths of Rorty''s specific claims, the book had a therapeutic effect on philosophy. It reenergized pragmatism as an intellectual force, steered philosophy back to its roots in the humanities, and helped to make alternatives to analytic philosophy a serious choice for young graduate students. Twenty-five years later, the book remains a must-read for anyone seriously concerned about the nature of philosophical inquiry and what philosophers can and cannot do to help us understand and improve the world.', 'en', 1980, 424, 'http://books.google.com/books/content?id=cxYFw3NkPMoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4210', 'accepted', 'Richard Rorty', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 12 FROM public.book WHERE isbn13 = '9780691020167' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d80b1b9c-97ab-5876-aae8-668e56222e43', '9780691020686', 'Images and Symbols', 'zeE9DwAAQBAJ', 'Mircea Eliade--one of the most renowned expositors of the psychology of religion, mythology, and magic--shows that myth and symbol constitute a mode of thought that not only came before that of discursive and logical reasoning, but is still an essential function of human consciousness. The author describes and analyzes some of the most powerful and ubiquitous symbols that have ruled the mythological thinking of people of the East and West in many times and at many levels of cultural development.', 'en', 1961, 192, 'http://books.google.com/books/content?id=zeE9DwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
