INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1b0fcead-f3a6-588d-8b43-e1edce1f7ad4', '9780691024714', 'Vladimir Nabokov', 'C8lF4iqAgRQC', 'The story of Nabokov''s life continues with his arrival in the United States in 1940. He found that supporting himself and his family was not easy--until the astonishing success of Lolita catapulted him to world fame and financial security.The story of Nabokov''s life continues with his arrival in the United States in 1940. He found that supporting himself and his family was not easy--until the astonishing success of Lolita catapulted him to world fame and financial security.', 'en', 1991, 800, 'http://books.google.com/books/content?id=C8lF4iqAgRQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
