INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('17f0e04b-33f5-5929-b85f-3ba8b5e0b11b', '9780691027494', 'The Rise of Christianity', 'HcFSaGvgKKkC', 'Rodney Stark, a sociologist by training, has written a book that should end much of the Christian-bashing occuring in academia. Stark demonstrates that Christianity became popular very quickly because it offered its adherents a better faith than competing religions and treated those believers better both physically and spiritually.', 'en', 1996, 246, 'http://books.google.com/books/content?id=HcFSaGvgKKkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
