INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1e405273-755a-5669-87e8-2836b7d3d55c', '9780691037387', 'Making Democracy Work', '6hpoGGrHH-oC', 'Why do some democratic governments succeed and others fail? In a world full of hope for democratization but wary of government failure, this book offers empirical evidence for the importance of civic community in developing successful institutions. As part of a unique experiment begun in 1970 when Italy created new governments for each of its regions - regions that vary greatly from the standpoint of wealth, social structure, and political leanings - Robert Putnam and his collaborators spent two decades evaluating the performance of these governments in such fields as agriculture, housing, and health services. Their findings were surprising: regions that enjoy effective government in the 1990s have inherited a legacy of civic engagement that can be traced back to the early Middle Ages. Just as Tocqueville traveled to America to try to understand democracy, Putnam and his colleagues draw broad lessons for democratic theory from their twenty-year journey through Italy. Their conclusions challenge the simple-minded thesis of the primacy of economics and the easy optimism of social engineers. Based on dozens of case studies and thousands of interviews with politicians, community leaders, and ordinary citizens, this book illuminates patterns of associationism, trust, and cooperation that facilitate good governance and economic prosperity. It also contributes to the discussion of democracy in the newly freed lands of Eurasia and the developing world and to the gathering debate about how to revitalize democracy in America.', 'en', 1993, 280, 'http://books.google.com/books/content?id=6hpoGGrHH-oC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4215', 'accepted', 'Robert D. Putnam; Robert Leonardi; Raffaella Nanetti', 'Political Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 8 FROM public.book WHERE isbn13 = '9780691037387' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('04088aa5-4011-5302-9391-e810b5ed4b6e', '9780691037790', 'Multiculturalism', 'vjxwzLGTFJYC', 'A new edition of the highly acclaimed book Multiculturalism and "The Politics of Recognition," this paperback brings together an even wider range of leading philosophers and social scientists to probe the political controversy surrounding multiculturalism. Charles Taylor''s initial inquiry, which considers whether the institutions of liberal democratic government make room--or should make room--for recognizing the worth of distinctive cultural traditions, remains the centerpiece of this discussion. It is now joined by Jürgen Habermas''s extensive essay on the issues of recognition and the democratic constitutional state and by K. Anthony Appiah''s commentary on the tensions between personal and collective identities, such as those shaped by religion, gender, ethnicity, race, and sexuality, and on the dangerous tendency of multicultural politics to gloss over such tensions. These contributions are joined by those of other well-known thinkers, who further relate the demand for recognition to issues of multicultural education, feminism, and cultural separatism. Praise for the previous edition:', 'en', 1994, 192, 'http://books.google.com/books/content?id=vjxwzLGTFJYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
