INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e9a0a06f-9242-5f9f-8a1b-c70aab5f2ef1', '9780691050843', 'The Nature of Space and Time', 'LstaQTXP65cC', 'Presents a series of lectures delivered in 1994 by Hawking and Penrose, renowned professors at Cambridge and Oxford, respectively, on the general topic of how mathematical physics might best represent the realities of the universe.', 'en', 2000, 152, 'http://books.google.com/books/content?id=LstaQTXP65cC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
