INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('06f78018-7cd8-5d13-b8ca-fffe892a5049', '9780691102573', 'Hamlet in Purgatory', 'G1d_Cq5Yfp8C', 'Stephen Greenblatt sets out to explain his longtime fascination with the ghost of Hamlet''s father, and his daring and ultimately gratifying journey takes him through surprising intellectual territory. It yields an extraordinary account of the rise and fall of Purgatory as both a belief and a lucrative institution--as well as a capacious new reading of the power of Hamlet. In the mid-sixteenth century, English authorities abruptly changed the relationship between the living and dead. Declaring that Purgatory was a false "poem," they abolished the institutions and banned the practices that Christians relied on to ease the passage to Heaven for themselves and their dead loved ones. Greenblatt explores the fantastic adventure narratives, ghost stories, pilgrimages, and imagery by which a belief in a grisly "prison house of souls" had been shaped and reinforced in the Middle Ages. He probes the psychological benefits as well as the high costs of this belief and of its demolition. With the doctrine of Purgatory and the elaborate practices that grew up around it, the church had provided a powerful method of negotiating with the dead. The Protestant attack on Purgatory destroyed this method for most people in England, but it did not eradicate the longings and fears that Catholic doctrine had for centuries focused and exploited. In his strikingly original interpretation, Greenblatt argues that the human desires to commune with, assist, and be rid of the dead were transformed by Shakespeare--consummate conjurer that he was--into the substance of several of his plays, above all the weirdly powerful Hamlet. Thus, the space of Purgatory became the stage haunted by literature''s most famous ghost. This book constitutes an extraordinary feat that could have been accomplished by only Stephen Greenblatt. It is at once a deeply satisfying reading of medieval religion, an innovative interpretation of the apparitions that trouble Shakespeare''s tragic heroes, and an exploration of how a culture can be inhabited by its own spectral leftovers.', 'en', 2002, 344, 'http://books.google.com/books/content?id=G1d_Cq5Yfp8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4221', 'accepted', 'Stephen Greenblatt', 'Drama', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 20 FROM public.book WHERE isbn13 = '9780691102573' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('85cc5788-4eb8-5dfd-893a-13231656c8f7', '9780691102962', 'The Two-Mile Time Machine', 'oSEQG31t2tIC', 'Provides an account of the 1990s research in Greenland that revealed a history of global climatic change, and suggests that "switches" and "dials" that control Earth''s climate may cause severe weather changes in the future.', 'en', 2002, 229, 'http://books.google.com/books/content?id=oSEQG31t2tIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
