INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5299da5a-b7d2-5bdf-b349-29b376676883', '9780691119427', 'Shamanism', 'OxCnDwAAQBAJ', 'Surveys the practice of Shamanism over two and a half millennia of human history, moving from the Shamanic traditions of Siberia and Central Asia--where Shamanism was first observed--to North and South America, Indonesia, Tibet, China, and beyond. Eliade illuminates the magico-religious life of societies that give primacy of place to the figure of the Shaman--at once magician and medicine man, healer and miracle-doer, priest, mystic, and poet.', 'en', 2004, 610, 'http://books.google.com/books/content?id=OxCnDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4223', 'accepted', 'Mircea Eliade', 'Body, Mind & Spirit', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 1 FROM public.book WHERE isbn13 = '9780691119427' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('51825a96-bb36-52e4-a0ab-ca8ffd4b73b0', '9780691120522', 'Hegel''s Preface to the Phenomenology of Spirit', 'woV2QgAACAAJ', 'This is a new translation, with running commentary, of what is perhaps the most important short piece of Hegel''s writing. The Preface to Hegel''s first major work, the Phenomenology of Spirit, lays the groundwork for all his other writing by explaining what is most innovative about Hegel''s philosophy. This new translation combines readability with maximum precision, breaking Hegel''s long sentences and simplifying their often complex structure. At the same time, it is more faithful to the original than any previous translation. The heart of the book is the detailed commentary, supported by an introductory essay. Together they offer a lucid and elegant explanation of the text and elucidate difficult issues in Hegel, making his claims and intentions intelligible to the beginner while offering interesting and original insights to the scholar and advanced student. The commentary often goes beyond the particular phrase in the text to provide systematic context and explain related topics in Hegel and his predecessors (including Kant, Spinoza, and Aristotle, as well as Fichte, Schelling, Hölderlin, and others). The commentator refrains from playing down (as many interpreters do today) those aspects of Hegel''s thought that are less acceptable in our time, and abstains from mixing his own philosophical preferences with his reading of Hegel''s text. His approach is faithful to the historical Hegel while reconstructing Hegel''s ideas within their own context.', 'en', 2005, 223, 'http://books.google.com/books/content?id=woV2QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
