INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7443f1da-44da-5b3e-9ba3-8bd367c70132', '9780713998948', 'America', 'IChOPwAACAAJ', 'American democracy is the world''s most beloved form of government, which is why so many other nations are eager for it to be imposed on them. But just what exactly is it? Jon Stewart and his fellow patriots from the Emmy-winning The Daily Show finally deliver the answer. They offer their insights into a unique system of government, dissecting its institutions, explaining its history and processes, and exploring the reasons why concepts like ''One man, one vote'', ''Government by the people'', and ''Every vote counts'' have become such popular urban myths. Includes such favourites as Ancient Rome: The First Republicans; The Founding Fathers: Young, Gifted and White; The President: King of Democracy; The Supreme Court: 18 Legs, Four Tits, One Mission; Running for Office: What Are You Thinking?; The Media: Can It Be Stopped?; The Future of Democracy: The Constitutional Robocracy and You', 'en', 2005, 228, 'http://books.google.com/books/content?id=IChOPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
