INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5f73760a-56d1-5b82-95a3-fc4e6f5ea045', '9780715629949', 'Euripides', 'km9iAAAAMAAJ', 'Iphigenia at Aulis dramatises the myth of Iphigenia, the young virgin sacrificed by her father Agamemnon at the start of the expedition against Troy. Produced at the end of the Peloponnesian war, it explores the breakdown of social norms which turns Greeks against Greeks, men against women, and condemns young brides to death. Pantelis Michelakis examines the mythological, socio-political and institutional context, the main themes and major issues in modern criticism, and ends with an outline of performance history and reception.', 'en', 2006, 144, 'http://books.google.com/books/content?id=km9iAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
