INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('388d90d6-b3dc-50f0-8444-3956ffedb4d2', '9780715633991', 'The Egyptologist', 'I_FyPwAACAAJ', 'The New York Times Bestseller Arrives In The UK; The Egyptologist is a witty, inventive, brilliantly constructed novel about an archaeologist obsessed with finding the tomb of an apocryphal king. This darkly comic labyrinth of a story opens on the desert plains of Egypt in 1922, then winds its way from the slums of Australia to the ballrooms of Boston by way of Oxford, the battlefields of the First World War, and a royal court in turmoil. Exploring issues of class, greed, ambition, and the very human hunger for eternal life, The Egyptologist is a triumph of narrative bravado.', 'en', 2005, 392, 'http://books.google.com/books/content?id=I_FyPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
