INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('931347bd-1ceb-50e1-8ce4-81cf0ba19db9', '9780716799566', 'Economics: European Edition', 'JgGyX4ocbjcC', 'Economics: European Edition is the ideal text for introductory economics, bringing together an international scope of real world examples and economic theory. The text is supported by a number of features to enhance student understanding as well as supplements to consolidate the learning process.', 'en', 2007, 1088, 'http://books.google.com/books/content?id=JgGyX4ocbjcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
