INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('629005c8-688b-5ed7-a9f3-15e20c240865', '9780718132385', 'Banker', 'SGj1A5voN78C', 'It is difficult to say where disaster begins, to point towards one particular happening as the first definite step towards distant cataclysm. Looking back, Tim Ekaterin sees the beginning as the day his boss stepped into a fountain. Onwards from there, he comes across people and events as yet unconnected but which, when woven together by time and chance, leads towards violent explosive action and the threat of death. Set in the worlds of thoroughbred racing and merchant banking, the story covers a span of three years, growing from quiet harmless-seeming seeds to a wholly horrific harvest.', 'en', 2000, 288, 'http://books.google.com/books/content?id=SGj1A5voN78C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
