INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ab02b9fd-9921-5d5d-bd07-4241a9384f17', '9780718144463', 'Sushi for Beginners', '905hAQAACAAJ', 'Who will have the nervous breakdown? Will it be Clodagh who awaits her beautiful husband''s homecoming, or Lisa, hard and brittle and recently demoted? Or perhaps it will be Ashling who is so normal that she is actually weird.', 'en', 2000, 448, 'http://books.google.com/books/content?id=905hAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
