INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('134322d8-7fd7-5ed4-8a33-9fce98bbecc2', '9780719045783', 'Orientalism', 'Hwhwfod4rTEC', 'The Orientalism debate, inspired by the work of Edward Said, has been a major source of cross-disciplinary controversy. This work offers a re-evaluation of this vast literature of Orientalism by a historian of imperalism, giving it a historical perspective', 'en', 1995, 256, 'http://books.google.com/books/content?id=Hwhwfod4rTEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
