INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9fc7f171-c2b8-5786-9299-fc0fa21a07a5', '9780719071157', 'A Farewell to Arms?', 'G5wuwrmrdWoC', 'Neither naively optimistic nor hopelessley pessimistic, this collection of writings by experts on the history of the troubles in Northern Ireland paints a realistic picture of the peace processes that have dotted the province''s landscape.', 'en', 2006, 624, 'http://books.google.com/books/content?id=G5wuwrmrdWoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
