INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('23ee4a42-21ab-500b-afce-e5cc969cc8c5', '9780722540404', 'Mutant Message from Forever', 'yREnAAAACAAJ', 'From the bestselling author of ''Mutant Message Down Under'' comes a fabulous tale of aboriginal twins, separated at birth, and the search for their roots that takes them halfway across the world. Marlo Morgan weaves the entrancing story of babies Geoff and Beatrice, who are taken from their mother by Christian missionaries. Geoff is sent to a sheep ranch, where he grows up wild, and is then uprooted to the US by an American minister. Beatrice is brought up by nuns in an Australian orphanage where for 18 years she encounters continual racism. The story follows them as they grow into adults and eventually meet again, to discover the different paths their lives have taken. Eventually both twins are reunited with the ageless values and healing wisdom that is their Aboriginal heritage.', 'en', 2000, 323, 'http://books.google.com/books/content?id=yREnAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
