INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2c662822-15d1-541f-9554-75f81f1df2fd', '9780727861153', 'Desert Heat', 'YDFDPgAACAAJ', 'Life is good for Joanna Brady in the small desert community of Bisbee. She has Jenny, her adored nine-year-old daughter, and solid, honest, and loving husband, Andy, a local lawman who''s running for Sheriff of Cochise County. But her good life explodes when a bullet destroys Andy Brady''s future and leaves him dying beneath the blistering Arizona sun. The police brass claim that Andy was dirty -- up to his neck in drugs and smuggling -- and that the shooting was a suicide attempt.', 'en', 2004, 256, 'http://books.google.com/books/content?id=YDFDPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
