INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('30c80b7c-673d-5535-bc22-41ff7fdb02fa', '9780727862426', 'The Dark City', 'pu0SAAAACAAJ', 'After The Untouchables, Eliot Ness goes solo. In 1929, Eliot Ness put away Al Scarface Capone and became the biggest living legend this side of law and order. Now it''s 1935. With The Untouchables and Prohibition behind him and the Great Depression falling darkly across the nation, Ness arrives in Cleveland to straighten out a crooked city. An anonymous ring of bent cops is dealing in vice, graft, gambling and racketeering, overlorded by a mysterious top cop known as the outside chief. But between corrupt politicians, jealous colleagues, a parasitic reporter and two blondes with nothing in common, Ness has big troubles pulling the sheets off the bed of blue vipers. Until the outside chief makes a move, and Ness moves just a bit quicker.', 'en', 2005, 233, 'http://books.google.com/books/content?id=pu0SAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
