INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9f05f6b8-fb9b-5aea-a2dd-cf14ad7f903f', '9780736910194', 'Life Management for Busy Women', 'OdeIjgEACAAJ', 'Women eager to bring simplicity to their busy lives will embrace the principles presented in this exciting study guide based on Elizabeth George''s new Life Management for Busy Women. With clear and inspired steps for women eager to become better stewards of their time and their lives, this study guide complements all the major sections of the book, including: Spiritual Life: first things first Home Life: minding the stewardship of place Mental Life: minding your mind Easily adaptable to individual or group study, Life Management for Busy Women Growth and Study Guide will help women of all ages, in all stages of life, learn to see and follow God''s blueprint for their lives.', 'en', 2002, 166, 'http://books.google.com/books/content?id=OdeIjgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
