INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0496c53b-f16e-52ab-85b6-f08da39eb01f', '9780736910736', 'Simple Acts of Faith', 'hSnhJMi6TiQC', 'The beloved art of Normal Rockwell chronicles small-town America and reflects the simple kindnesses that paint ordinary life with shades of the extraordinary. This gathering of select Rockwell classics is joined by stories that illuminate acts of goodwill that transformed people''s lives: A cycle shop owner gives Lance Armstrong his first bike, and the rest is history. The young, hurting Frank Peretti is shown compassion that opens up his heart. One man''s sharing of faith changed the life of shoe salesman Dwight L. Moody. Norman Rockwell fans, Americana collectors, and those who cherish an uplifting look at life will treasure this celebration of family, community, and the goodness that overflows from the simplest acts of faith.', 'en', 2003, 48, 'http://books.google.com/books/content?id=hSnhJMi6TiQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
