INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('74d91b60-8c4f-59b0-b1e0-86e7c0d1cd0c', '9780738519388', 'Juneau and Sauk Counties', 'gMZrK2qNGIEC', 'Wild flowers and powerful rivers carved out the landscape, and the beauty of the Baraboo Bluffs touched the pioneers'' spirits. Ships full of immigrants plowed across the ocean, while dreams, faith, and courage helped families into the oxen-drawn wagons that carried them to Juneau and Sauk Counties. As the forces in their homelands pushed them toward south central Wisconsin, brother wrote to brother, mother to son, neighbor to former neighbor, bringing people from the same communities in the Old World to settle near each other in the new. Highway 12 in Sauk Prairie became known as Yankee Street, and Lyndon Station in Juneau County was called Irish Alley. Today, the counties are home to many popular tourist destinations, including Rocky Arbor State Park, Devil''s Lake, and the Wisconsin Dells. The images in these pages showcase photographs from family, community, and historical society collections.', 'en', 2002, 128, 'http://books.google.com/books/content?id=gMZrK2qNGIEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4282', 'accepted', 'Jacqueline Ann; Sheila Zenk', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 6 FROM public.book WHERE isbn13 = '9780738519388' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ea0ce315-aebb-50a2-9793-903d71446c31', '9780738528526', 'Sebastopol', 'AV7207YoIMMC', 'Since the 1850s, the soothing countryside hamlets of Sonoma County have beckoned settlers of every stripe-farmers, homesteaders, businesspeople, and commuters. Sebastopol has always been among the county''s loveliest towns, retaining its small-town feel even as its population has steadily grown. This book of vintage photography presents Sebastopol''s journey through time, the early Mexican land grants and initial settlements, Luther Burbank''s far-ranging botanical experiments, and the rich farming industry that made this town one of California''s premier agricultural zones, producing grapes, hops, cherries, and dairy products. In these pages readers will experience Sebastopol''s turn-of-the-century days at the Apple Fair, with its astonishing fruit sculptures. The first days of railroads are illustrated with images of the Petaluma & Santa Rosa Railway, an electric train system that took passengers to and from Sebastopol Depot. The architecture of the region and the stories of local businesses and institutions are all shown here, along with Sebastopol''s early religious institutions, schools, sawmills, factories, and even its small airport in the 1920s. Together with views of the town''s sporting teams, natural history, outlying communities, and important citizens, these photographs tell a unique story of a unique place that transcends the generations.', 'en', 2003, 128, 'http://books.google.com/books/content?id=AV7207YoIMMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4283', 'accepted', 'Western Sonoma County Historical Society', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 17 FROM public.book WHERE isbn13 = '9780738528526' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('017039b7-854b-5264-950b-2c56f836631c', '9780738539560', 'Lake Orion', 'OioLW2Hq3sQC', 'Orion Township, established in 1835, became a prosperous agrarian and resort community by the beginning of the 20th century. The village of Lake Orion developed as the center of commerce for township residents and a summer community of tourists and revivalists. Passenger boats and an amusement park popularized Lake Orion as a vacation destination with hotels and summer cottages. Suburban development has since transformed the landscape, but township signposts proudly display a vestige of the past: Orion Township, where living is a vacation. Orion Township, established in 1835, became a prosperous agrarian and resort community by the beginning of the 20th century. The village of Lake Orion developed as the center of commerce for township residents and a summer community of tourists and revivalists. Passenger boats and an amusement park popularized Lake Orion as a vacation destination with hotels and summer cottages. Suburban development has since transformed the landscape, but township signposts proudly display a vestige of the past: Orion Township, where living is a vacation.', 'en', 2006, 128, 'http://books.google.com/books/content?id=OioLW2Hq3sQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
