INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('efa728ff-53ce-5a8b-becd-84386686a498', '9780738544922', 'Center City Philadelphia in the 19th Century', 'svr39oWQq2MC', 'Philadelphia, as laid out in the 1680s, extended from the Delaware River to the Schuylkill River and from Vine Street to South Street, an area known today as Center City. As its population grew, the settled areas expanded westward from the Delaware River beyond early important landmarks such as Christ Church, the Pennsylvania State House, and Pennsylvania Hospital. By the mid-19th century, commercial, religious, and cultural institutions arose along Broad Street, and exclusive residential neighborhoods developed even farther west in areas previously undeveloped or used as industrial sites. Bustling shopping districts anchored by stores such as Wanamaker''s Grand Depot and Strawbridge and Clothier ran for blocks along Chestnut and Market Streets. Center City Philadelphia in the 19th Century highlights the buildings, people, and activities of this area from the 1840s until the end of the century.', 'en', 2006, 128, 'http://books.google.com/books/content?id=svr39oWQq2MC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4286', 'accepted', 'The Print and Photograph Department of the Library Company of Philadelphia', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 12 FROM public.book WHERE isbn13 = '9780738544922' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a41b4b0d-3ed9-5b52-9e1c-0ae7b3deb84b', '9780738546780', 'Selections from the Oakland Tribune Archives', 'zuHQJTSS4JwC', 'The landmark Oakland Tribune clock tower has been telling the time in neon in downtown Oakland since it was built in 1923, but the paper itself first appeared on city streets as early as 1874. For over a half century, the paper was owned and published by the influential and civic-minded Knowland family, who spearheaded efforts to modernize the Port of Oakland, construct the San Francisco Oakland Bay Bridge, and establish a regional park system for Alameda and Contra Costa Counties. Following the Loma Prieta earthquake, the damaged clock tower on Thirteenth Streetwhere Harry Houdini once hung by his heels above gawking crowds on Broadwaywas sadly vacant, but today it is once again busy with the buzz and bustle of the newsroom.', 'en', 2006, 128, 'http://books.google.com/books/content?id=zuHQJTSS4JwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
