INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('463dc4ba-3f47-52f6-a7e4-aa15aee08b81', '9780743203623', 'Jeeves And The Tie That Binds', 'yqHynP2B1VIC', 'After saving his master so often in the past, Jeeves may finally prove to be the unwitting cause of Bertie Wooster''s undoing when the Junior Ganymede, a club for butlers in London''s West End, requires its members to provide details about their employers. When information is inadvertently revealed to a dangerous source, it falls to Jeeves to undo the damage.', 'en', 2000, 205, 'http://books.google.com/books/content?id=yqHynP2B1VIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
