INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4eea447a-c8e1-581b-af08-d59eb5cb2425', '9780743203968', 'The Body Artist', 'PQdaAAAAYAAJ', 'A stunning novel by the bestselling National Book Award-winning author of White Noise and Underworld. Since the publication of his first novel Americana, Don DeLillo has lived in the skin of our times. He has found a voice for the forgotten souls who haunt the fringes of our culture and for its larger-than-life, real-life figures. His language is defiantly, radiantly American. In The Body Artist his spare, seductive twelfth novel, he inhabits the muted world of Lauren Hartke, an artist whose work defies the limits of the body. Lauren is living on a lonely coast, in a rambling rented house, where she encounters a strange, ageless man, a man with uncanny knowledge of her own life. Together they begin a journey into the wilderness of time, love and human perception. The Body Artist is a haunting, beautiful and profoundly moving novel from one of the finest writers of our time.', 'en', 2002, 128, 'http://books.google.com/books/content?id=PQdaAAAAYAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
