INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fd904ef5-ce20-5c29-b313-5eeb068da264', '9780743219570', 'Cover Her Face', 'oaIv9NpNXBIC', 'Headstrong and beautiful, the young housemaid Sally Jupp is put rudely in her place, strangled in her bed behind a bolted door. Coolly brilliant policeman Adam Dalgliesh of Scotland Yard must find her killer among a houseful of suspects, most of whom had very good reason to wish her ill. Cover Her Face is P. D. James''s electric debut novel, an ingeniously plotted mystery that immediately placed her among the masters of suspense.', 'en', 2001, 250, 'http://books.google.com/books/content?id=oaIv9NpNXBIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
