INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('78293b93-ef51-50c0-8a0d-c3927de1ddd2', '9780743222051', 'The Skull Beneath the Skin', 'i1JsQmfSsxQC', 'Combining the classic ingredients of a murder mystery with elements of horror, apparitions and hairbreadth episodes, "The Skull Beneath The Skin" creates a dark and claustrophobic atmosphere in a masterpiece of crime fiction. When leading actress Clarissa Lisle receives threats to her life the young detective, Cordelia Gray, is hired to accompany her to a private island where she is going to star in "The Duchess Of Malfi." In this gripping dramatization, the sharp-witted slueth, played by Greta Scaachi, finds herself in the enclosed setting of a chilling country house on an island with a blood-stained history.', 'en', 1982, 352, 'http://books.google.com/books/content?id=i1JsQmfSsxQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
