INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('391ff95e-1fd9-5f57-86fa-bb6ef31ec237', '9780743222983', 'Authentic Happiness', 'CM9tBAAAQBAJ', 'Argues that happiness can be a learned and cultivated behavior, explaining how every person possesses at least five of twenty-four profiled strengths that can be built on in order to improve life.', 'en', 2004, 336, 'http://books.google.com/books/content?id=CM9tBAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
