INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('646f6ac2-57c6-5c28-8bc4-49af44d81c94', '9780743223133', 'John Adams', 'mtBkcldvD3cC', 'The Pulitzer Prize–winning, bestselling biography of America’s founding father and second president that was the basis for the acclaimed HBO series, brilliantly told by master historian David McCullough. In this powerful, epic biography, David McCullough unfolds the adventurous life journey of John Adams, the brilliant, fiercely independent, often irascible, always honest Yankee patriot who spared nothing in his zeal for the American Revolution; who rose to become the second president of the United States and saved the country from blundering into an unnecessary war; who was learned beyond all but a few and regarded by some as “out of his senses”; and whose marriage to the wise and valiant Abigail Adams is one of the moving love stories in American history. This is history on a grand scale—a book about politics and war and social issues, but also about human nature, love, religious faith, virtue, ambition, friendship, and betrayal, and the far-reaching consequences of noble ideas. Above all, John Adams is an enthralling, often surprising story of one of the most important and fascinating Americans who ever lived.', 'en', 2002, 751, 'http://books.google.com/books/content?id=mtBkcldvD3cC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4327', 'accepted', 'David McCullough', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 3 FROM public.book WHERE isbn13 = '9780743223133' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2826457c-9dd1-5995-b7dd-be9cff0c8ec8', '9780743223850', 'Yanks', '4UjYAQAACAAJ', 'In the perfect match of subject and author, John S. D. Eisenhower, a noted military historian, presents the definitive account of the birth of the modern Amer- ican army and its decisive role in World War I. With the help of his wife Joanne, Eisenhower captures the viewpoints of the actual participants, blending a narrative told from the perspective of top officers with the stories of average soldiers. Drawing on diaries and memoirs, he brings each engagement to life, from the initial planning to the actual battlefield experiences of soldiers whose exploits at Belleau Woods and along the Meuse-Argonne would become the stuff of legend. Along the way, he shows how General Pershing and other leaders -- including George Marshall, Douglas MacArthur, George Patton, Billy Mitchell, and Peyton March -- transformed the American Expeditionary Force from a small, underequipped force into a strong, efficient, and effective army. Fast-paced, lively, and engaging, Yanks illuminates the central role of the American army in turning the tide in the biggest war the world had ever known.', 'en', 2002, 368, 'http://books.google.com/books/content?id=4UjYAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
