INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('39315728-f250-58e6-932b-088780436021', '9780743225083', 'Man and Boy', 'pM0UuyMT0sUC', 'Facing his thirtieth birthday with trepidation, Harry Silver watches his perfect life crumble around him when his wife leaves him and he must adjust to raising his son alone.', 'en', 2001, 368, 'http://books.google.com/books/content?id=pM0UuyMT0sUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
