INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4dcdf51d-db23-541c-95af-a0931be8531d', '9780743226721', 'Seventeen Seventy-six', 'R1Jk-A4R5AYC', 'Draws on personal correspondence and period diaries to present a history of the American Revolution that includes the siege of Boston, the American defeat at Brooklyn, the retreat across New Jersey, and the American victory at Trenton.', 'en', 2006, 386, 'http://books.google.com/books/content?id=R1Jk-A4R5AYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
