INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5e69d745-34d9-5c80-98c3-60e1c7fd1e67', '9780743227193', 'President Nixon', 'ajLBlZwwB0IC', 'PRESIDENT NIXON shows a man alone in a White House ruled by secrets and lies, trying to impose old values at home and new balances of power everywhere in the world. Reeves proves that the Watergate scandal was no abberation in an administration foreshadowed by a series of successful uses of ''national security'' to cover coups, burglaries, lies, the abandonment of America''s allies - and even murder. Reeves portrays a man of vision and iron will who created, used and was used by a small cast of hard, ambitious men who formed a poisonous circle around their insecure leader. Alone, Nixon challenged and changed the world''s political and military balance while also plotting to destroy both the Democratic and Republican parties in an attempt to create secretly a new party of the centre. This account of Nixon''s stewardship will stand as the balanced, authoratative portrait of an astonishng president and his ruined presidency.', 'en', 2002, 704, 'http://books.google.com/books/content?id=ajLBlZwwB0IC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4331', 'accepted', 'Richard Reeves', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 11 FROM public.book WHERE isbn13 = '9780743227193' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0ff8dd20-020f-594b-b620-c45fbafb6e67', '9780743227445', 'The Other Boleyn Girl', 'mx8-sy_e6r8C', 'The #1 New York Times bestseller from “the queen of royal fiction” (USA TODAY) Philippa Gregory is a rich, compelling novel of love, sex, ambition, and intrigue surrounding the Tudor court of Henry VIII, Anne Boleyn, and the infamous Boleyn family. When Mary Boleyn comes to court as an innocent girl of fourteen, she catches the eye of the handsome and charming Henry VIII. Dazzled by the king, Mary falls in love with both her golden prince and her growing role as unofficial queen. However, she soon realizes just how much she is a pawn in her family’s ambitious plots as the king’s interest begins to wane, and soon she is forced to step aside for her best friend and rival: her sister, Anne. With her own destiny suddenly unknown, Mary realizes that she must defy her family and take fate into her own hands. With more than one million copies in print and adapted for the big screen, The Other Boleyn Girl is a riveting historical drama. It brings to light a woman of extraordinary determination and desire who lived at the heart of the most exciting and glamorous court in Europe, and survived a treacherous political landscape by following her heart.', 'en', 2001, 661, 'http://books.google.com/books/content?id=mx8-sy_e6r8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
