INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bf9ce13f-70d9-5d0a-b9b8-f76a5b9bd002', '9780743231534', 'Shampoo Planet', 'j5apPwAACAAJ', 'Tyler Johnson is an apocalyptic entrepreneur in the making. His memories begin with Ronald Reagan. With his neat girlfriend, smart jokes and shampoo collection, he works at the nuclear power plant where his hippie parents used to demonstrate, plotting his fortune. But fortune has other plans - the return of a Paris summer fling, one of the ''low-ambition Euro-teens'', who takes Tyler on the road to the shimmering dreams of L.A.', 'en', 2002, 282, 'http://books.google.com/books/content?id=j5apPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
