INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6ec11dbf-7a90-5f30-91b0-d93349b81751', '9780743236140', 'Man and Wife', 'GFupHDzCyh4C', 'Harry Silver is ready to try again at living "happily ever after." It won''t be easy: not when he has to juggle his wife, his ex-wife, his son, his stepdaughter, his work, and his new wife''s fast-growing career. Did Harry commit to marriage to Cyd too soon after his split with Gina? Can you love -- really love -- a child who is not your own? Can you be a good father to a child you only see on the weekends? When Harry meets a woman who makes him question all these things and more, his tangled web becomes even more knotty. A brilliant sequel to the international bestseller Man and Boy, Tony Parsons'' Man and Wife is a story about families -- and love -- in the new century, written with his trademark humor, passion, and superb storytelling that have made millions across the globe laugh and cry.', 'en', 2002, 352, 'http://books.google.com/books/content?id=GFupHDzCyh4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
