INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('024b05a7-e93d-532d-a197-4bc4aef3ddbe', '9780743243827', 'Will You Miss Me When I''m Gone?', 'qTdns8tiSqUC', 'Traces the bluegrass country music achievements of the Carter family, from their discovery by a New York record maker to their rise to stardom and eventual breakup, noting their influence on the careers of top performers.', 'en', 2004, 432, 'http://books.google.com/books/content?id=qTdns8tiSqUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
