INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a42e43ff-93e4-5c77-b0f7-9d2d752fe480', '9780743244251', 'Cosmopolis', '4_ocfLBdl2kC', 'A brilliant billionaire asset manager, en route via white stretch limo to the local haircutter, finds his trip interrupted by a presidential motorcade, music idol''s funeral, movie set, and violent political demonstration, and receives a number of important visitors in the fields of security, technology, currency, finance, and theory. Reprint. 75,000 first printing.', 'en', 2004, 224, 'http://books.google.com/books/content?id=4_ocfLBdl2kC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
