INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('59907620-fed4-5ad3-aed7-faf91012905c', '9780743245920', 'The Boat of Dreams', 'KaAyuAAACAAJ', 'Stumbling upon an ornery old man in the trailer they call home, Lila and Will Foster, who have recently lost their father, realize that their visitor is Santa Claus, who grants them a Christmas wish--their father''s beautiful lobster boat.', 'en', 2003, 111, 'http://books.google.com/books/content?id=KaAyuAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
