INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fd6f3d12-7faf-5c13-b962-7d7c8659b8f3', '9780743249294', 'Wideacre', 'RAWLDgAAQBAJ', 'As an eighteenth-century Englishwoman without property rights, Beatrice Lacey is destined to lose what she loves most--her family''s ancestral estate of Wideacre--unless her ambitious schemes succeed. Reprint. 60,000 first printing.', 'en', 2003, 656, 'http://books.google.com/books/content?id=RAWLDgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
