INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cd90b1d5-8716-5de6-a708-d3aac847748e', '9780743249300', 'The Favored Child', 'Hla-lAEACAAJ', 'From #1 New York Times bestselling author and “queen of royal fiction” (USA TODAY) Philippa Gregory comes the thrilling sequel to the New York Times bestseller Wideacre as the once-great Lacey estate is restored to its former grandeur—though not without cost. The Wideacre estate is bankrupt. The villagers are living in poverty and formerly stunning hall is a smoke-blackened ruin. But, in the Dower House nearby, two children are being raised in protected innocence. Equal claimants to the estate, rivals for the love of the village, they are tied by a secret childhood betrothal but forbidden to marry. Only one can be the favored child—only one can inherit the magical understanding between the land and the Lacey family that can make the Sussex village grow green again. Only one can be Beatrice Lacey’s true heir. Sensual, gripping, and mystical, The Favored Child irresistibly sweeps the reader into a world of secrets, betrayals, and power in this revolutionary period of English history.', 'en', 2003, 624, 'http://books.google.com/books/content?id=Hla-lAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
