INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5b20c4b4-b5c6-540e-b440-7c0b755228e5', '9780743250443', 'Generation of Swine', 'hysRM1imbJ0C', 'The second volume of the Gonzo Papers comments on the television coverage of Hurricane Gloria, blood pressure machines, the Super Bowl, the hijinks of televangelists, the Iran Contra hearings, the 1988 Presidential race, and other topics, in a collection of cynical, provocative essays. Reprint. 20,000 first printing.', 'en', 2003, 336, 'http://books.google.com/books/content?id=hysRM1imbJ0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
