INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4a540171-8d9f-5f92-a763-6d480ca42fbe', '9780743252218', 'Sea of Thunder', 'je8dswEACAAJ', 'A suspenseful account of the Battle of Leyte Gulf in October 1944 is told through the commands of four naval leaders, including two American commanders and two Japanese admirals, and offers insight into how the war reflected profound cultural differences. 100,000 first printing.', 'en', 2006, 415, 'http://books.google.com/books/content?id=je8dswEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
