INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0d5bcfa0-9e3d-5efa-b840-dc4561fb2640', '9780743255783', 'Frankenstein', 'OB6cYGw12UAC', 'The story of Dr. Frankenstein and the obsessive experiment that leads to the creation of a monstrous and deadly creature is accompanied by 629 SAT vocabulary words highlighted and defined on pages opposite those of the text.', 'en', 2003, 448, 'http://books.google.com/books/content?id=OB6cYGw12UAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
