INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('85c94613-67d0-5cef-91d0-a3341ac306d3', '9780743260947', 'The Sleeping Doll', 'jtYeoK0ym14C', 'California Bureau of Investigation interrogator and body language expert Kathryn Dance works to recapture a dangerous escaped killer with the help of three victims from his former cult and the lone survivor from a family he slaughtered. By the author of The Bone Collector. 300,000 first printing.', 'en', 2007, 428, 'http://books.google.com/books/content?id=jtYeoK0ym14C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
