INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f258eeea-1ea4-596d-a90f-26e9d5247767', '9780743264730', 'Einstein', 'IMtGnwEACAAJ', 'The first full biography of Albert Einstein since all of his papers have become available shows how his scientific imagination sprang from the rebellious nature of his personality. Biographer Isaacson explores how an imaginative, impertinent patent clerk-', 'en', 2007, 675, 'http://books.google.com/books/content?id=IMtGnwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
