INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e56ee3b6-d601-5689-9c36-8a2ae091ccb7', '9780743264914', 'I Heard that Song Before', 'ujiZgSMzIBYC', 'Marrying the son of her father''s wealthy employer, twenty-eight-year-old gardener''s daughter Kay Lansing becomes increasingly disturbed by the suspicion surrounding her husband, Peter, in regard to the mysterious deaths of his first wife and a high-school senior. 1,000,000 first printing. Lit Guild, Doubleday, Mystery Guild, & BOMC Main.', 'en', 2007, 318, 'http://books.google.com/books/content?id=ujiZgSMzIBYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
