INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('85cd9bdc-7662-5dc8-86f2-b7ad66c8976e', '9780743267748', 'I''m Too Young To Be Seventy', 'SuPUwAEACAAJ', 'The beloved author of Forever Fifty and Suddenly Sixty tackles the ins and outs of becoming a septuagenarian with wry good humor. Fans of Viorst’s funny, touching, and wise decades poems will love these verses filled with witty advice and reflections on marriage, milestones, and middle-aged children. Viorst explores, among the many other issues of this stage of life, the state of our sex lives and teeth, how we can stay married though thermostatically incompatible, and the joys of grandparenthood and shopping. Readers will nod with rueful recognition when she asks, “Am I required to think of myself as a basically shallow woman because I feel better when my hair looks good?,” when she presses a few helpful suggestions on her kids because “they may be middle aged, but they’re still my children,” and when she graciously—but not too graciously—selects her husband’s next mate in a poem deliciously subtitled “If I Should Die Before I Wake, Here’s the Wife You Next Should Take.” Though Viorst acknowledges she is definitely not a good sport about the fact that she is mortal, her poems are full of the pleasures of life right now, helping us come to terms with the passage of time, encouraging us to keep trying to fix the world, and inviting us to consider “drinking wine, making love, laughing hard, caring hard, and learning a new trick or two as part of our job description at seventy.” I''m Too Young to Be Seventy is a joy to read and makes a heartwarming gift for anyone who has reached or is soon to reach that—it’s not so bad after all—seventh decade.', 'en', 2005, 64, 'http://books.google.com/books/content?id=SuPUwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4362', 'accepted', 'Judith Viorst', 'Humor', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 2 FROM public.book WHERE isbn13 = '9780743267748' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9d190757-42c0-52c3-8ed6-15887729a8f6', '9780743269261', 'The Virgin''s Lover', 'tc-nDwAAQBAJ', 'From #1 New York Times bestselling author and “queen of royal fiction” (USA TODAY) comes a riveting and scandalous love triangle between a young woman on the brink of greatness, a young man whose ambition far exceeds his means, and the wife who cannot forgive them. In the autumn of 1558, church bells across England ring out the joyous news that Elizabeth I is the new queen, yet one woman hears the tidings with utter dread. She is Amy Dudley, wife of Sir Robert, and she knows that Elizabeth’s ambitious leap to the throne will draw her husband back to the center of the glamorous Tudor court, where he was born to be. Elizabeth’s excited triumph is short-lived. She has inherited a bankrupt country where treason is rampant and foreign war a certainty. Her faithful advisors warns her that she will survive only if she marries a strong prince to govern the rebellious country, but the one man Elizabeth desires is her childhood friend, the ambitious Robert Dudley. As the young couple falls back in love, a question hangs in the air: can he really set aside his wife and marry the queen? When Amy is found dead, Elizabeth and Dudley are suddenly plunged into a struggle for survival.', 'en', 2005, 441, 'http://books.google.com/books/content?id=tc-nDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
