INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fc68bb36-55a2-5472-816e-f1b81a49b6f6', '9780743272506', 'The Boleyn Inheritance', 'caWnfWM77oIC', 'An only survivor of the ambitious Boleyn family, lady-in-waiting Jane Boleyn testifies against Henry VIII''s latest queen, Anne of Cleeves, and conspires to place her young cousin, Catherine Howard, on the throne. By the author of The Other Boleyn Girl. 225,000 first printing.', 'en', 2006, 518, 'http://books.google.com/books/content?id=caWnfWM77oIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
