INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('20862dec-f3b8-509b-b7f7-9edf83cdf201', '9780743272537', 'Virgin Earth', 'ZJeA9rj26a8C', 'A sequel to Earthly Joy follows the life of John Tradescant the Younger, who works as a gardener to King Charles I before fleeing to the Royalist colony of Virginia in order to protect his family, a decision that tests his botanical talents and involves him in the plight of Native Americans whose lives are threatened by colonial settlers. Reprint. 85,000 first printing.', 'en', 2006, 661, 'http://books.google.com/books/content?id=ZJeA9rj26a8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
