INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9113f78d-d303-5968-826b-2b9e59a640df', '9780743281591', 'Diary of a Mistress', 'XFtxvwEACAAJ', 'What should a wife believe? The words of her husband or the diary of his mistress? From the author of Secret Society comes a tale of love and jealousy in which two women struggle to separate fact from fiction. Monica counts her blessings -- she has a husband who is not only devoted to her but is also committed to being a strong, caring father to their twin sons. When Carlos surprises her with an unforgettably romantic getaway, Monica knows her husband is still very much in love with her -- and she with him. But an unexpected package threatens to change everything Monica''s ever believed about her husband. Angela has adopted a sex-them-and-leave-them attitude toward the married men she''s bedded over the last five years. Then she met Monica''s Carlos. Now she will stop at nothing to get him for herself -- even if that means destroying her own life and another woman''s family.', 'en', 2006, 182, 'http://books.google.com/books/content?id=XFtxvwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
