INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('50301994-104f-5ff2-b02f-6a688e43c739', '9780743284790', 'Persian Mirrors', 'Nop3PwAACAAJ', 'The book that revealed Iran to the West, now with a new Afterword. Elaine Sciolino updates Persian Mirrors to include coverage of the 2005 presidential election in Iran. As a correspondent for Newsweek and The New York Times, Sciolino has had more experience covering revolutionary Iran than any other American reporter. She was aboard the airplane that took Ayatollah Ruhollah Khomeini to Tehran in 1979 and was there for the revolution, the hostage crisis, the Iran-Iraq war, the rise of President Khatami, the riots of 1999, and the crisis over Iran''s nuclear program. In Persian Mirrors, Sciolino takes us into the public and private spaces of Iran, uncovering an alluring and seductive nation where a great battle is raging -- not for control over territory, but for the soul of its people.', 'en', 2005, 418, 'http://books.google.com/books/content?id=Nop3PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
