INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cd9d29e8-456b-5e2e-a900-b5d9b1f0bc5e', '9780743292542', 'You On A Diet', '4wRJwgEACAAJ', 'The only way that dieting can work is to make eating so easy and automatic that you never even realize that you''re dieting. Through their entertaining style, Drs. Roizen and Oz teach you about your body.', 'en', 2006, 370, 'http://books.google.com/books/content?id=4wRJwgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
