INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9772e956-743e-58da-ac98-d350e7ee9b3e', '9780743296168', 'The Good House', '62tLnSyQLTAC', 'Award-winning author Tananarive Due''s spine-wingling tale of supernatural suspense ''waves a stronger net than ever'' (Kirkus Reviews) as a woman searches for the inherited power that can save her hometown from the forces of evil.', 'en', 2006, 597, 'http://books.google.com/books/content?id=62tLnSyQLTAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
