INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cccc209d-89db-51e8-9bea-15ebd91e7cf2', '9780743406567', 'Fargo Rock City', 'AhhOOYzmcPsC', 'Empirically proving that—no matter where you are—kids wanna rock, this is Chuck Klosterman''s hilrious memoir of growing up as a shameless metalhead in Wyndmere, North Dakotoa (population: 498). With a voice like Ace Frehley''s guitar, Klosterman hacks his way through hair-band history, beginning with that fateful day in 1983 when his older brother brought home Mötley Crüe''s Shout at the Devil. The fifth-grade Chuck wasn''t quite ready to rock—his hair was too short and his farm was too quiet—but he still found a way to bang his nappy little head. Before the journey was over, he would slow-dance to Poison, sleep innocently beneath satanic pentagrams, lust for Lita Ford, and get ridiculously intellectual about Guns N'' Roses. C''mon and feel his noize.', 'en', 2002, 288, 'http://books.google.com/books/content?id=AhhOOYzmcPsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
