INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c14ff24c-656a-5066-b7f7-84b76cef29b1', '9780743412629', 'The Second Time Around', '6en6XMXSLOgC', 'The "Queen of Suspense," Mary Higgins Clark, delivers a gripping tale of deception and tantalizing twists that might have been ripped from today''s headlines. When Nicholas Spencer, the charismatic head of a company that has developed an anticancer vaccine, disappears without a trace, reporter Marcia "Carley" DeCarlo is assigned the story. Word that Spencer, if alive, has made off with huge sums of money -- including the life savings of many employees -- doesn''t do much to change Carley''s already low opinion of Spencer''s wife, Lynn, who is also Carley''s stepsister and whom everyone believes is involved. But when Lynn''s life is threatened, she asks Carley to help her prove that she wasn''t her husband''s accomplice. As the facts unfold, however, Carley herself becomes the target of a dangerous, sinister group that will stop at nothing to get what they want.', 'en', 2004, 373, 'http://books.google.com/books/content?id=6en6XMXSLOgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
