INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e020a05c-ca62-56f2-b443-aa7ee136ea8b', '9780743422000', 'God Bless You, Dr. Kevorkian', 'mspRQTHcVFQC', '''Vonnegut is our strongest writer...the most stubbornly imaginative'' - John Irving Setting himself up as a ''reporter on the afterlife,'' Vonnegut bravely allows himself to be dispatched on a round-trip to the Pearly Gates - or at least that''s what he claims - in these 30-odd comic and irreverent ''interviews'' with the likes of William Shakespeare, Adolf Hitler and Clarence Darrow. A delight for all Vonnegut devotees, it will appeal to just about anyone with a sense of humour.', 'en', 2001, 80, 'http://books.google.com/books/content?id=mspRQTHcVFQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
