INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fbe23e23-ec8d-51cd-88dc-ddb915ff9b39', '9780743426916', 'The Diablo: The Black Road', 'fSGE8cPJktwC', 'Returning to his hometown of Bramwell after years of wandering, mercenary Darrick Lang discovers that a dark and horrifying force has ensnared its citizens and now seeks to seize him, in a chilling novel of dark fantasy, based on the popular video game. Original. (A Blizzard Entertainment M-rated electronic game) (Horror)', 'en', 2002, 360, 'http://books.google.com/books/content?id=fSGE8cPJktwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
