INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bf0abb0b-8c0f-51d3-9ef7-488b4fefb7be', '9780743435383', 'March Upcountry', 'N8hTPgAACAAJ', 'When his spaceship crashes en route to a boring ceremonial appearance, Roger MacClintock, a spoiled young prince, and his guardian Royal Marines must take a perilous trek across a planet filled with dangerous plants and hostile peoples.', 'en', 2002, 608, 'http://books.google.com/books/content?id=N8hTPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
