INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a5cd0036-b83a-59ac-ab3b-9264f0f79d52', '9780743437813', 'The Vanished Man', 'vrVqO7oSC2EC', 'Hunting down a killer and master illusionist whose first of several brutal murders took place at a prestigious New York music school, investigator Lincoln Rhyme and his protégée, Amelia Sachs, work together to prevent a terrifying act of vengeance. Reprint.', 'en', 2004, 560, 'http://books.google.com/books/content?id=vrVqO7oSC2EC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
