INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dc0a18dd-55fe-5efd-833f-d4021478636d', '9780743440745', 'One More for the Road', 'JVB4PwAACAAJ', 'The Master of storytelling treats us to eighteen brand-new stories and seven previously published but never before collected. Tales of abandoned places and betrayed love; of a house where time has no boundaries; of a faraway planet plagued by an epidemic of sorrow; a wheat field that hides a strangely welcome enemy; the ghosts of dear friends, of errant sons and lost fathers, are but a few of the ingredients that have gone into Bradbury''s savoury cocktail. One More for the Road is a superb refreshment served with wit, heart and flair by the incomparable Ray Bradbury.', 'en', 2003, 289, 'http://books.google.com/books/content?id=JVB4PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4412', 'accepted', 'Ray Bradbury', 'Fantasy fiction, American', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 14 FROM public.book WHERE isbn13 = '9780743440745' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('482f6510-6c97-5d42-a7d5-ee7e30289984', '9780743444040', 'Double Dealer', 'SWBlnQEACAAJ', 'Meet the little known and even less understood heroes of police work in Las Vegas -- the forensic investigators. Led by veteran Gil Grissom, the remarkable team assigned to the Criminalistics Bureau''s graveyard shift -- including Catherine Willows, Warrick Brown, Nick Stokes, and Sara Sidle -- must combine cutting-edge scientific methods and old-fashioned savvy as they work to untangle the evidence behind the yellow police tape. While Nick and Catherine investigate a newly discovered fifteen-year-old murder, Grissom and the rest of the team must uncover the indentity of a cold-blooded killer -- one whose execution-style, "double-tap" signature has provoked the interest of FBI agent Rick Culpepper.', 'en', 2003, 320, 'http://books.google.com/books/content?id=SWBlnQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4413', 'accepted', 'Max Allan Collins', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 13 FROM public.book WHERE isbn13 = '9780743444040' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f50db7f6-b5c7-53ef-9983-d5e266543c58', '9780743449021', 'Shooting Stars Omnibus', 'p1pPcgAACAAJ', 'FOUR GIRLS TOUCHED BY SPECIAL GIFTS. FOUR STUNNING NEW YORK TIMES BESTSELLERS -- - TOGETHER FOR THE FIRST TIME Cinnamon...She escaped her family''s turmoil by dreaming of imaginary worlds. But it''s her talent for the theater that gives Cinnamon a chance...to truly escape. Ice...To her mother''s dismay, she was a silent wallflower, not a social butterfly. Now, her secret gift -- her solid-gold singing voice -- may become her saving grace. Rose...When she danced, she could dream -- and when her father''s secrets threatened to destroy her world, a most unlikely person gives Rose the courage to follow her heart. Honey...Raised on her strict grandfather''s farm, her natural-born talent for the violin gave her a new life -- and love with a handsome soul mate. Will a shocking revelation shatter her newfound happiness?', 'en', 2002, 656, 'http://books.google.com/books/content?id=p1pPcgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4414', 'accepted', 'V.C. Andrews', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 2 FROM public.book WHERE isbn13 = '9780743449021' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b50eae02-59d8-5348-bc43-088868ec4538', '9780743449656', 'Serpent', 'cldoPwAACAAJ', 'When Kurt Austin, the leader of a courageous National Underwater & Marine Agency exploration team, rescues beautiful marine archaeologist Nina Kirov off the coast of Morocco, he becomes the next target of Texas industrialist Don Halcon. A madman bent on carving a new nation out of the southwestern United States and Mexico, Halcon''s scheme hinges on Nina''s recent discovery involving Christopher Columbus, and a priceless pre-Columbian antiquity buried in the battered remains of the sunken Italian luxury liner Andrea Doria. Only Kurt Austin and his crack NUMA team stand between Halcon and the Andrea Doria''s silent steel hull - and if their deadly mission fails, Halcon will ride to power on a wave of death and destruction.', 'en', 2002, 480, 'http://books.google.com/books/content?id=cldoPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
