INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('db1b868a-c816-581a-baf0-1ac34808383d', '9780743458191', 'Changeling', '6Zo8PgAACAAJ', 'Two novels in one volume include Changeling, in which the wizard Mor, after defeating Det Morson and destroying his castle, finds Det''s infant son Pol amidst the ruins, and Madwand, in which Pol, son of Lord Det and a powerful sorcerer, must learn how to control his powers before he can take the throne. Original.', 'en', 2003, 244, 'http://books.google.com/books/content?id=6Zo8PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
