INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('49f4e44d-28e2-50b5-b44f-c39b3352e9fe', '9780743461511', 'Click, Clack, Moo', 'VtszAAAACAAJ', 'Farmer Brown has a problem. His cows like to type. All day long he hears Click, clack, moo. Click, clack, moo. Clickety, clack, moo. But the problems really begin when the cows start leaving Farmer Brown notes. First it was electric blankets... where will it end? And when the animals don''t get what they want they go on strike, of course! Doreen Cronin''s unusual text and Betsy Lewin''s quirky illustrations make this a hilarious story.', 'en', 2003, 30, 'http://books.google.com/books/content?id=VtszAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
