INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('31c862d6-dff3-5f52-a7e7-f61dc06ee540', '9780743463089', 'Eight Black Horses', 'f-oLAAAACAAJ', 'When cryptic notes featuring patterns of eight black horses are delivered to Steve Carello, and a sudden rise in corpses occurs, the cops of the 87th Precinct realize the Deaf Man is back with a vengeance.', 'en', 2003, 336, 'http://books.google.com/books/content?id=f-oLAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
