INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e68337cb-12e5-5494-8984-250c17ff940b', '9780743464116', 'Band of Brothers', 'jlFL20cX9HIC', 'Through soldiers'' journals and letters, describes Easy Company''s contributions to the campaigns in western Europe and recounts their stories of survival.', 'en', 2002, 432, 'http://books.google.com/books/content?id=jlFL20cX9HIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4428', 'accepted', 'Stephen E. Ambrose', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 8 FROM public.book WHERE isbn13 = '9780743464116' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9ecd75fd-fb11-5c1d-a338-90ab3d13ae98', '9780743464796', 'Pendulum', 'GKhhPwAACAAJ', 'He was neither a mathematician nor a trained physicist and yet Léon Foucault always knew that a mysterious force of nature was among us. Like Newton, Galileo, Copernicus, and others before him, Foucault sensed a dramatic relationship between the rotating skies above and the seemingly motionless ground beneath our feet. But it wasn''t until 1851 -- in Paris, inside the Panthéon, and in the company of fellow amateur scientist Napoleon III -- that Foucault swung a pendulum and demonstrated an extraordinary truth about the world: that it turns on its axis. Pendulum is a fascinating journey through the mind and findings of one of the most important and lesser-known characters in the history of science. Through careful research and lively anecdotes, world-renowned author Amir D. Aczel reveals the astonishing range and breadth of Foucault''s discoveries. For, in addition to offering the first unequivocal proof of Earth''s rotation, Foucault gave us the modern electric compass and microscope, was a pioneer in photographic technology, and made remarkable deductions about color theory, heat waves, and the speed of light. At its heart, Pendulum is a story about the illustrious period in France during the Second Empire; the crucial triumph of science over religion; and, most compelling, the life of a struggling, self-made man whose pursuit of knowledge continues to inform our notions about the universe today.', 'en', 2004, 288, 'http://books.google.com/books/content?id=GKhhPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4429', 'accepted', 'Amir D. Aczel', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 19 FROM public.book WHERE isbn13 = '9780743464796' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1b0e47b3-fa4b-5fa1-947d-9cf72c92852a', '9780743466509', 'The Price of Pleasure', 'v_u5lAEACAAJ', 'Kresley Cole returns with a breathtaking romantic saga of love, honor, and passion unbound -- as a man of duty faces his greatest trial, and a young castaway discovers her greatest desire.... A man noted for his courage and integrity, Captain Grant Sutherland journeys to Oceania to find Victoria Dearbourne, an English girl lost at sea a decade before. He''s given her ailing grandfather his word -- as a gentleman -- to find and protect her. But one look at a grown Victoria and Grant has never felt less like one. Tori relishes freedom, untamed passion, and spontaneity above stifling order. Even more so when a proud, cold British captain arrives to rescue her, though she has no wish to be. As Grant tries to convince her to leave her island home, she begins to see in him a man hungering for more. A man who once laughed. A man who desires her but won''t take what she offers. Grant struggles to control his own savage passions -- and fails, Tori must decide what she wants more -- her unfettered independence or the only man who could tame her wild heart....', 'en', 2004, 353, 'http://books.google.com/books/content?id=v_u5lAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
