INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2922c671-5dfc-58f4-b098-3e6472bc61c4', '9780743466523', 'Fall on Your Knees', 'HsgMVk8q6h4C', 'Spanning five generations and moving from Cape Breton Island in Nova Scotia, to the bleak landscape of World War I, and to the emerging jazz scene in New York City, this epic tale tells the story of four sisters.', 'en', 2002, 672, 'http://books.google.com/books/content?id=HsgMVk8q6h4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
