INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('93f0c5c5-ef39-573c-82bc-bf74ad743656', '9780743467544', 'Homecoming', 'fYBwQgAACAAJ', 'After seven years trapped in the Delta Quadrant, Admiral Kathryn Janeway and the crew of Voyager miraculously find their way home, where they find new opportunities, adventures, and reunions with loved ones, until a mysterious cybernetic plague strikes Earth, transforming humans into a new generation of Borg. Original.', 'en', 2003, 262, 'http://books.google.com/books/content?id=fYBwQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4432', 'accepted', 'Christie Golden', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 2 FROM public.book WHERE isbn13 = '9780743467544' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('336143c6-b2c1-5e5f-b289-1383fe0a99c6', '9780743468596', 'First Things First', 'KRZEPgAACAAJ', 'In the spirit of THE 7 HABITS OF HIGHLY EFFECTIVE PEOPLE, the international bestseller, FIRST THINGS FIRST is a revolutionary guide to managing your time by learning how to balance your life. Traditional time management suggests that working harder, smarter and faster will help you gain control of your life, and that increased control will bring peace and fulfilment. The authors of FIRST THINGS FIRST disagree. In the first real breakthrough in time management in years, Stephen R. Covey, A. Roger Merrill and Rebecca R. Merrill apply the insights of the 7 HABITS to the daily problems of people who must struggle with the ever increasing demands of work and home life. Rather than focusing on time and things, FIRST THINGS FIRST emphasises relationships and results. And instead of efficiency, this new approach emphasises effectiveness. Covey offers a principle-centred approach that will empower readers to define what is truly important; to accomplish worthwhile goals; and to lead rich, rewarding and balanced lives.', 'en', 2002, 360, 'http://books.google.com/books/content?id=KRZEPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
