INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4b879764-be6d-53c6-b93f-27945cec6301', '9780743471220', 'The Diablo: The Sin War #1: Birthright', 'zmc4swEACAAJ', 'Since the beginning of time, the angelic forces of the High Heavens and the demonic hordes of the Burning Hells have been locked in an eternal conflict for the fate of all Creation. That struggle has now spilled over into Sanctuary -- the world of men. Determined to win mankind over to their respective causes, the forces of good and evil wage a secret war for mortal souls. This is the tale of the Sin War -- the conflict that would forever change the destiny of man. Three thousand years before the darkening of Tristram, Uldyssian, son of Diomedes, was a simple farmer from the village of Seram. Content with his quiet, idyllic life, Uldyssian is shocked as dark events rapidly unfold around him. Mistakenly blamed for the grisly murders of two traveling missionaries, Uldyssian is forced to flee his homeland and set out on a perilous quest to redeem his good name. To his horror, he has begun to manifest strange new powers -- powers no mortal man has ever dreamed of. Now, Uldyssian must grapple with the energies building within him -- lest they consume the last vestiges of his humanity.', 'en', 2006, 326, 'http://books.google.com/books/content?id=zmc4swEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4436', 'accepted', 'Richard A. Knaak', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 3 FROM public.book WHERE isbn13 = '9780743471220' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6da7c6db-a3c2-5501-8be9-48054cb864dd', '9780743471237', 'Diablo: The Sin War #2: Scales of the Serpent', 'widqvQEACAAJ', 'Since the beginning of time, the angelic forces of the High Heavens and the demonic hordes of the Burning Hells have been locked in the Eternal Conflict for the fate of all Creation. That struggle has now spilled over into Sanctuary -- the world of men. Determined to win mankind over to their respective causes, the forces of good and evil wage a secret war for mortal souls. This is the tale of the Sin War -- the conflict that would forever change the destiny of man. Bent on destroying the evil cult of the Triune, Uldyssian does not yet suspect that Inarius -- secret Prophet of the Cathedral of Light -- has been subtly aiding his quest. Obsessed with restoring Sanctuary to its former glory, Inarius has been playing Uldyssian against the two great religions in a reckless attempt to topple them both. But another player has slipped back into the equation. The demon Lilith, once Inarius''s lover, seeks to use Uldyssian as her own pawn in a scheme to turn humans into an army of naphalem -- godlike beings, more powerful than any angel or demon, who could overturn all Creation and elevate Lilith to supreme being. An original tale of swords, sorcery, and timeless struggle based on the bestselling, award-winning M-rated computer game from Blizzard Entertainment. Intended for mature readers.', 'en', 2007, 327, 'http://books.google.com/books/content?id=widqvQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4437', 'accepted', 'Blizzard Entertainment', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 14 FROM public.book WHERE isbn13 = '9780743471237' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('151c1f3f-0a6d-58f9-9a0d-0b2ab8550475', '9780743471329', 'Diablo: Moon of the Spider', 'GcY6PgAACAAJ', 'Since the beginning of time, the angelic hosts of the High Heavens and the demonic hordes of the Burning Hells have been locked in a struggle for the fate of all Creation. That struggle has now come to the mortal realm...and neither Man nor Demon nor Angel will be left unscathed.... DIABLO Driven by nightmares to the ruins of a mysterious tomb, Lord Aldric Jitan hopes to awaken a terrible evil that has slept since the fall of Tristram. Drawn by the growing darkness in the land, the enigmatic Necromancer, Zayl, stumbles upon Jitan''s plot -- unaware that one of his own brethren has set these dire events in motion. Now, as the celestial Moon of the Spider rises, the nefarious demon, Astrogha, prepares to unleash his minions upon Sanctuary. MOON OF THE SPIDER An original tale of swords, sorcery, and timeless struggle based on the bestselling, award-winning M-rated computer game from Blizzard Entertainment. Intended for mature readers.', 'en', 2006, 336, 'http://books.google.com/books/content?id=GcY6PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
