INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7bbf56ba-5448-5cd9-904a-d802bbe397dc', '9780743480727', 'Blood Enemy', 'AsBkvj5LUeYC', 'Once the servants of the vampires, the werewolves use their power to transform themselves into beasts of unearthly ferocity against their former masters, aristocrats with a sensual appetite for blood, in a clandestine conflict, in a prequel to the blockbuster film. Original. (Prequel to the Sony Pictures film, written by Danny McBride, starring Kate Beckinsale, Scott Speedman, Shane Brolly, Robby Gee, Erwin Leder, Wentworth Miller, Sophia Myles, Bill Nighy, & Michael Sheen) (Horror)', 'en', 2004, 310, 'http://books.google.com/books/content?id=AsBkvj5LUeYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
