INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7608c5f8-74cc-55a6-9117-c686d85cba40', '9780743482790', 'Macbeth', 'HysVAjLGOC0C', 'Macbeth: The DVD Edition includes everything you''ve come to expect from the Folger Shakespeare Library editions of Shakespeare''s plays -- facing-page explanatory notes, scene-by-scene plot summaries, illustrations from the Folger archives -- combined here with a bonus DVD of a performance of Macbeth recorded before a rapt audience in the Folger''s intimate Elizabethan Theatre. Conceived and directed by Teller (of Penn & Teller) and Aaron Posner, this acclaimed production showcases the inventive magic of Teller, who, with Posner, contributes a new foreword to this edition, writing about their vision of the play as a "supernatural horror thriller." Macbeth: The DVD Edition is the perfect volume for those encountering the play for the first time and for those finding brilliant new insights into a classic. THIS DVD EDITION INCLUDES: • DVD of the 2008 Folger Theatre/Two River Theater Company production -- with over 50 minutes of special features, including interviews with the directors, actors, designers, and scholars • Foreword by directors Teller and Aaron Posner on the staging of Macbeth • Freshly edited text based on the 1623 First Folio • Full explanatory notes conveniently placed on pages facing the text of the play • A key to the play''s famous lines and phrases • An introduction to reading Shakespeare''s language in Macbeth • Illustrations from the Folger Shakespeare Library''s vast holdings of rare books • An essay by Susan Snyder that provides a modern perspective on the play', 'en', 2004, 272, 'http://books.google.com/books/content?id=HysVAjLGOC0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
