INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cf4cdee0-6b68-57ed-869b-b75f68d12dab', '9780743491686', 'Star Trek: The Original Series: Crucible: McCoy: Provenance of Shadows', '_Pz9jwEACAAJ', 'Displaced in time, Dr. Leonard McCoy''s life takes two bizarre, divergent paths as his actions in the past threaten to forever alter the present and destroy the future as he discovers an unimaginable altered history. Original.', 'en', 2006, 640, 'http://books.google.com/books/content?id=_Pz9jwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
