INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('65182ad3-d4ae-5e74-a740-c286bef359cf', '9780743496148', 'The Manolo Matrix', 'rxB-qUD74ocC', 'USA Today bestselling author of The Givenchy Code Julie Kenner reloads for her second novel of high-heeled thrills as another woman gets pulled into a mysterious world of extreme gaming where she must play or die. Aspiring actress Jennifer Crane knows all about games -- the games girls play to get a guy; the games actresses play to land a part; and the good old game of credit-card roulette. (How else is a girl supposed to afford her shoes?) But she never expected to be playing a game with life-or-death consequences. Unable to successfully score an acting gig, she has, instead, been cast in the role of reluctant bodyguard to a real-life assassin''s target -- a dashing FBI agent of all people! -- and must embark with him upon a scavenger hunt across Manhattan in search of the ultimate prize: survival. Before this, Jenn''s definition of fighting dirty has been elbowing her way to the front of the line at a Manolo sample sale. Now, if she wants to stay alive, she''s going to have to learn a few new uses for her stilettos. . . and they ain''t pretty. Fast, flirty, and full of great footwear, The Manolo Matrix is another electrifying adventure in this breakout series for fashionistas who love a perfectly appointed mystery.', 'en', 2006, 352, 'http://books.google.com/books/content?id=rxB-qUD74ocC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4467', 'accepted', 'Julie Kenner', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 19 FROM public.book WHERE isbn13 = '9780743496148' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('19804a94-f424-528a-a7dc-052cb63b3e55', '9780743496162', 'Never Go Home Again', 'i89aAAAAYAAJ', 'The experience and quality that I bring to my writing can''t be faked. I know what I know. Through my novels, I invite readers to journey with me into the streets. Come see what I''ve seen. Let me show the gritty and grimy undercarriage of society, the "flip side" of the game.... -- Shannon Holmes Inspired by the events of his own life, the Essence bestselling author of B-More Careful and Bad Girlz presents a vivid, unflinching novel about a young man''s coming of age in the city streets. Never Go Home Again is the story of Corey Dixon, a young man whose father tries as best he can to steer him away from the lure of the streets. And yet, like so many others in his neighborhood, Corey finds the lucrative drug trade too tempting to resist. While he makes fast money for a while, ultimately Corey must pay the price for his choice of his profession: his freedom. By the age of sixteen, Corey is sentenced to prison. Incarcerated at Riker''s Island, Corey lives through experiences that threaten to destroy his body, his mind, and his spirit. Still, in the midst of his horrific imprisonment, he discovers inner strength and -- against unimaginable odds -- manages to survive. Corey makes a new kind of family for himself in jail, including a teacher who encourages him to "never go home again." In the course of his journey of self-discovery, Corey comes to realize the wisdom in his mentor''s words. Unflinching and riveting, Never Go Home Again is a powerful, true-to-life story of redemption that no reader will soon forget.', 'en', 2005, 320, 'http://books.google.com/books/content?id=i89aAAAAYAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4468', 'accepted', 'Shannon Holmes', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 4 FROM public.book WHERE isbn13 = '9780743496162' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('763c2c95-2409-5d6f-8370-2bf754224dc9', '9780743498715', 'Tinker', 'N4gMAAAACAAJ', 'Inventor, girl genius Tinker lives in a near-future Pittsburgh which now exists mostly in the land of the elves. She runs her salvage business, pays her taxes, and tries to keep the local ambient level of magic down with gadgets of her own design. When a pack of wargs chase an Elven noble into her scrap yard, life as she knows it takes a serious detour. Tinker finds herself taking on the Elven court, the NSA, the Elven Interdimensional Agency, technology smugglers and a college-minded Xenobiologist as she tries to stay focused on what''s really important - her first date. Armed with an intelligence the size of a planet, steel-toed boots, and a junkyard dog attitude, Tinker is ready to kick butt to get her first kiss.', 'en', 2004, 448, 'http://books.google.com/books/content?id=N4gMAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
