INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a8354e19-8ae1-564d-92bb-de08ee5369d0', '9780743499484', 'The Dead Yard', 'GQhDKlrFQnYC', 'In this breathtaking sequel to "Dead I Well May Be," the mercenary Michael Forsythe is forced to infiltrate an Irish terrorist cell on behalf of the FBI, confronting murder, mayhem, and the prospect of his own death.', 'en', 2006, 364, 'http://books.google.com/books/content?id=GQhDKlrFQnYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
