INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('25958dd7-2927-5c10-ad74-02b44450bf7c', '9780744004410', 'World of Warcraft Atlas', 'Ag3jAQAACAAJ', 'BradyGames'' World of WarCraft Atlas includes the following: Complete resource detailing each area of this expansive MMORPG. Maps are provided for every area including all regions and major cities. Each illustration shows critical locations and characters such as NPCs, enemies, mobs, shops, merchants, flight points, entry and exit points from regions and where they lead. As an added bonus, cross-referenced indices of all information are also provided for ease of use. Platform: PC CD-ROM Genre: MMORPG This product is available for sale worldwide.', 'en', 2005, 192, 'http://books.google.com/books/content?id=Ag3jAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
