INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('686f4aa6-33dd-599e-9331-03a2f74c680b', '9780745317885', 'Propaganda and the Public Mind', 'nTMEirKUw-QC', 'An invitation to take part in a conversation with one of the great minds of our time. First published in 2001, this book collects a series of discussions with the journalist David Barsamian. It is the perfect complement to Chomsky''s major works of media study such as Manufacturing Consent and Necessary Illusions. Events discussed in detail are the so-called ''Battle of Seattle'' protests against the World Trade Organisation, US involvement in East Timor, and the beginning of the movement towards a second Iraq War.', 'en', 2001, 256, 'http://books.google.com/books/content?id=nTMEirKUw-QC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4485', 'accepted', 'David Barsamian; Noam Chomsky', 'Language and languages', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 18 FROM public.book WHERE isbn13 = '9780745317885' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fa761cae-0e4a-5ef0-bb91-399ac38181d6', '9780745622088', 'Zizek', 'JJfIC6_Ws3QC', 'Zizek is hailed as the most significant interdisciplinary thinker of modern times. His work is a powerful, often explosive combination of Lacanian psychoanalysis and philosophy which tests key psychoanalytical concepts against the ideas of major European thinkers, especially Hegel. It has ignited enthusiasm and stimulated new approaches across a vast range of disciplines, and seems to be attracting an ever-growing readership. In part, this is because Zizek himself has a panoramic range of interests encompassing film studies, literature, cyber culture, ethics, theology and, above all, politics. It is also because he is a highly entertaining writer, having a flair for anecdote, a smutty sense of humour and the knack of capturing complex ideas in concrete form. Sarah Kay''s book provides a lucid and comprehensive introduction to Zizek''s work. His writings to date are presented and evaluated here for the first time, together with an outline of their development and explanations of his key premises, themes and terms. This book will be essential reading for students of cultural studies, literary studies, philosophy and social and political theory.', 'en', 2003, 195, 'http://books.google.com/books/content?id=JJfIC6_Ws3QC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4486', 'accepted', 'Sarah Kay', 'Social Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 0 FROM public.book WHERE isbn13 = '9780745622088' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('76952054-2f77-5531-9f53-3626f205c213', '9780745628479', 'Political Philosophy: A Beginner''s Guide for Students and Politicians', 'VM3R5IfrqT8C', 'Politicians invoke grand ideas: social justice, liberty, equality,community. But what do these ideas really mean? How can politicians across the political spectrum appeal to the same values? Political Philosophy: A Beginners'' Guide for Students and Politicians answers these important questions. Accessible and lively, the book is an ideal student text, but it also brings the insights of the world''s leading political philosophers to a wide general audience. Using plenty of examples, it equips readers to think for themselves about the ideas that shape political life. Democracy works best when both politicians and voters move beyond rhetoric to think clearly and carefully about the political principles that should govern their society. But clear thinking is difficult in an age when established orthodoxies have fallen by the wayside. Bringing political philosophy out of the ivory tower and within the reach of all, this book provides us with tools to cut through the complexities of modern politics. In so doing, it makes a valuable contribution to the democratic process.', 'en', 2001, 194, 'http://books.google.com/books/content?id=VM3R5IfrqT8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4487', 'accepted', 'Adam Swift', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 4 FROM public.book WHERE isbn13 = '9780745628479' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5b85e846-f43c-56cc-867d-a71abed2ec56', '9780745628974', 'Conversations with Zizek', 'ExMYKdVRjHIC', 'In this new book, Slavoj Žižek and Glyn Daly engage in a series of entertaining conversations which illustrate the originality of Žižek’s thinking on psychoanalysis, philosophy, multiculturalism, popular/cyber culture, totalitarianism, ethics and politics. An excellent introduction to one of the most engaging and controversial cultural theorists writing today. Žižek is a Slovenian sociologist who trained as a Lacanian and uses Lacan to analyse popular culture and politics. Illustrates the originality of Žižek’s thinking on psychoanalysis, philosophy, multi-culturalism, popular/cyber culture, totalitarianism, ethics and politics. Provides a unique glimpse of Žižek’s humour and character and offers new material and fresh perspectives which will be of interest to followers of Žižek’s writings.', 'en', 2003, 171, 'http://books.google.com/books/content?id=ExMYKdVRjHIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4488', 'accepted', 'Slavoj Žižek; Glyn Daly', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 0 FROM public.book WHERE isbn13 = '9780745628974' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d528a1e0-825b-5ca0-99a6-019277148677', '9780745633794', 'Sociology', 'vbu2gis26C0C', 'This fully revised and updated version of Anthony Giddens′s Sociology, now in its fifth edition, offers an unrivalled introduction for students new to the subject – lucid, lively, authoritative and original. Written by one of the world′s leading sociologists, this comprehensive textbook manages to be clear, accessible and jargon–free, but without oversimplifying complex debates. Earlier editions of Sociology broke new ground by incorporating cutting–edge debates, such as the impact of globalisation, into an introductory text. This fifth edition remains a state of the art textbook, with fresh and engaging new material added throughout. While covering all of the core topics of sociology, the fifth edition also includes a great deal of substantive new material, ensuring that students are introduced to the most recent sociological debates. Throughout, the book weaves together classical and contemporary theory and data, and provides a wide range of everyday examples to which students can easily relate. The fifth edition also benefits from: ∗ New discussions of global inequality, disability, ageing and the life course, risk, the network society, and terrorism, as well as many other additional and up–to–date topics. ∗ Numerous learning aids in every chapter, such as summary points, questions for further thought, and additional reading suggestions, which help to reinforce students′ knowledge. ∗ Lots of extra photographs, diagrams, case studies and cartoons, to bring ideas to life and fire students′ imaginations. ∗ High–quality supplementary resources on a dedicated website, including a full instructors′ manual and additional student aids, all specially designed to stimulate students′ learning and critical thinking. The fifth edition of this classic textbook is an ideal teaching text for first–year university and college courses, and will be essential reading for all students who are looking for an exciting, authoritative and easy–to–follow introduction to sociology. Please visit the accompanying website at: http://www.polity.co.uk/giddens5/', 'en', 2006, 1000, 'http://books.google.com/books/content?id=vbu2gis26C0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
