INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('07bb4565-1951-5b5f-982d-a97e57223019', '9780745950549', 'The Gifts of the Jews', '35dHPgAACAAJ', 'The bestselling author of "How the Irish Saved Civilization" reveals the critical change that made Western civilization possible, in this irresistible exploration of the origins of some of humankind''s oldest and most closely held beliefs. Line drawings.', 'en', 2001, 304, 'http://books.google.com/books/content?id=35dHPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
