INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2c4c6741-5e62-53f9-99e3-884731fdc1ec', '9780747252139', 'Never Far from Nowhere', 'pFKsQgAACAAJ', 'A passionate and perceptive story full of the pain and the humour of growing up, from Andrea Levy, author of the Orange Prize winning SMALL ISLAND and the Man Booker shortlisted THE LONG SONG. NEVER FAR FROM NOWHERE is the story of two sisters, Olive and Vivien, born in London to Jamaican parents and brought up on a council estate. They go to the same grammar school, but while Vivien''s life becomes a chaotic mix of friendships, youth clubs, skinhead violence, A-levels, discos and college, Olive, three years older and a skin shade darker, has a very different tale to tell...', 'en', 1996, 282, 'http://books.google.com/books/content?id=pFKsQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
