INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9706b1d5-01e8-53a7-b848-433913ca67f8', '9780747264866', 'Millie''s Fling', 'BEp9HAAACAAJ', 'Love is always just around the corner in a Jill Mansell novel - with a few surprises and a lot of humour on the way to happiness When Millie Brady saves Orla Hart''s life she doesn''t realise how drastically it will change her own - not least because the boyfriend who was asking her to move in with him at the time stormed off in a huff. Actually, Millie''s relieved. She''s happy to enjoy a man-free summer in Cornwall. But Orla has other ideas. She''s determined that Millie should meet the man of her dreams. Trouble is, Millie''s taste in men doesn''t tally with Orla''s. The one who really interests her is Hugh Emerson, and he''s the man with whom Orla''s adamant she mustn''t get involved...', 'en', 2001, 512, 'http://books.google.com/books/content?id=BEp9HAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
