INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6410a0c1-c106-5095-ad70-f30464df0717', '9780747266976', 'Black Evening', 'H9JsPwAACAAJ', 'From the American heartland to the edge of Hell, David Morrell, the bestselling author of the classics FIRST BLOOD and THE BROTHERHOOD OF THE ROSE, presents a career-spanning examination into his own life - and the fears we all share. From his first published short fiction to his latest, award-winning stories BLACK EVENING includes: ''The Beautiful Uncut Hair of Graves'' - Winner, Best Novella, Horror Writers of America Award, ''Orange is for Anguish, Blue for Insanity'' - Winner, Best Novella, Horror Writers of America Award and ''Dead Image'' - Nominee, Best Novella, World Fantasy Award.', 'en', 2000, 435, 'http://books.google.com/books/content?id=H9JsPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
