INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1a7a90aa-7c47-5b75-8a09-13c1983db801', '9780747267195', 'Deep Waters', 'HDcBHAAACAAJ', 'A man''s body, virtually decapitated, is found by the Bosphorus. His identity card names him as Rifat Berisha, an Albanian. The family is impenetrable but when Inspector Cetin Ikmen, whose mother was Albanian, consults his cousin, Samsun, he''s left in little doubt that Berisha''s death is likely to be the result of a fis, an implacable blood feud between rival Albanian families. Which means the blood already shed will have to be avenged. And if the Berishas or their enemies discover Ikmen is from a noted Albanian clan, some of the spilt blood might be his...', 'en', 2002, 448, 'http://books.google.com/books/content?id=HDcBHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
