INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7a6e1bb6-9b2b-5b36-bb47-356845bc4269', '9780747267447', 'Two''s Company', '8nfZHAAACAAJ', 'Love is always just around the corner in a Jill Mansell novel - with a few surprises and a lot of humour on the way to happiness Jack and Cass Mandeville are a dream couple, ridiculously happy together and successful to boot - Jack as a journalist and Cass with her own hugely popular radio show. Indeed, almost every member of the Mandeville family is famous in their own right: from stunning Cleo, a supermodel with attitude, to Sean, the rising star of the comedy circuit. Incredibly good-looking and likeable, the family have captured the hearts of the nation - and the nation''s press. But on the day that Jack hits the big 40 - the same day that a redhead called Imogen turns up to interview Jack and Cass for Hi! magazine - their proverbial bubble is about to burst...', 'en', 2003, 448, 'http://books.google.com/books/content?id=8nfZHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
