INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ef1481dc-6ba0-5327-a584-1e87f5c5d26e', '9780747268468', 'Kiss', 'TrK7GwAACAAJ', 'Love is always just around the corner in a Jill Mansell novel - with a few surprises and a lot of humour on the way to happiness When Izzy is knocked off her motor bike she doesn''t just lose her dignity - she loses as a result not one but two long-term boyfriends, her job and, to boot, her extremely bijou flat. Gina, who caused the accident, has more important things to worry about - her husband''s mistress is pregnant and she''s suddenly on her own. Why should she care about Izzy? Yet somehow the well-heeled Gina finds herself opening her home to Izzy and her spirited teenage daughter. And it''s there that Izzy meets heart-stoppingly handsome Sam, whose lingering kiss is all it takes for her to find the true love that has always eluded her - though there are just a few obstacles between that first kiss and the ''happy ever after''...', 'en', 1993, 512, 'http://books.google.com/books/content?id=TrK7GwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
