INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f55defa1-a887-52c6-982e-69da48174746', '9780747268475', 'Sheer Mischief', 'sAV5QgAACAAJ', 'Love is always just around the corner in a Jill Mansell novel - with a few surprises and a lot of humour on the way to happiness It''s not that Janey Sinclair isn''t pleased to see her sister. It''s just that being woken at seven by Maxine, complete with police escort, isn''t quite how she''d planned to spend her Sunday. Even so Janey, who''s just rebuilding her life after her husband disappeared, is delighted that her sister''s back in the Cornish town where they grew up. When Maxine sets her sights on Guy Cassidy, an impossibly glamorous fashion photographer, Janey knows there''s no limit to the mischief her sister will get up to in order to dispatch her rivals. But little do they know that the competition is a lot closer to home than they think...', 'en', 2001, 504, 'http://books.google.com/books/content?id=sAV5QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
