INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b5df7b93-63e8-51db-8a6d-c99604080a42', '9780747548317', 'The Turtle Diary', 'oSD53x_ZlZMC', 'In the aquarium at the London Zoo, three sea turtles swim endlessly in ''their little bedsitter of ocean''. Two lonely people, William G and Neaera H, become obsessed with the turtles'' captivity, and resolve to rescue them and release them in to the sea. William''s and Neaera''s diaries tell the story of how they achieve the turtles'' freedom, and in the process re-define their own lives.', 'en', 2000, 182, 'http://books.google.com/books/content?id=oSD53x_ZlZMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
