INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6d7d83c8-b0c5-55e9-9f5f-621564a7d8e0', '9780747553663', 'Ransom', 'jDdAPwAACAAJ', 'Since Christopher Ransom has been living in Kyoto, the ancient capital of Japan, he has devoted himself to the study of karate. He doesn''t just want to be good, he wants to be transformed. Two years after a lapse in his scruples drew him into crisis on the Khyber Pass, it is through karate that Ransom has regained some control, beginning to subsume his disillusionment and assuage his guilt. But soon he finds himself threatened by everything he thought he had left behind -- a sequence of bizarre events whose consequences he cannot escape.', 'en', 2001, 279, 'http://books.google.com/books/content?id=jDdAPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
