INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7ad3ccaf-768c-5f83-be4e-223c8e478142', '9780747569138', 'More Sideways Arithmetic from Wayside School', 'EMj7HAAACAAJ', 'Welcome back to maths class at Wayside School. How much is PEPPERS + PIG LIPS? If Jenny''s shirt has sparkles on it, will Todd have egg in his hair? These Sideways Arithmetic problems may look puzzling at first, but you can use real maths to solve them, and the answers are perfectly logical. Three are lots of clues and hints, plus all the answers are right there in the book. Best of all the children you have read about in the other books about Wayside School are here to help you! Try solving the brainteasers in this book, along with Mrs Jewls and the children from her class, and maths will be a dream!', 'en', 2004, 112, 'http://books.google.com/books/content?id=EMj7HAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
