INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c0dc0df7-4a29-5df5-9fa4-a03f862786d9', '9780747572930', 'A Sound Like Someone Trying Not to Make a Sound', '45_bGAAACAAJ', 'When a child hears a noise in the night he gets up to investigate. He calls his father to help him and they work through all the things that the ''noise'' could be, eventually realising that it is nothing to be scared of. An empowering book about over coming ones fears handled with brilliant originality by John Irving and Tatjana Hauptmann.', 'en', 2004, 32, 'http://books.google.com/books/content?id=45_bGAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
