INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ae6d703a-2b94-5042-8734-af8ec4874411', '9780747573647', 'The Little Friend', '2ojFwAEACAAJ', 'Twelve-year-old Harriet is doing her best to grow up, which is not easy as her mother is permanently on medication, her father has silently moved to another city, and her serene sister rarely notices anything. All of them are still suffering from the shocking and mysterious death of her brother Robin twelve years earlier, and it seems to Harriet that the family may never recover. So, inspired by Captain Scott, Houdini, and Robert Louis Stevenson, she sets out with her only friend Hely to find Robin''s murderer and punish him. But what starts out as a child''s game soon becomes a dark and dangerous journey into the menacing underworld of a small Mississippi town.', 'en', 2005, 555, 'http://books.google.com/books/content?id=2ojFwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
