INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b25f9af3-b499-56b0-8cc5-6b4d3c39b08b', '9780749934422', 'Portrait in Death', '7PZKPgAACAAJ', '''She was still three feet away when she''d smelled it. She''d walked with death too many times to mistake it.'' After a tip from a reporter, Eve Dallas finds the body of a young woman in a Delancey street dumpster. Just hours before, the news station had mysteriously received a portfolio of professional portraits of the woman. The photos seemed to be nothing out of the ordinary for any pretty young woman starting a modeling career. Except that she wasn''t a model. And that these photos were taken after she had been murdered. Now Dallas is on the trail of a killer who''s a perfectionist and an artist. He carefully observes and records his victim''s every move. And he has a mission: to own every beautiful young woman''s innocence, to capture her youth and vitality - in one fateful shot...', 'en', 2004, 354, 'http://books.google.com/books/content?id=7PZKPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4539', 'accepted', 'J. D. Robb; Nora Roberts', 'Dallas, Eve (Fictitious character)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 1 FROM public.book WHERE isbn13 = '9780749934422' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fee54b89-28ed-5d3c-a088-35a593bf10a5', '9780750666008', 'Brand New Justice', 'MmahV_o4oh4C', 'Recently vilified as the prime dynamic driving home the breach between poor and rich nations, here the branding process is rehabilitated as a potential saviour of the economically underprivileged. Brand New Justice, now in a revised paperback edition, systematically analyses the success stories of the Top Thirteen nations, demonstrating that their wealth is based on the ''last mile'' of the commercial process: buying raw materials and manufacturing cheaply in third world countries, these countries realise their lucrative profits by adding value through finishing, packaging and marketing and then selling the branded product on to the end-user at a hugely inflated price. The use of sophisticated global media techniques alongside a range of creative marketing activities are the lynchpins of this process. Applying his observations on economic history and the development and impact of global marketing, Anholt presents a cogent plan for developing nations to benefit from globalization. So long the helpless victim of capitalist trading systems, he shows that they can cross the divide and graduate from supplier nation to producer nation. Branding native produce on a global scale, making a commercial virtue out of perceived authenticity and otherness and fully capitalising on the ''last mile'' benefits are key to this graduation and fundamental to forging a new global economic balance. Anholt argues with a forceful logic, but also backs his hypothesis with enticing glimpses of this process actually beginning to take place. Examining activities in India, Thailand, Russia and Africa among others, he shows the risks, challenges and pressures inherent in ''turning the tide'', but above all he demonstrates the very real possibility of enlightened capitalism working as a force for good in global terms. * Controversial and thought-provoking analysis of issues that are central to 21st century economic thought; radical new thinking on wealth-creation in the developing world. * Unites world-class branding and marketing knowledge with an emerging-market development agenda. * Concrete answers to the problems of anti-capitalism, medium level poverty and the brand backlash; a way for the marketing and advertising industries to regain respect and a more positive reputation', 'en', 2005, 184, 'http://books.google.com/books/content?id=MmahV_o4oh4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
