INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('749ed656-e69a-5bbb-9848-3b6625e610a8', '9780750937252', 'Ulysses Found', 'QBdGPgAACAAJ', 'Having settled in Malta after the end of World War 2, Ernle Bradford decided to trace the route of Ulysses. This book is a journal of his travels, describing both the amazing sights and the pitfalls that befell Homer''s character.', 'en', 2005, 238, 'http://books.google.com/books/content?id=QBdGPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
