INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2eb7f61b-9f46-50a3-89c8-ef7f436bfcca', '9780751333329', 'The Story of Philosophy', '5qqvOQAACAAJ', 'Philosophy is a subject that influences many aspects of our lives and our understanding of our experiences yet it can seem dauntingly inaccessible. This book features history of Western philosophy. It traces over 2500 years of Western philosophy from the Ancient Greeks to modern thinkers.', 'en', 2001, 240, 'http://books.google.com/books/content?id=5qqvOQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
