INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2b6ebf01-1ad6-56aa-bcae-2a18d5f7d283', '9780751503890', 'The Physician', 'FPsTngEACAAJ', 'Eleventh-century England and Persia are the backgrounds of this story of an orphan named Rob Cole, who is apprenticed to a travelling barber-surgeon and, discovering in himself a gift for healing, decides to study medicine with the legendary Avicenna.', 'en', 2001, 720, 'http://books.google.com/books/content?id=FPsTngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
