INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1fa2511c-22ee-5083-8aed-6f7ea9b6ef02', '9780751504354', 'Red Phoenix', 'eLRtPwAACAAJ', 'Violent riots formented by foreign agents are breaking out in South Korea. Seizing the opportunity, North Korea launches a lightning invasion, with heavy Soviet support, whose aim is to unite North and South under Communist rule. The second Korean War has begun and World War III may be imminent.', 'en', 1992, 791, 'http://books.google.com/books/content?id=eLRtPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
