INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d7c8a6a5-54e1-594c-8ce0-0093527d4129', '9780751506471', 'The Tangled Thread', 'tyqLOQAACAAJ', 'In the Morland Dynasty Series, the majestic sweep of English history is richly and movingly portrayed through the fictional lives of the Morland family. The 22 volumes that comprise this elegantly produced series offer entertainment of the most compelling kind.', 'en', 1987, 474, 'http://books.google.com/books/content?id=tyqLOQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
