INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4559', 'accepted', 'Bill Watterson', 'American wit and humor, Pictorial', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 7 FROM public.book WHERE isbn13 = '9780751517200' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b70dbe2f-06d7-5c2b-afcc-37aa94ebc431', '9780751527346', 'The Pilgrim of Hate', 'ef6CvgEACAAJ', 'In the year of our Lord 1141, civil war over England''s throne leaves a legacy of violence- and the murder of a knight dear to Brother Cadfael. And with gentle budstrewn May, a flood of pilgrims comes to the celebration of Saint Winifred at the Abbey of Saint Peter and Saint Paul, carrying with it many strange souls and perhaps the knight''s killer. Brother Cadfael''s shrewd eyes see all: the prosperous merchant who rings false, and angelic lame boy, his beautiful dowess sister, and two wealthy penitents. In the name of justice, Cadfael decides to uncover the strange and twisted tale that accompanies these travellers. Instead he unearths a quest for vengeance, witnesses a miracle, and finds himself on a razor''s edge between death and the absolution of love.', 'en', 1998, 271, 'http://books.google.com/books/content?id=ef6CvgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4560', 'accepted', 'Ellis Peters', 'Benedictine monasteries', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 9 FROM public.book WHERE isbn13 = '9780751527346' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c929b23e-fa82-5879-b889-08f468163b9f', '9780751529814', 'Tuesdays with Morrie', 'LXkCKQAACAAJ', '"Maybe it was a grandparent, or a teacher, or a colleague. Someone older, patient and wise, who understood you when you were young and searching, helped you see the world as a more profound place, gave you sound advice to help you make your way through it. For Mitch Albom, that person was Morrie Schwartz, his college professor from nearly twenty years ago. Maybe, like Mitch, you lost track of this mentor as you made your way, and the insights faded, and the world seemed colder. Wouldn''t you like to see that person again, ask the bigger questions that still haunt you, receive wisdom for your busy life today the way you once did when you were younger? Mitch Albom had that second chance. He rediscovered Morrie in the last months of the older man''s life. Knowing he was dying, Morrie visited with Mitch in his study every Tuesday, just as they used to back in college. Their rekindled relationship turned into one final "class": lessons in how to live."--Back cover.', 'en', 2003, 210, 'http://books.google.com/books/content?id=LXkCKQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
