INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('65e6f703-f178-5335-9c06-ab80112c1d53', '9780751531244', 'Spencerville', '01pXPwAACAAJ', 'After twenty-five years of working in the shadowy world of espionage Keith Landry is on his way home. Driving along the highway, humming a few bars of ''Homeward Bound'', the twenty-five years'' service he has given the US government are fast becoming a distant memory. He is safe. He is alone. And life has never felt sweeter as the signs for hometown Spencerville come into view. Keith Landry has promised himself no more violence, no more death. But a chance meeting with childhood sweetheart Annie Baxter makes it a promise he cannot keep. As passion is rekindled between them, jealousy flares. For Annie is married to a violent and sadistic bully: the man who runs Spencerville, Sheriff Baxter. And he won''t tolerate any man near his wife. Especially Keith Landry.', 'en', 2001, 564, 'http://books.google.com/books/content?id=01pXPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4562', 'accepted', 'Nelson DeMille', 'Abused wives', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 5 FROM public.book WHERE isbn13 = '9780751531244' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('72709c2a-166e-543d-a794-5ebd40ca3ff8', '9780751533118', 'The Waiting Sands', 'qalsewAACAAJ', 'Dearest Raye,'' Decima had written...''I''m writing to ask if you can possibly come up to Ruthven for a few days. My twenty-first birthday falls next Sunday, and it would be such a relief if you could stay until after the celebration dinner party which Charles is giving for me on Saturday night. Please come, Raye. I may be behaving very stupidly by panicking like this, but I would feel so much less frightened if I knew you were beside me at Ruthven till after midnight on Saturday...'' Dependable Rachel Lord hasn''t heard from her friend Decima for over two years when out of the blue she is invited to Ruthven, the fairy tale Scottish castle that Decima will inherit on her coming of age. Her arrival is met with relief by Decima who is convinced her husband, Charles, means her harm. Is Decima in her right mind? Or is Rachel being duped by her worldlier friend? As the eve of the 21st birthday celebration approaches, a shocking event leaves Rachel in no doubt.', 'en', 2002, 192, 'http://books.google.com/books/content?id=qalsewAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4563', 'accepted', 'Susan Howatch', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 4 FROM public.book WHERE isbn13 = '9780751533118' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4fe0c3e8-dec8-5066-858d-cc0e96e31978', '9780751533439', 'The Dream Kingdom', 'oRBdGwAACAAJ', 'Edwardian England is a country at the peak of its power; a kingdom of peace, prosperity and progress. As Jessie and Violet enjoy their coming-out in the glittering Season of 1908, their thoughts are of pleasure, dancing and falling in love. For the Morlands things seem set fair: new business ventures expand their influence and wealth; there are weddings, babies in the nursery, careers for the boys now reaching manhood. It is an exciting age, with new technologies - motor cars, telephones, radio, aeroplanes - extending man''s control over the natural world. But under the appearance of permanence, a different reality is stirring. Socialism, the suffrage movement, the constitutional crisis, all call forth ever more dissent and anger. Increasingly violent protests and strikes disturb the peace; war with Germany looms ever closer. With the King''s death, it begins to seem that the safe Edwardian world was only a dream, from which the wakening will be hard indeed.', 'en', 2004, 640, 'http://books.google.com/books/content?id=oRBdGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4564', 'accepted', 'Cynthia Harrod-Eagles', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 1 FROM public.book WHERE isbn13 = '9780751533439' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('32c70ef5-e85d-5d3f-a0fc-80b494df164f', '9780751533453', 'The White Road', 'stJpGwAACAAJ', 'August 1914: the whole country is thrilled by the declaration of war. The British Experditionary Force goes off toe France to defend gallant little Belgium, and thousands more young men rush to volunteer, hoping to see action before the war ends at Christmas. At home everyone competes to be doing the most for the war effort. The Morlands have their share of volunteers, and no-one can say they aren''t at the very heart of things. But when Christmas comes the war is far from over, and nine in ten of the men who marched, singing, down the white road to Mons have fallen ...', 'en', 2006, 480, 'http://books.google.com/books/content?id=stJpGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
