INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ebd2e042-25f7-5984-9185-4ecc76e07b1b', '9780751535389', 'Something Borrowed', 'w3BDHAAACAAJ', 'Adopted as a baby, Vicky McCarthy''s curiosity about where she came from has finally got the better of her: she wants to trace her birth mother. If that doesn''t cause friction enough, there''s a new face to contend with at work: Ed O''Neill, whom Vicky is convinced is being groomed for her job as manager of Dublin toyshop Toys Galore. Sal, Vicky''s go-getting best friend, thinks Ed is gorgeous, and that if Vicky doesn''t bag him, she will. But Vicky is going out with Marti, manager of an up-and-coming boy band, with a six-year-old son and complications of his own . . . Something Borrowed is the brilliant fourth novel from Tina Reilly: a fresh, frank, funny tale of loves lost and found.', 'en', 2004, 480, 'http://books.google.com/books/content?id=w3BDHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
