INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5e8a7cf6-9902-5bb8-8543-8ad2fb9b4e42', '9780752224411', 'The Lost World', 'YXhuPQAACAAJ', 'Summer 1997 will see the release of Steven Spielberg''s colossal new film The Lost World: Jurassic Park, the long awaited sequel to the unforgettable and highest grossing film of all time, Jurassic Park ''The Lost World: Jurassic Park Junior Novelisation'' captures all the thrills and chills of The Lost World story, with heart-stopping suspense, hair-raising action and illustrated with colour photographs from the film.', 'en', 1997, 448, 'http://books.google.com/books/content?id=YXhuPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
