INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e6966d68-7995-5867-a6c9-042a5c22aa12', '9780752834528', 'The Sins of the Fathers', 'a09bPgAACAAJ', 'The first novel in the explosive Matthew Scudder Series. The tenth novel in the series - A WALK AMONG THE TOMBSTONES - is set to be a major Hollywood film, starring Liam Neeson. A pretty young girl is butchered in her Greenwich Village apartment. The prime suspect, a minister''s son, is found dead in his jail cell. As far as the NYPD is concerned, the case is closed. But ex-cop Matt Scudder, is persuaded to look into the case by the dead girl''s father. And suddenly he''s up to his neck in sleaze and corruption, phoney religious cults and murderous lust. In New York''s underbelly, the children have no choice but to pay the price for their parent''s most unspeakable sins...', 'en', 2000, 182, 'http://books.google.com/books/content?id=a09bPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
