INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('726cd4f3-d76a-5871-a1a3-d36ca52d9e05', '9780752848266', 'The Next Accident', 'tztXPwAACAAJ', 'FBI Agent Pierce Quincy is haunted by his daughter''s death in a drunk- driving accident. Pierce knew about his daughter''s problem with alcohol, and about her loneliness. And so, he is sure, did the man who killed her. Rainie Conner is an ex-cop with a past overshadowed by violence. She was once involved with Pierce in a harrowing case that brought them together personally and professionally. Then he came to her rescue. Now it is time for her to help him. This killer is different. He has an insatiable hunger for revenge - and for fear. He isn''t satisfied with taking his victims'' lives, he wants to get inside their minds and strip them of every defence. And his target is Quincy''s only surviving daughter. Rainie believes that only way to stop him is to put herself directly into the killer''s murderous path and become - the next accident.', 'en', 2002, 389, 'http://books.google.com/books/content?id=tztXPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
