INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fa041fb9-a66f-5f2a-887f-7e3ac3dbe26a', '9780752851310', 'The Choirboys', 'pUpSPgAACAAJ', 'They are the Choirboys ¿ the patrol squad of the LA Police attempting to stay sane in an insane world. The five sets of partners on the night-watch are men of varying temperaments and backgrounds, but they are joined together by the job and they have elected to spend their pre-dawn hours in MacArthur Park in relaxing drink and sex sessions they call ¿choir practice¿. This is the story of men endangered ultimately not by the violence of their jobs but by their choice of off-duty entertainment. This is a boisterous and freewheeling novel, as chillingly authentic as only a veteran police officer could make it.', 'en', 2002, 368, 'http://books.google.com/books/content?id=pUpSPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4571', 'accepted', 'Joseph Wambaugh', 'Los Angeles (Calif.)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 1 FROM public.book WHERE isbn13 = '9780752851310' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('10330cf0-03a7-536d-bdc8-465cb2154015', '9780752851808', 'The Dain Curse', 'Q7NuHQAACAAJ', 'Miss Gabriel Dain Leggett is young and wealthy, with a penchant for morphine and religious cults. She also has an unfortunate effect on the people around her. They die - violently. Is she the victim of a family curse? The short, squat, utterly unsentimental Continental Op, the best private detective around, has his doubts and finds himself confronting something infinitely more dangerous. This is the Continental Op''s most bizarre case.', 'en', 1929, 256, 'http://books.google.com/books/content?id=Q7NuHQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
