INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dc5cd31c-40f7-587c-b159-ec7b5ec34950', '9780752852614', 'Red Harvest', 'gDKAPwAACAAJ', 'The Continental Op first heard Personville called Poisonville by Hickey Dewey. But since Dewey also called a shirt a shoit, he didn''t think anything of it. Until he went there and his client, the only honest man in Poisonville, was murdered. Then the Op decided to stay to punish the guilty. And that meant taking on the entire town...', 'en', 2003, 224, 'http://books.google.com/books/content?id=gDKAPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
