INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7166417f-3a6f-5c22-b614-980e6abc2779', '9780752857930', 'The Pusher', 'NNdsHAAACAAJ', 'Two a.m. in the bitter cold of winter: the young Hispanic man''s body is found in a tenement basement. The rope around his neck suggests a clear case of suicide - until the autopsy reveals he''d overdosed on heroin. He was a pusher, and now a thousand questions press down on the detectives of the 87th Precinct. Who set up the phony hanging? Whose fingerprints were on the syringe found at the scene? Who was making threatening phone calls, attempting to implicate Lieutenant Byrnes'' teenage son? Somebody is pushing the 87th Precinct hard, and Detective Steve Carella and Lieutenant Pete Byrnes have to push back harder - before a frightening and deadly chain tightens its trip.', 'en', 2003, 192, 'http://books.google.com/books/content?id=NNdsHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
