INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('154d4ca7-fc0d-59cb-bb33-a4385ec60d4b', '9780752858470', 'The Scorpio Illusion', 'nzGOPwAACAAJ', 'Tyrell Hawthorne was a naval intelligence officer until his wife was murdered. Now Hawthorne has been called out of retirement for one last assignment. For he is the only man who can track down the world''s most dangerous terrorist, Amaya Bajaratt, who has set in motion a chilling conspiracy that a desperate government cannot stop. Hawthorne must follow Amaya''s serpentine trail to uncover the sinister network that exists to help this consummate killer. And Hawthorne must discover the shattering truth behind the Scorpio Illusion...', 'en', 2005, 624, 'http://books.google.com/books/content?id=nzGOPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
