INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d2f8021a-f80c-522b-921f-d6b034158e16', '9780752858623', 'Trevayne', 'qfVhPwAACAAJ', 'Trevayne was a self-made millionaire by the time he was thirty. Then he went into government, carving out a brilliant and honourable career. Now he is head of one of the biggest foundations in the USA. Fearless, intelligent and incorruptible, he thinks no one can touch him... Then his investigation into the ''secret government'' leads him beyond the corridors of official power into a nightmare maze where Mafia leaders and ''legitimate'' billionaires mix, where even the Presidency can be bought and sold. And where a man like Trevayne can be a dreaded enemy, a duped victim, or maybe - just maybe - a king.', 'en', 2004, 528, 'http://books.google.com/books/content?id=qfVhPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
