INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1a0d98f5-77aa-56a3-b5a9-b7b20381c27a', '9780752858654', 'The Scarlatti Inheritance', 'k013PwAACAAJ', 'In Washington, word is received that an elite member of Nazi High Command is willing to defect and divulge information that will shorten the war. But his defection entails the release of the ultra top-secret file on the Scarlatti Inheritance - a file whose contents will destroy many of the Western world''s greatest and most illustrious reputations if they are made known...', 'en', 2004, 381, 'http://books.google.com/books/content?id=k013PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
