INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a759a6c2-2c9c-598b-aab0-08ba8d21b6fe', '9780752858937', 'Beasts', '5eg7QgAACAAJ', 'A bright, talented junior at Catamount College in the druggy 1970s, Gillian Brauer strives to realise more than a poet''s craft in her workshop with the charismatic, anti-establishment professor Andre Harrow. For Gillian has fallen in love - with Harrow, with his aesthetic sensibility and bohemian lifestyle, with his secluded cottage, with the mystique of his imposing, russet-haired French wife, Dorcas. A sculptress, Dorcas has outraged the campus and alumnae with the crude, primitive, larger than life-sized wooden totems that she has exhibited under the motto ''We are beasts and this is our consolation''.As if mesmerised, Gillian enters the rarefied world of the Harrows. She is special, even though she knows her classmates have preceded her here. She is helpless. She is powerful. And she will learn in full the meaning of Dorcas'' provocative motto . . .', 'en', 2004, 138, 'http://books.google.com/books/content?id=5eg7QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
