INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c010b043-bd91-5704-b1e8-ec819dde28b9', '9780753459645', 'I Wonder Why the Sun Rises', 'SqpYsTCG6bMC', 'What is a leap year? Why are bees busy in summer? Who eats the moon? Why does it get dark at night? In I Wonder Why the Sun Rises by Brenda Walpole children will find out the answers to these and many more questions about time and seasons.', 'en', 2006, 32, 'http://books.google.com/books/content?id=SqpYsTCG6bMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
