INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('42a4e9b1-a466-5ba7-912e-0d3dd9f50059', '9780753806791', 'Eden in the East', 'C01yQgAACAAJ', 'This book completetly changes the established and conventional view of prehistory by relocating the Lost Eden—the world''s first civilisation—to Southeast Asia. At the end of the Ice Age, Southeast Asia formed a continent twice the size of India, which included Indochina, Malaysia, Indonesia, and Borneo. In Eden in the East, Stephen Oppenheimer puts forward the astonishing argument that here in southeast Asia—rather than in Mesopotamia where it is usually placed—was the lost civilization that fertilized the Great cultures of the Middle East 6,000 years ago. He produces evidence from ethnography, archaeology, oceanography, creation stories, myths, linguistics, and DNA analysis to argue that this founding civilization was destroyed by a catastrophic flood, caused by a rapid rise in the sea level at the end of the last ice age.', 'en', 1998, 575, 'http://books.google.com/books/content?id=C01yQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4586', 'accepted', 'Stephen Oppenheimer', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 11 FROM public.book WHERE isbn13 = '9780753806791' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8dcf4405-1587-5c4f-8263-37599cea3a67', '9780753809259', 'The White Hotel', '_npfQgAACAAJ', '"It is a dream of electrifying eroticism and inexplicable violence, recounted by a young woman to her analyst, Sigmund Freud. It is a horrifying yet restrained narrative of the Holocaust. It is a searing vision of the wounds of our century, and an attempt to heal them. Interweaving poetry and case history, fantasy and historical truth-telling, Thw white hotel is a modern classic of enduring emotional power that attempts nothing less than to reconcile the notion of individual destiny with that of historical fate."--Back cover.', 'en', 1999, 240, 'http://books.google.com/books/content?id=_npfQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4587', 'accepted', 'D. M. Thomas', 'Austria', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 6 FROM public.book WHERE isbn13 = '9780753809259' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1b2ab4aa-0d22-5fdd-b2d8-02e663a501f8', '9780753810743', 'Arthur and the Lost Kingdoms', 'g28qHAAACAAJ', 'Moffat builds up a thesis which enables him to reveal the location and identity of the real Arthur, asserting that he was not a king but a cavalry general chosen around 500AD to lead a coalition army. The key to this argument lies in place-names and their derivation, and that the lost medieval city of Roxburgh and its castle were Arthur''s Camelot.', 'en', 2000, 282, 'http://books.google.com/books/content?id=g28qHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4588', 'accepted', 'Alistair Moffat', 'Great Britain', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 18 FROM public.book WHERE isbn13 = '9780753810743' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5e2124cf-fa3c-51c8-950a-2a0ad2ee4e04', '9780753811467', 'Maya', 'z0tIPgAACAAJ', 'A chance meeting on the Fijian island of Taveuni is the trigger for a fascinating and mysterious novel that intertwines the stories of John Spooke, an English author who is grieving for his dead wife; Frank Andersen, a Norwegian evolutionary biologist estranged from his wife Vera; and an enigmatic Spanish couple, Ana and Jose, who are absorbed in their love for each other. Why does Ana bear such a close resemblance to the model for Goya''s famous Maja paintings? What is the significance of the Joker as he steps out of his pack of cards? As the action moves from Fiji to Spain, from the present to the past, unfolding further stories within the stories, the novel reveals an astonishing richness and complexity. As bold and imaginative in its sweep as Sophie''s World, it shows again that Jostein Gaarder''s unique and special gift is to make us wonder at the awe-inspiring mystery of the universe.', 'en', 2001, 352, 'http://books.google.com/books/content?id=z0tIPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4589', 'accepted', 'Jostein Gaarder', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 16 FROM public.book WHERE isbn13 = '9780753811467' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a23fbc40-ce9b-5009-8924-5127f2b7cfd6', '9780753813959', 'Pure Drivel', '3pGFPwAACAAJ', '''A mix of urbane wit and surreal extrapolations - Douglas Adams meets Flann O''Brien'' Independent Who else but Steve Martin could combine irrefutable evidence that Mars is populated by kittens with a treatise on sledgehammers? In this brilliantly witty collection of pieces Steve Martin takes a subversive glimpse at the world and a sideways swipe at the conventional. From memory tips for the over-fifties to his insightful exposition of ''Wittgenstein''s Banana'', never has ''pure drivel'' been so entertaining.', 'en', 2003, 144, 'http://books.google.com/books/content?id=3pGFPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4590', 'accepted', 'Steve Martin', 'Surealism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 3 FROM public.book WHERE isbn13 = '9780753813959' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b7103a13-8b3e-5946-a63d-5b562f6f6b7d', '9780753814413', 'My Favourite Year', 'W2e4SQAACAAJ', 'Roddy Doyle¿s account of the Republic of Ireland¿s triumphant journey through Italia ¿90 is just one of the many first-class pieces in this anthology of original football writing. Contributors include: Roddy Doyle, Harry Pearson, Harry Ritchie, Ed Horton, Olly Wicken, D.J. Taylor, Huw Richards, Nick Hornby, Chris Pierson, Matt Nation, Graham Brack, Don Watson and Giles Smith. ¿A new kind of football writing developed ¿ passionate, disrespectful, self-mocking, yet steeped in personal bias. In book form, young writers such as Nick Hornby and Pete Davies became to the New Football Writing what Tom Wolfe and Hunter S. Thompson had been to the New Journalism¿ Terence Blacker, Sunday Times', 'en', 2001, 288, 'http://books.google.com/books/content?id=W2e4SQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4591', 'accepted', 'Nick Hornby', 'Sports & Recreation', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 7 FROM public.book WHERE isbn13 = '9780753814413' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c96e2db0-cd95-56e4-b14c-d65eef027037', '9780753817988', 'Mouse Or Rat?', 'R9B9QgAACAAJ', 'Based on a series of lectures on translation, these essays are discussions on the difficulties of translating faithfully. Using examples from classic literary texts including his own novels, Eco examines the rights and wrongs, the misunderstandings and the ''negotiations'' needed in order to translate.', 'en', 2004, 208, 'http://books.google.com/books/content?id=R9B9QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4592', 'accepted', 'Umberto Eco', 'Language Arts & Disciplines', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 20 FROM public.book WHERE isbn13 = '9780753817988' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4a77c25f-eeff-5874-bcad-169d852dbe38', '9780753819920', 'The Orange Girl', 'DoznGwAACAAJ', '''My father died eleven years ago. I was only four then. I never thought I''d hear from him again, but now we''re writing a book together'' To Georg Røed, his father is no more than a shadow, a distant memory. But then one day his grandmother discovers some pages stuffed into the lining of an old red pushchair. The pages are a letter to Georg, written just before his father died, and a story, ''The Orange Girl''. But ''The Orange Girl'' is no ordinary story - it is a riddle from the past and centres around an incident in his father''s youth. One day he boarded a tram and was captivated by a beautiful girl standing in the aisle, clutching a huge paper bag of luscious-looking oranges. Suddenly the tram gave a jolt and he stumbled forward, sending the oranges flying in all directions. The girl simply hopped off the tram leaving Georg''s father with arms full of oranges. Now, from beyond the grave, he is asking his son to help him finally solve the puzzle of her identity.', 'en', 2005, 151, 'http://books.google.com/books/content?id=DoznGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4593', 'accepted', 'Jostein Gaarder', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 7 FROM public.book WHERE isbn13 = '9780753819920' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cf03f197-9a19-5d92-b138-6e280e538e0d', '9780753821862', 'Razor''s Edge', 'TgwoAAAACAAJ', 'The controversial memoir of a top British spy which finally reveals what really went on behind the scenes of the Falklands War For five years before the Falklands War, Hugh Bicheno was one of the top British spies in Argentina. As such, he gathered hard, corroborated intelligence on Argentine intentions over the Falklands - which the British establishment then chose to ignore. The reasons behind this British decision, and its disastrous and inevitable consequences in the South Atlantic, are the main story of this book. There were three main players in the war, each of them trying to overcome their own cultural baggage. The Argentines were riddled with guilt: after years of fighting a morally repugnant campaign against its own people, the Argentine military saw a war for the Malvinas islands as a perfect opportunity to win back their self-respect. The hands of the Americans were also bloody from the likewise dirty wars they had sponsored and abetted in Central America. For Britain it was simply the last straw after decades of humiliation.', 'en', 2007, 400, 'http://books.google.com/books/content?id=TgwoAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4594', 'accepted', 'Hugh Bicheno; Richard Holmes', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 19 FROM public.book WHERE isbn13 = '9780753821862' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0a343606-2c36-5d5b-9a53-f745a693a919', '9780755301942', 'Atlantic Shift', 'zu04HQAACAAJ', 'Gorgeous, world-famous cellist Evie Silverman is classical-lite through and through. Real musicians despise her. Her talent has been promoted way beyond its value because - apparently - everyone loves a blonde girl in lipstick who can do interesting things between her thighs. She''s played for the President of the United States. She''s played at No 10 Downing Street. And tonight she''s playing for Royalty. But tonight she''s also going to change her life. Tonight she''s going to leave her husband. Tonight, for the first time in fifteen years, she''s going to stand on her own two feet. For tomorrow begins her new life - starting with a trip to New York. It all too soon becomes apparent that breaking the rules - and escaping from your past - isn''t what it''s cracked up to be...', 'en', 2005, 406, 'http://books.google.com/books/content?id=zu04HQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
