INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4b6b9a45-3e7e-5e33-bf46-aec4f183bb5d', '9780755301973', 'Full Speed', 'lclXPgAACAAJ', 'Treat yourself to FULL SPEED by Janet Evanovich and Charlotte Hughes. Praise for the FULL series: ''A fine romance with plenty of kisses'' Mirror; ''A wild mix of intrigue, sex and pyrotechnics'' The Times Their enemies haven''t got a prayer... Journalist Jamie Swift and millionaire Max Holt drive each other crazy when they work together - but they just can''t stop. Especially when they both have their reasons for wanting to investigate a charismatic preacher with suspected ties to the Mob and a long history with his female church members. The trouble is, someone has got wind of Jamie and Max''s snooping around, and is pretty eager to introduce them to their Maker - a lot sooner than either Jamie or Max had planned...', 'en', 2003, 344, 'http://books.google.com/books/content?id=lclXPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
