INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d3cb5f1f-710c-57be-b348-67647b8808b1', '9780755304851', 'Falling for You', 'K3zCGwAACAAJ', 'Love is always just around the corner in a Jill Mansell novel - with a few surprises and a lot of humour on the way to happiness Maddy Harvey was a bit of an ugly duckling as a teenager, what with her NHS specs, unfortunate hair and wonky teeth. Thankfully she''s blossomed since then. But when she meets Kerr McKinnon one starry summer''s night and discovers, days later, who he actually is... well, that''s when the problems really start. Because everyone in Ashcombe knows what happened eleven years ago, and as far as her mother''s concerned, Marcella would rather tear that family to pieces with her bare hands than see Maddy associate with a McKinnon. It''s Romeo and Juliet all over again. Quick, hide those sharp knives and that little bottle of poison...', 'en', 2004, 448, 'http://books.google.com/books/content?id=K3zCGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
