INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dea2345c-0166-59aa-88cd-d2191d28258b', '9780755305308', 'Girl in Hyacinth Blue', 'CHg8PgAACAAJ', 'Girl in Hyacinth Blue tells the story of an imaginary painting by Vermeer, and the aspirations and longings of those whose lives it illuminates, and darkens. From a proud father regretting his lost love to a compromised French noblewoman, from a hanged girl to Vermeer''s own gifted daughter, Susan Vreeland''s beautiful and luminous tales link to form an evocative jewel.', 'en', 2002, 180, 'http://books.google.com/books/content?id=CHg8PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
