INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('892bdcf2-4bd4-5157-a7af-831bc91b1eb1', '9780755311514', 'The Science of Harry Potter', '0VCgNwAACAAJ', 'Invisibility cloaks, flying broomsticks, magic doors - all the stuff of children''s fantasy. But have you ever wondered if this magic could feasibly work? Roger Highfield explores the world of the Harry Potter stories and shows how cutting edge science can explain much of it. Exciting scientific concepts such as wormholes and general relativity and he also offers explanations for the more historical links between magic and science, investigating the archaelogical and anthropological evidence for witchcraft and dragons.', 'en', 2002, 374, 'http://books.google.com/books/content?id=0VCgNwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
