INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('016279e0-0acf-5e8c-98f0-6f3fa1c1cb97', '9780755321384', 'After the Mourning', 'DF_GPAAACAAJ', 'In the dark days of the Blitz, crime goes undercover... Undertaker Francis Hancock has seen the worst that humanity can do to itself. Why then does the murder of a young gypsy girl in Epping Forest move him so much? Travellers, gypsies, the homeless, deserters and German spies inhabit this stretch of open ground that was once her home. Francis knows it''s not wise to delve into this human melting pot, but he is drawn to the exotic customs of the gypsies, their music and magic. But as he investigates the girl''s murder further, the death toll rises and Francis uncovers a much bigger conspiracy, at the heart of which lies something even Adolf Hitler is prepared to kill for...', 'en', 2006, 352, 'http://books.google.com/books/content?id=DF_GPAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
