INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3aa46be3-bba6-5819-8487-a6c4856102cb', '9780760329634', 'The John Deere Two-Cylinder Tractor Encyclopedia', 'RO0ungEACAAJ', 'Here are the simple farm machines, the trusty green two-cylinder tractors that pulled agriculture from horses to horsepower. Compiled by the historian chosen by Deere & Company to write its story, this encyclopedia unfolds the full model-by-model history of the worlds most popular tractor--from the first one produced in 1914 to the last in 1960. Brochures and toys, archival photographs and new color images lovingly depict every facet of these sturdy machines. Entries profile the model variations and specs, the options and historical features of the John Deere two-cylinder tractor through the decades, a classic sight on the American horizon.', 'en', 2007, 256, 'http://books.google.com/books/content?id=RO0ungEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4634', 'accepted', 'Don Macmillan; Wayne G. Broehl', 'Reference', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 2 FROM public.book WHERE isbn13 = '9780760329634' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1fd10b53-8a0b-5224-bb89-dea58339644a', '9780760768952', 'The Conquest of Gaul', 'AYuHPwAACAAJ', 'Among the most durable and engaging texts in world literature, Julius Caesar''s Conquest of Gaul tells how he and his legions conquered much of modern France in less than a decade (58-51 BCE), despite determined resistance. Perhaps the most famous Roman ever, Gaius Julius Caesar created a legacy which has resonated, for good or ill, throughout Western culture. Architect of an imperial system, eponymous sponsor of a reformed calendar system, orator second only to Cicero, conqueror of Gaul: Surely those accomplishments in the diverse fields of politics, applied mathematics, rhetoric, and military science would justify his eminence. Nevertheless, the high literary quality and historical value of this seemingly modest account match its exciting story of diplomatic maneuverings, shifting alliances, and military actions; the final chapters culminate in the revolt of the united Gallic tribes under Vercingetorix, France''s first national hero, and are as compelling as any contemporary spy thriller.', 'en', 2005, 288, 'http://books.google.com/books/content?id=AYuHPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
