INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('70f01ffe-4e02-5309-b3a0-5e7479962d24', '9780761555483', 'Elder Scrolls IV', 'WeTBAQAACAAJ', 'Find Your Path! ·Detailed maps for every part of the world and every major city, plus special maps for every key section of the main quest. ·Specific chapters on how to create your character and maximize your abilities and skills. ·Over 400 full-color pages packed with information on everything you need to know about the massive gameworld of Oblivion. ·Walkthroughs for every quest in the game, including the main quest, all faction quests, as well as miscellaneous and freeform quests. ·Sections on various gameplay systems including stealth, combat, magic, spellmaking and enchanting, alchemy, and more. ·Detailed bestiary chapter to help you best deal with the denizens of Tamriel and Oblivion. ·Includes new chapters on Knights of the Nine and Oblivion downloadable content.', 'en', 2006, 432, 'http://books.google.com/books/content?id=WeTBAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
