INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ab0d6fa1-e381-52cc-ad39-1d4780024b90', '9780761956921', 'Société de Consommation', 'Bbex0zAG23IC', 'Now available in English for the first time, Jean Baudrillard''s classic text was one of the first to focus on the process and meaning of consumption in contemporary culture. Originally published in 1970, the book still makes a vital contribution to current debates on consumption. Many of the themes which would make Baudrillard famous appear here for the first time. The book includes Baudrillard''s most organized discussion of mass media culture, the meaning of leisure and anomie in affluent society. A chapter on the body demonstrates Baudrillard''s extraordinary prescience for flagging vital subjects in contemporary culture long before others. This English translation begins with an introductory essay by Ge', 'en', 1998, 224, 'http://books.google.com/books/content?id=Bbex0zAG23IC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
