INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c6694917-0992-5aac-9323-a130f50d0cee', '9780764226465', 'A Higher Justice', 'j6ENAAAACAAJ', 'A case involving a trolley accident pits Kit against powerful railway men, all of whom have something to hide. The truth may blow the lid off a conspiracy, so will her enemies find a way to keep her silenced forever?', 'en', 2003, 303, 'http://books.google.com/books/content?id=j6ENAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
