INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('07fe2fe7-7b5b-5a60-98fd-677b2df9cabd', '9780764538131', 'CliffsNotes on Dostoevsky''s The Brothers Karamazov', 'J9j6zAEACAAJ', 'Dostoevsky''s last novel is considered his masterpiece and tells the story of a family and the appetites and struggles that lead to patricide. With rich character development and understanding of humanity, Dostoevsky comes across as a force of nature.', 'en', 2003, 96, 'http://books.google.com/books/content?id=J9j6zAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
