INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ef2a6c30-e8dc-5d71-8e96-144018b62008', '9780764586019', 'CliffsNotes on Fitzgerald''s The Great Gatsby', 'gu5aWm1m260C', 'The original CliffsNotes study guides offer a look into key elements and ideas within classic works of literature. The latest generation of titles in this series also features glossaries and visual elements that complement the familiar format. CliffsNotes on The Great Gatsby explores F. Scott Fitzgerald''s novel of triumph, tragedy, and a classic love triangle in the 1920s. Following the story of a young Midwesterner who''s fascinated by the mysterious past and opulent lifestyle of his landlord, this study guide provides summaries and critical commentaries for each chapter within the novel. Other features that help you figure out this important work include Personal background on the author Introduction to and synopsis of the book In-depth character analyses Critical essays on topics of interest Review section that features interactive questions and suggested essay topics and practice projects Resource Center with books, videos, and Web sites that can help round out your knowledge Classic literature or modern-day treasure — you''ll understand it all with expert information and insight from CliffsNotes study guides.', 'en', 2000, 96, 'http://books.google.com/books/content?id=gu5aWm1m260C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
