INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8aed16d4-e040-57db-b2ea-37fe916a95a4', '9780764586552', 'CliffsNotes on Dstoevsky''s Crime and Punishment', 'lWeD6EpnlWYC', 'The original CliffsNotes study guides offer a look into critical elements and ideas within classic works of literature. The latest generation of titles in this series also feature glossaries and visual elements that complement the classic, familiar format. CliffsNotes on Crime and Punishment takes you into a masterpiece of Russian literature, a work published during the time the western world was moving away from romanticism and into a new realistic approach to writing. Following the story of an impoverished young man who expects to enrich humanity by rising to a level above the law, this study guide provides a character list, character map, and character analyses to explore the personalities within Fyodor Dostoevsky''s masterpiece. Other features that help you figure out this important work include Life and background of the author Introduction to and brief synopsis of the novel Summaries and expert commentaries for each chapter within the book Essays that explore aspects of the author''s characters and theories A review section that tests your knowledge and suggests essay topics and practice projects A Resource Center full of books, publications, films, and Internet resources Classic literature or modern-day treasure — you''ll understand it all with expert information and insight from CliffsNotes study guides.', 'en', 2000, 128, 'http://books.google.com/books/content?id=lWeD6EpnlWYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
