INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1a61040e-bd4f-5fe0-aa34-2a70bd3b18f5', '9780765308375', '7 Steps to Midnight', 'EgI7aR2Tw_8C', 'After his identity and life is stolen by a mysterious imposter, mathematician Chris Barton must elude killers as he follows a series of cryptic messages that lead him around the world to a rendezvous with an enigmatic woman. By the author of Somewhere in Time. Reprint. 20,000 first printing.', 'en', 2003, 320, 'http://books.google.com/books/content?id=EgI7aR2Tw_8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
