INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cf8dd3c4-20f4-5f8f-9463-5329a778cf5a', '9780765311856', 'Outside the Dog Museum', 'pxvc3ufQddIC', 'Recently divorced after an inexplicable nervous breakdown, award-winning architect and womanizing opportunist Harry Radcliffe is unexpectedly enlisted by the wealthy Sultan of Saru to design a billion-dollar dog museum, an assignment that introduces him to a magical culture beyond anything he has ever imagined. Reprint. 20,000 first printing.', 'en', 2005, 267, 'http://books.google.com/books/content?id=pxvc3ufQddIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
