INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4d71de7f-7d30-5852-b950-ddce3d4fb70c', '9780765311863', 'Sleeping in Flame', '-4v6sdwLliAC', 'Falling in love with a beautiful artist who creates cities, Vienna screenwriter Walker Easterling discovers that he has developed the ability to see into the near future and is referred to a shaman who helps him tour his numerous interconnected past lives. By the author of The Land of the Laughs and The Wooden Sea. Reprint. 25,000 first printing.', 'en', 2004, 304, 'http://books.google.com/books/content?id=-4v6sdwLliAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
