INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e36ae282-54c7-543f-b528-9c85ccf65ac1', '9780765312808', 'Someone Comes to Town, Someone Leaves Town', 'tTamUiYMmlsC', 'Having recently moved to a bohemian Toronto neighborhood, middle-aged entrepreneur Alan learns his next-door neighbor''s struggle to conceal her wings and hides his own secrets about his unusual family, which includes Russian nesting doll brothers, one of whom is bent on revenge. By the author of Down and Out in the Magic Kingdom. Reprint. 20,000 first printing.', 'en', 2006, 315, 'http://books.google.com/books/content?id=tTamUiYMmlsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4726', 'accepted', 'Cory Doctorow', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 10 FROM public.book WHERE isbn13 = '9780765312808' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9547339e-288f-5d3d-af3a-b28204893ec3', '9780765312921', 'Hunters of Dune', 'gGlnvgAACAAJ', 'Hunters of Dune and the concluding volume, Sandworms of Dune, bring together the great story lines and beloved characters in Frank Herbert''s classic Dune universe, ranging from the time of the Butlerian Jihad to the original Dune series and beyond. Based directly on Frank Herbert''s final outline, which lay hidden in a safe-deposit box for a decade, these two volumes will finally answer the urgent questions Dune fans have been debating for two decades. At the end of Chapterhouse: Dune--Frank Herbert''s final novel--a ship carrying the ghola of Duncan Idaho, Sheeana (a young woman who can control sandworms), and a crew of various refugees escapes into the uncharted galaxy, fleeing from the monstrous Honored Matres, dark counterparts to the Bene Gesserit Sisterhood. The nearly invincible Honored Matres have swarmed into the known universe, driven from their home by a terrifying, mysterious Enemy. As designed by the creative genius of Frank Herbert, the primary story of Hunters and Sandworms is the exotic odyssey of Duncan''s no-ship as it is forced to elude the diabolical traps set by the ferocious, unknown Enemy. To strengthen their forces, the fugitives have used genetic technology from Scytale, the last Tleilaxu Master, to revive key figures from Dune''s past--including Paul Muad''Dib and his beloved Chani, Lady Jessica, Stilgar, Thufir Hawat, and even Dr. Wellington Yueh. Each of these characters will use their special talents to meet the challenges thrown at them. Failure is unthinkable--not only is their survival at stake, but they hold the fate of the entire human race in their hands.', 'en', 2006, 524, 'http://books.google.com/books/content?id=gGlnvgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4727', 'accepted', 'Brian Herbert; Kevin J. Anderson', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 10 FROM public.book WHERE isbn13 = '9780765312921' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('914aa0bc-6539-55d0-b1f2-04bdf5b4e403', '9780765312938', 'Sandworms of Dune', 'tCv5jwEACAAJ', 'At the end of Frank Herbert''s final novel, Chapterhouse: Dune, a ship carrying a crew of refugees escapes into the uncharted galaxy, fleeing from a terrifying, mysterious Enemy. The fugitives used genetic technology to revive key figures from Dune''s past--including Paul Muad''Dib and Lady Jessica--to use their special talents to meet the challenges thrown at them. Based directly on Frank Herbert''s final outline, which lay hidden in two safe-deposit boxes for a decade, Sandworms of Dune will answer the urgent questions Dune fans have been debating for two decades: the origin of the Honored Matres, the tantalizing future of the planet Arrakis, the final revelation of the Kwisatz Haderach, and the resolution to the war between Man and Machine. This breathtaking new novel in Frank Herbert''s Dune series has enough surprises and plot twists to please even the most demanding reader.', 'en', 2007, 494, 'http://books.google.com/books/content?id=tCv5jwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
