INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5d29a230-5d19-5f71-bcf3-35233412e459', '9780765313195', 'Jinx High', 'GE3ligfOGg8C', 'While enjoying a visit with an old friend in Tulsa, Oklahoma, Diana Tregarde discovers that a malevolent combination of sex and blood magic is behind relatively normal teenage jealousies and infatuations at the local high school, one ruled by Fay Harper, a powerful sorceress hundreds of years old who takes over the bodies of her own daughters to remain eternally young. Reprint. 15,000 first printing.', 'en', 2006, 335, 'http://books.google.com/books/content?id=GE3ligfOGg8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
