INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0a39f860-ae16-5986-b34a-3ecb138af88d', '9780765316929', 'Voices From the Street', 'ZZjDxhPuDT4C', 'In 1950s Oakland, California, Stuart Hadley, a young radio electronics salesman, puts his perfect life at risk as his growing anger, anxiety, and fear results in a quest to fill the void with drinking, sex, and religious fanaticism.', 'en', 2007, 301, 'http://books.google.com/books/content?id=ZZjDxhPuDT4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
