INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4fcf9d13-e012-5ffb-9c91-1ad897edab14', '9780765340740', 'The Pillars of Creation', 'Cr4tHm6k_cUC', 'Seeking to silence the inhuman voices in her head, young Lauren triggers a series of events that forces her to participate in a vengeful quest, pitting Richard Rahl and his wife Kahlan against a relentless demonic force. Reprint.', 'en', 2002, 725, 'http://books.google.com/books/content?id=Cr4tHm6k_cUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
