INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('330f1898-8fd2-57ea-a183-76b5d92f6278', '9780765341136', 'Wasteland of Flint', 'dJt30tCjMHAC', 'In a distant future where humans have journeyed throughout space and formed a ruling body called the Empire, Dr. Gretchen Andersen is called upon to discover the whereabouts of a missing survey team that had been searching for artifacts of long-gone interstellar civilizations. Reprint.', 'en', 2004, 512, 'http://books.google.com/books/content?id=dJt30tCjMHAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
