INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a8e27dc1-0f04-503a-9460-99cb0141cd06', '9780765344724', 'Hawkes Harbor', 'rCYqkxt7G34C', 'Haunted by the past he endured for his illegitimacy, Jamie Sommers, believing himself destined to a life of crime, works as a smuggler and murderer on the high seas before encountering a dark force that pushes him to the brink of insanity.', 'en', 2005, 289, 'http://books.google.com/books/content?id=rCYqkxt7G34C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
