INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('335aebd4-5233-5f72-acac-69ea67a14bb9', '9780765345516', 'A Cavern of Black Ice', '8R0OxBb9gfMC', 'A young man and woman from different clans, Raif Sevrance, a member of the Clan Blackhail, and Ash March, a girl who is plagued by sinister dreams, are drawn together by prophecy and plunged into a realm of magic, war, and danger that could determine the fate of their world. Reprint.', 'en', 2005, 769, 'http://books.google.com/books/content?id=8R0OxBb9gfMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
