INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('64bdd515-8093-558b-a4de-0e08a026d51c', '9780765345707', 'In the Land of the Lawn Weenies', 'XFVtWs3w8dQC', 'A collection of humorous stories involves some monstrous students, a levitation trick gone wrong, and a boring neighborhood.', 'en', 2003, 256, 'http://books.google.com/books/content?id=XFVtWs3w8dQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
