INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1be5d1e0-457a-508a-86cc-b1f2c4b9aef2', '9780765348210', 'The Family Trade', 'VuTCidNT2G4C', 'Believing she has found a career-making story when she stumbles upon a money-laundering scheme, reporter Miriam Beckstein is shocked when she is fired and threatened with death, a situation that turns increasingly bizarre when she learns the fate of her murdered mother and is transported to a parallel earth where her family rules a powerful kingdom. Reprint.', 'en', 2005, 308, 'http://books.google.com/books/content?id=VuTCidNT2G4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
