INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3c6b9d61-5bad-574a-b758-4d4cd28e0c22', '9780765350503', 'The Wizard', '96qdmAEACAAJ', 'Sir Able returns to Mythgathr on his steed Cloud, a great mare the color of her name. Able is filled with new knowledge of the ways of the seven-fold world and possessed of great magical secrets. His knighthood now beyond question, Able works to fulfill his vows to his king, his lover, his friends, his gods, and even his enemies. Able must set his world right, restoring the proper order among the denizens of all the seven worlds. The Wizard is a charming, riveting, emotionally charged tale of wonders, written with all the beauty one would expect from a writer whom Damon Knight called "a national treasure."', 'en', 2006, 587, 'http://books.google.com/books/content?id=96qdmAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
