INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('90521b9b-9307-56e8-96aa-9daa94768d19', '9780765350985', 'Godslayer', '98LaKp4-alcC', 'One thousand years after pledging himself to the dark god Satoris, Lord Tanaros works to defend the citadel of Darkhaven from a human uprising, a situation that is complicated by Satoris''s capture of the beautiful Elvish princess, Cerelinde. By the author of Banewreaker. Reprint.', 'en', 2006, 416, 'http://books.google.com/books/content?id=98LaKp4-alcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
