INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e1ace4d1-2391-501b-85e1-2b736129c16f', '9780765351548', 'Debt of Bones', '4V0NmAEACAAJ', 'A milestone of storytelling set in the world of The Sword of Truth, Debt of Bones is the story of young Abby''s struggle to win the aid of the wizard Zedd Zorander, the most important man alive. Abby is trapped, not only between both sides of the war, but in a mortal conflict between two powerful men. For Zedd, who commands power most men can only imagine, granting Abby''s request would mean forsaking his sacred duty. With the storm of the final battle about to break, both Abby and Zedd are caught in a desperate fight to save the life of a child...but neither can escape the shadow of an ancient betrayal. With time running out, their only choice may be a debt of bones. The world-for Zedd, for Abby, for everyone-will never again be the same. Discover why millions of readers the world over have elevated Terry Goodkind to the ranks of legend.', 'en', 2004, 160, 'http://books.google.com/books/content?id=4V0NmAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
