INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1e07b916-95e2-5289-a2d2-110f3bd58373', '9780767909266', 'The Minimalist Cooks at Home', 'F0Z6PQAACAAJ', 'In a revised cookbook, the author of the award-winning How to Cook Everything presents dozens of delectable and accessible recipes, all of which utilize a few choice ingredients and simple preparation, for a wide range of tasty but sophisticated dishes, including 10-Minute Stir-Fried Chicken with Nuts, The Minimalist''s Choucroute, and Paella, Fast and Easy.', 'en', 2002, 240, 'http://books.google.com/books/content?id=F0Z6PQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
