INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4ca27ffe-7880-57fd-b333-f2cbed36862b', '9780767923064', 'Leonardo''s Swans', '4N8mfyt515IC', 'Born into wealth amid the political and artistic foment of the Italian Renaissance, worldly and ambitious Isabella and naïve Beatrice Este, sisters and rivals, compete for the attentions of Ludovico Sforza, the Duke of Milan--even though he marries Beatrice--and must choose between family loyalty and survival amid the treachery of a dangerous era. Reprint. 30,000 first printing.', 'en', 2007, 351, 'http://books.google.com/books/content?id=4N8mfyt515IC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
