INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0e0ef488-bd8a-5821-9152-2d261b8717a6', '9780768423488', 'Experiencing Father''s Embrace', 'FV8vWWvmfCgC', 'Experiencing Father''s Embrace is an excellent resource for anyone interested in growing or ministering in the Father''s love message. The author''s style of writing makes this book easy to read, yet it is one of the most thorough and profoundly impacting books available on knowing God as a Father.', 'en', 2006, 256, 'http://books.google.com/books/content?id=FV8vWWvmfCgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
