INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('be50a767-3280-5c0d-92a8-703721947982', '9780771008740', 'The Handmaid''s Tale', '9orUvwEACAAJ', '(Book Jacket Status: Jacketed) A gripping vision of our society radically overturned by a theocratic revolution, Margaret Atwood’s The Handmaid''s Tale has become one of the most powerful and most widely read novels of our time. Offred is a Handmaid in the Republic of Gilead, serving in the household of the enigmatic Commander and his bitter wife. She may go out once a day to markets whose signs are now pictures because women are not allowed to read. She must pray that the Commander makes her pregnant, for in a time of declining birthrates her value lies in her fertility, and failure means exile to the dangerously polluted Colonies. Offred can remember a time when she lived with her husband and daughter and had a job, before she lost even her own name. Now she navigates the intimate secrets of those who control her every move, risking her life in breaking the rules. Like Aldous Huxley’s Brave New World and George Orwell’s Nineteen Eighty-Four, The Handmaid''s Tale has endured not only as a literary landmark but as a warning of a possible future that is still chillingly relevant.', 'en', 2006, 368, 'http://books.google.com/books/content?id=9orUvwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4795', 'accepted', 'Margaret Atwood', 'Dystopias', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 13 FROM public.book WHERE isbn13 = '9780771008740' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('378fa5a7-7aa6-5081-927d-64ce1931d520', '9780771014178', 'The Jane Austen Cookbook', 'vtgBAAAACAAJ', 'Jane Austen wrote her novels in the midst of a large and sociable family. Brothers and sisters, nieces and nephews, friends and acquaintances were always coming and going, which offered numerous occasions for convivial eating and drinking. One of Jane’s dearest friends, Martha Lloyd, lived with the family for many years and recorded in her “Household Book” over 100 recipes enjoyed by the Austens. A selection of this family fare, now thoroughly tested and modernized for today’s cooks, is recreated here, together with some of the more sophisticated dishes which Jane and her characters would have enjoyed at balls, picnics, and supper parties. A fascinating introduction describes Jane’s own interest in food, drawing upon both the novels and her letters, and explains the social conventions of shopping, eating, and entertaining in late Georgian and Regency England. The book is illustrated throughout with delightful contemporary line drawings, prints, and watercolours. Authentic recipes, modernized for today’s cooks, include: • Buttered Prawns • Wine-Roasted Gammon and Pigeon Pie • Broil’d Eggs • White Soup and Salmagundy • Pyramid Creams • Martha’s Almond Cheesecakes', 'en', 2002, 128, 'http://books.google.com/books/content?id=vtgBAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
