INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b1da39a3-0e17-5265-bfe8-2723ed73c7d2', '9780781731836', 'Kaplan & Sadock''s Synopsis of Psychiatry', 'YX5mQgAACAAJ', 'The best-selling general psychiatry text since 1972, Kaplan and Sadock''s Synopsis of Psychiatry is now in its thoroughly updated Ninth Edition. This complete, concise overview of the entire field of psychiatry is a staple board review text for psychiatry residents and is popular with a broad range of students in medicine, clinical psychology, social work, and occupational therapy. This edition includes new chapters on health care delivery systems and end-of-life care and palliative medicine. Coverage of psychotropic drugs and neuropsychiatric foundations of biological psychiatry has been significantly updated. The book is DSM-IV-TR compatible and replete with case studies and tables, including ICD-10 diagnostic coding tables.', 'en', 2003, 1500, 'http://books.google.com/books/content?id=YX5mQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
