INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b193cc4e-63b0-527c-bce6-1439408aeb02', '9780785114932', 'Homecoming', '2wDmAAAACAAJ', 'The deadliest agent in the Marvel Universe has finally gotten out of the spy game, and she''s not asking for much, just a life of her own. When a sudden assassination attempt provides a harsh reality check, the former Soviet agent tracks a string of international killings that will lead her back to a Russia she can barely recognize. Collects Black Widow #1-6.', 'en', 2005, 144, 'http://books.google.com/books/content?id=2wDmAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
