INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ca704d91-b16a-5e45-9a68-bcd660440fd2', '9780785123262', 'New X-Men Omnibus', '7yJ3wgEACAAJ', 'Sixteen million mutants dead... and that was just the beginning! In one bold stroke, writer Grant Morrison (The Invisibles, JLA, Fantastic Four: 1234) propelled the X-Men into the 21st century - masterminding a challenging new direction for Marvel''s mutant heroes that began with the destruction of Genosha and never let up. Regarded as the most innovative thinker of the current comic-book renaissance, Morrison proceeded to turn the mutant-hero genre on its ear. Gone were the gaudy spandex costumes - replaced by slick, black leather and an attitude to match. Now, his entire Eisner Award-nominated run on New X-Men is collected in one deluxe hardcover! Collects New X-Men #114-154 and Annual 2001', 'en', 2006, 1096, 'http://books.google.com/books/content?id=7yJ3wgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
