INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('807a5843-c092-53c4-9e0a-4a6a74cfa8f5', '9780785260059', 'The Power of One', 'L_FGsSyk2PkC', 'In this 30-day companion workbook to There''s No Such Thing as "Business" Ethics, bestselling author John C. Maxwell demonstrates how we can live with integrity by using the Golden Rule as our standard-in business and in life. In fact, Maxwell suggests the higher standard of exceeding the Golden Rule-by treating people better than they treat us, helping those who cannot help us, doing right when it is natural to do wrong, and keeping promises, even when it hurts. An ethics guide for any situation, each "day" of The Power of One offers a Drilling Down section which features a case study or story that illustrates the day''s topic, Summarizing Principles on the subject, penetrating questions for Making Evaluation, and points of application for Taking Action. Maxwell reveals the factors that can "tarnish" the Golden Rule and teaches how to develop the Midas touch in personal integrity.', 'en', 2004, 256, 'http://books.google.com/books/content?id=L_FGsSyk2PkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4831', 'accepted', 'John C. Maxwell; Thomas G. Addington', 'Business & Economics', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 17 FROM public.book WHERE isbn13 = '9780785260059' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f71ea851-02e5-5081-8b86-2faeb029454a', '9780785263715', 'Searching for God Knows What', 'Hw4gWVAoz8kC', 'Miller reveals how the inability to find redemption leads to chaotic relationships, self-hatred, the accumulation of meaningless material possessions, and a lack of inner peace.', 'en', 2004, 246, 'http://books.google.com/books/content?id=Hw4gWVAoz8kC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
