INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b22735b4-9aa9-5fb8-98f1-e74fe48bd3d8', '9780785263784', 'Only the River Runs Free', 'ElG9KiBi4EEC', 'It was four o''clock on the afternoon of December twenty-fourth, 1841, in the village of Ballynockanor, County of Galway, Province of Connaught, Ireland. It was after mass on the first day of Advent that the old woman, Mad Molly Fahey, had told Father O''Bannon (as well as every farmer, farmer''s wife and child) that a great miracle was coming to visit the poor of Ballynockanor. The village is in sore need of a miracle. Struggling under grinding poverty and a greedy landlord, Ballynockanor is the story of a thousand Irish villages where an English usurper is despied by his Irish tenants.', 'en', 2003, 271, 'http://books.google.com/books/content?id=ElG9KiBi4EEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4833', 'accepted', 'Bodie Thoene; Brock Thoene', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 11 FROM public.book WHERE isbn13 = '9780785263784' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d68e3923-c498-5d07-b171-a2065e86db72', '9780785265436', 'The Blood of the Moon', 'S6wsAQAAIAAJ', '"Allah has bought from the Umma-the true believers of Islam-their selves and their substance in return for Paradise; they fight in the way of Allah, killing and being killed. Their promise is written in the blood of the moon." -From the Koran, chap. 9, v. 112 The conflict between Islam and the West existed long before the destruction of the World Trade Center and the other events that recently touched America. It goes back hundreds, even thousands, of years. Yet the struggle is upon us now as never before. In this well-reasoned, accessible book, Middle East expert George Grant answers the troubling questions on many believers'' minds. Who are the followers of Islam, and what do they believe? What could have motivated those who carried out the acts of terror on September 11? Why has there been tension between Islam and the West for centuries? What are the true meanings of terms such as Ji''had, Intifada, and Dhimma? And is there any hope for peace? The call upon believers now-as always-is to prepare and equip ourselves so that we may stand fast. The Blood of the Moon will help readers better understand the history of Islam and its struggle with the Western world, as well as how Christians can share the message of salvation through Jesus Christ with the followers of Allah.', 'en', 2001, 224, 'http://books.google.com/books/content?id=S6wsAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
