INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('42782f68-256c-5d63-b498-3c857150af9f', '9780786647972', 'Deluxe Encyclopedia of Mandolin Chords', '9TAe6DVyjZgC', 'This encyclopedia is designed to provide mandolin players with a wide variety of chords in different voicings. This book is intended as both a starting point of learning chord voicings and patterns, as well as a dictionary of common mandolin chords. Each key section includes the first position scale for that key, as well as the chord formula and notes for each chord. If you want to learn to be a bluegrass rhythm player it helps to have a guide or ''map'' to take you through the initial learning stage. This book provides a small but powerful set of starter chords used in this style of music. Once these chords are learned, you''ll be able to jam with other musicians in no time. These are the same chords used by greats like Bill Monroe, Doyle Lawson, David Grisman and hundreds of other bluegrass players in this genre. While there are only a few chords presented in the "map" section, they form the foundation of bluegrass mandolin and with them you can play literally thousands of songs in every key. Chords are presented by key.', 'en', 2000, 72, 'http://books.google.com/books/content?id=9TAe6DVyjZgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
