INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2c267033-45b9-5cb4-b377-57553f6f263d', '9780786702275', 'Bad Dreams', 'LTtBch9U8CkC', 'Anne Nielson, an American journalist, comes to London to investigate the strange death of her sister. Soon, she becomes sucked into a netherworld of corruption and perversion and is hurtled toward a final confrontation where she has only the dead as allies. From the author of Anno-Dracula.', 'en', 1995, 280, 'http://books.google.com/books/content?id=LTtBch9U8CkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
