INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b195111f-23d0-52b4-8c1d-7363c95a4f0c', '9780786716234', 'Divine Invasions', 'tL89TqisTVwC', 'An official portrait of the influential novelist''s life and career explores how Dick''s writings expanded the scope of the science fiction genre, served as the inspirations for blockbuster movies, and influenced the written works of such contemporaries as Thomas Pynchon, Don Delillo, and David Foster Wallace. Original.', 'en', 2005, 352, 'http://books.google.com/books/content?id=tL89TqisTVwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
