INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('05b54ed3-d1a5-5c55-a7a0-3ee84b5d0efa', '9780786717675', 'Writing with Intent', 'ZBQXBQAAQBAJ', 'The first collection of nonfiction work by the author in more than two decades features fifty-seven essays and reviews on a wide range of topics, including John Updike, Toni Morrison, grunge, September 11th, and Gabriel Garca Mrquez, among others. Reprint.', 'en', 2006, 448, 'http://books.google.com/books/content?id=ZBQXBQAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
