INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9f323fa4-7a2b-5c57-8757-38baec2c867b', '9780786719051', 'The Mammoth Book of Golden Age Science Fiction', 'Ihn4AAAACAAJ', 'The Golden Age of Science Fiction, from the early 1940s through the 1950s, saw an explosion of talent in SF writing, including authors such as Isaac Asimov, Robert A. Heinlein, and Arthur C. Clarke. Their writing helped science fiction gain wide public attention, and left a lasting impression upon society. The same writers formed the mold for the next three decades of science fiction, and much of their writing remains as fresh today as it was then.', 'en', 2007, 512, 'http://books.google.com/books/content?id=Ihn4AAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
