INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e9bb622b-94e5-5a16-9d6b-7430086f2fb1', '9780786809196', 'Son of the Mob: Hollywood Hustle', 'nTVxh9uxGUEC', 'When Vince heads out to sunny L.A. to go to college, he feels like he is finally going to be able to leave his shady family and their illegal antics behind. Once he arrives at school, he is paired up with the son of a prominent congressman as a roommate-finally some respectability! Not to mention that the girls in college are something else. With his girlfriend, Kendra, giving him such a hard time, Vince is beginning to wonder if single life is the way to go.', 'en', 2006, 268, 'http://books.google.com/books/content?id=nTVxh9uxGUEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
