INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a7006d5d-498f-5d3e-b0ce-4ea1c9ccb31b', '9780786809288', 'The Tales from the Odyssey #1: One-Eyed Giant', 'osALAAAACAAJ', 'When Odysseus must leave his home to fight the Trojan War, he never imagines that he’ll be away from his family for so many years. Now, at long last, he is leading his men home across the seas. But many dangers await them – and none is more terrifying than Polyphemus, the one-eyed giant.', 'en', 2003, 112, 'http://books.google.com/books/content?id=osALAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
