INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6f03d0a8-dc45-5002-a0a3-93178856b306', '9780786809295', 'Tales from the Odyssey: The Land of the Dead - Book #2', 'OwYQ82s5VzIC', 'Odysseus and his men have defeated the one-eyed giant, but its curse follows them at every turn. Cast out to the open seas by the wind god, Odysseus and his fleet continue the difficult journey home. But they cannot return to Ithaca yet. First they must take on giant cannibals and outwit a beautiful witch, who reveals Odysseus’ next challenge – a journey to the mysterious and feared land of the dead.', 'en', 2003, 112, 'http://books.google.com/books/content?id=OwYQ82s5VzIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
