INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('80103947-a544-5619-8be1-ccb1d9e2378f', '9780786809967', 'Be More Chill', 'Yqk9ezeiGvoC', 'Jeremy Heere is your average high school dork. Day after day, he stares at beautiful Christine, the girl he can never have, and dryly notes the small humiliations that come his way. Until the day he learns about the "squip." A pill-sized supercomputer that you swallow, the squip is guaranteed to bring you whatever you most desire in life. By instructing him on everything from what to wear, to how to talk and walk, the squip transforms Jeremy from Supergeek to superchic.', 'en', 2005, 287, 'http://books.google.com/books/content?id=Yqk9ezeiGvoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
