INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('89641d3c-d722-5060-acd8-d3ad69ef7358', '9780786816156', 'Summerland', 't8vDQgAACAAJ', 'A BookSense 76 pick, and best-seller from coast to coast-Summerland is part fantasy, part adventure, part baseball, but most of all it''s the story of a young boy, Ethan Feld-a lousy, but lovable little-leaguer who finds himself playing in the most important baseball game ever. Not only the game, but the fate of the world rests on his shoulders.', 'en', 2004, 500, 'http://books.google.com/books/content?id=t8vDQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
