INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9cd7745e-1f57-5fd8-a27a-841ade04465d', '9780786818723', 'Baby Einstein: Violet''s House', 'bC4HAAAACAAJ', 'Violet, a very curious young mouse, invites babies and toddlers into her home to explore, room by room, her favorite things. Delightfully written rhythmic verse and engaging illustrations lead children to discover the feel of objects that surround them in their everyday world. From touching Violet''s fluffy poodle to joining her as she puts sticky toothpaste on her brush, children will want to visit Violet''s House time and time again.', 'en', 2003, 10, 'http://books.google.com/books/content?id=bC4HAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
