INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f8403d3e-6541-500a-9449-052dbdfc5274', '9780786852970', 'The Meanest Doll in the World', '2gsvPwAACAAJ', 'Annabelle Doll and Tiffany Funcraft are two dolls who have been best friends since they met in Kate Palmer''s house at 26 Wetherby Lane. In this sequel to The Doll People, they hitch a ride in Kate''s backpack and find themselves in the biggest adventure of their lives, a day at school! But when an attempt to return home lands them in the wrong house, they''re in far deeper trouble than they imagined. Along with a host of new doll friends, they also encounter Mean Mimi, the wickedest doll of all. Mean Mimi is mean-really mean-and she''s determined to rule all of Dollkind or else destroy it. Will the world ever be safe for dolls again? In this masterfully plotted sequel, Ann M. Martin and Laura Godwin, with the help of Brian Selznick''s ingenious black-and-white illustrations, take the reader on another nonstop adventure from a doll''s eye view! /DIVDIV', 'en', 2005, 304, 'http://books.google.com/books/content?id=2gsvPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
