INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fb43daac-d51e-587c-a4fe-566e1e58954f', '9780786868698', 'Nigella Bites', '_BpZPQAACAAJ', 'With her charming style, delicious recipes, bestselling cookbooks, and popular cooking show, Nigella Lawson has become a household name -- symbolizing all that is sumptuous and pleasurable about food. In Nigella Bites, Nigella shares her favorite recipes that are easy to make after a busy day at the office, perfect to linger over during a lazy weekend, or fun to make with kids on a rainy afternoon. All the recipes are delectable to read, dreamy to look at, and, of course, delicious to eat. Whether cooking Pasta E Fagioli or baking Orange Breakfast Muffins, Nigella knows just how to achieve maximum flavor with minimum effort.', 'en', 2002, 254, 'http://books.google.com/books/content?id=_BpZPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
