INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('55fcdd52-faf2-526e-abb2-606a08c88849', '9780786885596', 'Dirty Jokes and Beer', 'bD_zwAEACAAJ', '.Drew Carey scripted and starred in his own cable special for years before hooking up with Bruce Helford and creating The Drew Carey Show. He is also the host of his own show Whos Line Is It Anyway? We all know Drew Carey from his award-winning stand-up career and his hit television show, but do we really know Drew Carey, the person Now, meet the true Drew, in his book, the bawdy, irreverent, and hilarious Dirty Jokes and Beer, and find out about all the many sides of the misunderstood Hollywood star.', 'en', 2000, 256, 'http://books.google.com/books/content?id=bD_zwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
