INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e34f370c-cabc-53ef-b2fd-6d698fbe3666', '9780786886326', 'Carter Beats the Devil', 'ArWAQBeA5BUC', 'A powerful and richly textured novel set in 1920 follows Charles Carter, a.k.a. Carter the Great, who has become a master illusionist borne out of loneliness and desperation, as he creates the most outrageous stunt of all involving President Harding--one that could cause his downfall. Reprint. 100,000 first printing.', 'en', 2002, 483, 'http://books.google.com/books/content?id=ArWAQBeA5BUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
