INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('01a89298-84f5-5c40-bd3a-f0891b28b1c9', '9780786890910', 'Lost: Secret Identity - Novelization #2', '54cjAAAACAAJ', 'LOST, the television series, takes place on a remote South Pacific island, where a plane crash has left 48 survivors stranded. This novel focuses on Bernard, a college student with a closely-guarded secret - he-s not really a rich kid but a poor poseur who has been faking it to impress his wealthy girlfriend. Through his encounters with Jack and other major characters as they battle the island wilderness, Bernard starts to realize he-s not alone in keeping up a false front. But as his secret identity is exposed, Bernard finds an inner strength and the courage to face what he may lose - and gain -- by being stranded', 'en', 2006, 176, 'http://books.google.com/books/content?id=54cjAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
