INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('366c99b4-215c-5a5b-bf2c-8a929f29302a', '9780786891078', 'Shopgirl', 'OMRXqLJTl-oC', 'One of our country''s most acclaimed and beloved entertainers, Steve Martin has written a novella that is unexpectedly perceptive about relationships and life. Martin is profoundly wise when it comes to the inner workings of the human heart. Mirabelle is the "shopgirl" of the title, a young woman, beautiful in a wallflowerish kind of way, who works behind the glove counter at Neiman Marcus "selling things that nobody buys anymore..." Slightly lost, slightly off-kilter, very shy, Mirabelle charms because of all that she is not: not glamorous, not aggressive, not self-aggrandizing. Still there is something about her that is irresistible. Mirabelle captures the attention of Ray Porter, a wealthy businessman almost twice her age. As they tentatively embark on a relationship, they both struggle to decipher the language of love -- with consequences that are both comic and heartbreaking. Filled with the kind of witty, discerning observations that have brought Steve Martin critical success, Shopgirl is a work of disarming tenderness.', 'en', 2006, 130, 'http://books.google.com/books/content?id=OMRXqLJTl-oC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
