INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8c8d5a65-3946-5e08-af34-f249e6137d73', '9780787960759', 'The Five Dysfunctions of a Team', 'dsN3CgAAQBAJ', 'In The Five Dysfunctions of a Team Patrick Lencioni once again offers a leadership fable that is as enthralling and instructive as his first two best-selling books, The Five Temptations of a CEO and The Four Obsessions of an Extraordinary Executive. This time, he turns his keen intellect and storytelling power to the fascinating, complex world of teams. Kathryn Petersen, Decision Tech''s CEO, faces the ultimate leadership crisis: Uniting a team in such disarray that it threatens to bring down the entire company. Will she succeed? Will she be fired? Will the company fail? Lencioni''s utterly gripping tale serves as a timeless reminder that leadership requires as much courage as it does insight. Throughout the story, Lencioni reveals the five dysfunctions which go to the very heart of why teams even the best ones-often struggle. He outlines a powerful model and actionable steps that can be used to overcome these common hurdles and build a cohesive, effective team. Just as with his other books, Lencioni has written a compelling fable with a powerful yet deceptively simple message for all those who strive to be exceptional team leaders.', 'en', 2002, 227, 'http://books.google.com/books/content?id=dsN3CgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4913', 'accepted', 'Patrick M. Lencioni', 'Business & Economics', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 6 FROM public.book WHERE isbn13 = '9780787960759' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7d8dc469-cc6b-5c0b-a725-913e2b56847a', '9780787967413', 'Cults in Our Midst', 'lfnFQgAACAAJ', 'Cults today are bigger than ever, with broad ramifications for national and international terrorism. In this newly revised edition of her definitive work on cults, Singer reveals what cults really are and how they work, focusing specifically on the coercive persuasion techniques of charismatic leaders seeking money and power. The book contains fascinating updates on Heaven''s Gate, Falun Gong, Aum Shinrikyo, Hare Krishna, the Reverend Sun Myung Moon, and the connection between cults and terrorism in Al Queda and the PLO.', 'en', 2003, 432, 'http://books.google.com/books/content?id=lfnFQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4914', 'accepted', 'Margaret Thaler Singer', 'Psychology', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 2 FROM public.book WHERE isbn13 = '9780787967413' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f53e9d36-1eec-5c8c-a0cf-b15f7a06fbd2', '9780787968335', 'The Leadership Challenge', 'a7BztgAACAAJ', 'When it was initially written in 1987, few could have predicted that The Leadership Challenge would become one of the best-selling leadership books of all time. Now, faced with the new challenges of our unpredictable global business environment, Jim Kouzes and Barry Posner--two of the country''s premier leadership experts--have completely revised and updated their classic book. Building on the knowledge base of their previous books, the third edition of The Leadership Challenge is grounded in extensive research and based on interviews with all kinds of leaders at all levels in public and private organizations from around the world. In this edition, the authors emphasize that the fundamentals of leadership are the same today as they were in the 1980s, and as they''ve probably been for centuries. In that sense, nothing''s new. Leadership is not a fad. While the content of leadership has not changed, the context has-and in some cases, changed dramatically.', 'en', 2003, 458, 'http://books.google.com/books/content?id=a7BztgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4915', 'accepted', 'James M. Kouzes; Barry Z. Posner', 'Business & Economics', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 0 FROM public.book WHERE isbn13 = '9780787968335' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('392dd673-b346-59d3-89bc-9b717578f133', '9780787976286', 'Becoming a Goddess of Inner Poise', 'wPxcoTocoSAC', 'Today’s young women are smart, educated, career-oriented, and maybe a little bit fashion-obsessed. So where does the spiritual life fit in? With InStyle magazine on one nightstand, and Julian of Norwich on the other, author Donna Freitas has her finger on the pulse of a new generation of women and understands the spiritual issues that most concern them. Drawing on the stories of popular heroines such as Bridget Jones and Carrie Bradshaw, Becoming a Goddess of Inner Poise illustrates how our life choices can have a profoundly spiritual dimension—in the bedroom, the boardroom, the beach, and at Barney’s. Freitas combines wisdom from a variety of spiritual traditions and with a generous dash of humor, giving modern women a new model for the spiritual journey.', 'en', 2004, 239, 'http://books.google.com/books/content?id=wPxcoTocoSAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4916', 'accepted', 'Donna Freitas', 'Social Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 11 FROM public.book WHERE isbn13 = '9780787976286' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f1b865ab-46fe-5104-9ea4-25b6842c0842', '9780787976385', 'Silos, Politics and Turf Wars', 'P17HAgAAQBAJ', 'In yet another page-turner, New York Times best-selling author and acclaimed management expert Patrick Lencioni addresses the costly and maddening issue of silos, the barriers that create organizational politics. Silos devastate organizations, kill productivity, push good people out the door, and jeopardize the achievement of corporate goals. As with his other books, Lencioni writes Silos, Politics, and Turf Wars as a fictional—but eerily realistic—story. The story is about Jude Cousins, an eager young management consultant struggling to launch his practice by solving one of the more universal and frustrating problems faced by his clients. Through trial and error, he develops a simple yet ground-breaking approach for helping them transform confusion and infighting into clarity and alignment.', 'en', 2006, 224, 'http://books.google.com/books/content?id=P17HAgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4917', 'accepted', 'Patrick M. Lencioni', 'Business & Economics', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 20 FROM public.book WHERE isbn13 = '9780787976385' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4bbd464a-d19f-574c-862d-a296739d50da', '9780787981297', 'Organic Church', 'YIFSl1GH5gAC', 'Churches have tried all kinds of ways to attract new and younger members - revised vision statements, hipper worship, contemporary music, livelier sermons, bigger and better auditoriums. But there are still so many people who aren''t being reached, who don''t want to come to church. And the truth is that attendance at church on Sundays does not necessarily transform lives; God''s presence in our hearts is what changes us. Leaders and laypeople everywhere are realizing that they need new and more powerful ways to help them spread God''s Word. According to international church starter and pastor Neil Cole, if we want to connect with young people and those who are not coming to church, we must go where people congregate. Cole shows readers how to plant the seeds of the Kingdom of God in the places where life happens and where culture is formed - restaurants, bars, coffeehouses, parks, locker rooms,and neighborhoods. Organic Church offers a hands-on guide for demystifying this new model of church and shows the practical aspects of implementing it.', 'en', 2005, 237, 'http://books.google.com/books/content?id=YIFSl1GH5gAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
