INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3511bb57-6831-5481-822e-c89b46359b5a', '9780800614287', 'Liturgies of the Western Church', 's8nfEy1H8QcC', 'The liturgies of the Word and the Lord''s Supper that are included in this volume range from those of the church fathers Justin Martyr and Hippolytus through the Roman Mass (in both Latin and English), to the great Reformation liturgies of Luther, Zwingli, Calvin, Knox, Baxter, and Wesley, as well as the Middleburg Liturgy of the English Puritans and the Westminster Directory. In addition to his translations, Thompson draws upon copies of many original documents to insure accuracy. An introduction, which places the liturgy within its tradition, accompanies each text.', 'en', 1980, 434, 'http://books.google.com/books/content?id=s8nfEy1H8QcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
