INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8fa32dfb-fcad-59f8-91b2-17626d4ef617', '9780800871864', 'Silence', 'tQ-CAAAAIAAJ', 'Sustained by dreams of glorious martyrdom, a seventeenth-century Purtuguese missionary in Japan administers to the outlawed Christians until Japanese authorities capture him and force him to watch the torture of his followers, promising to stop if he will renounce Christ.', 'en', 1980, 201, 'http://books.google.com/books/content?id=tQ-CAAAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
