INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('815ee51d-8f40-57b9-a78f-0860dddae619', '9780801489785', 'The River Runs Black', '5FEraqsGy6gC', 'China''s spectacular economic growth over the past two decades has dramatically depleted the country''s natural resources and produced greatly increasing rates of pollution. Elizabeth Economy examines the growing environmental crisis and its implications for future development.', 'en', 2004, 337, 'http://books.google.com/books/content?id=5FEraqsGy6gC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
