INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d92eafb2-6c3d-5357-8bc6-4d9e3c45b604', '9780802131355', 'India Song', '2m160YyDxx4C', 'Unseen voices narrate this story of the affair between the haunting Anne-Marie Stretter and the disgraced French vice-consul in Lahore. In the India of 1937, with the smell of laurels and leprosy permeating the air, the characters perform a dance of doomed love to the strains of a dying colonialism.', 'en', 1988, 146, 'http://books.google.com/books/content?id=2m160YyDxx4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
