INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b25b2b77-ab77-5828-9aa4-f47205ccdb45', '9780802133113', 'Practicalities', 'xWgc9M7DCp8C', '"It''s the women who upset the applecart. Between themselves they talk only about the practicalities of life", declares Duras in this collection of her transcribed conversations with friend Jerome Beaujour. Some of her free-ranging meditations are short and deceptively simple, while many are autobiographical and reveal her most intimate thoughts about motherhood, her struggle with alcohol, her love for a young man, and more.', 'en', 1993, 143, 'http://books.google.com/books/content?id=xWgc9M7DCp8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
