INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bf6f86c6-64b3-55c9-b46d-9dbd31ff542d', '9780802141248', 'Charlie Wilson''s War', 'BYBFUTUSX-EC', 'Describes how, after the 1979 Soviet invasion of Afghanistan, maverick Texas congressman Charlie Wilson persuaded his colleagues to fund the CIA''s efforts to arm the mujahideen and recounts the repercussions of that covert operation.', 'en', 2003, 560, 'http://books.google.com/books/content?id=BYBFUTUSX-EC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
