INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b02ddfb3-43c8-5f75-961f-602c48d25f9a', '9780802151544', 'Destroy, She Said', 'HmklOjlIU3EC', 'In this classic novel by the best-selling author of The Lover, erotic intrigue masks a chillingly deceptive form of madness. Elisabeth Alione is convalescing in a hotel in rural France when she meets two men and another woman. The sophisticated dalliance among the four serves to obscure an underlying violence, which, when the curtain of civilization is drawn aside, reveals in her fellow guests a very contemporary, perhaps even new, form of insanity. Like many of Duras''s novels, Destroy, She Said owes much to cinema, displaying a skillful interplay of dialogue and description. There are recurring moods and motifs from the Duras repertoire: eroticism, lassitude, stifled desire, a beautiful woman, a mysterious forest, a desolate provincial hotel. Included in this volume is an in-depth interview with Duras by Jacques Rivette and Jean Narboni.', 'en', 1986, 133, 'http://books.google.com/books/content?id=HmklOjlIU3EC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
