INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('851060f9-4872-5551-abe8-fd1096d923e3', '9780802715524', 'A History of the World in 6 Glasses', 'sSugAwAAQBAJ', 'An offbeat history of the world traces the story of humankind from the Stone Age to the twenty-first century from the perspective of six different drinks--beer, wine, spirits, coffee, tea, and cola--describing their pervasive influence during pivotal eras of world history, from humankind''s adoption of agriculture to the advent of globalization. Reprint. 40,000 first printing.', 'en', 2006, 336, 'http://books.google.com/books/content?id=sSugAwAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
