INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('115d5872-a29c-5524-a25f-b7b37b655c87', '9780802789471', 'Once Upon a Cool Motorcycle Dude', '9-fBHAAACAAJ', 'Once upon a time there was ... a princess who loved all her beautiful ponies, a cool muscle dude who rode an awesome motorcycle. But a giant came and started stealing them! The dude came to fight the ugly, smelly giant with his mighty sword. She turned gold into thread while she cried for Buttercup, her favorite pony. And he took the princess''s gold thread for payment The end! Wait a minute! That''s not how it ends! Oh no? Once upon a time there was a boy and a girl who had to tell a fairy tale to the class, but they couldn''t agree on the story. Will everyone live happily ever after?', 'en', 2005, 32, 'http://books.google.com/books/content?id=9-fBHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
