INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('eaf608e7-5327-511b-908c-1bdac22fc9ac', '9780802806413', 'The Pilgrim''s Regress', '3ZWvQLtNgtgC', 'The first book written by C. S. Lewis after his conversion, The Pilgrim''s Regress is, in a sense, the record of Lewis''s own search for meaning and spiritual satisfaction -- a search that eventually led him to Christianity. Here is the story of the pilgrim John and his odyssey to an enchanting island which has created in him an intense longing 7mdash; a mysterious, sweet desire. John''s pursuit of this desire takes him through adventures with such people as Mr. Enlightenment, Media Halfways, Mr. Mammon, Mother Kirk, Mr. Sensible, and Mr. Humanist and through such cities as Thrill and Eschropolis as well as the Valley of Humiliation. Though the dragons and giants here are different from those in Bunyan''s Pilgrim''s Progress, Lewis''s allegory performs the same function of enabling the author to say simply and through fantasy what would otherwise have demanded a full-length philosophy of religion.', 'en', 1981, 219, 'http://books.google.com/books/content?id=3ZWvQLtNgtgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
