INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('49412a9b-3318-56f6-80ae-6188877c3387', '9780802829665', 'A Time to Embrace', 'i9AQWs7dco0C', 'As rhetoric continues to heat up on both sides of the debate over same-gender unions, clear, reasoned statements are in short supply. Johnson presents a comprehensive case for acknowledging the legitimacy of same-gender unions in law, politics, and especially religion.', 'en', 2006, 330, 'http://books.google.com/books/content?id=i9AQWs7dco0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
