INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('738ef0af-2931-5c05-9bdd-544792fb8a73', '9780802831620', 'Jesus and the Eyewitnesses', 'IU37uAEACAAJ', 'This momentous book argues that the four Gospels are closely based on the eyewitness testimony of those who personally knew Jesus. Noted New Testament scholar Richard Bauckham challenges the prevailing assumption that the accounts of Jesus circulated as anonymous community traditions, asserting instead that they were transmitted in the names of the original eyewitness. To drive home this controversial point, Bauckham draws on internal literary evidence, the use of personal names in first-century Jewish Palestine, and recent developments in the understanding of oral tradition. "Jesus and the Eyewitnesses" also taps into the rich resources of modern study of memory, especially in cognitive psychology, refuting the conclusions of the form critics and calling New Testament scholarship to make a clean break with this long-dominant tradition. Finally, Bauckham challenges readers to end the classic division between the historical Jesus and the Christ of faith, proposing instead the Jesus of testimony as presented by the Gospels. Sure to ignite heated debate on the precise character of the testimony about Jesus, "Jesus and the Eyewitnesses" is a groundbreaking work that will be valued by scholars, students, and all who seek to understand the origins of the Gospels.', 'en', 2006, 538, 'http://books.google.com/books/content?id=IU37uAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '4995', 'accepted', 'Richard Bauckham', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 15 FROM public.book WHERE isbn13 = '9780802831620' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c4dd33e3-eb5e-5157-811a-59b76fc993fa', '9780802839725', 'The Early History of God', '1yM3AuBh4AsC', 'Foreword by Patrick D. Miller In this remarkable, acclaimed history of the development of monotheism, Mark S. Smith explains how Israel''s religion evolved from a cult of Yahweh as a primary deity among many to a fully defined monotheistic faith with Yahweh as sole god. Repudiating the traditional view that Israel was fundamentally different in culture and religion from its Canaanite neighbors, this provocative book argues that Israelite religion developed, at least in part, from the religion of Canaan. Drawing on epigraphic and archaeological sources, Smith cogently demonstrates that Israelite religion was not an outright rejection of foreign, pagan gods but, rather, was the result of the progressive establishment of a distinctly separate Israelite identity. This thoroughly revised second edition ofThe Early History of God includes a substantial new preface by the author and a foreword by Patrick D. Miller.', 'en', 2002, 243, 'http://books.google.com/books/content?id=1yM3AuBh4AsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
