INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8c3fcc64-b8cd-582d-8025-02b818656446', '9780803283855', 'Black Elk Speaks', 'LHXWwAEACAAJ', 'Black Elk Speaks is the story of the Lakota visionary and healer Nicholas Black Elk (1863-1950) and his people during the momentous twilight years of the nineteenth century. Black Elk met the distinguished poet, writer, and critic John G. Neihardt (1881-1973) in 1930 on the Pine Ridge Reservation in South Dakota and chose Neihardt to tell his story. Neihardt understood and conveyed Black Elk’s experiences in this powerful and inspirational message for all humankind. When Black Elk received his great vision, white settlers were invading the Lakotas’ homeland, decimating buffalo herds, and threatening to extinguish the Lakotas’ way of life. The Lakotas fought fiercely to retain their freedom and way of life, a dogged resistance that resulted in a remarkable victory at the Little Bighorn and an unspeakable tragedy at Wounded Knee. Black Elk Speaks offers much more than a precious glimpse of a vanished time, however. As related by Neihardt, Black Elk’s searing visions of the unity of humanity and the earth have made this book a venerated spiritual classic. Whether appreciated as the poignant tale of a Lakota life, a history of a Native nation, or an enduring spiritual testament, Black Elk Speaks is unforgettable. This new edition features two additional essays by John G. Neihardt that further illuminate his experience with Black Elk; an essay by Alexis Petri, great-granddaughter of John G. Neihardt, that celebrates Neihardt’s remarkable accomplishments; and a look at the legacy of the special relationship between Neihardt and Black Elk, written by Lori Utecht, editor of Knowledge and Opinion: Essays and Literary Criticism of John G. Neihardt. For more information on John G. Neihardt, visit www.neihardt.com', 'en', 2004, 270, 'http://books.google.com/books/content?id=LHXWwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5000', 'accepted', 'Black Elk; John Gneisenau Neihardt; Alexis N. Petri; Lori Utecht', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 20 FROM public.book WHERE isbn13 = '9780803283855' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fd1c7198-94cb-5634-a904-bddf3501c33c', '9780803292451', 'A Lie and a Libel', '_Jc4n1s0_ugC', 'A strange and repugnant mystery of the twentieth century is the durability of the Protocols of the Elders of Zion, a clumsy forgery purporting to be evidence of the supposed Jewish plot to rule the world. Though it has been exposed as a forgery, some apprentice brownshirt is always rediscovering it, the latest in a line of gullibility that includes, most famously, Henry Ford. Recently it has been translated into Japanese and circulates once again with renewed virulence in the former Soviet Union and Eastern Europe. In 1924 in Germany the Jewish author and journalist Binjamin Segel wrote a major historical exposé of the fraud and later edited his work into a shorter form, published as Welt-Krieg, Welt-Revolution, Welf-Verschwörung, Welt-Oberregierung (Berlin 1926). Translator Richard S. Levy, a specialist on the history of anti-semitism, provides an extensive introduction on the circumstances of Segel''s work and the story of the Protocols up to the 1990s, including an explanation of its continuing psychological appeal and political function.', 'en', 1996, 148, 'http://books.google.com/books/content?id=_Jc4n1s0_ugC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
