INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7ad88f32-fad2-50e2-b71c-5fdbfac34cd6', '9780804119436', 'Horse Heaven', 'WyHQMVx77MMC', 'Set in the exciting world of thoroughbred racing, this lavishly detailed novel by the author of A Thousand Acres follows a group of trainers, jockeys, and "track brats" on a two-year journey through the racing cycle. Reprint.', 'en', 2003, 640, 'http://books.google.com/books/content?id=WyHQMVx77MMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
