INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('899bc85b-74f2-53e8-8af9-39225a211bca', '9780804741712', 'Human, All Too Human, I', 'etq_ab9t9qoC', 'This is the second volume to appear in an edition that will be the first complete, critical, and annotated English translation of all of Nietzsches work. Volume 2: Unfashionable Observations, translated by Richard T. Gray, was published in 1995. The edition is a new English translation, by various hands, of the celebrated Colli-Montinari edition, which has been acclaimed as one of the most important works of scholarship in the humanities in the last quarter century. The original Italian edition was simultaneously published in French, German, and Japanese. This volume of Human, All Too Human, the first of two parts, is the earliest of Nietzsches works in which his philosophical concerns and methodologies can be glimpsed. In this work Nietzsche began to establish the intellectual difference from his own cultural milieu and time that makes him our contemporary. Published in 1878, it marks both a stylistic and an intellectual shift away from Nietzsches own youthful affiliation with Romantic excesses of German thought and culture typified by Wagnerian opera.', 'en', 2000, 396, 'http://books.google.com/books/content?id=etq_ab9t9qoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5016', 'accepted', 'Friedrich Wilhelm Nietzsche; Gary Handwerk', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 14 FROM public.book WHERE isbn13 = '9780804741712' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c0b4425d-e6d4-5477-8f57-d5813cda37e3', '9780804833370', 'The Golden Country', 'rXrWNsPIPEAC', 'The events described in this exciting and provocative three-act play, a companion piece to Endo’s highly acclaimed novel Silence, take place in 1633, nearly a hundred years after Christianity was introduced into Japan. By this time, Japanese Christians were being cruelly persecuted by the government; every Christian searched out was made to apostatize or suffer a slow, agonizing death. The central character of ''The Golden Country'' is Father Christopher Ferreira, a Portuguese Jesuit missionary. Given shelter by a Christian farming community, everyone looks to him for help, including one of his chief persecutors. When, after cruel torture, Father Ferriera apostatizes to the disbelief of his Japanese converts, the play reaches a climax that is later capped only by the courage, nobility and love of the martyrs. Father Francis Mathy’s detailed Introduction to this tightly constructed drama, which poses basic questions about the meaning of faith, love and fate, provides valuable historical background.', 'en', 2003, 128, 'http://books.google.com/books/content?id=rXrWNsPIPEAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
