INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2962fd18-327c-54f4-bfb5-8c50e903da9f', '9780805069372', 'John Adams', 'sa_-58fpwpkC', 'Profiles John Adams as an ideal successor to Washington, citing the qualities of his character and Federalist policies that enabled him to address the challenges that took place during his presidency, and crediting him with such achievements as the creation of the Department of the Navy and the establishment of a solvent treasury. 25,000 first printing.', 'en', 2003, 224, 'http://books.google.com/books/content?id=sa_-58fpwpkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
