INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1ae661b1-5e46-5c8e-b5d8-782dfd0e4e35', '9780805076233', 'The Second World War', 'V4vPG5Zi6AsC', 'It began with the German invasion of Poland on September 1, 1939. By the time it came to an end on V-J Day--August 14, 1945--it had involved every major power and become global in its reach. In the final accounting, it would turn out to be, in both human terms and material resources, the costliest war, taking the lives of forty million people.', 'en', 2004, 928, 'http://books.google.com/books/content?id=V4vPG5Zi6AsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
