INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('12f4d4fe-073f-5e06-ae90-59252e625fcf', '9780805242164', 'Emma Lazarus', 'UqzfkGd0sMwC', 'A definitive portrait of the iconoclastic poet and activist whose words are are set on the Statue of Liberty follows the complex life and times of Emma Lazarus, from her early literary success, to her roles as a feminist, Zionist, and renowned Jewish-American writer, based on previously undiscovered personal correspondence. 20,000 first printing.', 'en', 2006, 368, 'http://books.google.com/books/content?id=UqzfkGd0sMwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
