INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d354675b-114a-5123-ab53-8c5a832758cd', '9780805242256', 'The Origins of Totalitarianism', 'W16oQgAACAAJ', 'A political analysis of totalitarian societies, originally published in 1951, traces the nineteenth-century rise of anti-Semitism in central and western Europe and considers the institutions and operations of Nazi Germany and Stalinist Russia, examining such phenomena as the transformation of classes into masses, the applications of propaganda, and the use of terror.', 'en', 1951, 674, 'http://books.google.com/books/content?id=W16oQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
