INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('99bc66d4-a660-557f-9e17-55dc0f17dda2', '9780805359091', 'Human Anatomy & Physiology', 'RZ-7jgEACAAJ', ': With each edition of her top-selling Human Anatomy & Physiology text, Elaine N. Marieb draws on her own, unique experience as a full-time A&P professor and part-time nursing student to explain concepts and processes in a meaningful and memorable way. With the Seventh Edition, Dr. Marieb has teamed up with co-author Katja Hoehn to produce the most exciting edition yet, with beautifully-enhanced muscle illustrations, updated coverage of factual material and topic boxes, new coverage of high-interest topics such as Botox, designer drugs, and cancer treatment, and a comprehensive instructor and student media package. The Human Body: An Orientation, Chemistry Comes Alive, Cells: The Living Units, Tissue: The Living Fabric, The Integumentary System, Bones and Skeletal Tissues, The Skeleton, Joints, Muscles and Muscle Tissue, The Muscular System, Fundamentals of the Nervous System and Nervous Tissue, The Central Nervous System, The Peripheral Nervous System and Reflex Activity, The Autonomic Nervous System, The Special Senses, The Endocrine System, Blood, The Cardiovascular System: The Heart, The Cardiovascular System: Blood Vessels, The Lymphatic System, The Immune System: Innate and Adaptive Body Defensives, The Respiratory System, The Digestive System, Nutrition, Metabolism, and Body Temperature Regulation, The Urinary System, Fluid, Electrolyte, and Acid-Base Balance, The Reproductive System, Pregnancy and Human Development, Heredity For all readers interested in human anatomy & physiology.', 'en', 2007, 1296, 'http://books.google.com/books/content?id=RZ-7jgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5055', 'accepted', 'Elaine Nicpon Marieb; Katja Hoehn', 'Medical', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 4 FROM public.book WHERE isbn13 = '9780805359091' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('42e3a403-93e7-5aa2-9ca9-396ba067136e', '9780805372762', 'Anatomy & Physiology Coloring Workbook', 'CWUMAAAACAAJ', '"This workbook is an excellent tool for use by itself or with any human anatomy & physiology text. Along with its review of the human body from microscopic to macroscopic levels, the workbook also includes clinically oriented activities. Practice makes perfect with a wide variety of exercises - "At the clinic" questions help you apply what you learn to real-life clinical settings; "Incredible journey" visualization exercises in each chapter summarize chapter content; the many written exercises include completion from a selection of key choices, matching terms or descriptions, labeling diagrams, true/false, and definition questions. Elimination questions require you to discover the similarities or dissimilarities among a number of structures or objects; more than 100 coloring exercises reinforce concepts through active learning." - back cover.', 'en', 2004, 368, 'http://books.google.com/books/content?id=CWUMAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
