INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('073342b7-4173-5998-9269-2e6b46d266ae', '9780805390452', 'The Feynman Lectures on Physics', 'FuhJAQAACAAJ', 'This revised edition of Feynman''s legendary lectures includes extensive corrections Feynman and his colleagues received and Caltech approved. This boxed set provides Volumes 1-3 together with Feynman''s Tips on Physics making this the complete and definitive set of The Feynman Lectures on Physics.', 'en', 2006, 1552, 'http://books.google.com/books/content?id=FuhJAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
