INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('902a92e6-5497-5c89-87eb-2957a7bf653b', '9780805427318', 'Things Pondered', 'rsvxqaqVNLQC', 'Just as Mary treasured her memories as the mother of Jesus and pondered them in her heart, this book celebrates treasured moments in the life of every woman, wife, and mother. Told from a fresh, personal perspective, these stories and poems form a warm, inspiring collection of remembrances of children, Christmas, marriage, trials, friendship, the seasons, grace, and above all, God’s love for us. Things Pondered proves Beth Moore not only to be an effective speaker and author of popular Bible studies, but also show her to be a gifted, sensitive writer and poet.', 'en', 2004, 160, 'http://books.google.com/books/content?id=rsvxqaqVNLQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
