INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6ae7c4a6-b967-55d9-b31d-7cd5e3d18e08', '9780805427776', 'Once Upon a Gulf Coast Summer', 'ChW9611Q6FcC', 'Susan Oliver says, "It takes very little for a mother and daughter to turn on each other. So much lies below the surface—hurts held for decades in clinched fists, extravagant expectations never met, and ties that bind." Once Upon a Gulf Coast Summer is about the complex relationship between Josephine Green and her grown daughter, Katy. Issues bear down from Josephine’s troubled and rigid childhood and the enigmatic mother who was preoccupied with her own secret disappointments. Jo and Katy continue to war with each other, especially after Jo is diagnosed with lung cancer. Jo struggles to communicate her faith with her daughter and receives help from her housekeeper, Adele, who is a devout lady of faith. Jo and Katy work to find their redemption, both together and individually, even as flood waters threaten their home one Gulf Coast summer.', 'en', 2004, 368, 'http://books.google.com/books/content?id=ChW9611Q6FcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
