INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fef6e0f5-388f-553d-812b-cb9615e02933', '9780805431575', 'Monkey Business', 'oIoMlTqoxscC', 'Describes the famous 1925 courtroom showdown of William Jennings Bryan and Clarence Darrow over the teaching of evolution in public schools, and points out details and discrepancies that have not come to light until recently.', 'en', 2005, 368, 'http://books.google.com/books/content?id=oIoMlTqoxscC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
