INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5efd280d-8f60-5231-a141-5301f38f2ae1', '9780805832891', 'Writing the Qualitative Dissertation', 'h5tbvgAACAAJ', 'The purpose of this book is to share, in rich detail, an understanding of how it feels and what it means to do qualitative research, and to provide support for doctoral students who choose this form of inquiry for their dissertation research.', 'en', 2002, 242, 'http://books.google.com/books/content?id=h5tbvgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
