INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6bcc79a0-a6b0-5a0d-bd49-6671de578d55', '9780806114569', 'Ovid''s Metamorphoses', '0RUhlNVR758C', 'Ovid is a poet to enjoy, declares William S. Anderson in his introduction to this textbook. And Anderson’s skillful introduction and enlightening textual commentary will indeed make it a joy to use. In these books Ovid begins to leave the conflict between men and the gods to concentrate on the relations among human beings. Subjects of the stories include Arachne and Niobe; Tereus, Procne, and Philomela; Medea and Jason; Orpheus and Eurydice; and many others, familiar and unfamiliar. For students of Latin-and teachers, too-they provide an interesting experience. In his introduction the editor discusses Ovid’s career, the reputation of the Metamorphoses during Ovid’s time and after, and the various manuscripts that exist or have been known to exist. He describes the general plan of the poem, its main theme, and the problem of its tone. Technical matters, such as style and meter, are also considered. In notes the editor summarizes the story being told before proceeding to the line-by-line textual comments.', 'en', 1972, 560, 'http://books.google.com/books/content?id=0RUhlNVR758C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5066', 'accepted', 'Ovid', 'Social Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 3 FROM public.book WHERE isbn13 = '9780806114569' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('48d5a701-b765-5279-88be-0eea37d3df53', '9780806115603', 'Tibullus', 'IpQRKCKEsz0C', 'The work of the Latin elegiac poet Tibullus (c. 55-19 b.c.) is characterized by an artful, witty "simplicity," and it relies on repetition, ambiguity, irony, and paradox for its effect. His poetry appealed to his countrymen in his own time, as it still does to students today, and this textbook is designed to explain and enhance that appeal. The commentary presented here is limited to the sixteen poems which comprise the first two books of the corpus Tibullianum, that is, to poems authentically by Tibullus. The notes focus on the needs of students approaching Latin elegy for the first time, but they will also prove useful to the more experienced student of Latin or to scholars in other languages. The editor has tried to balance matters of fact with occasional fresh interpretations. One introduction records what is known of the poet''s life and discusses the rise of Latin elegy. The meter of the poems is explained, and Tibullus'' style is examined.', 'en', 1979, 222, 'http://books.google.com/books/content?id=IpQRKCKEsz0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
