INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('954a671e-eadd-5c95-b4e2-ebb4861ce0d4', '9780806132792', 'So Far from God', 'srvXgPuHIvEC', 'The Mexican-American War of the 1840s, precipitated by border disputes and the U.S. annexation of Texas, ended with the military occupation of Mexico City by General Winfield Scott. In the subsequent treaty, the United States gained territory that would become California, Nevada, New Mexico, Arizona, Utah, and parts of Wyoming and Colorado. In this highly readable account, John S.D. Eisenhower provides a comprehensive survey of this frequently overlooked war.', 'en', 2000, 464, 'http://books.google.com/books/content?id=srvXgPuHIvEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
