INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ea7846b9-82f0-562e-a540-f68213f1f721', '9780806133638', 'Selections from Homer''s Iliad', 'nY-5r76h7SwC', 'First published in 1903, Selections from Homer''s Iliad has become a classic Greek textbook. Allen Rogers Benner presents selections from twelve books of the Iliad in both Greek and English and short summaries that help students understand the Iliad as a work of literature and art.', 'en', 2001, 522, 'http://books.google.com/books/content?id=nY-5r76h7SwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
