INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2c965b0c-196e-5b24-9f46-902fcb941434', '9780806523705', 'Vicars of Christ', '4tbYF51StSQC', 'Tracing the history of the papacy from ancient times to the present day, this illuminating study features detailed profiles of each pope, describing the events of their reign, their role in relation to Catholic doctrine, their accomplishments and failures, and other aspects of each man who ruled the Vatican.', 'en', 2003, 492, 'http://books.google.com/books/content?id=4tbYF51StSQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
