INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ca3d2fd2-7800-5f9b-bd64-99cc77b08378', '9780806523798', 'The Minority Report', 'R7rALwfN6pYC', 'A collection of eighteen science fiction short stories features "The Minority Report," in which Commissioner John Anderton''s clever use of "precogs," people who can identify criminals before they can do any harm, turns against him when they identify him as the next criminal.', 'en', 2002, 380, 'http://books.google.com/books/content?id=R7rALwfN6pYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
