INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4bd88249-1e00-5026-925c-9500ecadbe21', '9780806524276', 'The Complete Films of Alfred Hitchcock', 'iWYk2j78ELwC', 'A tribute to the undisputed master of terror and suspense and the visionary who revolutionised the art of filmmaking, this book covers everything from his 1922 silent film The Pleasure Garden to his final 1976 film, Family Plot, including such masterpieces as Vertigo, Psycho, Rear Window and The Birds, and the years of his popular television show, Alfred Hitchcock Presents. Complete with 450 b/w stills from his many films and a text that examines the background of each production, this is the ultimate portrait of the movie genius in all his cinematic glory.', 'en', 2002, 256, 'http://books.google.com/books/content?id=iWYk2j78ELwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
