INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4491423b-d38a-5a4a-a91e-db03e3bf0d38', '9780807014264', 'Man''s Search for Meaning', 'dnJmBMv2jUUC', 'A new gift edition of a modern classic, with supplemental photographs, speeches, letters, and essays Psychiatrist Viktor Frankl''s memoir of life in Nazi death camps has riveted generations of readers. Based on Frankl''s own experience and the stories of his patients, the book argues that we cannot avoid suffering but we can choose how to cope with it, find meaning in it, and move forward. Man''s Search for Meaning has become one of the most influential books of our times, selling over twelve million copies worldwide. With a foreword by Harold S. Kushner, Frankl''s classic is presented here in an elegant new edition with endpapers, supplementary photographs, and several of Frankl''s previously unpublished letters, speeches, and essays.', 'en', 1992, 165, 'http://books.google.com/books/content?id=dnJmBMv2jUUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
