INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a35227aa-9bb6-526a-8687-ac6886d893eb', '9780807842591', 'The Scotch-Irish', 'r9TX6swm_5kC', 'Dispelling much of what he terms the ''mythology'' of the Scotch-Irish, James Leyburn provides an absorbing account of their heritage. He discusses their life in Scotland, when the essentials of their character and culture were shaped; their removal to Northern Ireland and the action of their residence in that region upon their outlook on life; and their successive migrations to America, where they settled especially in the back-country of Pennsylvania, Virginia, the Carolinas, and Georgia, and then after the Revolutionary War were in the van of pioneers to the west.', 'en', 1989, 377, 'http://books.google.com/books/content?id=r9TX6swm_5kC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
