INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f0ecbbbe-8199-5379-84fb-39ab8ddebad4', '9780809015450', 'The Transcendence of the Ego', '17150PDhLu4C', 'The Transcendence of the Ego may be regarded as a turning-point in the philosophical development of Jean-Paul Sartre. Prior to the writing of this essay, published in France in 1937, Sartre had been intimately acquainted with the phenomenological movement which originated in Germany with Edmund Husserl. It is a fundamental tenet of Husserl, the notion of a transcendent ego, which is here attacked by Sartre. This disagreement with Husserl has great importance for Sartre and facilitated the transition from phenomenology to the doctrine of Being and Nothingness.', 'en', 1957, 120, 'http://books.google.com/books/content?id=17150PDhLu4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
