INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('39dca440-cbe4-55c6-9d6e-14d40b88e75e', '9780809230419', 'Wooden: A Lifetime of Observations and Reflections On and Off the Court', '4XXymAEACAAJ', 'NATIONAL BESTSELLER "I am just a common man who is true to his beliefs."--John Wooden Evoking days gone by when coaches were respected as much for their off-court performances as for their success on the court, Wooden presents the timeless wisdom of legendary basketball coach John Wooden. In honest and telling passages about virtually every aspect of life, Coach shares his personal philosophy on family, achievement, success, and excellence. Raised on a small farm in south-central Indiana, he offers lessons and wisdom learned throughout his career at UCLA, and life as a dedicated husband, father, and teacher. These lessons, along with personal letters from Bill Walton, Denny Crum, Kareem Abdul-Jabbar, and Bob Costas, among others, have made Wooden: A Lifetime of Observations and Reflections on and off the Court an inspirational classic.', 'en', 1997, 201, 'http://books.google.com/books/content?id=4XXymAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
