INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0df773b6-940b-5331-8973-ab213ec8afe3', '9780810111134', 'Billy Budd, Sailor and Other Uncompleted Writings', 'MZMGwwEACAAJ', '"The new reading text of Billy Budd, Sailor in this volume is based on a corrected version (also printed here) of the "Genetic Text" that was prepared by Harrison Hayford and originally published in 1962 by the University of Chicago Press in a volume edited by Hayford and Merton M. Sealts, Jr. This new reading text employs different editorial principles from those followed in the 1962 volume. Portions of the introduction and notes to that volume have also been used here in an extensively revised form."', 'en', 2017, 1016, 'http://books.google.com/books/content?id=MZMGwwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5107', 'accepted', 'Herman Melville', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 10 FROM public.book WHERE isbn13 = '9780810111134' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f7b59463-3e0b-553a-a626-0be357558a05', '9780810117303', 'The Chain of Chance', 'oY9hKQ-YLl0C', 'Written in the style of a detective novel, The Chain of Chance is classic Lem: a combination of action, hard science, and philosophical investigation. An ex-astronaut is hired to look into the death of a wealthy businessman, one of several men to meet a gruesome end after visiting Naples. The authorities suspect a pattern, but neither the police nor a sophisticated computer enlisted for the investigation can crack the case. On a trail leading from Naples to Rome to Paris, the ex-astronaut barely escapes numerous threats on his life. Having set himself up as a potential victim, he realizes that he may now be the target of a deadly conspiracy - and that the conspiracy is not the work of a criminal mind but a manifestation of the laws of nature. The population has numerically exceeded its critical mass; certain patterns have begun to emerge from the chaotic workings of society. As the ex-astronaut unravels the puzzle, he begins to see that some of those patterns can be fatal.', 'en', 2000, 179, 'http://books.google.com/books/content?id=oY9hKQ-YLl0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5108', 'accepted', 'Stanisław Lem', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 0 FROM public.book WHERE isbn13 = '9780810117303' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('058d57f4-39b2-575a-ac2c-a526abd0f57d', '9780810117310', 'His Master''s Voice', 'I5gYWtcfMioC', '"Twenty-five hundred scientists have been herded into an isolated site in the Nevada desert. A neutrino message of extraterrestrial origin has been received, and, under the surveillance of the Pentagon, the scientists labor on His Master''s Voice, the secret program set up to decipher the transmission."--BOOK JACKET. "Among them is Peter Hogarth, an eminent mathematician whose posthumous diary makes up the novel. Hogarth joins His Master''s Voice after all efforts to decode the message prove futile and, after an early success, gives up on the project to pursue clandestine research into the so-called TX effect. Hogarth comes to realize that the TX effect could lead to the construction of the ultimate weapon - a fission bomb - and that such knowledge must not be allowed into the hands of the military."--BOOK JACKET. "Originally published in 1968, His Master''s Voice takes to task the military takeover of scientific research, Cold War - era politics, and humanity''s perpetual capacity for (self-)destruction. It remains a mordant satire on scientific microworlds and the monstrous political and military systems bankrolling them."--BOOK JACKET.', 'en', 1999, 199, 'http://books.google.com/books/content?id=I5gYWtcfMioC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5109', 'accepted', 'Stanisław Lem', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 17 FROM public.book WHERE isbn13 = '9780810117310' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('275cea32-e733-55f1-80ee-4b6a0ce52853', '9780810117334', 'A Perfect Vacuum', 'jMvpf5K1qD0C', 'In a perfect vacuum, Stanislaw Lem presents a collection of book reviews of nonexistent works of literature - works that, in many cases, could not possibly be written. Embracing postmodernism''s "games for games'' sake" ethos, Lem joins the contest with hilarious and grotesque results. Most of the "reviews" target the postmodern infatuation with antinarratives by lampooning their self-indulgence and exploiting their mannerisms. Lem exposes the limits of postmodern fiction, showing how its studious self-consciousness frequently conceals intellectual paucity. Beginning with a review of his own book, Lem moves on to tackle (or create pastiches of) the French new novel, James Joyce, pornography, authorless writing, and Dostoevsky, while at the same time ranging across scientific topics, from cosmology to the pervasiveness of computers.', 'en', 1999, 229, 'http://books.google.com/books/content?id=jMvpf5K1qD0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
