INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('11e11714-cbff-588f-b6d6-45ce42cb0575', '9780810117495', 'The Phenomenon of Life', 'F2seCz7wmfQC', 'One of the most prominent thinkers of his generation, Hans Jonas wrote on topics as diverse as the philosophy of biology, ethics and cosmology. This work sets forth a systematic philosophy of biological facts, laid out in support of his claim that mind is prefigured throughout organic existence.', 'en', 2001, 304, 'http://books.google.com/books/content?id=F2seCz7wmfQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
