INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f40bfb2c-2473-5a05-a1e6-9c903039f821', '9780810935204', 'Lewis Carroll''s Jabberwocky', 'tyMFAAAACAAJ', 'Lewis Carroll''s classic and inventive verse comes to life in a series of ingenious dioramas, colorful three-dimensional renderings of the rhyme by the best-selling author-illustrator of Animalia and The Eleventh Hour.', 'en', 1996, 14, 'http://books.google.com/books/content?id=tyMFAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
