INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d98dfe1d-03c8-5dc8-b752-fbd83a8148f1', '9780810959361', 'Creating the Worlds of Star Wars', 'H-oaAAAACAAJ', 'A visual effects supervisor for the Star Wars movies Attack of the Clones and Revenge of the Sith presents a comprehensive selection of one thousand behind-the-scenes images, including panoramic shots of sets and models, as well as concept art, props, film stills, and memorabilia from all six films, as well as a CD-ROM containing nearly three hundred navigable panoramas of the sets.', 'en', 2005, 744, 'http://books.google.com/books/content?id=H-oaAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
