INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2d76cf48-63e1-5dc0-90c9-1708cc5a763d', '9780810992597', 'Pink Box', 'GujtAAAACAAJ', 'In Pink Box, photographer Joan Sinclair gives us a privileged view into Japan''s most elaborate sex clubs. Unrivalled in their creativity and the sheer number of choices, these clubs offer their clientele every fantasy imaginable. Subway groping, video and comic book character encounters and visits to the nurse are just the beginning of the immense list of possibilities that are played out in colourful playrooms for adults where no detail is overlooked. Sinclair''s photographs are colourful, fun and absolutely absorbing, and they capture the unique sensibility of Japanese culture that has given rise to Hello Kitty (who, by the way, is available for $800 an hour).', 'en', 2006, 192, 'http://books.google.com/books/content?id=GujtAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
