INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3fa49c3e-ed94-5c19-93b6-edd3edc6a802', '9780811200073', 'Paris Spleen, 1869', '15craP5h4O4C', 'Baudelaire composed the series of prose poems known as Paris Spleen between 1855 and his death in 1867. He attached great importance to his work in this then unusual form, asking, "Which one of us, in his moments of ambition, has not dreamed of the miracle of a poetic prose, musical, without rhythm and without rhyme, supple enough and rugged enough to adapt itself to the lyrical impulses of the soul, the undulations of reverie, the jibes of conscience?"', 'en', 1970, 118, 'http://books.google.com/books/content?id=15craP5h4O4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
