INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5124', 'accepted', 'Henry Miller', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 14 FROM public.book WHERE isbn13 = '9780811201063' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3486d4ed-a326-58db-940f-1a0f915d3cfd', '9780811201087', 'Mémoires, Plaidoiries Et Documents', 'N-xUV8_ic5QC', 'Some writers attempt to conceal the literary influences which have shaped their thinking - but not Henry Miller. In The Books in My Life he shares the thrills of discovery that many kinds of books have brought to a keenly curious and questioning mind. Some of Miller''s favorite writers are the giants whom most of us revere - authors such as Dostoeyvsky, Boccaccio, Walt Whitman, James Joyce, Thomas Mann, Lao-Tse. To them he brings fresh and penetrating insights. But many are lesser-known figures: Krishnamurti, the prophet-sage; the French contemporaries Blaise Cendrars and Jean Giono; Richard Jeffries, who wrote The Story of My Heart ; the Welshman John Cowper Powys; and scores of others. The Books in My Life contains some fine autobiographical chapters, too. Miller describes his boyhood in Brooklyn, when he devoured the historical stories of G. A. Henty and the romances of Rider Haggard. He tells of the men and women whom he regards as living books": Lou Jacobs, W. E. B. DuBois, Elizabeth Gurley Flynn, and others. He offers his reminiscences of the New York Theatre in the early 1900''s - including plays such as Alias Jimmy Valentine and Nellie, the Beautiful Cloak Model . And finally, in Miller''s best vein of humor, he provides a satiric chapter on bathroom reading. In an appendix, Miller lists the hundred books that have influenced him most. "', 'en', 1969, 327, 'http://books.google.com/books/content?id=N-xUV8_ic5QC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5125', 'accepted', 'Henry Miller', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 3 FROM public.book WHERE isbn13 = '9780811201087' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('32733784-1883-5846-ad39-116a0a430d4a', '9780811201124', 'Henry Miller on Writing', 'tNB6wAEACAAJ', 'Some of the most rewarding pages in Henry Miller''s books concern his self-education as a writer. He tells, as few great writers ever have, how he set his goals, how he discovered the excitement of using words, how the books he read influenced him, and how he learned to draw on his own experience.', 'en', 1964, 217, 'http://books.google.com/books/content?id=tNB6wAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
