INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4df254dc-fc9b-5110-abb8-f77d89cb734c', '9780811201353', 'Safe Conduct', 'GW_mawWxyvwC', 'Safe Conduct is Boris Pasternak''s first autobiography written when he was forty and after the great success of Dr. Zhivago. Experimental in its category, its isolated sharp impressions and juxtapositions seem to deny a normal chronology.', 'en', 1958, 256, 'http://books.google.com/books/content?id=GW_mawWxyvwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
