INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4d392a32-d6e0-5218-b267-f541ccd3eb5d', '9780811204835', 'The Flight of Icarus', 'ds-3QmK565sC', 'The Flight of Icarus is Raymond Queneau''s only novel written in the form of a play: seventy-four short scenes, complete with stage directions. Consciously parodying Pirandello and Robbe-Grillet, it begins with a novelist''s discovery that his principal character, Icarus by name, has vanished. This in turn, sets off a rash of other such disappearances.', 'en', 1973, 191, 'http://books.google.com/books/content?id=ds-3QmK565sC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
