INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f1610e64-b9fa-5d8d-b809-3f037a733c85', '9780811205467', 'Turtle Island', 'xilff6LAWAcC', 'These Pulitzer Prize-winning poems and essays by the author of No Nature range from the lucid, lyrical, and mystical to the political. All, however, share a common vision: a rediscovery of North America and the ways by which we might become true natives of the land for the first time.', 'en', 1974, 112, 'http://books.google.com/books/content?id=xilff6LAWAcC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
