INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b42f3710-69ee-5b87-a9af-6eaef2417c8f', '9780811211734', 'The Collected Poems of Octavio Paz, 1957-1987', 'Q9FIe1MmGVoC', 'This landmarked bilingual edition gathers all the poetry the 1990 Nobel Laureate has published in book form since 1957, the year his long poem "Sunstone"--her translated anew--made its first appearance. Included are the complete texts of "Days and Occasions", "Solo for Two Voices", "A Drift of Shadows", "East Slope", "Toward the Beginning", and more; plus Paz''s most recent collection, A Tree Within.', 'en', 1991, 669, 'http://books.google.com/books/content?id=Q9FIe1MmGVoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
