INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d1680649-0792-5e6b-8f9f-ce78527bc043', '9780811213462', 'The Samurai', 'Bb1fXVWzkt8C', 'One of the late Shusaku Endo''s finest works, The Samurai tells of the journey of some of the first Japanese to set foot on European soil and the resulting clash of cultures and politics.', 'en', 1997, 272, 'http://books.google.com/books/content?id=Bb1fXVWzkt8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
