INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('21e0b97d-dc81-5b77-bfe3-e6e244e0bf93', '9780811213653', 'The Daring Young Man on the Flying Trapeze, and Other Stories', 'OjZLNgfDKHwC', 'A timeless selection of brilliant short stories that won William Saroyan a position among the foremost, most widely popular writers of America when it first appeared in 1934.With the greatest of ease William Saroyan flew across the literary skies in 1934 with the publication of The Daring Young Man on the Flying Trapeze and Other Stories. One of the first American writers to describe the immigrant experience in the U.S., Saroyan created characters who were Armenians, Jews, Chinese, Poles, Africans, and the Irish. The title story touchingly portrays the thoughts of a very young writer, dying of starvation. All of the tales were written during the great depression and reflect, through pathos and humor, the mood of the nation in one of its greatest times of want.', 'en', 1997, 272, 'http://books.google.com/books/content?id=OjZLNgfDKHwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
