INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4f6a3516-00b9-51b2-aa8a-781d45896190', '9780811213769', 'In Search of Duende', 'Tdw_76l_DnMC', 'Federico Garcia Lorca was born in Spain in 1898 and executed in 1936, during the Spanish Civil War. The notion of "duende"--a demonic earth spirit--became a fixation of Lorca''s poetics over the course of his career. This book gathers Lorca''s writings about the duende, and a full bilingual sampling of his poetry also is included, with special attention to poems arising from traditional Spanish verse forms.', 'en', 1998, 99, 'http://books.google.com/books/content?id=Tdw_76l_DnMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
