INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9ea039a3-4ada-5404-855d-bf5357c77cce', '9780811215923', 'Borges and the Eternal Orangutans', 'G5cn9BrD6d0C', 'Vogelstein is a loner who has always lived among books. Suddenly, fate grabs hold of his insignificant life and carries him off to Buenos Aires, to a conference on Edgar Allan Poe, the inventor of the modern detective story. There Vogelstein meets his idol, Jorge Luis Borges, and for reasons that a mere passion for literature cannot explain, he finds himself at the center of a murder investigation that involves arcane demons, the mysteries of the Kaballah, the possible destruction of the world, and the Elizabethan magus John Dee''s theory of the Eternal Orangutan, which, given all the time in the world, would end up writing all the known books in the cosmos. Verissimo''s small masterpiece is at once a literary tour de force and a brilliant mystery novel.', 'en', 2005, 135, 'http://books.google.com/books/content?id=G5cn9BrD6d0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
