INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1c28b755-5fbd-50a1-8c49-3a37bd2da9ff', '9780812505771', 'The Last Book of Swords: Shieldbreaker''s Story', '_fvzjK3FsXkC', 'Created by gods, the forged Twelve Swords can kill the gods themselves if they fall into human hands, and when Vilkata the Dark King returns from exile determined to get the swords, only an untested boy, with Shieldbreaker in hand, stands in the man''s way. Reissue.', 'en', 1995, 255, 'http://books.google.com/books/content?id=_fvzjK3FsXkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
