INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('613ed97d-f604-5712-8ba2-15a9d9f530bc', '9780812511185', 'The Sixth Book of Lost Swords', 'iamepaEpC4oC', 'When the long-lost Mindsword--which gives mindless devotion to the one who wields it--falls into the hands of Prince Murat, Kristen, the beautiful wife of Prince Mark, falls under its spell, and it is up to Mark and his companions to save his wife and his kingdom', 'en', 1991, 250, 'http://books.google.com/books/content?id=iamepaEpC4oC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
