INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('aae23da3-6eee-5607-a1fa-912121c3143e', '9780812524260', 'Red Prophet', 's5q4wQEACAAJ', 'Alvin Maker is drawn into the political manueverings of his visionary brother and a French colonel exiled to Fort Detroit named Napoleon Bonapart, in this tale set in the frontier of a magical alternate America', 'en', 1988, 311, 'http://books.google.com/books/content?id=s5q4wQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
