INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d91669e2-3670-595d-a2bd-e8d42db2b732', '9780812532616', 'The Call of Earth', 'oisnmQEACAAJ', 'As Harmony''s Oversoul grows weaker, a great warrior has arisen to challenge its bans. His name is Moozh, and he has won control of an army using forbidden technology. Now he is aiming his soldiers at the city of Basilica, that strong fortress above the Plain. Basilica remains in turmoil. Wetchik and his sons are not strong enough to stop a army. Can Rasa and her allies defeat him through intrigue, or will Moozh take the city and all who are in it?', 'en', 1994, 352, 'http://books.google.com/books/content?id=oisnmQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
