INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b2e97308-31a8-544e-8d64-a1e26c711a28', '9780812532630', 'The Ships of Earth', '5Vo-mgEACAAJ', 'The City of Basilica has fallen. Now Wetchik, Nafai, and all their family must brave the desert wastes, and cross the wide continents to where Harmony''s hidden spaceport lies silent, abandoned, waiting for the command to make the great interstellar ships ready for flight again. But of these sixteen people, only a few have chosen their exile. The others, Rasa''s spiteful daughters and their husbands; Wetchik''s oldest son, Elemak, have been forced against their will. Their anger and hatreds will make the difficult journey harder.', 'en', 1995, 351, 'http://books.google.com/books/content?id=5Vo-mgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
