INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e79c3594-5c08-574a-8f9d-225362d700b5', '9780812574739', 'The Dastard', 'exL0mAEACAAJ', 'Many malevolent menaces have imperiled the magical land of Xanth in its long and storied history. But none has been as despicably dangerous as the Dastard-a craven miscreant who sold his soul to a detestable demon for the power to erase events. Now the entire future of Xanth is at the mercy of his every whim. Only a young dragon-girl named Becka has the power to stop his devious deeds! Becka is a crossbreed-the daughter of Draco Dragon and a lovely human woman who met, by chance, at a Love Spring. Now fourteen, Becka is beginning to wonder where in Xanth she belongs-on the ground with her mother''s people, or flying the skies with her father''s kind. So she journeys to the Good Magician Humfrey to discover her True Purpose in life. Much to her astonishment and surprise, the Magician tells her that that a great Destiny awaits her-one that will affect the future of all of Xanth.', 'en', 2001, 384, 'http://books.google.com/books/content?id=exL0mAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
