INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f0ce1aa1-bfbf-55fe-949a-31675e2bef7d', '9780813191553', 'The Cave', 'D1Z5Ks95UlIC', 'In his sixth novel, The Cave (1959), Robert Penn Warren tells the story of a young man trapped in a cave in fictional Johntown, Tennessee. His predicament becomes the center of national attention as television cameras, promoters, and newscasters converge on the small town to exploit the rescue attempts and the thousands of spectators gathered at the mouth of the cave.', 'en', 1959, 424, 'http://books.google.com/books/content?id=D1Z5Ks95UlIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
