INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('66f7330c-5f18-5a60-a11b-1831fd9cc107', '9780813520186', 'Daughters of Decadence', 'VOWhXVuuzWQC', 'At the turn of the century, short stories by -- and often about -- "New Women" flooded the pages English and American magazines such as the Atlantic Monthly, Harpers, and the Yellow Book. This daring new fiction, often innovative in form and courageous in its candid representations of female sexuality, marital discontent, and feminist protest, shocked Victorian critics, who denounced the authors as "literary degenerates" or "erotomaniacs." This collection brings together twenty of the most original and important stories from this period. The writers included in this highly readable volume are Kate Chopin, Victoria Cross, George Egerton, Julia Constance Fletcher, Charlotte Perkins Gilman, Sarah Grand, Vernon Lee, Ada Leverson, Charlotte Mew, Olive Schreiner, Edith Wharton, Constance Fenimore Woolson, and Mabel E. Wotton. As Elaine Showalter shows in her introduction, the short fiction of the Fin-de-Siecle is the missing link between the Golden Age of Victorian women writers and the new era of feminist modernism. Elaine Showalter is a professor of English at Princeton University. She is the author of A Literature of Their Own, The Female Malady, and other books, and editor of Alternative Alcott, a volume in the American Women Writers Series', 'en', 1993, 352, 'http://books.google.com/books/content?id=VOWhXVuuzWQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5246', 'accepted', 'Elaine Showalter', 'Social Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 2 FROM public.book WHERE isbn13 = '9780813520186' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3413c542-458d-50fe-a336-087a509fb7ac', '9780813530659', 'Girls who Wore Black', '4AfkN_6r3WoC', 'What do we know about the women who played an important role in creating the literature of the Beat Generation? Until recently, very little. Studies of the movement have effaced or excluded women writers, such as Elise Cowen, Joyce Johnson, Joanne Kyger, Hettie Jones, and Diane Di Prima, each one a significant figure of the postwar Beat communities. Equally free-thinking and innovative as the founding generation of men, women writers, fluent in Beat, hippie, and women''s movement idioms, partook of and bridged two important countercultures of the American mid-century. Persistently foregrounding female experiences in the cold war 1950s and in the counterculture 1960s and in every decade up to the millennium, women writing Beat have brought nonconformity, skepticism, and gender dissent to postmodern culture and literary production in the United States and beyond.', 'en', 2002, 318, 'http://books.google.com/books/content?id=4AfkN_6r3WoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5247', 'accepted', 'Ronna Johnson; Nancy McCampbell Grace', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 5 FROM public.book WHERE isbn13 = '9780813530659' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d0a7c404-e596-528f-b3eb-5bcf2c4d8d4b', '9780814317327', 'Latin Via Ovid', 'fORWW12AoTAC', 'Using an introduction to mythology by the master storyteller Ovid himself, the authors have prepared a unique teaching tool designed to achieve proficiency at Latin in one year at the college level, two years at the high school or intermediate level. The volume provides students with imaginative, connected reading, beginning with introductory prose versions of Ovid''s simple myth tales and progressing to the rich poetry of Ovidian Latin (with appropriate teaching aids) within forty lessons. The grammatical approach is traditional, but the central emphasis is on reading. In each chapter the reading appears first, followed by the vocabulary, the grammar, exercises, and etymology relating to the vocabulary. The exercises begin with a group of questions in Latin (based on the reading), to be answered in Latin. Each tale is preceded by a brief discussion in English of the story and its mythological significance. The myths retold by Ovid and the attractive format are conceived to impel the student into acquiring the skill to read the author in the original language. For additional complimentary materials on this topic, please see Latin Via Ovid Audio materials (available via downloadable flash drive and cassette tapes) by Norma Goldman and Jacob E. Nyenhuis and the accompanying text Practice, Practice: A Latin Via Ovid Workbook by Norma Goldman and Michael Rossi.', 'en', 1982, 524, 'http://books.google.com/books/content?id=fORWW12AoTAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5248', 'accepted', 'Norma Goldman; Jacob E. Nyenhuis', 'Foreign Language Study', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 10 FROM public.book WHERE isbn13 = '9780814317327' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d9c54ef4-442f-5fea-a392-a619616d13bc', '9780814326114', 'Practice! Practice!', '-34_qtcxorsC', 'Exhibiting the same clarity as Latin via Ovid, this student workbook parallels the text''s forty lessons and is the ideal supplement to classroom recitation and exercises. Drills in grammar and vocabulary, combined with innovative directions for practice, facilitate the student''s acquisition of Latin. Teachers: When ordering Latin via Ovid and the audio material, be sure to order the free Teacher''s Manual (not sent to students) that contains all of the translations of the Latin stories, plus each chapter''s Exercise V, which requires the translation from English into Latin. Games and songs are included. Please request this guide by calling us at 313-577-6126. The VCR video of the puppet show "Ulysses" for Chapter XXXV can be ordered directly from Norma W. Goldman at College of Lifelong Learning; 5700 Cass Avenue, Wayne State University Detroit, MI 48202 phone number: 313-577-6582 fax number: 313-577-8585 Price: $25.00 (includes shipping & handling).', 'en', 1995, 152, 'http://books.google.com/books/content?id=-34_qtcxorsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
