INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2ef51d8d-9452-5d85-ba88-e922fc9e7ac6', '9780814727010', 'The Gramsci Reader', 'nl_bJyeYdpwC', 'with a new introduction by ERIC J. HOBSBAWM "Very usefully pulls the key passages from Gramsci''s writings into one volume, which allows English-language readers an overall view of his work. Particularly valuable are the connections it draws across his work and the insights which the introduction and glossary provide into the origin and development of some key Gramscian concepts." --Stuart Hall, Professor of Sociology, Open University The most complete one-volume collection of writings by one of the most fascinating thinkers in the history of Marxism, The Antonio Gramsci Reader fills the need for a broad and general introduction to this major figure. Antonio Gramsci was one of the most important theorists of class, culture, and the state since Karl Marx. In the U.S., where his writings were long unavailable, his stature has lately so increased that every serious student of Marxism, political theory, or modern Italian history must now read him. Imprisoned by the Fascists for much of his adult life, Gramsci wrote brilliantly on a broad range of subjects: from folklore to philosophy, popular culture to political strategy. Still the most comprehensive collection of Gramsci''s writings available in English, it now features a new introduction by leading Marxist historian Eric Hobsbawm, in addition to its biographical introduction, informative introductions to each section, and glossary of key terms.', 'en', 2000, 447, 'http://books.google.com/books/content?id=nl_bJyeYdpwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5250', 'accepted', 'Antonio Gramsci', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 12 FROM public.book WHERE isbn13 = '9780814727010' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7ef84ab5-d891-521e-9676-08f5734b77ad', '9780815319665', 'Cold Counsel', 'FBYAYvQv774C', 'Cold Counsel is the only collection devoted to the place of women in Old Norse literature and culture. It draws upon the disciplines of history, sociology, feminism, ethnography and psychoanalysis in order to raise fresh questions about such new subjects as gender, class, sexuality, family structure and ideology in medieval Iceland.', 'en', 2002, 320, 'http://books.google.com/books/content?id=FBYAYvQv774C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
