INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a4ede672-41cd-51bc-8131-10fc5a038c0c', '9780815411215', 'George Eliot', '6s8CR_lzCfUC', 'This intensely engaging biography examines the extraordinary life of George Eliot from her childhood, through her scandalous liaison and social exile, to her hard-won status as one of Victorian England''s literary elite.', 'en', 2001, 416, 'http://books.google.com/books/content?id=6s8CR_lzCfUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
