INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b721dac3-71d9-5331-8547-de2777acd2f4', '9780815411833', 'Marilyn Monroe', 'r2W9SGUyRmgC', 'A biography of the screen legend employs thirty-five thousand formerly sealed documents--letters, diaries, and other papers--to examine virtually every aspect of Monroe''s life and death.', 'en', 1993, 752, 'http://books.google.com/books/content?id=r2W9SGUyRmgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
