INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b13e25c5-f0a5-5705-a28b-43ad709e8e54', '9780815412182', 'Temptations', 'KMJo37QXc7gC', 'The Temptations were the most commercially successful and critically lauded male vocal group of the 60s and early 70s. This is the frank, revealing story of the legendary supergroup, told by its founder. 57 photos.', 'en', 2002, 304, 'http://books.google.com/books/content?id=KMJo37QXc7gC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
