INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2c9823d5-3a89-58f9-a74c-7822a16116c6', '9780816041619', 'Edgar Allan Poe, A to Z', 'VUdqb7HPTPAC', 'More than 3,400 entries chart the life and work of Poe. Entries arearranged alphabetically and cover works (including essays and reviews as well as poems and tales) and characters. Entries for works contain publishing and dramatization history, a list of characters, and a synopsis of the plot. There is also coverage of people, places, and publications that played a role in Poe''s life or helped shape his literary development. Coverage extends into the twentieth century with entries (Corman, Roger; Price, Vincent) related to film and musical adaptations. Terms in boldface type serve as cross-references. Following the entries are four appendixes: a chronology of Poe''s life, a chronology of his works, a list of Poe research collections, and a bibliography.', 'en', 2001, 320, 'http://books.google.com/books/content?id=VUdqb7HPTPAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
