INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2a72f60b-3e84-5280-ba28-c2e83a56400f', '9780816638635', 'Christopher and His Kind', 'EV86HAAACAAJ', '"Originally published in 1976, Christopher and His Kind covers the most memorable ten years in the writer''s life - from 1929, when Isherwood left England to spend a week in Berlin and decided to stay there indefinitely, to 1939, when he arrived in America." "What most impressed the first readers of this memoir was the candor with which he describes his life in gay Berlin of the 1930s and his struggles to save his companion, Heinz, from the Nazis. An engrossing and dramatic story and a fascinating glimpse into a little-known world, Christopher and His Kind remains one of Isherwood''s greatest achievements."--BOOK JACKET.Title Summary field provided by Blackwell North America, Inc. All Rights Reserved', 'en', 2001, 352, 'http://books.google.com/books/content?id=EV86HAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
