INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e24cc021-e8a9-5e39-99a1-f82dcb359771', '9780816639823', 'The Condor and the Cows', 'jxdoPgAACAAJ', 'One of the few classic works of South American travel, now available in paperback with a new foreword by Jeffrey Meyers and additional photographs by Isherwood''s lover, Bill Caskey. Isherwood frankly depicts the squalor and discomforts of his journey--as he wrote he was very skeptical about the book but later came to regard it as one of his best.', 'en', 2003, 248, 'http://books.google.com/books/content?id=jxdoPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
