INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('876f0223-d9f0-5a49-9fa7-20bc9411a6a5', '9780816643004', 'Filth', 'b4RrtwAACAAJ', 'Focusing on ''filth'' in literary & cultural materials from London, Paris & their colonial outposts in the 19th & early 20th centuries, the essays in this volume range over topics from the building of sewers to the fictional representation of labouring women as polluting.', 'en', 2005, 360, 'http://books.google.com/books/content?id=b4RrtwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
