INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e5394017-2026-5dea-a2d9-2a267a407c75', '9780820320977', 'Robert Penn Warren''s All the King''s Men', 'au5XzVpSb_cC', 'Robert Penn Warren''s 1946 Pulitzer Prize-winning novel All the King''s Men is one of the undisputed classics of American literature. Fifty years after the novel''s publication, Warren''s characters still stand as powerful representations of the moral dilemmas faced by individuals in positions of power. All the King''s Men had its genesis in Warren''s stage play Proud Flesh, unpublished in his lifetime. He also wrote a subsequent unpublished play titled Willie Stark: His Rise and Fall and a later dramatic version of the novel that shared the title All the King''s Men. This volume is the first to collect all three dramatic texts and to publish Proud Flesh and Willie Stark. Proud Flesh is particularly fascinating for what it reveals about the development of All the King''s Men and Warren''s changing perceptions of its characters and themes. The other plays, as post-novel writings, provide a forum for Warren to clarify his intentions in the novel. The editors'' introduction to this collection reviews the composition history of the works and their relationship to the novel and to each other. The new perspectives on Warren''s writing presented in Robert Penn Warren''s "All the King''s Men": Three Stage Versions provide a glimpse into a creative mind struggling with a compelling story and offer readers another way of looking at this American classic. This book is an essential reference in Warren studies that will give students of All the King''s Men another context from which to consider Warren''s novel.', 'en', 2000, 264, 'http://books.google.com/books/content?id=au5XzVpSb_cC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5264', 'accepted', 'Robert Penn Warren', 'Performing Arts', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 6 FROM public.book WHERE isbn13 = '9780820320977' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2dcb5ea7-691c-5ded-849e-4a57dcdfb80f', '9780821220801', 'Odes to Common Things', 'FrunQgAACAAJ', 'A bilingual collection of 25 newly translated odes by the century''s greatest Spanish-language poet, each accompanied by a pair of exquisite pencil drawings. From bread and soap to a bed and a box of tea, the "odes to common things" collected here conjure up the essence of their subjects clearly and wondrously. 50 b&w illustrations.', 'en', 1994, 152, 'http://books.google.com/books/content?id=FrunQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5265', 'accepted', 'Pablo Neruda', 'Poetry', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 3 FROM public.book WHERE isbn13 = '9780821220801' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('70585c2e-a373-5146-9ba3-f5fc317df9d7', '9780821221846', 'The Camera', 'aZYCuwEACAAJ', 'Ansel Adams (1902-1984) produced some of the 20th century''s most iconic photographic images and helped nurture the art of photography through his creative innovations and peerless technical mastery. The Camera--the first volume in Adams'' celebrated series of books on photographic techniques--has taught generations of photographers how to harness the camera''s artistic potential. This time-honored handbook distills the knowledge gained through a lifetime in photography and remains as vital today as when it was first published. Along with visualization, image management, Adams'' famous Zone System, and other keys to photographic artistry, The Camera covers 35mm, medium-format, and large-format view cameras, while offering detailed advice on camera components such as lenses, shutters, and light meters. Beautifully illustrated with photographs as well as instructive line drawings, this classic manual belongs on every serious photographer''s bookshelf. "Adams is a clear-thinking writer whose concepts cannot but help the serious photographer." - New York Times "A master-class kind of guide from an undisputed master." - Publishers Weekly Over 1 million copies sold.', 'en', 1995, 195, 'http://books.google.com/books/content?id=aZYCuwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5266', 'accepted', 'Ansel Adams', 'Photography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 4 FROM public.book WHERE isbn13 = '9780821221846' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fb4491fd-d0ad-5452-bedb-2d8dd3cdbe38', '9780821221877', 'The Print', 'BGFWGPFQg7oC', 'Ansel Adams (1902-1984) produced some of the 20th century''s most iconic photographic images and helped nurture the art of photography through his creative innovations and peerless technical mastery. The Print--the third volume in Adams'' celebrated series of books on photographic techniques--has taught generations of photographers how to explore the artistic possibilities of printmaking. Examples of Adams'' own work clarify the principles discussed. This classic handbook distills the knowledge gained through a lifetime in photography and remains as vital today as when it was first published. The Print takes you step-by-step--from designing and furnishing a darkroom to mounting and displaying your photographs, from making your first print to mastering advanced techniques, such as developer modifications, toning and bleaching, and burning and dodging. Filled with indispensable darkroom techniques and tips, this amply illustrated guide shows how printmaking--the culmination of photography''s creative process--can be used expressively to enhance an image. "Adams is a clear-thinking writer whose concepts cannot but help the serious photographer." - New York Times "A master-class kind of guide from an undisputed master." - Publishers Weekly Over 1 million copies sold.', 'en', 1995, 203, 'http://books.google.com/books/content?id=BGFWGPFQg7oC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
