INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e0222600-a512-5245-9727-77ba886b9b44', '9780821758267', 'A Devilish Dilemma', 'MgYDAAAACAAJ', 'When Miss Minerva Potts called off her engagement to the self-absorbed Lord Whithall, she vowed not to marry at all. Then, she met Chadwick Brumfield, Earl of Rossland. Known as the Devil''s Delight, the charming earl had a reputation so scandalous, Minerva was certain she would never lose her heart to him--but she was wrong.', 'en', 1998, 288, 'http://books.google.com/books/content?id=MgYDAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
