INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c685d6d5-e3c0-5828-8f76-e0e824e9250c', '9780821760536', 'Prince of Magic', 'tmgreaMc6r0C', 'Exiled to Yorkshire after shaming her minister father by dancing barefoot in the moonlight, Elizabeth Penshurst meets mysterious Gabriel Durham, and as they become drawn to each other, a secretive Druid cult plans to use her as a sacrifice, and Gabriel will stop at nothing to save her. Original.', 'en', 1998, 348, 'http://books.google.com/books/content?id=tmgreaMc6r0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
