INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4fcd7a0e-7bbc-5070-822f-69b6b45287fb', '9780821778067', 'This Christmas', 'l4aNflr03_IC', 'A trio of holiday romances features Jane Green''s Vacation, in which surburban housewife Sarah, dissatisfied with her marriage, gets a break from her husband when his job sends him to Chicago indefinitely and learns that the grass isn''t always greener on the other side. Original.', 'en', 2005, 480, 'http://books.google.com/books/content?id=l4aNflr03_IC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
