INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d6173536-21d6-5ca4-9e38-08d048192226', '9780822000235', 'CliffsNotes on Shakespeare''s King Henry IV', '1r0_xgEACAAJ', 'This popular play entertains and inspires in alternating comic scenes and serious ones and is the birthplace of one of the theater''s greatest characters, Sir John Falstaff. Young Prince Hal rebels against his father the king until he must go to the king''s aid to stamp out the rebellion of nobles.', 'en', 1971, 80, 'http://books.google.com/books/content?id=1r0_xgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5277', 'accepted', 'James K. Lowers', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 15 FROM public.book WHERE isbn13 = '9780822000235' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1d78a1fe-39f1-5247-97ba-055877e67bd1', '9780822000945', 'CliffsNotes on Shakeapeare''s Twelfth Night', '1jUsP-7JfqwC', 'The original CliffsNotes study guides offer expert commentary on major themes, plots, characters, literary devices, and historical background. The latest generation of titles in this series also feature glossaries and visual elements that complement the classic, familiar format. In CliffsNotes on Twelfth Night, you follow several separate groups of characters whose stories are flawlessly woven together to produce one of Shakespeare''s lightest, most popular, and most musical comedies — full of intricate plots and subplots and witty banter that only Shakespeare could write. Summaries and commentaries take you through Shakespeare''s masterpiece, and character analyses of such memorable characters as Viola, Olivia, and Duke Orsino clue you in on their motivations. You also get these additional features: A section on the life and background of William Shakespeare A review section that tests your knowledge A selected bibliography Classic literature or modern modern-day treasure — you''ll understand it all with expert information and insight from CliffsNotes study guides.', 'en', 1960, 64, 'http://books.google.com/books/content?id=1jUsP-7JfqwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
