INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2a5217d4-1703-5518-8e32-766d920a594f', '9780822002109', 'Cliffs notes on Faulkner''s As I lay dying', 'l0VRu6X7hkYC', 'Presents a guide to understanding William Faulkner''s "As I Lay Dying," examining the life of the author, discussing the structure and narrative technique employed in the novel, featuring analysis and commentary on individual sections, and including character notes, and other study aids.', 'en', 1969, 72, 'http://books.google.com/books/content?id=l0VRu6X7hkYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
