INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('817a4e3b-e9d3-5c40-af9e-6dd9125ddd23', '9780822002420', 'CliffsNotes on Wright''s Black Boy', '7TRLcrdf9ZIC', 'The original CliffsNotes study guides offer expert commentary on major themes, plots, characters, literary devices, and historical background. CliffsNotes on Black Boy chronicles the alienation of the author – not only from white society, but from his own people. Richard Wright’s novel is a cry of anguish in the face of the human condition and the tragedy that comes when an individual struggles to overcome it. With this study guide, you’ll experience the events and the unique tone of the novel. Background about the life of the author will help shed light on the novel’s themes. Other features that help you study include Character analyses of major players Chapter summaries and commentaries Critical essays Character genealogy chart Helpful maps Review questions and suggested essay topics Classic literature or modern modern-day treasure — you''ll understand it all with expert information and insight from CliffsNotes study guides.', 'en', 1971, 56, 'http://books.google.com/books/content?id=7TRLcrdf9ZIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5282', 'accepted', 'Carl Senna', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 1 FROM public.book WHERE isbn13 = '9780822002420' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c6bb3828-4dad-50f3-aeb2-ddae91d74973', '9780822002833', 'CliffsNotes on Voltaire''s Candide', 'wCTjzAEACAAJ', 'The original CliffsNotes study guides offer expert commentary on major themes, plots, characters, literary devices, and historical background. CliffsNotes on Candide explores the best known philosophic tale from Voltaire. The tale is a vehicle for his profoundest views on politics, religion, and philosophy. At the same time, it is an adventure tale about a young hero who travels far and wide and experiences great dangers. With this study guide, you’ll see why Voltaire is considered among the greatest satirists in literature. Along with detailed explanations of the plot, your understanding will increase with insight into the life and times of the author. Other features that help you study include Background on Voltaire’s contemporaries and influences Character analyses of major players A character map that graphically illustrates the relationships among the characters Critical essays Review questions Classic literature or modern modern-day treasure — you''ll understand it all with expert information and insight from CliffsNotes study guides.', 'en', 1965, 80, 'http://books.google.com/books/content?id=wCTjzAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
