INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('68f271a9-bb08-51b1-a910-d39f311e33b2', '9780822002963', 'CliffsNotes on Heller''s Catch-22', 'sP4E_2e2Ij4C', 'The original CliffsNotes study guides offer expert commentary on major themes, plots, characters, literary devices, and historical background. CliffsNotes on Catch-22 takes you into this unforgettable novel that is full of satire, exaggeration, grotesque and comic caricatures, and telling allusions. Heller’s main characters are two Jewish boys from Brooklyn at the end of World War II – one from an orthodox family, one from a secular background. The growing friendship between the boys reflects the tensions within American society. With this study guide, you’ll be able to follow the unique structure of the novel and supplement your reading with insights into the life and background of author Joseph Heller. Other features that help you study include Life and background of the author Character analyses of major players A character map that graphically illustrates the relationships among the characters Critical essays Review questions Classic literature or modern modern-day treasure — you''ll understand it all with expert information and insight from CliffsNotes study guides.', 'en', 1976, 48, 'http://books.google.com/books/content?id=sP4E_2e2Ij4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
