INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('daa937b8-c07b-5227-b2e5-4d9fb37a4488', '9780822005339', 'CliffsNotes on Williams'' The Glass Menagerie & Streetcar Named Desire', 'eahFfhm1jjIC', 'The original CliffsNotes study guides offer a look into key elements and ideas within classic works of literature. CliffsNotes on Glass Menagerie & Streetcar Named Desire explores two popular plays, both of which take place in the South and borrow heavily from author Tennessee Williams’s own life experiences. Following stories marked by struggle among loved ones, this study guide provides summaries and critical commentaries for each scene within the works. Other features that help you figure out this important work include Personal background on the playwright Introduction to and synopsis of the plays In-depth analyses of the cast of characters Review section that features interactive quizzes and suggested essay topics Selected bibliographies for both plays Classic literature or modern-day treasure — you''ll understand it all with expert information and insight from CliffsNotes study guides.', 'en', 1965, 88, 'http://books.google.com/books/content?id=eahFfhm1jjIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
