INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d6d6a68f-a03a-5e32-93f2-238e3b4c9133', '9780822012375', 'CliffsNotes on Hemingway''s The Sun Also Rises', '6TBr9lMlh-QC', 'This is the book that chronicled the lives and times of "the Lost Generation," American expatriates that filled Europe between the world wars. Hemingway''s expatriates are there for two different reasons: one is there solely for entertainment, the other, to heal from the horrors of war and create something worth living for. Wounded Jake Barnes narrates a great, difficult love story.', 'en', 1968, 80, 'http://books.google.com/books/content?id=6TBr9lMlh-QC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
