INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d594a354-775f-5826-bac4-9164d8076ad8', '9780822013549', 'Beckett''s Waiting for Godot, Endgame, & Other Plays', 'TKcBAAAACAAJ', 'A true innovation for the stage, Waiting for Godot is one of the greatest successes of the Theater of the Absurd. Although the subject and play is bleak in appearance, a semblance of nobility emerges as the two characters maintain hope. This volume also covers Endgame, All That Fall, Act Without Words I, and Krapp''s Last Tape.', 'en', 1980, 72, 'http://books.google.com/books/content?id=TKcBAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
