INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4511fc10-722c-51b9-8edb-27f8d8b1afe7', '9780822215028', 'Having Our Say', 'nV6C8u9xmdcC', 'THE STORY: HAVING OUR SAY opens as 103-year-old Sadie Delany and 101-year-old Bessie Delany welcome us into their Mount Vernon, New York, home. As they prepare a celebratory dinner in remembrance of their father''s birthday, they take us on a remark', 'en', 1996, 262, 'http://books.google.com/books/content?id=nV6C8u9xmdcC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
