INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9b849f34-3be3-5153-bd76-6421a06812e5', '9780822309321', 'Gunslinger', 'QjA1iPqs8G8C', 'Dorn’s high-spirited, crazy-quilt, complex anti-epic is a masterful critique of late twentieth-century capitalism and is one of the great comic poems of American literature. Dorn is one of the few political poets in America; this fantasy about a demigod cowboy, a saloon madam, and a talking horse named Claude Levi-Strauss, who travel the Southwest in search of Howard Hughes, as become a minor classic.', 'en', 1989, 224, 'http://books.google.com/books/content?id=QjA1iPqs8G8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
