INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('12168e5d-b338-5bf7-9df2-d51e38ca3f9a', '9780825429828', 'Reinventing Jesus', 'D7ecngEACAAJ', 'Reinventing Jesus cuts through the rhetoric of extreme doubt to reveal the profound credibility of historic Christianity. Meticulously researched yet eminently readable, this book invites a wide audience to take a firsthand look at the primary evidence for Christianity''s origins.', 'en', 2006, 347, 'http://books.google.com/books/content?id=D7ecngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
