INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('372f41d2-c6e5-5cef-a88a-d22389293db1', '9780826323576', 'Quito 1599', 'otABiA17lNUC', 'Quito has always been one of the most enigmatic of colonial Spanish American cities. The history of its enormous hinterland, only a fraction of which forms the modern Republic of Ecuador, is even less known. This engaging book takes the watershed year 1599 as a starting point for a provocative reinterpretation of the history of Quito, city and colony. The result is a lively narrative that is also an original inquiry into the driving forces behind sixteenth-century Spanish colonialism. In six overlapping topical narratives Lane brings to life a place wracked by civil disturbances, shipwrecks, indigenous uprisings, pirate attacks, maroon intransigence, urban decadence, failed missionary endeavors, sharp economic reorientations, and wily and unpredictable subaltern adaptation and resistance. Drawing from a wealth of recent research on the colonial north Andes and on more than seven years of study in the archives of Ecuador, Colombia, and Spain, Lane presents rich discoveries of interest to economic historians, including a previously unknown gold boom; however, his primary interest is people. He explores the ways both individuals and groups--shipwreck victims, slaves, laborers, merchants, traders--faced obstacles and seized (or missed) opportunities, showing readers not only the basic facts and major themes of colonial life but also the influence and outcome of individual hopes and fears among people from a multitude of races and ethnicities.', 'en', 2002, 312, 'http://books.google.com/books/content?id=otABiA17lNUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5320', 'accepted', 'Kris E. Lane', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 20 FROM public.book WHERE isbn13 = '9780826323576' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8bebfc13-4a12-5c08-ad40-8d788888ecf3', '9780826406736', 'Art of Being', 'pvQHAAAACAAJ', 'Fromm examines the true paths--as opposed to false directions--that will lead us to self-knowledge and enlightenment and offers another way to self-awareness and well-being, one based on psychoanalysis and self-awareness through meditation.', 'en', 1994, 144, 'http://books.google.com/books/content?id=pvQHAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
