INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('64e64727-9d90-51aa-9fe5-4ea663860880', '9780826407078', 'Nathan the Wise, Minna von Barnhelm, and Other Plays and Writings: Gotthold Ephraim Lessing', 'AsmnSZaZfsYC', 'Lessing was a playwright, scholar, poet, archeologist, philosopher, and critic. His genius is evident in the works collected in this volume, which includes the comedy Minna von Barnhelm, the tragedy Emilia, Galotti, Nathan the Wise, The Jews (and related correspondence), Ernst and Falk: Conversations for the Freemasons, and selections from philosophical and theological writings', 'en', 1991, 370, 'http://books.google.com/books/content?id=AsmnSZaZfsYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5322', 'accepted', 'Peter Demetz', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 11 FROM public.book WHERE isbn13 = '9780826407078' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('62d186a4-d066-5811-a0df-58770db8d760', '9780826411327', 'The Art of Listening', 'Gi1-PwAACAAJ', 'Although Erich Fromm intended to publish his work as a practicing psychotherapist, these plans were never realized in his lifetime. This volume fulfills his wish. Not intended as a textbook about psychoanalytic therapy, these reflections provide welcome new information about Fromm the therapist and the way he dealt with the psychological suffering of his patients. As Fromm envisioned, each chapter is structured to capture the informality and intimacy of his psychoanalytic work so that readers get a new and different sense of Fromm''s humanism, honesty and insight. These talks and seminars, given by Fromm between 1964 and his death in 1980, deal with the issues between analyst and analysand that go to the heart of the psychoanalytic process. For Fromm, the analyst is his or her own next patient, as the patient becomes his or her analyst.', 'en', 1998, 204, 'http://books.google.com/books/content?id=Gi1-PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5323', 'accepted', 'Erich Fromm', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 3 FROM public.book WHERE isbn13 = '9780826411327' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9c7b9630-f4bd-500a-8233-25c0033750e7', '9780826414533', 'Guerilla Film Makers Movie Blueprint', 'YshOYecAD0oC', 'Central to The Guerilla Film Makers Movie Blueprint are flow charts: crystal-clear diagrams detailing every single thing, no matter how small, that needs to be done to make your film. This visual approach to the filmmaking process ensures that new (and established!) filmmakers get an instant overview of each and every discipline. Backing up the diagrams are copious notes - humorous in tone, yet broad and deep in content. Wherever possible, the text is broken apart into box outs, hot tips and sub-diagrams. This book is entertaining, irreverent, and never less than painfully practical. The Guerilla Film Makers Movie Blueprint will have its own dedicated website where readers can download the tools, forms, software, and artwork detailed in the book. Jones''s latest endeavor is packed with over a decade''s worth of experience, know-how, and insider tips. A must-read for every budding filmmaker.', 'en', 2003, 608, 'http://books.google.com/books/content?id=YshOYecAD0oC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
