INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7f6dfc44-2aed-5031-b6ef-e4bdfe7694e7', '9780826414748', 'Don DeLillo''s White Noise', 'jTSzxgEACAAJ', 'A critical examination of "White Noise" by Don Delillo, this title forms part of a series that aims to provide accessible and informative introductions to some of the most popular, most acclaimed and most influential novels of recent years. A team of contemporary fiction scholars from both sides of the Atlantic has been assembled to give a thorough and readable analysis of each of the novels in question.The books in the series all follow the same five-part structure: a short biography of the novelist; a full-length study of the novel, drawing out the most important themes and ideas; a summary of how the novel was received when it was first published; a summary of the novel''s standing today, including any film or television adaptations; and a helpful list of discussion questions, suggestions for further reading, and useful websites.', 'en', 2003, 96, 'http://books.google.com/books/content?id=jTSzxgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5325', 'accepted', 'Leonard Orr', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 19 FROM public.book WHERE isbn13 = '9780826414748' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ea83ad98-fcfc-5d8e-8f1c-ab63b4161c1a', '9780826414755', 'Gabriel Garcia Marquez''s Love in the Time of Cholera', 'ayjUAwAAQBAJ', 'A brilliant idea--short, perceptive books which tell you what you need to know about some of the most vibrant and challenging writing around today--a bit like having a reading group in your pocket. IAN RANKIN', 'en', 2003, 188, 'http://books.google.com/books/content?id=ayjUAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
