INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b74c9991-89ee-5911-be58-df3bdae9f0ad', '9780826414779', 'David Foster Wallace''s Infinite Jest', 'xJ6U1VK3SRcC', 'This is part of a new series of guides to contemporary novels. The aim of the series is to give readers accessible and informative introductions to some of the most popular, most acclaimed and most influential novels of recent years - from ‘The Remains of the Day'' to ‘White Teeth''. A team of contemporary fiction scholars from both sides of the Atlantic has been assembled to provide a thorough and readable analysis of each of the novels in question.', 'en', 2003, 96, 'http://books.google.com/books/content?id=xJ6U1VK3SRcC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5327', 'accepted', 'Stephen Burn', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 7 FROM public.book WHERE isbn13 = '9780826414779' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a06887de-45f8-53da-88c7-b665e822ce42', '9780826415745', 'Anita Diamant''s The Red Tent', 'pSGfoDNjvzEC', 'Continuum Contemporaries give readers accessible and informative introductions to some of the most popular, most acclaimed, and most influential novels of recent years. A team of contemporary fiction scholars from both sides of the Atlantic has been assembled to provide a through and readable analysis of each of the novels in question. The books in the series all follow the same structure: a biography of the novelist, including other works, influences, and, in some cases, an interview; a full-length study of the novel, drawing out the most important themes and ideas; a summary of how the novel was received upon publication; a summary of how the novel has performed since publication, including film or television adaptations, literary prizes, and so forth; a wide range of suggestions for further reading, including web sites and discussion forums; and a list of questions for reading groups to discuss.', 'en', 2004, 88, 'http://books.google.com/books/content?id=pSGfoDNjvzEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5328', 'accepted', 'Ann Finding', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 6 FROM public.book WHERE isbn13 = '9780826415745' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8c8e8c7f-64e7-5971-b07c-f78aff4ae7e9', '9780826418975', 'Beyond the Chains of Illusion', 'fS7UAwAAQBAJ', 'First published in 1962 and long unavailable, BEYOND THE CHAINS OF ILLUSION is, only at first glance, a book about Marx and Freud--those two intellectual giants of the 20th century. Fromm here shows himself an outstanding interpreter of Marx. In all, Fromm''s re-creation of the Freudian and Marxist way of thinking is, essentially, a look at the individual and society. BEYOND THE CHAINS OF ILLUSION will introduce many of today''s readers to unknown aspects of Marx and Freud, as it also serves as a unique introduction to the life and mind of Erich Fromm as well. A new foreword by Fromm Literary Executor Rainer Funk puts this book into historic context and high relief.', 'en', 2006, 152, 'http://books.google.com/books/content?id=fS7UAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
