INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('357a18bb-7dfa-5b7f-bc86-b1aa9e79cdb5', '9780826514707', 'Cervantes in Algiers', 'h97ivaPeOx8C', 'Returning to Spain after fighting in the Battle of Lepanto and other Mediterranean campaigns against the Turks, the soldier Miguel de Cervantes was captured by Barbary pirates and taken captive to Algiers. The five years he spent in the Algerian bagnios or prison-houses (1575-1580) made an indelible impression on his works. From the first plays and narratives written after his release to his posthumous novel, the story of Cervantes''s traumatic experience continuously speaks through his writings. Cervantes in Algiers offers a comprehensive view of his life as a slave and, particularly, of the lingering effects this traumatic experience had on his literary production. No work has documented in such vivid and illuminating detail the socio-political world of sixteenth-century Algiers, Cervantes''s life in the prison-house, his four escape attempts, and the conditions of his final ransom. Garces''s portrait of a sophisticated multi-ethnic culture in Algiers, moreover, is likely to open up new discussions about early modern encounters between Christians and Muslims. By bringing together evidence from many different sources, historical and literary, Garces reconstructs the relations between Christians, Muslims, and renegades in a number of Cervantes''s writings. The idea that survivors of captivity need to repeat their story in order to survive (an insight invoked from Coleridge to Primo Levi to Dori Laub) explains not only Cervantes''s storytelling but also the book that theorizes it so compellingly. As a former captive herself (a hostage of Colombian guerrillas), the author reads and listens to Cervantes with another ear.', 'en', 2005, 368, 'http://books.google.com/books/content?id=h97ivaPeOx8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5334', 'accepted', 'María Antonia Garcés', 'Health & Fitness', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 16 FROM public.book WHERE isbn13 = '9780826514707' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cf85d52c-9248-5fea-aee4-792ee3e075e9', '9780829421224', 'Helena', 'H927wAEACAAJ', '“In Helena, the play of words and the fireworks, the exquisite descriptions of landscapes, and even the finished portraits of the heroine, her husband, and her son, are always subordinate to the author''s broad vision of the mixed anguish and hope with which the world of Constantine''s time was filled.” —New York Herald Tribune “[Helena] may be read on two levels of appreciation: As bright entertainment, or as deceptively profound commentary. On both levels it''s a superlatively well done book.” —Chicago Tribune Evelyn Waugh, author of the internationally acclaimed bestseller Brideshead Revisited and one of the greatest writers of the twentieth century, considered Helena to be perhaps his finest novel. Based on the life of St. Helena, mother of the Emperor Constantine and finder of the true cross, this spiritual adventure brings to life the political intrigues of ancient Rome and the early years of Christianity.', 'en', 2005, 264, 'http://books.google.com/books/content?id=H927wAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
