INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9fb3bd12-d6ab-595e-ba28-54dad57904a2', '9780830819713', 'Too Busy Not to Pray', 'xYJ1bl1c3gwC', 'Most of us have trouble finding time to pray. And then the crises hit! Time for prayer seems impossible to find. The ideas in this practical book can help us to learn to slow down to be with God as well. Also included is a helpful guide for personal and group prayer.', 'en', 1998, 191, 'http://books.google.com/books/content?id=xYJ1bl1c3gwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
