INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d23b80e7-1901-5d1d-9f9d-c6bb83078aa0', '9780830825707', 'The Nature of the Atonement', 'ctikDwAAQBAJ', 'James K. Beilby and Paul R. Eddy edit a collection of essays on four views of atonement: the healing view, the Christus victor view, the kaleidoscopic view and the penal substitutionary view. This is a book that will help Christians understand the issues, grasp the differences and proceed toward a clearer articulation of their understanding of the atonement.', 'en', 2006, 208, 'http://books.google.com/books/content?id=ctikDwAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
