INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7fe70e31-44ef-5203-9fa8-d6fbcd9c40c5', '9780830826193', 'The Cross from a Distance', 'cfIjrV1A6xwC', 'In this New Studies in Biblical Theology exploration of Mark''s Gospel, Peter G. Bolt looks at why the cross is so prominent in the narrative, asks what contribution Mark''s teaching can make to our understanding of the atonement and shows how this teaching can inform, correct and enrich our own preaching of the gospel in the contemporary world.', 'en', 2004, 213, 'http://books.google.com/books/content?id=cfIjrV1A6xwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
