INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1d3337db-f448-5906-bdc7-be4818f436e6', '9780830832941', 'Courageous Faith Through the Year', 'T-lM23fB5m8C', 'Focusing on the key aspects of Christian life--prayer, character, and wisdom--this one-year devotional shows believers how to know God more deeply and discover how he works in them.', 'en', 2004, 327, 'http://books.google.com/books/content?id=T-lM23fB5m8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
