INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f729324c-a2cb-549c-beb5-93989487d1e8', '9780835608473', 'Mandala', 'ez4BScCzwBgC', 'Mandala will guide readers of all levels through simple mandala exercises and easy-to-follow drawing techniques, incorporating meditation and guided visualization with lavish illustrations. By exploring the tradition of the sacred circle, readers will learn how to create their own unique and powerful works of sacred art and use the mandala symbol as a self-transformative tool that manifests and enhances their own spiritual consciousness. The new edition also includes a CD with meditations set to music and guided exercises.', 'en', 2006, 176, 'http://books.google.com/books/content?id=ez4BScCzwBgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
