INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c83ad687-e770-579c-8ee7-09ab10bacf19', '9780836217353', 'The Days Are Just Packed', '_7jI4ZPuztUC', 'The irrepressible Calvin, aided by his mischievous tiger sidekick, Hobbes, sets out to save the world with his alter egos, Spaceman Spiff and Stupendous Man, while coping with Miss Wormwood, Santa, Susie, and the monsters under his bed. Simultaneous.', 'en', 1993, 176, 'http://books.google.com/books/content?id=_7jI4ZPuztUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5344', 'accepted', 'Bill Watterson', 'Humor', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 20 FROM public.book WHERE isbn13 = '9780836217353' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1d58bca4-585d-5929-b8a8-5ab9714d23d5', '9780836217698', 'Homicidal Psycho Jungle Cat', '-aOTQgAACAAJ', 'Reprising the wide-open landscape format of, The Days Are Just Packed, Homicidal Psycho Jungle Cat chronicles another segment of the multifarious adventures of this wild child and his faithful, but skeptical, friend. If the best cartoons compel readers to identify themselves within the funny frames, then all who enjoy Calvin and Hobbes are creative, imaginative, and ... bad, bad, bad! Calvin, the irascible little boy with the stuffed tiger who comes to life are a pair bound for trouble. Boring school lessons become occasions for death-defying alien air battles, speeding snow sled descents elicit philosophical discussions on the meaning of life, and Hobbe''s natural inclination to pounce on his little friend wreaks havoc on Calvin''s sense of security. Calvin''s the kid we all wish we''d been. Sassy, imaginative, far more verbal than his parents can manage, Calvin is the quintessential bad boy -- and the boy we love to see. He terrorizes little Susie, offers "Candid Opinions" from a neighborhood stand, and questions his parents'' authority. "What assurance do I have that your parenting isn''t screwing me up?" he demands. Calvin and Hobbes manages to say what needs to be said about childhood and life: "Eww, mud," says Calvin. "Look at this gooshy, dirty, slimy, thick, wet mud ... Bleecch ... Talk about a kid magnet!"', 'en', 1994, 176, 'http://books.google.com/books/content?id=-aOTQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
