INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('23ff1a4a-7503-5c1a-b05e-79a1e1263b2f', '9780838526958', 'Foundations of Clinical Research', 'zzhrAAAAMAAJ', 'This book serves as a comprehensive reference for a variety of research situations. This edition reflects the popular approaches to analysis and design, and addresses the focus of health-care related research through the 1990s and into the 21st century. Expanded or added topics include outcomes research and the disablement model, validity and diagnostic screening, meta-analysis, scales used in survey and outcomes research, logistic regression, measures of reliability, and data management to prepare for computer analysis. For those in the health professions, including physical therapy, occupational therapy, speech therapy, nursing, and exercise physiology.', 'en', 2000, 742, 'http://books.google.com/books/content?id=zzhrAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
