INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bc0aeb72-1c80-574c-97c3-32b8577bd51a', '9780851513348', 'Discovering God''s Will', 'm0MPAAAACAAJ', 'Discovering God''s Will draws out fundamental principles by which God guides us. It shows that the guidance God gives comes primarily through knowing, loving and obeying him.', 'en', 1981, 126, 'http://books.google.com/books/content?id=m0MPAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
