INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('15173e78-1be7-50ad-94ea-22ab7b92677a', '9780859653725', 'Dissecting Marilyn Manson', '7_FrAAAACAAJ', 'Marilyn Manson in more than a mere rock star - he is a cultural phenomenon. He has created a phantasmal world of freaks irresistible to a generation of disaffected youth, while generating unprecedented controversy and protests from conservative and Christian organisations. In Dissecting Marilyn Manson author Gavin Baddeley performs a cultural autopsy, examining the seminal influences and psychotic sources that have created this fascinating Frankenstein''s monster. With its heavily visual approach, the text and pictures form a pathological scrapbook that explore the Manson mythos in an irreverent but deeply authoritative manner. Book jacket.', 'en', 2005, 192, 'http://books.google.com/books/content?id=7_FrAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
