INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a6fd8af9-0d2a-5351-ac83-d8944537823d', '9780861661411', 'From Hell', 'Op3iQAAACAAJ', 'Following the huge success of From Hell, Knockabout presents a stunning volume comprising a new story by Alan Moore, Snakes and Ladders, based on a performance given on Red Lion Square in Holborn. The other story, originally a performance piece by Alan Moore and Tim Perkins, was adapted as a comic by Eddie Campbell. It is a shamanism of childhood, a journey from the present to the past, back into the womb and beyond. The last part of this volume is an extensive interview of Alan Moore he gave Eddie Campbell for his self-published magazine, Egomania.', 'en', 2006, 576, 'http://books.google.com/books/content?id=Op3iQAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
