INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b5247545-5edd-506f-b066-3f265fc07e39', '9780865471863', 'Moon in a Dewdrop', 'af-BZb7n9P8C', 'Eihei Dogen (1200-1253), among the first to transmit Zen Buddhism from China to Japan and founder of the important Soto School, was not only a profoundly influential and provocative Zen philosopher but also one of the most stimulating figures in Japanese letters. Kazuaki Tanahashi, collaborating with several other Zen authorities, has produced sensitive and accurate translations of Dogen''s most important texts. Moon in a Dewdrop contains the key essays of the great master, as well as extensive background materials that will help Western readers to approach this significant work. There is also a selection of Dogen''s poetry, most of which has not appeared in English translation before. Dogen''s thought runs counter to conventional logic, employing paradoxical language and startling imagery. It illuminates such fundamental concerns as the nature of time, existence, life, death, the self, and what is beyond self.', 'en', 1985, 368, 'http://books.google.com/books/content?id=af-BZb7n9P8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
