INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f2344da4-219f-5520-ab63-33ed54a54069', '9780865476066', 'Suburban Nation', 'UZ0-0X4aiwQC', 'Three members of the Founders of the Congress for the New Urbanism give voice to a growing movement in North America to put an end to suburban sprawl and to replace the automobile-based settlement patterns of the past fifty years with a return to traditional planning principles. Reprint.', 'en', 2001, 320, 'http://books.google.com/books/content?id=UZ0-0X4aiwQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
