INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1c04d4c0-4074-5099-ab4d-d935e511c160', '9780870610639', 'Summa Theologica', 'l9R4xQEACAAJ', 'Creating a summary of all human knowledge may not be the sort of undertaking we begin in the twenty-first century, but there is still room on our bookshelves for a classic--Summa Theologica, one of the world''s oldest and greatest masterpieces. St. Thomas Aquinas has much to teach us--most especially how to confront the classic questions that are still with us after centuries of thought.', 'en', 2000, 3020, 'http://books.google.com/books/content?id=l9R4xQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
