INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d05144b0-a725-5f46-ae9f-b3d30817b2e6', '9780872201934', 'The Grand Inquisitor', 'l27NSK53qsEC', 'This new edition presents The Grand Inquisitor together with the preceding chapter, Rebellion, and the extended reply offered by Dostoevsky in the following sections, entitled The Russian Monk. By showing how Dostoevsky frames the Grand Inquisitor story in the wider context of the novel, this edition captures the subtlety and power of Dostoevsky''s critique of modernity as well as his alternative vision of human fulfillment.', 'en', 1993, 160, 'http://books.google.com/books/content?id=l27NSK53qsEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
