INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('98148e77-9157-579f-a614-d648fce8cbaa', '9780872207363', 'Republic', 'T8X5wAEACAAJ', 'Taking full extent of S.R. Slings'' new Greek text of the Republic, Reeve has given us a translation at once both accurate and limpid. Loving attention to detail and deep familiarity with Plato''s thought are evident on every page.', 'en', 2004, 358, 'http://books.google.com/books/content?id=T8X5wAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
