INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('56e68dc5-51c3-5986-808c-d5722f7330b0', '9780873387804', 'Chekhov''s Doctors', 'mSvsP3m78Q4C', 'In his brief life, Chekhov was a doctor, essayist, dramatist and a humanitarian. He saw no conflict between art and science or art and medicine. This collection of stories presents powerful portraits of doctors in their everyday lives, struggling with their own personal problems.', 'en', 2003, 228, 'http://books.google.com/books/content?id=mSvsP3m78Q4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
