INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d93ae3b0-8292-5013-98a0-3413e8051a18', '9780873512695', 'Early Candlelight', 'XH_EwAEACAAJ', '"Young Deedee DuGay knew everyone at Fort Snelling in the 1830s ... On an island in the Mississippi, near yet remote, lived Jasper Page, the leading fur trader in the territory ... And although he was far above her in social class, Deedee dared to love him. Their story is a rich and romantic re-creation of an important time in Minnesota history ... A new introduction compares the fictional Jasper Page to Henry H. Sibley, fur trader and first governor of Minnesota, upon whom the character was based"--Back cover.', 'en', 1992, 342, 'http://books.google.com/books/content?id=XH_EwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
