INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('32e29968-aca8-544a-8adc-1d55c72b812b', '9780873527361', 'Approaches to Teaching Atwood''s The Handmaid''s Tale and Other Works', 'GOVzQgAACAAJ', 'Now at seventy-three volumes, this popular MLA series (ISSN 1059-1133) addresses a broad range of literary texts. Each volume surveys teaching aids and critical material and brings together essays that apply a variety of perspectives to teaching the text. Upper-level undergraduate and graduate students, student teachers, education specialists, and teachers in all humanities disciplines will find these volumes particularly helpful.', 'en', 1996, 215, 'http://books.google.com/books/content?id=GOVzQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
