INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3ca8c068-87c2-53e2-8a68-9cc4a22079ae', '9780875168166', 'The Guide to Dan Brown''s The Solomon Key', '5mtwPQAACAAJ', 'The massive success of Dan Brown''s The Da Vinci Code has readers eagerly awaiting his next novel, The Solomon Key. Using clues left by Brown in interviews, on his website, and on the cover of The Da Vinci Code, Greg Taylor takes you on an unprecedented tour of the new book before it is even released. The Guide to Dan Brown''s The Solomon Key explores the topics likely to be included in Brown''s next novel - including the hidden history of Washington, D.C., Freemasonry, and even the Ku Klux Klan - to give you a better understanding of the concepts behind the book. With no spoilers, this is the essential primer for The Solomon Key. Book jacket.', 'en', 2005, 183, 'http://books.google.com/books/content?id=5mtwPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
