INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e0ee7501-585a-5ed4-9c59-a92a6b4c0172', '9780878937202', 'Essentials of Conservation Biology', 'spaGQgAACAAJ', 'Essentials of Conservation Biology (Fourth Edition) combines theory and basic research to explain the connections between conservation biology and environmental economics, education, ethics, law and the social sciences. It is beautifully illustrated and is written in clear, non-technical language. The book''s broad, up-to-date coverage and its extensive bibliography with over 1,000 references also make it invaluable to graduate students and researchers. This new edition now comes with a Glossary.', 'en', 2006, 585, 'http://books.google.com/books/content?id=spaGQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
