INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2038669f-73fa-52c8-b77d-ca4a31534181', '9780879074494', 'Exercitia Spiritualia', 'aehfQgAACAAJ', 'The most scholarly of the remarkable nuns of Helfta composed these meditations, rituals, prayers, instructions on how to pray, chants, hymns, and litanies in the late thirteenth century. Her mastery of poetic prose attests to the level of women''s education in the highly cultured abbey she entered as a child of five and never, so far as we know, left even once.', 'en', 1989, 165, 'http://books.google.com/books/content?id=aehfQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
