INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e5de54cf-03ce-5f79-a527-bb610e69a1bb', '9780879102784', 'Jean Arthur', 'gdDl4Y38jD4C', 'The luminous star of Mr. Smith Goes to Washington, Shane, and other classic films was, as the subtitle aptly puts it, "the actress nobody knew." Jean Arthur (1900-91) kept her personal life private, disdained the Hollywood publicity machine, and was called "difficult" because of her perfectionism and remoteness from costars on the movie set. John Oller, a lawyer, tracked down kinsfolk and friends never before interviewed to capture the elusive personality of a free spirit best embodied in her favorite role, Peter Pan. Arthur herself might have appreciated his warm, respectful portrait. "...[An] insightful, painstakingly researched analysis of Arthur''s life and career raises the curtain on the complex, conflicted person behind the screen persona...Captures the special shine of a unique star who turned out to be a genuine eccentric." -Chicago Tribune', 'en', 1999, 358, 'http://books.google.com/books/content?id=gdDl4Y38jD4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5482', 'accepted', 'John Oller', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 7 FROM public.book WHERE isbn13 = '9780879102784' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('da777bad-0bf3-56e7-b207-51e7f67e6190', '9780879232153', 'Hamlet''s Mill', 'ql7ATHGee50C', 'Ever since the Greeks coined the language we commonly use for scientific description, mythology and science have developed separately. But what came before the Greeks? What if we could prove that all myths have one common origin in a celestial cosmology? What if the gods, the places they lived, and what they did are but ciphers for celestial activity, a language for the perpetuation of complex astronomical data? Drawing on scientific data, historical and literary sources, the authors argue that our myths are the remains of a preliterate astronomy, an exacting science whose power and accuracy were suppressed and then forgotten by an emergent Greco-Roman world view. This fascinating book throws into doubt the self-congratulatory assumptions of Western science about the unfolding development and transmission of knowledge. This is a truly seminal and original thesis, a book that should be read by anyone interested in science, myth, and the interactions between the two.', 'en', 1977, 450, 'http://books.google.com/books/content?id=ql7ATHGee50C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
