INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('21e54df2-ce53-5c10-85f5-8f925f12cfe5', '9780879237516', 'Life, a User''s Manual', 'mOu_ZfwIRJkC', 'Represents an exploration of the relationship between imagination and reality as seen through the eyes of the dying Serge Valene, an inhabitant of a large Parisian apartment block.', 'en', 1987, 581, 'http://books.google.com/books/content?id=mOu_ZfwIRJkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
