INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2b33f57d-da06-58f1-948b-d15a6e8c31a9', '9780880014403', 'The Assignation', 'fokfOwAACAAJ', 'A woman''s lover seems not to recognize her on the street. A teenage girl accepts a ride from a stranger in a rust-speckled Cadillac. An old man is obsessed by the memory of his innocent childhood intrusion on a half-dressed aunt. In forty-four very short, very powerful stories, Joyce Carol Oates fashions brief, intensely compact dramas out of the unwieldy material of human experience. The stories in The Assignation are infused with a "radiant intensity," wrote James Atlas in the New York Times Book Review, and they convey the depth and scope of a novel in a few charged pages. The Assignation is an electric display of the talents that make Joyce Carol Oates one of our finest short story writers.', 'en', 1996, 208, 'http://books.google.com/books/content?id=fokfOwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
