INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0c611443-771f-52ab-89aa-c793e4a2cf26', '9780881927696', 'A Book of Blue Flowers', 'EsbHMAAACAAJ', 'Perhaps the most uncommon hue in the plant kingdom, the color blue strikes a distinctive note in any garden. In this fascinating book, Robert Geneve provides a wide selection of blue flowers that will help readers expand the range of colors in their gardening palettes.', 'en', 2006, 327, 'http://books.google.com/books/content?id=EsbHMAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
