INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3d0e0ef3-868c-5a51-91f6-d2d17e294b61', '9780887061998', 'Experimental Phenomenology', '5AYQEphi6DsC', 'Experimental Phenomenology has already been lauded for the ease with which its author explains and demonstrates the kinds of consciousness by which we come to know the structure of objects and the structure of consciousness itself. The format of the book follows the progression of a number of thought experiments which mark out the procedures and directions of phenomenological inquiry. Making use of examples of familiar optical illusions and multi-stable drawings, Professor Ihde illustrates by way of careful and disciplined step-by-step analyses, how some of the main methodological procedures and epistemological concepts of phenomenology assume concrete relevance. Such formidable fare as epoche, noetic and noematic analysis, apodicticity, adequacy, sedimentation, imaginative variation, field, and fringe are rendered into the currency of familiar examples from the everyday world.', 'en', 1986, 155, 'http://books.google.com/books/content?id=5AYQEphi6DsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
