INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('96ca009b-80bc-5436-b915-14637b06d366', '9780887511127', 'Teaching the World''s Children', 'mp4FhKqKN7MC', 'The language young children use is the language they learn. In clear, practical terms, this primer explains how early childhood educators and primary teachers can support the efforts of non-English speaking children in nursery schools, day care centres and classrooms to use -- and learn -- English as a second language. Loaded with ideas and down-to-earth advice from two highly experienced and internationally renowned ESL experts, it''s an essential guide to developing a sensitive, welcoming program for all of the world''s children.', 'en', 2004, 101, 'http://books.google.com/books/content?id=mp4FhKqKN7MC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
