INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bc2603db-baaa-5103-9457-20c1305536b9', '9780895260475', 'The Politically Incorrect Guide To American History', 'ltSIOnW6XLsC', 'Looks at American history with an irreverant and hard-hitting look at the nation''s important people and events, concluding that the American Revolution was fought by conservatives and the First Amendment accepted state-sponsored churches.', 'en', 2004, 270, 'http://books.google.com/books/content?id=ltSIOnW6XLsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
