INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('58615744-aebf-5278-927f-70a5139eb41b', '9780895260789', 'America Alone', 'thP_UKhPbP0C', 'Arguing that the anti-Americanism of Europe may force America to stand alone in the world against global terrorism and other threats, the author paints a chilling portrait of a nation surrounded by enemies and less-than-loyal allies.', 'en', 2006, 224, 'http://books.google.com/books/content?id=thP_UKhPbP0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
