INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ec00ec29-bd9a-5e76-8d2d-65ff3b2ee16a', '9780895260901', 'The Real Jimmy Carter', 'FJTmAgAAQBAJ', 'A fellow at the American Enterprise Institute attacks former President Jimmy Carter''s reputation as a "good" man in this myth-deflating biography of the Novel Prize-winning politician, diplomat, and advocate, focusing particular attention on his "disastrous" presidency.', 'en', 2004, 272, 'http://books.google.com/books/content?id=FJTmAgAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5536', 'accepted', 'Steven F. Hayward', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 1 FROM public.book WHERE isbn13 = '9780895260901' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1b3eea79-cf54-5249-b6ce-3aab4cd36851', '9780895873316', 'Topsail Island', '2fp6ngEACAAJ', 'After a week-long family vacation on Topsail Island, McAllister went home and wrote a newspaper column about the place where everyone goes 10 miles per hour under the speed limit. This column brought a deluge of responses from his readers who shared his appreciation for this barrier island off the coast of North Carolina. As if caught in a time warp, Topsail resembles the resorts of decades past. It has the small-town feel of a family beach, a place with few commercial trappings whose devotees return generation after generation. McAllister blends interviews with the people who know the island with stories of early pirates, devastating hurricanes, a 1940s dig in search of a 1630 Spanish galleon''s treasure, the U.S. government''s secret rocket program, a modern-day sea-turtle preservation project, and a black bear that came to stroll the beach. In this book, McAllister tells the many stories of Topsail with the help of those who love the island best. - Publisher.', 'en', 2006, 228, 'http://books.google.com/books/content?id=2fp6ngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
