INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('682f0cc3-4e81-573d-b79a-058191cc5511', '9780895941411', 'Sister Outsider', '8obb_SHZwyQC', 'The fourteen essays and speeches collected in this work, several of them published for the first time, span almost a decade of this Black lesbian feminnist''s work. Lorde is unflinching in her observations and is lucid and clarifying in her coverage of a range of essential topics.', 'en', 1984, 190, 'http://books.google.com/books/content?id=8obb_SHZwyQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
