INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e786700c-f69f-55ae-b320-d2539b30bb21', '9780896583214', 'Walking the Rez Road', 't7oimAEACAAJ', 'Walking the Rez Road contains forty short stories and poems featuring Luke Warmwater as a central character. Luke is a Vietnam veteran who has survived the war but is having "trouble/surviving the peace" on a reservation where everyone is broke and where the tribal government seems to work against the interests of the reservation folk. Throughout Walking the Rez Road, it is humor that holds the people and their community together. Winner, Midwest Book Achievement Award, Minnesota Book Award, Northeastern Minnesota Book Award.', 'en', 1995, 176, 'http://books.google.com/books/content?id=t7oimAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
