INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('81e2bd61-f98f-5515-a24b-9945860bb891', '9780896892026', '200 Quilt Blocks to Mix & Match', 'jnRQuQEACAAJ', 'Discover the beauty and ease of mixing and matching in this easy-to-follow guide that contains 200 simple quilt blocks that open the door to a variety of contemporary and traditional designs. 200 photos.', 'en', 2005, 128, 'http://books.google.com/books/content?id=jnRQuQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
