INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c18b0dfb-179c-5eba-aab3-c8539f78d10a', '9780896892934', 'Standard Catalog of Smith & Wesson', 'fvdouQEACAAJ', 'Smith & Wesson outfitted some of the biggest and boldest gunfighters, both actual and fictional, including Wild Bill Hickock, Buffalo Bill and Dirty Harry, whose exploits are still legendary. Today a renewed Smith & Wesson corporation is back in the front of the pack. Standard Catalog of Smith & Wesson, 3rd Edition combines full color photos with details collectors need to identify and better appreciate all Smith & Wesson firearms. For fans of Smith & Wesson firearms, this book is a must-have. This work provides easy-to-locate listings organized by model ad year of manufacture to quickly and accurately identify firearms. With more than 775 models of Smith & Wesson guns and variations, including many models not found in other firearm-pricing guides, this is the book for any Smith & Wesson gun-toting fan.', 'en', 2007, 432, 'http://books.google.com/books/content?id=fvdouQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
