INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d664df93-ed8b-582f-815b-e6a3753c9895', '9780898599596', 'The Ecological Approach to Visual Perception', 'DrhCCWmJpWUC', 'This is a book about how we see: the environment around us (its surfaces, their layout, and their colors and textures); where we are in the environment; whether or not we are moving and, if we are, where we are going; what things are good for; how to do things (to thread a needle or drive an automobile); or why things look as they do. The basic assumption is that vision depends on the eye which is connected to the brain. The author suggests that natural vision depends on the eyes in the head on a body supported by the ground, the brain being only the central organ of a complete visual system. When no constraints are put on the visual system, people look around, walk up to something interesting and move around it so as to see it from all sides, and go from one vista to another. That is natural vision -- and what this book is about.', 'en', 1986, 348, 'http://books.google.com/books/content?id=DrhCCWmJpWUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5546', 'accepted', 'James Jerome Gibson', 'Psychology', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 2 FROM public.book WHERE isbn13 = '9780898599596' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8e4a3064-bf7c-5121-9a58-b2f87935d1af', '9780898702620', 'Three Philosophies of Life', 'iQ1kGnHQNw4C', '"I''ve been a philosopher for all my adult life and the three most profound books of philosophy that I have ever read are Ecclesiastes, Job, and Song of Songs." These are the opening lines of Kreeft''s Three Philosophies of Life. He reflects that there are ultimately only three philosophies of life and each one is represented by one of these books of the Bible-life is vanity; life is suffering; life is love. In these three books Kreeft shows how we have Dante''s great epic The Divine Comedy played out, from Hell to Purgatory to Heaven. But it is an epic played out in our hearts and lives, here and now. Just as there is movement in Dante''s epic, so there is movement in these books, from Ecclesiates to Job, from Job to Song of Songs. Love is the final answer to Ecclesiastes'' quest, the alternative to vanity, and the true meaning of life. Finally, Kreeft sees in these books the epitome of theological virtues of faith, hope and love and "an essential summary of the spiritual history of the world."', 'en', 1989, 140, 'http://books.google.com/books/content?id=iQ1kGnHQNw4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5547', 'accepted', 'Peter Kreeft', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 12 FROM public.book WHERE isbn13 = '9780898702620' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6c1b7898-66ac-5378-89fe-a01f069dcb28', '9780898704525', 'Christianity for Modern Pagans', 'ueroynbTaRkC', 'Peter Kreeft believes that Baise Pascal is the first post-medieval apologist. No writer in history, claims Kreeft, is a more effective Christian apologist and evangelist to today''s uprooted, confused, secularized pagans (inside and outside the Church) than Pascal. He was a brilliant man--a great scientist who did major work in physics and mathematics, as well as an inventor--whom Kreeft thinks was three centuries ahead of his time. His apologetics found in his Pensees are ideal for the modern, sophisticated skeptic.', 'en', 1993, 341, 'http://books.google.com/books/content?id=ueroynbTaRkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5548', 'accepted', 'Peter Kreeft', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 5 FROM public.book WHERE isbn13 = '9780898704525' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d6aed7ce-942a-523b-b28d-16630eea0985', '9780898706833', 'Saint Ignatius Loyola', 'Q4p2tkQ4JBgC', 'It is generally agreed among his foes no less than among his friends that Ignatius of Loyola was a maker of history. A hundred books could be cited in proof of this statement, but the aim of this classic work is rather to show history and the grace of God forming the person of St. Ignatius. In this definitive biographical work, Fr. Brodrick combines scholarly research with a readable, enjoyable style in a book that endeavors to show the stages by which God led the wounded cavalier out of his dream-world of romantic battles in the service of fair ladies into the noontide of divine reality. "The Pilgrimage," as he liked to call the difficult period of his spiritual apprenticeship, began when he was thirty and lasted for seventeen years of endless and often very moving trials. Out of it emerged a man completely transformed in Christ, one of the great saints in the history of the Church. Includes maps and index.', 'en', 1998, 350, 'http://books.google.com/books/content?id=Q4p2tkQ4JBgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
