INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0336e7fa-f061-53a5-871b-362aae3e3a8c', '9780898868098', 'The Avalanche Handbook', '0Bpscs7Gqb8C', 'Technical yet accessible, The Avalanche Handbook, 3rd Edition, covers the formation, character, effects, and control of avalanches; rescue techniques; and research on understanding and surviving avalanches. Illustrated with nearly 200 updated illustrations, photos and examples, the revised edition offers exhaustive information on contributing weather and climate factors, snowpack analysis, the newest transceiver search techniques, and preventative and protective measures, including avalanche zoning and control. It contains new information on the unique characteristics of alpine snow, snow slab instability, terrain variables, skier triggering of avalanches, and the nature of avalanche motion. Plus brand-new chapters on the elements of backcountry avalanche forecasting and the decision-making process.', 'en', 2006, 342, 'http://books.google.com/books/content?id=0Bpscs7Gqb8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
