INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f14eb87d-3055-58f2-b6b3-f7714f251515', '9780899421698', 'The Confessions of St. Augustine', 'jRkLAAAACAAJ', 'For the first time, Wills''s translation of the entire Confessions work by Saint Augustine has been compiled into one edition. Removed by time and place but not spiritual relevance, this text continues to influence contemporary religion, language and thought.', 'en', 1997, 448, 'http://books.google.com/books/content?id=jRkLAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
