INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d863164e-b478-58ac-b6c0-e8f1be16354e', '9780919123700', 'Melville''s Moby-Dick', 'zZNTxaIVRiQC', 'The great American novel Moby-Dick is a psychological document which, like a dream, needs interpretation and elaboration of its images for its meaning to emerge fully. The subtitle of this work underscores the correspondence between Melville''s deep internal struggle and the hidden complexities within us all.', 'en', 1995, 156, 'http://books.google.com/books/content?id=zZNTxaIVRiQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
