INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a6a4bef4-c93b-5afa-a420-9010a28047d3', '9780922915613', 'The Covert War Against Rock', 'V4xyjIB0Ky4C', 'What You Don''t Know About the Deaths of Jim Morrison, Tupac Shakur, Michael Hutchence, Brian Jones, Jimi Hendrix, Phil Ochs, Bob Marley, Peter Tosh, John Lennon, and The Notorious B.I.G. Many rock musicians have been outspoken and powerful proponents for social change, making them a threat to those eager to maintain the status quo. In this comprehensive look at suspect rock star deaths, conspiracy researcher Constantine unearths the secrets that the music industry and organised crime would prefer kept under wraps.', 'en', 2000, 280, 'http://books.google.com/books/content?id=V4xyjIB0Ky4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
