INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('43753599-1a53-54c4-a05f-666b6ca1f00e', '9780922915996', 'Big Dead Place', 'kRsHlPD3bcgC', 'In the desolate continent of Antarctica, the United States Government has set up three bases operated by the Raytheon corporation. These alleged ports of high science have seen little if any technical endeavours this century; nevertheless, the charade continues and many dozens of workers are cooped up together in high-tech communes. Harassed by a tic-tac bureaucracy that makes the Soviet Union look free and easy, these bases are filled with highly neurotic individuals who use their free time playing mind games with one another.', 'en', 2005, 260, 'http://books.google.com/books/content?id=kRsHlPD3bcgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
