INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e3bab48c-2a2f-5250-a833-27e81473b2c9', '9780933121294', 'African Origins of the Major "Western Religions"', '6zDWi-srH6EC', 'African Origins of the Major "Western Religions" first published in 1970, continues to be one of Dr. Ben''s most thought-provoking works. This critical examination of the history, beliefs and myths, remains instructive and fresh. By highlighting the African influences and roots of these religions, Dr. Ben reveals an untold history that many would prefer to froget.', 'en', 1991, 363, 'http://books.google.com/books/content?id=6zDWi-srH6EC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
