INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('da41b002-e64e-5623-9f47-6bb8b1dd13a6', '9780934380232', 'The Crowd: Extradordinary Popular Delusions: Twin Classics of Crowd Pyschology', '3OXIPAAACAAJ', 'There are two classic texts that deal with crowd psychology and the irrational behavior that characterizes large groups of people acting en masse. They are The Crowd, and Extraordinary Popular Delusions and the Madness Crowds. Both books provide lucid and witty insights into the madness of crowd psychology, such as the tulipmania in Holland, when the price of tulip bulbs was up to astronomical heights. Both of these books are combined into a single volume for the price of one!', 'en', 1993, 288, 'http://books.google.com/books/content?id=3OXIPAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
