INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9f4ffb52-3d5d-5586-b741-7b911e17dd01', '9780938045557', 'The Naked Warrior', 'WzI6NQAACAAJ', 'Have you noticed-the greater a man''s skill, the more he achieves with less? And the skill of strength is no exception. From the ancient days of Greek wrestling, to the jealously guarded secrets of Chinese Kung Fu masters, to the hard men of modern spec ops, warriors and allied strongmen have developed an amazing array of skills for generating inhuman strength.But these skills have been scattered far and wide, held closely secret, or communicated in a piecemeal fashion that has left most of us frustrated and far from reaching our true strength potential.Now, for the first time, Russian strength expert and former Spetsnaz instructor Pavel has gathered many of these devastating techniques into one highly teachable skill set. In The Naked Warrior Pavel reveals exactly what it takes to be super-strong in minimum time-when your body is your only tool.', 'en', 2004, 218, 'http://books.google.com/books/content?id=WzI6NQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
