INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c7049634-e29d-5ebb-a595-0abf37918f96', '9780940322783', 'Seduction and Betrayal', 'rH6QReDflQIC', 'The novelist and essayist Elizabeth Hardwick is one of contemporary America''s most brilliant writers, and Seduction and Betrayal, in which she considers the careers of women writers as well as the larger question of the presence of women in literature, is her most passionate and concentrated work of criticism. A gallery of unforgettable portraits--of Virginia Woolf and Zelda Fitzgerald, Dorothy Wordsworth and Jane Carlyle--as well as a provocative reading of such works as Wuthering Heights, Hedda Gabler, and the poems of Sylvia Plath, Seduction and Betrayal is a virtuoso performance, a major writer''s reckoning with the relations between men and women, women and writing, writing and life.', 'en', 2001, 224, 'http://books.google.com/books/content?id=rH6QReDflQIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
