INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('42c6fc77-b2fd-5432-8796-52bf9f8f64c2', '9780941807555', 'The Little Big Book for God''s Children', 's2PfTIZ2IDEC', 'THE LITTLE BIG BOOK FOR GOD''S CHILDREN is a wonderful resource for parents looking to introduce their children to the wisdom and beauty of Christian faith. Illustrated with early twentieth-century art from artists such as Jessie Wilcox Smith, Ellen H. Clapsaddle, and Maud and Miska Petersham, this Little Big Book presents selected bible stories, parables, and verses; poems and prayers; excerpts and fables; songs and hymns; and activities - all collected in one delightful volume. A celebration of God''s enduring message of love, GOD''S CHILDREN is sure to provide an endless wellspring of inspiration and hope.', 'en', 2001, 352, 'http://books.google.com/books/content?id=s2PfTIZ2IDEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
