INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ecfb99fc-74bf-5d9f-8302-638fd5eaff61', '9780946061150', 'Leaving the 20th Century', 'S5Cc0TY15cEC', 'First published in 1974, ''Leaving..'' was the first collection of Situationist writing in English. Chris Gray, its editor, was himself a member of the SI. Long out of print, it has gained an enormous reputation. This new, lavish, oversize edition, keeps the original provocative, and free and easy translations, along with the cut and paste graphics, poster-art and cartoons. It stands as a remarkable, and eminently accessible, introduction to a remarkable (and oft-times superficially at least, inaccessible) revolutionary project. Now as we stand at the gates of the 21st century, it is time for a new generation of readers to take up this remarkable book.', 'en', 1998, 136, 'http://books.google.com/books/content?id=S5Cc0TY15cEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
