INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e34ec8c0-8a2b-5644-87f2-36dbb7483d84', '9780965429900', 'Desire and Duty', 'Zn6FAAAACAAJ', 'Jane Austen''s story of Elizabeth Bennet Darcy ends with Elizabeth''s marriage. The Baders continue her story as wife, mother and confidante to her sister in law, Georgiana. Set in the years 1805-1816, the story tells the romantic adventures of beautiful, shy, devout Georgiana. Along the way, issues of duty and desire, in marriage and in one''s relationship to God, are presented.', 'en', 1997, 286, 'http://books.google.com/books/content?id=Zn6FAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
