INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('37024825-d5a5-57b3-8357-54d1249ddeb1', '9780966410075', 'You are Being Lied to', 'KALsz08ijnkC', 'This book acts as a battering ram against the distortions, myths and outright lies that have been shoved down our throats by the government, the media, corporations, organized religion, the scientific establishment and others who want to keep the truth from us. A group of researchers - investigative reporters, political dissidents, academics, media watchdogs, scientist-philosophers, social critics and rogue scholars - paints a picture of a world where crucial stories are ignored or actively suppressed and the official version of events has more holes in it than Swiss cheese. A world where real dangers are downplayed and nonexistent dangers are trumpeted. In short, a world where you are being lied to. You''ll discover that a human being has already been cloned; Joseph McCarthy was not paranoid; museums refuse to display artifacts that conflict with the theory of evolution; the CIA has admitted to involvement in the drug trade; parents don''t affect who their children become; plus further revelations involving Columbine, WWII, textbooks, Al Gore, George W. Bush, Timothy Leary and much more.', 'en', 2001, 399, 'http://books.google.com/books/content?id=KALsz08ijnkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5631', 'accepted', 'Russell Kick', 'Language Arts & Disciplines', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 17 FROM public.book WHERE isbn13 = '9780966410075' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e571e829-6e88-56a9-99cc-a85027cb08ff', '9780967469782', 'The Buddha in Your Mirror', '5YVEBAAAQBAJ', 'While the notion that “happiness can found within oneself” has recently become popular, Buddhism has taught for thousands of years that every person is a Buddha, or enlightened being, and has the potential for true and lasting happiness. Through real-life examples, the authors explain how adopting this outlook has positive effects on one’s health, relationships, and career, and gives new insights into world environmental concerns, peace issues, and other major social problems.', 'en', 2001, 230, 'http://books.google.com/books/content?id=5YVEBAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
