INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d413cbd3-512f-520d-862d-e19a834f5cb5', '9780969876748', 'A Winter''s Tale', 'TUyiAAAACAAJ', 'It was a snowy, stormy night, that February 23, 1918, when the sturdy S.S. Florizel steamed out of St. John''s harbour, bound for Halifax and New York. Captain William Martin, a cautious and competent skipper, encountered thick ice and heavy winds as he headed down the treacherous Newfoundland coast. But these circumstances did not account for the ship''s slow speed. Just before dawn, over nine hours after leaving port, Captain Martin ran his ship full steam onto the rocks just north of Cape Race. But that was only the beginning of a long and gruelling drama. As the ship slowly disintegrated, the passengers and crew desperately tried to save themselves. Men, women, and children were washed overboard, or killed from exposure, or fatally trapped below deck. From the shore helpless fishermen watched in horror. Twenty-seven hours after striking the reef the daring rescue took place. Of the 138 on board, seventeen passengers and twenty-seven crew members survived. In A Winter''s Tale Cassie Brown retells in chilling detail the story of the wreck, the rescue, and the enquiry that followed. And she proposes, for the first time, the real reason for this senseless disaster.', 'en', 1997, 276, 'http://books.google.com/books/content?id=TUyiAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5634', 'accepted', 'Cassie Brown', 'Shipwrecks', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 0 FROM public.book WHERE isbn13 = '9780969876748' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('37393505-2e9b-5379-bbb8-a36d31850ca0', '9780970312532', 'New York City''s Best Dive Bars', 'HrG8nd6NrpYC', 'With New York City overrun by cosms-sipping, crouch-sprawling hipsters, it''s high time to explore the places where real people settle in for some real drinking. If you think New York''s classic dives were slipping away, have no fear - Wendy Mitchell''s seven years of bar crawling have unearthed 90 places where you''d be scared to take your parents.', 'en', 2002, 160, 'http://books.google.com/books/content?id=HrG8nd6NrpYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
