INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d8f71c31-72a8-510e-98cd-b9664152000d', '9780971316829', 'Maud Hart Lovelace''s Deep Valley', 'pYuWAAAACAAJ', 'Photography and historical information about the places and faces featured in the Betsy-Tacy Deep Valley books. Includes a removable map containing a walking or driving tour of the locations featured in the books, bibliographies of books by Maud Hart Lovelace, a list of characters and their real-life counterparts, and a membership application for the Betsy-Tacy Society.', 'en', 2002, 325, 'http://books.google.com/books/content?id=pYuWAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5637', 'accepted', 'Julie A. Schrader', 'Authors, American', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 12 FROM public.book WHERE isbn13 = '9780971316829' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9695c562-f18e-5750-8975-a8f39c3bbb1f', '9780971500747', 'Transcending the Levels of Consciousness', 'kXImmwEACAAJ', 'Explores the ego''s expressions and inherent limitations and gives detailed explanations and instructions on how to transcend them. It expands the understanding of the levels of consciousness as presented in the wiedely-acclaimed Map of Consciousness. The book focuses on the individual, and studies the experiential subjective blocks to the advancement of awareness, at each level of consciousness. This leads to progressive spiritual awareness and on to higher levels of consciousness, providing specific steps for transcending each level, preparatory to advanced states such as Enlightenment itself. By analyzing the various obstacles and levels to be transcended, certain principles that support spiritual evolution are self-revealing. This book si therefore a practical manual rather than a comprehensive analysis.', 'en', 2005, 407, 'http://books.google.com/books/content?id=kXImmwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5638', 'accepted', 'David R. Hawkins', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 11 FROM public.book WHERE isbn13 = '9780971500747' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a6176b4e-7109-5fee-9c5d-52af63585d38', '9780971500761', 'Discovery of the Presence of God', '5-UONgAACAAJ', 'Finalizes and further clarifies the true nature and core of the condition termed "Enlightenment." It is primarily an instruction manual for the serious spiritual devotee, and reveals information only known by those who have transcended the ego to reach Divine Realization. This is the inner route from the self to the Self. The subjective states of the mystic are of great interest, but historically never have been clarified to the degree presented in this semi-autobiographical account that also provides the means by which to identify their rare occurrence, and thus describe the core characteristics of Spiritual Truth. Devoid of ecclesiastical doctrine or religious belief systems, the pristine essence of all spiritual Truth is revealed in its purity with unprecedcented clarity.', 'en', 2006, 296, 'http://books.google.com/books/content?id=5-UONgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
