INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b2c54a34-cd4d-5a88-bcf0-b9091bb8ce97', '9780972121798', 'Tea with Jane Austen', 'sqoVPPhhcvYC', 'While to us tea is an everyday commodity, in Austen''s time it was relatively expensive, and to be able to offer it to visitors implied some degree of social status. This book examines the social customs of the time, and includes recipes.', 'en', 2004, 128, 'http://books.google.com/books/content?id=sqoVPPhhcvYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
