INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5279b1ca-89b9-543a-badd-4c629c029981', '9780972167482', 'Dark Birthright', 'Oh3mAQAACAAJ', 'Its 1619 in Scotland, a time of intolerance, when healers are hanged as witches. A child born of mysterious parentage is given to fisher folk to raise as their son. Dughall grows up in a family bound by love and morality, becomes a healer, and displays psychic abilities.His life is torn apart when hes claimed by his real father, a cruel and powerful lord who tries to mold him in his image. Dughall must define himself, in the midst of a struggle between an Earl, a Duke, and the family who wants him back. All the while, hes determined to marry the lass he left behind, a woodland priestess with eyes as green as a peacock''s feather."Dark Birthright" is a story reflecting the political, religious, and cultural dynamics of 17th century Scotland. It paints a picture of life in the Highlands, as well as the fisher folk and a village of witches worshipping the Goddess.', 'en', 2006, 429, 'http://books.google.com/books/content?id=Oh3mAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
