INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e8b2fce6-e91a-5301-b8a2-f03e36b6b610', '9780976249870', 'Jesus Freaks', '0sChAAAACAAJ', 'For God so loved the world that he gave his only two begotten sons. and a few million zombies Thugs, pushers, gangsters, rapists, murderers; Detective Philip Makane thought he''d seen it all until he awoke on the morning of Easter Sunday 2015, to a world filled with bleeding rain, ravenous zombies, a homicidal ghost, and the sudden arrival of two men with extraordinary powers who both claim to be Jesus Christ in the flesh.', 'en', 2006, 390, 'http://books.google.com/books/content?id=0sChAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
