INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4ebbed5f-72a1-5d59-8489-31c7ff1f2f3b', '9780976540601', 'Unauthorized Harry Potter and the Deathly Hallows News', 'LH5C9q83T6wC', 'Through the magic of print-on-demand technology, this "nimble" guide to the work of best-selling author J. K. Rowling provides the latest news about the author and her works, updated whenever there are significant developments. Unlike a conventional book, for which editions are printed in quantity every couple of years, this "living book" goes through frequent "mini-editions" and is printed fresh whenever customers place an order. Purchasers are entitled to free PDF updates! An entirely new section of analysis with more than 75 new pages will be added shortly after the release of "Harry Potter and the Half-Blood Prince" on July 16, 2005.', 'en', 2005, 152, 'http://books.google.com/books/content?id=LH5C9q83T6wC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
