INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('675a85c2-20d7-534f-a0d2-21d8f891bd15', '9780976631156', 'Clown Girl', 'SyIr9jVVsT8C', 'Clown Girl lives in Baloneytown, a seedy neighborhood where drugs, balloon animals, and even rubber chickens contribute to the local currency. Against a backdrop of petty crime, she struggles to live her dreams, calling on cultural masters Charlie Chaplin, Kafka, and da Vinci for inspiration. In an effort to support herself and her layabout performance-artist boyfriend, Clown Girl finds herself unwittingly transformed into a "corporate clown," trapping herself in a cycle of meaningless, high-paid gigs that veer dangerously close to prostitution. Monica Drake has created a novel that riffs on the high comedy of early film stars — most notably Chaplin and W. C. Fields — to raise questions of class, gender, economics, and prejudice. Resisting easy classification, this debut novel blends the bizarre, the humorous, and the gritty with stunning skill.', 'en', 2007, 297, 'http://books.google.com/books/content?id=SyIr9jVVsT8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
