INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('10dbce97-9776-5465-824e-2c7f53afac4e', '9780977312795', 'Pictures Showing what Happens on Each Page of Thomas Pynchon''s Novel Gravity''s Rainbow', 'pjoQBQAAQBAJ', 'Thomas Pynchon''s Gravity''s Rainbow (1973) has been called a modernFinnegans Wake for its challenging language, wild anachronisms, hallucinatory happenings, and fever-dream imagery. With Pictures Showing What Happens on Each Page of Thomas Pynchon''s Novel Gravity''s Rainbow, artist Zak Smith at once eases and expands readers'' experience of the twentieth-century classic. Smith has created more than 750 pages of drawings, paintings, and photos--each derived from a page of Pynchon''s novel. Extraordinary tableaux of the detritus of war--a burned-out Konigstiger tank, a melted machine gun--coexist alongside such fantasmagoric Pynchon inventions as the "stumbling bird" and "Grigori the octopus." Smith has said he aimed to be "as literal as possible" in interpreting Gravity''s Rainbow, but his images are as imaginative and powerful as the prose they honor.', 'en', 2006, 784, 'http://books.google.com/books/content?id=pjoQBQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
