INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('da7b7d6b-4355-5f5f-aa2f-46b7681d16e9', '9780978984809', 'Brevity & echo', 'WngsAQAAIAAJ', 'This collection of previously published short shorts by Emerson alumni celebrates the short short genre and the important role Emerson College''s writing program has played in the history of that genre. The anthology features authors: Derrick Ableman, Joann Avallon, Rusty Barnes, Jane Berentson, Stace Budzko, Leslie Busler, Jennifer Carr, Keith Carter, Chip Cheek, Amy L. Clark, Kirsten Culbertson, Mark DeCarteret, Erin Dionne, Denise Duhamel, Elizabeth Kemper French, Lee Harrington, Jen Heller, Chris Helmuth, Steve Himmer, Brian Hinshaw, Jacqueline Holland, Amanda Holzer, Shannon Huffman, John F. Kersey, Laurel Dile King, Mariette Landry, Molly Lanzarotta, Don Lee, Matt Marinovich, Tara L. Masih, Melissa McCracken, Sheehan McGuirk, LaTanya McQueen, Maryanne O Hara, Janice O Leary, Josh Pahigian, Jennifer Pieroni, Robert Repino, Ashley Rice, Matt Rittenhouse, Joe Robb, Beth Anne Royer, Brian Ruuska, Mary Saliba, Nina R. Scheider, Kimberly Ann Southwick, R. S. Steinberg, Cam Terwilliger, Terry Thuemling, and Laura van den Berg, as well as an introduction by Ron Carlson and an afterword by Pamela Painter.', 'en', 2006, 168, 'http://books.google.com/books/content?id=WngsAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
