INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('35122c7c-dc67-5b9c-9469-134031d5f0f5', '9781400051533', 'The Hedgehog, the Fox, and the Magister''s Pox', '4f8v9WDf0ZIC', 'Draws on the philosophy of seventh century B.C. Greek soldier and poet Archilochus to challenge assumptions about an inescapable conflict between science and the humanities, rebut ideas from Edward O. Wilson''s Consilience, and explain why the pursuit of knowledge must always operate in tandem with nature. Reprint. 50,000 first printing.', 'en', 2003, 288, 'http://books.google.com/books/content?id=4f8v9WDf0ZIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
