INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5cbe25e9-9643-52f9-aff1-2d001756533a', '9781400064892', 'The Wild Trees', 'IWlU7yaIHwcC', 'The best-selling author of The Hot Zone takes a close-up look at the world''s tallest trees, the coast redwoods that grow only in the coastal regions of California, and at the previously unknown ecosystem that the trees form high in the air in the forest canopy, profiling the scientists and researchers that study this unique, labyrinthine ecological niche. 150,000 first printing.', 'en', 2007, 294, 'http://books.google.com/books/content?id=IWlU7yaIHwcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
