INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ec2341f4-da45-5b21-b3a0-0426b2a4943c', '9781400065554', 'American Gospel', '-v2xMy1jkvYC', 'Author Meacham tells the human story of how the Founding Fathers viewed faith, and how they ultimately created a nation in which belief in God is a matter of choice. At a time when our country seems divided by extremism, this book draws on the past to offer a new perspective. Meacham re-creates the history of a nation grappling with religion and politics--from John Winthrop''s "city on a hill" sermon to Thomas Jefferson''s Declaration of Independence; from a proposed nineteenth-century Christian Amendment to the Constitution to Martin Luther King, Jr.''s call for civil rights; from George Washington to Ronald Reagan. At the heart of the American experiment lies what Benjamin Franklin called "public religion," a God who invests all human beings with inalienable rights while protecting private religion from government interference. It is a great American balancing act, and it has served us well.--From publisher description.', 'en', 2006, 399, 'http://books.google.com/books/content?id=-v2xMy1jkvYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
