INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('97cdc327-fed8-5e51-b032-8bd66f561587', '9781400071579', 'Scoop', 'rbxWojccV6gC', 'As Channel 7 new producer Hugo Talley schemes to boost ratings, his team inadvertently lands a huge story, but an untimely Botox disaster for aging anchorwoman Gilda Braun and the personal convictions of a new assistant, Hayden Hazard, threaten to crush Hugo''s dreams of news stardom. Original.', 'en', 2006, 352, 'http://books.google.com/books/content?id=rbxWojccV6gC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
