INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('021ebbe6-16fe-53d0-af86-7c15e68c9052', '9781401211509', 'Desolation Jones', 'x2ogAAAACAAJ', 'A former field agent for M16, Michael Jones was the first surviving victim of the Desolation Test, a radically dangerous procedure cooked up by the British government. Jones was intravenously kept alive while being force-fed a steady diet of horrific data and images non-stop as stimulants were continuously pumped into his body--keeping him conscious and alert for a solid year. Now retired from the agency, Jones lives in Los Angeles, acting as a private investigator to the secret underground community of ex-spooks who have come in from the cold, and who have no one else to turn to.', 'en', 2006, 144, 'http://books.google.com/books/content?id=x2ogAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
