INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c835e065-e7f8-5122-8b45-4ad9621d0668', '9781401300463', 'Pledged', '1WHEwNOApAsC', 'An provocative look inside the world of sorority life offers an eye-opening view of the drugs, psychological abuse, promiscuity, racism, violence, and other problems that are rampant among young women in a typical sorority and analyzes why intelligent young women put up with these abuses in order to become part of a sorority sisterhood. 25,000 first printing.', 'en', 2004, 384, 'http://books.google.com/books/content?id=1WHEwNOApAsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
