INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9120c358-bb25-5131-9bd5-7a2057f9476b', '9781401301880', 'There''s No Place Like Here', 'toYSuQEACAAJ', 'Tracking down missing persons as a way of purging lingering demons about a childhood friend who went missing, Sandy Shortt finds herself increasingly consumed by a growing obsession with understanding how and why people disappear. By the author of PS, I Love You.', 'en', 2007, 340, 'http://books.google.com/books/content?id=toYSuQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
