INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ceba7159-49fa-5380-b730-bc67add18f36', '9781401301941', 'Jamie''s Dinners', 'gMDlAAAACAAJ', 'Cooking sensation Jamie Oliver returns with a cookbook designed to delight the entire family! estselling cookbook author Jamie Oliver takes his signature fresh, fun cooking style into new territory by putting his focus on the family. Designed to encourage us to eat healthier meals at home and enjoy our time spent in the kitchen, Jamie''s Dinners features over 100 new and simple recipes for easy-to-afford, easy-to-prepare gourmet dinners that will get even the busiest of families back into the kitchen. Jamie''s pared-down style and inventive use of fresh, uncomplicated ingredients will ensure that even novice chefs can cook up delicious dinners with confidence and ease using accessible, stylish recipes that the whole family will love, such as Farfalle with Carbonara and Spring Peas and Japanese-Style Saturday Night Steak.', 'en', 2004, 336, 'http://books.google.com/books/content?id=gMDlAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5811', 'accepted', 'Jamie Oliver', 'Cooking', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 20 FROM public.book WHERE isbn13 = '9781401301941' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e2234fb7-5d02-523c-a807-2ff7c067f3b1', '9781401301958', 'Jamie''s Italy', 'e1sYAAAACAAJ', 'Bestselling author Jamie Oliver finally devotes an entire book to America''s favorite cuisine -- Italian! Italy and its wonderful flavors have always had a major influence on Jamie Oliver''s food and cooking. In Jamie''s Italy, he travels this famously gastronomic country paying homage to the classic dishes of each region and searching for new ideas to bring home. The result is a sensational collection of Italian recipes, old and new, that will ensure that Italy''s influence reaches us all. Italy has inspired Jamie Oliver throughout his career. His ambition has always been to travel across the country on a quest to capture the very essence of Italian cooking -- and to produce the best and simplest Italian cookbook for everybody anywhere to enjoy. Jamie''s Italy is the result of that journey -- and it''s a land of plenty. As well as providing more than 120 brand-new recipes for everything from risotto to roasts and spaghetti to stews, structured as traditional trattoria menus, Jamie takes you all over Italy to cook with and learn from the real masters of Italian cuisine: the locals. Far from the standard "lemons and olives" version of Italian cooking, Jamie''s Italy is a cookbook by the people for the people. From Sicily to Tuscany, it''s about the local fishermen, family bakers, and, of course, the "Mamas," sharing their recipes and the tips that have gone into their cooking for generations. But it''s not only mouthwatering food that Jamie brings back home: it''s also the spirit that makes cooking and eating absolutely central to family life, whichever part of Italy youre in. Bursting with the warmth and hospitality of real family life, this is both a superbly accessible cookbook and a unique travelogue and diary, in which youll find the authentic flavor of Italy and the people who live there. If you love quality food prepared with genuine passion -- youll never want to leave Jamie''s Italy.', 'en', 2006, 320, 'http://books.google.com/books/content?id=e1sYAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
