INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b0f83f3a-0ad3-5055-bcf2-aa04b801f079', '9781401359348', 'Being dead is no excuse', 'B6cqAAAAYAAJ', 'A Southern hostess shares the secrets of throwing the proper Southern funeral in a hilarious compilation of recipes and humor that answers such essential questions as: Can you be properly buried without tomato aspic? and Who prepares better funeral fare, the Episcopal ladies or the Methodist ladies? 35,000 first printing.', 'en', 2005, 243, 'http://books.google.com/books/content?id=B6cqAAAAYAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
