INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('abdd2cb5-bc09-596d-9295-3107064bd646', '9781401850685', 'Illustrated Guide to the National Electrical Code', 'hoKRpBF-5TEC', 'This updated edition utilizes visualization to present a complete, concise, and easy-to-understand explanation of the "2005 Edition of the National Electrical Code." From beginners to master electricians, the illustrated guide provides something for everyone practicing a trade in the electrical industry.', 'en', 2005, 452, 'http://books.google.com/books/content?id=hoKRpBF-5TEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
