INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7f12cd8c-0c0b-5ea6-ad7b-d6c7d52512be', '9781402732980', 'Off to Sea', 'vSY8fGIsJTsC', 'A brief, simplified retelling of the episode in "Treasure Island" during which Jim Hawkins and his friends set sail in search of a pirate''s treasure, and Jim meets Long John Silver, who he soon learns is not a friend at all.', 'en', 2006, 32, 'http://books.google.com/books/content?id=vSY8fGIsJTsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
