INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9557a9f9-4839-524f-94ba-c4f7ff493683', '9781403356208', 'Lila''s Child', 'JcBh4L-fj5EC', 'Secular Faith revolves around the friendship of two men, one Christian and the other atheist. The difference in their perspectives, where faith and reason seem to diverge, forms the underlying tension that propels the storyline. When an unlikely sequence of fortune and misfortune seems divinely influenced and leads them to interpret events differently, it produces conflicting judgments on how to react, and their friendship is put to the test. Counteracting the wedge that pushes them apart is the human drive to grasp the spiritual meaning of existence. Because it is not enough to agree to disagree, each is driven to bring the other to his view in order to affirm that it represents truth. Their actions are influenced not by a God who intervenes in the matters of mankind, but by belief of whether or not He does. Ultimately they discover that a man is defined by his actions and not by what he believes to be true. Morality exists to guide actions, not thoughts. The story of Tom Dagney and Christopher Pierce represents the struggle between belief and non-belief within men who, by their very nature, doubt that which they profess to believe, and struggle to understand this dichotomy. How belief translates into behavior proves far more intriguing than scholarly debate about philosophical perspectives. Caring about what people think pales compared to the passions aroused by how they live. This story of friendship, love, envy, tragedy, and redemption gives breath to philosophy and life to the struggle to identify human purpose. Above all Secular Faith exemplifies that, without a doubt, a man who puts aside his faith to serve his friends will always be a better man than one who puts aside his friends to serve his faith.', 'en', 2003, 600, 'http://books.google.com/books/content?id=JcBh4L-fj5EC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5834', 'accepted', 'Dan Glover', 'Computers', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 0 FROM public.book WHERE isbn13 = '9781403356208' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0df2168f-b5cc-56e4-87d9-f304aa47201b', '9781403904560', 'V.S. Naipaul, Second Edition', 'uVZzQgAACAAJ', 'This revised and updated introduction to the novels and non-fiction of V.S. Naipaul will be of interest to students, specialists and general readers. Chronological chapters examine the structure, significance and development of Naipaul''s writing, setting the texts in their autobiographical, philosophical, social and political, colonial and post-colonial contexts. New chapters in the second edition include an expanded biographical introduction, and discussion of the recent novels A Way in the World and Half a Life, Naipaul''s writings on Islam, and the criticism of Naipaul by writers and post-colonial theorists.', 'en', 2003, 240, 'http://books.google.com/books/content?id=uVZzQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5835', 'accepted', 'Bruce King', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 9 FROM public.book WHERE isbn13 = '9781403904560' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('908a2ed6-5536-5f16-8203-708af5738542', '9781403967213', 'EntreMundos/AmongWorlds', 'XYXgPjlnYqwC', 'EntreMundos offers a multidisciplinary investigation of the concepts, impact, and writings of contemporary cultural theorist and creative writer, Gloria Anzaldua. Her work, which is frequently anthologized and often cited, as well as widely taught at the high school, undergraduate, and graduate level, has challenged and expanded previous views in American Studies, Chicano/a Studies, composition studies, cultural studies, ethnic studies, feminism, literary studies, critical pedagogy, and queer theory. Here scholars from a number of disciplines gather to reflect critically and anecdotally on Anzaldua''s writing, her ideas, and the wider significance of her work. Highlighting some of Anzaldúa''s lesser explored theories, EntreMundos challenges readers to re-examine Anzaldúa''s writings and theorizing from additional perspectives. The goal is to broaden Anzaldúan scholarship, shifting the conversation in new directions while underscoring the visionary yet pragmatic social-justice dimensions of her work.', 'en', 2005, 304, 'http://books.google.com/books/content?id=XYXgPjlnYqwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5836', 'accepted', 'AnaLouise Keating', 'Literary Collections', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 4 FROM public.book WHERE isbn13 = '9781403967213' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('02721e8d-9833-54c9-8920-7c8fba1189d5', '9781403967923', 'Strawberry Days', 'iO3zwAEACAAJ', 'Strawberry Days tells the vivid and moving tale of the creation and destruction of a Japanese immigrant community. Before World War II, Bellevue, the now-booming "edge city" on the outskirts of Seattle, was a prosperous farm town renowned for its strawberries. Many of its farmers were recent Japanese immigrants who, despite being rejected by white society, were able to make a living cultivating the rich soil. Yet the lives they created for themselves through years of hard work vanished almost instantly after the bombing of Pearl Harbor. David Neiwert combines compelling story-telling with first-hand interviews and newly uncovered documents to weave together the history of this community and the racist schemes that prevented the immigrants from reclaiming their land after the war. Ultimately, Strawberry Days represents more than one community''s story, reminding us that bigotry''s roots are deeply entwined in the very fiber of American society.', 'en', 2005, 288, 'http://books.google.com/books/content?id=iO3zwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5837', 'accepted', 'David A. Neiwert', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 14 FROM public.book WHERE isbn13 = '9781403967923' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('708d2abb-f1d0-52a1-b0ef-c52c73333610', '9781403969736', 'Tolkien''s Modern Middle Ages', '3r_9wAEACAAJ', 'J.R.R. Tolkien delved into the Middle Ages to create a critique of the modern world in his fantasy, yet did so in a form of modernist literature with postmodern implications and huge commercial success. These essays examine that paradox and its significance in understanding the intersection between traditionalist and counter-culture criticisms of the modern. The approach helps to explain the popularity of his works, the way in which they continue to be brought into dialogue with Twenty-First century issues, and their contested literary significance in the academy.', 'en', 2008, 264, 'http://books.google.com/books/content?id=3r_9wAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5838', 'accepted', 'J. Chance; A. Siewers', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 5 FROM public.book WHERE isbn13 = '9781403969736' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c5a43bfa-aeae-5963-ada3-1851c10cdc68', '9781405151412', 'How to Read a Poem', 'mU7FZ7W-TkoC', 'Lucid, entertaining and full of insight, How To Read A Poem is designed to banish the intimidation that too often attends the subject of poetry, and in doing so to bring it into the personal possession of the students and the general reader. Offers a detailed examination of poetic form and its relation to content. Takes a wide range of poems from the Renaissance to the present day and submits them to brilliantly illuminating closes analysis. Discusses the work of major poets, including John Milton, Alexander Pope, John Keats, Christina Rossetti, Emily Dickinson, W.B. Yeats, Robert Frost, W.H.Auden, Seamus Heaney, Derek Mahon, and many more. Includes a helpful glossary of poetic terms.', 'en', 2006, 182, 'http://books.google.com/books/content?id=mU7FZ7W-TkoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5839', 'accepted', 'Terry Eagleton', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 18 FROM public.book WHERE isbn13 = '9781405151412' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b1025b12-fed7-5212-8142-725f6b453051', '9781405153607', 'Christian Theology', 'tHlY94UWi3UC', 'Alister McGrath’s internationally-acclaimed Christian Theology: An Introduction is one of the most widely used textbooks in Christian theology. Fully revised and featuring lots of new material, this fourth edition provides an unparalleled introduction to 2,000 years of Christian thought. A fully revised new edition of the bestselling introductory textbook in Christian theology Features new sections on monastic schools of theology, the English Reformation, and Radical Orthodoxy Includes increased discussion of women in the early Church, feminist theology, Eastern Orthodox theology and history, and Catholic teachings on the Doctrine of the Church Incorporates user-friendly key terms sections, and study questions Supported by a website at www.blackwellpublishing.com/mcgrath, containing additional lecturer resources.', 'en', 2006, 534, 'http://books.google.com/books/content?id=tHlY94UWi3UC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5840', 'accepted', 'Alister E. McGrath', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 2 FROM public.book WHERE isbn13 = '9781405153607' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f49fb7f8-eb5b-512d-926d-e623e261a07f', '9781405161602', 'South Park and Philosophy', 'BJq0Z8gtO2kC', 'If you think Saddam and Satan make a kinky couple, wait till you get a load of South Park and Philosophy. Get your Big Wheels ready, because we’re going for a ride, as 22 philosophers take us down the road to understanding the big-picture issues in this small mountain town. A smart and candid look at one of television’s most subversive and controversial shows, celebrating its 10th anniversary this year Draws close parallels between the irreverent nature of South Park and the inquiring and skeptical approach of philosophy Addresses the perennial questions of the show, and the contemporary social and political issues that inspire each episode Uses familiar characters and episodes to illustrate topics such as moral relativism, freedom of expression, gay marriage, blasphemy, democracy, feminism, animal ethics, existential questions and much more makes you laugh out loud', 'en', 2006, 273, 'http://books.google.com/books/content?id=BJq0Z8gtO2kC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5841', 'accepted', 'Robert Arp', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 4 FROM public.book WHERE isbn13 = '9781405161602' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('803b8227-2b5a-5e4b-8a80-b2f17a5a22c5', '9781405201711', 'The Faraway Tree Stories', '2d93OAAACAAJ', 'Jo, Bessie and Fanny move to the country and find an Enchanted Wood right on their doorstep And in the wood stands the magic Faraway Tree, and in that tree live the magical characters that soon become their new friends - Moon-Face, Silky the fairy, and Saucepan Man. Together they climb through the clouds to the top of the tree and discover the Land of Spells, The Land of Secrets and the Land of Do-As-You-like. There are lots of magical adventures to read about in this bumper 3-in-1 edition.', 'en', 1987, 583, 'http://books.google.com/books/content?id=2d93OAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5842', 'accepted', 'Enid Blyton', 'Children''s stories, English', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 3 FROM public.book WHERE isbn13 = '9781405201711' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('72bf377a-4192-5196-a51e-7c11985244ef', '9781405203944', 'The Mystery of the Disappearing Cat', 'V6aEAAAACAAJ', 'A fantastic children’s crime story from the world’s best-loved children’s author, Enid Blyton. Lady Candling''s best Siamese cat has gone missing. It''s another mystery for the Find-Outers! The gardener, Luke, always seems so friendly. He couldn''t possibly be the thief... Or could he? All will be revealed in The Mystery of the Disappearing Cat. The Mystery series follows the adventures of ‘The Five Find Outers’ - Pip, Bets, Larry, Daisy and Fatty, as they solve the most unusual crime cases with the help of their dog Buster. Enid Blyton is arguably the most famous children’s author of all time. Thanks to series such as The Wishing-Chair, The Faraway Tree­, The Mysteries, The Famous Five and The Secret Seven, she has sold over 400 million books in more than 40 languages worldwide. Her Mysteries stories have charmed generations of children – and they are as popular today as they have ever been.', 'en', 1944, 232, 'http://books.google.com/books/content?id=V6aEAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
