INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('64465085-253b-5946-abea-8413b7b73d85', '9781410103277', 'The End of Nana Sahib', 'aBYMAAAACAAJ', 'This story is dated a few years after the Indian Mutiny. A party of men travel many miles in a wonderful moving house, drawn by a marvelous steam elephant. Their many adventures, and the doings of Nana Sahib, the fiend of the Mutiny and his final overthrow, are very exciting.', 'en', 2003, 276, 'http://books.google.com/books/content?id=aBYMAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
