INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3519da12-64a8-54db-9ac0-0943020bfcf1', '9781411665309', 'Existential Meditation', '8-2zkuSOPWsC', 'In this three-part discourse, Simon Cleveland offers a perspective on life derived partly from the latest scientific theories in cosmology and quantum mechanics and partly from analysis on the works of some of the greatest writers and philosophers of the nineteenth and twentieth centuries. The book explores topics such as the meaning of time, consciousness and the development of the essence. The author also examines the genesis of the concept of immortality.', 'en', 2005, 100, 'http://books.google.com/books/content?id=8-2zkuSOPWsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
