INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8541aa11-dddf-53bf-89da-cceb93b58e85', '9781411683051', 'The Master and Margarita', 'Xw_WwAEACAAJ', 'Moscow, 1929: a city that has lost its way amid corruption and fear, inhabited by people who have abandoned their morals and forsaken spirituality. But when a mysterious stranger arrives in town with a bizarre entourage that includes a giant talking cat and a fanged assassin, all hell breaks loose. Among those caught up in the strange and inexplicable events that transpire in the capital are the Master, a writer whose life has been destroyed by Soviet repression, and his beloved Margarita. Their adventures reveal a story that began two thousand years ago in ancient Jerusalem -- and its resolution will decide their fate. Translated by Michael Karpelson.', 'en', 2006, 332, 'http://books.google.com/books/content?id=Xw_WwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5863', 'accepted', 'Mikhail Afanasevich Bulgakov', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 2 FROM public.book WHERE isbn13 = '9781411683051' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('15824669-ba15-5385-a082-f3211cdbcfb4', '9781412040556', 'The Radical Right and the Murder of John F. Kennedy', 'LD8TUAGSuMoC', 'The Radical Right and the Murder of John F. Kennedy: Stunning Evidence in the Assassination of the President Harrison E. Livingstone''s major new book, the fifth of his works on the death of JFK, brings together for the first time all of the central evidence demonstrating a domestic Right Wing conspiracy rooted in Texas which assassinated the President on November 22, 1963. The book represents forty years of work. The book discusses in great detail the actual medical evidence and the forgery of the autopsy photographs and X-rays, which Mr. Livingstone first exposed, the alteration of the autopsy report, the framing of the designated patsy, Lee Harvey Oswald, and the substitution and fabrication of every single piece of evidence. It discusses the role played in the murder by some of the most powerful men in the country: Lyndon Johnson, J. Edgar Hoover, and Richard Nixon, as well as the rich oil men and companies who backed them. It then describes the cover-ups by the media, the major investigations over the years, the FBI, and the mind-control cooperation at work in the case to misdirect researchers and the public. The book describes in great detail the people and companies in Texas who planned and carried out the assassination. It names names. One recent investigation in the 90s followed Mr. Livingstone''s preceeding work and reinvestigated with the witnesses both he and the official investigations had talked to, but this time took into consideration their documentation and what they had actually said, and in a chapter this is his stunning new evidence from the U.S. government under President Clinton that is blowing the lid off the case. Mr. Livingstone first revealed to the Washington press corps in 1998 that there has been such a secret investigation, and spoke for fifty minutes when the Assassination Records Review Board gave their final press conference. As a result, Mr. Livingstone was on all major TV networks and on the "Today" show (NBC) with Katie Couric the next morning. The book also contains the story of Dallas doctor Charles Crenshaw''s law suit and the depositions of the editor and writer of the Journal of American Medical Association who libeled him in articles in 1992. Dr. Crenshaw''s book about trying to save Kennedy at Parkland Hospital shortly after the shooting came out on the same day as Mr. Livingstone''s major work on the medical evidence, High Treason 2, were JAMA''s targets, and the depositions contain much discussion of Mr. Livingstone''s major impact on the JFK case. This new book is to be followed closely by a sixth book entirely about the Zapruder film, called The Hoax of the Century: Decoding the Forgery of the Zapruder Film.', 'en', 2004, 615, 'http://books.google.com/books/content?id=LD8TUAGSuMoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
