INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('aab6801e-1dc3-50a6-9e10-6bb15ecf6c16', '9781416501626', 'Dirty Little Secrets', 'cLOax2a40x8C', 'USA Today bestselling author Julie Leto launches a caliente new series featuring a sexy, Latina bounty hunter with an appetite for danger and an insatiable thirst for the man she''s hunting down: her ex. When Marisela Morales sets out to stop her ex-boyfriend Francisco Vega from skipping out on bail, she has a secret agenda: revenge. She hasn''t seen Frankie in ten years, and back then, he broke her heart, choosing his gang over his girl. So when she tracks him down in their old haunt, a hot dance club in Tampa, she sets about seducing him into her trap. Frankie has a secret agenda, too, and Marisela soon faces a tough choice: continue drifting through her twentysomething life -- hitting the same town with the same girlfriends every weekend while struggling to find a job and pay the rent -- or dive headfirst into danger with her ex. Frankie operates in a treacherous underworld full of arms dealers, assassins, and sinister agendas -- a world overrun with people keeping dirty little secrets -- and only Marisela has the cojones to fight her way to the truth. Sexy, sultry, and action-packed, Dirty Little Secrets is a thrilling adventure in manhunting of the most dangerous kind.', 'en', 2005, 352, 'http://books.google.com/books/content?id=cLOax2a40x8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
