INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f70268cf-1966-5734-a966-0d062d40dfd6', '9781416509387', '1635: Cannon Law', 'dpVYaFSYmYEC', 'In Rome in 1635, Grantville''s diplomatic team, headed by Sharon Nichols, has come to a standstill in their negotiations with Pope Urban VIII, whle an ambitious Cardinal Borja launches his sinister schemes, mysterious agitators are stirring up trouble, Spain''s armies prepare for an attack on the Kingdom of Naples, and Frank Stone finds himself in the middle of the trouble.', 'en', 2006, 420, 'http://books.google.com/books/content?id=dpVYaFSYmYEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
