INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5acb22ae-6bdf-552d-af66-58b86f92c47c', '9781416510871', 'Playing Easy to Get', '-shysdG-bA4C', 'Three novellas feature a law enforcement officer who endeavors to serve his passions, a ruthless vampire warrior who desires a vengeful valkyrie, and a neo-Viking warrior who spirits his unwilling bride to an underground realm.', 'en', 2006, 352, 'http://books.google.com/books/content?id=-shysdG-bA4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
