INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d2018b86-a1eb-5750-bde5-2ac0bad70568', '9781416520399', 'Midnight Brunch', 'e07VyAEACAAJ', 'What''s a girl to do when she discovers she''s the main course on the menu? Hip, funny Milagro de los Santos thinks she''s finally found love and a home at the California ranch of fabulous Oswald Grant and his urbane relatives, who have a rare genetic disorder that some call vampirism. But Milagro is bewildered when she''s excluded from an ancient and mysterious midnight ceremony whose participants include Oswald''s unfriendly parents, a creepy family elder, and Milagro''s ex-lover, the powerful and decadent Ian Ducharme. What skeletons are the vampires keeping in their designer closets? When Milagro''s life is threatened by a rogue family member, she flees to the desert to hide. Instead of solitude, she encounters an egomaniacal actor, a partying heiress, a sly tabloid reporter, and a lavish spa full of dark secrets -- all of which might help her find a way home.', 'en', 2007, 336, 'http://books.google.com/books/content?id=e07VyAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
