INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0a569d02-8274-50b9-b78b-146b303002ea', '9781416521075', 'By Slanderous Tongues', 'MRqVdBYNPJIC', 'In the epic sequel to Ill Met by Moonlight, in the wake of Henry VIII''s death, a young Princess Elizabeth is confronted by enemies--both human and supernatural--who will do anything to keep her from the throne of England.', 'en', 2007, 544, 'http://books.google.com/books/content?id=MRqVdBYNPJIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
