INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7cf6b868-550b-584a-a701-d22fbbf57db1', '9781416521105', 'Bedlam''s Edge', 'RjsiAAAACAAJ', 'Mercedes Lackey and Rosemary Edghill are the biggest names in the urban fantasy subgenre¿where elves, banshees, trolls, and even stranger creatures walk modern city streets, their presence, and even their existence unsuspected by the human inhabitants. Now these two present a volume of all new urban fantasy, with a stellar lineup of the best new fantasy writers, such as Roberta Gellis, Dave Freer and Eric Flint, Diana Paxton, and more¿including two new stories and an afterword by Mercedes Lackey herself, as well as a story by Rosemary Edghill. This is an indispensable volume for fans of urban fantasy in general, and the thousands of fans of Mercedes Lackey in particular.', 'en', 2007, 384, 'http://books.google.com/books/content?id=RjsiAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
