INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('43dd5622-c6d4-564a-b71e-2f87faffa710', '9781416532354', 'Ricochet', 'WJtGXnJMoTsC', 'When detective Duncan Hatcher is summoned to the stately home of Judge Cato Laird to investigate a killing, he realises that discretion is key if he wants to keep his job. Elise, the judge''s trophy wife, claims to have shot and killed a burglar in self-defence, but Duncan is almost certain she''s lying.', 'en', 2007, 400, 'http://books.google.com/books/content?id=WJtGXnJMoTsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
