INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9c61df72-1b5b-5f3a-a696-2818da384d3d', '9781416903437', 'Wild Magic', 'lV1OPgAACAAJ', 'Thirteen-year-old DaIne has always had a knack with animals, but it''s not until she''s forced to leave home that she realizes it''s more than a knack -- it''s magic. With this wild magic, not only can Daine speak to animals, but also she can make them obey her. Daine takes a job handling horses for the Queen''s Riders, where she meets the master mage Numair and becomes his student. Under Numair''s guidance, Daine explores the scope of her magic. But she begins to sense other beings too: immortals. These bloodthirsty monsters have been imprisoned in the Divine Realms for the past four hundred years, but now someone has broken the barrier. It''s up to Daine and her friends to defend their world from an immortal attack.', 'en', 2005, 362, 'http://books.google.com/books/content?id=lV1OPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
