INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('97fc10ab-21e8-5620-ae74-ed99ade2def9', '9781416916321', 'Same Sex in the City', 'mDlmAAAACAAJ', 'At last, a relationship book for lesbians that tells it like it is . . . The journey from sexual curiosity to finally coming out can be confusing without proper guidance and empowering role models. In Same Sex in the City, Lauren Levin and Lauren Blitzer provide women -- gay, straight, and bi-curious alike -- with firsthand insight into the advantages and challenges of being a lesbian. In prose that is at once honest and uplifting, the Laurens relate their own experiences and those of the women they interview, as well as offer serious advice, titillating anecdotes, and a positive attitude for girls who know they''re gay -- and for those who are wondering about their sexuality but are not yet sure whether their Prince Charming is really a Cinderella. Part confessional, part informational, Same Sex in the City covers the gamut of lesbian life -- from dating to heartbreak, and from hooking up with straight chicks to raising a family. It''s the book that millions of women have been searching for -- a relationship guide that will help every woman come to terms with and celebrate her sexuality, whatever it may be.', 'en', 2006, 250, 'http://books.google.com/books/content?id=mDlmAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
