INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cff06ad0-fcd3-5a2a-b369-8b36c4a0ac27', '9781419154072', 'The Birth Of Tragedy', 't8NWyUHPwc0C', 'Indeed, what is the Dionysian? This book offers an answer to that question: a "knowledgeable person" speaks there, the initiate and disciple of his own god. Perhaps I would now speak with more care and less eloquently about such a difficult psychological question as the origin of tragedy among the Greeks. A basic issue is the relationship of the Greeks to pain, the degree of their sensitivity. Did this relationship remain constant? Or did it turn itself around? That question whether their constantly strong desire for beauty, feasts, festivities, and new cults arose out of some lack, deprivation, melancholy, or pain.', 'en', 2004, 84, 'http://books.google.com/books/content?id=t8NWyUHPwc0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
