INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('93261e91-5ac6-555a-a9c7-ba69c182f92e', '9781419542206', 'The Scarlet Letter', 'JgwYvgAACAAJ', 'The Scarlet Letter: A Kaplan SAT Score-Raising Classic features: *The complete tale of the classic novel, The Scarlet Letter *More than 800 vocabulary words frequently tested on the SAT highlighted throughout the text *Definitions for each highlighted word on the facing page *A pronunciation guide *An index for easy reference', 'en', 2006, 553, 'http://books.google.com/books/content?id=JgwYvgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
