INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f72479f0-84af-58df-b219-75bcd8b0ba5e', '9781419950582', 'Harm''s Way', 'rX2NswEACAAJ', '"Elgin Collier, AKA Gillian Shelby, is the world''s most popular women''s erotica author. She has wealth, success and now apparently a stalker who may already have committed murder. Sheila Forbes, Elgin''s publisher and best friend hires Campbell Harm, head of Harm''s Way Security to protect her and find the stalker. It''s hate at first sight for these strong-willed, independent people. He thinks she''s a ""pornographer"" and she thinks he''s a ""knuckle-dragging Neanderthal."" Sparks fly from their first meeting."', 'en', 2005, 261, 'http://books.google.com/books/content?id=rX2NswEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5922', 'accepted', 'Elizabeth Stewart', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 5 FROM public.book WHERE isbn13 = '9781419950582' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('abf432d9-2ea3-5c17-ac9f-4fb8ac0b34bb', '9781419953965', 'Wicked Sacrifice', 'dQ7sPAAACAAJ', 'Bound Hearts - Wicked Intent By Lora Leigh Control has meant everything to Tally Raines. Control of the office she ran as Jesse Wyman''s secretary, and now control of Lucian Conover''s office as well. But Lucian isn''t content to be controlled by his fiery secretary. As a matter of fact, Lucian thinks she needs to loosen up and let the sexy, sensual woman hiding beneath her cool exterior free. And he will dare her to do just that...With a little help. Bound Hearts - Sacrifice By Lora Leigh Book five of the Bound Hearts series. Kimberly has run from Jared for a year now, sensing the weakness he could be to her future. But she never expected the sacrifice he would make for her. One that will rock her soul, and destroy the very foundations of all her beliefs. Her sexuality, her heart, and all she''s fought for in the last six years will be tested when an assignment takes her to Jared''s farm, and into his bed. There she will learn the true meaning of hunger, of love¿as well as the deception and the lies that have governed her life for so long. Anything worth having is worth sacrificing for. Kimberly is about to find out if she can pay the price, and risk not only the inheritance that should be hers, but also her heart to the one man who can still the fires that rage in her soul.', 'en', 2006, 290, 'http://books.google.com/books/content?id=dQ7sPAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
