INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3c9ae7d3-2d4d-5a7a-81b9-ee8d9c654373', '9781421502793', 'Maison Ikkoku', '-CpgQgAACAAJ', 'From the creator of RANMA 1/2 and INUYASHA comes one of Rumiko Takahashi''s most beloved series, the romantic (sort of) comedy MAISON IKKOKU, re-presented in a second edition in its original episodic order, with a "missing" episode! Take a trip down memory lane back into Japan''s nuttiest apartment house and meet its volatile inhabitants: Kyoko, the beautiful and mysterious new apartment manager; Yusaku, the exam-addled college student; Mrs. Ichinose, the drunken gossip; Kentaro, her bratty son; Akemi, the boozy bar hostess who runs around the house in flimsy lingerie; and the mooching and peeping Mr. Yotsuya.', 'en', 2006, 208, 'http://books.google.com/books/content?id=-CpgQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
