INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('21d813ec-3314-584f-b9d6-9e230d2d706d', '9781421503547', 'Beauty is the Beast', 'G2-BAAAACAAJ', 'When bubbly eleventh-grader Eimi Yamashita finds out that her parents are relocating for work, she decides to strike out on her own and move into a dormitory for girls. Little does Eimi suspect the exciting romantic adventures that await her there! As winter sets in at the dforms and the boys hog all the electricity, Shimonuki continues his quest to win Eimi''s heart. She agrees to a date but they both end up confessing to Wanibuchi. Despite Wanibuchi''s commitment to another woman, Eimi can''t stop loving him. What will she do if Wanibuchi moves back to Mexico?!', 'en', 2006, 208, 'http://books.google.com/books/content?id=G2-BAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
