INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('55208b9e-0902-5124-84b2-49b4ef30105b', '9781421505411', 'From Far Away', '9zyolwEACAAJ', 'The End is here! The darkness that has pursued Noriko and her tortured warrior Izark descends full force as their corrupt enemies in the government stage a last coup. With Noriko bedridden, Izark must fight alone, but help may come from an unexpected source. Still, even if they survive, the prophecy can no longer be avoided. The time of the Sky Demon has come--and no one is ready for the final revelation. Will Noriko truly be the death of her first and only love? Find out all the answers and much more in the incredible conclusion to this epic manga.', 'en', 2007, 208, 'http://books.google.com/books/content?id=9zyolwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
