INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5169cbc9-c60d-5263-9d5e-42e534c47aaa', '9781421506296', 'Death Note', '-opLtgEACAAJ', 'Target: Light--working as Kira, the newest member of the NPA intelligence bureau, and L--has nearly succeeded in creating his ideal world. But the years of uncontested victory have made him complacent, and he is unprepared for a new attack close to home. With his younger sister Sayu kidnapped and the NPA''s Death Note demanded as ransom, Light must travel across the world and confront two new adversaries, each with a very different agenda. Will Light''s quick wits be a match for this new challenge, or will he be forced to choose between Kira''s ambitions and his own family''s lives?', 'en', 2006, 201, 'http://books.google.com/books/content?id=-opLtgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
