INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('aea866d2-27cc-52b5-b2ec-694abf9de57b', '9781421506548', 'JoJo''s Bizarre Adventure: Part 3--Stardust Crusaders', 'BT7DugEACAAJ', 'Violent, strange saga spanning four continents and four generations. Araki''s ideas are stretched increasingly thin, but there is still plenty of action and new concepts to sustain the interest of demanding Shounen Jump readers. Each part of Jojo can be read more or less independently, and has its own atmosphere and storytelling/art style.', 'en', 2006, 208, 'http://books.google.com/books/content?id=BT7DugEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
