INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1d6911f5-67ca-5045-90f1-c3e7f651a2d2', '9781421509594', 'The Drifting Classroom', '6ME-PQAACAAJ', 'A flash flood turns the desert into a drowned world, and the students struggle to protect the school--and their precious vegetable garden--from the deluge. But just as the first vegetables are ready to harvest, the crop is infested with a strange fungus. Was all their work for nothing? Lonely for home and their parents, the students make a surrogate mother out of a statue...only to find it replaced one day by a new, terrifying idol...', 'en', 2007, 192, 'http://books.google.com/books/content?id=6ME-PQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
