INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c8bff172-07af-5031-b002-272a2fe36c2c', '9781423100614', 'Pirates of the Caribbean: The Sword of Cortes - Jack Sparrow #4', 'AiezGQAACAAJ', 'This is it! Jack and his crew have found the Sword of Cortes, but along with it, they’ve also found Cortes himself. And he’s not the kind ruler they thought he’d be. Jack and his crew have defeated a storm king, escaped sirens, defeated the notorious pirate Left Foot Louis, but can they possibly conquer a conquistador with god-like powers?', 'en', 2006, 122, 'http://books.google.com/books/content?id=AiezGQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
