INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2eacb89c-d55d-5189-bd67-1b8cbf44cd05', '9781423101680', 'Pirates of the Caribbean: Age of Bronze - Jack Sparrow #5', 'iHKINwAACAAJ', 'The beginning of a new story arc! Jack and company are regrouping after their Sword of Cortes ordeal. They want to forget about magical power and turn their attention towards treasure. But they are about to learn that in the Caribbean magic and treasure often go hand in hand when they encounter a young sailor who can turn things to solid… bronze?', 'en', 2006, 144, 'http://books.google.com/books/content?id=iHKINwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
