INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('55d27dd1-f53d-534b-b948-f69304b0af58', '9781423600763', 'Surfer''s Code', 'DgSl4_tFfR8C', 'Surfing has been described as a sport, religion, obsession and way of life. For Shaun Tomson, world-champion surfer and successful entrepreneur, surfing is all of that and more. In Surfer''s Code, Tomson shares the life lessons he''s gathered from many years of surfing-from his boyhood in apartheid South Africa to the world tour in the ''70s and ''80s.', 'en', 2006, 192, 'http://books.google.com/books/content?id=DgSl4_tFfR8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
