INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6b1466f1-9314-5682-a546-09539c12ed99', '9781425910396', 'The Trouble with the Pears', 'PlJPmAEACAAJ', 'Picture a Navy biplane swooping low over the Grand Concourse in the Bronx and a father and son being so scared that the former dropped the auto battery he carried. The pilot was Al Williams, the Navy''s first test pilot flying over New York. He had met General Billy Mitchell, who had proved that planes could sink battleships with bombs. Williams developed inverted flight and diving from great heights to gain speed in air races a tactic later pilots developed into dive bombing. Williams fought for air power rather than for battleships, a trait that did not endear him to F.D.R. He encouraged thousands to become air-minded and to serve in WWII. He wrote with conviction for air power.', 'en', 2006, 272, 'http://books.google.com/books/content?id=PlJPmAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
