INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('41b2a1f6-0198-53c4-8014-37c7e2eaec8d', '9781426423703', 'The Adventures of Sally', 'Tu_yc69FKcAC', 'Sally looked contentedly down the long table. She felt happy at last. Everybody was talking and laughing now, and her party, rallying after an uncertain start, was plainly the success she had hoped it would be.', 'en', 2007, 232, 'http://books.google.com/books/content?id=Tu_yc69FKcAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
