INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5b3a13a0-2e1b-5470-9ed0-98d4ab3e46e7', '9781550023923', 'No Cherubs for Melanie', 'Hss8hg6xUYUC', 'Melanie Gordonstone, a cherubic six-year-old, was Daddy''s favourite in every way, but her life ended tragically when she drowned in a backyard pond. Inexperience led young English detective David Bliss to attribute the girl''s death to an accident, but since that time he has been haunted by doubts about his original conclusion. Now, more than twenty years later, Melanie''s father has died, and toxicology reports indicate that he was murdered. Bliss begins to suspect Melanie''s sister, Margaret, who lives in a remote community in northern Ontario. But could Margaret have killed her father from half a world away? Bliss''s unauthorized investigation brings him overseas to Canada in search of Margaret - and answers. As he gets closer to the truth, he uncovers the disturbing secrets that have destroyed the Gordonstone family.', 'en', 2002, 394, 'http://books.google.com/books/content?id=Hss8hg6xUYUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
