INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4bbd7c72-cad0-5e19-b0cb-5bd72c9c44a7', '9781550225402', 'Bite Me!', 'h3ENAAAACAAJ', 'Revised and updated to include information about all six seasons of Buffy, this ultimate guide to one of televisions hottest shows also includes capsule reviews of the full first three seasons of the spin-off Angel, with more emphasis put on the crossover episodes between the two shows. With full cast bios, plus bios for all of the new cast members who have become major characters in the latest season, this best-seller is bound to keep selling!', 'en', 2002, 450, 'http://books.google.com/books/content?id=h3ENAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
