INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('422823b2-e29b-5ec6-84e8-7cd4ccf26e4f', '9781551111728', 'Lord Jim', '23H0nIJtLEkC', 'One of Joseph Conrad’s greatest novels, Lord Jim brilliantly combines adventure and analysis. Haunted by the memory of a moment of lost nerve during a disastrous voyage, Jim submits to condemnation by a Court of Inquiry. In the wake of his disgrace he travels to the exotic region of Patusan, and as the agent at this remote trading post comes to be revered as ‘Tuan Jim.’ Here he finds a measure of serenity and respect within himself. However, when a gang of thieves arrives on the island, the memory of his earlier disgrace comes again to the fore, and his relationship with the people of the island is jeopardized. This new Broadview edition is based on the first British edition of 1900, which provides the historical basis for the accompanying critical and contextual discussions. The appendices include a wide variety of Conrad’s source material, documents concerning the scandal of the Jeddah, along with other materials such as a substantial selection of early critical comments.', 'en', 2000, 455, 'http://books.google.com/books/content?id=23H0nIJtLEkC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5973', 'accepted', 'Joseph Conrad', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 16 FROM public.book WHERE isbn13 = '9781551111728' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d9e0cbea-c5f3-5531-9deb-0b8c0315b8be', '9781551112237', 'Alice''s Adventures in Wonderland', 'HJ8Wg0u7CUgC', 'First published in 1865, Alice''s Adventures in Wonderland began as a story told to Alice Liddell and her two sisters on a boating trip in July of 1862. The novel follows Alice down a rabbit-hole and into a surreal world of strange and wonderful characters who constantly turn everything upside-down with their mind-boggling logic and word play, and their fantastic parodies. Carroll''s fable illustrates his masterful ability to weave logic with nonsense in a tale that continues to delight all ages. While this great classic is widely available, the Broadview edition is unique. Richard Kelly combines Alice''s Adventures in Wonderland not with the later (and largely distinct) work Through the Looking Glass but rather with Alice''s Adventures Under Ground, Lewis Carroll''s first version of the story. Readers are thus able to trace the literary revisions, and to compare Caroll''s own illustrations in the original with the famous John Tenniel illustrations for Alice''s Adventures in Wonderland. Among the many other materials included in the Broadview Literary Texts edition are a substantial selection of early reviews, selections from Carroll''s diaries and correspondence, Carroll''s early nonsense poems, and the originals of the poems parodied in his text.', 'en', 2000, 356, 'http://books.google.com/books/content?id=HJ8Wg0u7CUgC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5974', 'accepted', 'Lewis Carroll', 'Juvenile Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 8 FROM public.book WHERE isbn13 = '9781551112237' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a0f9a499-063c-5966-89c5-fbb7513e00b1', '9781551114125', 'The Governess', 'zHAx97IJgKEC', 'Published in 1749, the story of Mrs. Teachum and the nine pupils who make up her “little female academy” is widely recognized as the first full-length novel for children, and the first to be aimed specifically at girls. The daily experiences of Mrs. Teachum’s charges are interwoven with fables and fairy tales illustrating the book’s underlying principles, which draw on contemporary theories of education and virtue. As central to the history of the novel as it is to the development of children’s literature, The Governess is a pioneering work by one of the eighteenth century’s most respected women writers. This Broadview edition includes a critical introduction that places The Governess in its cultural and literary context; appendices include examples of eighteenth-century educational literature and selections from Fielding’s correspondence.', 'en', 2005, 242, 'http://books.google.com/books/content?id=zHAx97IJgKEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5975', 'accepted', 'Sarah Fielding', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 8 FROM public.book WHERE isbn13 = '9781551114125' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('21b99f85-0275-5f68-a7bd-277da7c15bec', '9781551116440', 'The Woman in White', 'VcVgyYHd3OMC', 'As the inscription on his tombstone reveals, Wilkie Collins wanted to be remembered as the “author of The Woman in White,” for it was this novel that secured his reputation during his lifetime. The novel begins with a drawing teacher’s eerie late-night encounter with a mysterious woman in white, and then follows his love for Laura Fairlie, a young woman who is falsely incarcerated in an asylum by her husband, Sir Percival Glyde, and his sinister accomplice, Count Fosco. This edition returns to the original text that galvanized England when it was published in serial form in All the Year Round magazine in 1860. Three different prefaces Collins wrote for the novel, as well as two of his essays on the book’s composition, are reprinted, along with nine illustrations. The appendices include contemporary reviews, along with essays on lunacy, asylums, mesmerism, and the rights of women.', 'en', 2006, 696, 'http://books.google.com/books/content?id=VcVgyYHd3OMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5976', 'accepted', 'Wilkie Collins', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 18 FROM public.book WHERE isbn13 = '9781551116440' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('04307b14-60ed-590d-9a01-43edc9995667', '9781551117225', 'The Hound of the Baskervilles', 'zxw4XAdXGRIC', 'The Hound of the Baskervilles (1901–02) is Arthur Conan Doyle’s most celebrated Sherlock Holmes adventure. At the end of the yew tree path of his ancestral home, Sir Charles Baskerville is found dead. Close by are the footprints of a gigantic hound. Called to investigate, Holmes seems to face a supernatural foe. In the tense narration of the detective’s efforts to solve the crime, Conan Doyle meditates on late Victorian and early twentieth-century ideas of ancestry and atavism, the possible biological determination of criminals, the stability of the British landed classes, and the place of the supernatural. Historical documents included with this fully-annotated Broadview edition help contextualize the novel’s debates and reveal its cultural and literary significance as a supreme instance of early detective fiction. Also included is the Conan Doyle short story “The Adventure of the Speckled Band.”', 'en', 2006, 300, 'http://books.google.com/books/content?id=zxw4XAdXGRIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
