INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fed62a78-6ae5-588c-9d7b-edda725307c8', '9781551665719', 'Shadows at Sunset', 'nkRCvWAooAcC', 'The house on Sunset Blvd. has witnessed everything from the infamous murder-sucide of a 50s starlet and her lover, to the drug-fueled commune in the 60s, to the anguish of its present owner.', 'en', 2000, 384, 'http://books.google.com/books/content?id=nkRCvWAooAcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
