INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('413c93c8-615f-56e1-9b3f-4958b24450b5', '9781551666723', 'The Thrill of Victory', 'C2xVHuhz6TQC', 'Finding everything she has worked for in jeopardy and her entire life hanging in the balance of a decision that she has only two weeks to make, Stevie Corbett puts her fate into the hands of journalist Judd Mackie, who is determined to expose her secrets to the world until he discovers the truth. Originally in paperback. 200,000 first printing.', 'en', 2003, 240, 'http://books.google.com/books/content?id=C2xVHuhz6TQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
