INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8141e9cc-58d3-579b-aba9-4297442a81d2', '9781551667430', 'Strange Bedpersons', 'Sq6qd12BjP4C', 'When she agrees to accompany her ex-boyfriend Nick Jamieson, a conservative Republican lawyer who is desperate to make partner, on a weekend business trip as his fiance, Tess Newhart, an outspoken woman of the world, discovers that opposites really do attact. Reprint.', 'en', 1994, 256, 'http://books.google.com/books/content?id=Sq6qd12BjP4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
