INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4c7f8f6d-4cdb-5d20-8f5d-bad5d155247e', '9781555533076', 'Louisa May Alcott on Race, Sex, and Slavery', '6g6kwxBDzxoC', 'Louisa May Alcott championed women''s causes in gothic tales of interracial romance and in newspaper articles published during the Civil War. Drawn from her service as a nurse in a Union hospital as well as from her radical abolitionist activities, these writings allow Alcott to comment boldly on unstable racial identities, interracial sex and marriage, armed slave rebellion, war, and the links between the bondage of slaves and the conditions of white womanhood. A comprehensive introduction situates Alcott and her family within the network of antebellum reformers and unmasks her personal and literary struggles with the boundaries of race, sex, and class.', 'en', 1997, 160, 'http://books.google.com/books/content?id=6g6kwxBDzxoC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
