INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f5f906a9-2b82-5963-978f-684f7ec8ecc5', '9781555837235', 'Stir-fry', '-wpAPgAACAAJ', 'Exhilerating...irreverent, and extremely funny, - Ms, Seventeen and sure of nothing, Maria has left her parents'' small-town grocery for university life in Dublin. An ad in the Student Union-2 FEMALE SYMBOL] seek flatmate. No bigots.-leads Maria to a home with warm Ruth and wickedly funny Jael, students who are older and more fascinating than she''d expected. A poignant, funny, and sharply insightful coming-of-age story, Stir-fry is a lesbian novel that explores the conundrum of desire arising in the midst of friendship and probes feminist ideas of sisterhood and nonpossessiveness. Emma Donoghue is the author of the forthcoming Slammerkin, Hood and Kissing the Witch . Born in Dublin, she now lives in Ontario, Canada. Stir-fry was her first novel. Also Available by Emma Donoghue Hood TP 11.95, 1-55583-453-1 CUSA', 'en', 1994, 240, 'http://books.google.com/books/content?id=-wpAPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '5990', 'accepted', 'Emma Donoghue', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 18 FROM public.book WHERE isbn13 = '9781555837235' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9bd49c14-24f9-586e-bfbf-ecae39e87fcf', '9781555916220', 'The Gonzo Way', '8MvUl2GH0KcC', 'The writer Tom Wolfe once described Hunter S. Thompson as the finest comic writer of the 20th century. Thompson was this and more, an apt observer of the American scene for almost four decades, the founding father of Gonzo journalism, and an inspiration to many. Through his writings, Thompson examined the loss of American innocence in the latter part of the 20th century, all the while holding up those deserving of contempt for closer examination and espousing (and exemplifying) what it meant to be a citizen at the end of the American Century. With his death, a vacuum was created that remains to be filled. Anita Thompson explores the legacy of her late husband as a writer and as a citizen, through her own words and through interviews with those who knew him best including Johnny Depp, Ed Bradley, Doug Brinkley, Jack Nicholson, Bill Murray, Senator George McGovern, and others.', 'en', 2007, 112, 'http://books.google.com/books/content?id=8MvUl2GH0KcC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
