INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1682bd00-d9c2-5ed1-a3d1-0742a9f9c6a9', '9781555973032', 'Some Ether', '1JxaAAAAMAAJ', 'Winner of a "Discovery"/The Nation Award Winner of the 1999 PEN/Joyce Osterweil Award for Poetry Some Ether is one of the more remarkable debut collections of poetry to appear in America in recent memory. As Mark Doty has noted, "these poems are more than testimony; in lyrics of ringing clarity and strange precision, Flynn conjures a will to survive, the buoyant motion toward love which is sometimes all that saves us. Some Ether resonates in the imagination long after the final poem; this is a startling, moving debut."', 'en', 2000, 85, 'http://books.google.com/books/content?id=1JxaAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
