INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('67cea308-41eb-5f2d-ac26-1bbf4644a834', '9781556432460', 'Your Inner Physician and You', 'sOZAMsCiz44C', 'The "inner physician" is that part of the psyche that can heal--when one becomes aware of the psycho-emotional issues that come with pain. Dr. Upledger describes his methods through personal accounts such as that from Mary Ellen Clark, the Olympic diver, whom he cured of dizziness.', 'en', 1997, 240, 'http://books.google.com/books/content?id=sOZAMsCiz44C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
