INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9394e5ac-eb5a-583d-9c1a-0163678f69d1', '9781556434242', 'A Saucer of Loneliness', 'amWBa48lb6AC', 'Kurt Vonnegut cites Theodore Sturgeon as the inspiration for his character Kilgore Trout. This volume includes 12 stories from 1953, considered Sturgeon''s golden era. Among them are such favorites as the title story, "The Silken-Swift," "A Way of Thinking," "The Dark Room," "The Clinic," and "The World Well Lost," a story known for being very ahead of its time in advocating gay rights.', 'en', 2002, 400, 'http://books.google.com/books/content?id=amWBa48lb6AC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
