INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('695e9df2-a911-5a13-9e85-78f244a280c5', '9781556523984', 'James Dean', 'CfiE4x4V_PAC', 'This is the book that restarted the James Dean cult by celebrating him as the cool, defiant visionary of pop culture who made adolescence seem heroic instead of awkward and who defined the style of rock ''n'' roll''s politics of delinquency. The only book to fully show how deliberately and carefully Dean crafted his own image and performances, and the product of still unequalled research, vivid writing, intimate photographs, and profound meditation, James Dean: The Mutant King has become almost as legendary as its subject.', 'en', 2001, 384, 'http://books.google.com/books/content?id=CfiE4x4V_PAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
