INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0313fb19-61d8-5c04-a6b6-e94a7571be48', '9781556525131', 'Women & Cats', 'wszOPQAACAAJ', '"This anthology of quotations, letters, poems, stories, and essay excerpts—delicately and elegantly illustrated with small silhouettes and old tinted photographs in sepia and pink—celebrates the love affair between women and cats. Insightful gems include “Of course, every cat is really the most beautiful woman in the room”; “Women and cats will do as they please and men and dogs should relax and get used to the idea”; and “Flirting, falling, and yawning anywhere, / Like women who want no contract.” Included are selections from Colette, Mark Twain, Eleanor Glyn, Fanny Kemble, Elizabeth Barrett Browning, Amy Lowell, Katherine Mansfield, Dorothy L. Sayers, Rosa Luxemburg, and Hedda Hopper."', 'en', 2003, 66, 'http://books.google.com/books/content?id=wszOPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
