INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a34730b1-13a9-56d2-ad1a-0d540057a30f', '9781556615429', 'Angel of the Outback', 'EzkFAAAACAAJ', 'Rachel Langley and Betsy Brady have fulfilled a seven-year transportation sentence in Australia. Weakened through years of servitude, they soon realize that freedom is a constant battle for survival. When Betsy is mysteriously murdered, Rachel flees for her own safety and finds refuge with Reverend Whitley. Her intent is to find Betsy''s murderer but her own life is in grave danger.', 'en', 1995, 319, 'http://books.google.com/books/content?id=EzkFAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
