INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2cd5ff13-b15f-5ba6-89aa-28e94a2d68f4', '9781557046864', 'The Sideways Guide to Wine and Life', '3MktAAAACAAJ', 'A lighthearted companion to the best-reviewed film of the year—a pocket-sized illustrated guide to the locations and wines featured in Sideways including maps, winery listings, tips for drinking wine, and Oscar®-winning dialogue. Yesterday, you didn''t know Pinot Noir from film noir. Now, after seeing the marvelous movie Sideways, you are living the life uncorked, and this is the perfect little book to celebrate your own sideways journey. Inside you will find: Wine recommendations, tips for tasting wine, and a list of bottles featured in the film Places and wineries to visit in the Santa Ynez Valley in Santa Barbara County that were featured in the movie Excerpts from the Oscar®-winning screenplay Web sites and information for planning your own trip. This hilarious and useful guide is fully illustrated in color with movie stills, location stills, and delightful drawings by artist Robert Neubecker, who created the film''s poster. Originally created as a specialty item for wineries and tourist sites, The Sideways Guide to Wine and Life has been featured widely in articles (USA Today, The New York Times, and Wine Spectator) about the Sideways phenomenon and the surge in Pinot Noir''s popularity across the country. Now available in an expanded trade edition for the first time, this is a terrific gift and countertop book year round.', 'en', 2005, 64, 'http://books.google.com/books/content?id=3MktAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6003', 'accepted', 'Alexander Payne; Jim Taylor', 'Performing Arts', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 12 FROM public.book WHERE isbn13 = '9781557046864' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b69021e5-8f08-5502-ba36-00827e1fd927', '9781557047410', 'The Namesake', 'nClcAAAACAAJ', 'Original essays and glorious photography, stunningly designed in this unique moviebook from the director of Monsoon Wedding and Vanity Fair—a Fox Searchlight release. In her essay "Writing and Film," the Pulitzer Prize-winning novelist Jhumpa Lahiri writes about the experience of seeing her novel "transposed" from paper to film. "Its essence remains, but it inhabits a different realm and must, like a transposed piece of music, conform to a different set of rules. . . . To have someone as devoted and as gifted as Mira reinvent my novel . . . has been a humbling and thrilling passage." Mira Nair''s essay, "Photographs as Inspiration," begins with the provocative comment: "If it weren''t for photography, I wouldn''t be a filmmaker." She explains how photographs help her crystallize the visual style of her films and which particular photos influenced her vision for The Namesake. These two essays, written exclusively for this Newmarket Pictorial Moviebook, introduce an amazing panoply of images of people and places shot mainly in New York and Calcutta during the making of the movie, accented by excerpts from Lahiri''s bestselling novel. Six Indian and American photographers'' works are represented. Brilliantly illuminating the immigrant experience and the tangled ties between generations, The Namesake tells the story of the Ganguli family, whose move from Calcutta to New York evokes a lifelong balancing act to adapt to a new world while remembering the old. The couple''s firstborn, Gogol, and sister Sonia grow up amid these divided loyalties, struggling to find their own identity without losing their heritage. Kal Penn (Harold & Kumar Go to White Castle, Superman Returns) stars as Gogol.', 'en', 2006, 144, 'http://books.google.com/books/content?id=nClcAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
