INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e8a1cc5b-2c2e-51a6-83d9-6f832f6f06ef', '9781557091031', 'George Washington''s Rules of Civility and Decent Behaviour', '2_UIAAAACAAJ', 'Copied out by hand as a young man aspiring to the status of Gentleman, the 110 precepts which make up this work were based on a set of rules composed by French Jesuits in 1595. The first English edition of these rules was available in Francis Hawkins'' Youths Behavior, or Decency in Conversation Amongst Men, which appeared in 1640, and it is from this work that George Washington seems to have copied. However much he may have simplified them, these precepts had a strong influence on Washington, who aimed to always live by them. The rules focus on self-respect and respect for others through details of etiquette and offer pointers on such issues as how to dress, walk, eat in public, and address one''s superiors.', 'en', 1989, 30, 'http://books.google.com/books/content?id=2_UIAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
