INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('416aac61-0949-55ab-9594-bb1716889e2e', '9781557280244', 'The Apple that Astonished Paris', '6mwhkMv4K9kC', 'Billy Collins strikes at the deepest concerns of the human heart and mind. His metaphysical wit and cosmic puzzlement, expressed always in a clean, direct, unpretentious idiom, will touch every reader who is fascinated by the play of a truly original imagination and a disarming way of seeing the world.', 'en', 1988, 61, 'http://books.google.com/books/content?id=6mwhkMv4K9kC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
