INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7e1cd750-a4a2-5f46-b873-efa8a248884c', '9781557424297', 'The Picture of Dorian Gray', '8_d2vgEACAAJ', 'A young man of rare beauty, Dorian Gray is the very picture of the ideal British gentleman. When he is drawn into a life of decadence and lustful indulgence, he discovers a painting begins to bear new marks for each of his sins, leaving him as youthful and attractive as ever. And so begins Dorian''s descent into a personal hell of lies, murder, and depravity.', 'en', 2005, 187, 'http://books.google.com/books/content?id=8_d2vgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
