INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4eedd4a4-6092-53ac-9bb6-343432910d8d', '9781557832450', 'Spring''s Awakening', '0fuhI9YwsdIC', '(Applause Books). Spring''s Awakening is a tragi-comedy of teenage sex. Its fourteen-year-old heroine, Wendla, is killed by abortion pills. The young Moritz, terrorized by the world around him, and especially by his teachers, shoots himself. The ending seems likely to be the suicide of Moritz''s friend, Melchior, but in a confrontation with a mysterious stranger (the famous Masked Man) he finally manages to shed his illusions and face the consequences.', 'en', 1995, 126, 'http://books.google.com/books/content?id=0fuhI9YwsdIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
