INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5f609ec5-276b-5b0e-ab35-74665349ab7e', '9781559210867', 'East Wind, West Wind', 'VPkAjwEACAAJ', 'In her acceptance speech upon receiving the Nobel Prize for Literature, Pearl Buck said, "The mind of my own country and of China, my foster country, are alike in many ways, but above all, in our common love of freedom." "East Wind: West Wind" embodies this love of, and struggle for, freedom.', 'en', 1930, 288, 'http://books.google.com/books/content?id=VPkAjwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
