INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('615ec44c-f7bf-56bb-81b9-85ccc2632819', '9781560251149', 'On the Bus', 'E_lCNQAACAAJ', 'The fabled 1964 cross-country bus trip of Ken Kesey & the Merry Pranksters-on a psychedelically painted school bus crammed with amplifiers, cameras, costumes, & assorted contraband as cargo & Beat legend Neal Cassady at the wheel-marked the irreversible end of the "Eisenhower Era," & set an American cultural revolution in motion. On the Bus, by Paul Perry, is a celebration of the unforgettable exploits of the Merry Pranksters, immortalized in Tom Wolfe''s bestselling book. In this engrossing popular history, the spirit of the era is captured in a remarkable living chronicle, combining analysis & history with colorful additional narrative by Kesey-sidekick Ken Babbs. It features over 100 never-before-seen photos by Prankster photographer Ron Bevirt, Allen Ginsberg, & others, alongside candid & insightful interviews with participants & leading countercultural figures. In addition to forewords by Hunter S. Thompson, Jerry Garcia, & Ken Kesey, On the Bus features commentary by Ron "Hassler" Bevirt, William S. Burroughs, Malcolm Cowley, Ram Dass, Lawrence Ferlinghetti, Jerry Garcia, Allen Ginsberg, Wavy Gravy, Denise "Mary Microgram" Kaufmann, Ken Kesey, Steve "Zonker" Lambrecht, Timothy Leary, Gordon Lish, Ed McClanahan, Gurney Norman, Lee Quarnstrom, Robert Stone, & Hunter S. Thompson.', 'en', 1996, 205, 'http://books.google.com/books/content?id=E_lCNQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6028', 'accepted', 'Paul Perry; Ken Babbs', 'Social Science', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 20 FROM public.book WHERE isbn13 = '9781560251149' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('588c29ed-abbb-5dd8-94b2-bd53be60f3be', '9781560252481', 'Requiem for a Dream', 'nSrOm1Yf1qIC', 'The acclaimed novel that inspired the Darren Aronofsky film--the story of three friends whose pursuit of wealth ends in addiction and tragedy. "To understand Selby''s work is to understand the anguish of America" (New York Times Book Review). Over twenty years after its first publication in 1978, Requiem for a Dream makes it to the big screen in a major motion picture starring Ellen Burstyn, Jennifer Connelly, Marlon Wayans, Jared Leto, and Christopher McDonald. Directed by Darren Aronofsky, the highly acclaimed director of Pi, the movie was released in November 2000. In this searing novel, two young hoods, Harry and Tyrone, and a girlfriend fantasize about scoring a pound of uncut heroin and getting rich. But their habit gets the better of them, consumes them and destroys their dreams.', 'en', 1999, 279, 'http://books.google.com/books/content?id=nSrOm1Yf1qIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
