INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('962162b3-67ab-5dbc-b7d8-77156efba910', '9781560254416', 'Expelled from Eden', 'Q_XQswEACAAJ', 'No stranger to living and writing on the edge, the author shares the fruits of his productive career as "the most prodigiously talented and historically important novelist under 35," including autobiographical writing, interviews, critical essays, correspondence, and poems.', 'en', 2004, 512, 'http://books.google.com/books/content?id=Q_XQswEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
