INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('591460cd-546e-5c07-b728-aab196a2cd72', '9781560257011', 'Pink Flamingos, and Other Filth', 'nNlBZApxhx8C', 'Here are three of the filthiest-and yet, in their own way, sweetest—screenplays ever written: Pink Flamingos, Desperate Living, and Flamingos Forever. Intermixed with the scripts are dozens of classic stills from the films. In Pink Flamingos, Waters''s muse and leading lady, Divine, a 300-pound cross-dresser who could turn your stomach in one scene and break your heart in the next, competes with her family for the title of "filthiest people alive"—as readers will see, it''s really anyone''s game. Desperate Living is a perverse fairy tale featuring gun-toting lesbians, leather-clad castle guards, and a repulsive queen who has her own daughter gang-raped among other atrocities. Flamingos Forever is the unproduced sequel to Pink Flamingos, set fifteen years after the original, when the rivalry for "filthiest people alive" is revived; it was never filmed, Waters tells us, because by the time it was written, too many of the original cast had died—this book is the only chance for Water''s fans to read it.', 'en', 2005, 258, 'http://books.google.com/books/content?id=nNlBZApxhx8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6032', 'accepted', 'John Waters', 'Performing Arts', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 12 FROM public.book WHERE isbn13 = '9781560257011' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5ad33fcd-6202-5057-9074-25f73eb104d0', '9781560258247', 'The Big Empty', '9oBpswEACAAJ', 'Questions are posed, writes Norman Mailer, "in the hope they will open into richer insights, which in turn will bring forth sharper questions." In this series of conversations, John Buffalo Mailer, 27, poses a series of questions to his father, challenging the reflections and insights of the man who has dominated and defined much of American letters for the past sixty years. Their wide-ranging discussions take place over the course of a year, beginning in July 2004. Set against the backdrop of George W. Bush''s re-election campaign and the war in Iraq, each considers what it means to live in America today. John asks his father to look back to World War II, and explore the parallels that can—and cannot—be drawn between that time and our current post-9/11 consciousness. As their conversations develop, the topics shift from the political to the personal to the political again, as they duck and weave around one another. They explore their shared admiration of boxing and poker, the nature of marriage and love, television, movies, writing, and what it means to be a part of this extraordinary family.', 'en', 2006, 218, 'http://books.google.com/books/content?id=9oBpswEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
