INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4c680788-0b36-55a5-8d91-d0965c0cff17', '9781560258506', 'Monster Island', 'BpsmiilnN-4C', 'It''s one month after a global disaster. Manhattan has become Monster Island after a plague has turned all its denizens into shambling, rotting animated corpses, except for a couple who have kept their intelligence and also acquired psychic powers. When a', 'en', 2006, 282, 'http://books.google.com/books/content?id=BpsmiilnN-4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
