INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('152657ea-3993-5ff9-9532-9b10c5fadd58', '9781561706600', 'Wokini', 'NikOAAAACAAJ', '"Wokini, " translated from Lakota, means "seeking a new beginning." On that theme, the famous athlete joins the bestselling author to blend modern therapeutic principles and Native American tradition.', 'en', 1990, 175, 'http://books.google.com/books/content?id=NikOAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
