INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cc4b141a-a1bf-53ab-9b6c-87e4ba4c2017', '9781563410901', 'Read my lips', 'rBDaAAAAMAAJ', 'Riki Anne Wilchins has written the book that may take the discussion of gender over the top. In a voice that is by turns outraged, outrageous, sad, and hilarious, Wilchins - cofounder of the Transexual Menace and Executive Director of GenderPAC - weaves theory and personal experience into a story of self-discovery. Lesbians, feminists, queer academics, activists, transpeople, the "queer-on-the-street," and mainstream readers hungry for writing that pushes the absolute edge of the gender envelope - Read My Lips will change the way you think about bodies, sex, and gender.', 'en', 1997, 288, 'http://books.google.com/books/content?id=rBDaAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
