INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d95bc536-de2b-5924-a278-22f1fa5dfb78', '9781563895166', 'Michael Moorcock''s Multiverse', 'iHZ5PQAACAAJ', 'This book is a sword and sorcery tale that expands upon the universe of the Eternal Champion made famous through novels and short stories. In a world of alternate universes and realities in which time and space often converge, the Eternal Champion is cursed to live multiple lives of eternal reincarnation. Caught in the war between the forces of Law and Chaos, his allegiance often changes as he fights for the preservation of balance. In three separate but intertwining tales of heroic fantasy, the Eternal Champion takes on the form of an enigmatic woman, a time-traveling detective, and an albino sorcerer as he searches for the elusive Silverskin and the secret which could end his cosmic battle forever.', 'en', 1999, 288, 'http://books.google.com/books/content?id=iHZ5PQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
