INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('97897ab7-34c7-5275-b705-6f86d8487d88', '9781563896002', 'The Invisibles', 'RE3BQgAACAAJ', 'Imagine if every paranoid fantasy, every conspiracy theory, every alleged cover-up and government deception, every tabloid story you''ve ever heard ...were true. Discover a world where paranoia is a survival skill and the only hope for mankind is a group of unconventional occultist freedom fighters-The Invisibles.', 'en', 2000, 224, 'http://books.google.com/books/content?id=RE3BQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
