INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ee67bdc1-2589-5c91-962b-b9cae57c3145', '9781564775009', 'Happy Endings', 'nrQAAAAACAAJ', 'A must for every quilter''s library, this is the classic book on finishing--back by popular demand! First published in 1987, this popular resource has sold more than 275,000 copies and is still the one quilters want. Well-known author and quiltmaking expert Mimi Dietrich shows you all you need to know about finishing quilts with style. Discover dozens of creative ways to finish your quilts, from easy to advanced Find terrific ideas for quilt backings, battings, bindings, and hanging sleeves Get creative with a great section on quilt borders Learn from Mimi Dietrich''s "Happy Ending Hints," sprinkled throughout the book Happy Endings: Finishing the Edges of Your Quilt teaches how to finish a quilt and is a recommendation for beginners and experienced quilters alike. New ideas cover quilt backings, battings, bindings and more, offering a new section on quilt borders and new creative ideas for finishing edges. Patterns, step-by-step color illustrations, and fun finishing techniques make for a fine collection of ideas perfect for any quilter who wants to produce polished borders and finishing touches. --Midwest Book Review, August 2013', 'en', 2003, 80, 'http://books.google.com/books/content?id=nrQAAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6072', 'accepted', 'Mimi Dietrich', 'Crafts & Hobbies', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 12 FROM public.book WHERE isbn13 = '9781564775009' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('38d73f17-3d0b-5cc1-8dc4-297c384fa0c2', '9781564780614', 'Letters', 'm0MZch4xxRIC', 'Basically, [Barth] takes several people from his early novels and has them all starting to write to each other, and to him, their letters and experiences directing the plot. And what starts out as what could be a too-cute literary trick winds up being extremely revealing, as the characters pour themselves into the letters, regardless of whom they''re writing to, as the plot skips and slips through time. On one level it acts as a sequel to those early novels, continuing their stories and although it''s not really required to read those books, I''m not going to pretend it doesn''t help. The best thing to do would be to read those old novels in one block and then move onto this ... I read them some years ago so I was a little fuzzy on the finer points. But I picked it up. But Barth captures the voices of his old characters well and even if you didn''t know who was writing what letter, you could tell. And thus they tell the recepient, and us, about their hopes and fears, they mingle together, they lie, they come unglued, and by the end you sort of get a tapestry of their thoughts. There''s a plot weaving through here but sometimes it becomes hard to connect it with six different people discussing different angles of it with you, but I just went with it and enjoyed the writing for what it was. --Michael Battaglia at Amazon.com.', 'en', 1994, 772, 'http://books.google.com/books/content?id=m0MZch4xxRIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6073', 'accepted', 'John Barth', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 17 FROM public.book WHERE isbn13 = '9781564780614' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f0c9cb8d-d62f-5701-af59-3d478e31184c', '9781564781314', 'Point Counter Point', 'i48OyQk9o7AC', 'Aldous Huxley''s lifelong concern with the dichotomy between passion and reason finds its fullest expression both thematically and formally in his masterpiece Point Counter Point. By presenting a vision of life in which diverse aspects of experience are observed simultaneously, Huxley characterizes the symptoms of "the disease of modern man" in the manner of a composer - themes and characters are repeated, altered slightly, and played off one another in a tone that is at once critical and sympathetic. First published in 1928, Huxley''s satiric view of intellectual life in the ''20s is populated with characters based on such celebrities of the time as D.H. Lawrence, Katherine Mansfield, Sir Oswald Mosley, Nancy Cunard, and John Middleton Murray, as well as Huxley himself. A major work of the 20th century and a monument of literary modernism, this edition includes an introduction by acclaimed novelist Nicholas Mosley (author of Hopeful Monsters and the son of Sir Oswald Mosley). Along with Brave New World (written a few years later), Point Counter Point is Huxley''s most concentrated attack on the scientific attitude and its effect on modern culture.', 'en', 2001, 432, 'http://books.google.com/books/content?id=i48OyQk9o7AC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6074', 'accepted', 'Aldous Huxley', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 0 FROM public.book WHERE isbn13 = '9781564781314' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a765c75d-c63a-5fd1-9e1e-5e92e0e50b15', '9781564781406', 'The Last Days', 'G8uW0BlvvtcC', 'The Last Days is Raymond Queneau''s autobiographical novel of Parisian student life in the 1920s: Vincent Tuquedenne tries to reconcile his love for reading with the sterility of studying as he hopes to study his way out of the petite bourgeoisie to which he belongs. Vincent and his generation are contrasted with an older generation of retired teachers and petty crooks, and both generations come under the bemused gaze of the waiter Alfred, whose infallible method of predicting the future mocks prevailing scientific models. Similarly, Queneau''s literary universe operates under its own laws, joining rigorous artistry with a warm evocation of the last days of a bygone world.', 'en', 1996, 250, 'http://books.google.com/books/content?id=G8uW0BlvvtcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6075', 'accepted', 'Raymond Queneau; Barbara Wright; Vivian Kogan', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 7 FROM public.book WHERE isbn13 = '9781564781406' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6afe7f05-bdc1-551b-851a-7673e965e659', '9781564782991', 'Heartsnatcher', 'T-wj9t353TAC', 'Boris Vian s early death robbed French literature of a novelist who was coherent while still modern. Heartsnatcher is an esoteric, surrealistic comedy about guilt, set in a deceptively familiar, almost ordinary locale. New Statesman', 'en', 2003, 245, 'http://books.google.com/books/content?id=T-wj9t353TAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6076', 'accepted', 'Boris Vian', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 2 FROM public.book WHERE isbn13 = '9781564782991' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4e3a4af1-bc4c-52b2-a368-e42a03f998eb', '9781564783950', 'The Review of Comtemporary Fiction - Future of Fiction', 'iEDYPQAACAAJ', 'The Review''s aesthetic focus has been called many things--postmodern, experimental, avant-garde, metafictional, subversive--but in bringing this aesthetic to a wider audience it also seeks to expose the artificial barriers that exist between and within cultures. To this end, The Review has a special affinity for the works of foreign writers who may otherwise go unread in the United States, as well as American writers whose work has gone unchampioned in their own country. An extensive book review section also covers recent works of innovative writing. Above all, The Review of Contemporary Fiction attempts to expand readers'' notions of what fiction is and what it can do.', 'en', 1996, 200, 'http://books.google.com/books/content?id=iEDYPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6077', 'accepted', 'John O''Brien; David Foster Wallace', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 2 FROM public.book WHERE isbn13 = '9781564783950' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a5362009-0575-5644-9024-35200b4f5e1e', '9781565041912', 'The Eternal Champion', 'Fo8RPwAACAAJ', 'Young and old, familiar fans and newcomers, will be captivated by Michael Moorcock''s legendary Eternal Champion collection. Timeless, classic and beyond a doubt one of the foundations of modern Fantasy, the Eternal Champion is a series of stories that no Fantasy aficionado should pass up. Includes The Eternal Champion, Phoenix in Obsidian, To Rescue Tanelorn and The Sundered Worlds.', 'en', 1996, 484, 'http://books.google.com/books/content?id=Fo8RPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6078', 'accepted', 'Michael Moorcock; Tom Canty', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 17 FROM public.book WHERE isbn13 = '9781565041912' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('58908e8f-5151-5af3-896f-9b06b9a46fe3', '9781565044043', 'Tales of Magick', 'gJbGPQAACAAJ', '"Kick Ass! And Live to Tell About It! Some people think the Awakened sit around dreaming about Ascension. Wrong. Dead wrong. When reality itself is on the brink of destruction, you don''t contemplate your navel. You fight -- and sometimes die -- for the sake of the future. Tales of Magick takes Mage from the realm of abstraction and kicks it screaming into high gear. If you ever wondered how to run an epic, exciting modern sorcery chronicle, Dark Adventure is for you. Indeed, Tales of Magick is an ongoing series of books dedicated to playing Mage in a variety of genres and settings. Now your Mage game can go anywhere, anywhen".', 'en', 1998, 96, 'http://books.google.com/books/content?id=gJbGPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6079', 'accepted', 'Phil Brucato; Aaron Rosenberg', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 12 FROM public.book WHERE isbn13 = '9781565044043' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c2accbc4-fd14-506a-8f1d-55f793c26677', '9781565047082', 'Changeling Storytellers Guide', '3sMLAAAACAAJ', 'The gates to Arcadia, the original paradise, are closed. Only the world of humanity remains. Without any awareness of our true nature, humankind crushes us beneath its banal heel. Joy and laughter are gone; only the Dreaming remains. We are changelings, the forgotten ones, neither fully fae nor wholly mortal. The last of our kind on Earth, we have built ourselves an invisible kingdom. We are everywhere, yet you have never seen us. We hide, not behind some fragile Masquerade, but in plain sight with the power of our Glamour. We exist within a real world of make-believe where "imaginary" things can kill and" "pretend" monsters are real. The Changeling Storytellers Guide picks up where the Changeling rulebook leaves off and offers a plethora of new information, from rules clarifications to new and advanced systems for handling fae magic -- and puts it all in the Storyteller''s hands. Included are new settings and new rules for expanding the boundaries of your Changeling chronicle.', 'en', 1998, 139, 'http://books.google.com/books/content?id=3sMLAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6080', 'accepted', 'Mark Hunter; Nancy Schultz-Yetter; Steve Kenson; Ian Lemke; Nicky Rea', 'Games', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 20 FROM public.book WHERE isbn13 = '9781565047082' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8f3b5e36-226c-5bdb-9209-06c7ccc45781', '9781565078321', 'Stormie', '3K7EjGtQ4aEC', 'When Catechism of the Catholic Church broke onto the N.Y. Times bestseller list, its astonishing success confirmed the overwhelming interest of Catholics and Protestants in understanding modern Catholicism. Has the recent openness among denominations affected Catholic teachings? In the new spirit of cooperation, is there any reason why Catholics and Protestants should remain divided? This powerful and insightful examination of the Catholic Church provides: a side-by-side comparison of Scripture with the first new worldwide Catholic catechism in 400 years a summary of how modern Catholicism views grace, works, and heaven 24 ways the Catholic plan of salvation still stands in contrast to biblical truth a balanced overview of how the authority structure of the Roman Catholic Church compares with that of the New Testament church an explanation of how participation in the Mass and other sacraments is inconsistent with faith in Christ as Savior Clear, accurate, significant information to know and share--The Gospel According to Rome', 'en', 1997, 192, 'http://books.google.com/books/content?id=3K7EjGtQ4aEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
