INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('69b05d96-708d-5bdf-9343-ed8143df6dda', '9781565121829', 'The Sharpshooter Blues', 'aPuE315HqaUC', 'The identity of the Sharpshooter becomes a central theme in a story that introduces such prospective characters as the owner of the local funeral parlor, an avid comic-book reader, a man who shoots refrigerators, and a boy who never grew up', 'en', 1997, 398, 'http://books.google.com/books/content?id=aPuE315HqaUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
