INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0d136d44-2347-5b9c-86f2-f2ea351c4d1b', '9781565124820', 'Hemingway and Bailey''s Bartending Guide to Great American Writers', 'xLpMD-3PqmAC', 'An original guide to cocktails and the literary life brings together classic cocktail recipes, literary history, and entertaining anecdotes about famous American literati, with excerpts from each writer''s work alongside a drink recipe, biographical sketch, and stories about life, literature, and drinking.', 'en', 2006, 100, 'http://books.google.com/books/content?id=xLpMD-3PqmAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
