INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0e55dbde-f787-5a8f-867f-cc1a844e7827', '9781565840089', 'The Truth about Columbus', '8ZDWHQAACAAJ', 'An historian sets the record straight on Columbus''s "discovery" of the Americas, using art and text to sum up recent revisionist thought and to debunk common myths about the European invader responsible for the deaths of thousands. Original.', 'en', 1992, 48, 'http://books.google.com/books/content?id=8ZDWHQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
