INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1560e43c-60c9-5df7-a28c-137b3f1e0ad3', '9781565844759', 'On Language', 'eDwaBQAAQBAJ', 'An attractive new edition of two of Chomsky''s most popular books on language - an ideal introduction to his pioneering work in modern linguistics. In Part I, Language and Responsibility, the legend discusses his political, moral and linguistic thinking via a series of interviews with French linguist Mitsou Ronat. In Part II, Reflections on Language, he explores the more general implications of his linguistic theories and the controversies among social scientists over fundamental questions of language.', 'en', 1998, 481, 'http://books.google.com/books/content?id=eDwaBQAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
