INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0323e5da-f10c-586e-8ccf-0dc5737474d9', '9781565846715', 'On the Edge of the New Century', 'MnROHAAACAAJ', '"On the Edge of the New Century" is the sequel to Eric Hobsbawm''s "The Age of Extremes", a serious and challenging historical analysis that became a bestseller. Hobsbawm''s book continues his "magisterial" ("The New York Times Book Review") analysis of the 20th century, and asks crucial questions about our inheritance from a century of conflict and its meaning for our future.', 'en', 2001, 192, 'http://books.google.com/books/content?id=MnROHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
