INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7bcda586-3180-59db-9334-19a997dab92b', '9781565847040', 'Dr. Seuss Goes to War', '2p2qDQAAQBAJ', 'For decades, readers throughout the world have enjoyed the marvelous stories and illustrations of Theodor Seuss Geisel, better known as Dr. Seuss. But few know the work Geisel did as a political cartoonist during World War II, for the New York daily newspaper PM. In these extraordinarily trenchant cartoons, Geisel presents "a provocative history of wartime politics" (Entertainment Weekly). Dr. Seuss Goes to War features handsome, large-format reproductions of more than two hundred of Geisel’s cartoons, alongside "insightful" (Booklist) commentary by the historian Richard H. Minear that places them in the context of the national climate they reflect. Pulitzer Prize–winner Art Spiegelman’s introduction places Seuss firmly in the pantheon of the leading political cartoonists of our time.', 'en', 2001, 272, 'http://books.google.com/books/content?id=2p2qDQAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
