INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('13ecd2f8-71e9-504a-babf-edae99253f85', '9781565849426', 'The Assassination of Julius Caesar', 'xApsWf5QAmoC', 'Parenti presents a story of popular resistance against entrenched power and wealth. As he carefully weighs the evidence in the murder of Caesar, he sketches in the background to the crime with fascinating detail about Roman society.', 'en', 2004, 276, 'http://books.google.com/books/content?id=xApsWf5QAmoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
