INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1e833f45-c1ea-58ab-b147-395a8b94b447', '9781565849655', 'Interesting Times', 'EgEMvgAACAAJ', 'Eric Hobsbawm has been widely acclaimed as one of the greatest living historians. Called "a lyrical, pungent, and provocative memoir” by Publishers Weekly, Interesting Times offers a personal tour through what Hobsbawm terms "the most extraordinary and terrible century in human history.” The book takes us from his birth in Alexandria, Egypt, and early schooling in Weimar Berlin to his student days as a Cambridge Red and Apostle at King’s College. Hobsbawm took E.M. Forster to hear Lenny Bruce, demonstrated with Bertrand Russell against nuclear arms, translated for Che Guevara in Havana, and inaugurated the modern history of banditry. With Interesting Times, we see the making of one of the Left’s most important intellectuals, and the history of the twentieth century through the unforgiving eye of one of its most intensely engaged participants.', 'en', 2005, 448, 'http://books.google.com/books/content?id=EgEMvgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
