INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('95cae9dc-9b56-5b69-abc4-f475ee5589dc', '9781566630184', 'After Many a Summer Dies the Swan', '7V2IreCUUF0C', 'Jo Stoyte, an unscrupulous and self-indulgent Hollywood tycoon, launches a search for the man who has discovered immortality', 'en', 1993, 368, 'http://books.google.com/books/content?id=7V2IreCUUF0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
