INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8c4161b8-fd0e-5f04-95c8-d98ebd533678', '9781566633949', 'Complete Essays', 't1EfzQEACAAJ', 'The fourth of six volumes collects essays that British social critic Huxley (1894-1963) wrote during a period that witnessed Germany''s Anschluss with Austria, the Sudeten crisis, intensifying violence in the Spanish Civil War, Stalin''s purges, Japan''s invasion of China, and Mussolini''s Ethiopian war. The collection includes all his published essays, in their latest version, and a selection of shorter reviews and brief occasional pieces.', 'en', 2001, 416, 'http://books.google.com/books/content?id=t1EfzQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
