INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a08cc0ce-ba70-519b-bf52-8e40cfd7486f', '9781566915908', 'Foghorn Outdoors Pacific Northwest Hiking', 'C7V1GwAACAAJ', 'This complete guide explores more than 1,000 of the best hikes in Washington and Oregon, with details on treks through Mount Rainier National Park, the Columbia River Gorge, the Olympic Peninsula, and a wealth of hikes within easy reach of Seattle and Portland. Trail maps, photos, & illustrations.', 'en', 2005, 912, 'http://books.google.com/books/content?id=C7V1GwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
