INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e57a8d0c-d778-5249-84ed-43cc3d4a88f0', '9781567430288', 'Zora neale Hurston', 'BfhnQgAACAAJ', 'Zora Neale Hurston(1891 -- 1960) Of the various signs that the study of literature in America has been transformed, none is more salient than is the resurrection and canonization of Zora Neale Hurston. Twenty years ago, Hurston''s work was largely out-of-print, her literary legacy alive only to a tiny, devoted band of readers who were often forced to photocopy her works if they were to be taught ... Today her works are central to the canon of African-American, American, and Women''s literatures ... The author of four novels, Jonah''s Gourd Vine (1934), Their Eyes Were Watching God (1937),Moses, Man of the Mountain (1939), and Seraph on the Suwanee (1948); two books of folklore -- Mules and Men (1935) and Tell My Horse (1938); an autobiography, Dust Tracks On a Road (1942); and over 50 short stories, essays, and plays, Hurston was one of the most widely acclaimed Black authors for the two decades between 1925 and 1945. -- from the Preface by Henry Louis Gates, Jr.', 'en', 2000, 238, 'http://books.google.com/books/content?id=BfhnQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6106', 'accepted', 'Henry L. Gates', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 18 FROM public.book WHERE isbn13 = '9781567430288' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ae85f7bc-876d-5cf3-8061-501321e8b253', '9781567921571', 'Things', 'Ia9-dneCWcwC', 'Two trailblazing novels by Georges Perec, Things: Jerome and Sylvie, the young upwardly mobile couple, lust for the good life. They wanted life''s enjoyment, but this equated to ownership. A Man Asleep: A nameless student attempts to purify himself entirely of material desires and ambitions.', 'en', 1990, 221, 'http://books.google.com/books/content?id=Ia9-dneCWcwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6107', 'accepted', 'Georges Perec; David Bellos', 'Comics & Graphic Novels', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 16 FROM public.book WHERE isbn13 = '9781567921571' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5b23909d-aca4-548f-a1ad-216974d73c73', '9781567921588', 'W, Or, The Memory of Childhood', 'vuN10GmOHD0C', 'Guaranteed to send shock waves through the literary community, Perec''s W tells two parallel stories. The first is autobiographical, describing the author''s wartime boyhood. The second tale, denser, more disturbing, more horrifying, is the allegorical story of W, a mythical island off Tierra del Fuego, governed by the thrall of the Olympic "ideal," where losers are tortured and winners held in temporary idolatry. As the reader soon discovers, W is a place where "it is more important to be lucky than to be deserving," and "you have to fight to live ... ÃwithÂ¨ no recourse, no mercy, no salvation, not even any hope that time will sort things out." Here, sport is glorified and victors honored, but athletes are vilified, losers executed, stealing encouraged, rape common, and violence a fact of life. Perec''s interpretive vision of the Holocaust forces us to ask the question central to our time: How did this happen before our eyes? How did we look at those "shells of skin and bone, ashen faced, with their backs permanently bent, their eyes full of panic and their suppurating sores?" How did all of this happen, not on W, but before millions of spectators, some horrified, some cheering, some in-different, but all present at the games watching the events of that grisly arena?', 'en', 2003, 176, 'http://books.google.com/books/content?id=vuN10GmOHD0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6108', 'accepted', 'Georges Perec', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 11 FROM public.book WHERE isbn13 = '9781567921588' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('25d2142c-1630-53ba-818b-d8be0ca6eb79', '9781567921892', 'The Woman in Black', 'Io65k_1MmQ8C', '1986 Set on the obligatory English moor, on an isolated cause-way, the story stars an up-and-coming young solicitor who sets out to settle the estate of Mrs. Drablow. Routine affairs quickly give way to a tumble of events and secrets more sinister than any nightmare. This first-class thriller - lately reincarnated on the stage - is a brilliant exercise in controlled horror. A real spine-tingler by a real master.', 'en', 2002, 138, 'http://books.google.com/books/content?id=Io65k_1MmQ8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
