INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('683b3dce-4a2c-5b68-b99f-d58203e48d0a', '9781567922691', 'Selected Poems of Herman Melville', '2rhlAAAAMAAJ', '"First published in 1970, Warren''s edition remains the most comprehensive selection of Melville''s poetry ever presented. It brings together the best of the Civil War poems from Battle-Pieces (1866), the portraits of sailors from John Marr (1888), and the autumnal lyrics from Timoleon (1891), as well as poems uncollected during Melville''s lifetime. Central to the selection are several self-contained passages from Clarel: A Poem and Pilgrimage to the Holy Land (1876), a book-length work that Warren calls "an important document of our modernity ... in fact, a precursor to The Waste Land, with the same central image, the same flickering contrasts of the past and the present, the same charade of belief and unbelief."" "Warren introduces his selection with a valuable interpretive essay, and also provides copious textual and critical notes."--BOOK JACKET.Title Summary field provided by Blackwell North America, Inc. All Rights Reserved', 'en', 2004, 512, 'http://books.google.com/books/content?id=2rhlAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
