INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e44ab4b1-9e89-59d3-8af1-144da61f89dc', '9781568363561', 'The Last Shogun', 'b_7ZdfGzHFsC', 'Yoshinobu, a seventeen-year-old boy emperor, was brought back from the secluded Imperial Palace in Kyoto, and "during a year of frenetic activity, he overhauled the military systems, reorganized the civil administration, promoted industrial development, and expanded foreign intercourse," and then capitulated to assure a peaceful transfer of sovereignty when the shogunal armies were defeated.--Jacket.', 'en', 2004, 256, 'http://books.google.com/books/content?id=b_7ZdfGzHFsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
