INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0b42c848-10eb-59d6-9b6e-65fcc00ec78d', '9781568821177', 'Song of Cthulhu', 'uXhlAAAAMAAJ', 'At the heart of the universe, the court of the blind idiot god Azathoth dances to the insane piping of demonic flute-players. The sinister music resounds across space and time, blasting the minds and ripping the souls of those who hear it. It is the melody of chaos, the sound of madness, the song of Cthulhu. This book includes nineteen stories and one essay, linked together by the alien and terrible music of the spheres.', 'en', 2001, 211, 'http://books.google.com/books/content?id=uXhlAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
