INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('69c95445-2c8c-59b1-b3c2-c4fa99b038ae', '9781568821405', 'Miskatonic University', 'kySWAAAACAAJ', 'A sourcebook detailing the campus, courses, students and personnel of one of the world''s most prestigious institutions of deeper learning. Filled with data on various University departments and professors, this book weaves the details drawn from Lovecraft''s Mythos tales with the Call of Cthulhu game background to create an indispensible sourcebook.', 'en', 2005, 242, 'http://books.google.com/books/content?id=kySWAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
