INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('db30aa12-f426-5510-b991-2618e1790d2e', '9781568821443', 'The Keeper''s Companion', '659r23-K96sC', '[CALL OF CTHULHU ROLEPLAYING] "The Keeper''s Companion" is an invaluable resource for gamemasters. The material includes advice for new keepers, a lengthy study of Mythos artifacts, a learned discussion of many occult books, an up-to-the-moment description of every facet of forensic medicine, a thorough revision and expansion of the game skills (including nearly two dozen new ones), and the entire text of "The Keeper''s Compendium," somewhat updated -- forbidden books, secret cults, alien races, and mysterious places. Additional short essays and features round out this book -- more than 100,000 words!', 'en', 2000, 208, 'http://books.google.com/books/content?id=659r23-K96sC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
