INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('76b04b4f-89c6-58c5-a239-e0da7d19be5a', '9781568821481', 'Call of Cthulhu RPG', 'Db4GAAAACAAJ', 'Ordinary people are confronted by the terrifying beings and forces of the Cthulhu Mythos. Players portray investigators of things unknown and unspeakable. Except for dice, everything needed for play is included in this book. Call of Cthulhu includes extensive background about H. P. Lovecraft, one-stop investigator creation, dozens of skills, three eras of play (1890s, 1920s, and present-day), over 200 Mythos creatures and spells, ready-to-play investigators, expanded weapons data from all three eras, four complete scenarios, and essays on the Necronomicon, Forensic Pathology, and the Dreamlands.', 'en', 2000, 288, 'http://books.google.com/books/content?id=Db4GAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6122', 'accepted', 'Sandy Petersen; Lynn Willis', 'Games', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 5 FROM public.book WHERE isbn13 = '9781568821481' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5dbb309a-11f2-5771-a309-e2926dc21dde', '9781568821740', 'Shadows of Yog-Sothoth', '1aIDAAAACAAJ', 'A Campaign for Call of CthulhuThe Silver Twilight is a secretive, international order dedicated to the destruction of the human race. As brave investigators, you must piece together passages from esoteric books, shards of strange artifacts and puzzling letters to discover the Silver Twilight''s loathsome goals.Shadows of Yog-Sothoth is a modestly-sized campaign of seven scenarios. During the course of play the investigators penetrate the outer layers of a secret sinister occult organization led by the lords of the Silver Twilight. Beginning in Boston they investigate an organization in New York, run afoul of a coven in Scotland, roam the desert of the American southwest, vacation off the coast of Maine, and explore the mysteries of the South Pacific.In addition to the campaign, this book includes two bonus scenarios. The People of the Monolith introduces the mysteries of the Cthulhu Mythos, and no harm can come to the investigators except through insanity. As such, is perfect for introducing new players to the wonders of Call of Cthulhu.The other bonus scenario, The Warren, presents and unsettling challenge for even experienced players.Originally published in 1982, this new edition includes modified episode scene changes, player-handouts guide for the keeper, and new illustrations and diagrams. It is 144 pages, perfect-bound, illustrated with an index.CHAPTERSThe Hermetic Order of the Silver TwilightLook to the FutureThe Coven of CannichDevil''s CanyonThe Worm that WalksThe Watchers of Easter IslandThe Rise of R''lyehBONUS ADVENTURESThe People of the MonolithThe WarrenDELUXE HANDOUTS', 'en', 2004, 180, 'http://books.google.com/books/content?id=1aIDAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
