INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ba76a51c-6380-5303-9f8c-68acd65be6db', '9781568821801', 'Secrets of New York', 'xUNYAAAACAAJ', 'It is the City that Never Sleeps. During the day ships, barges, tugs, and pleasure boats ply New York''s bay and rivers, dashing beneath bridges and disgorging thousands of people upon the city''s shores. Each brings hope and dreams of a new life. At night the city blazes with myriad lights, diamonds dazzling in buildings that scrape the sky. Music, food, dance, dark rituals, and clandestine cults flourish beneath the mantle of New York City.', 'en', 2005, 180, 'http://books.google.com/books/content?id=xUNYAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
