INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6b90456a-56c2-5e00-b587-41f40f7ca2b7', '9781568821863', 'The Keeper''s Companion, Vol. 2', '5PfnPQAACAAJ', 'New to Call of Cthulhu? A battle-scarred veteran of many campaigns? Here are essential background articles useful to most keepers.', 'en', 2002, 170, 'http://books.google.com/books/content?id=5PfnPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
