INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7b792de7-18d9-5074-b3d3-c86209d24ff5', '9781568821870', 'Secrets of San Francisco', 'RUT9PAAACAAJ', 'This resource guide provides background for a campaign setting in the San Francisco Bay area of the 1920s, including urban geography, civic history, and research venueswhere San Franciscans go when they break the law, go insane, or dieand sights, sounds, and secrets of a city that make it unique. It is more than a metropolis, it is a living entity whose unique character and changeable nature shape its atmosphere, its institutions, and its leading citizens. It is an excellent location from which to launch campaigns focusing on the Orient, and it possesses abundant research resources and outr locales for scenarios within its extensive boundaries, including the largest, oldest American enclave of Chinese settlers, the worlds most famous haunted house, and two of the most infamous prisons ever erected. Here is a complete a portrait of San Francisco in the 1920s, with careful attention to the vast body of local folklore and unique opportunities for Mythos investigation.', 'en', 2006, 189, 'http://books.google.com/books/content?id=RUT9PAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
