INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4db010d8-2b69-50f5-ab97-9f37cc83aa85', '9781568984957', 'Yours in Food, John Baldessari', 'FtnNdQaQtI4C', 'In John Baldessari''s new book, Yours in Food, the founding member of the conceptual art movement explores America at the table, savoring the nuances of breaking bread in carefully composed vignettes culled appropriated video and film. Reflections on food and eating specially commissioned from a smorgasbord of contemporary writers on culture and the arts, from novelist David Eggers to musician David Byrne, offer up the perfect accompaniment to Baldessari''s work. Paired with his images, these humorous, insightful, and, in some cases, bizarre meditations investigate one of the most fundamental and telling of all human experiences. A visual and intellectual feast, Yours in Food is sure to entertain and delight readers of fiction, art history, and cultural criticism and all lovers of food. A Blind Spot Book published by Princeton Architectural Press.', 'en', 2004, 144, 'http://books.google.com/books/content?id=FtnNdQaQtI4C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
