INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('01f4810c-aa1d-5d67-a7fa-4569b0599267', '9781569471241', 'Robert Van Gulik', '0ZIrAAAAYAAJ', 'Born in Holland in 1910 but raised in Java, Robert Hans van Gulik explored esoteric Buddhism and translated ancient texts, including an authentic Chinese 16th century detective novel, around which he created a fictional series. Based on extensive research, renowned author Janwillem van de Wetering, whose life and career parallels that of his subject, examines van Gulik''s life and work.', 'en', 1987, 149, 'http://books.google.com/books/content?id=0ZIrAAAAYAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
