INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a6326553-fc8e-5f8c-a930-fbe112e518b9', '9781569473337', 'White Sky, Black Ice', 'zl9qofe2FjQC', 'Alaska State Trooper Nathan Active must figure out what connects a death on a remote Arctic lake with a year-old fatal plane crash in the Brooks Range and a fire at the Chukchi Recreation Center that killed eight people, including the town''s basketball star. The case turns out to involve a lucrative polar bear poaching operation and the intense bond between a brother and sister from the village of Cape Goodwin. The heart of the matter, he discovers, is a dead woman whose killer remembers her as having a mouth so sweet ''it was like kissing a Hershey bar''.', 'en', 2003, 284, 'http://books.google.com/books/content?id=zl9qofe2FjQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
