INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c3ef7f80-94c5-5466-bf29-60bc02a5fa21', '9781569550342', 'Restless Till We Rest in You', 'nREGAAAACAAJ', '"Restless Till We Rest in You" features spiritual pearls from the works of St. Augustine (354-430 A.D.), including his "Confessions" and "The City of God", as well as rich insights from his homilies, especially those based on John''s Gospel and epistles. As part of the "Saints Speak Today Series", this title features 60 daily readings, along with scripture passages and hymns.', 'en', 1998, 158, 'http://books.google.com/books/content?id=nREGAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
