INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c4ab18f0-9052-5d34-8b26-28e2f958d76f', '9781569709085', 'The Art of Loving', 'wEs_AAAACAAJ', '"What''s the greatest happiness one can know in love? For Yutaka, there is only one answer: sex. To him, happiness and lust are the same thing. The likeable and respectable heir to the wealthy Fujiwara family is being torn inside-out by repressed physical desires. Then one day, Tohno, a transfer student, shows up at school. Yutaka sees Tohno as the ''toy'' that will make real all his desires and debauched fantasies. A life-long friendship based on trust and gratitude--will it all be shattered when Tohno learns the truth about Yutaka''s obsession?"--P. [4] of cover.', 'en', 2006, 184, 'http://books.google.com/books/content?id=wEs_AAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
