INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8bf3d51c-35ce-55f5-9009-b904acd059d1', '9781569719367', 'Creatures of the Night', 'REcJAAAACAAJ', 'From the New York Times best-selling author Neil Gaiman comes this collection, featuring two magical and disturbing stories lushly adapted to comics by veteran painter Michael Zulli (The Last Temptation). Rewritten by Gaiman for this graphic novel, these two ominous stories from the author’s award-winning prose work Smoke and Mirrors: Short Fictions and Illusions feature animals and people not being quite what they seem. In "The Price," a black cat like a small panther arrives at a country home and is soon beset by mysterious and vicious wounds. What is he fighting every night that could do this, and why does he persist? "The Daughter of Owls" recounts an eerie old tale of a foundling girl who was left with an owl pellet as a newborn on the steps of the Dymton Church. She was soon cloistered away in a local convent, but by her fourteenth year word of her beauty had spread—and those who would prey upon her faced unforeseen consequences.', 'en', 2004, 46, 'http://books.google.com/books/content?id=REcJAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6147', 'accepted', 'Neil Gaiman; Michael Zulli; Todd Klein', 'Comics & Graphic Novels', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 5 FROM public.book WHERE isbn13 = '9781569719367' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('af451011-3b64-5ce3-93c0-1780176dc811', '9781569719602', 'The Will Eisner Sketchbook', 'aEMKAAAACAAJ', 'For most of the 20th century, the work of cartoonist and graphic novelist Will Eisner defined the art of comic book storytelling in the U.S. and throughout the world. Still prolific today at the age of 86, Eisner is the embodiment of "living legend" in the world of comic books, continuing to produce some of the most innovative and influential work in the medium. This all-new hardcover collection of Eisner''s gorgeous pencil sketches and groundbreaking designs is a must-have for pop-culture enthusiasts and fans of comic books. Culled from many decades'' worth of work, the Sketchbook presents the world as seen through Will Eisner''s eyes, with introductory notes for each of the eleven different sections. From his observations of his friends and loved ones hustling through their busy daily lives to witnessing those quiet moments when no one is supposed to be watching, Eisner''s keen perception and steadfast hand capture the essence of what it means to be alive.', 'en', 2003, 200, 'http://books.google.com/books/content?id=aEMKAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
