INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('39503842-bba8-585e-b6fa-2b8e00ca0778', '9781569755662', 'Dirty Italian', 'tSfmBQAAQBAJ', 'GET D!RTY Next time you’re traveling or just chattin’ in Italian with your friends, drop the textbook formality and bust out with expressions they never teach you in school, including: *Cool slang *Funny insults *Explicit sex terms *Raw swear words Dirty Italian teaches the casual expressions heard every day on the streets of Italy: What''s up? Come va? He''s a real hottie. Lui è proprio un figo. This pizza''s awesome! Questa pizza è buonissima! I''m totally wasted. Soo sbronzo. I gotta piss. Devo pisciare. Hey ref, you''re an asshole! Arbitro cornuto! Wanna do it doggy-style? Lo facciamo alla pecorina?', 'en', 2006, 163, 'http://books.google.com/books/content?id=tSfmBQAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
