INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3cba9c70-1019-509e-a084-bb3a64250449', '9781570671814', 'Monday Night Class', '1PkcPQAACAAJ', 'Monday night class, held in San Francisco, was a popular venue "taught" by Stephen Gaskin with 2,000 people attending weekly by 1970. During these historic meetings the laws that governed the spiritual plane were explored--interpreted through the visions of the 60s generatoin with humor and affection. This new edition is a collection of the original transcripts with new commentary by Stephen from today''s perspective.', 'en', 2005, 191, 'http://books.google.com/books/content?id=1PkcPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
