INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6057599a-1498-5c69-b79e-92abbbd0d6a0', '9781570754364', 'Mother Maria Skobtsova', '2vLYAAAAMAAJ', 'A collection of writings that reflect the deep commitment to the gospel mandate that unites love of God and love of neighbor comes from the modern saint and Orthodox nun (1891-1945) who made her home in Paris a haven for Jews during Nazi occupation, a cause for which she gave her life in a concentration camp. Original.', 'en', 2003, 192, 'http://books.google.com/books/content?id=2vLYAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
