INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('74e274d5-65b0-555d-ab03-f95384dd961c', '9781572307025', 'Persuasive Communication', 'YnXk9Txuov0C', 'This popular text provides a comprehensive introduction to the study of persuasive messages and their effects. Concepts and methods from communication and social psychology are seamlessly integrated to give students a solid grasp of foundational issues in persuasion research, the core features of persuasive transactions, and major models of persuasive communication. Distinguished by its clear organization and wealth of concrete examples, this is an ideal text for advanced undergraduate- and graduate-level courses for students with a basic understanding of quantitative research methods.', 'en', 2002, 351, 'http://books.google.com/books/content?id=YnXk9Txuov0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
