INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f0aac8aa-04a1-58b9-ae17-7a27878223f1', '9781572308688', 'Africa South of the Sahara, Second Edition', 'TY4KTgbYnl0C', 'This authoritative text provides a broad introduction to the geography of Africa south of the Sahara. Exploring contemporary issues without losing sight of their historical roots, the volume analyzes the sociocultural, political, economic, and environmental processes that shape resource use and development in this rapidly changing region. Students gain a balanced view of the continent’s trials and triumphs—from postcolonial political strife and the devastating impact of HIV/AIDS to progress toward democratization and sustainable growth.', 'en', 2004, 479, 'http://books.google.com/books/content?id=TY4KTgbYnl0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
