INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('773f001e-69ed-5e0c-a4ef-ac9cf90b3b3b', '9781573456630', 'Stone Tables', 'WX_FNwAACAAJ', 'In this imaginative and vivid interpretation of the story of Moses, Orson Scott Card portrays the conflicts, the relationships, and the trials that drove one man from greatness to despair and back to greatness of a very different sort. The epic tale also traces the journey of a people destined to find their way out of slavery and sin to the light of Jehovah. A moving story of faith and uncertainty, political intrigue and personal jealousy, rebellion and submission. Stone Tables is both a gripping adventure and a brilliant study of human nature.', 'en', 2000, 448, 'http://books.google.com/books/content?id=WX_FNwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
