INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fddb9b32-ff7d-5b57-8f8b-0a8fbb0043ef', '9781574231007', 'Thus Spake the Corpse', 'ahrE0Prmge0C', 'Andrei Codrescu''s infamous anti-literary magazine Exquisite Corpse became a prime site of engaged dialogue in the stormy decade of its existence. Taking its name from Surrealism, the Corpse became the home of rebellion, passion, polemic, black humour, sedition, and all points between the front lines and back alleys of contemporary culture. In this text, Codrescu and Rosenthal resurrect the best essays and poems from Carl Rakosi, James Purdy, Joel Oppenheimer, Robert Creeley, Tom Clark and other members of America''s vibrant and eclectic avant-garde.', 'en', 1999, 417, 'http://books.google.com/books/content?id=ahrE0Prmge0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
