INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dfbd943b-fdec-5017-b7bd-c9e9346cbbd2', '9781577312055', 'The Gift', 'zSl9AAAAQBAJ', 'A renowned psychic argues that being psychic is a gift of the spirit we all have, and dispels the fears many people carry about psychics, answering such questions as "Can I be Christian and a psychic?" and "Is there any danger in opening yourself up to psychic information?" Original.', 'en', 2003, 160, 'http://books.google.com/books/content?id=zSl9AAAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
