INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7616f30e-2220-5314-b79e-4662f015cb0e', '9781577314035', 'Myths of Light', 'OWdqt29UDGYC', 'This previously unpublished title shows Campbell''s remarkable mind engaged with a favorite topic, the myths and metaphors of Asian religions. The book collects seven lectures and articles ranging from the ancient Hindu Vedas to Zen koans, Tantric yoga, and the Tibetan Book of the Dead. Campbell conveys complex insights through warm, accessible storytelling, revealing the intricacies and secrets of his subjects with his typical enthusiasm.--From publisher description.', 'en', 2003, 224, 'http://books.google.com/books/content?id=OWdqt29UDGYC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
