INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ddca6185-2a80-5b2a-a1b0-3177bd7bf05b', '9781577782087', 'Live Like a Jesus Freak', 'GKpbkU6DHE0C', 'Spend Today As If It Were Your Last For those who''ve read Jesus Freaks, this book is the next step. Focusing on life application, the book features practical ideas for putting faith to work, challenging questions for deepening your life, and readings that will help you sustain your passion. Live Like a Jesus Freak defines what it means to believe, pray, worship, study, love, stand, forgive, rejoice, serve, and witness like a true Jesus Freak!', 'en', 2001, 184, 'http://books.google.com/books/content?id=GKpbkU6DHE0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
