INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('040f718f-1c79-576e-8b10-1350e7ea6dc4', '9781578067046', 'Conversations with Don DeLillo', 'nIOdBrl1keUC', 'In a collection of profiles and conversations from 1982 to 2001, renowned novelist Don DeLillo, the author of White Noise and Libra, shares his thoughts on the distinction between historical fact and the creative imagination, his work habits, our media-saturated culture, baseball, Lee Harvey Oswald, the novelist''s role in the world, and other topics. Simultaneous.', 'en', 2005, 183, 'http://books.google.com/books/content?id=nIOdBrl1keUC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
