INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('383bb383-afb8-5b9c-a72f-21018ce4fb52', '9781578562589', 'Having a Mary Heart in a Martha World', 'IBkmI6dd-ZQC', 'A guide for women who struggle between a longing for a deeper spiritual life and the demands of their daily responsibilities offers practical advice on how to balance work and worship, offers guilt-reducing reassurance, and explains how readers can experience less stress and greater joy while strengthening their service. Reissue.', 'en', 2000, 256, 'http://books.google.com/books/content?id=IBkmI6dd-ZQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
