INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1081e697-1b97-5093-8dd0-aacee9195f47', '9781579126247', 'The A.B.C. Murders', 'rkc0_G_ULg4C', 'A is for Ascher, cudgeled in Andover. B is for Barnard, strangled in Bexhill. C is for Clarke, struck down in Churston. Beside each body is an A.B.C. Railway guide; before each murder Hercule Poirot is notified. In one of Christie''s most twisted tales, the meticulous Belgian sleuth must navigate the eerie maze of a serial killer''s mind. D is for Doncaster, where the next victim dies... E is for evidence, ingeniously analyzed.', 'en', 1936, 252, 'http://books.google.com/books/content?id=rkc0_G_ULg4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
