INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ed888751-339e-56aa-aab7-b1145df8d6e6', '9781580051880', 'Homelands', 'f-EEAQAAIAAJ', 'This beautifully complex collection of essays weaves together many different perspectives of "homeland," including belonging, longing, and exile, and features contributions from Etel Adnan, who chose to leave Beirut during wartime, and Agate Nesaule, who left Latvia under Nazi and Soviet threats. Original.', 'en', 2006, 343, 'http://books.google.com/books/content?id=f-EEAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
