INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('31f51c88-d6e6-53f3-aea2-def5822096ea', '9781580420815', 'Doyle Brunson''s Super System', 'xUB9hJqSxI8C', 'Twice-world champion and Hall of Famer Doyle Brunson and five leading experts in their various specialties tell you when to raise, call, bet, and fold at hold ''em (limit and no-limit), 7-stud (high and low), draw poker, and lowball. Collaborators David "Chip" Reese, Mike Caro, David Sklansky, Joey Hawthorne, and former world champion Bobby Baldwin. This treatise on professional-level poker is the result of over 10,000 hours of labor by the world''s greatest players and theorists and has never been equaled in scope or value. This is the must-have book for serious poker players.', 'en', 2002, 605, 'http://books.google.com/books/content?id=xUB9hJqSxI8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
