INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6302bd01-aa8b-5766-814d-abf1ce10241f', '9781580495790', 'A Christmas Carol', 'oWYO1uH9mmcC', 'This Prestwick House Literary Touchstone Edition includes a glossary and reader''s notes to help the reader fully appreciate the beauty and humor of Dickens''s work.In his "Ghostly little book," Charles Dickens invents the modern concept of Christmas Spirit and offers one of the world''s most adapted and imitated stories. We know Ebenezer Scrooge, Tiny Tim, and the Ghosts of Christmas Past, Present, and Future, not only as fictional characters, but also as icons of the true meaning of Christmas in a world still plagued with avarice and cynicism.', 'en', 2005, 112, 'http://books.google.com/books/content?id=oWYO1uH9mmcC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
