INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b42d5a5e-ec8b-538f-9aee-e28a94d5777d', '9781580495868', 'The Red Badge of Courage', 'lN1gajMoM7wC', 'As he faces battle in the Civil War for the first time, a young Union soldier comes to grips with his fear and conflicting emotions about war. This edition includes Crane''s short sequel, The veteran.', 'en', 2004, 170, 'http://books.google.com/books/content?id=lN1gajMoM7wC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
