INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0f98ab84-3165-5dff-b55c-775b13f6a503', '9781580624596', 'Sun Tzu', 'eUNB27RRRuQC', 'Learn the strategic rules of Sun Tzu and how to incorporate them into your management style. In this translation of The Art of War readers will benefit from the interpretations from other translators and strategist, as well as the 50 strategic rules, including: How to look for strategic turns to meet the competition How to attain strategic superiority and crush the competition How to plan surprise and stay ahead of the game And more timeless wisdom that will allow you to compete and win in the dynamic business environment! Business managers around the world have tapped into this ancient wisdom; it is time to master The Art of War for Managers for the existence and growth of your business!', 'en', 2001, 224, 'http://books.google.com/books/content?id=eUNB27RRRuQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
