INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b2a41bd2-caaf-583a-9551-a60ef04756d4', '9781580628365', 'Please Stop Laughing At Me', 'kAdKZqFgAmYC', 'In her poignant work, Jodee Blanco tells how school became a frightening and painful place, where threats, humiliation, and assault were as much a part of her daily experience as bubblegum and lip-gloss were for others. It is an unflinching look at what it means to be an outcast, how even the most loving parents can get it wrong, why schools fail, and how bullying is both misunderstood and mishandled.', 'en', 2003, 288, 'http://books.google.com/books/content?id=kAdKZqFgAmYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6229', 'accepted', 'Jodee Blanco', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 19 FROM public.book WHERE isbn13 = '9781580628365' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('356c9aed-f6ab-5669-a176-7c14a5596e14', '9781580631600', 'The Stephen King Universe', '8c6X4vTL5IMC', '"I am coming to understand that Roland''s world actually contains all the others of my making" --Stephen King With those words, from The Dark Tower: IV Wizard and Glass, the world''s most popular writer confirmed a suspicion long held by readers--that the myriad worlds and universes King has created are, in reality, one world, one universe. Here, for the first time ever is the guide to that universe, a thrilling road map and informative tour for new readers and diehard fans alike. The Stephen King Universe is the very first examination of all of King''s fiction and the way in which its plots and characters, conflicts, and themes, intertwine. This definitive reference work examines his novels and short stories, as well as the motion pictures, miniseries, and teleplays that King has written. The authors spent three years discovering and tying together the threads that exist in King''s fiction. Their insightful results will entertain and surprise readers new and old. Once you have read The Stephen King Universe, you will never read Stephen King the same way again', 'en', 2001, 478, 'http://books.google.com/books/content?id=8c6X4vTL5IMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
