INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('80293b76-07ee-5dfd-9be3-ba202a94f4f2', '9781580931779', 'New York 2000', 'F2xyQgAACAAJ', '"Featuring insightful discussions on the development of Battery Park City, the rebirth of Harlem and Times Square, the creation of the cultural precinct around the new MoMA, and the reclaiming of the waterfront along the East and Hudson Rivers as recreational parkland, New York 2000 documents ongoing commitments to innovation and renovation and celebrates the achievements of internationally recognized architects, including Sir Norman Foster, Cesar Pelli, Richard Meier, and Renzo Piano." "The survey of organized geographically, beginning in Lower Manhattan and moving north through Harlem and to the outer boroughs including the Bronx, Queens, Brooklyn, and Staten Island. Woven throughout is commentary on the repercussions of September 11, 2001, New York 2000 is a thorough study of how a world-class metropolis preserves, showcases, and constructs an architectural heritage that endures over the course of two centuries."--BOOK JACKET.', 'en', 2006, 1520, 'http://books.google.com/books/content?id=F2xyQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
