INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1a987eff-2627-52f0-bea1-d4e5aca9ccd7', '9781581342475', 'The Hidden Smile of God', 'kK0Ih-8e8wYC', 'The author of "Comforting God" takes an inspiring look at the words and examples of three early Christians--William Cowper, John Bunyan, and David Brainerd--and how their faith in adversity encourages us to rest in the sovereignty of God amid our own difficulties.', 'en', 2001, 175, 'http://books.google.com/books/content?id=kK0Ih-8e8wYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
