INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('53aa00c3-1e9f-5ba3-b58c-99014d42dde5', '9781581345261', 'Prophet', 'A0tppfpAvl4C', 'Anchorman John Barrett knows something is wrong. The story doesn''t add up. Prompted by extraordinary spiritual experiences, he begins to uncover a story about abortion that no one wants to hear.', 'en', 2004, 416, 'http://books.google.com/books/content?id=A0tppfpAvl4C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
