INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('26d2ad9d-cac0-5718-b07f-6a3d8c77f97d', '9781581346084', 'The Passion of Jesus Christ', '5eLRwAEACAAJ', 'Fifty Reasons Why Jesus Came to Die The most important questions anyone can ask are: Why was Jesus Christ crucified? Why did he suffer so much? What has this to do with me? Finally, who sent him to his death? The answer to the last question is that God did. Jesus was God''s Son. The suffering was unsurpassed, but the whole message of the Bible leads to this answer. Why did Christ suffer and die? The central issue of Jesus'' death is not the cause, but the meaning-God''s meaning. That is what this book is about. John Piper has gathered from the New Testament fifty reasons. Not fifty causes, but fifty purposes-in answer to the most important question that each of us must face: What did God achieve for sinners like us in sending his Son to die?', 'en', 2004, 127, 'http://books.google.com/books/content?id=5eLRwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6239', 'accepted', 'John Piper', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 15 FROM public.book WHERE isbn13 = '9781581346084' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c69a2715-cad5-5747-a3a8-b8560b33caf3', '9781581346527', 'When I Don''t Desire God', 'vtQgLN0Aq8YC', 'For over twenty-five years John Piper has trumpeted the truth that “God is most glorified in us when we are most satisfied in him.” He calls it Christian Hedonism. The problem is that many people, after being persuaded, find that this truth is both liberating and devastating. It’s liberating because it endorses our inborn desire for joy. And it’s devastating because it reveals that we don’t desire God the way we should. What do you do when you discover the good news that God wants you to be content in him, but then find that you aren’t? If joy in God were merely the icing on the cake of Christian commitment, this book would be insignificant. But Piper argues that joy is so much more. Our being satisfied in God is necessary to show God’s worthiness and to sustain sacrifices of love. Jesus endured the cross for the joy that was set before him. He tasted it. It sustained him through the deepest suffering. His Father was glorified. His people were saved. That is what joy in God does. The absolutely urgent question becomes: What can I do if I don’t have it? With a pastor’s heart and with radical passion for the glory of Christ, John Piper helps you answer that question.', 'en', 2004, 268, 'http://books.google.com/books/content?id=vtQgLN0Aq8YC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6240', 'accepted', 'John Piper', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 2 FROM public.book WHERE isbn13 = '9781581346527' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0203bb80-5e95-59c4-97a2-75284606b23d', '9781581348095', 'Suffering and the Sovereignty of God', 'cd3IwAEACAAJ', 'John Piper and other contributors explore the many categories of God''s sovereignty as evidenced in his Word, helping readers form a biblical view of suffering.', 'en', 2006, 254, 'http://books.google.com/books/content?id=cd3IwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
