INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('033ba9a3-939d-53e8-853e-e1f608451138', '9781581807592', 'Face Off', 'B-9-mAEACAAJ', 'Discover the fast, fun art of drawing comic portraits! Face Off shows you how to draw life like never before. Caricaturist Harold Hamernik shares the secrets to capturing the sillier side of friends, family, celebrities, strangers—any face that crosses your path. 40 step-by-step demonstrations show you how to sketch whimsical and expressive likenesses while developing your own quick, loose, improvisational style. You''ll get expert instruction on: Drawing eyes, noses, mouths and other features. Creating portraits in front, three-quarter and profile views. Adding color to your caricatures, either by hand or via computer—instruction you won''t find in any other book! Tips for making a likeness more masculine (skip the eyelashes), more feminine (lengthen the neck), younger, older, sexier, goofier—all while making a portrait your subject will love. How to draw hair as two simple lines, why drawing the parts of a face in the same order every time can cut minutes off your work, and tons of other handy tricks of the craft! Practice the simple techniques in this book, then start drawing! It''s the most fun you can have with paper, pencils and markers!', 'en', 2006, 127, 'http://books.google.com/books/content?id=B-9-mAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6244', 'accepted', 'Harry Hamernik', 'Art', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 7 FROM public.book WHERE isbn13 = '9781581807592' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d0318c0e-544c-52fe-a3ab-4ed9cc561c96', '9781581807745', 'Simply Beautiful Beaded Jewelry', 'PRvExwEACAAJ', 'If gorgeous beaded jewelry always catches your eye, you''ll love making (and wearing!) your own necklaces, bracelets and earrings. Simply Beautiful Beaded Jewelry includes 50 projects plus variations in designer Heidi Boyd''s simply elegant signature style. Inside you''re bound to find plenty of designs to strike your fancy as well as a helpful section that shows you the basic supplies and techniques you''ll need to get started. As an added bonus, many of the projects have variations in different colors and styles to help you customize your jewelry to your personal style. &break;&break;Just think how proud you''ll feel the first time you can answer, "I made it myself" to a compliment on your fabulous new multistrand necklace or your sparkling, swingy crystal earrings. With Simply Beautiful Beaded Jewelry, it truly is easy to get started–in no time at all you''ll be showcasing your own original beaded creations and making them as gifts.', 'en', 2006, 128, 'http://books.google.com/books/content?id=PRvExwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6245', 'accepted', 'Heidi Boyd', 'Crafts & Hobbies', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 9 FROM public.book WHERE isbn13 = '9781581807745' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('08d26cb1-644a-5605-a120-41f175816173', '9781581821369', 'The Southern Haunting of Truman Capote', 'z-8HAAAACAAJ', 'Like many Southern writers of the 1930s and 1940s, who as a group created the richest, most memorable body of regional literature in the history of American letters. Truman Capote eventually journeyed northward. As the years passed, Capote''s moorings to his Southern past grew weaker and weaker and he deliberately cut himself off from the people and places that provided fodder for much of his early fiction. The Southern Haunting of Truman Capote is a thoughtful reflection on the literary origins of four of Capote''s important early works - A Christmas Memory, The Grass Harp, Children on Their Birthdays and Other Voices, Other Rooms - in light of the boyhood experiences that inspired those four works. Marie Rudisill, a younger sister of Capote''s mother and the only one of her nephew''s companions to have known him well his whole life, was in touch with him for more than seventy years As early as the mid-1940s, Marie Rudisill realised that her nephew was destined for literary greatness. She began hoarding his letters, newspaper clippings, articles, personal mementoes - anything that might prove useful later as a record of his life. During their many telephone conversations, whenever Cap', 'en', 2000, 135, 'http://books.google.com/books/content?id=z-8HAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6246', 'accepted', 'Marie Rudisill; James Coleman Simmons', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 10 FROM public.book WHERE isbn13 = '9781581821369' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0f5a5312-d302-54a7-be9d-743dcef2ed04', '9781582293080', 'Shoofly Pie', 'HjJb3LiXfg8C', 'Forensic entomologist Nick Polchak (a.k.a. the Bug Man) is hired by 30-year-old Kathryn Guilford, who is terrified of bugs, to solve her friend''s death. When Polchak stumbles into the mystery of how Kathryn''s husband was killed years earlier, Polchak finds himself on the run with his client from someone who will do anything to keep a secret.', 'en', 2003, 371, 'http://books.google.com/books/content?id=HjJb3LiXfg8C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
