INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b591f3de-2039-5a7a-be0c-af6bb7738ca3', '9781582294018', 'Chop Shop', 'xqEIdLQrZHwC', 'Intern forensic pathologist Dr. Riley McKay has noticed irregularities in autopsies at the Allegheny County Coroner''s lab. Suspecting foul play, she seeks help from Dr. Nick Polchak, the "bug man" renowned for his ability to solve murders by analyzing the insects on victim''s bodies. Nick and Riley uncover a sinister link between the lab''s director and PharmaGen, a start-up drug company specializing in genetic research. They also discover that PharmaGen fronts an underground system to procure transplant organs for wealthy clients by finding and murdering matching donors. But PharmaGen learns of their security breach and orders the couple destroyed. While staying a step ahead of PharmaGen assassins, romantic attraction develops between Nick and Riley. But the attraction is complicated by a tragic secret that Riley hides -- a secret closely tied to one member of PharmaGen''s operation which propels the novel to its astonishing conclusion.', 'en', 2004, 352, 'http://books.google.com/books/content?id=xqEIdLQrZHwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
