INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fd8e7a2b-39fa-5f86-9a07-b2b02ca3f03e', '9781582343495', 'Schott''s Original Miscellany', 'm72iQgAACAAJ', 'Impossible to read at one sitting, but utterly unputdownable, Schott''s Original Miscellany is a unique collection of fabulous trivia. What other book boasts an index that includes shoelace lengths, sign language, and the seven deadly sins; dueling and dwarves; the hair color of Miss America and the Hampton Court maze? Where else can you find, packed onto one page, the names of golf strokes, a history of the Hat Tax, cricketing dismissals, nouns of assemblage, an unofficial motto of the US Postal Service, and the flag of Guadeloupe? Where else but Schott''s Original Miscellany will you stumble across John Lennon''s cat, the supplier of bagpipes to the Queen, the labors of Hercules, and the brutal methods of murder encountered by Miss Marple? A book like no other, Schott''s Original Miscellany is entertaining, informative, unpredictable, and utterly addictive.', 'en', 2003, 158, 'http://books.google.com/books/content?id=m72iQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
