INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('36bb867f-0e79-52c7-bf92-9a1067be9fb0', '9781582972947', 'Write Great Fiction - Plot & Structure', '0arFsgEACAAJ', 'Craft an Engaging Plot How does plot influence story structure? What''s the difference between plotting for commercial and literary fiction? How do you revise a plot or structure that''s gone off course? With Write Great Fiction: Plot & Structure, you''ll discover the answers to these questions and more. Award-winning author James Scott Bell offers clear, concise information that will help you create a believable and memorable plot, including: Techniques for crafting strong beginnings, middles, and ends Easy-to-understand plotting diagrams and charts Brainstorming techniques for original plot ideas Thought-provoking exercises at the end of each chapter Story structure models and methods for all genres Tips and tools for correcting common plot problems Filled with plot examples from popular novels, comprehensive checklists, and practical hands-on guidance, Write Great Fiction: Plot & Structure gives you the skills you need to approach plot and structure like an experienced pro.', 'en', 2004, 234, 'http://books.google.com/books/content?id=0arFsgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
