INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d2ec0e81-4aaf-541e-9107-092f5719de6f', '9781585675173', 'The Stones of Summer', '-UsyPwAACAAJ', 'Originally published to glowing reviews in 1972, Dow Mossman''s extraordinary debut is a sweeping coming-of-age novel that developed a passionate cult following - even as it went out of print for more than twenty years. It recently inspired director Mark Moskowitz''s award-winning documentary film Stone Reader, which was embraced by readers across the country and described by Peter Rainer in New York magazine as "a marvelous literary thriller that gets at the way books can stay with people forever."', 'en', 2004, 586, 'http://books.google.com/books/content?id=-UsyPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
