INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0ed67a89-1791-57ab-8b78-f579a59abfe0', '9781585675753', 'Spring Fever', '8_ecxwEACAAJ', 'The fall brings four more antic novels from comic genius, P. G. Wodehouse. In Picadilly Jim (soon to be a major motion picture), Jimmy Crocker has a scandalous reputation on both sides of the Atlantic and must do an about-face to win back the woman of his dreams. Uneasy Money sees the hard-up Lord Dawlish off to America to make a fortune, while in Cocktail Time events turn on the fate of a filmscript. Spring Fever is a light-hearted comedy involving love and various complications.', 'en', 2004, 276, 'http://books.google.com/books/content?id=8_ecxwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
