INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a920aec9-c766-59e2-9f93-941df783901e', '9781585676576', 'Money in the Bank', 'Zb1wPwAACAAJ', 'When George, sixth Viscount Uffenham, turns the family fortune into diamonds and hides them away, naturally he forgets where he has hidden the loot and is compelled to let the family seat to stay afloat. So it is that Mrs. Cork''s Health Colony comes into being.', 'en', 1942, 290, 'http://books.google.com/books/content?id=Zb1wPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
