INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a78c40e7-a7ba-5ce8-b933-925d9820afc2', '9781586638221', 'The Aristotle''s Ethics', 'NBPbiXwwsGQC', 'Enduringly profound treatise, whose lasting effect on Western philosophy continues to resonate. Aristotle identifies the goal of life as happiness and discusses its attainment through the contemplation of philosophic truth.', 'en', 2003, 80, 'http://books.google.com/books/content?id=NBPbiXwwsGQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
