INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('64835d53-c25f-5ef9-b30c-048aee0ca098', '9781586857721', 'It''s Easy Being Green', '82_EngEACAAJ', 'Provides a comprehensive guide to adopting greener buying habits and identifying earth-friendly products, shopping for green products online, participating in online activism, and learning tips for cultivating a sustainable environment, such as collecting rainwater from your roof to use in the garden, submerging a plastic bottle in your toilet tank to save one quart of water per flush, and more. Original.', 'en', 2006, 168, 'http://books.google.com/books/content?id=82_EngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
