INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('10df4f8e-3b09-52fb-8338-d007a2644c5c', '9781587150791', 'Fifty-One Tales', 'QdbDaHpPICQC', 'Lord Dunsany was one of the most influential writers of fantasy fiction in 20th century. "Fifty-One Tales" (originally published in 1915 and sometimes reprinted under the title "The Food of Death") is an ideal introduction to Dunsany.', 'en', 2002, 108, 'http://books.google.com/books/content?id=QdbDaHpPICQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
