INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('681850c6-13fe-5794-bed0-2311c376763f', '9781587155871', 'The Lure of the Basilisk', 'n5J-84oiCbQC', 'The overman named Garth sought immortal fame. The oracle told him to serve the Forgotten King to get that fame. But this King sent Garth after a basilisk whose gaze could turn men to stone. What sane use could anyone have for a monster like that?', 'en', 2001, 208, 'http://books.google.com/books/content?id=n5J-84oiCbQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
