INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f3a34758-817e-5522-b349-91078d5b9eb9', '9781587680267', 'Tolkien and C.S. Lewis', 'GQMwj9mcE-AC', 'Reveals the complex friendship between the two literary figures, noting their shared academic experiences at Oxford University, Lewis''s influence on Tolkien''s completion of The Lord of the Rings, and the differences in their temperaments and spiritual beliefs. Original.', 'en', 2003, 244, 'http://books.google.com/books/content?id=GQMwj9mcE-AC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
