INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('954cf64a-963c-5df8-aaa9-5011cf47bb28', '9781588993007', 'Category Freaks', '46Uh-rFKIrsC', 'From the creator of Aquarian Age comes a dark and occult adventure. Asagi Nanami is the director of Nanami Paranormal Investigations, where his supernatural assistants Naoki Amano, Tokiko and her helper Mahime Yoshino solve strange phenomena caused by |Freaks|. Masters of bodily possession, freaks are demonic creatures with a morbid purpose...', 'en', 2005, 184, 'http://books.google.com/books/content?id=46Uh-rFKIrsC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
