INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4b292534-4bb1-5a42-9555-bc5b37caece9', '9781589802544', 'This Side of Paradise', 'qCVAngEACAAJ', 'When his father relocates the family to Paradise to work for the mysterious Eden Corporation, Jack Barrett uncovers a sinister plot that threatens everyone he loves.', 'en', 2004, 224, 'http://books.google.com/books/content?id=qCVAngEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
