INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c69dca6b-bc8d-54d6-bbbc-b06ed1f20666', '9781589880023', 'Farewell to Salonica', 'yBTgVi88GukC', 'At the crossroads of the Eastern and Western worlds, Salonica -- now Greece''s third largest city Thessaloniki -- was an oasis in a desert of conflicting powers and interests. A Turkish territory until 1912, the city was an economic centre of the Ottoman empire and a cultural centre of Sephardic Judaism. In this memoir, Leon Sciaky, the son of a Sephardic merchant family who immigrated to Turkey during the Spanish Inquisition, tells of growing up in the vibrant community that flourished in Salonica at the turn of the century. He introduces the Turkish sheiks and dervishes, Sephardic rabbis, Hungarian revolutionaries, Bulgarian farmers, Greek priests, Kurdish grocers, Albanian woodcutters, and French headmasters who populated this little Balkan world. Although his early years were idyllic, Sciaky''s well-respected merchant family could not escape the violence of Salonica''s constant lesions and struggles. Situated amidst peoples of different languages, religions, cultures, and national allegiances, Salonica was like a vividly set stage in a drama where these very diverse peoples lived, in peace and strife, vying for power and prosperity.', 'en', 2003, 299, 'http://books.google.com/books/content?id=yBTgVi88GukC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6321', 'accepted', 'Leon Sciaky', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 6 FROM public.book WHERE isbn13 = '9781589880023' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d451dd64-1730-569a-b9d8-495b7a15f04f', '9781589943070', 'The Art of H. P. Lovecraft''s the Cthulhu Mythos', 'E43GPAAACAAJ', 'This full-color volume collects the best art from Fantasy Flight''s acclaimed Call of Cthulhu collectible card game, as well as from 25 years of Chaosium''s legendary line of Call of Cthulhu role-playing game products. In these pages are glimpses of the most terrible beings ever to exist, whose very names are spoken of in whispers, if at all: Mighty Cthulhu, Yog-Sothoth the Crawling Chaos Nyarlathotep and He Who Shall Not Be Named. Strange and alien races swarm here: the Fungi From Yuggoth, the star-headed Elder Things, the slithering Formless Spawn and awful chthonians. The Art of H.P. Lovecraft''s The Cthulhu Mythos contains hundreds of full-color pieces of art, from fan favorites such as Patrick McEnvoy, Michael Komarck, Jean Tay, Thomas Denmark, John Gravato, Aaron Acevedo, James Ryman, Felicia Cano, Linda Bergkvist and dozens more. Once you see these blasphemous visions, you will never forget them.', 'en', 2006, 191, 'http://books.google.com/books/content?id=E43GPAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
