INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0b6a887f-8441-5527-911d-4fa4d1340019', '9781589971288', 'Creative Correction', 'haewmAEACAAJ', 'In addition to advice on topics such as sibling conflict and lying, Whelchel offers this handy reference guide that provides a biblical perspective and down to-earth encouragement to parents who are feeling overwhelmed.', 'en', 2005, 367, 'http://books.google.com/books/content?id=haewmAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
