INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('991c9ecc-942c-5c31-8768-afe2fa2c78d0', '9781590170168', 'De Vita Propria Liber', '-BQjtJwGoJYC', 'A bright star of the Italian Renaissance, Girolamo Cardano was an internationally-sought-after astrologer, physician, and natural philosopher, a creator of modern algebra, and the inventor of the universal joint. Condemned by the Inquisition to house arrest in his old age, Cardano wrote The Book of My Life, an unvarnished and often outrageous account of his character and conduct. Whether discussing his sex life or his diet, the plots of academic rivals or meetings with supernatural beings, or his deep sorrow when his beloved son was executed for murder, Cardano displays the same unbounded curiosity that made him a scientific pioneer. At once picaresque adventure and campus comedy, curriculum vitae, and last will, The Book of My Life is an extraordinary Renaissance self-portrait—a book to set beside Montaigne''s Essays and Benvenuto Cellini''s Autobiography.', 'en', 2002, 320, 'http://books.google.com/books/content?id=-BQjtJwGoJYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6324', 'accepted', 'Girolamo Cardano; Jean Stoner', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 0 FROM public.book WHERE isbn13 = '9781590170168' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7c3d9725-540d-5718-b888-7b178bf373e1', '9781590170311', 'Witch Grass', 'sz6A0oZ_KaAC', 'Seated in a Paris café, a man glimpses another man, a shadowy figure hurrying for the train: Who is he? he wonders, How does he live? And instantly the shadow comes to life, precipitating a series of comic run-ins among a range of disreputable and heartwarming characters living on the sleazy outskirts of the city of lights. Witch Grass (previously titled The Bark Tree) is a philosophical farce, an epic comedy, a mesmerizing book about the daily grind that is an enchantment itself.', 'en', 2003, 328, 'http://books.google.com/books/content?id=sz6A0oZ_KaAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6325', 'accepted', 'Raymond Queneau; Barbara Wright', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 1 FROM public.book WHERE isbn13 = '9781590170311' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4c840f44-b771-52cd-9e00-f5c662f5b208', '9781590170700', 'The Tenants of Moonbloom', 'gNIb_NXhIjQC', 'Norman Moonbloom is a loser, a drop-out who can''t even make it as a deadbeat. His brother, a slumlord, hires him to collect rent in the buildings he owns in Manhattan. Making his rounds from apartment to apartment, Moonbloom confronts a wildly varied assortment of brilliantly described urban characters, among them a gay jazz musician with a sideline as a gigolo, a Holocaust survivor, and a brilliant young black writer modeled on James Baldwin. Moonbloom hears their cries of outrage and abuse; he learns about their secret sorrows and desires. And as he grows familiar with their stories, he finds that he is drawn, in spite of his best judgment, into a desperate attempt to improve their lives. Edward Lewis Wallant''s astonishing comic tour de force is a neglected masterpiece of 1960s America.', 'en', 2003, 264, 'http://books.google.com/books/content?id=gNIb_NXhIjQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6326', 'accepted', 'Edward Lewis Wallant', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 7 FROM public.book WHERE isbn13 = '9781590170700' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4483253f-16bd-5243-bdcd-873a7997c107', '9781590170786', 'The Ivory Tower', 'KelaAAAAMAAJ', 'In 1914, Henry James began work on a major novel about the immense new fortunes of America’s Gilded Age. After an absence of more than twenty years, James had returned for a visit to his native country; what he found there filled him with profound dismay. In The Ivory Tower, his last book, the characteristic pattern underlying so much of his fiction—in which American “innocence” is transformed by its encounter with European “experience”—receives a new twist: raised abroad, the hero comes home to America to confront, as James puts it, “the black and merciless things that are behind the great possessions.” James died in 1916 with the first three books of The Ivory Tower completed. He also left behind a “treatment,” in which he charted the further progress of his story. This fascinating scenario, one of only two to survive among James’s papers, is also published here together with a striking critical essay by Ezra Pound.', 'en', 2004, 296, 'http://books.google.com/books/content?id=KelaAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
