INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1ae612f9-889e-5ae1-be86-412a74057d27', '9781590171035', 'Mistress Masham''s Repose', 'J_Sg2c9uwT8C', 'Ten-year-old Maria, an orphaned heiress living with her unpleasant guardians on a crumbling English estate called Malplaquet, finds her life changing in unimagined ways when she explores an overgrown island on the estate''s lake and discovers the descendants of Gulliver''s Lilliputians.', 'en', 1946, 260, 'http://books.google.com/books/content?id=J_Sg2c9uwT8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
