INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d244c0ba-addd-554e-b24f-be1970c29b0d', '9781590171240', 'An Episode of Sparrows', 'wLgdpV170wgC', 'In post-World War II London, two street-tough children attempt to build a hidden garden, an act that awakens hidden courage in the children and profoundly disrupts the neighborhood.', 'en', 2004, 247, 'http://books.google.com/books/content?id=wLgdpV170wgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
