INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ae1d98b1-cfcc-560e-807d-3645a1db0c48', '9781590171493', 'The Man who Watched Trains Go by', '-T7faBq7gxUC', 'A man who has lived within the lines of moral conduct and good behavior for most of his life discovers in one fateful evening that his world is unraveling and commits murder--an act that seems to contradict his entire life. Reprint.', 'en', 2005, 203, 'http://books.google.com/books/content?id=-T7faBq7gxUC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
