INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('592ee3ac-f8e8-566e-bfc9-27db59344aaa', '9781590171622', 'The New York Stories of Henry James', 'LlpBNR7_vpQC', 'Brings together for the first time all the stories that Henry James set in New York City, including "The Jolly Corner," "An International Episode," and "The Impressions of a Cousin."', 'en', 2006, 563, 'http://books.google.com/books/content?id=LlpBNR7_vpQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
