INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a1704638-e1ec-59b5-975e-b307b7ceea8f', '9781590171707', 'Dime-store Alchemy', 'yllRAAAAMAAJ', 'In Dime-Store Alchemy, poet Charles Simic refects on the life and work of Joseph Cornell, the maverick surrealist who is one of America’s great artists. Simic’s spare prose is as enchanting and luminous as the mysterious boxes of found objects for which Cornell is justly renowned. In a work that is in various degrees biography, criticism, and sheer poetry, Simic tells the story of Cornell’s life and illuminates the hermetic mysteries of his extraordinary boxes–objects in which private obsessions were alchemically transformed into enduring works of art. Simic sees Cornell’s work as exemplifying a distinctively American aesthetic, open to the world, improvisatory, at once homemade and universal, modest and teasing and profound. Full of unexpected riches, Dime-Store Alchemy is both an entrancing meditation on the nature of art and a perfect introduction to a major American artist by one of his peers–a book that can be perused at length or dipped into at leisure again and again.', 'en', 2006, 116, 'http://books.google.com/books/content?id=yllRAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6333', 'accepted', 'Charles Simic; Joseph Cornell', 'Art', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 2 FROM public.book WHERE isbn13 = '9781590171707' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6b70776e-e12b-5c7f-aa98-1e531c440c75', '9781590171943', 'The Strangers in the House', '7GIPCVrT4HMC', 'Dirty, drunk, unloved, and unloving, Hector Loursat has lived as a near recluse since his wife abandoned him and their infant daughter eighteen years before. Though a member of a prominent local family and at one time a successful lawyer, Loursat now shuns and is shunned by polite society–which suits him fine. He prefers to spend his evenings leafing through the books in his library and drinking Bordeaux. Loursat does his best to ignore the presence of his teenage daughter, paying little attention to the questionable activities that seem to be going on in his vast, old, ever-more dilapidated house. But then, one night, the sound of a gunshot penetrates the padded walls of Loursat’s study. He leaves the security of his wing of the house to investigate. What he stumbles on is a case of murder. Loursat begins to discover something of the secret life of his daughter and her circle of friends, young people from all levels of local society. He finds himself strangely drawn to this group, and when one of them is accused of the murder, he astonishes all by taking up the young man’s defense. Reluctantly Loursat finds himself drawn back into the thick of life. InThe Strangers in the House, Georges Simenon, master chronicler of the dark side of the human heart, gives us a detective story that is also a tale of an improbable redemption.', 'en', 2006, 194, 'http://books.google.com/books/content?id=7GIPCVrT4HMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6334', 'accepted', 'Georges Simenon', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 7 FROM public.book WHERE isbn13 = '9781590171943' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fd0216c6-3d34-5307-bdeb-e340d469b7c4', '9781590172186', 'A Savage War of Peace', 'wuoDDB4Rbz8C', 'Although war was never formally declared, the Algerian War lasted from 1954 to 1962. It caused six French governments to fall, led to the collapse of the Fourth Republic, brought De Gaulle back to power, and came close to provoking a civil war on French soil. More than a million Muslim Algerians died in the conflict and as many European settlers were driven into exile. Above all, the war was marked by an unholy marriage of revolutionary terror and state torture. The war made headlines around the world, and at the time it seemed like a French affair: Now, this brutal and intractable conflict looks less like the last colonial war than the first postmodern one--a full-dress rehearsal for the sort of amorphous struggle that convulsed the Balkans in the 1990s and that is now ravaging Iraq, and in which religion, nationalism, imperialism, and terrorism assume previously unimagined degrees of intensity.', 'en', 2006, 608, 'http://books.google.com/books/content?id=wuoDDB4Rbz8C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
