INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d7ce6cab-2e3f-528a-bfcf-a02f8e6f17b0', '9781590300060', 'The Wave in the Mind', 'YAdTofRMkvEC', 'The author presents a collection of nonfiction writings, including essays on such topics as Tolstoy, Tolkien, women''s shoes, Mark Twain, family life, and beauty, as well as autobiographical writings and reflections on the arts of reading and writing.', 'en', 2004, 314, 'http://books.google.com/books/content?id=YAdTofRMkvEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
