INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7186e29e-c455-5ff6-9d55-d402b036691a', '9781590300107', 'Healing Emotions', 'w7xvDwAAQBAJ', 'A new edition documents encounters between the Dalai Lama and prominent western psychologists, physicians, and meditation teachers to offer insight into the mind''s ability to heal the body. Original.', 'en', 2003, 288, 'http://books.google.com/books/content?id=w7xvDwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
