INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2440c301-2f79-5ab4-9d16-a15b1d145123', '9781590300732', 'A Guide to the Words of My Perfect Teacher', 'TWcmAS2h3YMC', 'This guide provides readers with the theoretical background that is an essential foundation for studying and practicing with Patrol Rinpoche''s Words of My Perfect Teacher. The author of the guide examines the role of the teacher in Tibetan Buddhist practice and relates the stages of the path to the Buddha''s teachings on the Four Noble Truths, bringing it into perspective with an interesting overview. And, starting with a general introduction on how to approach the teachings, he goes through the original book chapter by chapter, filling in the background and putting each subject into greater perspective. Here are a few examples: - In the original text, Patrul encourages readers to have confidence in the "Three Jewels"; the guide gives a detailed description of what the Three Jewels are. - Patrul stresses the importance of transcendent wisdom; the guide provides an introduction to Madhyamika philosophy, which is the basis of transcendent wisdom. - Patrul describes the importance of the sincerity of the student''s Vajrasattva practice; the guide explains why this practice is so important and it lists the actions and karmic patterns that are addressed by the practice. - Patrul describes the Buddhist cosmology with a startling vision of the universe that encourages the reader to open his or her usual notions', 'en', 2004, 336, 'http://books.google.com/books/content?id=TWcmAS2h3YMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6339', 'accepted', 'Khenpo Ngawang Pelzang; Ṅag-dbaṅ-dpal-bzaṅ (Mkhan-po)', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 3 FROM public.book WHERE isbn13 = '9781590300732' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2a9ca1a1-5c3a-5309-81d1-c94a210bcea7', '9781590301081', 'Dewdrops on a Lotus Leaf', 'mIxUTxblX6kC', 'The Japanese poet-recluse Ryokan (1758–1831) is one of the most beloved figures of Asian literature, renowned for his beautiful verse, exquisite calligraphy, and eccentric character. Deceptively simple, Ryokan''s poems transcend artifice, presenting spontaneous expressions of pure Zen spirit. Like his contemporary Thoreau, Ryokan celebrates nature and the natural life, but his poems touch the whole range of human experience: joy and sadness, pleasure and pain, enlightenment and illusion, love and loneliness. This collection of translations reflects the full spectrum of Ryokan''s spiritual and poetic vision, including Japanese haiku, longer folk songs, and Chinese-style verse. Fifteen ink paintings by Koshi no Sengai (1895–1958) complement these translations and beautifully depict the spirit of this famous poet.', 'en', 2004, 120, 'http://books.google.com/books/content?id=mIxUTxblX6kC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
