INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4318d3a4-57b3-5b08-89a2-25c6c4057e0d', '9781590301876', 'Lovingkindness', 'C9kY3vnGh54C', 'In this inspiring book, Sharon Salzberg, one of America''s leading spiritual teachers, shows us how the Buddhist path of metta, or lovingkindness, can help us discover the radiant, joyful heart within each of us. The author draws on simple Buddhist teachings, wisdom stories from various traditions, guided meditation practices, and her own experience of practice and teaching to illustrate how each one of us can cultivate love, compassion, joy, and equanimity''the four "heavenly abodes" of traditional Buddhism.', 'en', 2004, 256, 'http://books.google.com/books/content?id=C9kY3vnGh54C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
