INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2a318d2a-07bc-50cb-aa26-80562d78921a', '9781590302255', 'The Art of War', 'Kjw1jwEACAAJ', 'Written around the 6th century BC, The Art of War is one of the oldest books about war and military strategy, and probably the best. For more than two thousand years, Sun-tzu''s "The Art of War" has provided leaders with essential advice on battlefield tactics, managing troops and terrain, and employing cunning and deception. Above all, it teaches how, when battles commences, to think on your feet and catch your enemy off guard. An elemental part of Chinese culture, it has also become a touchstone for the Western struggle for survival and success.', 'en', 2005, 273, 'http://books.google.com/books/content?id=Kjw1jwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
