INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('26b587a0-bbe9-5d22-8883-d49bc87a2382', '9781590592168', 'Complete Guide to OneNote', 'swoszQEACAAJ', '* OneNote has the potential to be the next "killer-app" in the Microsoft Office family * Author already has public visibility in the OneNote field as author of a related web site (OneNoteInfoCenter.com) and first OneNote MVP * Advanced content will differentiate the book from numerous beginner’s texts * Early to market will allow this book to establish it as the definitive book on the subject. * OneNote will be part of the Microsoft Office family and Office titles sell well', 'en', 2003, 412, 'http://books.google.com/books/content?id=swoszQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
