INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f9097f08-d67e-55f5-a372-c33e37d5157c', '9781590593899', 'Joel on Software', '-WguzQEACAAJ', '* Covers three years of the best essays. * Essays range from technical to humorous, but are always tangible. * Beautifully written and extremely timely. * Google lists 183,000 links for "Joel on Software". * Spolsky is one of the most popular programmers around today, with legions of followers.', 'en', 2004, 384, 'http://books.google.com/books/content?id=-WguzQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6356', 'accepted', 'Avram Joel Spolsky', 'Computers', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 13, 11 FROM public.book WHERE isbn13 = '9781590593899' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('35df6adf-a0f5-558e-9d5e-f66b729e6f67', '9781590596241', 'The Career Programmer', 'Nn9QAAAAMAAJ', 'Unrealistic schedules, unstable releases, continual overtime, and skyrocketing stress levels are legendary in the software development industry. Unlike traditional occupations such as accounting or administration, the software business is populated with programmers who are as creative and passionate about their work as musicians and artists. But for most programmers and project managers, it is a complete surprise when they enter the business world and find that internal politics, inept management, and unrealistic marketing drive the process, rather than a structured and orderly approach based on technical issues and quality. This guide, delivered with the wit and aplomb to make a serious topic entertaining and palatable, will help you survive the programming industry. The Career Programmer explains how you can work within the existing system to solve deadline problems and regain control of the development process. Youll master self-defense techniques to shield yourself, your project, and your code from corporate politics, arbitrary management decisions, and marketing-driven deadlines. Author Chris Duncan provides proven, practical, hands-on solutions designed to work even when tested by the political and chaotic realities of the business environment. Issues are addressed from the points of view of both the programmer and project manager, and steps are illustrated from all perspectivesfrom large-scale teams down to projects with a single developer. For you, the end results will mean less overtime and stress, higher-quality software, and a more satisfying career.', 'en', 2006, 264, 'http://books.google.com/books/content?id=Nn9QAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6357', 'accepted', 'Christopher Duncan', 'Computers', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 13 FROM public.book WHERE isbn13 = '9781590596241' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ec5c3eda-0716-5419-b276-e224a12a57ad', '9781591146919', 'Bull Halsey', 'bVheUPjxImYC', 'Applauded by the public and revered by the men who served under him, Adm. William F. Halsey was one of the leading American personalities of World War II. His reputation as a no-holds-barred fighter and his tough-guy expression earned him the nickname "Bull," yet he was also known for showing genuine compassion toward his men and inspiring them to great feats in the Pacific. Originally disclaiming the praise heaped on him, Halsey eventually came to believe in the swashbuckling legend that surrounded him, and his conduct became increasingly controversial. Naval historian E. B. Potter, who established his reputation with an award-winning biography of Chester W. Nimitz, gets behind the stereotype of this national hero and describes Halsey at his best and worst, including his controversial actions at Leyte Gulf. To write this book Potter had full access to Halsey''s family and to the admiral''s private papers and provides detail of Halsey''s youth and career before the war. First published in 1985, it remains the definitive study.', 'en', 2003, 440, 'http://books.google.com/books/content?id=bVheUPjxImYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
