INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fe28b53e-1c6c-533a-9071-ba822b10262e', '9781592402694', 'Here, There and Everywhere', 'bpjbmAEACAAJ', 'An engineer who worked with the Beatles during the productions of "Revolver," "Sgt. Pepper''s Lonely Hearts Club Band," and other albums describes his innovative recording techniques, and shares his insights into the band''s creative processes.', 'en', 2007, 400, 'http://books.google.com/books/content?id=bpjbmAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
