INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cb5cf2e9-331e-503e-99fb-d95f12a367c1', '9781592441129', 'Natural Theology', 'J9xKAwAAQBAJ', 'This reissue of Emil Brunner''s ''Nature and Grace'' with Karl Barth''s response ''No!'' places back into the hands of theological students one of the most important, and well publicized, theological arguments of the 20th century. Here we see the climax of Barth and Brunner''s disagreement over the point of contact for the gospel in the consciousness of natural man. Also at stake is the nature of the theological task. Brunner claims that the task of that generation was to find a way back to a legitimate natural theology. Barth responds strongly, arguing that there is no way to knowledge of God by way of human reason. Barth''s radical Christocentric redevelopment of Reformation theology left no room for any source of authority aside from the Word of God.', 'en', 2002, 132, 'http://books.google.com/books/content?id=J9xKAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
