INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('56b06e22-5f91-56f5-81d0-83edfe547286', '9781592572229', 'The Complete Idiot''s Guide to World Religions', 'ZPokHByS3N0C', 'Presents an overview of the world''s major religions, and answers questions about the history, rituals, celebrations, structure, holy documents, and deities of major and lesser-known religions.', 'en', 2004, 405, 'http://books.google.com/books/content?id=ZPokHByS3N0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
