INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6ac578b7-246e-56dd-b519-6941fee987bf', '9781592851614', 'Drop the Rock', 'vxFEmAEACAAJ', 'A practical guide to letting go of the character defects that get in the way of true and joyful recovery. Resentment. Fear. Self-Pity. Intolerance. Anger. As Bill P. explains, these are the "rocks" that can sink recovery- or at the least, block further progress. Based on the principles behind Steps Six and Seven, Drop the Rock combines personal stories, practical advice, and powerful insights to help readers move forward in recovery. The second edition features additional stories and a reference section.', 'en', 2005, 132, 'http://books.google.com/books/content?id=vxFEmAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
