INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('429c06f2-1537-5630-8747-b92b524b60ad', '9781593074661', 'Star Wars: Empire Volume 5', 'hPcFyQEACAAJ', 'Luke Skywalker fights side-by-side with a shipwrecked veteran from the Clone Wars, Han Solo’s flirtations with an old flame land him in the fire, and BoShek (the galaxy''s second-coolest smuggler) attracts a whole lotta blaster fire from Rebels and Imperials alike in this collection featuring some of the most unexpected stories in the era of the Empire! Whether it’s BoShek transporting an innocent-enough looking girl, Han making a supply run for the resource-strapped Alliance, or Luke flying escort for a Rebel Intelligence team on a supposedly deserted planet, these adventures may start as routine missions, but their endings are anything but predictable!', 'en', 2006, 120, 'http://books.google.com/books/content?id=hPcFyQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
