INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('587380a8-de13-536f-8f1f-2d4140808e65', '9781593075293', 'Eden', 'kzBlAAAACAAJ', 'With the world reeling from the after effects of a brutal, widespread virus, civilization is torn between the laws and ways of the old world and a new order where cybernetic implants are commonplace and might means right. Elijah and his comrades-in-arms attempt to cross the Andes Mountains, with Propater''s gruesome Aeon soldiers and armored troops hot on their heels.', 'en', 2006, 224, 'http://books.google.com/books/content?id=kzBlAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
