INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('71569ba3-cc93-5a32-bdce-f805315d8500', '9781593075439', 'Conan and the Demons of Khitai', 'mb_RPQAACAAJ', 'Set many years in the future from the award-winning ongoing series, Conan and the Demons and Khitai marks Conan''s first appearance as King in Dark Horse''s best-selling comics revival of the legendary fantasy hero. When King Conan receives an invitation from the Eastern kingdom of Khitai to open trade in precious jewels and spices, he decides that he will travel into this long-mysterious land. Yet to do so is perilous, as those who have requested his company may have far more devious intentions, and beasts unseen by Western eyes lurk amidst the shadows.', 'en', 2006, 90, 'http://books.google.com/books/content?id=mb_RPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
