INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ea53373f-6220-5681-96f8-ace04a291587', '9781593076191', 'Star Wars: OmnibusXWing Rogue Squadron Vol. 2', 'FsCvAAAACAAJ', 'As the Empire withers away and the New Republic grows, one team of ace starfighters takes on the most critical missions to ensure freedom in a galaxy long oppressedRogue Squadron! Collecting XWing Rogue Squadron #920, this mammoth volume includes Battleground Tatooine, The Warrior Princess, and Requiem for a Rogue. Whether it''s keeping a massive weapons cache out of the hands of Jabba the Hutt''s wouldbe successors, brokering peace on a planet wracked by civil war, or rescuing a downed cruiser from the jaws of an ancient evil, no task is too treacherous for the heroes of Rogue Squadron! • This giant, affordable volume is the perfect opportunity to catch up on some of the most popular stories in the Star Wars Universe!', 'en', 2005, 288, 'http://books.google.com/books/content?id=FsCvAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
