INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b0778104-cca0-5007-84a8-43d0f90a7417', '9781593076276', 'Star Wars: Empire Volume 6 In The Shadows of Their Fathers', 'EFvXzAEACAAJ', 'Luke Skywalker confronts the legacy of the Jedi father he never knew in an epic story involving Princess Leia, Darth Vader, and the fate of an entire planet! When Luke and Leia travel to Jabiim recruiting allies for the fledgling Rebellion, they unwittingly set into motion events that will ignite one man''s betrayal of his people, pit rebel hero against rebel hero, and attract the attention of the Empire''s deadliest enforcer-Darth Vader! • This action-packed tale sheds new light on Anakin Skywalker''s actions at the Battle of Jabiim during the Clone Wars.', 'en', 2005, 144, 'http://books.google.com/books/content?id=EFvXzAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
