INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('94074ea9-127e-5fde-b045-0cf6a05d8deb', '9781593076405', 'Star Wars: Knights of the Old Republic Vol. 1--Commencement', 'srJgAAAACAAJ', 'Thousands of years before Luke Skywalker would destroy the Death Star in that fateful battle above Yavin 4, one lone Padawan would become a fugitive hunted by his own Masters, charged with murdering every one of his fellow Jedi-in-training! From criminals hiding out in the treacherous undercity of the planet Taris, to a burly, mysterious droid recovered from the desolate landscape of a cratered moon, Padawan Zayne Carrick will find unexpected allies in his desperate race to clear his name before the unmerciful authorities enact swift retribution upon him! • Collects Knights of the Old Republic #0-#6. • Set during the era of the smash-hit video games, Knights of the Old Republic features all-new characters in an action-packed adventure essential to any serious Star Wars devotee and the perfect introduction for anyone interested in exploring the universe beyond the movies!', 'en', 2006, 152, 'http://books.google.com/books/content?id=srJgAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
