INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('28d63d42-ace4-5437-baa5-8bb0ab1a5278', '9781593076672', 'Facts in the Case of the Departure of Miss Finch HC', 'U_vswAEACAAJ', 'Come, come and hear of the strange and terrible tale of Miss Finch, an exacting woman befallen by mystery and abduction deep under the streets of London! New York Times best-selling author Neil Gaiman delivers another stunning hardcover graphic novel with longtime collaborator Michael Zulli (Creatures of the Night, The Sandman). This is the first comics adaptation of his popular story "The Facts in the Case of the Departure of Miss Finch," which saw print only in the U.K. edition of Gaiman''s award-winning work Smoke and Mirrors: Short Fictions and Illusions and was recently interpreted for his Speaking in Tongues CD. The Facts in the Case of the Departure of Miss Finch is a "mostly true story" that combines the author''s trademark magic realism with Zulli''s sumptuous paintings, and has been newly rewritten for this hardcover. Join a group of friends, with the stern Miss Finch in tow, as they enter musty caverns for a subterranean circus spectacle called "The Theatre of Night''s Dreaming." Come inside, get out of the pounding rain, and witness this strange world of vampires, ringmasters, illusions, and the Cabinet of Wishes Fulfill''d. • The latest hardcover from New York Times best-selling author Neil Gaiman (Anansi Boys and The Sandman: Endless Nights), one of the world''s best-loved comics writers! • Smoke and Mirrors won the 1998 MacMillan Silver PEN Award for Best Short Story Collection.', 'en', 2008, 51, 'http://books.google.com/books/content?id=U_vswAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6390', 'accepted', 'Neil Gaiman; Michael Zulli', 'Comics & Graphic Novels', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 20 FROM public.book WHERE isbn13 = '9781593076672' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('061dbabd-da07-50a4-bd8e-ce1fce6ddbfa', '9781593077099', 'Star Wars: Empire Volume 7--The Wrong Side of the War', 'i6DfxwEACAAJ', 'Fresh from the killing fields of Jabiim, where the Empire has virtually wiped out the populace of that world, Imperial Lieutenant Janek Sunber is sent to the quiet prison base on Kalist VI. But, unbeknownst to the Empire, the Rebels have designs on Kalist Base both for its desirable fuel supplies, and for the presence of a very important prisoner-one of their own who has already attracted the interest of Darth Vader. Sunber doesn''t know it, but he''s on a collision course with an old friend who is with the Rebels, and he finds himself wondering which of them is on the wrong side of the war. • Just in time for the thirtieth anniversary of Star Wars comes a story that reintroduces a character not mentioned since A New Hope! • Collecting issues #35-40 of Star Wars Empire, this graphic novel holds a surprise that is sure to delight every Star Wars fan!', 'en', 2007, 144, 'http://books.google.com/books/content?id=i6DfxwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
