INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ac40f0a5-a9c3-5e95-abb1-942702c83a4e', '9781593082697', 'Essential Dialogues of Plato', 'eKRQH7wAbQEC', 'From the Publisher: Western philosophy starts with Socrates and his student Plato. By way of the dialectic that evolved between master and student, Plato invented the philosophical method of inquiry and analysis, and became the first to use a logical framework to ask-and try to answer-the eternal questions about ethics, politics, art, and life that still haunt humanity. Along with such exemplars of Plato''s thought as Symposium, Apology, and Phaedrus, this volume includes the first three books of Plato''s Laws.', 'en', 2005, 624, 'http://books.google.com/books/content?id=eKRQH7wAbQEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
