INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dfc512cb-8a13-56cf-9df1-6a08f3912aac', '9781593083779', 'Swann''s Way', 'wHUIr6NhLwMC', 'Presents the first book of Proust''s monumental work "Remembrance of Things Past", introducing such themes as the destructive force of obsessive love, the allure and the consequences of transgressive sex, and the selective eye that shapes memories.', 'en', 2005, 466, 'http://books.google.com/books/content?id=wHUIr6NhLwMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
