INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3f1e98cb-c4ee-56eb-b948-340f877083a2', '9781593761226', 'The Soloist', 'A7U2swEACAAJ', 'At thirty-four, piano soloist Max Randal has hit a wall. It''s been four years since his last live performance, and his manager is intent on revitalizing his career with a big concert at Carnegie Hall. As if that wouldn''t be enough for Max to worry about, as he struggles to prepare, the ghosts of his failed relationships have come to haunt him -- his first ex-wife is dying, his second ex-wife wants to get back together, the mother of his child has taken off for Europe and unexpectedly left him to care for their nine-year-old, and his present girlfriend now wants to get serious. Believe it or not, the plot only gets thicker. Merging dozens of characters and events into a seamless narrative, gifted novelist and poet Nicholas Christopher delivers a compelling tale. Like an exhilarating performance,The Soloist takes you on a brilliant adventure that resonates even once it''s over.', 'en', 2006, 320, 'http://books.google.com/books/content?id=A7U2swEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
