INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bc544ff2-a0e7-5d24-8085-6a9a16584a93', '9781593854461', 'Teaching Reading Comprehension to Students with Learning Difficulties', 'NfLfnEdzD60C', 'A ChoiceOutstanding Academic Title! A highly practical resource for the classroom, this book offers clear, research-based recommendations for helping students at all grade levels understand and learn from what they read. Explaining the skills and strategies that good readers use to comprehend text, the authors show how to support struggling students in developing these skills. They present a variety of effective assessment procedures, ways to enhance vocabulary instruction and teach students about different text structures, and instructional practices that promote comprehension before, during, and after reading. Special features include discussion questions in every chapter, and reproducible instructional materials and lesson plans.', 'en', 2007, 178, 'http://books.google.com/books/content?id=NfLfnEdzD60C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
