INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fd0746d1-5bf3-5c90-a88e-183144402fb2', '9781594130076', 'The Fellowship of the Ring', 'ZQFiPwAACAAJ', 'A New York Times Bestseller Part One of The Lord of the Rings In a sleepy village in the Shire, young Frodo Baggins is faced with an immense task as his elderly cousin Bilbo entrusts the One Ring of Sauron to his care. Frodo must make a perilous journey across Middle-earth to the Cracks of Doom, there to destroy the all-powerful Ring and foil the Dark Lord in his evil purpose.', 'en', 2003, 855, 'http://books.google.com/books/content?id=ZQFiPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
