INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d4ae476a-0892-5af6-8c55-0d880de07166', '9781594481529', 'The Brief and Frightening Reign of Phil', 'PWWmyMgGZ5gC', 'Citizens waiting to enter the country of Inner Horner, a strange land that is only large enough for one resident at a time, fall prey to the tyrannical rule of the ambitious and power-hungry Phil, igniting an outbreak of injustice and mass hysteria, in an unusual novel by the author of Pastoralia. Original.', 'en', 2005, 130, 'http://books.google.com/books/content?id=PWWmyMgGZ5gC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
