INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('80e16b87-2b42-57c7-abda-e267f70ea0d4', '9781594481574', 'Plan B', '__EKDAAAQBAJ', 'A spiritual guide by the author of the best-selling Traveling Mercies shares humorous and inspirational advice on how to manage with grace in today''s world of terrorism, while caring for aging parents and children simultaneously, and in the face of environmental threats. Reprint.', 'en', 2006, 352, 'http://books.google.com/books/content?id=__EKDAAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
