INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bc603a11-f6dc-5540-b68a-e30dbf3714b7', '9781595329141', 'Dragon Head', 'HOsfMiDATbEC', 'With the medicine to cure Teru in hand, Ako and Nimura struggle to return to their ailing friend. Standing in their way is a whole town bent on killing them as well as the strange young man with the scar on his head. Will they be able to save Teru before its too late? Older teens.', 'en', 2006, 220, 'http://books.google.com/books/content?id=HOsfMiDATbEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
