INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2f1705bd-7fa7-5440-a547-24fd4057c26a', '9781595540454', 'The Oath', 'UlpfXTEnDNQC', 'A decade ago, Peretti unleashed what many fans consider his most suspenseful, multilayered novel ever--now available in a 10th anniversary edition with an all-new cover, new Foreword by the author, and the author''s signature on the cover and case of the book.', 'en', 2005, 576, 'http://books.google.com/books/content?id=UlpfXTEnDNQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
