INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('36de83d2-c781-5aaf-b0a7-3929c0df50d2', '9781595690364', 'Teleny, Or, The Reverse of the Medal', 'Qw2ItholIXQC', 'This homoerotic novel unmasked the cynical double moral standards of the Victorian era: The love of Camille and Teleny is shattered by social reprisals. It was originally published in 1893 by Leonard Smithers who praised it as being "the most powerful and cleverly written erotic romance which has appeared in the English language." (Adult Fiction)', 'en', 2006, 138, 'http://books.google.com/books/content?id=Qw2ItholIXQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
