INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('803e25f2-0298-5fdf-8e0a-339d8a3d1d37', '9781595690555', 'His Excellency', 'oZgkKVGNDMQC', 'His Excellency (French: Son Excellence Eugene Rougon) - From Zola''s Rougon-Macquart Series. "Son Excellence Eugene Rougon is the one existing French novel which gives the reader a fair general idea of what occurred in political spheres at an important period of the Empire. It is a book for foreigners and particularly Englishmen to read with profit, for there are yet many among them who cherish the delusion that Napoleon III. was not only a good and true friend of England, but also a wise and beneficent ruler of France; and this, although his reign began with bloodshed and trickery, was prolonged by means of innume-rable subterfuges, and ended in woe, horror, and disgrace... There is, of course, some fiction in the book; but, again and again, page after page, I have found a simple record of fact, just deftly adapted to suit the requirements of the narrative. The history of the Second Empire is probably as familiar to me as it is to M. Zola himself-for, like him, I grew to manhood in its midst, with better opportunities, too, than he had of observing certain of its distinguishing features - and thus I have been able to identify innumerable incidents and allusions, and trace to their very source some of the most curious passages in the book. And it is for this reason, and by virtue of my own knowledge and experience, that I claim for His Excellency the merit of reflecting things as they really were in the earlier years of the Imperial regime." (Ernest Alfred Vizetelly)"', 'en', 2006, 364, 'http://books.google.com/books/content?id=oZgkKVGNDMQC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6437', 'accepted', 'Émile Zola; Ernest Alfred Vizetelly', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 0 FROM public.book WHERE isbn13 = '9781595690555' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('95b476cd-2a9f-5544-baac-cb60db12d6e4', '9781595820129', 'Vampire Hunter D Volume 1', '6GswxgEACAAJ', '12,090 A.D. It is a dark time for the world. Humanity is just crawling out from under three hundred years of domination by the race of vampires known as the Nobility. The war against the vampires has taken its toll; cities lie in ruin, the countryside is fragmented into small villages and fiefdoms that still struggle against nightly raids by the fallen vampires-and the remnants of their genetically manufactured demons and werewolves. Every village wants a Hunter-one of the warriors who have pledged their laser guns and their swords to the eradication of the Nobility. But some Hunters are better than others, and some bring their own kind of danger with them... From creator Hideyuki Kikuchi, one of Japan''s leading horror authors with illustrations by renowned Japanese artist, Yoshitaka Amano, best known for his illustrations in Neil Gaiman''s Sandman: The Dream Hunters and the Final Fantasy games.', 'en', 2005, 238, 'http://books.google.com/books/content?id=6GswxgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6438', 'accepted', 'Hideyuki Kikuchi; Yoshitaka Amano; Kevin Leahy', 'Comics & Graphic Novels', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 20 FROM public.book WHERE isbn13 = '9781595820129' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('db9e3e2e-46be-56f9-8af5-b454242d94a5', '9781595820310', 'Vampire Hunter D Volume 3: Demon Deathase', 'ShQvxgEACAAJ', 'The novel that was the basis for the hit motion picture Vampire Hunter D: Bloodlustis available in English for the first time! The third volume of the popular Japanese series Vampire Hunter D comes to America in Vampire Hunter D: Demon Deathchase. The vampire hunter known only as D has been hired by a wealthy, dying man to find his daughter, who was kidnapped by the powerful vampire Lord Meierlink. Though humans speak well of Meierlink, the price on his head is too high for D to ignore and he sets out to save her before she can be turned into an undead creature of the night. In the nightmare world of 12090 A.D., finding Meierlink before he reaches the spaceport in the Clayborn States and gets off the planet will be hard enough, but D has more than just Meierlink to worry about. The dying man is taking no chances, and has also enlisted the Marcus family, a renegade clan of four brothers and a sister who don''t care who they kill as long as they get paid. Beautiful illustrations by Yoshitaka Amano complement the post-apocalyptic plot, filled with chilling twists. FOR MATURE READERS', 'en', 2005, 211, 'http://books.google.com/books/content?id=ShQvxgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6440', 'accepted', 'Hideyuki Kikuchi; Yoshitaka Amano; Kevin Leahy', 'Comics & Graphic Novels', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 14 FROM public.book WHERE isbn13 = '9781595820310' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9c6e95a3-f1fb-56e5-aa99-185a28deac89', '9781595820617', 'Coffin', 'OnkwAAAACAAJ', 'For over 20 years, the character Vampire Hunter D has haunted the imaginations of people around the world, its image forever etched in the mind''s eye through the dazzling artwork of Yoshitaka Amano. As the original novels appear in English for the first time, American readers are clamoring for a more extensive look at this singular creation. Coffin obliges. This gorgeous retrospective embraces the full scope of Amano''s work with the character: in the novels, as inspiration for the animators of the two theatrical films, rare paintings, and illustrations created for release as limited edition prints. In addition to the breathtaking artwork, Coffin features an original Vampire Hunter D short story by creator Hideyuki Kikuchi, available nowhere else.', 'en', 2006, 199, 'http://books.google.com/books/content?id=OnkwAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6441', 'accepted', 'Yoshitaka Amano; Robert Simpson', 'Art', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 5 FROM public.book WHERE isbn13 = '9781595820617' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('724f0d99-1941-5a27-9bef-2eeef5559f1e', '9781595820631', 'Tale of Genji', '1tgAwQEACAAJ', 'Yoshitaka Amano has been praised around the world for his lush watercolors and evocative work dealing with myth and legend. In The Tale of Genji Mr. Amano brings his considerable talent to retelling one of the most famous of Japanese myths: written by Murasaki Shikibu shortly after 1000 AD and considered by most scholars to be the first novel ever written, The Tale of Genji is the story of the romantic adventures of Genji, the amazingly handsome prince and his many romantic conquests. Told through stunning paintings, Mr. Amano brings this classic story to life for a new generation. • As one of the most respected stories of all time, The Tale of Genji holds a worldwide place of honor among lovers of myth and legend.', 'en', 2006, 81, 'http://books.google.com/books/content?id=1tgAwQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
