INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fc5b9d80-04a0-5515-8363-ca9cac3a1f0d', '9781595820716', 'Ju-on', 'mP3oPAAACAAJ', 'A novelization of the horror film The Grudge, based on the popular manga and film series, traces the experiences of a senior citizen outreach volunteer who encounters a murderous deadly force involving the victims of a terrible curse. Original.', 'en', 2006, 240, 'http://books.google.com/books/content?id=mP3oPAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
