INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0e095423-dc4a-5a30-a50f-07d81b4a82f5', '9781595820938', 'Vampire Hunter D Volume 4: Tale of the Dead Town', '_3k1zQEACAAJ', 'When a floating city becomes the target of a rash of vampire attacks, only one man can restore the oasis. "The City," a tiny metropolis of a few hundred sheltered citizens floating serenely on a seemingly random course a few feet above the ground, has long been thought safe from the predation of marauding monsters. It seemed like a paradise. A paradise shattered when an invasion of apparent vampires threatens the small haven. While the Vampire Hunter known only as "D" struggles to exterminate the scourge, a former denizen of the city, the attractive Raleigh Knight, and the brash John M. Brassalli Pluto VIII seize control of the city lurching it onto a new and deadly course. D''s travails are just beginning. * The Vampire Hunter D films are two of the most-popular Japanese anime films released in the United States consistently ranking among the top DVDs sold on amazon.com! FOR MATURE READERS', 'en', 2006, 205, 'http://books.google.com/books/content?id=_3k1zQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6444', 'accepted', 'Hideyuki Kikuchi; Yoshitaka Amano; Kevin Leahy', 'Comics & Graphic Novels', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 2 FROM public.book WHERE isbn13 = '9781595820938' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9c08d4cf-a09e-5a7b-8d93-9c36fdb3e9c4', '9781595820945', 'Vampire Hunter D Volume 5: The Stuff of Dreams', 'CtHmAAAACAAJ', 'In a world where even the smallest and most remote village is being terrorized by the monsters that stalk the night, there is a hamlet, prosperous and peaceful, where mortals and vampires have lived in harmony for years. It is there that seventeen-year-old Sheavil Schmidt has slept, neither waking nor aging, for thirty years since first receiving the vampire''s immortal kiss. The mysterious Vampire Hunter D is lured to the tranquil oasis by recurrent dreams of the beautiful, undying girl bathed in an eerie blue light and dancing in a ghostly chateau. * Over 100,000 copies of the Vampire Hunter D novels have been sold. * The Stuff of Dreams is volume 5 in a seventeen volume series. FOR MATURE READERS', 'en', 2006, 208, 'http://books.google.com/books/content?id=CtHmAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
