INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e752eeca-99a9-5d75-ac4b-9fa90e852090', '9781595821072', 'Vampire Hunter D Volume 7: Mysterious Journey to the North Sea, Part 1', 'BEJwAQAACAAJ', 'A girl''s dying wish sends D on an impossible quest in this riveting prose novel. Even a reluctant hero can''t refuse the last request of a beautiful woman. On her deathbed, the mortally wounded woman gives him a strange gem and asks him to deliver the priceless stone to her sister, far off in a North Sea fishing village. D''s journey is made ever more perilous by a series of scoundrels and rogues hired by the girl''s murderer. They''ll stop at nothing to claim the jewel. Will they catch him? Hideyuki Kikuchi''s crackling narrative and Yoshitaka Amano''s imaginative artwork make this a must-read entry in the series.', 'en', 2007, 209, 'http://books.google.com/books/content?id=BEJwAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
