INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('66d494d6-e8db-54f1-bc69-28a5b79d72ad', '9781597221108', 'Undead and Unwed', 'XE9SPgAACAAJ', 'A just-laid-off secretary has a really bad week when she dies and is then made Queen of the Undead. "Chick lit meets vampire fiction in this creative, sophisticated, sexy, and wonderfully witty book."--Catherine Spangler.', 'en', 2005, 392, 'http://books.google.com/books/content?id=XE9SPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
