INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('57b1832f-7c75-5960-a919-c730b693b046', '9781600430015', 'Vegas Bites', 'eoMbPQAACAAJ', 'What howls in Vegas, stays in Vegas. Welcome to the French Quarter, Sin City''s premier casino, where the high rollers are vampires, the sexy showgirls are werewolves, and the lounge magician is a djinn. Beneath the sexy, sassy, smoldering action, danger lurks and Lady Love reigns supreme. Below the glittering, glitzy Las Vegas front lies a struggle for life, death, and dominance of the most powerful werewolf pack in North America. Explore this high roller fantasy world of feuding werewolf packs, high-stakes thieves, a sexy djinn, and a mystical medallion. But baby it''s only Vegas.', 'en', 2006, 346, 'http://books.google.com/books/content?id=eoMbPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
