INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('70693440-2feb-5029-93c5-f85a908ed540', '9781600961502', 'The Lost Continent', '35GYPwAACAAJ', 'The Lost Continent is one of the least-known of Burroughs'' thrilling science-fiction tales. In the year 2137, civilization has been in decline for nearly two centuries, and war-torn Europe is but a distant memory to the inhabitants of the isolated United States. But an American adventurer rediscovers the Old World, which has become a strange and savage land.', 'en', 2008, 108, 'http://books.google.com/books/content?id=35GYPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
