INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f232adda-a7e0-5fb2-bb20-e60e80a5d192', '9781740596466', 'Australia and New Zealand on a Shoestring', 'pISjtwEACAAJ', 'At last - the two hottest stars on the travel circuit combined in one sizzling guidebook! Grab your pack and head south to Australia''s awesome beaches and New Zealand''s spectacular landscapes. Written for backpackers by backpackers, this guide to the wonders clown under helps you travel further and pay less. - Two in one - No other guide covers both Australia and New Zealand, let alone from a backpacker''s perspective - Get the lowdown on where to go for nonstop parties, and where to find a little space all to yourself - Eat cheap and sleep easy with our fully updated coverage of the best local eateries and great-value accommodation - Take your life in your hands - get your thrills from the best scuba diving, bungy jumping, skiing and jetboating that Oz and NZ bas to offer!', 'en', 2005, 836, 'http://books.google.com/books/content?id=pISjtwEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
