INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d416d6c6-f64d-534c-ac95-aa5c7fa82f78', '9781740599085', 'Amsterdam', '_iiWTKQTt7sC', 'Marvel at the Dutch Masters and take a step back in time in an elegant merchant''s house. Join the late-night revellers in the Red Light District or cosy-up canalside in a " brown café ". Get the low-clown on Queen''s Day and see the Royal Orchestra at the Concertgebouw. Elegant, history-steeped port; liberal, laid-back party town. Connect with your Amsterdam using this stylish and streetwise guide. Comprehensive listings - more than 250 reviews of 4 the best restaurants, cafés, coffeeshops and clubs in town. Expanded architecture chapter - get gable- gazing with our chapter dedicated to this remarkable city''s characterful buildings. Be informed - in-depth analysis of current events gets you under the skin of the city. Explore the city your way- tailor-made cycling and walking tours and recommended canal cruises', 'en', 2006, 298, 'http://books.google.com/books/content?id=_iiWTKQTt7sC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
