INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4f0a0eb1-c829-5d0c-811f-e59b197f6319', '9781741142396', 'Harvesting the Heart', '0uNEzMkXweIC', 'Harvesting the Heart explores the story of a young woman overcome by the demands of having a family. Written with astonishing clarity and evocative detail, convincing in its depiction of emotional pain, love and vulnerability, Harvesting the Heart recalls the writing of Alice Hoffman and Sue Miller.', 'en', 2003, 468, 'http://books.google.com/books/content?id=0uNEzMkXweIC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
