INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('36861daa-3e82-5da0-92ab-10e88fedb7c6', '9781840224535', 'The Death of Ivan Ilyich and Other Stories', 'qzcSTHoNdSsC', 'Tolstoy wrote many masterly short stories, and this volume contains four of the longest and best in distinguished translations that have stood the test of time.', 'en', 2004, 256, 'http://books.google.com/books/content?id=qzcSTHoNdSsC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
