INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2f456214-31be-5f2d-9521-7afb21b3e427', '9781840233803', 'Planet of the Apes', 'KsixAAAACAAJ', 'The Hit Movie and Beyond...; A sequel story arising out of events featured in the Tim Burton summer blockbuster sci-fi movie, Planet of the Apes. It''s the year 2029, and astronaut/pilot Leo Davidson was caught in a special anomaly, stranded on a world where gorillas and chimps were the dominant species. A world where the remnants of mankind struggled to survive beneath the heel of ape rule. In this unique story, we discover what happens in the aftermath of Leo''s adventure on the ape world.', 'en', 2001, 72, 'http://books.google.com/books/content?id=KsixAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
