INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e4ada121-19bc-580f-af01-a09a6050f468', '9781840237870', 'American Splendor Presents Bob and Harv''s Comics', '-WhcPgAACAAJ', 'Harvey Pekar is a true American original, known by many as the blue-collar Mark Twain. For over 25 years he''s been writing comic books about his life, chronicling the ordinary and everyday in stories both funny and moving.', 'en', 2004, 318, 'http://books.google.com/books/content?id=-WhcPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
