INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5c96a4ad-fae0-5721-a33a-e5c7827ce29f', '9781840239249', 'Ministry of Space', 'QaHaswEACAAJ', 'In this alternative history tale, the British capture the cream of Nazi rocket science at the end of World War Two and create a new British Empire that extends to the moon and beyond; but the road to space is paved with a secret dark enough to bring the empire to its knees.', 'en', 2005, 100, 'http://books.google.com/books/content?id=QaHaswEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
