INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('70e7e39a-4842-542c-9983-6d299afc3766', '9781840460278', 'E.M. Forster - A Passage to India', 'Eyga_7KoLpgC', 'A Passage to India (1924), the last of E. M. Forster''s novels to be published in his lifetime, became an immediate bestseller and also met with critical acclaim for its moral and political commentary on the crossings between individuals and cultures in the India of the British Empire. Forster''s record of the terrible consequences of failed connection, of the unexpected upheavals that unsettle the calm of middle-class life, and of the challenges to the ideological foundations of Empire draw their strength from the novel''s blend of intense realism and complex narrative technique. In this Readers'' Guide, Betty Jay considers the establishment of Forster''s reputation and the various attempts of critics to decipher the complex codes that are a feature of his novel. Successive chapters focus on debates around Forster''s liberal-humanism, with essays from F. R. Leavis, Lionel Trilling and Malcolm Bradbury; on the indeterminacy and ambiguity of the text, with extracts from essays by Gillian Beer, Robert Barratt, Wendy Moffat and Jo-Ann Hoeppner Moran; and on the sexual politics of Forster''s work, with writings from Elaine Showalter, Frances L. Restuccia and Eve Dawkins Poll. The Guide concludes with essays from Jeffrey Meyers and Jenny Sharpe, who read A Passage to India in terms of its engagement with British imperialism.', 'en', 1998, 176, 'http://books.google.com/books/content?id=Eyga_7KoLpgC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6495', 'accepted', 'Betty Jay', 'Language Arts & Disciplines', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 5 FROM public.book WHERE isbn13 = '9781840460278' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e15944f9-0878-5a2a-b254-f66de94f872c', '9781840462685', 'Jean Rhys', '0sF1QgAACAAJ', 'In this Reader''s Guide, Carl Plasa provides a comprehensive survey and analysis of the most stimulating critical responses to Wide Sargasso Sea. The opening chapter outlines initial reactions to the novel from English and Caribbean critics, charting the differences between them. Chapter Two explores Wide Sargasso Sea ''s dialogue with Jane Eyre and the theoretical questions it has raised. Succeeding chapters examine how critics have assessed the racial politics of Rhys''s text, discuss the novel''s African Caribbean cultural legacy, and explore how critics read the work both in terms of its moment of production and the early Victorian period in which it is set.', 'en', 2003, 194, 'http://books.google.com/books/content?id=0sF1QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6496', 'accepted', 'Carl Plasa', 'Literary Criticism', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 16 FROM public.book WHERE isbn13 = '9781840462685' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ca1b7845-f141-51b2-a282-8d2273f4f2a1', '9781840681123', 'Divine Filth', 'mvGRAAAAIAAJ', 'Divine Filth is a collection of long-overlooked erotic prose and scatological fragments rivaled only by Bataille''s most well know work, Story of the Eye, for pure ''pornographic'' content that transcends the limits of literature and the self. These are shattered mystic visions of a seminal Surrealist with a deep thirst for negation of consciousness through ecstasy, humiliation, depravity and pain. Comprised of two parts, ''Filthy'' describes a descent into the scummy underworld of London''s nightlife, while ''Divinity'' describes drinking to excess and S&M pleasure.', 'en', 2004, 160, 'http://books.google.com/books/content?id=mvGRAAAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
