INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('00ca87b2-8d22-5360-9230-eb785fedb885', '9781841150352', 'The Hours', 'rbLQpzFDKOcC', 'Exiled in Richmond in the 1920s, Virginia Woolf struggles to tame her rebellious mind and make a start on her new novel. In 1990s New York, Clarissa Vaughan goes shopping for flowers for a party for her AIDS-suffering poet-friend. This novel meditates on artistic behaviour, love and madness.', 'en', 1999, 230, 'http://books.google.com/books/content?id=rbLQpzFDKOcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
