INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0427c3d5-1e9e-5bbd-a81f-6a110264ccf4', '9781841156736', 'The Corrections', 'rT6W4padP34C', 'The winner of THE NATIONAL BOOK AWARD, the New York Times No. 1 Bestseller and the worldwide literary sensation, The Corrections has established itself as a truly great American novel. The Lamberts -- Enid and Alfred and their three grown-up children -- are a troubled family living in a troubled age. Alfred is ill and as his condition worsens the whole family must face the failures, secrets and long-buried hurts that haunt them if they are to make the corrections that each desperately needs. Stretching from the Midwest in the mid-century to Wall Street and Eastern Europe in the age of globalised greed, The Corrections brings an old-time America of freight trains and civic duty into wild collision with the era of home surveillance, hands-off parenting, do-it-yourself mental healthcare, and New Economy millionaires. It announces Jonathan Franzen as one of the most brilliant interpreters of American society and the American soul.', 'en', 2002, 653, 'http://books.google.com/books/content?id=rT6W4padP34C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
