INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('786c0cf6-c13b-547b-b590-2da255d93bb2', '9781841157498', 'Strong Motion', 'HS-OchrnnuAC', 'The critically acclaimed second novel from the author of ''The Corrections''. ''Strong Motion'' is the brilliant, bold second novel from the bestselling and critically acclaimed author of ''The Corrections'' and ''Freedom''. Louis Holland arrives in Boston in a spring of strange happenings - earthquakes strike the city, and the first one kills his grandmother. During a bitter feud over the inheritance Louis falls in love with Renée Seitchek, a passionate and brilliant seismologist, whose discoveries about the origin of the earthquakes complicate everything. Potent and vivid, ''Strong Motion'' is a complex story of change from the forceful imagination of Jonathan Franzen.', 'en', 2003, 528, 'http://books.google.com/books/content?id=HS-OchrnnuAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
