INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c0c88e67-17c2-5f80-9eed-5cfaa80effaf', '9781841492056', 'Shadow of the Giant', 'GwiBPwAACAAJ', 'Orson Scott Card''s acclaimed new series following the events of his classic, award-winning Ender saga continues. Bean has narrowly averted total disaster and managed to thwart the plans of Achilles. But Achilles is far from defeated and his final goal - total domination of the Earth - is still well within his grasp. Now Bean must bring all his power and intellect to bear if he is to withstand the rise of the Hegemon. But even one of Ender''s greatest generals must realise when he is fighting a battle that cannot possibly be won. For more information on Orson Scott Card and other Orbit authors visit the web-site at www.orbitbooks.co.uk.', 'en', 2005, 388, 'http://books.google.com/books/content?id=GwiBPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6505', 'accepted', 'Orson Scott Card', 'Life on other planets', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 6 FROM public.book WHERE isbn13 = '9781841492056' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('89ac6beb-da34-5e49-a51a-282a509eb499', '9781841492667', 'The Word and the Void', 'JI-5HAAACAAJ', 'RUNNING WITH THE DEMON: One Fourth of July weekend, two men come to Hopewell, Illinois. One is a demon, a dark servant of the Void, who will feed off the anger and frustration of the community to achieve a terrible goal. Whilst families picnic and fireworks explode only John Ross, a Knight of the Word, can change the fate of humanity and save the soul of fourteen-year-old Nest Freemark. A KNIGHT OF THE WORD: The years spent saving mankind from the horrors of the Void have taken their toll on John Ross. He''s lost his spirit, his belief, and now, it seems his magic. When Nest is once again drawn into the mythic world of the Word and the Void she must warn John to take up his staff of magic once again, or the battle may be lost forever. ANGEL FIRE EAST: For twenty five years, Ross has single-handedly battled against the legion of demons of the Void. But now he learns of a gypsy morph, whose power and wild magics will be an invaluable weapon against the Void - but the Void knows this too and will not rest until the creature has been corrupted - or destroyed.', 'en', 2003, 872, 'http://books.google.com/books/content?id=JI-5HAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6506', 'accepted', 'Terry Brooks', 'Fantasy fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 4, 19 FROM public.book WHERE isbn13 = '9781841492667' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('260f950d-72f1-5d73-bdc4-4246fa6c787f', '9781841492704', 'Unto Leviathan', 'coIRHAAACAAJ', 'On a ship without a mission ... No one remembers where they came from or where they''re going. For hundreds of years, the starship Argonos, home to generations of humans, has wandered throughout the galaxy, searching for other signs of life. Now, a steady, unidentified transmission lures them toward a nearby planet. On a planet without inhabitants ... The colony has vanished. But deep within the planet''s steamy jungles, the exploration team find horrible evidence of its fate: a cavernous chamber neatly filled with rows of skeletons, each one hanging on its own hook. On a collision course with the unknown ... Once more, a signal lures the crew of the Argonos. Haunted by what they have seen, they have no choice but to follow - deep into space, where an alien mystery waits.', 'en', 2003, 442, 'http://books.google.com/books/content?id=coIRHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
