INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2db62bbb-e884-5803-bac0-dd51084e8ae6', '9781841591162', 'Jeeves in the Offing', '35IoAQAACAAJ', 'Anyone who involves himself with Roberta Wickham is asking for trouble, so naturally Bertie Wooster finds himself in just that situation when he goes to stay with his Aunt Dahlia at Brinkley Court. So much is obvious. Why celebrated loony-doctor Sir Roderick Glossop should be there too, masquerading as a butler, is less clear. As for Bertie''s former headmaster, the ghastly Aubrey Upjohn, the dreadful novelist, Mrs Homer Cream and her eccentric son Wilbert, their presence is entirely perplexing. Without Jeeves to help him solve these mysteries, Bertie nearly comes unstuck. It is only when that peerless manservant returns from his holiday that the resulting tangle of problems is sorted out to everyone''s satisfaction - except Bertie''s.', 'en', 2002, 208, 'http://books.google.com/books/content?id=35IoAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
