INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('77343692-b2ef-5fb1-8dda-0fae1e729f24', '9781841811109', 'Zen in Your Garden', 'SCvxNwAACAAJ', 'This title seeks to help the reader create a garden that is a haven of tranquility by drawing on the principles of Zen aesthetics and by incorporating elements of Zen philosophy and symbolism into garden design. It shows how to design rock and water gardens which symbolize spiritual qualities.', 'en', 2001, 128, 'http://books.google.com/books/content?id=SCvxNwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
