INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1c948a56-03c3-547f-8b4f-83f15bff2d1c', '9781841953670', 'Gone Bamboo', 'X1g0AAAACAAJ', 'Welcome to the retirement home of Henry and Frances, ex - New Yorkers and professional assassins. A luxury hotel suite in an idyllic, tequila - drenched Caribbean hideaway. It''s supposed to be all cocktails and sex on the beach. But when a job icing a Mafioso godfather goes awry, trouble hits paradise . . . in the form of a cross - dressing capo, a debaunched and savage Irish hardman and a slew of incompetant but vicious US marshals. Mix yourself a Tequila Sunrise and dive into Gone Bamboo.', 'en', 2002, 286, 'http://books.google.com/books/content?id=X1g0AAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
