INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f90f5349-5039-570f-b3cf-0884710831e5', '9781841954318', 'The Crimson Petal and the White', 'xGvlys8IlDkC', 'Sugar, An alluring, nineteen-year-old whore in the brothel of the peculiar Mrs Castaway, yearns for a better life. And when she is visited by William Rackham – the somewhat reluctant heir to Rackham Perfumeries – she begins an ascent through the strata of 1870''s London society that offers us intimacy with a host of loveable, maddening and superbly realised characters. Gripping from the first page, this immense novel is an intoxicating and deeply satisfying read – not only a wonderful story but the creation of an entire, extraordinary world.', 'en', 2003, 835, 'http://books.google.com/books/content?id=xGvlys8IlDkC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
