INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('708ca136-e81a-50a1-9f68-f8585ca67945', '9781841957951', 'Adiós Hemingway', '6y2CHZYxBfwC', 'When a human skeleton is discovered on Ernest Hemingway''s home in Havana, police inspector Mario Conde is called up out of retirement to unearth the truth. In the course of his investigations, Conde gradually reconstructs the mysterious goings-on of the night of 3rd October 1958 and in doing so is forced to come to terms with a very different side to the character of his former literary hero. Padura Fuentes cuts between Conde''s world and that of Hemingway''s Cuba four decades earlier.', 'en', 2006, 229, 'http://books.google.com/books/content?id=6y2CHZYxBfwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
