INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fcd75693-88c3-52e4-afa4-eecd83fb6964', '9781842124024', 'The Complete Short Stories of H.G. Wells', '4mS4SAAACAAJ', 'One of the founding-fathers of science fiction, it is in his short stories that Wells first explored the enormous potential of the scientific discoveries of his age. In this first ever complete collection of his stories, 84 minor miracles of the storyteller''s art remind us of the relevance of this greatest of modern dreamers.', 'en', 2000, 864, 'http://books.google.com/books/content?id=4mS4SAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
