INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('017a97d2-bfa0-569c-ac28-70629c5e10f7', '9781842163863', 'Portrait of Dorian Gray', 'zYGvRAAACAAJ', 'Dorian remembered the wish he had made at Basil''s. He had said that he wished the portrait would grow old and ugly while he remained young and beautiful. But could such things come true? Dorian didn''t think so. But what about the portrait? It had changed.', 'en', 2000, 32, 'http://books.google.com/books/content?id=zYGvRAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
