INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c9a86689-8983-5b8b-b6d9-f58811986d6a', '9781842931530', 'Beowulf & Grendel', 'yQPXAAAAMAAJ', 'The author of Heaven''s Mirror and The Mars Mystery presents evidence that the legend of Beowulf originated in an ancient human sacrifice ritual that was suppressed in Britain and later found expression in this compelling tale. Original.', 'en', 2005, 246, 'http://books.google.com/books/content?id=yQPXAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
