INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1a8ff66c-c5ce-5642-8ad8-0e2da26c3c13', '9781842931851', 'Mysteries', 'LiHQIYR2MwAC', 'Through his own cathartic experiences, Colin Wilson discovered that human beings consist of a ladder or hierarchy of selves, whose upper members may be called on at will for personal transformation and deep knowledge. "Mysteries" attempts to explain all paranormal phenomena -- from precognition to Uri Geller''s spoon bending -- in terms of this theory. Included are detailed studies of haunting, possession, and " demonic hypnosis, " and also of magic, the Kabbalah, and astrology. At the heart of the book is a fascinating chapter on the " Great Secret" of the alchemists, which Wilson sees as the key to the mystery of the " ladder of selves."', 'en', 2006, 672, 'http://books.google.com/books/content?id=LiHQIYR2MwAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
