INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('29720f27-8027-55ec-be26-1e6858963df1', '9781843534099', 'Cuba', 'ggOlMQEACAAJ', '"The Rough Guide to Cuba is the ultimate guidebook to the Caribbean''s most exciting destination. Features include: Full-colour section including Cuba''s highlights; Detailed accounts of every attraction, from the resort of Varadero and the unspoiled Vinales valley to the vibrant and accessible capital city of Havana. Informed reviews of the best places to eat, drink and stay, for every taste and budget. Expert coverage of Cuba''s enthralling culture and history, plus how to experience the island''s dynamic music scene first-hand. Practical advice for dealing with transport, currency and bureaucracy. Maps and plans for every region." -- Back cover.', 'en', 2005, 640, 'http://books.google.com/books/content?id=ggOlMQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
