INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9ffac112-de1e-5bb8-8228-ecc1ce1e442b', '9781843537205', 'The Rough Guide to the Beatles', 'HWE8AQAAIAAJ', 'The Beatles are the ultimate band – the most popular, the most respected, the most influential. This new edition of The Rough Guide to the Beatles covers every aspect of the Fab Four, delving deep into the music, lyrics, movies and solo careers. Features include: The Story: from Liverpool clubs to Beatlemania. The Music: incisive reviews of every Beatles and solo album. The Canon: the inside track on the 50 greatest songs. On Screen: the movies, the promos and the TV appearances. The Fifth Beatle: George Martin, Yoko Ono, Magic Alex and other contenders. Beatleology: the best books, the weirdest covers, the most obsessive websites, the obscurest trivia.', 'en', 2006, 325, 'http://books.google.com/books/content?id=HWE8AQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
