INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f4f1b0ca-7950-5adf-8598-f43706cab84d', '9781843914112', 'The Fatal Eggs', 'qzJuPgAACAAJ', 'An inspired work of science fiction and a biting political allegory, Bulgakov''sThe Fatal Eggstells of a brilliant scientist whose experiments with life spiral terribly—and fatefully—out of control. Quite by chance, Professor Persikov discovers a new form of light ray whose effect, when directed at living cells, is to accelerate growth in primitive organisms. But when this ray is shone on the wrong batch of eggs, the Professor finds himself both the unwilling creator of giant hybrids and the focus of a merciless press campaign. For it seems the propaganda machine has turned its gaze upon him, distorting his nature in the very way his “innocent” tampering created the monster snakes and crocodiles that now terrorize the neighborhood. Russian novelist and dramatist Mikhail Bulgakov is one of the foremost satirists of the 20th century.', 'en', 2005, 104, 'http://books.google.com/books/content?id=qzJuPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6540', 'accepted', 'Mikhail Bulgakov; Hugh Aplin', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 15, 4 FROM public.book WHERE isbn13 = '9781843914112' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0769d681-27a6-5019-82ba-89bd03ba767c', '9781844130801', 'The Fourth Crusade and the Sack of Constantinople', 'nXxIN5mp_00C', 'In April 1204, the armies of Western Christendom wrote another bloodstained chapter in the history of holy war. Two years earlier, aflame with religious zeal, the Fourth Crusade set out to free Jerusalem from the grip of Islam. But after a dramatic series of events, the crusaders turned their weapons against the Christian city of Constantinople, the heart of the Byzantine Empire and the greatest metropolis in the known world. The crusaders spared no one in their savagery: they murdered and raped old and young - they desecrated churches, plundered treasuries and much of the city was put to the torch. Some contemporaries were delighted: God had approved this punishment of the effeminate, treacherous Greeks; others expressed shock and disgust at this perversion of the crusading ideal. History has judged this as the crusade that went wrong. In this remarkable new assessment of the Fourth Crusade, Jonathan Phillips follows the fortunes of the leading players and explores the conflicting motives that drove the expedition to commit the most infamous massacre of the crusading movement.', 'en', 2005, 416, 'http://books.google.com/books/content?id=nXxIN5mp_00C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
