INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('52ff4d5d-a8ce-5278-ba9a-dda729736cd8', '9781844151455', 'Red Road From Stalingrad', 'adaXAwAAQBAJ', 'Mansur Abdulin fought in the front ranks of the Soviet infantry against the German invaders at Stalingrad, Kursk and on the banks of the Dnieper. This is his extraordinary story. His vivid inside view of a ruthless war on the Eastern Front gives a rare insight into the reality of the fighting and into the tactics and mentality of the Soviet army. In his own words, and with a remarkable clarity of recall, he describes what combat was like on the ground, face to face with a skilled, deadly and increasingly desperate enemy.', 'en', 1990, 195, 'http://books.google.com/books/content?id=adaXAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
