INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4bd9297e-fe56-5549-8057-5e67f29ce3de', '9781844164110', 'Outlander', '843TAAAACAAJ', 'When a stranger comes to town, the local religious zealots see an opportunity to put the man''s forgery skills to nefarious use. But is the stranger all he seems and is revenge the only thing he''s interested in forging? When a stranger comes to town, the local religious zealots see an opportunity to put the man''s forgery skills to nefarious use. But is the stranger all he seems and is revenge the only thing he''s interested in forging?', 'en', 2006, 254, 'http://books.google.com/books/content?id=843TAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
