INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ec53977c-14d0-54c8-b3f3-3a72ac06cfd9', '9781844350483', 'Doctor Who Short Trips: Repercussions', 'EJFdOAAACAAJ', 'Doctor Who Short Trips is a series of themed short story anthologies of new Doctor Who fiction, featuring the Doctor in all of his first eight incarnations. They feature stories written by some of the leading names in Doctor Who, past and present, including Paul Cornell, Gareth Roberts, Christopher H. Bidmead, and Paul Magrs. Repercussions features 16 tales set on a strange airship taking its passengers on a trip to who-knows-where. Among the people aboard is young adventuress Charley Pollard, just a few weeks into her life aboard the TARDIS alongside the Eighth Doctor, a man whose past she knows frighteningly little about. She encounters a diplomat trying to stop a war, a young man seemingly murdered by the Doctor, a tramp, a seismologist, and a republican trying to save the life of his plague-stricken daughter. One thing they all have in common: an encounter with a strange alien visitor who seemed to help them, but perhaps should have left them alone.', 'en', 2004, 246, 'http://books.google.com/books/content?id=EJFdOAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
