INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6a3d3050-2809-5752-a9d3-67bc3c4a388d', '9781844580514', 'Attack of the Jaguar', '3HUdt6w9XVAC', 'This training manual for operatives of Xtreme Adventures Inc., tells the story of Simon, a teenager who finds himself alone in the depths of the Amazon, where he must rescue his parents and survive the dangers of the jungle.', 'en', 2004, 125, 'http://books.google.com/books/content?id=3HUdt6w9XVAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
