INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6a060740-0586-53e2-b9b4-af7f569c897a', '9781844670222', 'Planet of Slums', 'FToaDLPB2jAC', 'An exploration of modern-world urbanization cites a concerning rise in slum life that currently accounts for nearly one-fifth of the world''s population, arguing that urban populations are disconnected and exempt from the formal world economy and may represent an explosive convergence of ethnic, religious, and political unrest.', 'en', 2006, 228, 'http://books.google.com/books/content?id=FToaDLPB2jAC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
