INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('633e1f5b-83af-5e3d-a223-034cc448d182', '9781844670536', 'Le Système Des Objets', '0T3-3Ce5VocC', 'Pressing Freudian and Saussurean categories into the service of a basically Marxist perspective, The System of Objects offersa cultural critique of the commodity in consumer society. Baudrillardclassifies the everyday objects of the "new technical order" asfunctional, nonfunctional and metafunctional. He contrasts "modern" and"traditional" functional objects, subjecting home furnishing andinterior design to a celebrated semiological analysis. His treatment ofnonfunctional or "marginal" objects focuses on antiques and thepsychology of collecting, while the metafunctional category extends tothe useless, the aberrant and even the "schizofunctional." Finally,Baudrillard deals at length with the implications of credit andadvertising for the commodification of everyday life. The System of Objectsis a tour de force of the materialist semiotics of the earlyBaudrillard, who emerges in retrospect as something of a lightning rodfor all the live ideas of the day: Bataille''s political economy of"expenditure" and Mauss''s theory of the gift; Reisman''s lonely crowdand the "technological society" of Jacques Ellul; the structuralism ofRoland Barthes in The System of Fashion; Henri Lefebvre''s workon the social construction of space; and last, but not least, GuyDebord''s situationist critique of the spectacle.', 'en', 2005, 224, 'http://books.google.com/books/content?id=0T3-3Ce5VocC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6549', 'accepted', 'Jean Baudrillard', 'Philosophy', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 18, 2 FROM public.book WHERE isbn13 = '9781844670536' ON CONFLICT DO NOTHING;
