INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('015c0a8d-b805-53e4-ada1-b801d9dbbfea', '9781844671083', 'In Defense of Lost Causes', 'VWB0QgAACAAJ', 'A high-energy philosophical manifesto on the concept and virtues of universal values addresses such topics as Heidegger''s engagement with the Third Reich, the role of class struggles in global capitalism, and the legacy of Christianity against New Age spiritualism. Original.', 'en', 2008, 504, 'http://books.google.com/books/content?id=VWB0QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
