INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('02bb4851-1940-51f6-a8df-fb997afc08e7', '9781845203344', 'The Intelligence of Evil or the Lucidity Pact', 'jNxzQgAACAAJ', 'There are few philosophers today cool enough to be referenced in the Matrix, interesting enough to be mentioned on Six Feet Under, and popular enough to get over 606,000 hits on Google. Jean Baudrillard has succeeded in all of this and more. Now, in his latest book, Baudrillard presents his most popular themes--symbolic exchange, hyper-reality, technology and war--and applies them to the current global conflict between "the West and the Rest", including Islam. Ultimately, it is not simply about the war against terror but about the bigger picture of capitalism versus everything else. This book serves as the summation of Baudrillard''s work over the last twenty years and is the essential analysis of the fundamental conflict of our time.', 'en', 2005, 215, 'http://books.google.com/books/content?id=jNxzQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
