INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4f4c4b43-acf9-5823-b4ba-bd5855355bc7', '9781845390105', 'Scary Edwin Page', 'uikcOAAACAAJ', 'Edwin Page was scarier than a bin bag full of bad dreams. And on one night of the year, Edwin Page was very, very scary indeed. But for once, on this Hallowe''en, something is about to change.', 'en', 2004, 24, 'http://books.google.com/books/content?id=uikcOAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
