INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7958497d-772f-569f-9823-992f9c684649', '9781852428082', 'Before Night Falls', 'r01MCuyrcOEC', 'Reinaldo Arenas presents a book about sexual, political and artistic freedom. In Before Night Falls, Arenas recounts his journey from a poverty-stricken rural childhood in Cuba to his death in New York four decades later.', 'en', 2001, 317, 'http://books.google.com/books/content?id=r01MCuyrcOEC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
