INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c7fa0c71-239d-5d19-9350-e174f08a1b2e', '9781852864989', 'Death', '5XnXOAAACAAJ', 'A tale of music, mortality, friendship and death is told in a graphic novel designed for mature readers by author Neil Gaiman. Spinning off from the popular Sandman Library, this is the story of Foxglove, a rising star of the music world who must wrestle with revealing her true sexual orientation as her companion, Hazel, is lured into the realm of Death.', 'en', 1994, 104, 'http://books.google.com/books/content?id=5XnXOAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
