INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6b9fbe89-7345-56b6-a6de-ae917b830be9', '9781854596017', 'Abandonment', 'dUrSIq5E6RMC', 'A play about love, death, identity and evolution, from the bestselling and highly acclaimed novelist. Elizabeth, forty-something, childless, recently separated, just wants to be alone. She''s moved into a converted Victorian mansion, alive with history, character, woodworm and rot. But worse than that she''s besieged by invaders of the human kind. Her best friend, her sister, their mother, the builder and a photographer are all determined to make their mark. And a former inhabitant of the house, disturbed from her resting place by Elizabeth''s arrival, revisits her own long-forgotten past. Kate Atkinson''s play Abandonment was first performed at the Traverse Theatre, Edinburgh, in 2000.', 'en', 2000, 96, 'http://books.google.com/books/content?id=dUrSIq5E6RMC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6572', 'accepted', 'Kate Atkinson', 'Drama', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 10 FROM public.book WHERE isbn13 = '9781854596017' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('10eeb6cf-d123-5502-8002-11c2db1837bd', '9781854790477', 'The Wicked Wit of Charles Dickens', '51RhAAAACAAJ', 'A prolific novelist and chronicler of Victorian England, the works of Charles Dickens have inspired, enthralled and entertained millions across the globe. In The World According to Charles Dickens, aspects of the personal life of Britain''s greatest writer are revealed and explored, along with the highs and lows of his professional life, covering such subjects as childhood and family, women and love, politics and wealth, marriage and divorce. Born in Portsmouth, in 1812, he spent a happy childhood in Chatham, Kent, until the age of twelve, when his father was imprisoned for debt. After working as an office boy, and studying shorthand, he became a reporter for the Morning Chronicle before writing articles for numerous other periodicals. By 1836, these articles were republished in book form as Sketches by Boz. Dickens then began his career as a novelist, and continued to write until his death in 1870. An entertaining and informative biography, which features extracts and quotes from his works, and draws comparisons between the life and work of one of the world''s best-known writers, The World According to Charles Dickens provides a fascinating insight into this great individual. A must for all readers and admirers of Dickens.', 'en', 2002, 162, 'http://books.google.com/books/content?id=51RhAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6573', 'accepted', 'Shelley Klein; Charles Dickens', 'Reference', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 2 FROM public.book WHERE isbn13 = '9781854790477' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('837787de-cb41-5025-b00a-41e1bf7dd043', '9781855325524', 'Lützen 1632', 'xrtXvgAACAAJ', 'The Thirty Years War, a religious conflict between Catholics and Protestants, raged across Europe between 1618 and 1648, devastating huge areas of Germany. By 1632 the Protestant powers were in a desperate situation until King Gustavus Adolphus II of Sweden, ''the Lion of the North'', came to their rescue. This book describes how, having smashed one of the two main Catholic armies, he faced the other at Lützen near Leipzig in November 1632. In a nightmare battle fought in thick fog, his Swedish troops locked horns with the Imperial army. It was a bloody clash, in which Gustavus himself demonstrated true courage at the head of his cavalry - and one for which he would pay the ultimate price.', 'en', 2001, 96, 'http://books.google.com/books/content?id=xrtXvgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6574', 'accepted', 'Richard Brzezinski', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 4 FROM public.book WHERE isbn13 = '9781855325524' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('edc6fd93-7004-56bc-a1a5-0180593c8cd4', '9781855384279', 'The Art of Dreaming', 'h4BElKY-TjAC', 'Carlos Castaneda Was One Of The Most Influential Spiritual Teachers Of The 20Th Century. In This Stunning New Jacket Edition Of His Bestselling Book, He Takes The Reader On An Amazing Journey Of The Soul Via The Teachings Of The Great Sorcerer Don Juan And Reveals That There Are Worlds Existing Within Our Own That Can Be Visited Through Dreams. The Art Of Dreaming Is An Extraordinary And Exciting Adventure Of The Psyche Unlike Any Other, Which Takes The Reader On An Amazing Journey Of The Soul Via The Teachings Of The Great Sorcerer, Don Juan. Carlos Castaneda Reveals That, Like The Layers Of An Onion, There Are Worlds Existing Within Our Own That Can Be Visited Through Dreams. Using Powerful Ancient Techniques To Alter His State Of Consciousness, Castaneda Travels Into New Worlds And Encounters Remarkable But Dangerous Beings; He Conjoins Energy Bodies With Another Dreamer In Order To Dream And Explore Together, And Thus Acquires New Knowledge And Understanding. Castaneda''S Compelling Writing Enables The Reader To Participate Fully In His Eye-Opening And Thrilling Discoveries And Explorations.', 'en', 1994, 260, 'http://books.google.com/books/content?id=h4BElKY-TjAC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6575', 'accepted', 'Carlos Castaneda', 'Dreams', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 5 FROM public.book WHERE isbn13 = '9781855384279' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('37b9f691-99e9-5f8b-afc6-25e46b38a648', '9781857024074', 'A Thousand Orange Trees', 'TRMwGQAACAAJ', 'Set in 17th-century Spain, this is a twisting together of the stories of two women born on the same day and whose lives are devoured by the bloodthirsty Spanish state.', 'en', 1995, 317, 'http://books.google.com/books/content?id=TRMwGQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
