INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b8be8edb-c084-59db-be14-ec3f15fed5ee', '9781857024692', 'A Scandalous Life', 'y0tQPgAACAAJ', 'From the acclaimed biographer of The Sisters, the story of one of the most remarkable women of the 19th century, who traveled far and wide on a quest for true love Produced from Jane Digby''s diaries, this sympathetic and dramatic portrait of a rare woman explores a fascinating glimpse into the centuries-old Bedouin tradition that is now almost lost. A celebrated aristocratic beauty, Jane Digby married Lord Ellenborough at 17. Their divorce a few years later was one of England''s most scandalous at that time. In her quest for passionate fulfillment she had lovers which included an Austrian prince, King Ludwig I of Bavaria, and a Greek count whose infidelities drove her to travel Eastern Asia. In Syria, she found the love of her life, a Bedouin nobleman, Sheikh Medjuel el Mezrab, who was 20 years her junior. During the remainder of her life she adopted for six months of each year the exotic but uniquely harsh existence of a desert nomad living in the famous black goathair tents of Arabia; the remaining months she spent in the splendid palace she built for herself and Medjuel in Damascus. As wife to the Sheikh and mother to his tribe this passionate woman found not only genuine fulfillment but further adventures, all of which she committed each year to her diary.', 'en', 1996, 365, 'http://books.google.com/books/content?id=y0tQPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6577', 'accepted', 'Mary S. Lovell', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 16 FROM public.book WHERE isbn13 = '9781857024692' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ea244988-9044-5759-b779-69431b39afda', '9781857027129', 'Galileo''s Daughter', 'SEpCrFCkwscC', 'While Galileo Galilei was under house arrest, accused of heresy for his claim that the earth revolved around the sun, his daughter Virginia, a cloistered nun, proved to be her father''s greatest source of strength through the difficult years of his trial and persecution. Winner of the Christopher Award and named a Notable Book of the Year by the "New York Times". Illustrations.', 'en', 2000, 448, 'http://books.google.com/books/content?id=SEpCrFCkwscC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
