INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('88dc948d-7d9b-599d-8972-7ffbe9b08407', '9781857028157', 'The Magician''s Assistant', '-yU3AQAACAAJ', 'The national bestseller--now in paperback. When the magician Parsifal dies, his assistant, Sabine, who was also for only the last few months of his life married to Parsifal, must sort out the emotional baggage she inherits.s', 'en', 1998, 357, 'http://books.google.com/books/content?id=-yU3AQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6579', 'accepted', 'Ann Patchett', 'Fantasy fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 10 FROM public.book WHERE isbn13 = '9781857028157' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2a103508-de65-5d13-8900-3e783e399026', '9781857093315', 'Tom Hunter', 'jaN5QgAACAAJ', 'Tom Hunter is a London-based photographer of international renown for his engaging, distinctive, and often provocative re-creations of Old Master paintings. In 1998 he won the John Kobal Photographic Portrait Award for A Woman Reading a Possession Order, a beautifully crafted photograph based on a composition by the Dutch master, Johannes Vermeer (1632–1675). Featuring selections of the bold images that established Hunter’s reputation, together with new work, this book conveys the artist’s deep concern with depicting the lives of the residents of Hackney, East London, as captured in the headlines of Hunter’s local newspaper, the Hackney Gazette. These startling, sometimes tragic, stories are retold in carefully staged photographs, whose compositions are frequently derived from paintings in the National Gallery. An essay by best-selling novelist Tracy Chevalier examines Hunter’s story-telling, while Colin Wiggins discusses the relationship between Hunter’s work and paintings in the National Gallery and elsewhere.', 'en', 2005, 80, 'http://books.google.com/books/content?id=jaN5QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6580', 'accepted', 'Tracy Chevalier; Colin Wiggins', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 20, 2 FROM public.book WHERE isbn13 = '9781857093315' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6ed03114-3299-527f-a675-ea7ae5bf0ccc', '9781857151336', 'Lolita', 'o8KYQgAACAAJ', 'Poet and pervert, Humbert Humbert becomes obsessed by twelve-year-old Lolita and seeks to possess her, first carnally and then artistically, out of love, ''to fix once for all the perilous magic of nymphets''. Is he in love or insane? A silver-tongued poet or a pervert? A tortured soul or a monster? Or is he all of these? Humbert Humbert''s seduction is one of many dimensions in Nabokov''s dizzying masterpiece, which is suffused with a savage humour and rich, elaborate verbal textures.', 'en', 1992, 335, 'http://books.google.com/books/content?id=o8KYQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6582', 'accepted', 'Vladimir Nabokov', 'American literature', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 16 FROM public.book WHERE isbn13 = '9781857151336' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e91cf17a-f2c1-5b8e-b6b9-cf714cc0ca9c', '9781857152746', 'The Prime of Miss Jean Brodie', '5yQLAAAACAAJ', 'The brevity of Muriel Spark''s novels is equaled only by their brilliance. These four novels, each a miniature masterpiece, illustrate her development over four decades. Despite the seriousness of their themes, all four are fantastic comedies of manners, bristling with wit. Spark''s most celebrated novel, THE PRIME OF MISS JEAN BRODIE, tells the story of a charismatic schoolteacher''s catastrophic effect on her pupils. THE GIRLS OF SLENDER MEANS is a beautifully drawn portrait of young women living in a hostel in London in the giddy postwar days of 1945. THE DRIVER''S SEAT follows the final haunted hours of a woman descending into madness. And THE ONLY PROBLEM is a witty fable about suffering that brings the Book of Job to bear on contemporary terrorism. All four novels give evidence of one of the most original and unmistakable voices in contemporary fiction. Characters are vividly etched in a few words; earth-shaking events are lightly touched on. Yet underneath the glittering surface there is an obsessive probing of metaphysical questions: the meaning of good and evil, the need for salvation, the search for significance.', 'en', 2004, 512, 'http://books.google.com/books/content?id=5yQLAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6583', 'accepted', 'Muriel Spark; Frank Kermode', 'Girls', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 20 FROM public.book WHERE isbn13 = '9781857152746' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7e32c9a3-84f7-5522-9aff-2ee76a02ab4f', '9781857231106', 'The Elfstones of Shannara', 'eAPuGwAACAAJ', 'An ancient evil threatens the Elves and the Races of Man. The Ellcrys, the tree of long-lost Elven magic, is dying, unravelling the spell of Forbidding that locks the hordes of Demons away from the world. Already the fearsome Reaper is free. Only by quickening a new seed in the mysterious Bloodfire can the Ellcrys be reborn and the Forbidding made whole. Amberle, a young Elven girl, is chosen to undertake the quest for the Bloodfire. The way is perilous, though. Other demons besides the Reaper stalk the land. Amberle will need a protector if she is to prevail, and Wil Ohmsford, heir to the elven magics of Shannara, is chosen to accompany her. Amberle''s quest and the fate of the Four Lands will rest on Wil''s ability to unlock the magic of the mysterious Elfstones of Shannara. THE ELFSTONES OF SHANNARA is the second volume of the classic series that has become one of the best loved fantasy tales of all time.', 'en', 1982, 469, 'http://books.google.com/books/content?id=eAPuGwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6584', 'accepted', 'Terry Brooks', 'Elves', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 13 FROM public.book WHERE isbn13 = '9781857231106' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0e8e96e4-4923-50e1-ba93-d25c4e03ded0', '9781857232097', 'The Fires of Heaven', '4HyfQgAACAAJ', 'The fifth book in Robert Jordan''s internationally bestselling epic fantasy series, THE WHEEL OF TIME, now reissued with a stunning new cover design. The bonds and wards that hold the Great Lord of the Dark are slowly failing, but still his fragile prison holds. The Forsaken, immortal servants of the shadow, weave their snares and tighten their grip upon the realms of men, sure in the knowledge that their master will soon break free ... Rand al'' Thor, the Dragon Reborn, knows that he must strike at the Enemy, but his forces are divided by treachery and by ambition. Even the Aes Sedai, ancient guardians of the Light, are riven by civil war. Betrayed by his allies, pursued by his enemies and beset by the madness that comes to the male wielders of the One Power, Rand rides out to meet the foe. Find out more about this title and others at www.orbitbooks.co.uk', 'en', 1994, 912, 'http://books.google.com/books/content?id=4HyfQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6586', 'accepted', 'Robert Jordan', 'Juvenile Nonfiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 16 FROM public.book WHERE isbn13 = '9781857232097' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b7ac3ea7-13af-56f3-ae92-f024ae7fa633', '9781857232561', 'Magic Kingdom for Sale', '1tdqPwAACAAJ', 'Landover was a genuine magic kingdom, complete with fairy folk and wizardry, just as the advertisement had promised. But after he purchased it for a million dollars, Ben Holiday discovered that there were a few details the ad had failed to mention. Such as the fact that the kingdom was falling into ruin. The barons refused to recognize a king and taxes hadn''t been collected for years. The dragon, Strabo, was laying waste to the countryside, while the evil witch, Nightshade, was plotting to destroy no less than everything. And if that weren''t enough for a prospective king to deal with, Ben soon learned that the Iron Mark, terrible lord of the demons, challenged all pretenders to the throne of Landover to a duel to the death - a duel no mere mortal could hope to win. But Ben Holiday had one human trait that even magic couldn''t overcome. Ben Holiday was stubborn...', 'en', 1987, 324, 'http://books.google.com/books/content?id=1tdqPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6587', 'accepted', 'Terry Brooks', 'Fantasy fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 1, 18 FROM public.book WHERE isbn13 = '9781857232561' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9b76bc09-7dbe-54c4-998c-d0092455017e', '9781857233940', 'Excession', 'YqpyQgAACAAJ', 'By the author of Feersum Endjinn. The Excession has returned but the only person who is aware of its potential is living out her death in the immense Sleeper Service ship. The Excession is something the culture must understand better - before it falls into less understanding hands.', 'en', 1996, 451, 'http://books.google.com/books/content?id=YqpyQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
