INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3d569196-8d44-5085-acff-9d9832db7251', '9781857234022', 'A Man Betrayed', 'Kcg6PwAACAAJ', 'At Castle Harvell, demented Prince Kylock grabs the reins of power by murdering his father. Harvell''s two young refugess are torn apart by the storms of war: headstrong young Melliandra is captured by brutal slavers and Jack, whose wild power works miracles, falls prey to a smuggler''s lying charms and a woman''s seductive schemes. Meanwhile, a knight''s shattered destiny is about to lead from death-sport pits to the blood-strewn creation of an empire. For more information on this or any other Orbit title, visit the Orbit website at www.orbitbooks.co.uk', 'en', 1996, 560, 'http://books.google.com/books/content?id=Kcg6PwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
