INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('05239101-32a2-50bf-a6a5-42bff8cadb03', '9781857237504', 'The Conan Chronicles 1', 'QHERQQAACAAJ', 'Before Robert Jordan conquered the bestseller lists with his phenomenally successful Wheel of Time series, he revived the legendary fantasy hero, Conan the Cimmerian. These widely acclaimed adventures introduced the world-famous barbarian to a new generation of readers. This volume contains three tales, CONAN THE INVISIBLE, CONAN THE DEFENDER and CONAN THE UNCONQUERED, all of which feature the storytelling magic and epic splendour that have made Robert Jordan one of the best-loved fantasy authors of all time.', 'en', 1999, 510, 'http://books.google.com/books/content?id=QHERQQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
