INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a778c3dd-eef4-5e3d-90df-41c986659f93', '9781857237641', 'Otherland', 's73lHAAACAAJ', 'Otherland, an incredibly complex and detailed virtual reality, has appeared. Surrounded by secrecy, it is home to the wildest dreams and darkest nightmares of its users and its creators. Vast amounts of money have been lavished on it. The best minds of two generations have laboured to build it. And somehow, bit by bit, it is claiming the Earth''s most valuable resource - its children. The story begun in OTHERLAND continues in this, the second volume of an astonishing series which is destined to become a landmark in imaginative fiction.', 'en', 1998, 796, 'http://books.google.com/books/content?id=s73lHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6592', 'accepted', 'Tad Williams', 'Otherland (Imaginary place)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 20 FROM public.book WHERE isbn13 = '9781857237641' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('dc3ecfb0-039e-55d0-a3f5-9b20091238c3', '9781857239706', 'Angel Fire East', '6QXiHAAACAAJ', 'As a Knight of the Word, John Ross has struggled against the tireless dark forces of the Void for twenty-five years. Ross is driven by dreams that show the world reduced to blood and ashes by the Void and its minions. But for all his power, John Ross is only one man, while the demons he battles are legion. Then Ross learns of the birth of a gypsy morph, a rare and dangerous creature formed of wild magics. If he can discover its secret, the morph will be an invaluable weapon against the Void. But the Void also knows the value of the morph, and will not rest until the creature has been corrupted - or destroyed. Desperate, Ross turns to Nest Freemark, a young woman with magical abilities of her own. And there they prepare to face an ancient evil beyond anything they have ever encountered. Look out for more information on this book and others on the Orbit website at www.orbitbooks.co.uk', 'en', 1999, 440, 'http://books.google.com/books/content?id=6QXiHAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6593', 'accepted', 'Terry Brooks', 'Courage', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 11, 3 FROM public.book WHERE isbn13 = '9781857239706' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a6450c46-693c-56a8-962c-926047ddac2a', '9781857442021', 'The Life and Games of Mikhail Tal', 'tkt9QgAACAAJ', 'Mikhail Tal, the ''magician from Riga, '' was the greatest attacking World Champion of them all, and this enchanting autobiography chronicles his extraordinary career with charm and humor. Dazzling games are interspersed throughout with anecdotes and witty self-interviews, and in typically objective fashion he related both the downs and ups of his encounters. An inveterate smoker and drinker, Tal''s life on the circuit was punctuated by bouts in the hospital with kidney problems, but nothing could dull his love for chess and his sheer genius on the chessboard. His illustrious tournament record, up to his death in 1992, is included here in full, along with 100 complete games and nearly as many positions. Tal''s annotations in this book are a world apart from ordinary games collections. No reader could fail to be swept along by his passion and vitality as he sets the scene for an encounter and then recounts every psychological twist and turn', 'en', 1997, 496, 'http://books.google.com/books/content?id=tkt9QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6594', 'accepted', 'Mihails Tāls', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 0, 11 FROM public.book WHERE isbn13 = '9781857442021' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b91a3489-76cd-5699-9a1c-7d9ae3c79e0e', '9781857880786', 'Snapshots From Hell', 'Pgb8wAEACAAJ', 'This work is an attempt to provide an answer to the paramount question every prospective student asks, "What is business school really like?" During his first year at Stanford Business School, the author began keeping a journal of his day-to-day impressions which evolved into this book, the writing of which he came to see as a "simple act of decency, like going back to the last calm bend in the river and nailing up a sign that reads ''Waterfall Ahead''". From his initial harrowing days at "maths camp" through the dizzying phalanx of core courses, the frenzy of the exam week, the pitfalls and triumphs of the interview process (including a surreal interview with Robert Maxwell) to being wined and dined by some of the most prestigious companies in the world, Robinson''s account is an irreverent story peopled with a wide range of characters.', 'en', 2005, 296, 'http://books.google.com/books/content?id=Pgb8wAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
