INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('12864d3a-6b8e-5bd3-8d53-88b4bc1802f8', '9781857983418', 'Flow My Tears, the Policeman Said', 'Wn2uuQAACAAJ', 'Another classic novel from the world''s greatest writer of science fiction Jason Taverner is a Six, the result of top secret government experiments forty years before which produced a handful of unnaturally bright and beautiful people ... and he''s the prime-time idol of millions until, inexplicably, all record of him is wiped from the data banks of Earth. Suddenly he''s a nobody in a police state where nobody is allowed to be a nobody. Will he ever be rich and famous again? Was he, in fact, ever rich and famous?', 'en', 2001, 204, 'http://books.google.com/books/content?id=Wn2uuQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
