INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7f208db1-3ca1-5071-bd18-d0aa2f21bd19', '9781857988192', 'The Rediscovery of Man', 'FGV1GwAACAAJ', 'Welcome to the strangest, most distinctive future ever imagined by a science fiction writer. An interstellar empire ruled by the mysterious Lords of the Instrumentality, whose access to the drug stroon from the planet Norstrilia confers on them virtual immortality. A world in which wealthy and leisured humanity is served by the underpeople, genetically engineered animals turned into the semblance of people. A world in which the great ships which sail between the stars are eventually supplanted by the mysterious, instantaneous technique of planoforming. A world of wonder and myth, and extraordinary imagination.', 'en', 1999, 368, 'http://books.google.com/books/content?id=FGV1GwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
