INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('109870bc-59a5-5a89-9491-38064cc4fcb6', '9781857988369', 'Stand on Zanzibar', 'ki-cPwAACAAJ', 'There are seven billion-plus humans crowding the surface of 21st century Earth. It is an age of intelligent computers, mass-market psychedelic drugs, politics conducted by assassination, scientists who burn incense to appease volcanoes ... all the hysteria of a dangerously overcrowded world, portrayed in a dazzlingly inventive style.', 'en', 1999, 672, 'http://books.google.com/books/content?id=ki-cPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
