INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('caf865a4-231d-54c9-9d89-2f89a58c4c31', '9781857988376', 'Martian Time-slip', 'hvxrHQAACAAJ', 'Mars is a desolate world. Largely forgotten by Earth, the planet remains helpless in the stranglehold of Arnie Kott, who as boss of the plumber''s union has a monopoly over the vital water supply. Arnie Kott is obsessed by the past; the native Bleekmen, poverty-stricken wanderers, can see into the future; while to Manfred, an autistic boy, time apparently stops. When one of the colonists, Norbert Steiner, commits suicide, the repercussions are startling and bizarre.', 'en', 1999, 226, 'http://books.google.com/books/content?id=hvxrHQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
