INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7b894235-ba41-53f1-978f-23bc9817d21a', '9781857989120', 'Three Early Novels', 'xbVYHQAACAAJ', 'At the beginning of his career, Philip K. Dick, whose later work won him widespread acclaim as the world''s greatest sf writer, wrote a number of short novels which were published as paperback originals back-to-back in dual volumes with works by writers who were then more famous. Considerably more straightforward than his later novels, these stories are nevertheless unmistakably the work of the author of Do Androids Dream of Electric Sheep? and Ubik in their quirky exuberance and originality.', 'en', 2000, 422, 'http://books.google.com/books/content?id=xbVYHQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
