INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('8aefe0ca-1ba7-5a42-9188-aaaa4bdd5414', '9781859605158', 'Motorcycle Basics Techbook', '1aBkQgAACAAJ', 'All common engine, chassis and electrical systems fully explained and illustrated. Topics covered include engine cycles and layouts, carburettors and fuel injection, ignition systems, clutches, gearbox, engine lubrication and cooling, wheels, tires, braking systems, suspension, steering, handling, design and electrical systems.', 'en', 2002, 222, 'http://books.google.com/books/content?id=1aBkQgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
