INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('40a4345b-ae9b-5652-b36b-f76b4e9501a6', '9781859840542', 'The Missionary Position', 'PTgJIjK67rEC', 'Explores the work of Mother Teresa, questioning her association with corrupt and cruel leaders and discussing the way wealthy western society promotes her as a celebrity', 'en', 1995, 98, 'http://books.google.com/books/content?id=PTgJIjK67rEC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
