INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('db278332-e492-5a9d-97fc-33fdb08b18d1', '9781859842843', 'No One Left to Lie to', 'VGSztGHC914C', 'Suggests that President Clinton''s largest legacy may be the weakening of the presidency and of the Democratic Party.', 'en', 2000, 150, 'http://books.google.com/books/content?id=VGSztGHC914C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
