INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e4b98cf5-80b2-5b2d-8334-44fcafb7dec0', '9781859843406', 'Blaming the Victims', 'wELzivMr_-cC', 'Blaming the Victims demonstrates with cold precision how the consistent denial of truth about the Palestinians by governments and the media in the West has led to the current impasse in Middle East politics. Controversial, forceful and above all honest it attempts to redress a sustained crime against historical truth in order to make a more rational political future in Palestine possible. With a new introduction by Edward Said and Christopher Hitchens and contributions by Norman G. Finkelstein, Peretz Kidron, Noam Chomsky, G.W. Bowerstock, Ibrahim Abu-Lughod, Rashid Khalidi, Janet L. Abu-Lughod, Muhammad Hallaj and Elia Zureik.', 'en', 2001, 296, 'http://books.google.com/books/content?id=wELzivMr_-cC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
