INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3ed4433f-9cf9-53cc-9c87-fdedf0862299', '9781859843826', 'Late Victorian Holocausts: El Nino Famines and the Making of the Third World', 'RQsHCBwizFcC', 'Shows how the droughts affecting northern Africa, China, and India in the 1870s and 1890s are consistant with El Niäno effects, and discusses the economic, racial, and political forces that allowed fifty million people to starve.', 'en', 2002, 464, 'http://books.google.com/books/content?id=RQsHCBwizFcC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
