INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('90117d01-ccaa-5424-adfb-200fed404853', '9781859843833', 'Unacknowledged Legislation', 'Dt8lTI6Q4h0C', 'A celebration of Percy Shelley''s assertion that ''poets are the unacknowledged legislators of the world'', these thirty-plus essays on writers from Oscar Wilde to Salman Rushdie dispel the myth of politics as a stone tied to the neck of literature; Norman Podhoretz''s ''bloody crossroads''. Instead Hitchens argues that when all parties in the state were agreed on a matter, it was the individual pens that created the space for a true moral argument.', 'en', 2002, 430, 'http://books.google.com/books/content?id=Dt8lTI6Q4h0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
