INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1ff8ada0-00e9-5bb1-861f-0fd2606fcc6c', '9781860465024', 'The Year of the Death of Ricardo Reis', '-GPVxLKsJdwC', 'Lisbon. 1936. Ricardo Reis is a doctor, returning to his native Portugal from Brazil after 16 years away. But what kind of doctor is he? His companions include: the ghost of the poet Pessoa; a girl with a paralysed hand; and the hotel chambermaid, who slips into his bed at night.', 'en', 1998, 384, 'http://books.google.com/books/content?id=-GPVxLKsJdwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
