INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('268bb942-4afe-5aa3-aec7-93d9287a9557', '9781860467219', 'The Stone Raft', 'nKfrc8OSjfQC', 'One day a rift opens along the border between Spain and France, and the Iberian peninsula floats off across the Atlantic, a great stone raft. But what of the floating population? While the tourists and investors flee, the Spanish and Portuguese escape the coast and wander the inland roads.', 'en', 2000, 272, 'http://books.google.com/books/content?id=nKfrc8OSjfQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
