INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('b3f71cb7-dfd6-5461-892e-49ddca0ce10f', '9781860467226', 'The History of the Siege of Lisbon', '2SQ7j8g8ZskC', 'When Raimundo Silva, humble proof-reader for a Lisbon publishing house, takes it upon himself to insert a negative into the sentence of a history book, he rewrites history. The effect of this act of insubordination is to make his editor, the voluptuous Dr Maria Sara, fall in love with him.', 'en', 2000, 314, 'http://books.google.com/books/content?id=2SQ7j8g8ZskC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6615', 'accepted', 'Jose Saramago; Giovanni Pontiero', 'Lisbon (Portugal)', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 19 FROM public.book WHERE isbn13 = '9781860467226' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('250bd8f4-bf5d-5bac-b998-b9d82c43c267', '9781860467769', 'Independent People', 'oozqxQEACAAJ', 'Bjartus is a sheep farmer hewing a living from a blighted patch of land in Iceland. After 18 years of servitude to a master he despises, all he wants is to raise his flock unbeholden to anyone. Nothing, not inclement weather, not his wives, not his family will come between him and his goal of financial independence. Only Asta Solillja, the child he brings up as his daughter, can pierce his stubborn heart. But she too wishes to live independently - and when Bjartus throws her from the house on discovering she is pregnant, her more temperate determination is set against his stony will.', 'en', 1946, 544, 'http://books.google.com/books/content?id=oozqxQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6616', 'accepted', 'Halldór Laxness; J. Anderson Thompson', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 19 FROM public.book WHERE isbn13 = '9781860467769' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('24cfa76f-bbdc-5b9e-95ba-f63bc7757818', '9781860469015', 'Baltasar & Blimunda', 'VTUF8oX1tl0C', 'In early eighteenth-century Lisbon, Baltasar, a soldier who has lost his left hand in battle, falls in love with Blimunda, a young girl with visionary powers. From the day that he follows her home from the auto-da-fe where her mother is burned at the stake, the two are bound body and soul by love of an unassailable strength. A third party shares their supper that evening: Padre Bartolomeu Lourenco, whose fantasy is to invent a flying machine. As the Crown and the Church clash, they purse his impossible, not to mention heretical, dream of flight.', 'en', 2001, 346, 'http://books.google.com/books/content?id=VTUF8oX1tl0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
