INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('cc0394e0-ca8a-5c7a-9d80-cbf9de82a2ad', '9781860492914', 'Becoming a Mother', 'WKT1GwAACAAJ', 'Combining medical and historical information with real life accounts of ordinary women, this book is an essential guide to the facts, feelings and emotions experienced during pregnancy and birth. It takes you week by week, from the decision to conceive, through to first impressions of life with your baby, offering invaluable information. Topics include: Conception - If and When; Feelings for Your Growing Baby; Your Career and Financial Position; Fear that Something May Go Wrong; Changing Relationships with Family and Friends; Choosing Where and How to Give Birth; How Others Felt - Women Relate their Experiences; The First Few Days with Your Baby', 'en', 1997, 392, 'http://books.google.com/books/content?id=WKT1GwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6618', 'accepted', 'Kate Mosse', 'Childbirth', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 6 FROM public.book WHERE isbn13 = '9781860492914' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1ac01a78-c29d-5f6f-bab0-f3e6faac97b9', '9781860499296', 'Peyton Place', 'SoNkPgAACAAJ', 'Switch off those TVs, kill your mobiles and settle down with the most controversial book ever written. Once denounced as ''wicked'', ''sordid'', ''cheap'' ''moral filth'', PEYTON PLACE was the top read of its time and sold millions of copies worldwide. Way before TWIN PEAKS, SURVIVOR or BIG BROTHER, the curtains were twitching in the mythical New England town of Peyton Place, and this soapy story exposed the dirty secrets of 1950s small-town America: incest, abortion, adultery, repression and lust. Take a peek ...', 'en', 2002, 475, 'http://books.google.com/books/content?id=SoNkPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6619', 'accepted', 'Grace Metalious', 'City and town life', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 9, 15 FROM public.book WHERE isbn13 = '9781860499296' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2c0aa82d-92a2-5370-85ff-1f273214d63a', '9781860645884', 'Mary, Queen of Scots', '5XtL-F1LKUcC', 'Mary, Queen of Scots, was one of history''s most romantically tragic figures. Her endless plotting eventually led her to flee from Scotland and be imprisoned by her equally ambitious cousin and fellow queen--Elizabeth of England--who later ordered Mary to be beheaded in 1587. This book looks at her tragedy. of photos.', 'en', 2001, 224, 'http://books.google.com/books/content?id=5XtL-F1LKUcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6620', 'accepted', 'Jenny Wormald', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 10, 18 FROM public.book WHERE isbn13 = '9781860645884' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f4922c6c-3ce7-5423-b877-3239e8889340', '9781861891846', '''Photos of the Gods''', '8hhXq7hpzSwC', 'Drawing on years of archival research, interviews with artists and publishers, and the ethnographic study of their rural consumers, Christopher Pinney traces the intimate connections between the production and consumption of mass-produced images in India and the struggle against colonial rule.', 'en', 2004, 239, 'http://books.google.com/books/content?id=8hhXq7hpzSwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6621', 'accepted', 'Christopher Pinney', 'Art', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 16, 17 FROM public.book WHERE isbn13 = '9781861891846' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('daf1ae02-d905-514a-9924-17a9e87a5751', '9781861974426', 'Call of the Mall', 'wTxkHQAACAAJ', 'Like Underhill''s bestseller, Why We Buy, this is a pleasurable and informative book on how we shop that surprises and tickles. Like Bill Bryson''s Walk in the Woods, which took readers up the Appalachian Trail, this book takes readers to a place they know much better: the shopping centre, the place where people meet. Nothing exemplifies shopping more than the mall or shopping centre. It is the US''s gift to personal consumption and the crossroad where consumer marketing, media and street culture meet. It is where the developed world (and increasingly everyone else too) goes to acquire, eat and hang out. It is where fashion trends are made dreams are constructed, and many people find their first jobs. The Call of the Mall is about sex and buying lingerie, about why the same camel coat costs exactly twice as much in the women''s department to the men''s, about why all mall food is so dreadful when the commodities in the shops are so good. Why location matters so much - but more for perfumes than DIY and why malls are invariably such bad architecture. Underhill''s views on the mall are sophisticated, funny, serious, and surprising.', 'en', 2004, 227, 'http://books.google.com/books/content?id=wTxkHQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6622', 'accepted', 'Paco Underhill', 'Consumer behavior', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 19, 20 FROM public.book WHERE isbn13 = '9781861974426' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('03ad7d59-e56b-5f6e-a9f2-7e4b1229427c', '9781861977694', 'The Art of Seduction', 'ZePgwAEACAAJ', 'Which sort of seducer could you be: *Siren? *Rake? *Cold Coquette? *Star? *Comedian? *Charismatic? or *Saint? This book will show you which. ''Charm, persuasion, the ability to create illusions: these are some of the many dazzling gifts of the Seducer, the compelling figure who is able to manipulate, mislead and give pleasure all at once. When raised to the level of art, seduction, an indirect and subtle form of power, has toppled empires, won elections and enslaved great minds. In this beautiful, sensually designed book, Greene unearths the two sides of seduction: the characters and the process. Discover who you, or your pursuer, most resembles. Learn, too, the pitfalls of the anti-Seducer. In part II, immerse yourself in the twenty-four manoeuvres and strategies of the seductive process, the ritual by which a seducer gains mastery over their target. Understand how to ''Choose the Right Victim'', ''Appear to Be an Object of Desire'' and ''Confuse Desire and Reality''. In addition, Greene provides instruction on how to identify victims by type. Each fascinating character and each cunning tactic demonstrates a fundamental truth about who we are, and the targets we''ve become - or hope to win over. The Art of Seduction is an indispensable primer on the essence of one of history''s greatest weapons and the ultimate power trip.', 'en', 2004, 466, 'http://books.google.com/books/content?id=ZePgwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6623', 'accepted', 'Robert Greene', 'Seduction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 3 FROM public.book WHERE isbn13 = '9781861977694' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ecfddd3f-83da-5243-83c9-29dc56c20816', '9781861979339', 'Talk to the Hand', 'ds5TPgAACAAJ', 'Sticklers unite! The Queen of Zero Tolerance takes on the sorry state of modern manners, in the spirit of her three million copy worldwide bestseller, Eats, Shoots & Leaves. "Talk to the hand ''cause the face ain''t listening," the saying goes. When did the world get to be so rude? When did society become so inconsiderate? It''s a topic that has been simmering for years, and Lynne Truss says that it has now reached boiling point. Taking on the boorish behaviour that has become a point of pride for some, Talk to the Hand is a rallying cry for courtesy. Like Eats, Shoots & Leaves, Talk to the Hand is a spirited conversation, not a stuffy guidebook. It is not about forks, for a start. Why hasn''t your nephew ever thanked you for that perfect Christmas present? What makes your builder think he can treat you like dirt in your own home? When you phone a utility with a complaint (and have negotiated the switchboard), why can''t you ever speak to a person who is authorised to apologise? What accounts for the appalling treatment you receive in shops? Most important, what will it take to roll back a culture that applauds rudeness and finds it so amusing? For anyone who''s fed up with the brutality inflicted by modern manners (and is naturally too scared to confront the actual yobs), Talk to the Hand is a colourful call to arms - from the wittiest defender of the civilised world.', 'en', 2005, 214, 'http://books.google.com/books/content?id=ds5TPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6624', 'accepted', 'Lynne Truss', 'Conduct of life', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 3, 4 FROM public.book WHERE isbn13 = '9781861979339' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('3c9cc0a5-479b-5f98-b4b0-e0d52b765e98', '9781862073296', 'Rodinsky''s Room', 'aN7RhyhzJZYC', 'David Rodinsky lived above a synagogue in the heart of the old Jewish East End of London, and sometime in the late 1960s he disappeared. His room, a chaos of writings, annotated books and maps, gramophone records and clothes, was left undisturbed for 20 years. Rodinsky''s world captured the imagination of a young artist, Rachel Lichtenstein, whose grandparents had escaped Poland in the 30s, and over a period of years she began to document the bizarre collection of artifacts that were found in his room, and make installations using images from his enigmatic bequest. She became obsessed with this mysterious man: Who was he? Where did he come from? Where did he go? Now Lichtenstein and Iain Sinclair have written an extraordinary book that weaves together Lichenstein''s quest for Rodinsky. Part mystery story, part memoir, part travelogue, Rodinsky''s Room is a testament to a world that has all but vanished and the celebration of the life of a unique man.', 'en', 2000, 362, 'http://books.google.com/books/content?id=aN7RhyhzJZYC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6625', 'accepted', 'Rachel Lichtenstein; Iain Sinclair', 'Biography & Autobiography', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 7, 5 FROM public.book WHERE isbn13 = '9781862073296' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('aef6e89f-752b-5d66-8690-2032aa3a125e', '9781862073708', 'Out of Place', 'Zxm-QgAACAAJ', 'Edward Said was born in Jerusalem, and brought up in Cairo, spending every summer in the Lebanese mountain village of Dhour el Shweir, until he was "banished" to America in 1951. This work is a mixture of emotional archaeology and memory, exploring an essentially irrecoverable past. As ill health sets him thinking about endings, Edward Said returns to his beginnings in this personal memoir.', 'en', 2000, 295, 'http://books.google.com/books/content?id=Zxm-QgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
