INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('23a632ac-19a4-57ad-8df3-34502993e80b', '9781862074057', 'Moth Smoke', 'eGx8oQbjzjcC', 'Pakistan, Summer 1998: hot, with a late monsoon and the occasional nuclear test. In Lahore, Daru Shezad loses his job. While the jet set parties behind high walls, the economy crumbles and Daru''s electricity is cut off. Soon he has fallen for his best friend''s wife, started mixing heroin with his hash and joined forces with a criminal rickshaw driver. Moth Smoke is the story of Daru''s spectacular', 'en', 2000, 247, 'http://books.google.com/books/content?id=eGx8oQbjzjcC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
