INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('21ec7fe2-0f07-5452-ac9c-5bbf8625b226', '9781879794061', 'Best of the Eighties', 'G7JvDwAAQBAJ', 'This 96-page full color trade paperback features many of the most hilarious exploits of Archie and Friends''from the "ME" decade, better known as the Eighties. Computers! New age music! Urban cowboys! Preppies! E.T.! Roller boogie! Michael Jackson! Cabbage Patch Kids! Breakdancing! Trivial Pursuit! Music videos! It''s all here in this amazing volume!', 'en', 2001, 96, 'http://books.google.com/books/content?id=G7JvDwAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
