INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('544177ee-4884-5097-8686-5589f234e511', '9781880393338', 'Plato on Rhetoric and Language', 'dPEU-Zc29J0C', 'Collected here for the first time in one volume, four key Platonic dialogues-the Ion, the Protagorus, the Gorgius and the Phaedrus - serve as an important introduction to the productive ambiguities of Platonic thought on rhetoric and language. In her introduction to the volume, editor Jean Nienkamp considers Plato''s views on language, genre, and writing, and outlines the critical issues involved in the study of Platonic thought on rhetoric and poetics. Readers are invited to participate in the dialogues as vital philosophical conversations about issues that animate contemporary rhetorical and literary thought today.', 'en', 1999, 232, 'http://books.google.com/books/content?id=dPEU-Zc29J0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
