INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fd6e49ff-4c96-5c61-abd7-39233d001290', '9781880656419', 'Hayao Miyazaki', '4YPh2_D9q2EC', 'Artist-writer-director-producer Hayao Miyazaki is often called "the Walt Disney of Japan." His animated theatrical features have been smash hits in Japan, and many, including My Neighbor Totoro and Kiki''s Delivery Service, are already familiar to American audiences. Now, with Disney-Miramax''s imminent release of Princess Mononoke,, Miyazaki''s masterwork and one of the top-grossing film in all Japanese history, this "animation master" is about to take America and the world by storm. Mixing first-hand interview and personal insights with critical evaluations of art, plot, production qualities, and literary themes, McCarthy provides a film-by-film appraisal that examines technique as well as message. She reveals Miyazaki to be not just a master of the art of animation, but a meticulous craftsman who sees his work as a medium for shaping the humanistic and environmental concerns of our times. An overview of the artist and his early career is followed by in-depth examinations of seven major Miyazaki films: Nausicaä of the Valley of Wind, Laputa: Castle in the Sky, Castle of Cagliostro, My Neighbor Totoro, Kiki''s Delivery Service, Porco Rosso, and Princess Mononoke. Included are design and technical data, story synopses and character sketches, personnel and filmography data, and critical evaluation. Illustrations throughout, in color and black and white, show the detail and vigor of Miyazaki''s art. Written for anime fans as well as students of film, literature, and popular culture, McCarthy''s book raises animation criticism to a whole new level and is an essential guide to the work of a world-class filmmaker. London-based Helen McCarthy is author of Anime! A Beginner''s Guide to Japanese Animation, The Anime Movie Guide, and (with Jonathan Clements) The Erotic Anime Movie Guide. She appears frequently on radio and TV and at conferences around the world.', 'en', 1999, 240, 'http://books.google.com/books/content?id=4YPh2_D9q2EC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6639', 'accepted', 'Helen McCarthy', 'Art', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 2, 2 FROM public.book WHERE isbn13 = '9781880656419' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('abed057a-b993-5a44-b7e0-6ad689ade539', '9781880685358', 'Harrington on Hold ''em', 'u8y_9XdJaEMC', 'Provides poker strategies for every phase of tournament play, covering the early phase where the stakes are small to later tactics such as bluffing, flops, scare cards, playing shorthanded, loose games, and endgame play.', 'en', 2005, 450, 'http://books.google.com/books/content?id=u8y_9XdJaEMC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
