INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('676267a4-b446-5587-bddb-d67e444e4df6', '9781883398293', 'H. R. Giger''s Retrospective, 1964-1984', 'Fr40AQAAIAAJ', 'More than 150 artworks, spanning 20 years in the career of the world''s most renowned artist of the fantastical and the surreal, are gathered in one volume, rich with detail and color. Carefully rendered reproductions of Giger''s best paintings are accompanied by his own commentary. 70 color illus. 75 bandw illus. 25 bandw photos.', 'en', 1997, 112, 'http://books.google.com/books/content?id=Fr40AQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
