INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6bc5cc94-2a4a-5745-961a-984aa310cae8', '9781884365300', 'The Jungle', '4cY-vgAACAAJ', 'The horrifying conditions of the Chicago stockyards are revealed through this narrative of a young immigrant''s struggles in America, including five chapters omitted from the original edition.', 'en', 2003, 335, 'http://books.google.com/books/content?id=4cY-vgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
