INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7271c3d9-5f0f-50a5-b694-53157dacb7af', '9781885586421', 'The World of Jules Verne', 'VjkbAQAAIAAJ', 'Not strictly a biography of Jules Verne, it is a fascinating mix of anecdotes, extracts from the novels and real-life incidents. The reader re-encounters extraordinary characters like Phileas Fogg and Captain Nemo against a backdrop of marvellous illustrations.', 'en', 2006, 85, 'http://books.google.com/books/content?id=VjkbAQAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
