INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c5679dab-6b55-56e9-be05-0755ae5ba43e', '9781885865243', 'Through a Brazen Mirror', 'ajlbAAAAMAAJ', 'Through a Brazen Mirror is the third book in The Ultra Violet Library, Circlet''s imprint of fantasy and science fiction by/for/about lesbian/gay/bi folk. Originally published in 1989 by mass market publisher Ace, the book was marketed as generic sword and sorcery and, in the way of mass market books, disappeared from sight shortly thereafter, before it had a chance to reach an audience who would appreciate its themes. Based on an ancient Anglo-Scots ballad called "The Famous Flower of Serving Men" (a magical, tragic tale about a young woman who disguises herself as a man after the murder of her husband), Through a Brazen Mirror tells the tale of the witch Margaret, her daughter Elinor, King Lionel, and the extraordinary William Flowers, who saves the king from doom and Margaret''s malevolent magic. With much richness of detail and folklore, Sherman uses the tale to explore issues of attraction, loyalty, and gender identity. For William is Elinor, who as William bonds with the young king and takes charge of a fate that was to be her undoing. The book, though it takes place in a fictional kingdom, is no cleaned-up fairy tale, and presents a historical picture of life circa 1400. In an age when women are not taught to read or write, both Margaret, as an evil schemer, and Elinor, who must take on a man''s name and countenance, fight for their self-determination, each in her own way.', 'en', 1999, 100, 'http://books.google.com/books/content?id=ajlbAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6652', 'accepted', 'Delia Sherman', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 17, 0 FROM public.book WHERE isbn13 = '9781885865243' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6096a6f1-4d7b-5d0c-9829-df2d5ac6ae97', '9781885972101', 'Uncle Setnakt''s Essential Guide to the Left Hand Path', 'jjfWAAAACAAJ', 'The Essential Guide opens the door to the darkly resplendent worlds of the Left Hand Path. Part philosophical treatise, part ontological stand-up comedy, and part magical practicum, this book makes clear what many other books have only hinted at. For people with wit and perseverance, this book is a training manual for super-men and women. Don Webb has been a practitioner of the Left hand path since the 1970s. He is the former High Priest of the Temple of Set, the world''s largest Left Hand Path organization, and the author of the best-selling Seven Faces of Darkness.', 'en', 1999, 128, 'http://books.google.com/books/content?id=jjfWAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
