INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6a1e0ab4-0c2d-554c-9b69-23a0c835324b', '9781886363069', 'Charles Dickens as a Legal Historian', '1_WdLFxkx6kC', 'Holdsworth, William S. Charles Dickens as a Legal Historian. New Haven: Yale University Press, 1929. 157 pp. Reprinted 1995 by The Lawbook Exchange, Ltd. LCCN 96-46579. ISBN 1-886363-06-4. Cloth. $40. * "The distinguished English historian, Professor Holdsworth, has contrived even during his moments of recreation to render us his debtors. No two books outside the bounds of technical law are more worth reading for law students than Pickwick Papers and Bleak House. Even a trained trial lawyer however, is puzzled by some of the legal points brought up by Dickens, because they have fortunately passed forever out of the realm of living law. Professor Holdsworth has performed a valuable service to lawyers and laymen alike in explaining these obscurities. And he has done much more than this. He has increased our admiration for the genius of Dickens by proving his great merit as a legal historian.": Zechariah Chafee, Jr. Harvard Law Review 42:286-8.', 'en', 2010, 166, 'http://books.google.com/books/content?id=1_WdLFxkx6kC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6654', 'accepted', 'William Searle Holdsworth', 'History', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 5, 6 FROM public.book WHERE isbn13 = '9781886363069' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('83dee50f-aaa4-5376-8d98-0ee7fae44651', '9781887178945', 'The Dancing Girl of Izu and Other Stories', 'TvE_tAEACAAJ', 'One of the most influential figures in modern Japanese fiction, Yasunari Kawabata is treasured for the intensity of his perception and the compressed elegance of his style. This new collection includes twenty-two stories now appearing in English for the first time in book form. Written between 1923 and 1929, these short fictions form a shadow biography of the author''s early years, and provide fresh glimpses of Kawabata''s haunting and haunted vision. Born in 1899, Kawabata committed suicide at age seventy-two. Throughout his life he was concerned with themes of loss, longing, and memory. His childhood was repeatedly shaken by deaths in the family - first his parents when he was three, then a grandmother, an older sister, and finally the blind grandfather he cared for in his early adolescence. These personal losses linger as motifs in such remarkable stories as "Gathering Ashes" and "The Master of Funerals." The stark physical details of caregiving - suffused with edgy resentment and desperate fear - are remembered in "Diary of My Sixteenth Year." In addition to the twenty-two stories unknown to American readers, this collection features the first translation of the complete text of the classic "Dancing Girl of Izu." This unforgettable story portrays the tender anxiety of a young man whose brooding fascination with a pubescent girl nudges him along the path toward adulthood.', 'en', 1998, 176, 'http://books.google.com/books/content?id=TvE_tAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
