INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('e4170f8a-7f74-5ded-b25f-d22bdc3200c5', '9781888690088', 'Tal-Botvinnik 1960', 'PtDUMQEACAAJ', 'In 1960 Mikhail Tal defeated chess champion Mikhail Botvinnik in one of the most celebrated world championship matches of all time. In this volume, Tal sets the stage and explains every one of the 21 games, telling both the on- and off-the-board story of this clash of styles and thought.', 'en', 2000, 220, 'http://books.google.com/books/content?id=PtDUMQEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
