INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6f19ce05-366b-503a-b252-81b14a98425a', '9781888996289', 'To America with Love', 'VQlkPwAACAAJ', 'The author and her husband, noted activist Abbie Hoffman, share the letters they exchanged in 1974 and 1975 while Abbie was in hiding to avoid imprisonment.', 'en', 2000, 224, 'http://books.google.com/books/content?id=VQlkPwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 6, 6, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
