INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ba6f28ef-f6f9-513f-93a5-7ac83332476a', '9781889032207', 'Teach Them Diligently', 'VHL3AQAACAAJ', 'The bookshelves in your home no doubt contain volumes of books, manuals, seminar notes, magazine articles, and video and audio cassettes purporting to address parenting from a Christian point of view. With rare exception, however, most of today''s Christian parenting resources fail to emphasize what is perhaps the most important aspect of true biblical parenting -- how to relate the Bible to the disciplinary process in practical ways. Think about it. With all of your training, do you really know how to use the Bible for doctrine, reproof, correction, and instruction in righteousness with your children? If you do, read no further. If you don''t, this little book will augment and strengthen your parenting skills as you learn how to use the scriptures more thoroughly and effectively in your child training. - Back cover.', 'en', 2000, 162, 'http://books.google.com/books/content?id=VHL3AQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6663', 'accepted', 'Louis Paul Priolo', 'Religion', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 8, 11 FROM public.book WHERE isbn13 = '9781889032207' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a2f99c5a-18c3-5bd3-a07f-56916867f8bb', '9781889963853', 'Not Just a Pretty Face', '_3Pn-oDS850C', 'Now in a full-color second edition, Not Just a Pretty Face is an engaging exploration of the role of dolls and doll making in Alaska Native cultures. From ancient ivory carvings to the thriving tourist market, dolls and human figurines have played integral parts in the ritual, economic, and social lives of Native Alaskans. Dolls served as children’s playthings, represented absent community members at ceremonies, and predicted the movements of game animals for shamans. Not Just a Pretty Face surveys these and other uses of dolls and figurines, illustrating in beautiful color photographs the diversity of the doll-making tradition in Eskimo, Athabaskan, and Northwest Coast Native communities. Authors explore the ethnographic literature, twentieth-century oral histories, and photographic documentation of dolls and the doll-making process. Contemporary doll makers explain, in their own words, how they learned to make dolls and what doll making means to them. The second edition features a photo essay on Rosalie Paniyak of Chevak, one of the most influential doll makers in Alaska today. Not Just a Pretty Face provides a panoramic view of an ancient tradition and situates the art of doll making within a contemporary context. Scholarly, yet accessible, Not Just a Pretty Face is a lively contribution to the literature on dolls, anthropology, and Native studies.', 'en', 2006, 80, 'http://books.google.com/books/content?id=_3Pn-oDS850C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6664', 'accepted', 'Molly Lee', 'Antiques & Collectibles', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 12 FROM public.book WHERE isbn13 = '9781889963853' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bccc01e3-b8d9-5c4e-8c44-31b5b77929da', '9781890159191', 'The Mistress Manual', 'DjOZv-ZM-V0C', 'Originally published in 1994 in a simple pink guidebook format by an experienced and wickedly creative dominant woman, The Mistress Manual fell out of print when the author moved on to other projects. Now, Greenery Press has brought this underground classic back to life, updated with new ideas and information on ''Learning to Love Command'' to ''The Art of Discipline''. Learn how to enact the Five Archetypal Fantasies, how to create your own scenarios and much, much more.', 'en', 2000, 220, 'http://books.google.com/books/content?id=DjOZv-ZM-V0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
