INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7a2a2be8-3b12-51e7-9924-33199f0df453', '9781890208288', 'My Sister''s Keeper', 'VBSEAQAACAAJ', 'Though separated from her lover, a Scotland Yard man, Gillian Adams hasn''t lost her sleuthing skills. Sexism has reared its ugly head in attacks on the Feminist ("Eff Yours") Union at the University of the Pacific Northwest in Vancouver, and a woman is found dead on campus. Adroitly plotted and filled with intrigue, "My Sister''s Keeper" solves the crimes but leaves open the mystery of Gillian, who is poised between her career as head of history department and her romance in England.', 'en', 2000, 228, 'http://books.google.com/books/content?id=VBSEAQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6666', 'accepted', 'Nora Kelly', 'Fiction', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 13 FROM public.book WHERE isbn13 = '9781890208288' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6c8ae533-71f6-5df0-94ec-436c71c20265', '9781890447168', 'Change Or Die', 'R9kiPQAACAAJ', 'The most important new literary journal to emerge since Granta, Open City has published some of the best work by major writers and artists such as Mary Gaitskill, Denis Johnson, Jeff Koons, David Foster Wallace, Irvine Welsh, Terry Southern, Patrick McCabe, Sam Lipsyte, and David Berman. Edited by the writers Thomas Beller and Daniel Pinchbeck and originally published by the late Robert Bingham, writing from Open City has been included in many prestigious anthologies, including Best American Short Stories and The Pushcart Prize. Known for launching the careers of today''s best new writers, the editors are also committed to printing important unpublished work by writers from past eras, such as Richard Yates, Delmore Schwartz, Jim Thompson, Cyril Connolly, Edvard Munch, and Gregor von Rezzori. With its innovative and daring mix of the old and the new, Open City combines undiscovered writing by classic authors with a fascinating portrait of a literary generation in the making.Open City #12 includes After the Wall, a special section on Berlin''s new generation of fiction writers; a story by Lewis Cole on the end of radicalism; and debut fiction by Sam Brumbaugh and Heather Lorimer. This issue features a previously unpublished story by Ford Maddox Ford.', 'en', 2000, 234, 'http://books.google.com/books/content?id=R9kiPQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6667', 'accepted', 'David Foster Wallace; Mary Gaitkill; Irvine Welsh; David Berman; Delmore Schwartz', 'American literature', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 12, 17 FROM public.book WHERE isbn13 = '9781890447168' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f3bef8e3-dfc7-5f44-8c0b-948bbbeb6beb', '9781890447175', 'Open City 6', 'J376GwAACAAJ', 'The most important new literary journal to emerge since Granta, Open City has published some of the best work by major writers and artists such as Mary Gaitskill, Denis Johnson, Jeff Koons, David Foster Wallace, Irvine Welsh, Terry Southern, Patrick McCabe, Sam Lipsyte, and David Berman. Edited by the writers Thomas Beller and Daniel Pinchbeck and originally published by the late Robert Bingham, writing from Open City has been included in many prestigious anthologies, including Best American Short Stories and The Pushcart Prize. Known for launching the careers of today''s best new writers, the editors are also committed to printing important unpublished work by writers from past eras, such as Richard Yates, Delmore Schwartz, Jim Thompson, Cyril Connolly, Edvard Munch, and Gregor von Rezzori. With its innovative and daring mix of the old and the new, Open City combines undiscovered writing by classic authors with a fascinating portrait of a literary generation in the making. Open City #12 includes "After the Wall", a special section on Berlin''s new generation of fiction writers; a story by Lewis Cole on the end of radicalism; and debut fiction by Sam Brumbaugh and Heather Lorimer. This issue features a previously unpublished story by Ford Maddox Ford.', 'en', 2000, 200, 'http://books.google.com/books/content?id=J376GwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
