INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0c04b5a8-d5bf-59c3-91ae-10546199704a', '9781890447427', 'Mother''s Milk', 'o8lY2W-OzzQC', 'The author of Some Hope returns with a story of complex family relationships, offering a trenchant novelistic analysis of marriage, adultery, parenthood, and assisted suicide.', 'en', 2005, 240, 'http://books.google.com/books/content?id=o8lY2W-OzzQC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 18, 18, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
