INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c958532a-1b44-5bbb-8e6d-adb89e3c5cfd', '9781890771485', 'Lands of Promise and Despair', 'q7e5opHZO7IC', 'This volume is a collection of primary documents of the writings of early California settlers. Taking the point of view of the Indians, settlers, missionaries, soldiers, and others who lived there, the editors offer letters, reports, reminiscences, and other documents that tell the inside story of California before the Gold Rush, from the time the Spanish arrived in the 1530s until the end of California''s experience as a territory in the Mexican republic in the 1840s. This work is illustrated with maps, portraits, sketches, and early photographs as well as seven color plates of drawings depicting plant and animal life made by an 18th-century Czech priest.', 'en', 2001, 506, 'http://books.google.com/books/content?id=q7e5opHZO7IC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
