INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7414756d-244c-5bd0-b210-6b4937d13fc2', '9781890995522', 'The Diamond Color Meditation', '1ChsHQAACAAJ', 'The Diamond Color Meditation presents an inspiring use of color in a therapeutic meditation that is designed for relaxation, deep personal growth, and healing. As you discover the power of each color, you will experience the healing effect it has on your mind, body, and soul. Going far beyond traditional color therapies, this book introduces a completely original concept that uses color to evoke the only true ealing--that which begins from within.', 'en', 2006, 74, 'http://books.google.com/books/content?id=1ChsHQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 4, 4, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
