INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('bd0999b4-b9d1-530d-a0b7-1120fab0b5a8', '9781891190230', 'City Eclogue', 'IGaxAAAAIAAJ', 'Poetry. African American Studies. Ed Roberson might no longer live in Pittsburgh, but the city in which he was born and raised still leaves its fragmented structures etched throughout his poetry. A city of hard work and hard times, the now-impoverished neighborhoods that had at one time stood as centers of jazz and art; the hills, the rivers, the skyscraping iron and steel, and the pain. Though most of the poems in this collection do not necessarily take place in Pittsburgh, there is a rhythmic fragmentation here painting portraits of urban life in general. Beauty, music, poverty, blood, and concrete seem to live within the line breaks, while breath-stopping pauses halt you just long enough so that--like at a smoky backroom jazz club--you can''t wait to see what he does next.', 'en', 2006, 136, 'http://books.google.com/books/content?id=IGaxAAAAIAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
