INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c032f187-c192-5227-a583-ad67db2ea9ed', '9781891620416', 'White Widow', '4vs4swEACAAJ', 'Praised by the New York Times Book Review as "an...affecting morality tale," Jim Lehrer''s devastating White Widow brings the reader to the brink of one man''s unstoppable, ruinous passion for a complete stranger. Jack T. Oliver has a solid marriage, a cozy house in Corpus Christi, and a job he loves as a driver for the Great Western Trailways bus line. In a few weeks, Jack is going to be promoted to Master Operator in recognition of his years of perfect service and on-time driving. It''s a good life. Until a White Widow boards his bus, on a one-way ticket from Victoria to Corpus Christi. A White Widow is a wild card, a woman traveling alone who can change the course of a driver''s life, and not always for the best. What happens when Jack Oliver''s White Widow passes through his life is as unforgettable as it is irrevocable. Within weeks, without ever even learning her name, he will fall passionately in love—and lose everything he has, a few things he never had, and some he never thought about until they were gone.', 'en', 2000, 224, 'http://books.google.com/books/content?id=4vs4swEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
