INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('aeab77a7-5afd-5fe0-a3fa-9029a250efea', '9781892389381', 'The State of the Art', 'AGRBvgAACAAJ', 'Iain M. Banks'' only short-story collection, never before published in the US. Contents: * Road of Skulls * A Gift from the Culture * Odd Attachment * Descendant * Cleaning Up * Piece * The State of the Art * Scratch * A Few Notes On the Culture Skyhorse Publishing, under our Night Shade and Talos imprints, is proud to publish a broad range of titles for readers interested in science fiction (space opera, time travel, hard SF, alien invasion, near-future dystopia), fantasy (grimdark, sword and sorcery, contemporary urban fantasy, steampunk, alternative history), and horror (zombies, vampires, and the occult and supernatural), and much more. While not every title we publish becomes a New York Times bestseller, a national bestseller, or a Hugo or Nebula award-winner, we are committed to publishing quality books from a diverse group of authors.', 'en', 2005, 188, 'http://books.google.com/books/content?id=AGRBvgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
