INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6b9a3cf7-1aec-5064-981c-2da373552291', '9781892391209', 'Her Smoke Rose Up Forever', 'h6icnOdHfhoC', 'These 18 darkly complex short stories and novellas touch upon human nature and perception, metaphysics and epistemology, and gender and sexuality, foreshadowing a world in which biological tendencies bring about the downfall of humankind. Revisions from the author''s notes are included, allowing a deeper view into her world and a better understanding of her work. The Nebula Award?winning short story Love Is the Plan, the Plan Is Death, the Hugo Award?winning novella The Girl Who Was Plugged In, and the Hugo and Nebula Award?winning novella Houston, Houston, Do You Read? are included.', 'en', 2004, 508, 'http://books.google.com/books/content?id=h6icnOdHfhoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
