INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('48148672-f8b4-5b7d-8ab3-c73280d4120c', '9781892395566', 'International Building Code 2003', '_opUAAAAMAAJ', 'The 2003 International Building Code addresses the design and installation of building systems through requirements that emphasize performance, providing minimum regulations for building systems using prescriptive- and performance-related provisions, including structural as well as fire- and life-safety provisions covering seismic, wind, accessibility, egress, occupancy, roofs, and more.', 'en', 2002, 656, 'http://books.google.com/books/content?id=_opUAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 13, 13, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
