INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('95a758d9-2d42-546a-a5fb-74378c881976', '9781894917124', 'The Devil''s in the Details', 'YoPY1-njfTIC', 'The news that an old acquaintance has had an accident comes as a surprise to Camilla MacPhee. By the time she unearths Laura''s connection to a violent revolutionary group active two decades earlier, she''s had several blows to the head and discovered that people shes been talking to keep ending up dead.', 'en', 2004, 320, 'http://books.google.com/books/content?id=YoPY1-njfTIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
