INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('f76077a6-4c87-570f-9178-20e19edbd7c9', '9781895176407', 'Galapagos, a Natural History', 'NXS8cwtMaGwC', 'This book details the natural history of the plants and animals found in the Galapagos Islands. A list of the dominant plants according to vegetation zone is included. Of particular note is the discussion of the problems of colonisation by founding populations, biological evolution, and ecology, and of the evolutionary processes bringing about species diversity.', 'en', 1993, 336, 'http://books.google.com/books/content?id=NXS8cwtMaGwC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
