INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0e562f03-ce8d-5d97-8aeb-19dfa8f2181e', '9781896597669', 'Acme Novelty Datebook, Volume One', '2my-tgEACAAJ', 'Acclaimed cartoonist Chris Ware reveals the outtakes of his genius in these intimate, imaginative, and whimsical sketches collected from the years during which he completed his award-winning graphic novel Jimmy Corrigan: The Smartest Kid on Earth (Pantheon). His novel not only won the Manchester Guardian First Novel prize in 2001 but it has sold over 100,000 copies. This book is as much a companion volume to Jimmy Corrigan --one of the great crossover success stories-- as a tremendous art collection from of one of America''s most interesting and popular graphic artist. Chris Ware has a passion for drawing that is surprisingly wide-ranging in style and subject. This book surprises the reader on every page with its sense of spontaneous vision. Architectural drawings from Chicago and interplanetary robot comics collide with cruelly doodled human figures and quietly troubling studies of the still life. A must for people with a passion for modern design and old-fashioned style.', 'en', 2013, 208, 'http://books.google.com/books/content?id=2my-tgEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 11, 11, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
