INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('20c15a55-8e99-57f3-886f-047124838d36', '9781898573456', 'Everest', 'yYs8PgAACAAJ', 'In 1978 Messner and Habeler became the first to make a successful ascent and descent of Everest without using supplementary oxygen. This is Messner''''s account of this landmark in the history of human physical endeavour.''', 'en', 1999, 286, 'http://books.google.com/books/content?id=yYs8PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
