INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1309d400-fa6f-5989-ad64-20c9b52905b4', '9781903252048', 'The Elephant War', 'kvX7AQAACAAJ', 'Based on a true incident in 1882, this gentle satire set in Victorian England is the story of how Aunt Louisa, young Harriet, and others protest against Jumbo''s tour of America. Jumbo is "the elephant friend of all England''s children", and they''re determined to keep him there.', 'en', 2000, 256, 'http://books.google.com/books/content?id=kvX7AQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 3, 3, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
