INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('48b2cb3d-12fc-53ef-9b3d-9cbefbc06036', '9781904271550', 'Hamlet: The Texts of 1603 and 1623', 'rGFlAAAAMAAJ', 'This second volume gives readers the First Quarto text of 1603 and The Folio Text of 1623, fully modernised and edited to the usual Arden standard. A companion to the core volume, it will be of particular interest to scholars and students of textual history, or to anyone studying Hamlet at an advanced level. Both play texts are fully edited and collated and the volume has a full Introduction which gives special attention to the 1603 First Quarto text This second volume gives readers the First Quarto text of 1603 and The Folio Text of 1623, fully modernised and edited to the usual Arden standard. A companion to the core volume, it will be of particular interest to scholars and students of textual history, or to anyone studying Hamlet at an advanced level. Both play texts are fully edited and collated and the volume has a full Introduction which gives special attention to the 1603 First Quarto text', 'en', 2006, 384, 'http://books.google.com/books/content?id=rGFlAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
