INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('455c559c-1142-563b-95bb-c49a0045ce7a', '9781904316343', 'Judas Pig', 'coAEAAAACAAJ', 'Billy Abrahams is a career criminal who makes a very good living from violence, armed robbery, sex shops, and theft from other criminals. But he becomes increasingly haunted by childhood ghosts and by the ever-growing influence of Danny, his psychopathic partner in crime. Billy finds himself starting to look beyond the violence and the scams, slowly descending into a drug-fuelled netherworld that affects his judgment and his perceptions. He is finally tipped over the edge when Danny commits an act even Billy cannot stomach. And that''s when things really start to go wrong. This explosive first novel from a reformed career criminal comes with authenticity stamped throughout.', 'en', 2004, 345, 'http://books.google.com/books/content?id=coAEAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 2, 2, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
