INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('fa0d2967-8588-5c0e-88d6-2a4819d57411', '9781905177042', 'A Midwife''s Story', 'hnbrAwAAQBAJ', 'When hospital-trained midwife Penny Armstrong takes on a job delivering the babies of the Amish, she discovers an approach to giving birth which would change her life forever. A Midwife''s Story is a life-affirming book that never fails to enlighten, inform and surprise. Honest and ultimately very moving, it is inspirational reading for all student midwives and expectant parents.', 'en', 2006, 194, 'http://books.google.com/books/content?id=hnbrAwAAQBAJ&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
