INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('811230fb-1386-54da-888a-351703e6ebf5', '9781928832430', 'Aquinas''s Shorter Summa', '1brEAQAAQBAJ', 'From the Church''s greatest theologian: the essentials of Catholic doctrine. This book contains Aquinas''s simple summary of the Faith. He covers the Trinity, Providence, the Incarnation, the Last Judgment, and much more. It''s a concise statement of the key doctrines and elements of the Faith.', 'en', 2002, 412, 'http://books.google.com/books/content?id=1brEAQAAQBAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
