INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('c692c264-ce73-5fa1-8881-930c74ac241f', '9781930846456', 'The Jennifer Morgue', 'IygxAAAACAAJ', 'Bob Howard is a special operative for the British agency called The Laundry, and his task is to stop a rogue billionaire from using an artifact, known as Gravedust, with the power to reanimate the dead. The U.S. Black Agency sends the lethal Ramona Random to aid Bob''s mission, but she seems to have a different agenda', 'en', 2006, 313, 'http://books.google.com/books/content?id=IygxAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
