INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('a246b4cd-1cb7-53c4-94c8-be738be68ec9', '9781931615037', 'Answers to Questions Teachers Ask about Sensory Integration', '3_9kPgAACAAJ', 'In this elegant approach to the often elusive subject of sensory integration, Kranowitz, author of the bestselling "The Out-of-Sync Child," and expert occupational therapists present an extensive and easy-to-use set of checklists and other tools that are invaluable to every teacher and parent who has children with sensory integration challenges.', 'en', 2001, 63, 'http://books.google.com/books/content?id=3_9kPgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 10, 10, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
