INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6da60a70-032b-5b03-a10c-5a0e35ae77d8', '9781932073201', 'Way of the Peaceful Warrior', 'NEU-1RfOMEwC', 'Presents the author''s personal account of his spiritual quest to unite the diverse realms of body, mind, and spirit by combining Eastern philosophy with Western fitness routines to become an example of the peaceful warrior.Now a major motion picture from Lionsgate starring Nick Nolte.', 'en', 2006, 240, 'http://books.google.com/books/content?id=NEU-1RfOMEwC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
