INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('4540bf8b-33af-56c4-bd11-d0105baf5178', '9781932206081', 'Insights', 'NOX2PgAACAAJ', 'In 1983, when Rama - Dr. Frederick P. Lenz recorded a series of profound and powerful talks entitled Insights: Talks on the Nature of Existence. This book is a transcript of those talks. Rama was instructing an ever-growing number of students. Dr. Lenz himself was developing an approach to self-realization that, while emphasizing meditation and enlightenment, drew from a variety of traditions including Vedanta, Tibetan Buddhism and the American mystic teachings described by Carlos Castaneda. The Insights talks, which evolved from this time period, are like a crest jewel of Dr. Lenz''s body of teachings. It is interesting to note that most of the Insights talks are subtitled "Modular Mysticism" (for example, "Modular Mysticism: The Truth"). Even the talk titled "How to Make Friends with God" - discussed in depth only in this series - is termed a part of "Modular Mysticism." In the practice of mysticism, Dr. Lenz explains, the student begins to understand awareness and power. Modular mysticism becomes the science of power, and the student learns to gain power, to stop losing power, to store power, and eventually to give power to others. In order to gain power, the student begins to lead an efficient and well-structured life. As the student accomplishes this, they are able to move more easily through the doorways to enlightenment. At each step along the journey of the Insights talks, Dr. Lenz gives specific examples of how to adapt and integrate mystical Buddhist practice into a Western lifestyle. For Dr. Lenz there was no contradiction between being a successful Westerner and a successful Buddhist, be it building a career, working out at the health club, going to the movies, shopping for clothes -- or understanding why more women don''t attain enlightenment (when, in fact, it''s easier for them to do so). In every instance, Dr. Lenz connects the heights of the mystical experiences directly to our everyday lives.', 'en', 2003, 304, 'http://books.google.com/books/content?id=NOX2PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 20, 20, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6738', 'accepted', 'Frederick Lenz', 'Spiritual life', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 6, 12 FROM public.book WHERE isbn13 = '9781932206081' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('5dcbc576-aacc-5e47-8bff-94ba296a3584', '9781932206104', 'How to Meditate', 'HhTVAAAACAAJ', 'How to Meditate is a transcript all of Rama''s, Dr. Frederick Lenz recorded talks on meditation. It also includes his book of lyrical poetry : "The Bridge is Flowing but the River is Not." How to Meditate provides a full range of meditation techniques, knowledge and wisdom to deepen meditation practice and understand meditation''s essential role in daily life. This volume is excellent for both newcomers and longtime meditators. Open the book at any time to any page, and you will receive your daily quota of inspiration.', 'en', 2004, 228, 'http://books.google.com/books/content?id=HhTVAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 5, 5, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
INSERT INTO public.book_source (book_id, source_row_id, row_status, authors, categories, total_copies_formula, available_copies_formula, cached_total_copies, cached_available_copies) SELECT id, '6739', 'accepted', 'Frederick Lenz', 'Meditation', '=RANDBETWEEN(0,20)', '=RANDBETWEEN(0,20)', 14, 8 FROM public.book WHERE isbn13 = '9781932206104' ON CONFLICT DO NOTHING;
INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('7ec3a10e-2dac-5e44-964a-25c3fe2e5f47', '9781932234299', 'Birthday', '2rEwAAAACAAJ', 'Basis of the Hit Movie Ring 0: Birthday! Birthday is Ring-master Koji Suzuki’s return to the Ring universe, a collection of short stories focusing on the female characters with a theme of birth. An exploration of extraordinary circumstances from the perspective of memorable women, this expansion of the Ring, Spiral, and Loop world was adapted into a hit movie less than a year after the book’s publication. Thirty years before the tragic events of Ring, Sadako Yamamura was an aspiring stage actress on the verge of her theatrical debut. The beautiful and ravishing Sadako was the object of every male’s desire involved with the company including n the director. There was one thespian she was interested in, but… Fast forward past the events of Ring, Ryuji Takayama’s distraught lover, Mai Takano is struggling in the wake of the professor’s mysterious demise. Mai visits Ryuji’s parents’ house to find the missing pages of his soon-to-be published article. There she is drawn to a curious videotape and a fate more terrifying than Ryuji or Kazuyuki Asakawa’s. Reiko Sugiura questioned the purpose of bringing a child into a world where there was only death. She already lost one son, and the father of her unborn child, Kaoru Futami, had disappeared in search of a cure to the deadly disease that threatened all life. Despite Kaoru’s to meet again in two months, he has not returned. Despondent but driven for answers Reiko is led to the Loop project, where she will discover the final truths of the Ring virus.', 'en', 2006, 216, 'http://books.google.com/books/content?id=2rEwAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
