INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('945388f8-84bd-5ae9-b6d2-ccce222dcc8b', '9781932361278', 'There''s No Toilet Paper... on the Road Less Traveled', 'Bi0XAQAAMAAJ', 'A compendium of humorous travel writing includes contributions from Bill Bryson, Steve Martin, Dave Barry, Art Buchwald, David Letterman, Paul Theroux, and others, presenting stories about everything from surviving in a nudist camp to learning how to use an ice-sheet outhouse in Antarctica. Original.', 'en', 2005, 216, 'http://books.google.com/books/content?id=Bi0XAQAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
