INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('9a05daeb-e933-54d5-b9cc-aef148559392', '9781932382600', 'Richard Matheson''s Hell House', 'plkKAAAACAAJ', 'Now, IDW brings you a lavishly illustrated adaptation of this tale of newspaper publisher Rudolph Deutsch facing his impending demise. To help Deutsch forestall this and learn the secrets of life after death, a hired team of experts must survive a night in Belasco House, a place known amongst the local townsfolk as Hell House!', 'en', 2004, 48, 'http://books.google.com/books/content?id=plkKAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 9, 9, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
