INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6799c608-fde2-5af1-bdd6-f4058087502e', '9781932382723', 'Hell House', 'p1kKAAAACAAJ', 'The notorious Belasco House starts to exert its dark influence on the group of scientists and spiritualists as they unearth the perverse and wretched secrets from within its walls. Hell House has let them in but will it ever let them leave? IDW''s adaptation of Richard Matheson''s classic tale of terror continues here!', 'en', 2005, 48, 'http://books.google.com/books/content?id=p1kKAAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
