INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2d0c6ad4-7729-54ef-86ce-ca47b1cd7a70', '9781932416770', 'McSweeney''s', 'o7cuHQAACAAJ', 'With a special section on Donald Barthelme, including remembrances from Ann Beattie, David Gates, and Oscar Hijuelos, and some of Barthelme''s barely published and never-collected early work, and a highly theoretical but potentially amazing Z-binding that we can''t describe very well here, or even to each other, McSweeney''s 24 will never be mistaken for anything else. (Except possibly the June 1978 issue of Popular Mechanics.)', 'en', 2007, 300, 'http://books.google.com/books/content?id=o7cuHQAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 19, 19, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
