INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1b656df5-9c76-59cd-ba6c-0f8d62641115', '9781932664591', 'Wasteland Vol. 1', '8K7CPAAACAAJ', 'A hundred years after the Big Wet, Earth has been left a broken, infertile world of rock and sand. The town of Providens is like many others on the post-Big Wet planet—small, mostly illiterate and struggling for survival. But while most communities are like Providens, not all the cities that survived the Big Wet are. Some are like Newbegin, burgeoning metropolises that combine pieces of past societies with the new status quo. When Providens welcomes a stranger named Michael into its midst, will the quiet man lead them to the better world of Newbegin or shatter what little order still exists?', 'en', 2010, 160, 'http://books.google.com/books/content?id=8K7CPAAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
