INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('d4e65f5b-627e-5e67-99a7-3cd431918418', '9781933110455', 'Carly''s Sound', 'vAvDwAEACAAJ', 'Is passion still possible the second time around? Poppy Valente has the world in the palm of her hand until fate steals from her the one thing that matters most--her wife Carly. When breast cancer ends their life together, Poppy finds herself at a loss. Julia Johnson is running to Carly''s Sound with her newborn daughter Tallulah in search of the path to her future. On a chance meeting two years after Carly''s death, these two women form a bond of friendship that lays the foundation for something more.', 'en', 2006, 212, 'http://books.google.com/books/content?id=vAvDwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
