INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('2394e468-e9b8-5d5c-9292-bb8274e44aae', '9781933368368', 'The Good Fairies of New York', 'XbspqbaIgy0C', 'Finding themselves in the very unusual world of Manhattan, a pair of Scottish thimble fairies apply their folk wisdom to assist a pair of down-and-out humans, including Kerry, who struggles with a colostomy bag, and Dinnie, who exhibits anti-social behaviors. Original.', 'en', 2006, 242, 'http://books.google.com/books/content?id=XbspqbaIgy0C&printsec=frontcover&img=1&zoom=1&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
