INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1fe929ef-90dd-5223-93c9-5ce2498e1104', '9781933372198', 'Amazing Disgrace', 's7jyAAAAMAAJ', 'In this sequel to the popular Cooking with Fernet Branca, Gerald Samper is back on his Tuscan hilltop and busily musing on the absurdities of modern life. His entertaining asides - on everything from publishing to penile implants, celebrity sportswomen to Australian media moguls - and his eccentric recipes form the comic heart of this literary romp. Marta, Gerald''s nemesis in Cooking with Fernet Branca, is back, along with her penchant for the eponymous potent liquor and her talent for shattering Gerald''s evening idylls. But she''s not alone: Amazing Disgrace touts a cavalcade of memorable characters, including a foul-mouthed, one-armed yachtswoman, and sees Gerald jettisoned from his Tuscan hideaway into the trendy haunts of his native London.', 'en', 2006, 320, 'http://books.google.com/books/content?id=s7jyAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 17, 17, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
