INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('248a6756-299e-5255-93b7-3e6824e36168', '9781933633107', 'Sister Bernadette''s Barking Dog', 'LItiAAAAMAAJ', 'In this illustrated personal history, Kitty Burns Florey explores the rise and fall of sentence diagramming, including its invention by a mustachioed man named Brainerd ''Brainy'' Kellogg and his wealthy accomplice Alonzo Reed - the inferior ''balloon diagram'' predecessor - and what diagrams of sentences by Hemingway, Welty, Proust, Kerouac and other famous writers reveal about them. Florey also answers some of literature''s most pressing questions: Was Mark Twain or James Fenimore Cooper a better grammarian? What are the silliest grammar rules?', 'en', 2006, 154, 'http://books.google.com/books/content?id=LItiAAAAMAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 1, 1, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
