INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6652c717-7ed5-5e0d-b803-f6c559b47a77', '9781933648279', 'Night Has a Thousand Eyes', '3Gk6swEACAAJ', '"Cornell Woolrich''s novels define the essence of noir nihilism."-Marilyn Stasio, The New York Times Book Review One of Woolrich''s most famous novels, this classic noir tale of a con man struggling with his ability to see the future is arguably the author''s best in its depiction of his vision of doomed predestination. From the 1930s until his death in 1968, Cornell Woolrich riveted the reading public with his unparalleled suspense stories. Classic films like Alfred Hitchcock''s Rear Window and novels such as Rendezvous in Black earned Woolrich epithets like "the twentieth century''s Edgar Allan Poe" and "the father of noir."', 'en', 2007, 344, 'http://books.google.com/books/content?id=3Gk6swEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
