INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('0c535489-4214-5edb-8063-2e748bbc854b', '9781933771137', 'Neptune Noir', 'VHu3waVCobIC', 'Edited by the creator and executive producer of the teen detective show, a collection of essays address such varied subjects as Veronica''s vigilante justice and Veronica and Loganâ€™s everchanging relationship.', 'en', 2007, 224, 'http://books.google.com/books/content?id=VHu3waVCobIC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 8, 8, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
