INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1da55ea3-94a8-5891-baa6-dd09526cf85a', '9783856305581', 'C.G. Jung and Hermann Hesse', 'sQt8bd6wFr0C', 'Miguel Serrano, a Chilean diplomat and writer who has travelled widely in India studying Yoga, had a close friendship with Jung and Hermann Hesse at the end of their lives. This book is the outcome of his meetings and correspondence with them. Many letters are reproduced, including a document of great importance written to the author by Jung shortly before his death, explaining his ideas about the nature of the world and of his work.', 'en', 1997, 142, 'http://books.google.com/books/content?id=sQt8bd6wFr0C&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 12, 12, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
