INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('1a0c15ed-3b97-5648-889e-8105372183ab', '9783895086908', 'War and Peace', 'R1Y6SwAACAAJ', 'Often called the greatest novel ever written, War and Peace is at once an epic of the Napoleonic Wars, a philosophical study, and a celebration of the Russian spirit. Tolstoy''s genius is seen clearly in the multitude of characters in this massive chronicle-all of them fully realized and equally memorable. Out of this complex narrative emerges a profound examination of the individual''s place in the historical process, one that makes it clear why Thomas Mann praised Tolstoy for his Homeric powers and placed War and Peace in the same category as the Iliad "To read him . . . is to find one''s way home . . . to everything within us that is fundamental and sane."', 'en', 1999, 1500, 'http://books.google.com/books/content?id=R1Y6SwAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 15, 15, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
