INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('04bdfd73-de51-5524-aa1c-95c2b272042d', '9784766113389', 'How to Draw Manga', 'N3s3GIkquCoC', 'This volume was inspired by young women working in cafes and restaurants clad in those absolutely charming uniforms. Snowy white aprons and crisply starched dresses are staples of manga and anime. This guide features various popular uniforms and costumes. Select an interesting uniform or costume to try on one of your own characters!', 'en', 2003, 132, 'http://books.google.com/books/content?id=N3s3GIkquCoC&printsec=frontcover&img=1&zoom=1&source=gbs_api', 7, 7, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
