INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('6972e38c-c764-5e61-9320-cf42e65e9804', '9784770028969', 'Coin Locker Babies', '87DJwAEACAAJ', 'Rescued from the lockers in which they were left to die as infants and raised to freely follow their ambitions, Kiku and Hashi begin parallel quests of vengeance against the mothers that abandoned them and the society that let it happen.', 'en', 2002, 393, 'http://books.google.com/books/content?id=87DJwAEACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 16, 16, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
