INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('ca575d1d-81a1-5d3c-b804-d2c0dea9e755', '9788122200850', 'Cry, the Peacock', '_QKwVYqp7ugC', 'This book is the story of a young girl obsessed by a childhood prophecy of disaster. The author builds up an atmosphere of tension and oppression, in the middle of an Indian summer.', 'en', 1980, 218, 'http://books.google.com/books/content?id=_QKwVYqp7ugC&printsec=frontcover&img=1&zoom=1&edge=curl&source=gbs_api', 0, 0, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
