INSERT INTO public.book (id, isbn13, title, gg_id, description, language, published_year, page_count, cover_image_url, total_copies, available_copies, status, created_at, updated_at) VALUES ('92b5d52b-4542-5c0b-9e3a-b0cd545c47af', '9788171565641', 'Aspects of the Novel', 'qWU9PgAACAAJ', 'Forster''s lively, informed originality and wit have made this book a classic. Avoiding the chronological approach of what he calls "pseudoscholarship," he freely examines aspects all English-language novels have in common: story, people, plot, fantasy, prophecy, pattern, and rhythm. Index.', 'en', 2004, 141, 'http://books.google.com/books/content?id=qWU9PgAACAAJ&printsec=frontcover&img=1&zoom=1&source=gbs_api', 14, 14, 'ACTIVE', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
