-- Source: books_clean_dedup_out_text.xlsx, sheet books; 6,109 data rows.
-- Generated from the original workbook; source formulas and cached values are retained.
-- Run once on a new database, or rerun safely: existing books are never updated.
SET client_encoding TO 'UTF8';
SET standard_conforming_strings TO on;
BEGIN;
CREATE TABLE IF NOT EXISTS public.book (
    id uuid PRIMARY KEY,
    isbn13 varchar(13) UNIQUE,
    title varchar(500) NOT NULL,
    gg_id varchar(12),
    description text,
    language varchar(10),
    published_year integer,
    page_count integer,
    cover_image_url varchar(1000),
    total_copies integer NOT NULL,
    available_copies integer NOT NULL,
    status varchar(20) NOT NULL CHECK (status IN ('ACTIVE', 'RETIRED')),
    created_at timestamptz NOT NULL,
    updated_at timestamptz NOT NULL
);
CREATE TABLE IF NOT EXISTS public.book_source (
    source_row_id text PRIMARY KEY,
    book_id uuid NOT NULL REFERENCES public.book(id),
    row_status text,
    authors text,
    categories text,
    total_copies_formula text,
    available_copies_formula text,
    cached_total_copies integer,
    cached_available_copies integer
);
COMMIT;
SELECT count(*) AS seeded_book_rows FROM public.book_source;
